# 5. DATASET LOADER
# ------------------------------------------------------------

@st.cache_data(show_spinner=False)
def load_ticket_dataset(
    dataset_path: str,
) -> tuple[pd.DataFrame | None, str | None]:
    """
    Load and normalize the ticket dataset.

    Returns:
        (dataframe, None) when loading succeeds.
        (None, error_message) when loading fails.
    """

    path = Path(dataset_path)

    if not path.is_absolute():
        path = BASE_DIR / path

    if not path.exists():
        return (
            None,
            f"Dataset file not found: {path}",
        )

    try:
        dataframe = pd.read_csv(path)

    except (
        OSError,
        UnicodeError,
        pd.errors.ParserError,
        ValueError,
    ) as exc:
        LOGGER.exception("Dataset loading failed.")

        return (
            None,
            f"Unable to read the dataset: {exc}",
        )

    required_columns = [
        TIMESTAMP_COLUMN,
        *DEMAND_COLUMNS,
    ]

    missing_columns = [
        column
        for column in required_columns
        if column not in dataframe.columns
    ]

    if missing_columns:
        return (
            None,
            "Required columns are missing: "
            + ", ".join(missing_columns),
        )

    dataframe = dataframe.copy()

    dataframe[TIMESTAMP_COLUMN] = pd.to_datetime(
        dataframe[TIMESTAMP_COLUMN],
        errors="coerce",
    )

    for column in DEMAND_COLUMNS:
        dataframe[column] = pd.to_numeric(
            dataframe[column],
            errors="coerce",
        )

    invalid_timestamp_count = int(
        dataframe[TIMESTAMP_COLUMN].isna().sum()
    )

    dataframe = dataframe.dropna(
        subset=[TIMESTAMP_COLUMN]
    )

    dataframe = dataframe.sort_values(
        TIMESTAMP_COLUMN
    ).reset_index(drop=True)

    if dataframe.empty:
        return (
            None,
            "The dataset contains no valid timestamp records.",
        )

    dataframe.attrs["invalid_timestamp_count"] = (
        invalid_timestamp_count
    )

    LOGGER.info(
        "Loaded %s dataset records from %s",
        len(dataframe),
        path,
    )

    return dataframe, None


def load_ticket_dataframe(dataset_path: str) -> pd.DataFrame:
    """Return a DataFrame for page renderers using the tuple-based loader."""
    dataframe, error_message = load_ticket_dataset(dataset_path)

    if error_message:
        st.error(error_message)
        return pd.DataFrame(
            columns=[TIMESTAMP_COLUMN, *DEMAND_COLUMNS]
        )

    if dataframe is None:
        return pd.DataFrame(
            columns=[TIMESTAMP_COLUMN, *DEMAND_COLUMNS]
        )

    return dataframe


# ------------------------------------------------------------
# 6. HISTORICAL DATA SUMMARY
# ------------------------------------------------------------

def build_dataset_summary(
    dataframe: pd.DataFrame,
) -> dict:
    """Build basic historical ticket-demand statistics."""

    summary = {
        "record_count": int(len(dataframe)),
        "column_count": int(len(dataframe.columns)),
        "first_timestamp": dataframe[
            TIMESTAMP_COLUMN
        ].min(),
        "last_timestamp": dataframe[
            TIMESTAMP_COLUMN
        ].max(),
        "missing_cell_count": int(
            dataframe.isna().sum().sum()
        ),
        "duplicate_timestamp_count": int(
            dataframe[TIMESTAMP_COLUMN].duplicated().sum()
        ),
        "invalid_timestamp_count": int(
            dataframe.attrs.get(
                "invalid_timestamp_count",
                0,
            )
        ),
    }

    for column in DEMAND_COLUMNS:
        values = dataframe[column].dropna()

        summary[f"{column}_total"] = (
            safe_number(values.sum())
        )

        summary[f"{column}_mean"] = (
            safe_number(values.mean())
            if not values.empty
            else 0.0
        )

        summary[f"{column}_missing"] = int(
            dataframe[column].isna().sum()
        )

    return summary


