def render_dataset_overview(
    dataframe: pd.DataFrame,
) -> None:
    """Render dataset KPIs and basic data-quality indicators."""

    summary = build_dataset_summary(dataframe)

    st.subheader("Historical Dataset Overview")

    metric_columns = st.columns(4)

    with metric_columns[0]:
        st.metric(
            "Total Records",
            format_number(summary["record_count"]),
        )

    with metric_columns[1]:
        st.metric(
            "Dataset Columns",
            format_number(summary["column_count"]),
        )

    with metric_columns[2]:
        st.metric(
            "Sales Count Total",
            format_number(
                summary["Sales Count_total"]
            ),
        )

    with metric_columns[3]:
        st.metric(
            "Redemption Count Total",
            format_number(
                summary["Redemption Count_total"]
            ),
        )

    date_columns = st.columns(2)

    with date_columns[0]:
        st.metric(
            "First Recorded Date",
            format_date(summary["first_timestamp"]),
        )

    with date_columns[1]:
        st.metric(
            "Last Recorded Date",
            format_date(summary["last_timestamp"]),
        )

    with st.expander(
        "Dataset Quality Details",
        expanded=False,
    ):
        quality_columns = st.columns(3)

        quality_columns[0].metric(
            "Missing Cells",
            format_number(
                summary["missing_cell_count"]
            ),
        )

        quality_columns[1].metric(
            "Duplicate Timestamps",
            format_number(
                summary["duplicate_timestamp_count"]
            ),
        )

        quality_columns[2].metric(
            "Invalid Timestamps Removed",
            format_number(
                summary["invalid_timestamp_count"]
            ),
        )

        st.caption(
            "Duplicate timestamps are reported, not silently "
            "removed. Multiple records at the same timestamp "
            "may require investigation before forecasting."
        )


