def main() -> None:
    """Render the dashboard foundation."""

    dataset_path = render_sidebar()

    render_header()

    with st.spinner(
        "Loading historical ticket data..."
    ):
        dataframe, error_message = load_ticket_dataset(
            dataset_path
        )

    if error_message:
        st.error(error_message)

        st.info(
            "Confirm that the CSV path is correct and that "
            "the file contains Timestamp, Sales Count and "
            "Redemption Count columns."
        )

        st.stop()

    if dataframe is None or dataframe.empty:
        st.warning(
            "No usable historical records are available."
        )

        st.stop()

    render_dataset_overview(dataframe)

    st.success(
        "Historical dataset loaded for dashboard analysis."
    )

    st.subheader("Historical Ticket Records")

    st.dataframe(
        dataframe.head(100),
        use_container_width=True,
        hide_index=True,
    )

    st.caption(
        "Showing the first 100 records. "
        "This table is a preview, not the complete dataset."
    )

    st.info(
        "The dashboard foundation is in place. "
        "Forecasting, evaluation, uncertainty and advanced "
        "insights will be connected in subsequent parts."
    )



