def filter_data_by_date(
    dataframe: pd.DataFrame,
    start_date,
    end_date
) -> pd.DataFrame:
    """Return records within the selected date range."""

    if dataframe.empty:
        return dataframe.copy()

    start_timestamp = pd.Timestamp(start_date)
    end_timestamp = (
        pd.Timestamp(end_date)
        + pd.Timedelta(days=1)
        - pd.Timedelta(nanoseconds=1)
    )

    mask = (
        dataframe[TIMESTAMP_COLUMN].ge(start_timestamp)
        & dataframe[TIMESTAMP_COLUMN].le(end_timestamp)
    )

    return dataframe.loc[mask].copy()


def aggregate_demand(
    dataframe: pd.DataFrame,
    frequency: str
) -> pd.DataFrame:
    """Aggregate ticket sales and redemptions by time frequency."""

    if dataframe.empty:
        return pd.DataFrame(
            columns=["Timestamp", "Sales Count", "Redemption Count"]
        )

    frequency_map = {
        "Daily": "D",
        "Weekly": "W",
        "Monthly": "MS",
    }

    if frequency not in frequency_map:
        raise ValueError(
            f"Unsupported aggregation frequency: {frequency}"
        )

    result = (
        dataframe.set_index(TIMESTAMP_COLUMN)[DEMAND_COLUMNS]
        .resample(frequency_map[frequency])
        .sum(min_count=1)
        .reset_index()
    )

    return result


def render_demand_filters(
    dataframe: pd.DataFrame
) -> pd.DataFrame:
    """Render date and time-frequency filters."""

    st.subheader("Historical Demand Explorer")

    if dataframe.empty:
        st.info("Date filters ke liye dataset mein valid records nahi hain.")
        return dataframe.copy()

    minimum_date = dataframe[TIMESTAMP_COLUMN].min().date()
    maximum_date = dataframe[TIMESTAMP_COLUMN].max().date()

    col1, col2, col3 = st.columns([1, 1, 1])

    with col1:
        start_date = st.date_input(
            "Start date",
            value=minimum_date,
            min_value=minimum_date,
            max_value=maximum_date,
            key="history_start_date",
        )

    with col2:
        end_date = st.date_input(
            "End date",
            value=maximum_date,
            min_value=minimum_date,
            max_value=maximum_date,
            key="history_end_date",
        )

    with col3:
        frequency = st.selectbox(
            "Trend frequency",
            options=["Daily", "Weekly", "Monthly"],
            index=2,
            key="history_frequency",
        )

    if start_date > end_date:
        st.warning("Start date, end date se pehle honi chahiye.")
        return dataframe.iloc[0:0].copy()

    filtered_data = filter_data_by_date(
        dataframe,
        start_date,
        end_date,
    )


    return filtered_data


def render_demand_metrics(dataframe: pd.DataFrame) -> None:
    """Display ticket demand metrics for the selected period."""

    st.subheader("Selected Period Summary")

    if dataframe.empty:
        st.info("Selected date range mein koi record available nahi hai.")
        return

    total_sales = dataframe["Sales Count"].sum()
    total_redemptions = dataframe["Redemption Count"].sum()

    average_sales = dataframe["Sales Count"].mean()
    average_redemptions = dataframe["Redemption Count"].mean()

    col1, col2, col3, col4 = st.columns(4)

    with col1:
        st.metric(
            "Total Sales",
            format_number(total_sales),
        )

    with col2:
        st.metric(
            "Total Redemptions",
            format_number(total_redemptions),
        )

    with col3:
        st.metric(
            "Average Sales / Record",
            format_number(average_sales),
        )

    with col4:
        st.metric(
            "Average Redemptions / Record",
            format_number(average_redemptions),
        )


def render_historical_charts(
    dataframe: pd.DataFrame,
    frequency: str,
) -> None:
    """Render historical demand charts."""

    st.subheader("Demand Trends")

    if dataframe.empty:
        st.info("Charts display karne ke liye data available nahi hai.")
        return

    trend_data = aggregate_demand(dataframe, frequency)

    if trend_data.empty:
        st.info("Selected period ke liye trend data available nahi hai.")
        return

    trend_data = trend_data.set_index(TIMESTAMP_COLUMN)

    col1, col2 = st.columns(2)

    with col1:
        st.markdown("**Ticket Sales Trend**")
        st.line_chart(
            trend_data[["Sales Count"]],
            use_container_width=True,
        )

    with col2:
        st.markdown("**Ticket Redemption Trend**")
        st.line_chart(
            trend_data[["Redemption Count"]],
            use_container_width=True,
        )

    st.markdown("**Sales vs. Redemptions**")
    st.line_chart(
        trend_data[DEMAND_COLUMNS],
        use_container_width=True,
    )

    with st.expander("View aggregated trend data"):
        st.dataframe(
            trend_data.reset_index(),
            use_container_width=True,
            hide_index=True,
        )


def render_historical_data_table(
    dataframe: pd.DataFrame
) -> None:
    """Display and download filtered historical records."""

    st.subheader("Historical Records")

    if dataframe.empty:
        st.info("Display karne ke liye koi historical record nahi hai.")
        return

    display_columns = [
        TIMESTAMP_COLUMN,
        "Sales Count",
        "Redemption Count",
    ]

    display_data = dataframe[display_columns].copy()

    with st.expander("Open historical data table"):
        st.caption(
            f"Filtered records: {len(display_data):,}"
        )

        st.dataframe(
            display_data,
            use_container_width=True,
            hide_index=True,
        )

        csv_data = display_data.to_csv(index=False).encode("utf-8")

        st.download_button(
            label="Download filtered historical data (CSV)",
            data=csv_data,
            file_name="ferry_historical_demand.csv",
            mime="text/csv",
            key="download_historical_demand",
        )


def render_historical_analysis(
    dataframe: pd.DataFrame
) -> None:
    """Connect the filters, metrics, charts, and data table."""

    filtered_data = render_demand_filters(dataframe)

    frequency = st.session_state.get(
        "history_frequency",
        "Monthly",
    )

    render_demand_metrics(filtered_data)

    render_historical_charts(
        filtered_data,
        frequency,
    )

    render_historical_data_table(filtered_data)


