def render_forecast_artifact_status(
    artifact_results: dict,
) -> None:
    """Show which forecast artifacts are currently available."""

    st.subheader("Forecast Output Availability")

    rows = []

    for category, artifact in artifact_results.items():
        path = artifact.get("path")

        rows.append(
            {
                "Artifact": category.replace("_", " ").title(),
                "Status": (
                    "Available"
                    if artifact.get("available")
                    else "Unavailable"
                ),
                "File": (
                    Path(path).name
                    if path is not None
                    else "Not found"
                ),
                "Details": artifact.get("message") or "Ready",
            }
        )

    status_dataframe = pd.DataFrame(rows)

    st.dataframe(
        status_dataframe,
        use_container_width=True,
        hide_index=True,
    )


