def render_forecast_summary_metrics(
    forecast_dataframe: pd.DataFrame,
) -> None:
    """Render forecast summary metrics when a forecast is available."""

    st.subheader("Forecast Summary")

    if forecast_dataframe is None or forecast_dataframe.empty:
        st.info(
            "Forecast output abhi available nahi hai. "
            "Forecasting pipeline ke outputs generate hone ke baad "
            "ye section results display karega."
        )
        return

    summary = get_forecast_numeric_summary(forecast_dataframe)

    col1, col2, col3, col4 = st.columns(4)

