def render_forecast_chart(
    forecast_dataframe: pd.DataFrame,
) -> None:
    """Display forecast predictions against time when possible."""

    st.subheader("Forecast Visualization")

    if forecast_dataframe is None or forecast_dataframe.empty:
        st.info("Forecast chart ke liye data available nahi hai.")
        return

    columns = identify_forecast_columns(forecast_dataframe)

    timestamp_column = columns["timestamp"]
    prediction_column = columns["predicted"]

    if timestamp_column is None or prediction_column is None:
        st.warning(
            "Chart ke liye timestamp aur prediction columns "
            "dono chahiye. Available columns neeche diye gaye hain."
        )
        st.write(list(forecast_dataframe.columns))
        return

    chart_data = forecast_dataframe[
        [timestamp_column, prediction_column]
    ].copy()

    chart_data[timestamp_column] = pd.to_datetime(
        chart_data[timestamp_column],
        errors="coerce",
    )

    chart_data[prediction_column] = pd.to_numeric(
        chart_data[prediction_column],
        errors="coerce",
    )

    chart_data = chart_data.dropna(
        subset=[timestamp_column, prediction_column]
    )

    if chart_data.empty:
        st.warning("Valid forecast points available nahi hain.")
        return

    chart_data = (
        chart_data
        .sort_values(timestamp_column)
        .set_index(timestamp_column)
    )

    st.line_chart(
        chart_data[[prediction_column]],
        use_container_width=True,
    )


