def render_forecast_uncertainty(
    uncertainty_dataframe: pd.DataFrame,
) -> None:
    """Display available prediction interval information."""

    st.subheader("Forecast Uncertainty")

    if uncertainty_dataframe is None or uncertainty_dataframe.empty:
        st.info(
            "Uncertainty output available nahi hai. "
            "Prediction interval analysis run hone ke baad "
            "is section mein results display kiye ja sakte hain."
        )
        return

    columns = identify_forecast_columns(uncertainty_dataframe)

    lower_column = columns["lower"]
    upper_column = columns["upper"]
    timestamp_column = columns["timestamp"]

    st.dataframe(
        uncertainty_dataframe,
        use_container_width=True,
        hide_index=True,
    )

    if (
        timestamp_column is None
        or lower_column is None
        or upper_column is None
    ):
        st.caption(
            "Is file mein standard timestamp, lower-bound aur "
            "upper-bound columns identify nahi ho paye."
        )
        return

    chart_data = uncertainty_dataframe[
        [timestamp_column, lower_column, upper_column]
    ].copy()

    chart_data[timestamp_column] = pd.to_datetime(
        chart_data[timestamp_column],
        errors="coerce",
    )

    for column_name in [lower_column, upper_column]:
        chart_data[column_name] = pd.to_numeric(
            chart_data[column_name],
            errors="coerce",
        )

    chart_data = chart_data.dropna()

    if not chart_data.empty:
        chart_data = (
            chart_data
            .sort_values(timestamp_column)
            .set_index(timestamp_column)
        )

        st.line_chart(
            chart_data[[lower_column, upper_column]],
            use_container_width=True,
        )


