def render_forecast_download(
    dataframe: pd.DataFrame,
    download_label: str,
    file_name: str,
    widget_key: str,
) -> None:
    """Offer a CSV download for an available dataframe."""

    if dataframe is None or dataframe.empty:
        st.caption(f"{download_label}: no data available.")
        return

    csv_content = dataframe.to_csv(index=False).encode("utf-8")

    st.download_button(
        label=download_label,
        data=csv_content,
        file_name=file_name,
        mime="text/csv",
        key=widget_key,
    )


def render_forecast_download_center(
    artifact_results: dict,
) -> None:
    """Show download controls for available forecast artifacts."""

    st.subheader("Forecast Export Center")

    for category, artifact in artifact_results.items():
        dataframe = artifact.get("data")

        if artifact.get("available") and dataframe is not None:
            safe_file_name = f"ferry_{category}.csv"

            render_forecast_download(
                dataframe=dataframe,
                download_label=(
                    f"Download {category.replace('_', ' ').title()}"
                ),
                file_name=safe_file_name,
                widget_key=f"forecast_download_{category}",
            )


