def render_forecasting_dashboard() -> None:
    """Render all available forecasting outputs in one page."""

    st.header("Forecasting Intelligence Center")

    st.caption(
        "Forecasts are based on historical ticket sales and "
        "redemption records. They should not be interpreted as "
        "verified passenger boarding or vessel occupancy counts."
    )

    artifact_results = collect_forecast_artifacts()

    render_forecast_artifact_status(artifact_results)

    forecast_dataframe = artifact_results.get(
        "forecast",
        {},
    ).get("data")

    comparison_dataframe = artifact_results.get(
        "model_comparison",
        {},
    ).get("data")

    uncertainty_dataframe = artifact_results.get(
        "uncertainty",
        {},
    ).get("data")

    model_predictions_dataframe = artifact_results.get(
        "model_predictions",
        {},
    ).get("data")

    if forecast_dataframe is None or forecast_dataframe.empty:
        if (
            model_predictions_dataframe is not None
            and not model_predictions_dataframe.empty
        ):
            forecast_dataframe = model_predictions_dataframe

    render_forecast_summary_metrics(forecast_dataframe)

    render_forecast_chart(
        prepare_forecast_dataframe(forecast_dataframe)
        if forecast_dataframe is not None
        else None
    )

    render_model_comparison(comparison_dataframe)

    render_forecast_uncertainty(uncertainty_dataframe)

    render_forecast_download_center(artifact_results)

    with st.expander("Forecasting methodology and limitations"):
        st.markdown(
            """
            **Forecasting methodology**

            - Historical ticket sales and redemptions are the source
              measures.
            - Forecast outputs depend on the existing forecasting
              pipeline and its selected model.
            - Model metrics should be interpreted using the exact
              evaluation method used by that pipeline.
            - Prediction intervals represent estimated uncertainty
              only when the uncertainty pipeline has generated them.

            **Important limitations**

            - Ticket sales do not necessarily equal same-day travel.
            - Redemptions are not automatically equivalent to verified
              vessel boarding counts.
            - These outputs do not establish actual vessel capacity.
            - Forecast accuracy must be assessed using historical
              out-of-sample evaluation.
            """
        )


