def render_data_explorer(dataframe: pd.DataFrame) -> None:
    """Provide searchable columns and downloadable dataset records."""

    st.header("Historical Data Explorer")

    if dataframe is None or dataframe.empty:
        st.warning("Explore karne ke liye koi data available nahi hai.")
        return

    st.write(
        "Is section se aap historical ticket records ko inspect "
        "aur CSV format mein download kar sakte hain."
    )

    available_columns = dataframe.columns.tolist()

    selected_columns = st.multiselect(
        "Select columns",
        options=available_columns,
        default=available_columns,
        key="data_explorer_columns",
    )

    if not selected_columns:
        st.warning("Kam se kam ek column select karein.")
        return

    selected_data = dataframe[selected_columns].copy()

    search_text = st.text_input(
        "Optional text filter",
        placeholder="Enter a value to search in displayed records",
        key="data_explorer_search",
    )

    if search_text.strip():
        searchable_columns = selected_data.select_dtypes(
            include=["object", "string"]
        ).columns.tolist()

        if searchable_columns:
            mask = pd.Series(
                False,
                index=selected_data.index,
            )

            for column_name in searchable_columns:
                mask |= (
                    selected_data[column_name]
                    .astype("string")
                    .str.contains(
                        search_text.strip(),
                        case=False,
                        na=False,
                        regex=False,
                    )
                )

            selected_data = selected_data.loc[mask]

        else:
            st.caption(
                "Selected columns mein text columns nahi hain; "
                "text search apply nahi hui."
            )

    st.caption(
        f"Matching records: {len(selected_data):,}"
    )

    preview_limit = st.selectbox(
        "Preview rows",
        options=[100, 500, 1000, 5000],
        index=1,
        key="data_explorer_preview_limit",
    )

    st.dataframe(
        selected_data.head(preview_limit),
        use_container_width=True,
        hide_index=True,
    )

    render_forecast_download(
        dataframe=selected_data,
        download_label="Download selected data as CSV",
        file_name="ferry_selected_data.csv",
        widget_key="download_selected_data",
    )


