# ------------------------------------------------------------
# SECTION 5.1 â€” INSIGHT CONFIGURATION
# ------------------------------------------------------------

INSIGHT_MINIMUM_ROWS = 2

INSIGHT_TOP_PERIODS = 10

INSIGHT_ROLLING_WINDOW = 7

INSIGHT_IQR_MULTIPLIER = 1.5

INSIGHT_NUMERIC_COLUMNS = [
    "Sales Count",
    "Redemption Count",
]


# ------------------------------------------------------------
# SECTION 5.2 â€” DATA PREPARATION
# ------------------------------------------------------------

def prepare_insight_data(
    dataframe: pd.DataFrame,
) -> pd.DataFrame:
    """
    Prepare a copy of the source dataframe for demand analysis.

    Original source data is not modified.
    """

    if dataframe is None or dataframe.empty:
        return pd.DataFrame(
            columns=[
                TIMESTAMP_COLUMN,
                "Sales Count",
                "Redemption Count",
            ]
        )

    required_columns = [
        TIMESTAMP_COLUMN,
        "Sales Count",
        "Redemption Count",
    ]

    missing_columns = [
        column
        for column in required_columns
        if column not in dataframe.columns
    ]

    if missing_columns:
        raise ValueError(
            "Missing required insight columns: "
            + ", ".join(missing_columns)
        )

    result = dataframe[required_columns].copy()

    result[TIMESTAMP_COLUMN] = pd.to_datetime(
        result[TIMESTAMP_COLUMN],
        errors="coerce",
    )

    for column in INSIGHT_NUMERIC_COLUMNS:
        result[column] = pd.to_numeric(
            result[column],
            errors="coerce",
        )

    result = result.dropna(
        subset=[TIMESTAMP_COLUMN]
    )

    result = result.sort_values(
        TIMESTAMP_COLUMN
    ).reset_index(drop=True)

    return result


# ------------------------------------------------------------
# SECTION 5.3 â€” DESCRIPTIVE STATISTICS
# ------------------------------------------------------------

def calculate_demand_statistics(
    dataframe: pd.DataFrame,
) -> pd.DataFrame:
    """Calculate descriptive statistics for available demand columns."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    available_columns = [
        column
        for column in INSIGHT_NUMERIC_COLUMNS
        if column in dataframe.columns
    ]

    if not available_columns:
        return pd.DataFrame()

    records = []

    for column in available_columns:
        values = pd.to_numeric(
            dataframe[column],
            errors="coerce",
        ).dropna()

        if values.empty:
            continue

        records.append(
            {
                "Measure": column,
                "Records": int(values.count()),
                "Total": float(values.sum()),
                "Mean": float(values.mean()),
                "Median": float(values.median()),
                "Standard Deviation": float(
                    values.std()
                ) if len(values) > 1 else 0.0,
                "Minimum": float(values.min()),
                "Maximum": float(values.max()),
                "25th Percentile": float(
                    values.quantile(0.25)
                ),
                "75th Percentile": float(
                    values.quantile(0.75)
                ),
            }
        )

    return pd.DataFrame(records)


# ------------------------------------------------------------
# SECTION 5.4 â€” SALES AND REDEMPTION COMPARISON
# ------------------------------------------------------------

def calculate_sales_redemption_comparison(
    dataframe: pd.DataFrame,
) -> dict:
    """
    Compare aggregate sales and redemptions.

    This comparison does not imply that sales and redemptions
    correspond to the same ticket cohort or travel date.
    """

    if dataframe is None or dataframe.empty:
        return {
            "total_sales": 0.0,
            "total_redemptions": 0.0,
            "difference": 0.0,
            "redemptions_to_sales_percent": None,
            "interpretation": "No data available.",
        }

    sales = pd.to_numeric(
        dataframe["Sales Count"],
        errors="coerce",
    )

    redemptions = pd.to_numeric(
        dataframe["Redemption Count"],
        errors="coerce",
    )

    total_sales = float(sales.sum())
    total_redemptions = float(redemptions.sum())

    difference = total_sales - total_redemptions

    if total_sales > 0:
        ratio = (
            total_redemptions / total_sales
        ) * 100.0
    else:
        ratio = None

    if ratio is None:
        interpretation = (
            "Sales total is zero; a percentage comparison "
            "cannot be calculated."
        )
    else:
        interpretation = (
            "Aggregate comparison only. This percentage is "
            "not a same-ticket redemption rate unless the "
            "underlying records establish matching cohorts."
        )

    return {
        "total_sales": total_sales,
        "total_redemptions": total_redemptions,
        "difference": difference,
        "redemptions_to_sales_percent": ratio,
        "interpretation": interpretation,
    }


# ------------------------------------------------------------
# SECTION 5.5 â€” TEMPORAL FEATURE CREATION
# ------------------------------------------------------------

def add_temporal_insight_features(
    dataframe: pd.DataFrame,
) -> pd.DataFrame:
    """Add calendar features derived from each timestamp."""

    result = prepare_insight_data(dataframe)

    if result.empty:
        return result

    timestamp_series = result[TIMESTAMP_COLUMN]

    result["Calendar_Date"] = timestamp_series.dt.date

    result["Year"] = timestamp_series.dt.year

    result["Month_Number"] = timestamp_series.dt.month

    result["Month_Name"] = timestamp_series.dt.month_name()

    result["Day_Of_Month"] = timestamp_series.dt.day

    result["Day_Of_Week_Number"] = (
        timestamp_series.dt.dayofweek
    )

    result["Day_Of_Week"] = (
        timestamp_series.dt.day_name()
    )

    result["Hour"] = timestamp_series.dt.hour

    result["Quarter"] = timestamp_series.dt.quarter

    result["Is_Weekend"] = (
        timestamp_series.dt.dayofweek >= 5
    )

    return result


# ------------------------------------------------------------
# SECTION 5.6 â€” DEMAND BY WEEKDAY
# ------------------------------------------------------------

def calculate_weekday_demand(
    dataframe: pd.DataFrame,
) -> pd.DataFrame:
    """Aggregate ticket activity by weekday."""

    enriched = add_temporal_insight_features(
        dataframe
    )

    if enriched.empty:
        return pd.DataFrame()

    weekday_order = [
        "Monday",
        "Tuesday",
        "Wednesday",
        "Thursday",
        "Friday",
        "Saturday",
        "Sunday",
    ]

    result = (
        enriched.groupby(
            [
                "Day_Of_Week_Number",
                "Day_Of_Week",
            ],
            as_index=False,
        )
        .agg(
            Sales_Total=("Sales Count", "sum"),
            Redemption_Total=(
                "Redemption Count",
                "sum",
            ),
            Record_Count=(
                TIMESTAMP_COLUMN,
                "count",
            ),
            Average_Sales=(
                "Sales Count",
                "mean",
            ),
            Average_Redemptions=(
                "Redemption Count",
                "mean",
            ),
        )
    )

    result = result.sort_values(
        "Day_Of_Week_Number"
    )

    result["Day_Of_Week"] = pd.Categorical(
        result["Day_Of_Week"],
        categories=weekday_order,
        ordered=True,
    )

    return result.reset_index(drop=True)


# ------------------------------------------------------------
# SECTION 5.7 â€” DEMAND BY MONTH
# ------------------------------------------------------------

def calculate_monthly_demand(
    dataframe: pd.DataFrame,
) -> pd.DataFrame:
    """Aggregate demand by calendar month."""

    prepared = prepare_insight_data(
        dataframe
    )

    if prepared.empty:
        return pd.DataFrame()

    result = (
        prepared.set_index(TIMESTAMP_COLUMN)
        .resample("MS")
        .agg(
            {
                "Sales Count": "sum",
                "Redemption Count": "sum",
            }
        )
        .reset_index()
    )

    result["Year"] = (
        result[TIMESTAMP_COLUMN].dt.year
    )

    result["Month"] = (
        result[TIMESTAMP_COLUMN].dt.month_name()
    )

    result["Period"] = (
        result[TIMESTAMP_COLUMN].dt.strftime(
            "%Y-%m"
        )
    )

    return result


# ------------------------------------------------------------
# SECTION 5.8 â€” DEMAND BY HOUR
# ------------------------------------------------------------

def calculate_hourly_demand(
    dataframe: pd.DataFrame,
) -> pd.DataFrame:
    """
    Aggregate ticket activity by timestamp hour.

    Results reflect the timestamps in the source data.
    """

    enriched = add_temporal_insight_features(
        dataframe
    )

    if enriched.empty:
        return pd.DataFrame()

    result = (
        enriched.groupby(
            "Hour",
            as_index=False,
        )
        .agg(
            Sales_Total=("Sales Count", "sum"),
            Redemption_Total=(
                "Redemption Count",
                "sum",
            ),
            Record_Count=(
                TIMESTAMP_COLUMN,
                "count",
            ),
            Average_Sales=(
                "Sales Count",
                "mean",
            ),
            Average_Redemptions=(
                "Redemption Count",
                "mean",
            ),
        )
    )

    return result.sort_values(
        "Hour"
    ).reset_index(drop=True)


# ------------------------------------------------------------
# SECTION 5.9 â€” PEAK PERIOD IDENTIFICATION
# ------------------------------------------------------------

def identify_peak_periods(
    dataframe: pd.DataFrame,
    measure: str = "Sales Count",
    frequency: str = "Daily",
    top_n: int = INSIGHT_TOP_PERIODS,
) -> pd.DataFrame:
    """Identify periods with the largest aggregate values."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    if measure not in INSIGHT_NUMERIC_COLUMNS:
        raise ValueError(
            f"Unsupported demand measure: {measure}"
        )

    frequency_map = {
        "Daily": "D",
        "Weekly": "W",
        "Monthly": "MS",
    }

    if frequency not in frequency_map:
        raise ValueError(
            f"Unsupported frequency: {frequency}"
        )

    prepared = prepare_insight_data(
        dataframe
    )

    if prepared.empty:
        return pd.DataFrame()

    result = (
        prepared.set_index(TIMESTAMP_COLUMN)[measure]
        .resample(frequency_map[frequency])
        .sum(min_count=1)
        .reset_index()
    )

    result = result.rename(
        columns={
            TIMESTAMP_COLUMN: "Period_Start",
            measure: "Demand_Value",
        }
    )

    result = result.dropna(
        subset=["Demand_Value"]
    )

    result = result.sort_values(
        "Demand_Value",
        ascending=False,
    )

    return result.head(
        max(1, int(top_n))
    ).reset_index(drop=True)


# ------------------------------------------------------------
# SECTION 5.10 â€” INTERQUARTILE-RANGE ANOMALIES
# ------------------------------------------------------------

def detect_iqr_outliers(
    dataframe: pd.DataFrame,
    measure: str,
    multiplier: float = INSIGHT_IQR_MULTIPLIER,
) -> pd.DataFrame:
    """
    Flag statistically unusual values using IQR fences.

    These flags are statistical outliers, not confirmed
    operational incidents or ticketing errors.
    """

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    if measure not in dataframe.columns:
        raise ValueError(
            f"Column not found: {measure}"
        )

    if multiplier <= 0:
        raise ValueError(
            "IQR multiplier must be greater than zero."
        )

    result = prepare_insight_data(
        dataframe
    )

    values = pd.to_numeric(
        result[measure],
        errors="coerce",
    )

    valid_values = values.dropna()

    if len(valid_values) < INSIGHT_MINIMUM_ROWS:
        return pd.DataFrame()

    q1 = float(
        valid_values.quantile(0.25)
    )

    q3 = float(
        valid_values.quantile(0.75)
    )

    iqr = q3 - q1

    lower_bound = q1 - multiplier * iqr

    upper_bound = q3 + multiplier * iqr

    result["IQR_Lower_Bound"] = lower_bound

    result["IQR_Upper_Bound"] = upper_bound

    result["Is_Statistical_Outlier"] = (
        values.lt(lower_bound)
        | values.gt(upper_bound)
    )

    result["Outlier_Measure"] = measure

    result["Outlier_Interpretation"] = (
        "Statistical flag only; investigate context "
        "before making operational decisions."
    )

    return result.loc[
        result["Is_Statistical_Outlier"]
    ].reset_index(drop=True)


# ------------------------------------------------------------
# SECTION 5.11 â€” ROLLING DEMAND STATISTICS
# ------------------------------------------------------------

def calculate_rolling_demand(
    dataframe: pd.DataFrame,
    window: int = INSIGHT_ROLLING_WINDOW,
) -> pd.DataFrame:
    """
    Calculate rolling means and standard deviations.

    The window represents observations, not necessarily days.
    """

    if window < 2:
        raise ValueError(
            "Rolling window must be at least 2 observations."
        )

    prepared = prepare_insight_data(
        dataframe
    )

    if prepared.empty:
        return prepared

    result = prepared.copy()

    for measure in INSIGHT_NUMERIC_COLUMNS:
        result[f"{measure}_Rolling_Mean"] = (
            result[measure]
            .rolling(
                window=window,
                min_periods=window,
            )
            .mean()
        )

        result[f"{measure}_Rolling_Std"] = (
            result[measure]
            .rolling(
                window=window,
                min_periods=window,
            )
            .std()
        )

    result["Rolling_Window_Observations"] = window

    return result


# ------------------------------------------------------------
# SECTION 5.12 â€” DEMAND VARIABILITY
# ------------------------------------------------------------

def calculate_demand_variability(
    dataframe: pd.DataFrame,
) -> pd.DataFrame:
    """Summarize variability for sales and redemptions."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    records = []

    for measure in INSIGHT_NUMERIC_COLUMNS:
        values = pd.to_numeric(
            dataframe[measure],
            errors="coerce",
        ).dropna()

        if values.empty:
            continue

        mean_value = float(
            values.mean()
        )

        std_value = float(
            values.std()
        ) if len(values) > 1 else 0.0

        if mean_value != 0:
            coefficient_variation = (
                std_value / abs(mean_value)
            ) * 100
        else:
            coefficient_variation = None

        records.append(
            {
                "Measure": measure,
                "Mean": mean_value,
                "Standard_Deviation": std_value,
                "Minimum": float(values.min()),
                "Maximum": float(values.max()),
                "Coefficient_of_Variation_Percent": (
                    coefficient_variation
                ),
                "Valid_Observations": int(
                    values.count()
                ),
            }
        )

    return pd.DataFrame(records)


# ------------------------------------------------------------
# SECTION 5.13 â€” ZERO AND MISSING VALUE REVIEW
# ------------------------------------------------------------

def calculate_demand_quality_summary(
    dataframe: pd.DataFrame,
) -> pd.DataFrame:
    """Summarize missing, zero and negative demand values."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    records = []

    for measure in INSIGHT_NUMERIC_COLUMNS:
        values = pd.to_numeric(
            dataframe[measure],
            errors="coerce",
        )

        records.append(
            {
                "Measure": measure,
                "Total_Rows": int(len(values)),
                "Missing_Values": int(
                    values.isna().sum()
                ),
                "Zero_Values": int(
                    values.eq(0).sum()
                ),
                "Negative_Values": int(
                    values.lt(0).sum()
                ),
                "Positive_Values": int(
                    values.gt(0).sum()
                ),
            }
        )

    return pd.DataFrame(records)


# ------------------------------------------------------------
# SECTION 5.14 â€” MONTH-OVER-MONTH CHANGE
# ------------------------------------------------------------

def calculate_monthly_change(
    dataframe: pd.DataFrame,
) -> pd.DataFrame:
    """Calculate absolute and percentage monthly changes."""

    monthly = calculate_monthly_demand(
        dataframe
    )

    if monthly.empty:
        return monthly

    for measure in INSIGHT_NUMERIC_COLUMNS:
        monthly[f"{measure}_Previous_Month"] = (
            monthly[measure].shift(1)
        )

        monthly[f"{measure}_Change"] = (
            monthly[measure]
            - monthly[f"{measure}_Previous_Month"]
        )

        previous = monthly[
            f"{measure}_Previous_Month"
        ]

        monthly[f"{measure}_Change_Percent"] = (
            monthly[f"{measure}_Change"]
            .div(previous.where(previous.ne(0)))
            .mul(100)
        )

    return monthly


# ------------------------------------------------------------
# SECTION 5.15 â€” EVIDENCE-BASED INSIGHT TEXT
# ------------------------------------------------------------

def generate_demand_insight_messages(
    dataframe: pd.DataFrame,
) -> list:
    """
    Generate simple descriptive messages from observed data.

    Messages do not establish causes or future outcomes.
    """

    messages = []

    if dataframe is None or dataframe.empty:
        return [
            "No historical records are available for analysis."
        ]

    prepared = prepare_insight_data(
        dataframe
    )

    for measure in INSIGHT_NUMERIC_COLUMNS:
        values = pd.to_numeric(
            prepared[measure],
            errors="coerce",
        ).dropna()

        if values.empty:
            messages.append(
                f"No valid observations found for {measure}."
            )
            continue

        messages.append(
            f"{measure}: total "
            f"{values.sum():,.0f}, average "
            f"{values.mean():,.2f}, and maximum "
            f"{values.max():,.0f} across the selected records."
        )

    weekday_data = calculate_weekday_demand(
        prepared
    )

    if not weekday_data.empty:
        average_column = "Average_Sales"

        if average_column in weekday_data.columns:
            valid_weekdays = weekday_data.dropna(
                subset=[average_column]
            )

            if not valid_weekdays.empty:
                peak_row = valid_weekdays.loc[
                    valid_weekdays[average_column].idxmax()
                ]

                messages.append(
                    "The highest average sales per recorded "
                    "observation occur on "
                    f"{peak_row['Day_Of_Week']}."
                )

    messages.append(
        "These observations describe the selected historical data. "
        "They do not establish why demand changed or guarantee "
        "future demand."
    )

    return messages


