    st.dataframe(
        peak_data,
        use_container_width=True,
        hide_index=True,
    )

    chart_data = peak_data.copy()

    chart_data["Period_Start"] = (
        pd.to_datetime(
            chart_data["Period_Start"],
            errors="coerce",
        )
        .dt.strftime("%Y-%m-%d")
    )

    chart_data = chart_data.dropna(
        subset=["Period_Start"]
    )

    if not chart_data.empty:
        st.bar_chart(
            chart_data.set_index("Period_Start")[
                ["Demand_Value"]
            ],
            use_container_width=True,
        )


