def render_statistical_outliers(
    dataframe: pd.DataFrame,
) -> None:
    """Show observations outside the IQR statistical fences."""

    st.subheader("Statistical Outlier Review")

    st.caption(
        "Outliers are unusual numerical observations. They are "
        "not automatically errors, incidents or confirmed events."
    )

    measure = st.selectbox(
        "Measure for outlier review",
        options=INSIGHT_NUMERIC_COLUMNS,
        key="insight_outlier_measure",
    )

    multiplier = st.slider(
        "IQR multiplier",
        min_value=1.0,
        max_value=3.0,
        value=1.5,
        step=0.25,
        key="insight_outlier_multiplier",
    )

    outlier_data = detect_iqr_outliers(
        dataframe,
        measure,
        multiplier,
    )

    if outlier_data.empty:
        st.success(
            "Selected measure ke liye IQR rule se "
            "koi outlier identify nahi hua."
        )
        return

    st.metric(
        "Statistical Outlier Records",
        format_number(len(outlier_data)),
    )

    display_columns = [
        TIMESTAMP_COLUMN,
        measure,
        "IQR_Lower_Bound",
        "IQR_Upper_Bound",
        "Is_Statistical_Outlier",
        "Outlier_Interpretation",
    ]

    st.dataframe(
        outlier_data[display_columns],
        use_container_width=True,
        hide_index=True,
    )

    render_forecast_download(
        dataframe=outlier_data,
        download_label="Download statistical outliers",
        file_name="ferry_statistical_outliers.csv",
        widget_key="download_statistical_outliers",
    )


