# ------------------------------------------------
# 6.1 REPORTING CONFIGURATION
# ------------------------------------------------

REPORTING_VERSION = "1.0.0"

REPORTING_REQUIRED_COLUMNS = [
    "Timestamp",
    "Sales Count",
    "Redemption Count",
]

REPORTING_DATE_FREQUENCIES = {
    "Daily": "D",
    "Weekly": "W-SUN",
    "Monthly": "MS",
}

REPORTING_EXPORT_COLUMNS = [
    "Timestamp",
    "Sales Count",
    "Redemption Count",
]


# ------------------------------------------------
# 6.2 SAFE DATA PREPARATION
# ------------------------------------------------

def prepare_reporting_data(dataframe):
    """
    Prepare ticket records for reporting.

    This function:
    - Checks required columns.
    - Creates a separate copy.
    - Converts timestamps.
    - Converts sales and redemption values.
    - Removes records with invalid timestamps.
    - Sorts records chronologically.

    The original dataframe is not intentionally modified.
    """

    if dataframe is None:
        raise ValueError(
            "Reporting cannot start because the dataset is missing."
        )

    if not isinstance(dataframe, pd.DataFrame):
        raise TypeError(
            "Reporting input must be a pandas DataFrame."
        )

    if dataframe.empty:
        raise ValueError(
            "Reporting cannot start because the dataset is empty."
        )

    missing_columns = [
        column
        for column in REPORTING_REQUIRED_COLUMNS
        if column not in dataframe.columns
    ]

    if missing_columns:
        raise ValueError(
            "Required reporting columns are missing: "
            + ", ".join(missing_columns)
        )

    report_data = dataframe[
        REPORTING_REQUIRED_COLUMNS
    ].copy()

    report_data["Timestamp"] = pd.to_datetime(
        report_data["Timestamp"],
        errors="coerce",
    )

    for column in [
        "Sales Count",
        "Redemption Count",
    ]:
        report_data[column] = pd.to_numeric(
            report_data[column],
            errors="coerce",
        )

    report_data = report_data.dropna(
        subset=["Timestamp"]
    )

    report_data = report_data.sort_values(
        "Timestamp"
    )

    report_data = report_data.reset_index(
        drop=True
    )

    return report_data


# ------------------------------------------------
# 6.3 DATE FILTERING
# ------------------------------------------------

def filter_reporting_period(
    dataframe,
    start_date=None,
    end_date=None,
):
    """
    Return records within the selected reporting period.

    Start and end dates are inclusive at the calendar-day level.
    """

    report_data = prepare_reporting_data(
        dataframe
    )

    if start_date is not None:
        start_timestamp = pd.Timestamp(
            start_date
        ).normalize()

        report_data = report_data[
            report_data["Timestamp"]
            >= start_timestamp
        ]

    if end_date is not None:
        end_timestamp = (
            pd.Timestamp(end_date).normalize()
            + pd.Timedelta(days=1)
        )

        report_data = report_data[
            report_data["Timestamp"]
            < end_timestamp
        ]

    return report_data.reset_index(
        drop=True
    )


# ------------------------------------------------
# 6.4 GENERAL REPORT METRICS
# ------------------------------------------------

def calculate_reporting_metrics(dataframe):
    """
    Calculate high-level metrics for a report period.
    """

    report_data = prepare_reporting_data(
        dataframe
    )

    sales = report_data[
        "Sales Count"
    ].dropna()

    redemptions = report_data[
        "Redemption Count"
    ].dropna()

    total_sales = (
        float(sales.sum())
        if not sales.empty
        else 0.0
    )

    total_redemptions = (
        float(redemptions.sum())
        if not redemptions.empty
        else 0.0
    )

    valid_sales_count = int(
        sales.notna().sum()
    )

    valid_redemption_count = int(
        redemptions.notna().sum()
    )

    if total_sales != 0:
        redemption_to_sales_ratio = (
            total_redemptions / total_sales
        ) * 100
    else:
        redemption_to_sales_ratio = None

    if not report_data.empty:
        first_timestamp = (
            report_data["Timestamp"].min()
        )

        last_timestamp = (
            report_data["Timestamp"].max()
        )

        covered_days = int(
            (
                last_timestamp.normalize()
                - first_timestamp.normalize()
            ).days
        ) + 1
    else:
        first_timestamp = None
        last_timestamp = None
        covered_days = 0

    if covered_days > 0:
        average_daily_sales = (
            total_sales / covered_days
        )
        average_daily_redemptions = (
            total_redemptions / covered_days
        )
    else:
        average_daily_sales = 0.0
        average_daily_redemptions = 0.0

    return {
        "record_count": int(
            len(report_data)
        ),
        "first_timestamp": first_timestamp,
        "last_timestamp": last_timestamp,
        "covered_days": covered_days,
        "total_sales": total_sales,
        "total_redemptions": total_redemptions,
        "average_daily_sales": (
            average_daily_sales
        ),
        "average_daily_redemptions": (
            average_daily_redemptions
        ),
        "valid_sales_records": (
            valid_sales_count
        ),
        "valid_redemption_records": (
            valid_redemption_count
        ),
        "redemption_to_sales_ratio_pct": (
            redemption_to_sales_ratio
        ),
    }


# ------------------------------------------------
# 6.5 PERIODIC AGGREGATION
# ------------------------------------------------

def build_periodic_reporting_table(
    dataframe,
    frequency="Daily",
):
    """
    Aggregate ticket records by day, week, or month.

    Output columns:
    Period
    Sales Count
    Redemption Count
    Record Count
    Sales Minus Redemptions
    """

    if frequency not in REPORTING_DATE_FREQUENCIES:
        raise ValueError(
            "Unsupported frequency. Choose Daily, Weekly, or Monthly."
        )

    report_data = prepare_reporting_data(dataframe)

    output_columns = [
        "Period",
        "Sales Count",
        "Redemption Count",
        "Record Count",
        "Sales Minus Redemptions",
    ]

    if report_data.empty:
        return pd.DataFrame(columns=output_columns)

    frequency_code = REPORTING_DATE_FREQUENCIES[frequency]

    indexed_data = report_data.set_index("Timestamp")

    grouped = indexed_data.resample(frequency_code).agg({
        "Sales Count": "sum",
        "Redemption Count": "sum",
    })

    grouped["Record Count"] = (
        indexed_data.resample(frequency_code).size()
    )

    grouped = grouped.rename_axis("Period").reset_index()

    grouped["Sales Minus Redemptions"] = (
        grouped["Sales Count"] - grouped["Redemption Count"]
    )

    grouped["Record Count"] = grouped["Record Count"].astype(int)

    return grouped[output_columns]



# ------------------------------------------------
# 6.6 SALES AND REDEMPTION COMPARISON
# ------------------------------------------------

def build_sales_redemption_report(
    dataframe,
):
    """
    Compare total sales and redemptions.

    The difference is a numerical comparison only.
    It must not be interpreted automatically as
    the number of passengers who did not travel.
    """

    report_data = prepare_reporting_data(
        dataframe
    )

    if report_data.empty:
        return pd.DataFrame(
            columns=[
                "Metric",
                "Value",
            ]
        )

    total_sales = float(
        report_data[
            "Sales Count"
        ].sum()
    )

    total_redemptions = float(
        report_data[
            "Redemption Count"
        ].sum()
    )

    sales_minus_redemptions = (
        total_sales
        - total_redemptions
    )

    if total_sales > 0:
        redemption_percentage = (
            total_redemptions
            / total_sales
        ) * 100
    else:
        redemption_percentage = None

    rows = [
        {
            "Metric": "Total Sales Count",
            "Value": total_sales,
        },
        {
            "Metric": "Total Redemption Count",
            "Value": total_redemptions,
        },
        {
            "Metric": "Sales Minus Redemptions",
            "Value": sales_minus_redemptions,
        },
        {
            "Metric": "Redemptions as % of Sales",
            "Value": redemption_percentage,
        },
        {
            "Metric": "Source Record Count",
            "Value": len(report_data),
        },
    ]

    return pd.DataFrame(rows)


# ------------------------------------------------
# 6.7 DATA QUALITY REPORT
# ------------------------------------------------

def build_reporting_quality_table(
    dataframe,
):
    """
    Summarize missing values and invalid numeric values.
    """

    if dataframe is None:
        return pd.DataFrame(
            columns=[
                "Column",
                "Total Records",
                "Missing Values",
                "Missing Percentage",
            ]
        )

    if not isinstance(dataframe, pd.DataFrame):
        raise TypeError(
            "Quality report requires a DataFrame."
        )

    total_records = len(dataframe)

    rows = []

    for column in dataframe.columns:
        missing_count = int(
            dataframe[column].isna().sum()
        )

        if total_records > 0:
            missing_percentage = (
                missing_count
                / total_records
            ) * 100
        else:
            missing_percentage = 0.0

        rows.append(
            {
                "Column": str(column),
                "Total Records": total_records,
                "Missing Values": missing_count,
                "Missing Percentage": (
                    missing_percentage
                ),
            }
        )

    return pd.DataFrame(rows)


# ------------------------------------------------
# 6.8 REPORT SUMMARY TEXT
# ------------------------------------------------

def generate_reporting_summary(
    dataframe,
    report_title="Ferry Demand Report",
):
    """
    Produce a concise human-readable report summary.
    """

    report_data = prepare_reporting_data(
        dataframe
    )

    metrics = calculate_reporting_metrics(
        report_data
    )

    first_timestamp = metrics[
        "first_timestamp"
    ]

    last_timestamp = metrics[
        "last_timestamp"
    ]

    if first_timestamp is not None:
        first_date_text = (
            first_timestamp.strftime(
                "%Y-%m-%d"
            )
        )
    else:
        first_date_text = "Not available"

    if last_timestamp is not None:
        last_date_text = (
            last_timestamp.strftime(
                "%Y-%m-%d"
            )
        )
    else:
        last_date_text = "Not available"

    ratio = metrics[
        "redemption_to_sales_ratio_pct"
    ]

    if ratio is None:
        ratio_text = (
            "Not calculated because total sales are zero."
        )
    else:
        ratio_text = f"{ratio:.2f}%"

    summary_lines = [
        report_title,
        "=" * len(report_title),
        "",
        "REPORT PERIOD",
        f"Start date: {first_date_text}",
        f"End date: {last_date_text}",
        f"Calendar days covered: {metrics['covered_days']}",
        "",
        "RECORD SUMMARY",
        f"Source records: {metrics['record_count']:,}",
        f"Valid sales records: {metrics['valid_sales_records']:,}",
        (
            "Valid redemption records: "
            f"{metrics['valid_redemption_records']:,}"
        ),
        "",
        "DEMAND SUMMARY",
        f"Total sales count: {metrics['total_sales']:,.2f}",
        (
            "Total redemption count: "
            f"{metrics['total_redemptions']:,.2f}"
        ),
        (
            "Average daily sales: "
            f"{metrics['average_daily_sales']:,.2f}"
        ),
        (
            "Average daily redemptions: "
            f"{metrics['average_daily_redemptions']:,.2f}"
        ),
        (
            "Redemptions as percentage of sales: "
            f"{ratio_text}"
        ),
        "",
        "INTERPRETATION NOTE",
        (
            "This report summarizes ticket sales and "
            "redemption records. It does not independently "
            "measure actual passenger boarding or vessel capacity."
        ),
    ]

    return "\n".join(summary_lines)


# ------------------------------------------------
# 6.9 SAFE CSV EXPORT
# ------------------------------------------------

def dataframe_to_csv_bytes(dataframe):
    """
    Convert a DataFrame into UTF-8 CSV bytes.
    """

    if dataframe is None:
        dataframe = pd.DataFrame()

    if not isinstance(dataframe, pd.DataFrame):
        raise TypeError(
            "CSV export requires a pandas DataFrame."
        )

    csv_text = dataframe.to_csv(
        index=False
    )

    return csv_text.encode(
        "utf-8-sig"
    )


# ------------------------------------------------
# 6.10 EXCEL EXPORT
# ------------------------------------------------

def build_excel_report_bytes(
    raw_data,
    daily_report=None,
    weekly_report=None,
    monthly_report=None,
    comparison_report=None,
    quality_report=None,
):
    """
    Build a multi-sheet Excel workbook in memory.

    No permanent file is created by this function.
    The workbook is returned as downloadable bytes.
    """

    from io import BytesIO

    report_data = prepare_reporting_data(
        raw_data
    )

    output_buffer = BytesIO()

    with pd.ExcelWriter(
        output_buffer,
        engine="openpyxl",
    ) as writer:

        report_data.to_excel(
            writer,
            sheet_name="Ticket Records",
            index=False,
        )

        if daily_report is not None:
            daily_report.to_excel(
                writer,
                sheet_name="Daily Summary",
                index=False,
            )

        if weekly_report is not None:
            weekly_report.to_excel(
                writer,
                sheet_name="Weekly Summary",
                index=False,
            )

        if monthly_report is not None:
            monthly_report.to_excel(
                writer,
                sheet_name="Monthly Summary",
                index=False,
            )

        if comparison_report is not None:
            comparison_report.to_excel(
                writer,
                sheet_name="Sales Comparison",
                index=False,
            )

        if quality_report is not None:
            quality_report.to_excel(
                writer,
                sheet_name="Data Quality",
                index=False,
            )

    output_buffer.seek(0)

    return output_buffer.getvalue()


# ------------------------------------------------
# 6.11 DOWNLOAD BUTTON HELPER
# ------------------------------------------------

def render_csv_download_button(
    dataframe,
    label,
    filename,
    key,
):
    """
    Display a reusable CSV download button.
    """

    csv_bytes = dataframe_to_csv_bytes(
        dataframe
    )

    st.download_button(
        label=label,
        data=csv_bytes,
        file_name=filename,
        mime="text/csv",
        key=key,
        use_container_width=True,
    )


# ------------------------------------------------
# 6.12 REPORT PERIOD SELECTOR
# ------------------------------------------------

def render_reporting_period_selector(
    dataframe,
    key_prefix="reporting",
):
    """
    Display report start/end date inputs.

    Returns the selected period's data.
    """

    report_data = prepare_reporting_data(
        dataframe
    )

    if report_data.empty:
        st.warning(
            "No valid timestamped records are available."
        )

        return report_data

    minimum_date = (
        report_data["Timestamp"].min().date()
    )

    maximum_date = (
        report_data["Timestamp"].max().date()
    )

    st.subheader(
        "Select Reporting Period"
    )

    left_column, right_column = st.columns(
        2
    )

    with left_column:
        start_date = st.date_input(
            "Start date",
            value=minimum_date,
            min_value=minimum_date,
            max_value=maximum_date,
            key=f"{key_prefix}_start_date",
        )

    with right_column:
        end_date = st.date_input(
            "End date",
            value=maximum_date,
            min_value=minimum_date,
            max_value=maximum_date,
            key=f"{key_prefix}_end_date",
        )

    if start_date > end_date:
        st.error(
            "Start date cannot be later than end date."
        )

        return report_data.iloc[0:0].copy()

    filtered_data = filter_reporting_period(
        report_data,
        start_date=start_date,
        end_date=end_date,
    )

    st.caption(
        f"Selected period: {start_date} to {end_date}"
    )

    st.caption(
        f"Records included: {len(filtered_data):,}"
    )

    return filtered_data


