# PART 7 â€” START
# OPERATIONAL PLANNING & DEMAND DECISION SUPPORT
# PROJECT: FERRY DEMAND FORECASTING
# AUTHOR: NARENDRA SUTHAR
# ================================================================

# PURPOSE:
# 1. Identify periods with relatively high ticket demand.
# 2. Compare demand across weekdays and months.
# 3. Estimate historical demand variability.
# 4. Produce transparent planning indicators.
# 5. Compare recent demand with a historical baseline.
# 6. Highlight unusually high or low demand periods.
# 7. Generate evidence-based planning suggestions.
# 8. Export the planning results.
#
# IMPORTANT LIMITATIONS:
# - This dataset contains ticket sales and redemption records.
# - It does not provide verified vessel capacity.
# - It does not provide verified passenger boarding counts.
# - It does not provide staffing or vessel availability.
# - Recommendations are planning indicators, not dispatch orders.
# - No exact future passenger count is claimed by this module.


# ------------------------------------------------
# 7.1 OPERATIONAL PLANNING CONFIGURATION
# ------------------------------------------------

OPERATIONAL_PLANNING_VERSION = "1.0.0"

PLANNING_DEMAND_COLUMNS = [
    "Timestamp",
    "Sales Count",
    "Redemption Count",
]

PLANNING_DEFAULT_METRIC = "Sales Count"

PLANNING_SUPPORTED_METRICS = [
    "Sales Count",
    "Redemption Count",
]

PLANNING_SUPPORTED_PERIODS = [
    "Daily",
    "Weekly",
    "Monthly",
]

PLANNING_HIGH_DEMAND_PERCENTILE = 90

PLANNING_LOW_DEMAND_PERCENTILE = 10

PLANNING_RECENT_WINDOW_DAYS = 7

PLANNING_BASELINE_WINDOW_DAYS = 28

PLANNING_MINIMUM_BASELINE_DAYS = 7

PLANNING_VARIABILITY_THRESHOLD = 0.50


# ------------------------------------------------
# 7.2 PREPARE OPERATIONAL PLANNING DATA
# ------------------------------------------------

def prepare_operational_planning_data(
    dataframe,
):
    """
    Prepare the source dataset for planning analysis.

    Returns a standardized copy containing:
    Timestamp, Sales Count, Redemption Count.
    """

    if dataframe is None:
        raise ValueError(
            "Operational planning requires a dataset."
        )

    if not isinstance(
        dataframe,
        pd.DataFrame,
    ):
        raise TypeError(
            "Operational planning input must be a DataFrame."
        )

    if dataframe.empty:
        raise ValueError(
            "Operational planning cannot use an empty dataset."
        )

    missing_columns = [
        column
        for column in PLANNING_DEMAND_COLUMNS
        if column not in dataframe.columns
    ]

    if missing_columns:
        raise ValueError(
            "Missing required planning columns: "
            + ", ".join(missing_columns)
        )

    planning_data = dataframe[
        PLANNING_DEMAND_COLUMNS
    ].copy()

    planning_data["Timestamp"] = pd.to_datetime(
        planning_data["Timestamp"],
        errors="coerce",
    )

    for column in PLANNING_SUPPORTED_METRICS:
        planning_data[column] = pd.to_numeric(
            planning_data[column],
            errors="coerce",
        )

    planning_data = planning_data.dropna(
        subset=["Timestamp"]
    )

    planning_data = planning_data.sort_values(
        "Timestamp"
    )

    planning_data = planning_data.reset_index(
        drop=True
    )

    return planning_data


# ------------------------------------------------
# 7.3 AGGREGATE DEMAND FOR PLANNING
# ------------------------------------------------

def aggregate_operational_demand(
    dataframe,
    metric="Sales Count",
    frequency="Daily",
):
    """
    Aggregate ticket demand by the requested frequency.

    Missing periods are retained with zero aggregate values.
    This means no valid source records were observed for that
    period; it does not prove that real-world demand was zero.
    """

    if metric not in PLANNING_SUPPORTED_METRICS:
        raise ValueError(
            "Unsupported demand metric."
        )

    if frequency not in PLANNING_SUPPORTED_PERIODS:
        raise ValueError(
            "Frequency must be Daily, Weekly, or Monthly."
        )

    planning_data = (
        prepare_operational_planning_data(
            dataframe
        )
    )

    if planning_data.empty:
        return pd.DataFrame(
            columns=[
                "Period",
                metric,
                "Record Count",
            ]
        )

    frequency_mapping = {
        "Daily": "D",
        "Weekly": "W-SUN",
        "Monthly": "MS",
    }

    indexed_data = planning_data.set_index(
        "Timestamp"
    )

    grouped = indexed_data.resample(
        frequency_mapping[frequency]
    ).agg(
        {
            metric: "sum",
            "Redemption Count": "count",
        }
    )

    grouped = grouped.rename(
        columns={
            "Redemption Count": "Record Count",
        }
    )

    grouped = grouped.rename_axis(
        "Period"
    ).reset_index()

    grouped["Record Count"] = (
        grouped["Record Count"].astype(int)
    )

    return grouped


# ------------------------------------------------
# 7.4 CALCULATE DEMAND DISTRIBUTION
# ------------------------------------------------

def calculate_operational_demand_distribution(
    dataframe,
    metric="Sales Count",
):
    """
    Calculate distribution statistics for historical demand.
    """

    if metric not in PLANNING_SUPPORTED_METRICS:
        raise ValueError(
            "Unsupported demand metric."
        )

    planning_data = (
        prepare_operational_planning_data(
            dataframe
        )
    )

    daily_data = aggregate_operational_demand(
        planning_data,
        metric=metric,
        frequency="Daily",
    )

    values = pd.to_numeric(
        daily_data[metric],
        errors="coerce",
    ).dropna()

    if values.empty:
        return {
            "metric": metric,
            "period_count": 0,
            "total": 0.0,
            "mean": None,
            "median": None,
            "standard_deviation": None,
            "minimum": None,
            "maximum": None,
            "p10": None,
            "p50": None,
            "p90": None,
            "coefficient_of_variation": None,
        }

    mean_value = float(
        values.mean()
    )

    standard_deviation = float(
        values.std(ddof=1)
    ) if len(values) > 1 else 0.0

    if mean_value != 0:
        coefficient_of_variation = (
            standard_deviation
            / abs(mean_value)
        )
    else:
        coefficient_of_variation = None

    return {
        "metric": metric,
        "period_count": int(
            len(values)
        ),
        "total": float(
            values.sum()
        ),
        "mean": mean_value,
        "median": float(
            values.median()
        ),
        "standard_deviation": (
            standard_deviation
        ),
        "minimum": float(
            values.min()
        ),
        "maximum": float(
            values.max()
        ),
        "p10": float(
            values.quantile(0.10)
        ),
        "p50": float(
            values.quantile(0.50)
        ),
        "p90": float(
            values.quantile(0.90)
        ),
        "coefficient_of_variation": (
            coefficient_of_variation
        ),
    }


# ------------------------------------------------
# 7.5 IDENTIFY HISTORICAL HIGH-DEMAND PERIODS
# ------------------------------------------------

def identify_operational_high_demand_periods(
    dataframe,
    metric="Sales Count",
    frequency="Daily",
):
    """
    Identify periods at or above a historical percentile.

    This is retrospective classification, not a forecast.
    """

    aggregated_data = (
        aggregate_operational_demand(
            dataframe,
            metric=metric,
            frequency=frequency,
        )
    )

    if aggregated_data.empty:
        return aggregated_data

    valid_values = aggregated_data[
        metric
    ].dropna()

    if valid_values.empty:
        aggregated_data[
            "Demand Classification"
        ] = "Unavailable"

        return aggregated_data

    threshold = float(
        valid_values.quantile(
            PLANNING_HIGH_DEMAND_PERCENTILE / 100
        )
    )

    aggregated_data[
        "Historical High-Demand Threshold"
    ] = threshold

    aggregated_data[
        "Demand Classification"
    ] = np.where(
        aggregated_data[metric] >= threshold,
        "High Demand",
        "Regular Demand",
    )

    return aggregated_data


# ------------------------------------------------
# 7.6 IDENTIFY HISTORICAL LOW-DEMAND PERIODS
# ------------------------------------------------

def identify_operational_low_demand_periods(
    dataframe,
    metric="Sales Count",
    frequency="Daily",
):
    """
    Identify periods at or below a historical percentile.

    Low demand does not automatically imply that services
    should be reduced; additional operational data is needed.
    """

    aggregated_data = (
        aggregate_operational_demand(
            dataframe,
            metric=metric,
            frequency=frequency,
        )
    )

    if aggregated_data.empty:
        return aggregated_data

    valid_values = aggregated_data[
        metric
    ].dropna()

    if valid_values.empty:
        aggregated_data[
            "Demand Classification"
        ] = "Unavailable"

        return aggregated_data

    threshold = float(
        valid_values.quantile(
            PLANNING_LOW_DEMAND_PERCENTILE / 100
        )
    )

    aggregated_data[
        "Historical Low-Demand Threshold"
    ] = threshold

    aggregated_data[
        "Demand Classification"
    ] = np.where(
        aggregated_data[metric] <= threshold,
        "Low Demand",
        "Regular Demand",
    )

    return aggregated_data


# ------------------------------------------------
# 7.7 WEEKDAY PLANNING PROFILE
# ------------------------------------------------

def calculate_weekday_planning_profile(
    dataframe,
    metric="Sales Count",
):
    """
    Compare historical demand across weekdays.
    """

    if metric not in PLANNING_SUPPORTED_METRICS:
        raise ValueError(
            "Unsupported demand metric."
        )

    planning_data = (
        prepare_operational_planning_data(
            dataframe
        )
    )

    if planning_data.empty:
        return pd.DataFrame(
            columns=[
                "Weekday",
                "Average Demand",
                "Median Demand",
                "Total Demand",
                "Observed Records",
            ]
        )

    planning_data["Weekday"] = (
        planning_data["Timestamp"].dt.day_name()
    )

    weekday_summary = (
        planning_data.groupby(
            "Weekday",
            observed=False,
        )
        .agg(
            **{
                "Average Demand": (
                    metric,
                    "mean",
                ),
                "Median Demand": (
                    metric,
                    "median",
                ),
                "Total Demand": (
                    metric,
                    "sum",
                ),
                "Observed Records": (
                    metric,
                    "count",
                ),
            }
        )
        .reset_index()
    )

    weekday_order = [
        "Monday",
        "Tuesday",
        "Wednesday",
        "Thursday",
        "Friday",
        "Saturday",
        "Sunday",
    ]

    weekday_summary["Weekday"] = pd.Categorical(
        weekday_summary["Weekday"],
        categories=weekday_order,
        ordered=True,
    )

    weekday_summary = weekday_summary.sort_values(
        "Weekday"
    )

    weekday_summary["Weekday"] = (
        weekday_summary["Weekday"].astype(str)
    )

    return weekday_summary.reset_index(
        drop=True
    )


# ------------------------------------------------
# 7.8 MONTH-OF-YEAR PLANNING PROFILE
# ------------------------------------------------

def calculate_month_of_year_profile(
    dataframe,
    metric="Sales Count",
):
    """
    Compare demand across calendar months.

    This groups together January observations across years,
    February observations across years, and so on.
    """

    if metric not in PLANNING_SUPPORTED_METRICS:
        raise ValueError(
            "Unsupported demand metric."
        )

    planning_data = (
        prepare_operational_planning_data(
            dataframe
        )
    )

    if planning_data.empty:
        return pd.DataFrame(
            columns=[
                "Month Number",
                "Month",
                "Average Demand",
                "Median Demand",
                "Total Demand",
                "Observed Records",
            ]
        )

    planning_data["Month Number"] = (
        planning_data["Timestamp"].dt.month
    )

    summary = (
        planning_data.groupby(
            "Month Number"
        )
        .agg(
            **{
                "Average Demand": (
                    metric,
                    "mean",
                ),
                "Median Demand": (
                    metric,
                    "median",
                ),
                "Total Demand": (
                    metric,
                    "sum",
                ),
                "Observed Records": (
                    metric,
                    "count",
                ),
            }
        )
        .reset_index()
    )

    month_names = {
        month_number: pd.Timestamp(
            year=2000,
            month=month_number,
            day=1,
        ).strftime("%B")
        for month_number in range(1, 13)
    }

    summary["Month"] = (
        summary["Month Number"].map(
            month_names
        )
    )

    return summary.sort_values(
        "Month Number"
    ).reset_index(
        drop=True
    )


# ------------------------------------------------
# 7.9 RECENT DEMAND VS HISTORICAL BASELINE
# ------------------------------------------------

def compare_recent_demand_with_baseline(
    dataframe,
    metric="Sales Count",
    recent_days=PLANNING_RECENT_WINDOW_DAYS,
    baseline_days=PLANNING_BASELINE_WINDOW_DAYS,
):
    """
    Compare recent daily demand with the preceding baseline.

    This function is descriptive. It does not train a model
    or produce a future-demand forecast.
    """

    if metric not in PLANNING_SUPPORTED_METRICS:
        raise ValueError(
            "Unsupported demand metric."
        )

    if recent_days < 1 or baseline_days < 1:
        raise ValueError(
            "Window sizes must be positive integers."
        )

    planning_data = (
        prepare_operational_planning_data(
            dataframe
        )
    )

    daily_data = aggregate_operational_demand(
        planning_data,
        metric=metric,
        frequency="Daily",
    )

    if daily_data.empty:
        return {
            "status": "No data",
            "metric": metric,
            "recent_average": None,
            "baseline_average": None,
            "percentage_change": None,
            "recent_days": recent_days,
            "baseline_days": baseline_days,
        }

    daily_data = daily_data.sort_values(
        "Period"
    ).reset_index(
        drop=True
    )

    latest_period = daily_data[
        "Period"
    ].max()

    recent_start = (
        latest_period
        - pd.Timedelta(
            days=recent_days - 1
        )
    )

    baseline_end = (
        recent_start
        - pd.Timedelta(days=1)
    )

    baseline_start = (
        baseline_end
        - pd.Timedelta(
            days=baseline_days - 1
        )
    )

    recent_values = daily_data.loc[
        (
            daily_data["Period"] >= recent_start
        )
        & (
            daily_data["Period"] <= latest_period
        ),
        metric,
    ].dropna()

    baseline_values = daily_data.loc[
        (
            daily_data["Period"] >= baseline_start
        )
        & (
            daily_data["Period"] <= baseline_end
        ),
        metric,
    ].dropna()

    if len(recent_values) == 0:
        return {
            "status": "Insufficient recent data",
            "metric": metric,
            "recent_average": None,
            "baseline_average": None,
            "percentage_change": None,
            "recent_days": recent_days,
            "baseline_days": baseline_days,
        }

    if len(baseline_values) == 0:
        return {
            "status": "Insufficient baseline data",
            "metric": metric,
            "recent_average": float(
                recent_values.mean()
            ),
            "baseline_average": None,
            "percentage_change": None,
            "recent_days": recent_days,
            "baseline_days": baseline_days,
        }

    recent_average = float(
        recent_values.mean()
    )

    baseline_average = float(
        baseline_values.mean()
    )

    if baseline_average != 0:
        percentage_change = (
            (
                recent_average
                - baseline_average
            )
            / abs(baseline_average)
        ) * 100
    else:
        percentage_change = None

    return {
        "status": "Calculated",
        "metric": metric,
        "recent_start": recent_start,
        "recent_end": latest_period,
        "baseline_start": baseline_start,
        "baseline_end": baseline_end,
        "recent_observed_days": int(
            len(recent_values)
        ),
        "baseline_observed_days": int(
            len(baseline_values)
        ),
        "recent_average": recent_average,
        "baseline_average": baseline_average,
        "percentage_change": percentage_change,
        "recent_days": recent_days,
        "baseline_days": baseline_days,
    }


# ------------------------------------------------
# 7.10 DEMAND VARIABILITY CLASSIFICATION
# ------------------------------------------------

def classify_demand_variability(
    dataframe,
    metric="Sales Count",
):
    """
    Classify historical demand variability using CV.

    Thresholds are project-defined indicators, not
    externally validated operational standards.
    """

    distribution = (
        calculate_operational_demand_distribution(
            dataframe,
            metric=metric,
        )
    )

    coefficient = distribution[
        "coefficient_of_variation"
    ]

    if coefficient is None:
        category = "Not Available"

    elif coefficient < 0.20:
        category = "Lower Variability"

    elif coefficient < PLANNING_VARIABILITY_THRESHOLD:
        category = "Moderate Variability"

    else:
        category = "Higher Variability"

    return {
        **distribution,
        "variability_category": category,
        "classification_note": (
            "Categories use project-defined thresholds "
            "and are not operational safety limits."
        ),
    }


# ------------------------------------------------
# 7.11 CREATE PLANNING ACTIONS
# ------------------------------------------------

def generate_operational_planning_actions(
    dataframe,
    metric="Sales Count",
):
    """
    Generate transparent planning suggestions from data.

    The output is decision support, not an automatic
    instruction to increase or reduce ferry operations.
    """

    if metric not in PLANNING_SUPPORTED_METRICS:
        raise ValueError(
            "Unsupported demand metric."
        )

    planning_data = (
        prepare_operational_planning_data(
            dataframe
        )
    )

    if planning_data.empty:
        return pd.DataFrame(
            columns=[
                "Planning Area",
                "Observed Evidence",
                "Suggested Action",
                "Confidence",
                "Limitation",
            ]
        )

    distribution = (
        calculate_operational_demand_distribution(
            planning_data,
            metric=metric,
        )
    )

    weekday_profile = (
        calculate_weekday_planning_profile(
            planning_data,
            metric=metric,
        )
    )

    month_profile = (
        calculate_month_of_year_profile(
            planning_data,
            metric=metric,
        )
    )

    recent_comparison = (
        compare_recent_demand_with_baseline(
            planning_data,
            metric=metric,
        )
    )

    variability = (
        classify_demand_variability(
            planning_data,
            metric=metric,
        )
    )

    actions = []

    if (
        not weekday_profile.empty
        and weekday_profile[
            "Average Demand"
        ].notna().any()
    ):
        busiest_weekday_row = (
            weekday_profile.loc[
                weekday_profile[
                    "Average Demand"
                ].idxmax()
            ]
        )

        busiest_weekday = str(
            busiest_weekday_row["Weekday"]
        )

        busiest_weekday_average = float(
            busiest_weekday_row[
                "Average Demand"
            ]
        )

        actions.append(
            {
                "Planning Area": "Weekly Scheduling",
                "Observed Evidence": (
                    f"{busiest_weekday} has the highest "
                    "historical average "
                    f"{metric.lower()}: "
                    f"{busiest_weekday_average:,.2f}."
                ),
                "Suggested Action": (
                    "Review historical booking patterns "
                    "and consider additional readiness "
                    "checks for comparable weekdays."
                ),
                "Confidence": "Historical pattern",
                "Limitation": (
                    "Does not confirm future demand or "
                    "required vessel count."
                ),
            }
        )

    if (
        not month_profile.empty
        and month_profile[
            "Average Demand"
        ].notna().any()
    ):
        busiest_month_row = (
            month_profile.loc[
                month_profile[
                    "Average Demand"
                ].idxmax()
            ]
        )

        busiest_month = str(
            busiest_month_row["Month"]
        )

        busiest_month_average = float(
            busiest_month_row[
                "Average Demand"
            ]
        )

        actions.append(
            {
                "Planning Area": "Seasonal Review",
                "Observed Evidence": (
                    f"{busiest_month} has the highest "
                    "average monthly-calendar "
                    f"{metric.lower()}: "
                    f"{busiest_month_average:,.2f}."
                ),
                "Suggested Action": (
                    "Review multiple years of records, "
                    "holidays, events and weather before "
                    "making seasonal plans."
                ),
                "Confidence": "Historical pattern",
                "Limitation": (
                    "Calendar-month averages may hide "
                    "year-to-year changes."
                ),
            }
        )

    coefficient = distribution[
        "coefficient_of_variation"
    ]

    if (
        coefficient is not None
        and coefficient
        >= PLANNING_VARIABILITY_THRESHOLD
    ):
        actions.append(
            {
                "Planning Area": "Demand Variability",
                "Observed Evidence": (
                    "The historical coefficient of "
                    f"variation is {coefficient:.3f}."
                ),
                "Suggested Action": (
                    "Investigate high-demand dates and "
                    "consider a more flexible planning "
                    "review process."
                ),
                "Confidence": "Statistical indicator",
                "Limitation": (
                    "Variability alone does not identify "
                    "its cause."
                ),
            }
        )

    recent_change = recent_comparison.get(
        "percentage_change"
    )

    if recent_change is not None:
        if recent_change >= 10:
            direction = "increased"

            recommendation = (
                "Review the latest demand pattern and "
                "check whether the change is associated "
                "with events, holidays or other factors."
            )

        elif recent_change <= -10:
            direction = "decreased"

            recommendation = (
                "Review data completeness and investigate "
                "whether the change reflects a real pattern "
                "or a reporting difference."
            )

        else:
            direction = "changed only modestly"

            recommendation = (
                "Continue monitoring and compare the "
                "next reporting period with the baseline."
            )

        actions.append(
            {
                "Planning Area": "Recent Demand Monitoring",
                "Observed Evidence": (
                    f"Recent average demand {direction} "
                    f"by {recent_change:.2f}% versus "
                    "the preceding baseline."
                ),
                "Suggested Action": recommendation,
                "Confidence": "Historical comparison",
                "Limitation": (
                    "A recent change is not itself a "
                    "future-demand forecast."
                ),
            }
        )

    if not actions:
        actions.append(
            {
                "Planning Area": "General Monitoring",
                "Observed Evidence": (
                    "Insufficient evidence for a more "
                    "specific planning recommendation."
                ),
                "Suggested Action": (
                    "Continue collecting consistent "
                    "ticket sales and redemption records."
                ),
                "Confidence": "Limited evidence",
                "Limitation": (
                    "Additional operational variables "
                    "are needed for stronger decisions."
                ),
            }
        )

    actions.append(
        {
            "Planning Area": "Operational Validation",
            "Observed Evidence": (
                "The available dataset contains ticket "
                "sales and redemption records."
            ),
            "Suggested Action": (
                "Combine demand analysis with verified "
                "boarding counts, vessel capacities, "
                "service schedules and staffing data."
            ),
            "Confidence": "Data limitation identified",
            "Limitation": (
                "This dataset alone cannot determine "
                "safe vessel loading or staffing levels."
            ),
        }
    )

    return pd.DataFrame(actions)


# ------------------------------------------------
# 7.12 BUILD A CONSOLIDATED PLANNING REPORT
# ------------------------------------------------

def build_operational_planning_report(
    dataframe,
    metric="Sales Count",
):
    """
    Build a consolidated dictionary of planning outputs.
    """

    planning_data = (
        prepare_operational_planning_data(
            dataframe
        )
    )

    return {
        "metrics": (
            calculate_operational_demand_distribution(
                planning_data,
                metric=metric,
            )
        ),
        "high_demand_periods": (
            identify_operational_high_demand_periods(
                planning_data,
                metric=metric,
                frequency="Daily",
            )
        ),
        "low_demand_periods": (
            identify_operational_low_demand_periods(
                planning_data,
                metric=metric,
                frequency="Daily",
            )
        ),
        "weekday_profile": (
            calculate_weekday_planning_profile(
                planning_data,
                metric=metric,
            )
        ),
        "month_profile": (
            calculate_month_of_year_profile(
                planning_data,
                metric=metric,
            )
        ),
        "recent_comparison": (
            compare_recent_demand_with_baseline(
                planning_data,
                metric=metric,
            )
        ),
        "variability": (
            classify_demand_variability(
                planning_data,
                metric=metric,
            )
        ),
        "actions": (
            generate_operational_planning_actions(
                planning_data,
                metric=metric,
            )
        ),
    }


