# ================================================================
# PART 8 â€” START
# FORECAST PERFORMANCE & MODEL INTELLIGENCE CENTER
# PROJECT: FERRY DEMAND FORECASTING
# AUTHOR: NARENDRA SUTHAR
# ================================================================

# PURPOSE:
# 1. Evaluate forecasts when actual and predicted values exist.
# 2. Calculate MAE, RMSE, and WAPE.
# 3. Compare multiple forecasting models.
# 4. Display actual versus predicted values.
# 5. Identify the model with the lowest selected error metric.
# 6. Explain the limitations of evaluation results.
# 7. Export evaluation results.
#
# IMPORTANT:
# Evaluation requires actual and predicted values aligned
# to the same time periods and the same target metric.
#
# The functions below do not assume that a trained model
# or prediction file already exists.
#
# No performance score is invented when evaluation data
# is unavailable.


# ------------------------------------------------
# 8.1 CONFIGURATION
# ------------------------------------------------

MODEL_INTELLIGENCE_VERSION = "1.0.0"

MODEL_EVALUATION_METRICS = [
    "MAE",
    "RMSE",
    "WAPE",
]

MODEL_EVALUATION_TARGETS = [
    "Sales Count",
    "Redemption Count",
]

MODEL_EVALUATION_DATE_COLUMN = "Timestamp"

MODEL_EVALUATION_ACTUAL_COLUMN = "Actual"

MODEL_EVALUATION_PREDICTED_COLUMN = "Predicted"


# ------------------------------------------------
# 8.2 STANDARDIZE EVALUATION DATA
# ------------------------------------------------

def prepare_model_evaluation_data(
    dataframe,
    date_column=None,
    actual_column=None,
    predicted_column=None,
):
    """
    Standardize a dataset containing actual and predicted values.

    Returns:
        Timestamp
        Actual
        Predicted

    Input column names can be supplied explicitly.
    """

    if dataframe is None:
        raise ValueError(
            "Evaluation data is missing."
        )

    if not isinstance(
        dataframe,
        pd.DataFrame,
    ):
        raise TypeError(
            "Evaluation input must be a pandas DataFrame."
        )

    if dataframe.empty:
        raise ValueError(
            "Evaluation data is empty."
        )

    date_column = (
        date_column
        or MODEL_EVALUATION_DATE_COLUMN
    )

    actual_column = (
        actual_column
        or MODEL_EVALUATION_ACTUAL_COLUMN
    )

    predicted_column = (
        predicted_column
        or MODEL_EVALUATION_PREDICTED_COLUMN
    )

    required_columns = [
        date_column,
        actual_column,
        predicted_column,
    ]

    missing_columns = [
        column
        for column in required_columns
        if column not in dataframe.columns
    ]

    if missing_columns:
        raise ValueError(
            "Missing evaluation columns: "
            + ", ".join(missing_columns)
        )

    evaluation_data = dataframe[
        required_columns
    ].copy()

    evaluation_data.columns = [
        "Timestamp",
        "Actual",
        "Predicted",
    ]

    evaluation_data["Timestamp"] = (
        pd.to_datetime(
            evaluation_data["Timestamp"],
            errors="coerce",
        )
    )

    evaluation_data["Actual"] = (
        pd.to_numeric(
            evaluation_data["Actual"],
            errors="coerce",
        )
    )

    evaluation_data["Predicted"] = (
        pd.to_numeric(
            evaluation_data["Predicted"],
            errors="coerce",
        )
    )

    evaluation_data = evaluation_data.replace(
        [np.inf, -np.inf],
        np.nan,
    )

    evaluation_data = evaluation_data.dropna(
        subset=[
            "Timestamp",
            "Actual",
            "Predicted",
        ]
    )

    evaluation_data = evaluation_data.sort_values(
        "Timestamp"
    )

    evaluation_data = evaluation_data.reset_index(
        drop=True
    )

    return evaluation_data


# ------------------------------------------------
# 8.3 CALCULATE MEAN ABSOLUTE ERROR
# ------------------------------------------------

def calculate_model_mae(
    actual_values,
    predicted_values,
):
    """
    MAE measures the average absolute prediction error.

    Formula:
        MAE = mean(abs(actual - predicted))
    """

    actual = np.asarray(
        actual_values,
        dtype=float,
    )

    predicted = np.asarray(
        predicted_values,
        dtype=float,
    )

    if actual.size == 0:
        return None

    if actual.shape != predicted.shape:
        raise ValueError(
            "Actual and predicted arrays must have equal shapes."
        )

    valid_mask = (
        np.isfinite(actual)
        & np.isfinite(predicted)
    )

    actual = actual[valid_mask]
    predicted = predicted[valid_mask]

    if actual.size == 0:
        return None

    return float(
        np.mean(
            np.abs(
                actual - predicted
            )
        )
    )


# ------------------------------------------------
# 8.4 CALCULATE ROOT MEAN SQUARED ERROR
# ------------------------------------------------

def calculate_model_rmse(
    actual_values,
    predicted_values,
):
    """
    RMSE penalizes larger errors more heavily than MAE.

    Formula:
        RMSE = sqrt(mean((actual - predicted) ** 2))
    """

    actual = np.asarray(
        actual_values,
        dtype=float,
    )

    predicted = np.asarray(
        predicted_values,
        dtype=float,
    )

    if actual.size == 0:
        return None

    if actual.shape != predicted.shape:
        raise ValueError(
            "Actual and predicted arrays must have equal shapes."
        )

    valid_mask = (
        np.isfinite(actual)
        & np.isfinite(predicted)
    )

    actual = actual[valid_mask]
    predicted = predicted[valid_mask]

    if actual.size == 0:
        return None

    squared_errors = (
        actual - predicted
    ) ** 2

    return float(
        np.sqrt(
            np.mean(squared_errors)
        )
    )


# ------------------------------------------------
# 8.5 CALCULATE WEIGHTED ABSOLUTE PERCENTAGE ERROR
# ------------------------------------------------

def calculate_model_wape(
    actual_values,
    predicted_values,
):
    """
    Calculate WAPE as a percentage.

    Formula:
        sum(abs(actual - predicted))
        -------------------------------- * 100
                  sum(abs(actual))

    WAPE is undefined when the denominator is zero.
    """

    actual = np.asarray(
        actual_values,
        dtype=float,
    )

    predicted = np.asarray(
        predicted_values,
        dtype=float,
    )

    if actual.size == 0:
        return None

    if actual.shape != predicted.shape:
        raise ValueError(
            "Actual and predicted arrays must have equal shapes."
        )

    valid_mask = (
        np.isfinite(actual)
        & np.isfinite(predicted)
    )

    actual = actual[valid_mask]
    predicted = predicted[valid_mask]

    if actual.size == 0:
        return None

    denominator = float(
        np.sum(
            np.abs(actual)
        )
    )

    if denominator == 0:
        return None

    numerator = float(
        np.sum(
            np.abs(
                actual - predicted
            )
        )
    )

    return float(
        numerator / denominator * 100
    )


# ------------------------------------------------
# 8.6 CALCULATE ALL CORE METRICS
# ------------------------------------------------

def calculate_model_evaluation_metrics(
    evaluation_data,
):
    """
    Calculate core regression-style forecasting metrics.
    """

    standardized_data = (
        prepare_model_evaluation_data(
            evaluation_data
        )
    )

    actual = standardized_data[
        "Actual"
    ].to_numpy()

    predicted = standardized_data[
        "Predicted"
    ].to_numpy()

    mae = calculate_model_mae(
        actual,
        predicted,
    )

    rmse = calculate_model_rmse(
        actual,
        predicted,
    )

    wape = calculate_model_wape(
        actual,
        predicted,
    )

    return {
        "evaluation_records": int(
            len(standardized_data)
        ),
        "MAE": mae,
        "RMSE": rmse,
        "WAPE_Percent": wape,
        "evaluation_start": (
            standardized_data[
                "Timestamp"
            ].min()
        ),
        "evaluation_end": (
            standardized_data[
                "Timestamp"
            ].max()
        ),
    }


# ------------------------------------------------
# 8.7 CREATE ACTUAL-VERSUS-PREDICTED TABLE
# ------------------------------------------------

def build_actual_prediction_comparison(
    evaluation_data,
):
    """
    Add error columns to standardized evaluation records.
    """

    standardized_data = (
        prepare_model_evaluation_data(
            evaluation_data
        )
    )

    comparison = standardized_data.copy()

    comparison["Error"] = (
        comparison["Actual"]
        - comparison["Predicted"]
    )

    comparison["Absolute Error"] = (
        comparison["Error"].abs()
    )

    comparison["Squared Error"] = (
        comparison["Error"] ** 2
    )

    comparison["Absolute Percentage Error"] = (
        np.where(
            comparison["Actual"].abs() > 0,
            (
                comparison["Absolute Error"]
                / comparison["Actual"].abs()
            ) * 100,
            np.nan,
        )
    )

    return comparison


# ------------------------------------------------
# 8.8 EVALUATE A SINGLE MODEL
# ------------------------------------------------

def evaluate_single_forecasting_model(
    dataframe,
    model_name="Unnamed Model",
    date_column=None,
    actual_column=None,
    predicted_column=None,
):
    """
    Evaluate a single model and return metrics plus details.
    """

    evaluation_data = (
        prepare_model_evaluation_data(
            dataframe,
            date_column=date_column,
            actual_column=actual_column,
            predicted_column=predicted_column,
        )
    )

    metrics = (
        calculate_model_evaluation_metrics(
            evaluation_data
        )
    )

    comparison = (
        build_actual_prediction_comparison(
            evaluation_data
        )
    )

    summary = {
        "Model": model_name,
        "Evaluation Records": (
            metrics["evaluation_records"]
        ),
        "MAE": metrics["MAE"],
        "RMSE": metrics["RMSE"],
        "WAPE (%)": metrics["WAPE_Percent"],
        "Evaluation Start": (
            metrics["evaluation_start"]
        ),
        "Evaluation End": (
            metrics["evaluation_end"]
        ),
    }

    return {
        "summary": summary,
        "comparison": comparison,
        "metrics": metrics,
    }


# ------------------------------------------------
# 8.9 EVALUATE MULTIPLE MODELS
# ------------------------------------------------

def evaluate_multiple_forecasting_models(
    model_dataframes,
    date_column=None,
    actual_column=None,
    predicted_column=None,
):
    """
    Evaluate multiple models.

    Parameters:
        model_dataframes:
            Dictionary mapping model names to DataFrames.

    Returns:
        Summary table.
        Dictionary of detailed comparisons.

    Each model must provide aligned actual and predicted values.
    """

    if not isinstance(
        model_dataframes,
        dict,
    ):
        raise TypeError(
            "model_dataframes must be a dictionary."
        )

    if not model_dataframes:
        return (
            pd.DataFrame(
                columns=[
                    "Model",
                    "Evaluation Records",
                    "MAE",
                    "RMSE",
                    "WAPE (%)",
                ]
            ),
            {},
        )

    summary_rows = []
    detailed_results = {}

    for model_name, model_dataframe in (
        model_dataframes.items()
    ):
        try:
            result = (
                evaluate_single_forecasting_model(
                    dataframe=model_dataframe,
                    model_name=str(model_name),
                    date_column=date_column,
                    actual_column=actual_column,
                    predicted_column=predicted_column,
                )
            )

            summary_rows.append(
                result["summary"]
            )

            detailed_results[
                str(model_name)
            ] = result

        except (
            ValueError,
            TypeError,
            KeyError,
        ) as error:
            summary_rows.append(
                {
                    "Model": str(model_name),
                    "Evaluation Records": 0,
                    "MAE": None,
                    "RMSE": None,
                    "WAPE (%)": None,
                    "Evaluation Error": str(error),
                }
            )

    summary_table = pd.DataFrame(
        summary_rows
    )

    return (
        summary_table,
        detailed_results,
    )


# ------------------------------------------------
# 8.10 RANK MODELS BY ERROR
# ------------------------------------------------

def rank_forecasting_models(
    model_summary,
    metric="MAE",
):
    """
    Rank evaluated models by an error metric.

    Lower values are preferred only when the compared
    models use the same evaluation observations and target.
    """

    if model_summary is None:
        return pd.DataFrame()

    if not isinstance(
        model_summary,
        pd.DataFrame,
    ):
        raise TypeError(
            "Model summary must be a DataFrame."
        )

    if model_summary.empty:
        return model_summary.copy()

    if metric not in model_summary.columns:
        raise ValueError(
            f"Metric '{metric}' is not available."
        )

    ranked = model_summary.copy()

    ranked[metric] = pd.to_numeric(
        ranked[metric],
        errors="coerce",
    )

    ranked = ranked.dropna(
        subset=[metric]
    )

    ranked = ranked.sort_values(
        metric,
        ascending=True,
    ).reset_index(
        drop=True
    )

    ranked.insert(
        0,
        "Rank",
        np.arange(
            1,
            len(ranked) + 1,
        ),
    )

    return ranked


# ------------------------------------------------
# 8.11 IDENTIFY THE BEST AVAILABLE MODEL
# ------------------------------------------------

def identify_best_forecasting_model(
    model_summary,
    metric="MAE",
):
    """
    Identify the lowest-error model in an evaluation table.

    This does not establish that the model will perform
    best on future, unseen data.
    """

    ranked = rank_forecasting_models(
        model_summary,
        metric=metric,
    )

    if ranked.empty:
        return {
            "status": "No evaluable models",
            "metric": metric,
            "best_model": None,
            "best_score": None,
        }

    best_row = ranked.iloc[0]

    return {
        "status": "Ranked by available evaluation metric",
        "metric": metric,
        "best_model": str(
            best_row["Model"]
        ),
        "best_score": float(
            best_row[metric]
        ),
        "ranked_models": ranked,
    }


# ------------------------------------------------
# 8.12 CALCULATE RESIDUAL DIAGNOSTICS
# ------------------------------------------------

def calculate_residual_diagnostics(
    evaluation_data,
):
    """
    Summarize forecast residuals.

    Residual convention:
        Residual = Actual - Predicted
    """

    comparison = (
        build_actual_prediction_comparison(
            evaluation_data
        )
    )

    if comparison.empty:
        return {
            "record_count": 0,
            "mean_residual": None,
            "median_residual": None,
            "residual_std": None,
            "positive_residual_count": 0,
            "negative_residual_count": 0,
            "zero_residual_count": 0,
        }

    residuals = comparison[
        "Error"
    ].dropna()

    if residuals.empty:
        return {
            "record_count": 0,
            "mean_residual": None,
            "median_residual": None,
            "residual_std": None,
            "positive_residual_count": 0,
            "negative_residual_count": 0,
            "zero_residual_count": 0,
        }

    return {
        "record_count": int(
            len(residuals)
        ),
        "mean_residual": float(
            residuals.mean()
        ),
        "median_residual": float(
            residuals.median()
        ),
        "residual_std": float(
            residuals.std(ddof=1)
        ) if len(residuals) > 1 else 0.0,
        "positive_residual_count": int(
            (residuals > 0).sum()
        ),
        "negative_residual_count": int(
            (residuals < 0).sum()
        ),
        "zero_residual_count": int(
            (residuals == 0).sum()
        ),
    }


# ------------------------------------------------
# 8.13 RESIDUAL INTERPRETATION
# ------------------------------------------------

def generate_residual_interpretation(
    diagnostics,
):
    """
    Produce a simple explanation of residual direction.
    """

    if diagnostics.get("record_count", 0) == 0:
        return (
            "Residual interpretation is unavailable "
            "because no valid evaluation records exist."
        )

    mean_residual = diagnostics.get(
        "mean_residual"
    )

    if mean_residual is None:
        return (
            "The mean residual could not be calculated."
        )

    if mean_residual > 0:
        return (
            "Average actual values exceed predictions. "
            "The model may be underpredicting on average "
            "over the evaluated records."
        )

    if mean_residual < 0:
        return (
            "Average predictions exceed actual values. "
            "The model may be overpredicting on average "
            "over the evaluated records."
        )

    return (
        "The mean residual is zero over the evaluated records. "
        "Individual prediction errors may still exist."
    )


# ------------------------------------------------
# 8.14 FIND LARGEST PREDICTION ERRORS
# ------------------------------------------------

def find_largest_forecast_errors(
    evaluation_data,
    top_n=20,
):
    """
    Return records with the largest absolute errors.
    """

    if top_n < 1:
        raise ValueError(
            "top_n must be a positive integer."
        )

    comparison = (
        build_actual_prediction_comparison(
            evaluation_data
        )
    )

    if comparison.empty:
        return comparison

    comparison = comparison.sort_values(
        "Absolute Error",
        ascending=False,
    )

    return comparison.head(
        top_n
    ).reset_index(
        drop=True
    )


# ------------------------------------------------
# 8.15 CREATE EVALUATION REPORT
# ------------------------------------------------

def build_forecast_evaluation_report(
    evaluation_data,
    model_name="Forecast Model",
):
    """
    Build a consolidated evaluation report.
    """

    evaluation = (
        evaluate_single_forecasting_model(
            dataframe=evaluation_data,
            model_name=model_name,
        )
    )

    diagnostics = (
        calculate_residual_diagnostics(
            evaluation_data
        )
    )

    largest_errors = (
        find_largest_forecast_errors(
            evaluation_data,
            top_n=20,
        )
    )

    return {
        "model_summary": pd.DataFrame(
            [evaluation["summary"]]
        ),
        "comparison": evaluation["comparison"],
        "metrics": evaluation["metrics"],
        "residual_diagnostics": diagnostics,
        "residual_interpretation": (
            generate_residual_interpretation(
                diagnostics
            )
        ),
        "largest_errors": largest_errors,
    }


