# ------------------------------------------------
# 8.22 FORECAST EVALUATION PAGE
# ------------------------------------------------

def render_forecast_evaluation_center():
    """
    Render the model evaluation interface.

    The user provides a CSV containing aligned actual
    and predicted values. No assumed output path is required.
    """

    st.header(
        "Forecast Performance & Model Intelligence"
    )

    st.write(
        "Upload an evaluation CSV containing timestamps, "
        "actual values, and predicted values to calculate "
        "forecast performance metrics."
    )

    st.info(
        "This page evaluates supplied prediction results. "
        "It does not train a model or create predictions."
    )

    uploaded_file = st.file_uploader(
        "Upload an evaluation CSV",
        type=["csv"],
        key="model_evaluation_upload",
        help=(
            "Required information: timestamp, actual value, "
            "and predicted value. You can select the exact "
            "column names below."
        ),
    )

    if uploaded_file is None:
        st.warning(
            "Upload a prediction evaluation CSV to view "
            "model performance."
        )

        st.markdown(
            """
            **Required structure example**

            | Timestamp | Actual | Predicted |
            |---|---:|---:|
            | 2025-01-01 | 100 | 95 |
            | 2025-01-02 | 120 | 115 |

            The numbers above are illustrative only.
            They are not results from your ferry dataset.
            """
        )

        return

    try:
        uploaded_data = pd.read_csv(
            uploaded_file
        )

    except Exception as error:
        st.error(
            "The uploaded CSV could not be read."
        )

        logging.exception(
            "Evaluation CSV read failed: %s",
            error,
        )

        return

    if uploaded_data.empty:
        st.warning(
            "The uploaded CSV contains no records."
        )

        return

    st.markdown(
        "#### Map Evaluation Columns"
    )

    available_columns = list(
        uploaded_data.columns
    )

    default_date_index = (
        available_columns.index("Timestamp")
        if "Timestamp" in available_columns
        else 0
    )

    default_actual_index = (
        available_columns.index("Actual")
        if "Actual" in available_columns
        else min(
            1,
            len(available_columns) - 1,
        )
    )

    default_predicted_index = (
        available_columns.index("Predicted")
        if "Predicted" in available_columns
        else min(
            2,
            len(available_columns) - 1,
        )
    )

    date_column = st.selectbox(
        "Timestamp column",
        options=available_columns,
        index=default_date_index,
        key="evaluation_date_column",
    )

    actual_column = st.selectbox(
        "Actual values column",
        options=available_columns,
        index=default_actual_index,
        key="evaluation_actual_column",
    )

    predicted_column = st.selectbox(
        "Predicted values column",
        options=available_columns,
        index=default_predicted_index,
        key="evaluation_predicted_column",
    )

    model_name = st.text_input(
        "Model name",
        value="Uploaded Forecast Model",
        key="evaluation_model_name",
    )

    if (
        len(
            {
                date_column,
                actual_column,
                predicted_column,
            }
        )
        != 3
    ):
        st.error(
            "Choose three different columns for timestamp, "
            "actual values, and predicted values."
        )

        return

    try:
        standardized = (
            prepare_model_evaluation_data(
                uploaded_data,
                date_column=date_column,
                actual_column=actual_column,
                predicted_column=predicted_column,
            )
        )

    except Exception as error:
        st.error(
            f"Evaluation preparation failed: {error}"
        )

        return

    if standardized.empty:
        st.warning(
            "No valid aligned evaluation records were found."
        )

        return

    evaluation_report = (
        build_forecast_evaluation_report(
            standardized,
            model_name=(
                model_name.strip()
                or "Uploaded Forecast Model"
            ),
        )
    )

    st.success(
        f"Evaluation records prepared: "
        f"{len(standardized):,}"
    )

    st.divider()

    render_forecast_evaluation_metrics(
        evaluation_report["metrics"]
    )

    st.divider()

    render_actual_prediction_chart(
        evaluation_report["comparison"]
    )

    st.divider()

    render_residual_diagnostics(
        evaluation_report[
            "residual_diagnostics"
        ],
        evaluation_report[
            "residual_interpretation"
        ],
    )

    st.divider()

    render_largest_forecast_errors(
        evaluation_report[
            "largest_errors"
        ]
    )

    st.divider()

    render_forecast_evaluation_exports(
        evaluation_report
    )


