# 10.13 â€” EXPORT SCENARIO RESULTS
# ------------------------------------------------------------

def render_scenario_export(
    scenario_table,
):
    """
    Provide a CSV download of scenario comparison results.
    """

    st.subheader(
        "Export Scenario Results"
    )

    if scenario_table is None:
        st.info(
            "Scenario results are not available."
        )
        return

    if not isinstance(
        scenario_table,
        pd.DataFrame,
    ):
        st.info(
            "Scenario results have an invalid format."
        )
        return

    if scenario_table.empty:
        st.info(
            "No scenario results are available to export."
        )
        return

    csv_bytes = scenario_table.to_csv(
        index=False
    ).encode("utf-8")

    st.download_button(
        label="Download Scenario Comparison CSV",
        data=csv_bytes,
        file_name="ferry_demand_scenario_comparison.csv",
        mime="text/csv",
        key="scenario_comparison_download",
    )


# ------------------------------------------------------------
# 10.14 â€” MAIN SCENARIO SIMULATOR PAGE
# ------------------------------------------------------------

def render_demand_scenario_simulator(dataframe):
    """
    Main Streamlit renderer for the Demand Scenario Simulator.

    This page will be connected to navigation during final
    dashboard integration.
    """

    st.title(
        "Demand Forecast Scenario Simulator"
    )

    st.write(
        "Explore how different percentage changes in "
        "historical ticket counts affect estimated demand."
    )

    st.warning(
        "What-if simulation only: these results are not "
        "machine-learning forecasts and do not represent "
        "verified passenger boarding or ferry capacity."
    )

    if dataframe is None or not isinstance(
        dataframe,
        pd.DataFrame,
    ):
        st.error(
            "A valid historical dataset is required."
        )
        return

    prepared = prepare_scenario_data(
        dataframe
    )

    if prepared.empty:
        st.error(
            "The dataset does not contain enough valid "
            "information for scenario simulation."
        )
        return

    controls = render_scenario_controls()

    aggregated = aggregate_scenario_demand(
        prepared,
        metric=controls["metric"],
        frequency=controls["frequency"],
    )

    if aggregated.empty:
        st.warning(
            "No aggregated historical demand is available."
        )
        return

    baseline_result = calculate_scenario_baseline(
        aggregated,
        metric=controls["metric"],
        baseline_method=controls["baseline_method"],
        recent_periods=controls["recent_periods"],
    )

    if baseline_result["Status"] != "Available":
        st.warning(
            baseline_result["Status"]
        )
        return

    st.divider()

    st.subheader(
        "Historical Baseline"
    )

    render_scenario_baseline_metrics(
        baseline_result
    )

    st.divider()

    st.subheader(
        "Your Custom Scenario"
    )

    custom_result = render_custom_scenario_result(
        baseline_demand=baseline_result["Baseline"],
        growth_percentage=controls["growth_percentage"],
        scenario_name=controls["scenario_name"],
    )

    st.divider()

    scenario_table = render_scenario_comparison(
        baseline_result["Baseline"]
    )

    st.divider()

    render_scenario_interpretation(
        scenario_table
    )

    st.divider()

    if not isinstance(
        scenario_table,
        pd.DataFrame,
    ):
        scenario_table = pd.DataFrame()

    export_table = scenario_table.copy()

    if (
        isinstance(custom_result, dict)
        and custom_result.get("Status") == "Calculated"
    ):
        export_table = pd.concat(
            [
                export_table,
                pd.DataFrame([custom_result]),
            ],
            ignore_index=True,
        )

    render_scenario_export(
        export_table
    )


