# ============================================================
# PART 14 â€” SEASONALITY & CALENDAR PATTERN INTELLIGENCE
# ============================================================

SEASONALITY_MODULE_VERSION = "1.0.0"

SEASONALITY_METRICS = [
    "Sales Count",
    "Redemption Count",
]

SEASONALITY_FREQUENCIES = [
    "Daily",
    "Weekly",
    "Monthly",
]

SEASONALITY_WEEKDAY_ORDER = [
    "Monday",
    "Tuesday",
    "Wednesday",
    "Thursday",
    "Friday",
    "Saturday",
    "Sunday",
]

SEASONALITY_MONTH_ORDER = [
    "January",
    "February",
    "March",
    "April",
    "May",
    "June",
    "July",
    "August",
    "September",
    "October",
    "November",
    "December",
]


# ------------------------------------------------------------
# 14.1 â€” PREPARE CALENDAR DATA
# ------------------------------------------------------------

def prepare_seasonality_data(dataframe):
    """
    Prepare ticket records and derive calendar attributes.

    Calendar attributes are derived from Timestamp.
    No public-holiday calendar is assumed.
    """

    if not isinstance(dataframe, pd.DataFrame):
        return pd.DataFrame()

    required_columns = [
        "Timestamp",
        "Sales Count",
        "Redemption Count",
    ]

    if not all(
        column in dataframe.columns
        for column in required_columns
    ):
        return pd.DataFrame()

    prepared = dataframe[
        required_columns
    ].copy()

    prepared["Timestamp"] = pd.to_datetime(
        prepared["Timestamp"],
        errors="coerce",
    )

    for column in SEASONALITY_METRICS:
        prepared[column] = pd.to_numeric(
            prepared[column],
            errors="coerce",
        )

    prepared = prepared.dropna(
        subset=["Timestamp"]
    )

    prepared = prepared.sort_values(
        "Timestamp"
    ).reset_index(drop=True)

    prepared["Year"] = (
        prepared["Timestamp"].dt.year
    )

    prepared["Month_Number"] = (
        prepared["Timestamp"].dt.month
    )

    prepared["Month"] = (
        prepared["Timestamp"].dt.month_name()
    )

    prepared["Weekday_Number"] = (
        prepared["Timestamp"].dt.dayofweek
    )

    prepared["Weekday"] = (
        prepared["Timestamp"].dt.day_name()
    )

    prepared["Day_of_Month"] = (
        prepared["Timestamp"].dt.day
    )

    prepared["Week_of_Year"] = (
        prepared["Timestamp"].dt.isocalendar().week
        .astype(int)
    )

    prepared["Quarter"] = (
        prepared["Timestamp"].dt.quarter
    )

    prepared["Year_Month"] = (
        prepared["Timestamp"].dt.to_period("M")
        .astype(str)
    )

    prepared["Date"] = (
        prepared["Timestamp"].dt.normalize()
    )

    return prepared


# ------------------------------------------------------------
# 14.2 â€” AGGREGATE CALENDAR DEMAND
# ------------------------------------------------------------

def aggregate_seasonality_demand(
    dataframe,
    metric="Sales Count",
    frequency="Daily",
):
    """
    Aggregate recorded ticket counts by calendar period.
    """

    prepared = prepare_seasonality_data(
        dataframe
    )

    if prepared.empty:
        return pd.DataFrame(
            columns=["Period", "Observed Demand"]
        )

    if metric not in SEASONALITY_METRICS:
        return pd.DataFrame(
            columns=["Period", "Observed Demand"]
        )

    frequency_mapping = {
        "Daily": "D",
        "Weekly": "W-SUN",
        "Monthly": "MS",
    }

    if frequency not in frequency_mapping:
        frequency = "Daily"

    indexed = prepared.set_index(
        "Timestamp"
    )

    aggregated = indexed[
        metric
    ].resample(
        frequency_mapping[frequency]
    ).sum(min_count=1)

    result = aggregated.rename(
        "Observed Demand"
    ).reset_index()

    result = result.rename(
        columns={
            "Timestamp": "Period",
        }
    )

    return result


# ------------------------------------------------------------
# 14.3 â€” WEEKDAY PATTERN ANALYSIS
# ------------------------------------------------------------

def calculate_weekday_seasonality(
    dataframe,
    metric="Sales Count",
):
    """
    Compare average recorded demand across weekdays.

    The mean is calculated from observed records grouped
    by calendar date. Missing dates are not treated as
    verified zero-demand dates.
    """

    prepared = prepare_seasonality_data(
        dataframe
    )

    if prepared.empty:
        return pd.DataFrame()

    if metric not in SEASONALITY_METRICS:
        return pd.DataFrame()

    daily = (
        prepared.groupby(
            ["Date", "Weekday_Number", "Weekday"],
            as_index=False,
        )[metric]
        .sum(min_count=1)
    )

    daily = daily.dropna(
        subset=[metric]
    )

    if daily.empty:
        return pd.DataFrame()

    profile = (
        daily.groupby(
            ["Weekday_Number", "Weekday"],
            as_index=False,
        )
        .agg(
            Average_Demand=(metric, "mean"),
            Median_Demand=(metric, "median"),
            Total_Demand=(metric, "sum"),
            Observed_Days=("Date", "nunique"),
        )
    )

    profile["Weekday_Number"] = (
        profile["Weekday_Number"].astype(int)
    )

    profile = profile.sort_values(
        "Weekday_Number"
    ).reset_index(drop=True)

    return profile


# ------------------------------------------------------------
# 14.4 â€” MONTH-OF-YEAR PATTERN ANALYSIS
# ------------------------------------------------------------

def calculate_month_seasonality(
    dataframe,
    metric="Sales Count",
):
    """
    Compare calendar months across all observed years.

    Average monthly demand is calculated only from observed
    calendar months; it is not an estimate of future demand.
    """

    prepared = prepare_seasonality_data(
        dataframe
    )

    if prepared.empty:
        return pd.DataFrame()

    if metric not in SEASONALITY_METRICS:
        return pd.DataFrame()

    monthly = (
        prepared.groupby(
            ["Year", "Month_Number", "Month"],
            as_index=False,
        )[metric]
        .sum(min_count=1)
    )

    monthly = monthly.dropna(
        subset=[metric]
    )

    if monthly.empty:
        return pd.DataFrame()

    profile = (
        monthly.groupby(
            ["Month_Number", "Month"],
            as_index=False,
        )
        .agg(
            Average_Monthly_Demand=(metric, "mean"),
            Median_Monthly_Demand=(metric, "median"),
            Total_Recorded_Demand=(metric, "sum"),
            Observed_Months=(metric, "count"),
        )
    )

    profile = profile.sort_values(
        "Month_Number"
    ).reset_index(drop=True)

    return profile


# ------------------------------------------------------------
# 14.5 â€” WEEK-OF-YEAR PATTERN ANALYSIS
# ------------------------------------------------------------

def calculate_week_of_year_seasonality(
    dataframe,
    metric="Sales Count",
):
    """
    Compare recorded demand across ISO week numbers.

    Results combine observations from different years.
    They should be interpreted as descriptive patterns.
    """

    prepared = prepare_seasonality_data(
        dataframe
    )

    if prepared.empty:
        return pd.DataFrame()

    if metric not in SEASONALITY_METRICS:
        return pd.DataFrame()

    daily = (
        prepared.groupby(
            [
                "Date",
                "Year",
                "Week_of_Year",
            ],
            as_index=False,
        )[metric]
        .sum(min_count=1)
    )

    daily = daily.dropna(
        subset=[metric]
    )

    if daily.empty:
        return pd.DataFrame()

    profile = (
        daily.groupby(
            "Week_of_Year",
            as_index=False,
        )
        .agg(
            Average_Demand=(metric, "mean"),
            Median_Demand=(metric, "median"),
            Total_Demand=(metric, "sum"),
            Observed_Days=("Date", "nunique"),
        )
    )

    profile = profile.sort_values(
        "Week_of_Year"
    ).reset_index(drop=True)

    return profile


# ------------------------------------------------------------
# 14.6 â€” QUARTERLY PATTERN ANALYSIS
# ------------------------------------------------------------

def calculate_quarter_seasonality(
    dataframe,
    metric="Sales Count",
):
    """
    Summarize observed ticket activity by year and quarter.
    """

    prepared = prepare_seasonality_data(
        dataframe
    )

    if prepared.empty:
        return pd.DataFrame()

    if metric not in SEASONALITY_METRICS:
        return pd.DataFrame()

    quarterly = (
        prepared.groupby(
            ["Year", "Quarter"],
            as_index=False,
        )[metric]
        .sum(min_count=1)
    )

    quarterly = quarterly.dropna(
        subset=[metric]
    )

    if quarterly.empty:
        return pd.DataFrame()

    profile = (
        quarterly.groupby(
            "Quarter",
            as_index=False,
        )
        .agg(
            Average_Quarterly_Demand=(metric, "mean"),
            Median_Quarterly_Demand=(metric, "median"),
            Total_Recorded_Demand=(metric, "sum"),
            Observed_Year_Quarters=(metric, "count"),
        )
    )

    profile = profile.sort_values(
        "Quarter"
    ).reset_index(drop=True)

    return profile


# ------------------------------------------------------------
# 14.7 â€” YEAR-OVER-YEAR COMPARISON
# ------------------------------------------------------------

def calculate_yearly_seasonality_comparison(
    dataframe,
    metric="Sales Count",
):
    """
    Calculate total recorded demand by calendar year.
    """

    prepared = prepare_seasonality_data(
        dataframe
    )

    if prepared.empty:
        return pd.DataFrame()

    if metric not in SEASONALITY_METRICS:
        return pd.DataFrame()

    yearly = (
        prepared.groupby(
            "Year",
            as_index=False,
        )[metric]
        .sum(min_count=1)
    )

    yearly = yearly.dropna(
        subset=[metric]
    )

    if yearly.empty:
        return pd.DataFrame()

    yearly = yearly.sort_values(
        "Year"
    ).reset_index(drop=True)

    yearly["Previous_Year_Demand"] = (
        yearly[metric].shift(1)
    )

    yearly["Absolute_Change"] = (
        yearly[metric]
        - yearly["Previous_Year_Demand"]
    )

    previous = yearly[
        "Previous_Year_Demand"
    ]

    yearly["Percentage_Change"] = np.where(
        previous.notna() & previous.ne(0),
        (
            yearly["Absolute_Change"]
            / previous.abs()
        ) * 100,
        np.nan,
    )

    return yearly


# ------------------------------------------------------------
# 14.8 â€” FIND HIGH AND LOW CALENDAR PATTERNS
# ------------------------------------------------------------

def identify_seasonality_extremes(
    profile_dataframe,
    value_column,
    top_n=5,
):
    """
    Return the highest and lowest groups in a seasonal profile.
    """

    if (
        profile_dataframe is None
        or not isinstance(
            profile_dataframe,
            pd.DataFrame,
        )
        or profile_dataframe.empty
    ):
        return {
            "Highest": pd.DataFrame(),
            "Lowest": pd.DataFrame(),
        }

    if value_column not in profile_dataframe.columns:
        return {
            "Highest": pd.DataFrame(),
            "Lowest": pd.DataFrame(),
        }

    result = profile_dataframe.copy()

    result[value_column] = pd.to_numeric(
        result[value_column],
        errors="coerce",
    )

    result = result.dropna(
        subset=[value_column]
    )

    if result.empty:
        return {
            "Highest": pd.DataFrame(),
            "Lowest": pd.DataFrame(),
        }

    top_n = max(
        1,
        min(int(top_n), 100),
    )

    return {
        "Highest": result.nlargest(
            top_n,
            value_column,
        ).reset_index(drop=True),
        "Lowest": result.nsmallest(
            top_n,
            value_column,
        ).reset_index(drop=True),
    }


# ------------------------------------------------------------
# 14.9 â€” CREATE CALENDAR INSIGHT MESSAGES
# ------------------------------------------------------------

def generate_seasonality_insights(
    weekday_profile,
    month_profile,
    quarter_profile,
):
    """
    Generate descriptive observations from available profiles.

    These messages describe historical records; they do not
    claim causal relationships or guarantee future outcomes.
    """

    insights = []

    if (
        isinstance(weekday_profile, pd.DataFrame)
        and not weekday_profile.empty
        and "Average_Demand" in weekday_profile.columns
    ):
        valid_weekdays = weekday_profile.dropna(
            subset=["Average_Demand"]
        )

        if not valid_weekdays.empty:
            highest = valid_weekdays.loc[
                valid_weekdays["Average_Demand"].idxmax()
            ]

            lowest = valid_weekdays.loc[
                valid_weekdays["Average_Demand"].idxmin()
            ]

            insights.append(
                "Highest average recorded demand by weekday: "
                f"{highest['Weekday']} "
                f"({highest['Average_Demand']:,.2f})."
            )

            insights.append(
                "Lowest average recorded demand by weekday: "
                f"{lowest['Weekday']} "
                f"({lowest['Average_Demand']:,.2f})."
            )

    if (
        isinstance(month_profile, pd.DataFrame)
        and not month_profile.empty
        and "Average_Monthly_Demand" in month_profile.columns
    ):
        valid_months = month_profile.dropna(
            subset=["Average_Monthly_Demand"]
        )

        if not valid_months.empty:
            highest_month = valid_months.loc[
                valid_months[
                    "Average_Monthly_Demand"
                ].idxmax()
            ]

            insights.append(
                "Highest average recorded monthly total: "
                f"{highest_month['Month']} "
                f"({highest_month['Average_Monthly_Demand']:,.2f})."
            )

    if (
        isinstance(quarter_profile, pd.DataFrame)
        and not quarter_profile.empty
        and "Average_Quarterly_Demand" in quarter_profile.columns
    ):
        valid_quarters = quarter_profile.dropna(
            subset=["Average_Quarterly_Demand"]
        )

        if not valid_quarters.empty:
            highest_quarter = valid_quarters.loc[
                valid_quarters[
                    "Average_Quarterly_Demand"
                ].idxmax()
            ]

            insights.append(
                "Highest average recorded quarterly total: "
                f"Q{int(highest_quarter['Quarter'])} "
                f"({highest_quarter['Average_Quarterly_Demand']:,.2f})."
            )

    if not insights:
        insights.append(
            "Not enough valid calendar data is available "
            "to generate seasonal observations."
        )

    return insights


