    prepared = prepare_seasonality_data(
        dataframe
    )

    if prepared.empty:
        st.error(
            "The dataset is unavailable or required columns "
            "are missing."
        )
        return

    metric = st.selectbox(
        "Select Ticket Metric",
        options=SEASONALITY_METRICS,
        key="seasonality_metric",
    )

    weekday_profile = calculate_weekday_seasonality(
        prepared,
        metric=metric,
    )

    month_profile = calculate_month_seasonality(
        prepared,
        metric=metric,
    )

    week_profile = calculate_week_of_year_seasonality(
        prepared,
        metric=metric,
    )

    quarter_profile = calculate_quarter_seasonality(
        prepared,
        metric=metric,
    )

    yearly_profile = calculate_yearly_seasonality_comparison(
        prepared,
        metric=metric,
    )

    insights = generate_seasonality_insights(
        weekday_profile,
        month_profile,
        quarter_profile,
    )

    st.divider()

    render_seasonality_weekday_profile(
        weekday_profile
    )

    st.divider()

    render_seasonality_month_profile(
        month_profile
    )

    st.divider()

    render_seasonality_week_profile(
        week_profile
    )

    st.divider()

    render_seasonality_quarter_profile(
        quarter_profile
    )

    st.divider()

    render_seasonality_yearly_comparison(
        yearly_profile,
        metric,
    )

    st.divider()

    render_seasonality_insight_messages(
        insights
    )

    st.divider()

    render_seasonality_exports(
        weekday_profile,
        month_profile,
        week_profile,
        quarter_profile,
        yearly_profile,
    )


