# ============================================================
# PART 15 â€” DATA QUALITY & FORECAST READINESS INTELLIGENCE
# ============================================================

FORECAST_READINESS_VERSION = "1.0.0"

READINESS_REQUIRED_COLUMNS = [
    "Timestamp",
    "Sales Count",
    "Redemption Count",
]

READINESS_NUMERIC_COLUMNS = [
    "Sales Count",
    "Redemption Count",
]

READINESS_DUPLICATE_CHECK_COLUMNS = [
    "Timestamp",
    "Sales Count",
    "Redemption Count",
]

READINESS_MINIMUM_RECORDS = 30
READINESS_MINIMUM_DISTINCT_DATES = 14
READINESS_HIGH_MISSING_PERCENTAGE = 10.0


# ------------------------------------------------------------
# 15.1 â€” PREPARE RAW DATA FOR QUALITY CHECKS
# ------------------------------------------------------------

def prepare_readiness_data(dataframe):
    """
    Prepare a copy of the raw dataset without silently
    dropping invalid rows from the quality assessment.

    Original rows are retained so quality problems remain
    measurable.
    """

    if not isinstance(dataframe, pd.DataFrame):
        return pd.DataFrame()

    prepared = dataframe.copy()

    if "Timestamp" in prepared.columns:
        prepared["Timestamp"] = pd.to_datetime(
            prepared["Timestamp"],
            errors="coerce",
        )

    for column in READINESS_NUMERIC_COLUMNS:
        if column in prepared.columns:
            prepared[column] = pd.to_numeric(
                prepared[column],
                errors="coerce",
            )

    return prepared


# ------------------------------------------------------------
# 15.2 â€” CHECK REQUIRED COLUMNS
# ------------------------------------------------------------

def calculate_readiness_column_check(dataframe):
    """
    Identify required columns that are present or missing.
    """

    if not isinstance(dataframe, pd.DataFrame):
        dataframe = pd.DataFrame()

    records = []

    for column in READINESS_REQUIRED_COLUMNS:
        exists = column in dataframe.columns

        records.append(
            {
                "Column": column,
                "Present": exists,
                "Status": (
                    "PASS"
                    if exists
                    else "FAIL"
                ),
            }
        )

    return pd.DataFrame(records)


# ------------------------------------------------------------
# 15.3 â€” CALCULATE MISSING VALUES
# ------------------------------------------------------------

def calculate_readiness_missing_values(dataframe):
    """
    Calculate missing values and missing percentages
    for every original column.
    """

    if not isinstance(dataframe, pd.DataFrame):
        return pd.DataFrame()

    total_rows = len(dataframe)

    records = []

    for column in dataframe.columns:
        missing_count = int(
            dataframe[column].isna().sum()
        )

        missing_percentage = (
            missing_count / total_rows * 100
            if total_rows
            else 0.0
        )

        if missing_count == 0:
            status = "PASS"
        elif (
            missing_percentage
            >= READINESS_HIGH_MISSING_PERCENTAGE
        ):
            status = "REVIEW"
        else:
            status = "WARNING"

        records.append(
            {
                "Column": str(column),
                "Missing Values": missing_count,
                "Missing Percentage": (
                    round(missing_percentage, 2)
                ),
                "Status": status,
            }
        )

    return pd.DataFrame(records)


# ------------------------------------------------------------
# 15.4 â€” CHECK INVALID TIMESTAMPS
# ------------------------------------------------------------

def calculate_readiness_timestamp_quality(dataframe):
    """
    Check timestamp parsing and distinct calendar coverage.
    """

    if not isinstance(dataframe, pd.DataFrame):
        return {
            "Total Records": 0,
            "Valid Timestamps": 0,
            "Invalid Timestamps": 0,
            "Distinct Dates": 0,
            "Coverage Start": None,
            "Coverage End": None,
            "Timestamp Validity Percentage": 0.0,
        }

    total_rows = len(dataframe)

    if "Timestamp" not in dataframe.columns:
        return {
            "Total Records": total_rows,
            "Valid Timestamps": 0,
            "Invalid Timestamps": total_rows,
            "Distinct Dates": 0,
            "Coverage Start": None,
            "Coverage End": None,
            "Timestamp Validity Percentage": 0.0,
        }

    parsed = pd.to_datetime(
        dataframe["Timestamp"],
        errors="coerce",
    )

    valid = parsed.dropna()

    valid_count = int(
        parsed.notna().sum()
    )

    invalid_count = int(
        parsed.isna().sum()
    )

    distinct_dates = int(
        valid.dt.normalize().nunique()
    )

    return {
        "Total Records": total_rows,
        "Valid Timestamps": valid_count,
        "Invalid Timestamps": invalid_count,
        "Distinct Dates": distinct_dates,
        "Coverage Start": (
            valid.min()
            if not valid.empty
            else None
        ),
        "Coverage End": (
            valid.max()
            if not valid.empty
            else None
        ),
        "Timestamp Validity Percentage": (
            round(
                valid_count / total_rows * 100,
                2,
            )
            if total_rows
            else 0.0
        ),
    }


# ------------------------------------------------------------
# 15.5 â€” CHECK NEGATIVE AND NON-FINITE COUNTS
# ------------------------------------------------------------

def calculate_readiness_numeric_quality(dataframe):
    """
    Summarize invalid values in sales and redemption counts.

    Negative counts are flagged for review rather than
    automatically deleted.
    """

    if not isinstance(dataframe, pd.DataFrame):
        return pd.DataFrame()

    records = []

    for column in READINESS_NUMERIC_COLUMNS:
        if column not in dataframe.columns:
            records.append(
                {
                    "Column": column,
                    "Missing Or Invalid": len(dataframe),
                    "Negative Values": 0,
                    "Zero Values": 0,
                    "Valid Numeric Values": 0,
                    "Status": "FAIL",
                }
            )
            continue

        raw = dataframe[column]

        numeric = pd.to_numeric(
            raw,
            errors="coerce",
        )

        finite_mask = (
            numeric.notna()
            & np.isfinite(
                numeric.fillna(0)
            )
        )

        negative_count = int(
            (
                finite_mask
                & numeric.lt(0)
            ).sum()
        )

        zero_count = int(
            (
                finite_mask
                & numeric.eq(0)
            ).sum()
        )

        valid_count = int(
            finite_mask.sum()
        )

        invalid_count = int(
            len(dataframe) - valid_count
        )

        if invalid_count > 0 or negative_count > 0:
            status = "REVIEW"
        else:
            status = "PASS"

        records.append(
            {
                "Column": column,
                "Missing Or Invalid": invalid_count,
                "Negative Values": negative_count,
                "Zero Values": zero_count,
                "Valid Numeric Values": valid_count,
                "Status": status,
            }
        )

    return pd.DataFrame(records)


# ------------------------------------------------------------
# 15.6 â€” CHECK DUPLICATE RECORDS
# ------------------------------------------------------------

def calculate_readiness_duplicate_summary(dataframe):
    """
    Count exact duplicate rows and duplicates among
    available timestamp and demand fields.
    """

    if not isinstance(dataframe, pd.DataFrame):
        return {
            "Total Records": 0,
            "Exact Duplicate Rows": 0,
            "Duplicate Key Rows": 0,
            "Exact Duplicate Percentage": 0.0,
        }

    total_rows = len(dataframe)

    exact_duplicates = int(
        dataframe.duplicated().sum()
    )

    available_keys = [
        column
        for column in READINESS_DUPLICATE_CHECK_COLUMNS
        if column in dataframe.columns
    ]

    if available_keys:
        duplicate_key_rows = int(
            dataframe.duplicated(
                subset=available_keys
            ).sum()
        )
    else:
        duplicate_key_rows = 0

    return {
        "Total Records": total_rows,
        "Exact Duplicate Rows": exact_duplicates,
        "Duplicate Key Rows": duplicate_key_rows,
        "Exact Duplicate Percentage": (
            round(
                exact_duplicates / total_rows * 100,
                2,
            )
            if total_rows
            else 0.0
        ),
    }


# ------------------------------------------------------------
# 15.7 â€” CHECK TIME GAPS
# ------------------------------------------------------------

def calculate_readiness_time_gaps(dataframe):
    """
    Summarize gaps between consecutive observed calendar dates.

    A gap indicates no record on an intervening date;
    it does not prove that actual demand was zero.
    """

    if (
        not isinstance(dataframe, pd.DataFrame)
        or "Timestamp" not in dataframe.columns
    ):
        return {
            "Distinct Dates": 0,
            "Gap Count": 0,
            "Largest Gap Days": 0,
            "Median Gap Days": np.nan,
            "Gap Details": pd.DataFrame(),
        }

    timestamps = pd.to_datetime(
        dataframe["Timestamp"],
        errors="coerce",
    ).dropna()

    distinct_dates = (
        timestamps.dt.normalize()
        .drop_duplicates()
        .sort_values()
    )

    if len(distinct_dates) < 2:
        return {
            "Distinct Dates": int(
                len(distinct_dates)
            ),
            "Gap Count": 0,
            "Largest Gap Days": 0,
            "Median Gap Days": np.nan,
            "Gap Details": pd.DataFrame(),
        }

    gaps = distinct_dates.diff().dt.days

    gap_details = pd.DataFrame(
        {
            "Date": distinct_dates.to_numpy(),
            "Days Since Previous Date": (
                gaps.to_numpy()
            ),
        }
    )

    gap_details = gap_details[
        gap_details[
            "Days Since Previous Date"
        ] > 1
    ].copy()

    gap_details["Missing Calendar Days"] = (
        gap_details[
            "Days Since Previous Date"
        ] - 1
    )

    gap_count = int(
        len(gap_details)
    )

    largest_gap = (
        int(
            gap_details[
                "Missing Calendar Days"
            ].max()
        )
        if gap_count
        else 0
    )

    median_gap = float(
        gaps.median()
    )

    return {
        "Distinct Dates": int(
            len(distinct_dates)
        ),
        "Gap Count": gap_count,
        "Largest Gap Days": largest_gap,
        "Median Gap Days": median_gap,
        "Gap Details": gap_details.reset_index(
            drop=True
        ),
    }


# ------------------------------------------------------------
# 15.8 â€” CHECK OBSERVATION SUFFICIENCY
# ------------------------------------------------------------

def calculate_readiness_sample_check(dataframe):
    """
    Assess record and distinct-date sufficiency using
    simple configurable thresholds.
    """

    if not isinstance(dataframe, pd.DataFrame):
        dataframe = pd.DataFrame()

    total_records = len(dataframe)

    timestamp_summary = (
        calculate_readiness_timestamp_quality(
            dataframe
        )
    )

    distinct_dates = timestamp_summary[
        "Distinct Dates"
    ]

    record_sufficient = (
        total_records >= READINESS_MINIMUM_RECORDS
    )

    date_sufficient = (
        distinct_dates
        >= READINESS_MINIMUM_DISTINCT_DATES
    )

    return {
        "Total Records": total_records,
        "Distinct Dates": distinct_dates,
        "Minimum Record Threshold": (
            READINESS_MINIMUM_RECORDS
        ),
        "Minimum Date Threshold": (
            READINESS_MINIMUM_DISTINCT_DATES
        ),
        "Record Sufficiency": (
            "PASS"
            if record_sufficient
            else "REVIEW"
        ),
        "Date Sufficiency": (
            "PASS"
            if date_sufficient
            else "REVIEW"
        ),
        "Basic Sample Readiness": (
            "PASS"
            if record_sufficient and date_sufficient
            else "REVIEW"
        ),
    }


# ------------------------------------------------------------
# 15.9 â€” BUILD QUALITY SCORECARD
# ------------------------------------------------------------

def build_forecast_readiness_scorecard(dataframe):
    """
    Calculate a transparent heuristic data-quality score.

    The score is a diagnostic indicator, not a statistical
    guarantee that a forecasting model will perform well.
    """

    if not isinstance(dataframe, pd.DataFrame):
        dataframe = pd.DataFrame()

    total_rows = len(dataframe)

    column_check = (
        calculate_readiness_column_check(
            dataframe
        )
    )

    missing_summary = (
        calculate_readiness_missing_values(
            dataframe
        )
    )

    timestamp_summary = (
        calculate_readiness_timestamp_quality(
            dataframe
        )
    )

    numeric_summary = (
        calculate_readiness_numeric_quality(
            dataframe
        )
    )

    duplicate_summary = (
        calculate_readiness_duplicate_summary(
            dataframe
        )
    )

    sample_summary = (
        calculate_readiness_sample_check(
            dataframe
        )
    )

    required_columns_present = bool(
        column_check["Present"].all()
    )

    missing_percentage = (
        missing_summary[
            "Missing Percentage"
        ].mean()
        if not missing_summary.empty
        else 100.0
    )

    timestamp_score = (
        timestamp_summary[
            "Timestamp Validity Percentage"
        ]
    )

    duplicate_percentage = (
        duplicate_summary[
            "Exact Duplicate Percentage"
        ]
    )

    numeric_invalid_count = (
        int(
            numeric_summary[
                "Missing Or Invalid"
            ].sum()
        )
        if not numeric_summary.empty
        else total_rows * len(
            READINESS_NUMERIC_COLUMNS
        )
    )

    numeric_negative_count = (
        int(
            numeric_summary[
                "Negative Values"
            ].sum()
        )
        if not numeric_summary.empty
        else 0
    )

    expected_numeric_values = (
        total_rows
        * len(READINESS_NUMERIC_COLUMNS)
    )

    numeric_valid_percentage = (
        max(
            0.0,
            100.0
            * (
                1
                - numeric_invalid_count
                / expected_numeric_values
            ),
        )
        if expected_numeric_values
        else 0.0
    )

    score = (
        0.30 * timestamp_score
        + 0.30 * numeric_valid_percentage
        + 0.20 * max(
            0.0,
            100.0 - float(
                missing_percentage
            ),
        )
        + 0.20 * max(
            0.0,
            100.0 - duplicate_percentage,
        )
    )

    if not required_columns_present:
        score = min(
            score,
            49.0,
        )

    if total_rows == 0:
        score = 0.0

    if score >= 90:
        readiness_label = "Strong Basic Data Quality"
    elif score >= 75:
        readiness_label = "Generally Usable â€” Review Issues"
    elif score >= 50:
        readiness_label = "Needs Data Cleaning"
    else:
        readiness_label = "Insufficient Data Quality"

    if (
        numeric_negative_count > 0
        or sample_summary[
            "Basic Sample Readiness"
        ] != "PASS"
    ):
        readiness_label += " / Additional Review Needed"

    return {
        "Heuristic Score": round(
            float(score),
            2,
        ),
        "Readiness Label": readiness_label,
        "Required Columns Present": (
            required_columns_present
        ),
        "Missing Percentage Average": round(
            float(missing_percentage),
            2,
        ),
        "Timestamp Validity Percentage": (
            timestamp_score
        ),
        "Numeric Validity Percentage": round(
            float(numeric_valid_percentage),
            2,
        ),
        "Exact Duplicate Percentage": (
            duplicate_percentage
        ),
        "Negative Demand Values": (
            numeric_negative_count
        ),
        "Sample Readiness": sample_summary[
            "Basic Sample Readiness"
        ],
    }


# ------------------------------------------------------------
# 15.10 â€” GENERATE DATA QUALITY RECOMMENDATIONS
# ------------------------------------------------------------

def generate_readiness_recommendations(
    dataframe,
    scorecard,
    timestamp_summary,
    numeric_summary,
    duplicate_summary,
    gap_summary,
):
    """
    Generate recommendations based on observed quality checks.
    """

    recommendations = []

    if not scorecard[
        "Required Columns Present"
    ]:
        recommendations.append(
            "Restore or map missing required columns "
            "before running downstream analysis."
        )

    if timestamp_summary[
        "Invalid Timestamps"
    ] > 0:
        recommendations.append(
            "Review invalid timestamps and determine "
            "whether they can be corrected from the source."
        )

    if (
        scorecard[
            "Numeric Validity Percentage"
        ] < 100
    ):
        recommendations.append(
            "Review missing or non-numeric sales and "
            "redemption counts before model training."
        )

    if scorecard[
        "Negative Demand Values"
    ] > 0:
        recommendations.append(
            "Investigate negative ticket counts. "
            "Do not remove them without understanding "
            "whether they represent legitimate corrections."
        )

    if duplicate_summary[
        "Exact Duplicate Rows"
    ] > 0:
        recommendations.append(
            "Inspect exact duplicate records and confirm "
            "whether they are duplicate ingestion or "
            "legitimate repeated transactions."
        )

    if gap_summary[
        "Gap Count"
    ] > 0:
        recommendations.append(
            "Review dates without records. A missing date "
            "does not necessarily mean zero ticket demand."
        )

    if scorecard[
        "Sample Readiness"
    ] != "PASS":
        recommendations.append(
            "Collect or verify a sufficiently long historical "
            "period before relying on time-series evaluation."
        )

    if not recommendations:
        recommendations.append(
            "No major issue was identified by these basic "
            "checks. Continue with chronological train/test "
            "validation and baseline model comparison."
        )

    return recommendations


# ------------------------------------------------------------
# 15.11 â€” BUILD FULL READINESS REPORT
# ------------------------------------------------------------

def build_forecast_readiness_report(dataframe):
    """
    Build all data quality outputs in one result dictionary.
    """

    prepared = prepare_readiness_data(
        dataframe
    )

    if prepared.empty:
        empty = pd.DataFrame()

        return {
            "Status": "Unavailable",
            "Prepared Data": prepared,
            "Column Check": empty,
            "Missing Values": empty,
            "Numeric Quality": empty,
            "Timestamp Summary": {},
            "Duplicate Summary": {},
            "Gap Summary": {},
            "Sample Summary": {},
            "Scorecard": {},
            "Recommendations": [
                "Load a dataset with the required columns."
            ],
        }

    column_check = (
        calculate_readiness_column_check(
            prepared
        )
    )

    missing_summary = (
        calculate_readiness_missing_values(
            prepared
        )
    )

    numeric_summary = (
        calculate_readiness_numeric_quality(
            prepared
        )
    )

    timestamp_summary = (
        calculate_readiness_timestamp_quality(
            prepared
        )
    )

    duplicate_summary = (
        calculate_readiness_duplicate_summary(
            prepared
        )
    )

    gap_summary = (
        calculate_readiness_time_gaps(
            prepared
        )
    )

    sample_summary = (
        calculate_readiness_sample_check(
            prepared
        )
    )

    scorecard = (
        build_forecast_readiness_scorecard(
            prepared
        )
    )

    recommendations = (
        generate_readiness_recommendations(
            prepared,
            scorecard,
            timestamp_summary,
            numeric_summary,
            duplicate_summary,
            gap_summary,
        )
    )

    return {
        "Status": "Available",
        "Prepared Data": prepared,
        "Column Check": column_check,
        "Missing Values": missing_summary,
        "Numeric Quality": numeric_summary,
        "Timestamp Summary": timestamp_summary,
        "Duplicate Summary": duplicate_summary,
        "Gap Summary": gap_summary,
        "Sample Summary": sample_summary,
        "Scorecard": scorecard,
        "Recommendations": recommendations,
    }


