# ============================================================
# PART 16 â€” FORECAST EXPLAINABILITY & DECISION INTELLIGENCE
# ============================================================

FORECAST_EXPLAINABILITY_VERSION = "1.0.0"

EXPLAINABILITY_REQUIRED_COLUMNS = [
    "Actual",
    "Predicted",
]

EXPLAINABILITY_DATE_CANDIDATES = [
    "Timestamp",
    "Date",
    "Period",
    "ds",
]

EXPLAINABILITY_ACTUAL_CANDIDATES = [
    "Actual",
    "Actual Demand",
    "Actual Sales",
    "Actual Value",
    "y_true",
    "y",
]

EXPLAINABILITY_PREDICTED_CANDIDATES = [
    "Predicted",
    "Predicted Demand",
    "Forecast",
    "Forecast Demand",
    "Predicted Value",
    "y_pred",
    "yhat",
]


# ------------------------------------------------------------
# 16.1 â€” NORMALIZE COLUMN NAMES
# ------------------------------------------------------------

def normalize_explainability_column_name(column_name):
    """
    Normalize a column label for flexible matching.
    """

    text_value = str(column_name).strip().lower()

    normalized = "".join(
        character
        if character.isalnum()
        else "_"
        for character in text_value
    )

    while "__" in normalized:
        normalized = normalized.replace(
            "__",
            "_",
        )

    return normalized.strip("_")


# ------------------------------------------------------------
# 16.2 â€” FIND A MATCHING COLUMN
# ------------------------------------------------------------

def find_explainability_column(
    dataframe,
    candidates,
):
    """
    Find the first matching candidate column.
    """

    if not isinstance(dataframe, pd.DataFrame):
        return None

    normalized_lookup = {
        normalize_explainability_column_name(column): column
        for column in dataframe.columns
    }

    for candidate in candidates:
        normalized_candidate = (
            normalize_explainability_column_name(
                candidate
            )
        )

        if normalized_candidate in normalized_lookup:
            return normalized_lookup[
                normalized_candidate
            ]

    return None


# ------------------------------------------------------------
# 16.3 â€” PREPARE ACTUAL AND PREDICTED DATA
# ------------------------------------------------------------

def prepare_explainability_data(
    dataframe,
    date_column=None,
    actual_column=None,
    predicted_column=None,
):
    """
    Standardize the input for forecast error analysis.

    Only observed actual and predicted values are compared.
    """

    if not isinstance(dataframe, pd.DataFrame):
        return pd.DataFrame()

    if dataframe.empty:
        return pd.DataFrame()

    if actual_column is None:
        actual_column = find_explainability_column(
            dataframe,
            EXPLAINABILITY_ACTUAL_CANDIDATES,
        )

    if predicted_column is None:
        predicted_column = find_explainability_column(
            dataframe,
            EXPLAINABILITY_PREDICTED_CANDIDATES,
        )

    if (
        actual_column not in dataframe.columns
        or predicted_column not in dataframe.columns
    ):
        return pd.DataFrame()

    if date_column is None:
        date_column = find_explainability_column(
            dataframe,
            EXPLAINABILITY_DATE_CANDIDATES,
        )

    selected_columns = [
        actual_column,
        predicted_column,
    ]

    if (
        date_column is not None
        and date_column in dataframe.columns
        and date_column not in selected_columns
    ):
        selected_columns.insert(
            0,
            date_column,
        )

    result = dataframe[
        selected_columns
    ].copy()

    rename_mapping = {
        actual_column: "Actual",
        predicted_column: "Predicted",
    }

    if date_column is not None:
        rename_mapping[date_column] = "Timestamp"

    result = result.rename(
        columns=rename_mapping
    )

    result["Actual"] = pd.to_numeric(
        result["Actual"],
        errors="coerce",
    )

    result["Predicted"] = pd.to_numeric(
        result["Predicted"],
        errors="coerce",
    )

    result["Actual"] = result[
        "Actual"
    ].replace(
        [np.inf, -np.inf],
        np.nan,
    )

    result["Predicted"] = result[
        "Predicted"
    ].replace(
        [np.inf, -np.inf],
        np.nan,
    )

    result = result.dropna(
        subset=[
            "Actual",
            "Predicted",
        ]
    )

    if "Timestamp" in result.columns:
        result["Timestamp"] = pd.to_datetime(
            result["Timestamp"],
            errors="coerce",
        )

        result = result.sort_values(
            "Timestamp",
            na_position="last",
        )

    result = result.reset_index(
        drop=True
    )

    return result


# ------------------------------------------------------------
# 16.4 â€” CALCULATE ERROR METRICS
# ------------------------------------------------------------

def calculate_explainability_metrics(
    dataframe,
):
    """
    Calculate common error metrics from actual/predicted pairs.
    """

    prepared = prepare_explainability_data(
        dataframe
    )

    if prepared.empty:
        return {
            "Status": "Unavailable",
            "Observation Count": 0,
            "MAE": np.nan,
            "RMSE": np.nan,
            "WAPE Percentage": np.nan,
            "Mean Error": np.nan,
            "Overprediction Count": 0,
            "Underprediction Count": 0,
            "Exact Match Count": 0,
        }

    actual = prepared[
        "Actual"
    ].to_numpy(dtype=float)

    predicted = prepared[
        "Predicted"
    ].to_numpy(dtype=float)

    errors = predicted - actual

    absolute_errors = np.abs(
        errors
    )

    mae = float(
        np.mean(absolute_errors)
    )

    rmse = float(
        np.sqrt(
            np.mean(errors ** 2)
        )
    )

    actual_absolute_sum = float(
        np.sum(np.abs(actual))
    )

    wape = (
        float(
            np.sum(absolute_errors)
            / actual_absolute_sum
            * 100
        )
        if actual_absolute_sum > 0
        else np.nan
    )

    return {
        "Status": "Available",
        "Observation Count": int(
            len(prepared)
        ),
        "MAE": mae,
        "RMSE": rmse,
        "WAPE Percentage": wape,
        "Mean Error": float(
            np.mean(errors)
        ),
        "Overprediction Count": int(
            np.sum(errors > 0)
        ),
        "Underprediction Count": int(
            np.sum(errors < 0)
        ),
        "Exact Match Count": int(
            np.sum(
                np.isclose(
                    actual,
                    predicted,
                )
            )
        ),
    }


# ------------------------------------------------------------
# 16.5 â€” CREATE ROW-LEVEL ERROR EXPLANATIONS
# ------------------------------------------------------------

def build_explainability_error_table(
    dataframe,
):
    """
    Add error direction and magnitude to each prediction.
    """

    prepared = prepare_explainability_data(
        dataframe
    )

    if prepared.empty:
        return pd.DataFrame()

    result = prepared.copy()

    result["Error"] = (
        result["Predicted"]
        - result["Actual"]
    )

    result["Absolute Error"] = (
        result["Error"].abs()
    )

    result["Absolute Percentage Error"] = np.where(
        result["Actual"].abs() > 0,
        (
            result["Absolute Error"]
            / result["Actual"].abs()
        ) * 100,
        np.nan,
    )

    result["Error Direction"] = np.select(
        [
            result["Error"] > 0,
            result["Error"] < 0,
        ],
        [
            "Overprediction",
            "Underprediction",
        ],
        default="Exact Match",
    )

    result["Error Severity"] = np.select(
        [
            result["Absolute Error"] == 0,
            result["Absolute Error"] > 0,
        ],
        [
            "No Error",
            "Error Present",
        ],
        default="Unknown",
    )

    return result


# ------------------------------------------------------------
# 16.6 â€” SUMMARIZE ERROR DIRECTION
# ------------------------------------------------------------

def summarize_explainability_error_direction(
    error_table,
):
    """
    Summarize how often predictions are above or below actuals.
    """

    if (
        not isinstance(error_table, pd.DataFrame)
        or error_table.empty
        or "Error Direction" not in error_table.columns
    ):
        return pd.DataFrame(
            columns=[
                "Error Direction",
                "Count",
                "Percentage",
            ]
        )

    counts = (
        error_table["Error Direction"]
        .value_counts()
        .rename_axis("Error Direction")
        .reset_index(name="Count")
    )

    total = int(
        counts["Count"].sum()
    )

    counts["Percentage"] = (
        counts["Count"] / total * 100
        if total
        else 0.0
    )

    return counts


# ------------------------------------------------------------
# 16.7 â€” SUMMARIZE ERROR BY TIME PERIOD
# ------------------------------------------------------------

def summarize_explainability_errors_by_period(
    error_table,
    frequency="Monthly",
):
    """
    Aggregate prediction errors by day, week, or month.
    """

    if (
        not isinstance(error_table, pd.DataFrame)
        or error_table.empty
        or "Timestamp" not in error_table.columns
    ):
        return pd.DataFrame()

    if "Absolute Error" not in error_table.columns:
        return pd.DataFrame()

    frequency_mapping = {
        "Daily": "D",
        "Weekly": "W-SUN",
        "Monthly": "MS",
    }

    if frequency not in frequency_mapping:
        frequency = "Monthly"

    prepared = error_table.dropna(
        subset=["Timestamp"]
    ).copy()

    if prepared.empty:
        return pd.DataFrame()

    prepared = prepared.set_index(
        "Timestamp"
    )

    summary = prepared.resample(
        frequency_mapping[frequency]
    ).agg(
        Actual_Total=("Actual", "sum"),
        Predicted_Total=("Predicted", "sum"),
        Mean_Absolute_Error=("Absolute Error", "mean"),
        Total_Absolute_Error=("Absolute Error", "sum"),
        Observation_Count=("Absolute Error", "count"),
    )

    summary = summary.dropna(
        how="all"
    )

    summary["Net_Error"] = (
        summary["Predicted_Total"]
        - summary["Actual_Total"]
    )

    return summary.reset_index()


# ------------------------------------------------------------
# 16.8 â€” FIND LARGEST ERRORS
# ------------------------------------------------------------

def find_largest_explainability_errors(
    error_table,
    top_n=20,
):
    """
    Return observations with the largest absolute errors.
    """

    if (
        not isinstance(error_table, pd.DataFrame)
        or error_table.empty
        or "Absolute Error" not in error_table.columns
    ):
        return pd.DataFrame()

    top_n = max(
        1,
        min(
            int(top_n),
            500,
        ),
    )

    return error_table.nlargest(
        top_n,
        "Absolute Error",
    ).reset_index(drop=True)


# ------------------------------------------------------------
# 16.9 â€” GENERATE ERROR INTERPRETATION
# ------------------------------------------------------------

def generate_explainability_interpretation(
    metrics,
):
    """
    Generate cautious interpretations from error metrics.
    """

    messages = []

    if metrics.get("Status") != "Available":
        return [
            "Actual and predicted values are required "
            "before error interpretation can be generated."
        ]

    observation_count = metrics[
        "Observation Count"
    ]

    messages.append(
        f"Evaluation uses {observation_count:,} valid "
        "actual/predicted observation pairs."
    )

    mae = metrics["MAE"]

    messages.append(
        f"MAE is {mae:,.3f} in the same units as the target. "
        "Its practical significance depends on the scale "
        "of the recorded ticket counts."
    )

    mean_error = metrics["Mean Error"]

    if mean_error > 0:
        messages.append(
            "Predictions are higher than actual values on "
            "average, indicating average overprediction."
        )
    elif mean_error < 0:
        messages.append(
            "Predictions are lower than actual values on "
            "average, indicating average underprediction."
        )
    else:
        messages.append(
            "The mean signed error is approximately zero. "
            "This does not mean every prediction is accurate."
        )

    wape = metrics["WAPE Percentage"]

    if np.isfinite(wape):
        messages.append(
            f"WAPE is {wape:,.2f}%. Compare this with "
            "baseline models and use a chronological "
            "holdout set for a fair assessment."
        )
    else:
        messages.append(
            "WAPE is unavailable because the sum of the "
            "absolute actual values is zero."
        )

    messages.append(
        "These metrics describe prediction errors; they do "
        "not explain which input feature caused an error."
    )

    return messages


