# ------------------------------------------------------------
# 16.17 â€” MAIN EXPLAINABILITY PAGE
# ------------------------------------------------------------

def render_forecast_explainability_center():
    """
    Main page for actual-versus-predicted error analysis.
    """

    st.title(
        "Forecast Explainability & Decision Intelligence"
    )

    st.write(
        "Compare actual and predicted ticket counts, "
        "inspect error direction, and locate large errors."
    )

    st.warning(
        "This module explains prediction errors, not the "
        "internal reasoning of a trained model. Feature "
        "importance and causal explanations require additional "
        "model-specific data and validation."
    )

    uploaded_file = st.file_uploader(
        "Upload actual and predicted values (CSV)",
        type=["csv"],
        key="explainability_upload",
        help=(
            "Provide columns such as Timestamp, Actual, "
            "and Predicted. Column selection is available below."
        ),
    )

    if uploaded_file is None:
        st.info(
            "Upload a CSV containing actual and predicted "
            "values to begin the analysis."
        )
        return

    try:
        uploaded_data = pd.read_csv(
            uploaded_file
        )
    except Exception as error:
        st.error(
            f"Unable to read the uploaded CSV: {error}"
        )
        return

    if uploaded_data.empty:
        st.warning(
            "The uploaded CSV contains no data rows."
        )
        return

    st.subheader(
        "Select Columns"
    )

    all_columns = list(
        uploaded_data.columns
    )

    suggested_actual = (
        find_explainability_column(
            uploaded_data,
            EXPLAINABILITY_ACTUAL_CANDIDATES,
        )
    )

    suggested_predicted = (
        find_explainability_column(
            uploaded_data,
            EXPLAINABILITY_PREDICTED_CANDIDATES,
        )
    )

    suggested_date = (
        find_explainability_column(
            uploaded_data,
            EXPLAINABILITY_DATE_CANDIDATES,
        )
    )

    actual_default = (
        all_columns.index(suggested_actual)
        if suggested_actual in all_columns
        else 0
    )

    predicted_default = (
        all_columns.index(suggested_predicted)
        if suggested_predicted in all_columns
        else min(
            1,
            len(all_columns) - 1,
        )
    )

    date_options = [
        "No date column"
    ] + all_columns

    date_default = (
        date_options.index(suggested_date)
        if suggested_date in all_columns
        else 0
    )

    col1, col2 = st.columns(2)

    with col1:
        actual_column = st.selectbox(
            "Actual Values Column",
            options=all_columns,
            index=actual_default,
            key="explainability_actual_column",
        )

    with col2:
        predicted_column = st.selectbox(
            "Predicted Values Column",
            options=all_columns,
            index=predicted_default,
            key="explainability_predicted_column",
        )

    date_column_selection = st.selectbox(
        "Date Column (Optional)",
        options=date_options,
        index=date_default,
        key="explainability_date_column",
    )

    date_column = (
        None
        if date_column_selection == "No date column"
        else date_column_selection
    )

    if actual_column == predicted_column:
        st.error(
            "Actual and predicted columns must be different."
        )
        return

    prepared = prepare_explainability_data(
        uploaded_data,
        date_column=date_column,
        actual_column=actual_column,
        predicted_column=predicted_column,
    )

    if prepared.empty:
        st.error(
            "No valid actual/predicted pairs were found. "
            "Check the selected columns and numeric values."
        )
        return

    metrics = calculate_explainability_metrics(
        prepared
    )

    error_table = build_explainability_error_table(
        prepared
    )

    direction_summary = (
        summarize_explainability_error_direction(
            error_table
        )
    )

    st.divider()

    render_explainability_metrics(
        metrics
    )

    st.divider()

    render_explainability_actual_predicted(
        prepared
    )

    st.divider()

    render_explainability_error_direction(
        direction_summary
    )

    st.divider()

    render_explainability_periodic_errors(
        error_table
    )

    st.divider()

    render_explainability_largest_errors(
        error_table
    )

    st.divider()

    render_explainability_interpretation(
        metrics
    )

    st.divider()

    render_explainability_export(
        error_table
    )


