PIPELINE_MANAGER_VERSION = "1.0.0"

PIPELINE_RUN_HISTORY_PATH = (
    OUTPUT_DIR / "pipeline_run_history.csv"
)

PIPELINE_DEFAULT_TIMEOUT_SECONDS = 1800

PIPELINE_MAX_TIMEOUT_SECONDS = 7200

PIPELINE_SCRIPT_CANDIDATES = [
    "forecasting_engine.py",
    "baseline_models.py",
    "forecasting_models.py",
]

PIPELINE_ARTIFACT_DIRECTORIES = [
    OUTPUT_DIR,
    FORECAST_DIR,
    REPORT_DIR,
]


# ------------------------------------------------------------
# 17.1 â€” ENSURE PIPELINE OUTPUT DIRECTORIES
# ------------------------------------------------------------

def ensure_pipeline_manager_directories():
    """
    Create the output directories used by the run manager.
    """

    directories = [
        OUTPUT_DIR,
        FORECAST_DIR,
        REPORT_DIR,
        LOG_DIR,
    ]

    for directory in directories:
        Path(directory).mkdir(
            parents=True,
            exist_ok=True,
        )


# ------------------------------------------------------------
# 17.2 â€” DISCOVER PYTHON SCRIPTS
# ------------------------------------------------------------

def discover_pipeline_scripts():
    """
    Find existing candidate scripts in the project directory.

    Discovery does not prove that a script is executable
    as a standalone pipeline.
    """

    discovered = []

    for filename in PIPELINE_SCRIPT_CANDIDATES:
        script_path = BASE_DIR / filename

        if script_path.is_file():
            discovered.append(
                {
                    "Script": filename,
                    "Path": str(script_path),
                    "Exists": True,
                    "Standalone Execution Verified": False,
                }
            )

    return pd.DataFrame(discovered)


# ------------------------------------------------------------
# 17.3 â€” INVENTORY OUTPUT ARTIFACTS
# ------------------------------------------------------------

def inventory_pipeline_artifacts():
    """
    Build an inventory of existing files in project outputs.
    """

    records = []

    directories = [
        BASE_DIR / "outputs",
        BASE_DIR / "output",
        BASE_DIR / "forecasts",
        BASE_DIR / "reports",
    ]

    seen_paths = set()

    for directory in directories:
        if not directory.exists():
            continue

        try:
            files = directory.rglob("*")

            for file_path in files:
                if not file_path.is_file():
                    continue

                resolved_path = str(
                    file_path.resolve()
                )

                if resolved_path in seen_paths:
                    continue

                seen_paths.add(
                    resolved_path
                )

                try:
                    stat = file_path.stat()

                    records.append(
                        {
                            "Artifact": file_path.name,
                            "Path": str(file_path),
                            "Extension": (
                                file_path.suffix.lower()
                            ),
                            "Size KB": round(
                                stat.st_size / 1024,
                                2,
                            ),
                            "Modified At": (
                                datetime.fromtimestamp(
                                    stat.st_mtime
                                ).isoformat(
                                    timespec="seconds"
                                )
                            ),
                        }
                    )

                except OSError:
                    continue

        except OSError:
            continue

    if not records:
        return pd.DataFrame(
            columns=[
                "Artifact",
                "Path",
                "Extension",
                "Size KB",
                "Modified At",
            ]
        )

    return pd.DataFrame(
        records
    ).sort_values(
        "Modified At",
        ascending=False,
    ).reset_index(drop=True)


# ------------------------------------------------------------
# 17.4 â€” READ PIPELINE RUN HISTORY
# ------------------------------------------------------------

def load_pipeline_run_history():
    """
    Load recorded pipeline run history from CSV.
    """

    history_path = Path(
        PIPELINE_RUN_HISTORY_PATH
    )

    if not history_path.exists():
        return pd.DataFrame(
            columns=[
                "Run ID",
                "Started At",
                "Finished At",
                "Script",
                "Status",
                "Duration Seconds",
                "Return Code",
                "Message",
            ]
        )

    try:
        history = pd.read_csv(
            history_path
        )

        expected_columns = [
            "Run ID",
            "Started At",
            "Finished At",
            "Script",
            "Status",
            "Duration Seconds",
            "Return Code",
            "Message",
        ]

        for column in expected_columns:
            if column not in history.columns:
                history[column] = np.nan

        return history[
            expected_columns
        ]

    except (
        OSError,
        pd.errors.ParserError,
        UnicodeDecodeError,
    ):
        return pd.DataFrame(
            columns=[
                "Run ID",
                "Started At",
                "Finished At",
                "Script",
                "Status",
                "Duration Seconds",
                "Return Code",
                "Message",
            ]
        )


# ------------------------------------------------------------
# 17.5 â€” SAVE PIPELINE RUN HISTORY
# ------------------------------------------------------------

def save_pipeline_run_history(
    history_dataframe,
):
    """
    Persist run history without overwriting unrelated files.
    """

    if not isinstance(
        history_dataframe,
        pd.DataFrame,
    ):
        return False

    try:
        ensure_pipeline_manager_directories()

        history_dataframe.to_csv(
            PIPELINE_RUN_HISTORY_PATH,
            index=False,
        )

        return True

    except OSError:
        logging.exception(
            "Unable to save pipeline run history."
        )

        return False


# ------------------------------------------------------------
# 17.6 â€” BUILD A RUN RECORD
# ------------------------------------------------------------

def build_pipeline_run_record(
    run_id,
    started_at,
    finished_at,
    script_name,
    status,
    duration_seconds,
    return_code,
    message,
):
    """
    Build a consistent metadata record for one pipeline run.
    """

    return {
        "Run ID": str(run_id),
        "Started At": str(started_at),
        "Finished At": str(finished_at),
        "Script": str(script_name),
        "Status": str(status),
        "Duration Seconds": round(
            float(duration_seconds),
            3,
        ),
        "Return Code": (
            return_code
        ),
        "Message": str(message),
    }


# ------------------------------------------------------------
# 17.7 â€” REGISTER A PIPELINE RUN
# ------------------------------------------------------------

def register_pipeline_run(
    run_record,
):
    """
    Append a new run record to the persistent run history.
    """

    required_fields = [
        "Run ID",
        "Started At",
        "Finished At",
        "Script",
        "Status",
        "Duration Seconds",
        "Return Code",
        "Message",
    ]

    if not isinstance(
        run_record,
        dict,
    ):
        return False

    if not all(
        field in run_record
        for field in required_fields
    ):
        return False

    history = load_pipeline_run_history()

    new_record = pd.DataFrame(
        [run_record]
    )

    updated_history = pd.concat(
        [
            history,
            new_record,
        ],
        ignore_index=True,
    )

    return save_pipeline_run_history(
        updated_history
    )


# ------------------------------------------------------------
# 17.8 â€” VALIDATE A SCRIPT PATH
# ------------------------------------------------------------

def validate_pipeline_script_path(
    script_path,
):
    """
    Ensure the selected script exists inside the project.

    This reduces accidental execution of an arbitrary path.
    """

    try:
        requested_path = Path(
            script_path
        ).resolve()

        project_path = Path(
            BASE_DIR
        ).resolve()

        requested_path.relative_to(
            project_path
        )

    except (
        ValueError,
        OSError,
        TypeError,
    ):
        return {
            "Valid": False,
            "Path": None,
            "Message": (
                "The script must be inside the project directory."
            ),
        }

    if requested_path.suffix.lower() != ".py":
        return {
            "Valid": False,
            "Path": str(requested_path),
            "Message": (
                "Only Python scripts are supported."
            ),
        }

    if not requested_path.is_file():
        return {
            "Valid": False,
            "Path": str(requested_path),
            "Message": (
                "The selected script does not exist."
            ),
        }

    return {
        "Valid": True,
        "Path": str(requested_path),
        "Message": "Script path is valid.",
    }


# ------------------------------------------------------------
# 17.9 â€” RUN A CONFIGURED PIPELINE SCRIPT
# ------------------------------------------------------------

def execute_pipeline_script(
    script_path,
    timeout_seconds=PIPELINE_DEFAULT_TIMEOUT_SECONDS,
    additional_arguments=None,
):
    """
    Execute one explicitly selected Python script.

    This function runs only after a user initiates execution.
    A candidate script is not assumed to be a valid standalone
    pipeline merely because the file exists.

    Shell execution is disabled.
    """

    import subprocess
    import sys
    import time
    import uuid

    run_id = str(
        uuid.uuid4()
    )

    started_timestamp = datetime.now()

    started_at = started_timestamp.isoformat(
        timespec="seconds"
    )

    timer_start = time.perf_counter()

    validation = validate_pipeline_script_path(
        script_path
    )

    if not validation["Valid"]:
        finished_at = datetime.now().isoformat(
            timespec="seconds"
        )

        record = build_pipeline_run_record(
            run_id=run_id,
            started_at=started_at,
            finished_at=finished_at,
            script_name=str(script_path),
            status="Rejected",
            duration_seconds=0,
            return_code=None,
            message=validation["Message"],
        )

        register_pipeline_run(
            record
        )

        return {
            "Run ID": run_id,
            "Status": "Rejected",
            "Return Code": None,
            "Duration Seconds": 0,
            "Message": validation["Message"],
            "Stdout": "",
            "Stderr": "",
        }

    try:
        timeout_seconds = int(
            timeout_seconds
        )
    except (
        TypeError,
        ValueError,
    ):
        timeout_seconds = (
            PIPELINE_DEFAULT_TIMEOUT_SECONDS
        )

    timeout_seconds = max(
        1,
        min(
            timeout_seconds,
            PIPELINE_MAX_TIMEOUT_SECONDS,
        ),
    )

    arguments = []

    if additional_arguments:
        if not isinstance(
            additional_arguments,
            list,
        ):
            additional_arguments = []

        arguments = [
            str(argument)
            for argument in additional_arguments
        ]

    command = [
        sys.executable,
        validation["Path"],
        *arguments,
    ]

    status = "Failed"
    return_code = None
    stdout_text = ""
    stderr_text = ""
    message = ""

    try:
        completed = subprocess.run(
            command,
            cwd=str(BASE_DIR),
            capture_output=True,
            text=True,
            timeout=timeout_seconds,
            shell=False,
            check=False,
        )

        return_code = completed.returncode

        stdout_text = completed.stdout or ""
        stderr_text = completed.stderr or ""

        if return_code == 0:
            status = "Completed"
            message = (
                "The script exited with return code 0. "
                "Generated outputs still require validation."
            )
        else:
            status = "Failed"
            message = (
                "The script exited with a non-zero return code."
            )

    except subprocess.TimeoutExpired as error:
        status = "Timed Out"

        stdout_text = (
            error.stdout.decode(
                errors="replace"
            )
            if isinstance(error.stdout, bytes)
            else error.stdout or ""
        )

        stderr_text = (
            error.stderr.decode(
                errors="replace"
            )
            if isinstance(error.stderr, bytes)
            else error.stderr or ""
        )

        message = (
            f"Execution exceeded the {timeout_seconds}-second timeout."
        )

    except OSError as error:
        status = "Failed"

        message = (
            f"Unable to launch the script: {error}"
        )

    duration_seconds = (
        time.perf_counter()
        - timer_start
    )

    finished_at = datetime.now().isoformat(
        timespec="seconds"
    )

    record = build_pipeline_run_record(
        run_id=run_id,
        started_at=started_at,
        finished_at=finished_at,
        script_name=Path(
            validation["Path"]
        ).name,
        status=status,
        duration_seconds=duration_seconds,
        return_code=return_code,
        message=message,
    )

    register_pipeline_run(
        record
    )

    return {
        "Run ID": run_id,
        "Status": status,
        "Return Code": return_code,
        "Duration Seconds": round(
            duration_seconds,
            3,
        ),
        "Message": message,
        "Stdout": stdout_text,
        "Stderr": stderr_text,
    }


# ------------------------------------------------------------
# 17.10 â€” BUILD RUN HISTORY SUMMARY
# ------------------------------------------------------------

def build_pipeline_run_summary(
    history_dataframe,
):
    """
    Summarize previously recorded pipeline executions.
    """

    if (
        not isinstance(
            history_dataframe,
            pd.DataFrame,
        )
        or history_dataframe.empty
    ):
        return {
            "Total Runs": 0,
            "Completed Runs": 0,
            "Failed Runs": 0,
            "Timed Out Runs": 0,
            "Latest Status": "No runs recorded",
        }

    statuses = (
        history_dataframe["Status"]
        .astype(str)
    )

    latest_status = (
        statuses.iloc[-1]
    )

    return {
        "Total Runs": int(
            len(history_dataframe)
        ),
        "Completed Runs": int(
            statuses.eq("Completed").sum()
        ),
        "Failed Runs": int(
            statuses.eq("Failed").sum()
        ),
        "Timed Out Runs": int(
            statuses.eq("Timed Out").sum()
        ),
        "Latest Status": latest_status,
    }


