def render_pipeline_execution_controls():
    """
    Let the user explicitly select and launch a Python script.

    Execution is not automatic. Candidate scripts may need
    additional integration before they produce forecast outputs.
    """

    st.subheader(
        "Run a Python Script"
    )

    scripts = discover_pipeline_scripts()

    if scripts.empty:
        st.info(
            "No candidate scripts are available to select."
        )
