    selected_script_name = st.selectbox(
        "Select Script",
        options=scripts["Script"].tolist(),
        key="pipeline_selected_script",
    )

    selected_script_path = (
        BASE_DIR / selected_script_name
    )

    timeout_seconds = st.number_input(
        "Execution Timeout (seconds)",
        min_value=1,
        max_value=PIPELINE_MAX_TIMEOUT_SECONDS,
        value=PIPELINE_DEFAULT_TIMEOUT_SECONDS,
        step=60,
        key="pipeline_timeout_seconds",
    )

    st.warning(
        "Only run scripts you understand and trust. "
        "A successful process exit does not guarantee valid "
        "forecasts or correct output files."
    )

    if st.button(
        "Execute Selected Script",
        type="primary",
        key="pipeline_execute_button",
    ):
        with st.spinner(
            "Executing the selected script..."
        ):
            result = execute_pipeline_script(
                script_path=selected_script_path,
                timeout_seconds=int(
                    timeout_seconds
                ),
            )

        st.session_state[
            "pipeline_last_execution"
        ] = result

    result = st.session_state.get(
        "pipeline_last_execution"
    )

    if not isinstance(
        result,
        dict,
    ):
        return

    st.write(
        f"**Run ID:** {result['Run ID']}"
    )

    st.write(
        f"**Status:** {result['Status']}"
    )

    st.write(
        f"**Duration:** {result['Duration Seconds']:.3f} seconds"
    )

    st.info(
        result["Message"]
    )

    if result.get("Stdout"):
        with st.expander(
            "Standard Output",
            expanded=False,
        ):
            st.code(
                result["Stdout"][-20000:]
            )

    if result.get("Stderr"):
        with st.expander(
            "Standard Error",
            expanded=result["Status"] != "Completed",
        ):
            st.code(
                result["Stderr"][-20000:]
            )


