# ============================================================
# PART 18 â€” DEMAND TREND & CHANGE-POINT INTELLIGENCE CENTER
# ============================================================

DEMAND_TREND_VERSION = "1.0.0"

DEMAND_TREND_METRICS = [
    "Sales Count",
    "Redemption Count",
]

DEMAND_TREND_FREQUENCIES = {
    "Daily": "D",
    "Weekly": "W",
    "Monthly": "MS",
}

DEMAND_TREND_DEFAULT_WINDOW = 7

DEMAND_TREND_MINIMUM_PERIODS = 5

DEMAND_TREND_CHANGE_THRESHOLD = 0.20

DEMAND_TREND_STABLE_THRESHOLD = 0.05


# ------------------------------------------------------------
# 18.1 â€” PREPARE TREND DATA
# ------------------------------------------------------------

def prepare_demand_trend_data(dataframe):
    """
    Prepare timestamp and demand columns for trend analysis.
    """

    required_columns = [
        "Timestamp",
        "Sales Count",
        "Redemption Count",
    ]

    if not isinstance(dataframe, pd.DataFrame):
        return pd.DataFrame(columns=required_columns)

    missing_columns = [
        column
        for column in required_columns
        if column not in dataframe.columns
    ]

    if missing_columns:
        return pd.DataFrame(columns=required_columns)

    prepared = dataframe[required_columns].copy()

    prepared["Timestamp"] = pd.to_datetime(
        prepared["Timestamp"],
        errors="coerce",
    )

    for column in DEMAND_TREND_METRICS:
        prepared[column] = pd.to_numeric(
            prepared[column],
            errors="coerce",
        )

        prepared[column] = prepared[column].replace(
            [np.inf, -np.inf],
            np.nan,
        )

    prepared = prepared.dropna(
        subset=["Timestamp"]
    )

    prepared = prepared.sort_values(
        "Timestamp"
    ).reset_index(drop=True)

    return prepared


# ------------------------------------------------------------
# 18.2 â€” AGGREGATE HISTORICAL DEMAND
# ------------------------------------------------------------

def aggregate_demand_trend(
    dataframe,
    metric="Sales Count",
    frequency="Daily",
):
    """
    Aggregate ticket counts to a selected time frequency.
    """

    if metric not in DEMAND_TREND_METRICS:
        raise ValueError(
            f"Unsupported demand metric: {metric}"
        )

    if frequency not in DEMAND_TREND_FREQUENCIES:
        raise ValueError(
            f"Unsupported frequency: {frequency}"
        )

    prepared = prepare_demand_trend_data(
        dataframe
    )

    if prepared.empty:
        return pd.DataFrame(
            columns=[
                "Timestamp",
                "Demand",
                "Source Records",
            ]
        )

    prepared = prepared.dropna(
        subset=[metric]
    )

    if prepared.empty:
        return pd.DataFrame(
            columns=[
                "Timestamp",
                "Demand",
                "Source Records",
            ]
        )

    prepared = prepared.set_index(
        "Timestamp"
    )

    rule = DEMAND_TREND_FREQUENCIES[
        frequency
    ]

    demand_series = prepared[metric].resample(
        rule
    ).sum(min_count=1)

    record_series = prepared[metric].resample(
        rule
    ).count()

    aggregated = pd.DataFrame(
        {
            "Demand": demand_series,
            "Source Records": record_series,
        }
    ).reset_index()

    aggregated = aggregated.rename(
        columns={
            "index": "Timestamp",
        }
    )

    return aggregated


# ------------------------------------------------------------
# 18.3 â€” CALCULATE ROLLING TREND
# ------------------------------------------------------------

def calculate_demand_rolling_trend(
    aggregated_data,
    window=DEMAND_TREND_DEFAULT_WINDOW,
):
    """
    Calculate moving averages and local demand changes.
    """

    required = [
        "Timestamp",
        "Demand",
    ]

    if not isinstance(
        aggregated_data,
        pd.DataFrame,
    ):
        return pd.DataFrame()

    if not all(
        column in aggregated_data.columns
        for column in required
    ):
        return pd.DataFrame()

    result = aggregated_data.copy()

    result["Timestamp"] = pd.to_datetime(
        result["Timestamp"],
        errors="coerce",
    )

    result["Demand"] = pd.to_numeric(
        result["Demand"],
        errors="coerce",
    )

    result = result.replace(
        [np.inf, -np.inf],
        np.nan,
    )

    result = result.dropna(
        subset=["Timestamp", "Demand"]
    ).sort_values(
        "Timestamp"
    ).reset_index(drop=True)

    try:
        window = int(window)
    except (
        TypeError,
        ValueError,
    ):
        window = DEMAND_TREND_DEFAULT_WINDOW

    window = max(
        2,
        min(
            window,
            365,
        ),
    )

    result["Rolling Average"] = (
        result["Demand"]
        .rolling(
            window=window,
            min_periods=1,
        )
        .mean()
    )

    result["Previous Period Demand"] = (
        result["Demand"].shift(1)
    )

    result["Demand Change"] = (
        result["Demand"]
        - result["Previous Period Demand"]
    )

    previous = result[
        "Previous Period Demand"
    ].replace(
        0,
        np.nan,
    )

    result["Demand Change %"] = (
        result["Demand Change"]
        .div(previous)
        .mul(100)
    )

    result["Rolling Change"] = (
        result["Rolling Average"]
        .diff()
    )

    return result


# ------------------------------------------------------------
# 18.4 â€” CLASSIFY OVERALL DEMAND TREND
# ------------------------------------------------------------

def classify_demand_trend(
    aggregated_data,
):
    """
    Compare the first and second halves of a demand series.

    The classification is a descriptive heuristic, not a
    statistical significance test.
    """

    if (
        not isinstance(
            aggregated_data,
            pd.DataFrame,
        )
        or "Demand" not in aggregated_data.columns
    ):
        return {
            "Classification": "Unavailable",
            "First Half Average": np.nan,
            "Second Half Average": np.nan,
            "Change Percentage": np.nan,
            "Observations": 0,
        }

    demand = pd.to_numeric(
        aggregated_data["Demand"],
        errors="coerce",
    ).replace(
        [np.inf, -np.inf],
        np.nan,
    ).dropna()

    if len(demand) < DEMAND_TREND_MINIMUM_PERIODS:
        return {
            "Classification": "Insufficient Data",
            "First Half Average": np.nan,
            "Second Half Average": np.nan,
            "Change Percentage": np.nan,
            "Observations": int(len(demand)),
        }

    midpoint = len(demand) // 2

    first_half = demand.iloc[:midpoint]
    second_half = demand.iloc[midpoint:]

    first_average = float(
        first_half.mean()
    )

    second_average = float(
        second_half.mean()
    )

    if first_average == 0:
        change_percentage = (
            0.0
            if second_average == 0
            else np.nan
        )
    else:
        change_percentage = (
            (
                second_average
                - first_average
            )
            / abs(first_average)
        ) * 100

    if not np.isfinite(change_percentage):
        classification = "Baseline Is Zero"

    elif (
        change_percentage
        >= DEMAND_TREND_CHANGE_THRESHOLD * 100
    ):
        classification = "Increasing"

    elif (
        change_percentage
        <= -DEMAND_TREND_CHANGE_THRESHOLD * 100
    ):
        classification = "Decreasing"

    elif (
        abs(change_percentage)
        <= DEMAND_TREND_STABLE_THRESHOLD * 100
    ):
        classification = "Relatively Stable"

    else:
        classification = "Moderate Change"

    return {
        "Classification": classification,
        "First Half Average": round(
            first_average,
            3,
        ),
        "Second Half Average": round(
            second_average,
            3,
        ),
        "Change Percentage": round(
            change_percentage,
            3,
        ) if np.isfinite(change_percentage) else np.nan,
        "Observations": int(
            len(demand)
        ),
    }


# ------------------------------------------------------------
# 18.5 â€” IDENTIFY SUDDEN DEMAND CHANGES
# ------------------------------------------------------------

def detect_demand_change_points(
    trend_data,
    change_threshold=DEMAND_TREND_CHANGE_THRESHOLD,
):
    """
    Identify adjacent periods with large percentage changes.

    This is a threshold-based change detector, not a formal
    statistical change-point detection algorithm.
    """

    required = [
        "Timestamp",
        "Demand",
    ]

    if (
        not isinstance(
            trend_data,
            pd.DataFrame,
        )
        or not all(
            column in trend_data.columns
            for column in required
        )
    ):
        return pd.DataFrame()

    result = trend_data.copy()

    result["Timestamp"] = pd.to_datetime(
        result["Timestamp"],
        errors="coerce",
    )

    result["Demand"] = pd.to_numeric(
        result["Demand"],
        errors="coerce",
    )

    result = result.replace(
        [np.inf, -np.inf],
        np.nan,
    ).dropna(
        subset=["Timestamp", "Demand"]
    ).sort_values(
        "Timestamp"
    ).reset_index(drop=True)

    result["Previous Demand"] = (
        result["Demand"].shift(1)
    )

    previous = result[
        "Previous Demand"
    ].replace(
        0,
        np.nan,
    )

    result["Change Percentage"] = (
        (
            result["Demand"]
            - result["Previous Demand"]
        )
        .div(previous.abs())
        .mul(100)
    )

    result["Change Direction"] = np.select(
        [
            result["Change Percentage"] > 0,
            result["Change Percentage"] < 0,
        ],
        [
            "Increase",
            "Decrease",
        ],
        default="No Change",
    )

    try:
        threshold = float(
            change_threshold
        )
    except (
        TypeError,
        ValueError,
    ):
        threshold = DEMAND_TREND_CHANGE_THRESHOLD

    if not np.isfinite(threshold):
        threshold = DEMAND_TREND_CHANGE_THRESHOLD

    threshold = max(
        0.01,
        min(
            threshold,
            5.0,
        ),
    )

    threshold_percentage = threshold * 100

    change_points = result.loc[
        result["Change Percentage"].abs()
        >= threshold_percentage
    ].copy()

    change_points["Change Severity"] = np.select(
        [
            change_points["Change Percentage"].abs() >= 100,
            change_points["Change Percentage"].abs() >= 50,
        ],
        [
            "High",
            "Medium",
        ],
        default="Moderate",
    )

    return change_points.reset_index(
        drop=True
    )


# ------------------------------------------------------------
# 18.6 â€” SUMMARIZE DEMAND VOLATILITY
# ------------------------------------------------------------

def summarize_demand_trend_volatility(
    aggregated_data,
):
    """
    Calculate descriptive volatility measures for demand.
    """

    if (
        not isinstance(
            aggregated_data,
            pd.DataFrame,
        )
        or "Demand" not in aggregated_data.columns
    ):
        return {
            "Observations": 0,
            "Mean Demand": np.nan,
            "Standard Deviation": np.nan,
            "Coefficient Of Variation": np.nan,
            "Maximum Demand": np.nan,
            "Minimum Demand": np.nan,
        }

    demand = pd.to_numeric(
        aggregated_data["Demand"],
        errors="coerce",
    ).replace(
        [np.inf, -np.inf],
        np.nan,
    ).dropna()

    if demand.empty:
        return {
            "Observations": 0,
            "Mean Demand": np.nan,
            "Standard Deviation": np.nan,
            "Coefficient Of Variation": np.nan,
            "Maximum Demand": np.nan,
            "Minimum Demand": np.nan,
        }

    mean_demand = float(
        demand.mean()
    )

    std_demand = float(
        demand.std(ddof=1)
    ) if len(demand) > 1 else 0.0

    coefficient_of_variation = (
        std_demand / abs(mean_demand)
        if mean_demand != 0
        else np.nan
    )

    return {
        "Observations": int(
            len(demand)
        ),
        "Mean Demand": round(
            mean_demand,
            3,
        ),
        "Standard Deviation": round(
            std_demand,
            3,
        ),
        "Coefficient Of Variation": (
            round(
                coefficient_of_variation,
                4,
            )
            if np.isfinite(
                coefficient_of_variation
            )
            else np.nan
        ),
        "Maximum Demand": round(
            float(demand.max()),
            3,
        ),
        "Minimum Demand": round(
            float(demand.min()),
            3,
        ),
    }


# ------------------------------------------------------------
# 18.7 â€” BUILD TREND REPORT
# ------------------------------------------------------------

def build_demand_trend_report(
    dataframe,
    metric="Sales Count",
    frequency="Daily",
    rolling_window=DEMAND_TREND_DEFAULT_WINDOW,
):
    """
    Build a complete descriptive demand trend report.
    """

    aggregated = aggregate_demand_trend(
        dataframe=dataframe,
        metric=metric,
        frequency=frequency,
    )

    trend = calculate_demand_rolling_trend(
        aggregated_data=aggregated,
        window=rolling_window,
    )

    classification = classify_demand_trend(
        aggregated
    )

    change_points = detect_demand_change_points(
        trend_data=aggregated
    )

    volatility = summarize_demand_trend_volatility(
        aggregated
    )

    return {
        "Metric": metric,
        "Frequency": frequency,
        "Aggregated Demand": aggregated,
        "Trend Data": trend,
        "Trend Classification": classification,
        "Change Points": change_points,
        "Volatility": volatility,
    }


