FORECAST_ERROR_DIAGNOSTICS_VERSION = "1.0.0"

FORECAST_ERROR_REQUIRED_COLUMNS = [
    "Actual",
    "Predicted",
]

FORECAST_ERROR_METRICS = [
    "MAE",
    "RMSE",
    "WAPE",
    "Bias",
    "MAPE",
]

FORECAST_ERROR_MINIMUM_ROWS = 2

FORECAST_ERROR_MAXIMUM_DISPLAY_ROWS = 1000


# ------------------------------------------------------------
# 19.1 â€” NORMALIZE COLUMN NAMES
# ------------------------------------------------------------

def normalize_forecast_error_column_name(
    column_name,
):
    """
    Normalize a column name for flexible column matching.
    """

    import re

    value = str(
        column_name
    ).strip().lower()

    value = re.sub(
        r"[^a-z0-9]+",
        "_",
        value,
    )

    return value.strip("_")


# ------------------------------------------------------------
# 19.2 â€” IDENTIFY ACTUAL AND PREDICTED COLUMNS
# ------------------------------------------------------------

def identify_forecast_error_columns(
    dataframe,
):
    """
    Suggest likely actual, predicted, and date columns.
    """

    if not isinstance(
        dataframe,
        pd.DataFrame,
    ):
        return {
            "Actual": None,
            "Predicted": None,
            "Timestamp": None,
        }

    normalized = {
        column: normalize_forecast_error_column_name(
            column
        )
        for column in dataframe.columns
    }

    actual_candidates = [
        "actual",
        "actual_value",
        "actual_demand",
        "actual_sales",
        "actual_count",
        "observed",
        "observed_demand",
        "y_true",
        "ground_truth",
    ]

    predicted_candidates = [
        "predicted",
        "prediction",
        "predicted_value",
        "predicted_demand",
        "forecast",
        "forecast_value",
        "forecast_demand",
        "y_pred",
        "model_prediction",
    ]

    date_candidates = [
        "timestamp",
        "date",
        "datetime",
        "forecast_date",
        "prediction_date",
        "ds",
    ]

    def find_candidate(
        candidates,
    ):
        for candidate in candidates:
            for original, normalized_name in normalized.items():
                if normalized_name == candidate:
                    return original

        return None

    return {
        "Actual": find_candidate(
            actual_candidates
        ),
        "Predicted": find_candidate(
            predicted_candidates
        ),
        "Timestamp": find_candidate(
            date_candidates
        ),
    }


# ------------------------------------------------------------
# 19.3 â€” PREPARE FORECAST EVALUATION DATA
# ------------------------------------------------------------

def prepare_forecast_error_data(
    dataframe,
    actual_column,
    predicted_column,
    timestamp_column=None,
):
    """
    Standardize evaluation data into Timestamp, Actual,
    Predicted, and Error columns.

    Error is defined as Actual minus Predicted.
    """

    output_columns = [
        "Timestamp",
        "Actual",
        "Predicted",
        "Error",
        "Absolute Error",
        "Squared Error",
    ]

    if not isinstance(
        dataframe,
        pd.DataFrame,
    ):
        return pd.DataFrame(
            columns=output_columns
        )

    if (
        actual_column not in dataframe.columns
        or predicted_column not in dataframe.columns
    ):
        return pd.DataFrame(
            columns=output_columns
        )

    if actual_column == predicted_column:
        return pd.DataFrame(
            columns=output_columns
        )

    prepared = pd.DataFrame(
        {
            "Actual": pd.to_numeric(
                dataframe[actual_column],
                errors="coerce",
            ),
            "Predicted": pd.to_numeric(
                dataframe[predicted_column],
                errors="coerce",
            ),
        }
    )

    if (
        timestamp_column is not None
        and timestamp_column in dataframe.columns
    ):
        prepared["Timestamp"] = pd.to_datetime(
            dataframe[timestamp_column],
            errors="coerce",
        )
    else:
        prepared["Timestamp"] = pd.NaT

    prepared = prepared.replace(
        [np.inf, -np.inf],
        np.nan,
    )

    prepared = prepared.dropna(
        subset=[
            "Actual",
            "Predicted",
        ]
    ).reset_index(
        drop=True
    )

    prepared["Error"] = (
        prepared["Actual"]
        - prepared["Predicted"]
    )

    prepared["Absolute Error"] = (
        prepared["Error"].abs()
    )

    prepared["Squared Error"] = (
        prepared["Error"] ** 2
    )

    return prepared[
        output_columns
    ]


# ------------------------------------------------------------
# 19.4 â€” CALCULATE MAE
# ------------------------------------------------------------

def calculate_forecast_error_mae(
    actual,
    predicted,
):
    """
    Mean Absolute Error.

    Lower values indicate smaller average absolute errors.
    """

    actual_values = np.asarray(
        actual,
        dtype=float,
    )

    predicted_values = np.asarray(
        predicted,
        dtype=float,
    )

    if (
        actual_values.size == 0
        or actual_values.shape != predicted_values.shape
    ):
        return np.nan

    valid = (
        np.isfinite(actual_values)
        & np.isfinite(predicted_values)
    )

    if not valid.any():
        return np.nan

    return float(
        np.mean(
            np.abs(
                actual_values[valid]
                - predicted_values[valid]
            )
        )
    )


# ------------------------------------------------------------
# 19.5 â€” CALCULATE RMSE
# ------------------------------------------------------------

def calculate_forecast_error_rmse(
    actual,
    predicted,
):
    """
    Root Mean Squared Error.

    Squaring errors gives larger errors greater influence.
    """

    actual_values = np.asarray(
        actual,
        dtype=float,
    )

    predicted_values = np.asarray(
        predicted,
        dtype=float,
    )

    if (
        actual_values.size == 0
        or actual_values.shape != predicted_values.shape
    ):
        return np.nan

    valid = (
        np.isfinite(actual_values)
        & np.isfinite(predicted_values)
    )

    if not valid.any():
        return np.nan

    errors = (
        actual_values[valid]
        - predicted_values[valid]
    )

    return float(
        np.sqrt(
            np.mean(
                errors ** 2
            )
        )
    )


# ------------------------------------------------------------
# 19.6 â€” CALCULATE WAPE
# ------------------------------------------------------------

def calculate_forecast_error_wape(
    actual,
    predicted,
):
    """
    Weighted Absolute Percentage Error.

    Returns NaN when the sum of absolute actual values is zero.
    """

    actual_values = np.asarray(
        actual,
        dtype=float,
    )

    predicted_values = np.asarray(
        predicted,
        dtype=float,
    )

    if (
        actual_values.size == 0
        or actual_values.shape != predicted_values.shape
    ):
        return np.nan

    valid = (
        np.isfinite(actual_values)
        & np.isfinite(predicted_values)
    )

    if not valid.any():
        return np.nan

    actual_values = actual_values[valid]
    predicted_values = predicted_values[valid]

    denominator = np.sum(
        np.abs(
            actual_values
        )
    )

    if denominator == 0:
        return np.nan

    numerator = np.sum(
        np.abs(
            actual_values
            - predicted_values
        )
    )

    return float(
        numerator / denominator * 100
    )


# ------------------------------------------------------------
# 19.7 â€” CALCULATE MAPE
# ------------------------------------------------------------

def calculate_forecast_error_mape(
    actual,
    predicted,
):
    """
    Mean Absolute Percentage Error.

    Actual values equal to zero are excluded because their
    individual percentage errors are undefined.
    """

    actual_values = np.asarray(
        actual,
        dtype=float,
    )

    predicted_values = np.asarray(
        predicted,
        dtype=float,
    )

    if (
        actual_values.size == 0
        or actual_values.shape != predicted_values.shape
    ):
        return np.nan

    valid = (
        np.isfinite(actual_values)
        & np.isfinite(predicted_values)
        & (actual_values != 0)
    )

    if not valid.any():
        return np.nan

    percentage_errors = (
        np.abs(
            actual_values[valid]
            - predicted_values[valid]
        )
        / np.abs(
            actual_values[valid]
        )
    ) * 100

    return float(
        np.mean(
            percentage_errors
        )
    )


# ------------------------------------------------------------
# 19.8 â€” BUILD EVALUATION METRICS
# ------------------------------------------------------------

def build_forecast_error_metrics(
    evaluation_data,
):
    """
    Calculate standard metrics from standardized observations.
    """

    required_columns = [
        "Actual",
        "Predicted",
        "Error",
        "Absolute Error",
        "Squared Error",
    ]

    if (
        not isinstance(
            evaluation_data,
            pd.DataFrame,
        )
        or evaluation_data.empty
        or not all(
            column in evaluation_data.columns
            for column in required_columns
        )
    ):
        return {
            "Observations": 0,
            "MAE": np.nan,
            "RMSE": np.nan,
            "WAPE": np.nan,
            "Bias": np.nan,
            "MAPE": np.nan,
        }

    actual = evaluation_data[
        "Actual"
    ].to_numpy(dtype=float)

    predicted = evaluation_data[
        "Predicted"
    ].to_numpy(dtype=float)

    valid = (
        np.isfinite(actual)
        & np.isfinite(predicted)
    )

    actual = actual[valid]
    predicted = predicted[valid]

    if len(actual) == 0:
        return {
            "Observations": 0,
            "MAE": np.nan,
            "RMSE": np.nan,
            "WAPE": np.nan,
            "Bias": np.nan,
            "MAPE": np.nan,
        }

    error = actual - predicted

    return {
        "Observations": int(
            len(actual)
        ),
        "MAE": calculate_forecast_error_mae(
            actual,
            predicted,
        ),
        "RMSE": calculate_forecast_error_rmse(
            actual,
            predicted,
        ),
        "WAPE": calculate_forecast_error_wape(
            actual,
            predicted,
        ),
        "Bias": float(
            np.mean(error)
        ),
        "MAPE": calculate_forecast_error_mape(
            actual,
            predicted,
        ),
    }


# ------------------------------------------------------------
# 19.9 â€” INTERPRET ERROR DIRECTION
# ------------------------------------------------------------

def summarize_forecast_error_direction(
    evaluation_data,
):
    """
    Summarize overprediction and underprediction.

    Positive error means actual demand exceeded predicted
    demand, so the model underpredicted.
    """

    if (
        not isinstance(
            evaluation_data,
            pd.DataFrame,
        )
        or "Error" not in evaluation_data.columns
    ):
        return {
            "Underpredicted": 0,
            "Overpredicted": 0,
            "Exact": 0,
            "Average Bias": np.nan,
        }

    errors = pd.to_numeric(
        evaluation_data["Error"],
        errors="coerce",
    ).replace(
        [np.inf, -np.inf],
        np.nan,
    ).dropna()

    if errors.empty:
        return {
            "Underpredicted": 0,
            "Overpredicted": 0,
            "Exact": 0,
            "Average Bias": np.nan,
        }

    return {
        "Underpredicted": int(
            (errors > 0).sum()
        ),
        "Overpredicted": int(
            (errors < 0).sum()
        ),
        "Exact": int(
            (errors == 0).sum()
        ),
        "Average Bias": float(
            errors.mean()
        ),
    }


# ------------------------------------------------------------
# 19.10 â€” BUILD PERIODIC ERROR SUMMARY
# ------------------------------------------------------------

def build_forecast_period_error_summary(
    evaluation_data,
    frequency="Weekly",
):
    """
    Aggregate forecast errors by calendar period.
    """

    frequency_map = {
        "Daily": "D",
        "Weekly": "W",
        "Monthly": "MS",
    }

    if frequency not in frequency_map:
        raise ValueError(
            f"Unsupported frequency: {frequency}"
        )

    required = [
        "Timestamp",
        "Actual",
        "Predicted",
        "Error",
        "Absolute Error",
    ]

    if (
        not isinstance(
            evaluation_data,
            pd.DataFrame,
        )
        or not all(
            column in evaluation_data.columns
            for column in required
        )
    ):
        return pd.DataFrame()

    dated = evaluation_data.dropna(
        subset=["Timestamp"]
    ).copy()

    if dated.empty:
        return pd.DataFrame()

    dated["Timestamp"] = pd.to_datetime(
        dated["Timestamp"],
        errors="coerce",
    )

    dated = dated.dropna(
        subset=["Timestamp"]
    ).set_index(
        "Timestamp"
    )

    summary = dated.resample(
        frequency_map[frequency]
    ).agg(
        {
            "Actual": "sum",
            "Predicted": "sum",
            "Error": "mean",
            "Absolute Error": "mean",
        }
    )

    counts = dated["Error"].resample(
        frequency_map[frequency]
    ).count()

    summary["Observations"] = counts

    summary = summary.rename(
        columns={
            "Error": "Mean Error",
            "Absolute Error": "MAE",
        }
    )

    return summary.dropna(
        how="all"
    ).reset_index()


# ------------------------------------------------------------
# 19.11 â€” IDENTIFY LARGEST ERRORS
# ------------------------------------------------------------

def identify_largest_forecast_errors(
    evaluation_data,
    top_n=20,
):
    """
    Return the observations with the largest absolute errors.
    """

    if (
        not isinstance(
            evaluation_data,
            pd.DataFrame,
        )
        or "Absolute Error" not in evaluation_data.columns
    ):
        return pd.DataFrame()

    try:
        top_n = int(
            top_n
        )
    except (
        TypeError,
        ValueError,
    ):
        top_n = 20

    top_n = max(
        1,
        min(
            top_n,
            FORECAST_ERROR_MAXIMUM_DISPLAY_ROWS,
        ),
    )

    return evaluation_data.nlargest(
        top_n,
        "Absolute Error",
    ).reset_index(
        drop=True
    )


# ------------------------------------------------------------
# 19.12 â€” GENERATE ERROR INTERPRETATION
# ------------------------------------------------------------

def generate_forecast_error_interpretation(
    metrics,
    direction_summary,
):
    """
    Create cautious, metric-based diagnostic observations.
    """

    messages = []

    observations = metrics.get(
        "Observations",
        0,
    )

    if observations < FORECAST_ERROR_MINIMUM_ROWS:
        messages.append(
            "Too few valid observations are available for "
            "a useful error assessment."
        )

        return messages

    mae = metrics.get(
        "MAE",
        np.nan,
    )

    rmse = metrics.get(
        "RMSE",
        np.nan,
    )

    wape = metrics.get(
        "WAPE",
        np.nan,
    )

    bias = metrics.get(
        "Bias",
        np.nan,
    )

    if np.isfinite(mae):
        messages.append(
            f"Mean absolute prediction error is {mae:.3f} "
            "in the target's units."
        )

    if (
        np.isfinite(mae)
        and np.isfinite(rmse)
        and mae > 0
    ):
        ratio = rmse / mae

        if ratio > 1.5:
            messages.append(
                "RMSE is substantially larger than MAE, "
                "suggesting that some larger errors may "
                "be influencing the overall score."
            )
        else:
            messages.append(
                "RMSE is relatively close to MAE, indicating "
                "that the two error summaries are not "
                "strongly separated."
            )

    if np.isfinite(wape):
        messages.append(
            f"WAPE is {wape:.2f}%. Compare this value with "
            "a baseline model and a time-ordered holdout."
        )

    if np.isfinite(bias):
        if bias > 0:
            messages.append(
                "Average error is positive: actual values "
                "were higher than predictions on average."
            )
        elif bias < 0:
            messages.append(
                "Average error is negative: predictions "
                "were higher than actual values on average."
            )
        else:
            messages.append(
                "Average signed error is zero."
            )

    under = direction_summary.get(
        "Underpredicted",
        0,
    )

    over = direction_summary.get(
        "Overpredicted",
        0,
    )

    if under > over:
        messages.append(
            "Underprediction occurred more often than "
            "overprediction in the evaluated observations."
        )
    elif over > under:
        messages.append(
            "Overprediction occurred more often than "
            "underprediction in the evaluated observations."
        )

    messages.append(
        "These diagnostics describe the supplied predictions. "
        "They do not establish future accuracy or causation."
    )

    return messages


