def render_forecast_error_metrics(
    metrics,
):
    """
    Display the core forecast evaluation metrics.
    """

    st.subheader(
        "Forecast Evaluation Metrics"
    )

    columns = st.columns(5)

    display_metrics = [
        ("MAE", "MAE"),
        ("RMSE", "RMSE"),
        ("WAPE", "WAPE"),
        ("Bias", "Bias"),
        ("MAPE", "MAPE"),
    ]

    for column, (label, key) in zip(
        columns,
        display_metrics,
    ):
        value = metrics.get(
            key,
            np.nan,
        )

        with column:
            if pd.isna(value):
                st.metric(
                    label,
                    "N/A",
                )
            elif key in [
                "WAPE",
                "MAPE",
            ]:
                st.metric(
                    label,
                    f"{value:.2f}%",
                )
            else:
                st.metric(
                    label,
                    f"{value:.3f}",
                )

    st.caption(
        f"Valid observations: {metrics.get('Observations', 0)}. "
        "MAE, RMSE and Bias use the target's units."
    )


