# ------------------------------------------------------------
# 19.21 â€” MAIN FORECAST ERROR DIAGNOSTICS CENTER
# ------------------------------------------------------------

def render_forecast_error_diagnostics_center():
    """
    Render the forecast evaluation workspace.

    The user must provide actual and predicted observations.
    """

    st.title(
        "Forecast Accuracy & Error Diagnostics"
    )

    st.write(
        "Evaluate historical predictions against actual "
        "observations and investigate prediction errors."
    )

    uploaded_file = st.file_uploader(
        "Upload an Actual vs Predicted CSV",
        type=["csv"],
        key="forecast_error_upload",
    )

    if uploaded_file is None:
        st.info(
            "Upload a CSV containing actual values and "
            "corresponding model predictions to begin."
        )

        st.caption(
            "A historical sales dataset alone cannot establish "
            "forecast accuracy. The file must contain genuine "
            "predictions aligned with their actual observations."
        )

        return

    try:
        raw_data = pd.read_csv(
            uploaded_file
        )
    except (
        pd.errors.ParserError,
        UnicodeDecodeError,
        ValueError,
    ) as error:
        st.error(
            f"Unable to read the uploaded CSV: {error}"
        )
        return

    if raw_data.empty:
        st.warning(
            "The uploaded file contains no rows."
        )
        return

    st.write(
        f"Uploaded observations: {len(raw_data):,}"
    )

    suggestions = identify_forecast_error_columns(
        raw_data
    )

    columns = list(
        raw_data.columns
    )

    actual_default = (
        columns.index(
            suggestions["Actual"]
        )
        if suggestions["Actual"] in columns
        else 0
    )

    predicted_default = (
        columns.index(
            suggestions["Predicted"]
        )
        if suggestions["Predicted"] in columns
        else min(
            1,
            len(columns) - 1,
        )
    )

    actual_column = st.selectbox(
        "Actual Values Column",
        options=columns,
        index=actual_default,
        key="forecast_error_actual_column",
    )

    predicted_column = st.selectbox(
        "Predicted Values Column",
        options=columns,
        index=predicted_default,
        key="forecast_error_predicted_column",
    )

    date_options = [
        "No date column",
        *columns,
    ]

    suggested_date = suggestions[
        "Timestamp"
    ]

    date_default = (
        date_options.index(
            suggested_date
        )
        if suggested_date in date_options
        else 0
    )

    date_selection = st.selectbox(
        "Timestamp Column (optional)",
        options=date_options,
        index=date_default,
        key="forecast_error_date_column",
    )

    timestamp_column = (
        None
        if date_selection == "No date column"
        else date_selection
    )

    if actual_column == predicted_column:
        st.error(
            "Select different columns for actual and predicted values."
        )
        return

    evaluation_data = prepare_forecast_error_data(
        dataframe=raw_data,
        actual_column=actual_column,
        predicted_column=predicted_column,
        timestamp_column=timestamp_column,
    )

    if len(evaluation_data) < FORECAST_ERROR_MINIMUM_ROWS:
        st.warning(
            "At least two valid actual-predicted pairs are "
            "required for this evaluation view."
        )
        return

    metrics = build_forecast_error_metrics(
        evaluation_data
    )

    direction_summary = summarize_forecast_error_direction(
        evaluation_data
    )

    render_forecast_error_metrics(
        metrics
    )

    st.divider()

    render_forecast_error_actual_predicted(
        evaluation_data
    )

    st.divider()

    render_forecast_error_direction(
        direction_summary
    )

    st.divider()

    render_forecast_error_distribution(
        evaluation_data
    )

    st.divider()

    render_forecast_period_error_summary(
        evaluation_data
    )

    st.divider()

    render_largest_forecast_error_table(
        evaluation_data
    )

    st.divider()

    render_forecast_error_interpretation(
        metrics,
        direction_summary,
    )

    st.divider()

    render_forecast_error_exports(
        evaluation_data
    )


