# ============================================================
# PART 20 â€” FORECASTING BENCHMARK & MODEL SELECTION CENTER
# ============================================================

FORECAST_BENCHMARK_VERSION = "1.0.0"

FORECAST_BENCHMARK_REQUIRED_COLUMNS = [
    "Model",
    "Actual",
    "Predicted",
]

FORECAST_BENCHMARK_MINIMUM_ROWS = 2

FORECAST_BENCHMARK_DEFAULT_METRIC = "WAPE"

FORECAST_BENCHMARK_SUPPORTED_METRICS = [
    "MAE",
    "RMSE",
    "WAPE",
]


# ------------------------------------------------------------
# 20.1 â€” PREPARE BENCHMARK DATA
# ------------------------------------------------------------

def prepare_forecast_benchmark_data(
    dataframe,
    model_column,
    actual_column,
    predicted_column,
    timestamp_column=None,
):
    """
    Standardize model evaluation data for benchmarking.

    Each row must contain one model prediction and its
    corresponding actual observation.
    """

    required = [
        model_column,
        actual_column,
        predicted_column,
    ]

    if not isinstance(
        dataframe,
        pd.DataFrame,
    ):
        return pd.DataFrame()

    if not all(
        column in dataframe.columns
        for column in required
    ):
        return pd.DataFrame()

    if len(
        set(required)
    ) != len(required):
        return pd.DataFrame()

    prepared = pd.DataFrame(
        {
            "Model": dataframe[
                model_column
            ].astype("string").str.strip(),
            "Actual": pd.to_numeric(
                dataframe[actual_column],
                errors="coerce",
            ),
            "Predicted": pd.to_numeric(
                dataframe[predicted_column],
                errors="coerce",
            ),
        }
    )

    if (
        timestamp_column is not None
        and timestamp_column in dataframe.columns
    ):
        prepared["Timestamp"] = pd.to_datetime(
            dataframe[timestamp_column],
            errors="coerce",
        )
    else:
        prepared["Timestamp"] = pd.NaT

    prepared = prepared.replace(
        [np.inf, -np.inf],
        np.nan,
    )

    prepared = prepared.dropna(
        subset=[
            "Model",
            "Actual",
            "Predicted",
        ]
    )

    prepared = prepared[
        prepared["Model"] != ""
    ].reset_index(
        drop=True
    )

    return prepared


# ------------------------------------------------------------
# 20.2 â€” CALCULATE BENCHMARK METRICS
# ------------------------------------------------------------

def calculate_forecast_benchmark_metrics(
    evaluation_data,
):
    """
    Calculate MAE, RMSE, WAPE, and bias for one model.
    """

    required = [
        "Actual",
        "Predicted",
    ]

    if (
        not isinstance(
            evaluation_data,
            pd.DataFrame,
        )
        or not all(
            column in evaluation_data.columns
            for column in required
        )
    ):
        return {
            "Observations": 0,
            "MAE": np.nan,
            "RMSE": np.nan,
            "WAPE": np.nan,
            "Bias": np.nan,
        }

    actual = pd.to_numeric(
        evaluation_data["Actual"],
        errors="coerce",
    ).to_numpy(
        dtype=float
    )

    predicted = pd.to_numeric(
        evaluation_data["Predicted"],
        errors="coerce",
    ).to_numpy(
        dtype=float
    )

    valid = (
        np.isfinite(actual)
        & np.isfinite(predicted)
    )

    actual = actual[valid]
    predicted = predicted[valid]

    if len(actual) == 0:
        return {
            "Observations": 0,
            "MAE": np.nan,
            "RMSE": np.nan,
            "WAPE": np.nan,
            "Bias": np.nan,
        }

    errors = actual - predicted

    denominator = np.sum(
        np.abs(actual)
    )

    wape = (
        float(
            np.sum(
                np.abs(errors)
            ) / denominator * 100
        )
        if denominator > 0
        else np.nan
    )

    return {
        "Observations": int(
            len(actual)
        ),
        "MAE": float(
            np.mean(
                np.abs(errors)
            )
        ),
        "RMSE": float(
            np.sqrt(
                np.mean(
                    errors ** 2
                )
            )
        ),
        "WAPE": wape,
        "Bias": float(
            np.mean(errors)
        ),
    }


# ------------------------------------------------------------
# 20.3 â€” BUILD MODEL COMPARISON TABLE
# ------------------------------------------------------------

def build_forecast_benchmark_comparison(
    evaluation_data,
):
    """
    Compare models using their supplied actual-predicted pairs.
    """

    if (
        not isinstance(
            evaluation_data,
            pd.DataFrame,
        )
        or evaluation_data.empty
    ):
        return pd.DataFrame()

    records = []

    for model_name, group in evaluation_data.groupby(
        "Model",
        sort=True,
    ):
        metrics = calculate_forecast_benchmark_metrics(
            group
        )

        records.append(
            {
                "Model": str(model_name),
                **metrics,
            }
        )

    if not records:
        return pd.DataFrame()

    return pd.DataFrame(
        records
    )


# ------------------------------------------------------------
# 20.4 â€” RANK FORECASTING MODELS
# ------------------------------------------------------------

def rank_forecast_benchmark_models(
    comparison_data,
    metric=FORECAST_BENCHMARK_DEFAULT_METRIC,
):
    """
    Rank models by a supported error metric.

    Lower error is better. Rankings are descriptive and
    depend on the supplied evaluation observations.
    """

    if metric not in FORECAST_BENCHMARK_SUPPORTED_METRICS:
        raise ValueError(
            f"Unsupported benchmark metric: {metric}"
        )

    if (
        not isinstance(
            comparison_data,
            pd.DataFrame,
        )
        or comparison_data.empty
        or metric not in comparison_data.columns
    ):
        return pd.DataFrame()

    ranked = comparison_data.copy()

    ranked[metric] = pd.to_numeric(
        ranked[metric],
        errors="coerce",
    )

    ranked = ranked.replace(
        [np.inf, -np.inf],
        np.nan,
    )

    ranked = ranked.dropna(
        subset=[metric]
    )

    if ranked.empty:
        return ranked

    ranked = ranked.sort_values(
        metric,
        ascending=True,
    ).reset_index(
        drop=True
    )

    ranked.insert(
        0,
        "Rank",
        np.arange(
            1,
            len(ranked) + 1,
        ),
    )

    return ranked


# ------------------------------------------------------------
# 20.5 â€” IDENTIFY BEST MODEL
# ------------------------------------------------------------

def identify_best_forecast_benchmark_model(
    ranked_data,
):
    """
    Return the top-ranked model if valid ranking data exists.
    """

    if (
        not isinstance(
            ranked_data,
            pd.DataFrame,
        )
        or ranked_data.empty
    ):
        return None

    if (
        "Model" not in ranked_data.columns
        or "Rank" not in ranked_data.columns
    ):
        return None

    best = ranked_data.iloc[0]

    return {
        "Model": str(
            best["Model"]
        ),
        "Rank": int(
            best["Rank"]
        ),
    }


# ------------------------------------------------------------
# 20.6 â€” CHECK MODEL EVALUATION SAMPLE SIZES
# ------------------------------------------------------------

def summarize_forecast_benchmark_samples(
    evaluation_data,
):
    """
    Report sample sizes and timestamp coverage by model.
    """

    required = [
        "Model",
        "Actual",
        "Predicted",
        "Timestamp",
    ]

    if (
        not isinstance(
            evaluation_data,
            pd.DataFrame,
        )
        or not all(
            column in evaluation_data.columns
            for column in required
        )
    ):
        return pd.DataFrame()

    records = []

    for model_name, group in evaluation_data.groupby(
        "Model",
        sort=True,
    ):
        valid_timestamps = group[
            "Timestamp"
        ].dropna()

        records.append(
            {
                "Model": str(model_name),
                "Evaluation Rows": int(
                    len(group)
                ),
                "Timestamp Coverage": int(
                    len(valid_timestamps)
                ),
                "First Evaluation Date": (
                    valid_timestamps.min()
                    if not valid_timestamps.empty
                    else pd.NaT
                ),
                "Last Evaluation Date": (
                    valid_timestamps.max()
                    if not valid_timestamps.empty
                    else pd.NaT
                ),
            }
        )

    return pd.DataFrame(
        records
    )


# ------------------------------------------------------------
# 20.7 â€” CHECK COMPARISON CONSISTENCY
# ------------------------------------------------------------

def check_forecast_benchmark_consistency(
    evaluation_data,
):
    """
    Check whether model groups have equal observation counts.

    Equal row counts alone do not prove that the models were
    evaluated on exactly the same timestamps and target values.
    """

    if (
        not isinstance(
            evaluation_data,
            pd.DataFrame,
        )
        or evaluation_data.empty
    ):
        return {
            "Comparable": False,
            "Model Count": 0,
            "Observation Counts": {},
            "Equal Observation Counts": False,
            "Message": "No valid evaluation observations.",
        }

    counts = (
        evaluation_data.groupby(
            "Model"
        ).size()
    )

    equal_counts = (
        counts.nunique() == 1
    )

    if equal_counts:
        message = (
            "Model groups have equal row counts. "
            "Confirm timestamp and target alignment separately."
        )
    else:
        message = (
            "Model groups have different row counts. "
            "Metric comparisons may use different sample sizes."
        )

    return {
        "Comparable": bool(
            equal_counts
        ),
        "Model Count": int(
            len(counts)
        ),
        "Observation Counts": {
            str(key): int(value)
            for key, value in counts.items()
        },
        "Equal Observation Counts": bool(
            equal_counts
        ),
        "Message": message,
    }


# ------------------------------------------------------------
# 20.8 â€” BUILD BENCHMARK REPORT
# ------------------------------------------------------------

def build_forecast_benchmark_report(
    evaluation_data,
    ranking_metric=FORECAST_BENCHMARK_DEFAULT_METRIC,
):
    """
    Build comparison, ranking, best-model and sample reports.
    """

    comparison = build_forecast_benchmark_comparison(
        evaluation_data
    )

    ranking = rank_forecast_benchmark_models(
        comparison,
        metric=ranking_metric,
    )

    best_model = identify_best_forecast_benchmark_model(
        ranking
    )

    sample_summary = summarize_forecast_benchmark_samples(
        evaluation_data
    )

    consistency = check_forecast_benchmark_consistency(
        evaluation_data
    )

    return {
        "Ranking Metric": ranking_metric,
        "Comparison": comparison,
        "Ranking": ranking,
        "Best Model": best_model,
        "Sample Summary": sample_summary,
        "Consistency": consistency,
    }


