def render_forecast_benchmark_center():
    """
    Render the multiple-model comparison workspace.

    Expected CSV format: one row per model prediction, with
    columns for model name, actual value and predicted value.
    """

    st.title(
        "Forecast Benchmark & Model Selection"
    )

    st.write(
        "Compare candidate forecasting models using "
        "consistent error metrics."
    )

    uploaded_file = st.file_uploader(
        "Upload Model Predictions CSV",
        type=["csv"],
        key="forecast_benchmark_upload",
    )

    if uploaded_file is None:
        st.info(
            "Upload model evaluation results to compare models."
        )

        st.code(
            "Model,Timestamp,Actual,Predicted\n"
            "Baseline,2025-01-01,120,115\n"
            "Baseline,2025-01-02,135,130\n"
            "Candidate,2025-01-01,120,118\n"
            "Candidate,2025-01-02,135,134",
            language="csv",
        )

        st.caption(
            "The displayed rows are an illustrative format example, "
            "not measured results from your ferry dataset."
        )

        return

    try:
        raw_data = pd.read_csv(
            uploaded_file
        )
    except (
        pd.errors.ParserError,
        UnicodeDecodeError,
        ValueError,
    ) as error:
        st.error(
            f"Unable to read the uploaded CSV: {error}"
        )
        return

    if raw_data.empty:
        st.warning(
            "The uploaded CSV contains no observations."
        )
        return

    columns = list(
        raw_data.columns
    )

    suggestions = identify_forecast_error_columns(
        raw_data
    )

    model_candidates = [
        "model",
        "model_name",
        "algorithm",
        "estimator",
    ]

    normalized_columns = {
        column: normalize_forecast_error_column_name(
            column
        )
        for column in columns
    }

    suggested_model = next(
        (
            column
            for column, normalized in normalized_columns.items()
            if normalized in model_candidates
        ),
        columns[0],
    )

    model_column = st.selectbox(
        "Model Name Column",
        columns,
        index=columns.index(
            suggested_model
        ),
        key="forecast_benchmark_model_column",
    )

    actual_suggestion = suggestions[
        "Actual"
    ]

    predicted_suggestion = suggestions[
        "Predicted"
    ]

    actual_default = (
        columns.index(
            actual_suggestion
        )
        if actual_suggestion in columns
        else 0
    )

    predicted_default = (
        columns.index(
            predicted_suggestion
        )
        if predicted_suggestion in columns
        else min(
            1,
            len(columns) - 1,
        )
    )

    actual_column = st.selectbox(
        "Actual Values Column",
        columns,
        index=actual_default,
        key="forecast_benchmark_actual_column",
    )

    predicted_column = st.selectbox(
        "Predicted Values Column",
        columns,
        index=predicted_default,
        key="forecast_benchmark_predicted_column",
    )

    date_options = [
        "No date column",
        *columns,
    ]

    date_suggestion = suggestions[
        "Timestamp"
    ]

    date_default = (
        date_options.index(
            date_suggestion
        )
        if date_suggestion in date_options
        else 0
    )

    date_selection = st.selectbox(
        "Timestamp Column (optional)",
        date_options,
        index=date_default,
        key="forecast_benchmark_date_column",
    )

    timestamp_column = (
        None
        if date_selection == "No date column"
        else date_selection
    )

    if len(
        {
            model_column,
            actual_column,
            predicted_column,
        }
    ) < 3:
        st.error(
            "Choose different columns for model, actual, "
            "and predicted values."
        )
        return

    evaluation_data = prepare_forecast_benchmark_data(
        dataframe=raw_data,
        model_column=model_column,
        actual_column=actual_column,
        predicted_column=predicted_column,
        timestamp_column=timestamp_column,
    )

    if evaluation_data.empty:
        st.warning(
            "No valid model evaluation rows were found."
        )
        return

    model_count = evaluation_data[
        "Model"
    ].nunique()

    if model_count < 2:
        st.warning(
            "At least two different models are needed "
            "for a model comparison."
        )
        return

    report = build_forecast_benchmark_report(
        evaluation_data
    )

    render_forecast_benchmark_overview(
        report
    )

    st.divider()

    render_forecast_benchmark_comparison(
        report["Comparison"]
    )

    st.divider()

    ranking = render_forecast_benchmark_ranking(
        report["Comparison"]
    )

    report["Ranking"] = ranking

    st.divider()

    render_forecast_benchmark_sample_summary(
        report["Sample Summary"]
    )

    st.divider()

    render_forecast_benchmark_exports(
        report
    )


