# ============================================================
# PART 21 â€” FORECAST ENSEMBLE & MODEL BLEND SIMULATOR
# ============================================================

ENSEMBLE_BLEND_VERSION = "1.0.0"
ENSEMBLE_BLEND_MINIMUM_ROWS = 2
ENSEMBLE_BLEND_DEFAULT_WEIGHT = 1.0
ENSEMBLE_BLEND_MAXIMUM_MODELS = 20


def prepare_ensemble_blend_data(
    dataframe,
    timestamp_column,
    actual_column,
    model_prediction_columns,
):
    """
    Prepare aligned actual values and model predictions.

    Required input:
    - One actual-value column
    - One or more model-prediction columns
    - An optional timestamp column

    This function does not train models.
    """

    if dataframe is None or dataframe.empty:
        raise ValueError("Uploaded dataset is empty.")

    if not model_prediction_columns:
        raise ValueError("Select at least one model prediction column.")

    if len(model_prediction_columns) > ENSEMBLE_BLEND_MAXIMUM_MODELS:
        raise ValueError(
            f"Select no more than "
            f"{ENSEMBLE_BLEND_MAXIMUM_MODELS} prediction columns."
        )

    selected_columns = [actual_column] + list(model_prediction_columns)

    if timestamp_column:
        selected_columns.insert(0, timestamp_column)

    if len(set(selected_columns)) != len(selected_columns):
        raise ValueError(
            "Timestamp, actual and prediction columns must be different."
        )

    missing_columns = [
        column
        for column in selected_columns
        if column not in dataframe.columns
    ]

    if missing_columns:
        raise ValueError(
            f"Missing selected columns: {', '.join(missing_columns)}"
        )

    prepared = dataframe[selected_columns].copy()

    rename_mapping = {
        actual_column: "Actual"
    }

    for index, column in enumerate(model_prediction_columns, start=1):
        rename_mapping[column] = f"Model_{index}"

    if timestamp_column:
        rename_mapping[timestamp_column] = "Timestamp"

    prepared = prepared.rename(columns=rename_mapping)

    if "Timestamp" in prepared.columns:
        prepared["Timestamp"] = pd.to_datetime(
            prepared["Timestamp"],
            errors="coerce",
        )

    prepared["Actual"] = pd.to_numeric(
        prepared["Actual"],
        errors="coerce",
    )

    model_columns = [
        f"Model_{index}"
        for index in range(1, len(model_prediction_columns) + 1)
    ]

    for column in model_columns:
        prepared[column] = pd.to_numeric(
            prepared[column],
            errors="coerce",
        )

    numeric_columns = ["Actual"] + model_columns

    prepared[numeric_columns] = prepared[numeric_columns].replace(
        [np.inf, -np.inf],
        np.nan,
    )

    required_valid_columns = ["Actual"] + model_columns

    prepared = prepared.dropna(
        subset=required_valid_columns
    )

    if "Timestamp" in prepared.columns:
        prepared = prepared.dropna(subset=["Timestamp"])

        prepared = prepared.sort_values(
            "Timestamp"
        ).reset_index(drop=True)

    else:
        prepared = prepared.reset_index(drop=True)

    if len(prepared) < ENSEMBLE_BLEND_MINIMUM_ROWS:
        raise ValueError(
            "At least two complete observations are required "
            "for ensemble evaluation."
        )

    prepared.attrs["model_mapping"] = {
        f"Model_{index}": original_column
        for index, original_column in enumerate(
            model_prediction_columns,
            start=1,
        )
    }

    return prepared, model_columns


def calculate_ensemble_blend_metrics(actual, predicted):
    """Calculate forecast error metrics for aligned numeric arrays."""

    actual_values = np.asarray(actual, dtype=float)
    predicted_values = np.asarray(predicted, dtype=float)

    valid_mask = (
        np.isfinite(actual_values)
        & np.isfinite(predicted_values)
    )

    actual_values = actual_values[valid_mask]
    predicted_values = predicted_values[valid_mask]

    if len(actual_values) == 0:
        return {
            "Observations": 0,
            "MAE": np.nan,
            "RMSE": np.nan,
            "WAPE (%)": np.nan,
        }

    errors = predicted_values - actual_values
    absolute_errors = np.abs(errors)

    mae = float(np.mean(absolute_errors))

    rmse = float(
        np.sqrt(np.mean(np.square(errors)))
    )

    actual_total = float(
        np.sum(np.abs(actual_values))
    )

    if actual_total > 0:
        wape = float(
            np.sum(absolute_errors) / actual_total * 100
        )
    else:
        wape = np.nan

    return {
        "Observations": int(len(actual_values)),
        "MAE": mae,
        "RMSE": rmse,
        "WAPE (%)": wape,
    }


def build_ensemble_blend_predictions(
    prepared,
    model_columns,
    model_weights,
):
    """
    Combine model predictions using non-negative weights.

    Formula:
        Ensemble = sum(prediction * weight) / sum(weights)

    A zero total weight is not allowed.
    """

    if prepared is None or prepared.empty:
        raise ValueError("No prepared observations are available.")

    if not model_columns:
        raise ValueError("No model prediction columns are available.")

    missing_columns = [
        column
        for column in model_columns
        if column not in prepared.columns
    ]

    if missing_columns:
        raise ValueError(
            f"Missing prediction columns: {', '.join(missing_columns)}"
        )

    weights = {}

    for column in model_columns:
        try:
            weight = float(model_weights.get(column, 0))
        except (TypeError, ValueError):
            raise ValueError(
                f"Invalid weight for {column}."
            )

        if not np.isfinite(weight) or weight < 0:
            raise ValueError(
                "Weights must be finite, non-negative numbers."
            )

        weights[column] = weight

    total_weight = sum(weights.values())

    if total_weight <= 0:
        raise ValueError(
            "At least one model must have a positive weight."
        )

    result = prepared.copy()

    weighted_predictions = np.zeros(
        len(result),
        dtype=float,
    )

    for column in model_columns:
        weighted_predictions += (
            result[column].to_numpy(dtype=float)
            * weights[column]
        )

    result["Ensemble_Prediction"] = (
        weighted_predictions / total_weight
    )

    return result, weights


def evaluate_ensemble_blend_models(
    prepared,
    model_columns,
):
    """Evaluate each individual model on the same observations."""

    evaluation_rows = []

    for column in model_columns:
        metrics = calculate_ensemble_blend_metrics(
            prepared["Actual"],
            prepared[column],
        )

        evaluation_rows.append({
            "Model": column,
            "Model Type": "Individual",
            **metrics,
        })

    return pd.DataFrame(evaluation_rows)


def build_ensemble_blend_comparison(
    prepared,
    model_columns,
    model_weights,
):
    """Compare individual predictions against the weighted ensemble."""

    individual_results = evaluate_ensemble_blend_models(
        prepared,
        model_columns,
    )

    blended_data, validated_weights = (
        build_ensemble_blend_predictions(
            prepared,
            model_columns,
            model_weights,
        )
    )

    ensemble_metrics = calculate_ensemble_blend_metrics(
        blended_data["Actual"],
        blended_data["Ensemble_Prediction"],
    )

    ensemble_row = {
        "Model": "Weighted Ensemble",
        "Model Type": "Ensemble",
        **ensemble_metrics,
    }

    comparison = pd.concat(
        [
            individual_results,
            pd.DataFrame([ensemble_row]),
        ],
        ignore_index=True,
    )

    return blended_data, comparison, validated_weights


def rank_ensemble_blend_models(
    comparison,
    ranking_metric="WAPE (%)",
):
    """Rank models by the selected error metric, lowest first."""

    supported_metrics = [
        "MAE",
        "RMSE",
        "WAPE (%)",
    ]

    if ranking_metric not in supported_metrics:
        raise ValueError(
            f"Choose a supported ranking metric: "
            f"{', '.join(supported_metrics)}"
        )

    if comparison is None or comparison.empty:
        return pd.DataFrame()

    ranked = comparison.copy()

    ranked[ranking_metric] = pd.to_numeric(
        ranked[ranking_metric],
        errors="coerce",
    )

    ranked = ranked.sort_values(
        ranking_metric,
        ascending=True,
        na_position="last",
    ).reset_index(drop=True)

    ranked.insert(
        0,
        "Rank",
        np.arange(1, len(ranked) + 1),
    )

    return ranked


def render_ensemble_blend_center():
    """Render the interactive ensemble simulator."""

    st.header("Forecast Ensemble & Model Blend Simulator")

    st.caption(
        "Combine existing model predictions using adjustable weights. "
        "Evaluation is limited to the uploaded observations."
    )

    st.info(
        "Upload a CSV containing actual values and predictions from "
        "at least one model. For a fair comparison, all models must "
        "refer to the same observations and forecasting horizon."
    )

    uploaded_file = st.file_uploader(
        "Upload aligned model predictions (CSV)",
        type=["csv"],
        key="ensemble_blend_upload",
    )

    if uploaded_file is None:
        st.write(
            "Expected structure: optional Timestamp, one Actual column, "
            "and separate prediction columns for each model."
        )
        return

    try:
        raw_data = pd.read_csv(uploaded_file)
    except Exception as error:
        st.error(f"Unable to read the uploaded CSV: {error}")
        return

    if raw_data.empty:
        st.warning("The uploaded CSV has no data rows.")
        return

    st.write("**Uploaded dataset preview**")
    st.dataframe(
        raw_data.head(10),
        use_container_width=True,
    )

    columns = list(raw_data.columns)

    timestamp_options = ["No timestamp"] + columns

    timestamp_selection = st.selectbox(
        "Timestamp column (optional)",
        timestamp_options,
        key="ensemble_blend_timestamp",
    )

    timestamp_column = (
        None
        if timestamp_selection == "No timestamp"
        else timestamp_selection
    )

    actual_column = st.selectbox(
        "Actual values column",
        columns,
        key="ensemble_blend_actual",
    )

    prediction_candidates = [
        column
        for column in columns
        if column != actual_column
        and column != timestamp_column
    ]

    if not prediction_candidates:
        st.warning(
            "The CSV must contain at least one prediction column "
            "besides the selected actual and timestamp columns."
        )
        return

    model_prediction_columns = st.multiselect(
        "Select model prediction columns",
        prediction_candidates,
        default=prediction_candidates[:min(3, len(prediction_candidates))],
        key="ensemble_blend_prediction_columns",
    )

    if not model_prediction_columns:
        st.warning("Select at least one model prediction column.")
        return

    try:
        prepared, model_columns = prepare_ensemble_blend_data(
            raw_data,
            timestamp_column,
            actual_column,
            model_prediction_columns,
        )
    except Exception as error:
        st.error(f"Dataset preparation failed: {error}")
        return

    st.success(
        f"Prepared {len(prepared):,} complete observations "
        f"for {len(model_columns)} model(s)."
    )

    st.subheader("Model weights")

    st.caption(
        "A higher weight gives that model more influence on the blend. "
        "Weights are user-selected, not automatically learned."
    )

    model_weights = {}

    weight_columns = st.columns(
        min(3, len(model_columns))
    )

    for index, column in enumerate(model_columns):
        with weight_columns[index % len(weight_columns)]:
            original_name = model_prediction_columns[index]

            model_weights[column] = st.number_input(
                f"Weight â€” {original_name}",
                min_value=0.0,
                max_value=100.0,
                value=1.0,
                step=0.25,
                key=f"ensemble_blend_weight_{index}",
            )

    ranking_metric = st.selectbox(
        "Rank models using",
        ["WAPE (%)", "MAE", "RMSE"],
        key="ensemble_blend_ranking_metric",
    )

    try:
        blended_data, comparison, validated_weights = (
            build_ensemble_blend_comparison(
                prepared,
                model_columns,
                model_weights,
            )
        )
    except Exception as error:
        st.error(f"Unable to calculate ensemble: {error}")
        return

    ranked = rank_ensemble_blend_models(
        comparison,
        ranking_metric,
    )

    st.subheader("Ensemble performance")

    ensemble_row = comparison[
        comparison["Model Type"] == "Ensemble"
    ]

    metrics_row = ensemble_row.iloc[0]

    metric_columns = st.columns(4)

    metric_columns[0].metric(
        "Observations",
        format_number(metrics_row["Observations"]),
    )

    metric_columns[1].metric(
        "Ensemble MAE",
        format_number(metrics_row["MAE"]),
    )

    metric_columns[2].metric(
        "Ensemble RMSE",
        format_number(metrics_row["RMSE"]),
    )

    metric_columns[3].metric(
        "Ensemble WAPE",
        (
            f"{metrics_row['WAPE (%)']:.2f}%"
            if pd.notna(metrics_row["WAPE (%)"])
            else "N/A"
        ),
    )

    st.subheader("Individual model vs ensemble")

    st.dataframe(
        ranked,
        use_container_width=True,
        hide_index=True,
    )

    if "Timestamp" in blended_data.columns:
        chart_data = blended_data.set_index("Timestamp")[
            ["Actual", "Ensemble_Prediction"]
        ]
    else:
        chart_data = blended_data[
            ["Actual", "Ensemble_Prediction"]
        ].reset_index(drop=True)

    st.line_chart(chart_data)

    st.subheader("Selected blend weights")

    weight_report = pd.DataFrame([
        {
            "Model": model_prediction_columns[index],
            "Internal Column": column,
            "Weight": validated_weights[column],
            "Normalized Weight (%)": (
                validated_weights[column]
                / sum(validated_weights.values())
                * 100
            ),
        }
        for index, column in enumerate(model_columns)
    ])

    st.dataframe(
        weight_report,
        use_container_width=True,
        hide_index=True,
    )

    st.subheader("Download results")

    export_columns = []

    if "Timestamp" in blended_data.columns:
        export_columns.append("Timestamp")

    export_columns.extend(
        ["Actual"] + model_columns + ["Ensemble_Prediction"]
    )

    prediction_export = blended_data[export_columns].copy()

    st.download_button(
        "Download aligned predictions (CSV)",
        data=prediction_export.to_csv(
            index=False
        ).encode("utf-8"),
        file_name="ensemble_blend_predictions.csv",
        mime="text/csv",
        key="ensemble_blend_predictions_download",
    )

    st.download_button(
        "Download model comparison (CSV)",
        data=ranked.to_csv(
            index=False
        ).encode("utf-8"),
        file_name="ensemble_blend_model_comparison.csv",
        mime="text/csv",
        key="ensemble_blend_comparison_download",
    )

    st.caption(
        "Interpretation note: a lower error indicates a closer match "
        "to the supplied actual values. This comparison does not prove "
        "that the blend will perform better on future, unseen data. "
        "Use a held-out test period to assess generalization."
    )


