AUTOMATED_REPORT_VERSION = "1.0.0"
AUTOMATED_REPORT_MAX_ROWS = 1000


def prepare_automated_report_data(dataframe):
    """Prepare ticket data for automated reporting."""

    required_columns = [
        "Timestamp",
        "Sales Count",
        "Redemption Count",
    ]

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    missing_columns = [
        column
        for column in required_columns
        if column not in dataframe.columns
    ]

    if missing_columns:
        raise ValueError(
            "Missing required columns: "
            + ", ".join(missing_columns)
        )

    prepared = dataframe[required_columns].copy()

    prepared["Timestamp"] = pd.to_datetime(
        prepared["Timestamp"],
        errors="coerce",
    )

    for column in ["Sales Count", "Redemption Count"]:
        prepared[column] = pd.to_numeric(
            prepared[column],
            errors="coerce",
        )

    prepared[["Sales Count", "Redemption Count"]] = (
        prepared[["Sales Count", "Redemption Count"]].replace(
            [np.inf, -np.inf],
            np.nan,
        )
    )

    prepared = prepared.dropna(
        subset=["Timestamp"]
    )

    prepared = prepared.sort_values(
        "Timestamp"
    ).reset_index(drop=True)

    return prepared


def calculate_automated_report_summary(dataframe):
    """Calculate descriptive statistics for the ticket dataset."""

    prepared = prepare_automated_report_data(dataframe)

    if prepared.empty:
        return {
            "status": "Unavailable",
            "message": "No valid timestamped records are available.",
        }

    summary = {
        "status": "Available",
        "record_count": int(len(prepared)),
        "start_date": prepared["Timestamp"].min(),
        "end_date": prepared["Timestamp"].max(),
        "unique_dates": int(
            prepared["Timestamp"].dt.date.nunique()
        ),
    }

    for column in ["Sales Count", "Redemption Count"]:
        values = prepared[column].dropna()

        summary[f"{column}_total"] = (
            float(values.sum()) if not values.empty else np.nan
        )

        summary[f"{column}_mean_per_record"] = (
            float(values.mean()) if not values.empty else np.nan
        )

        summary[f"{column}_median_per_record"] = (
            float(values.median()) if not values.empty else np.nan
        )

        summary[f"{column}_missing"] = int(
            prepared[column].isna().sum()
        )

        summary[f"{column}_negative"] = int(
            prepared[column].lt(0).sum()
        )

    return summary


def collect_automated_report_model_metrics(
    dataframe,
    model_column,
    actual_column,
    predicted_column,
):
    """Evaluate a model using explicitly selected actual and prediction columns."""

    required_columns = [
        actual_column,
        predicted_column,
    ]

    if dataframe is None or dataframe.empty:
        raise ValueError("The evaluation dataset is empty.")

    missing_columns = [
        column
        for column in required_columns
        if column not in dataframe.columns
    ]

    if missing_columns:
        raise ValueError(
            "Missing columns: " + ", ".join(missing_columns)
        )

    evaluation = dataframe[
        required_columns
    ].copy()

    evaluation["Actual"] = pd.to_numeric(
        evaluation[actual_column],
        errors="coerce",
    )

    evaluation["Predicted"] = pd.to_numeric(
        evaluation[predicted_column],
        errors="coerce",
    )

    evaluation[["Actual", "Predicted"]] = (
        evaluation[["Actual", "Predicted"]].replace(
            [np.inf, -np.inf],
            np.nan,
        )
    )

    evaluation = evaluation.dropna(
        subset=["Actual", "Predicted"]
    )

    if len(evaluation) < 2:
        raise ValueError(
            "At least two valid actual-predicted pairs are required."
        )

    metrics = calculate_ensemble_blend_metrics(
        evaluation["Actual"],
        evaluation["Predicted"],
    )

    return {
        "Model": str(model_column),
        **metrics,
    }, evaluation


def generate_automated_report_insights(summary):
    """Generate cautious, data-based descriptive observations."""

    insights = []

    if summary.get("status") != "Available":
        return [
            "A dataset summary could not be generated.",
            "Check the dataset path, required columns and timestamps.",
        ]

    insights.append(
        f"The prepared dataset contains "
        f"{summary['record_count']:,} timestamp-valid records."
    )

    insights.append(
        f"The records cover "
        f"{summary['unique_dates']:,} distinct calendar dates."
    )

    for column in ["Sales Count", "Redemption Count"]:
        total = summary.get(f"{column}_total", np.nan)
        missing = summary.get(f"{column}_missing", 0)
        negative = summary.get(f"{column}_negative", 0)

        if pd.notna(total):
            insights.append(
                f"{column} total across valid numeric records: "
                f"{total:,.2f}."
            )

        if missing:
            insights.append(
                f"{column} contains {missing:,} missing or "
                "non-numeric values."
            )

        if negative:
            insights.append(
                f"{column} contains {negative:,} negative values "
                "that should be reviewed."
            )

    insights.append(
        "Ticket sales and redemptions are used as demand indicators; "
        "they do not independently establish actual ferry boardings "
        "or vessel occupancy."
    )

    return insights


def build_automated_report_text(
    summary,
    insights,
    model_metrics=None,
):
    """Create a plain-text report for download."""

    lines = [
        "FERRY DEMAND INTELLIGENCE",
        "AUTOMATED REPORT",
        "=" * 60,
        f"Report version: {AUTOMATED_REPORT_VERSION}",
        f"Generated at: {datetime.now().isoformat(timespec='seconds')}",
        "",
        "1. DATASET SUMMARY",
        "-" * 60,
    ]

    if summary.get("status") == "Available":
        lines.extend([
            f"Valid timestamped records: {summary['record_count']:,}",
            f"First timestamp: {summary['start_date']}",
            f"Last timestamp: {summary['end_date']}",
            f"Distinct calendar dates: {summary['unique_dates']:,}",
        ])

        for column in ["Sales Count", "Redemption Count"]:
            lines.append(
                f"{column} total: "
                f"{summary.get(f'{column}_total', np.nan):,.2f}"
            )
            lines.append(
                f"{column} average per valid record: "
                f"{summary.get(f'{column}_mean_per_record', np.nan):,.4f}"
            )
    else:
        lines.append(
            summary.get("message", "Dataset summary unavailable.")
        )

    lines.extend([
        "",
        "2. DATA-BASED INSIGHTS",
        "-" * 60,
    ])

    lines.extend(
        f"- {insight}"
        for insight in insights
    )

    lines.extend([
        "",
        "3. FORECAST EVALUATION",
        "-" * 60,
    ])

    if model_metrics:
        for key, value in model_metrics.items():
            if isinstance(value, (int, float, np.integer, np.floating)):
                if pd.notna(value):
                    lines.append(f"{key}: {value:,.4f}")
                else:
                    lines.append(f"{key}: Unavailable")
            else:
                lines.append(f"{key}: {value}")
    else:
        lines.append(
            "Forecast metrics were not supplied for this report."
        )

    lines.extend([
        "",
        "4. INTERPRETATION LIMITATIONS",
        "-" * 60,
        "- Descriptive statistics do not prove future demand.",
        "- Forecast metrics require actual and predicted observations.",
        "- Evaluation on training data may overstate model performance.",
        "- Ticket counts are not verified passenger boarding counts.",
    ])

    return "\n".join(lines)


