def render_forecast_intelligence_metric_cards(
    model_metrics,
):
    """Render a compact summary of the best available evaluation."""

    if model_metrics is None or model_metrics.empty:
        st.info(
            "No evaluation metrics are available."
        )
        return

    available = model_metrics.copy()

    available["WAPE (%)"] = pd.to_numeric(
        available["WAPE (%)"],
        errors="coerce",
    )

    valid_wape = available.dropna(
        subset=["WAPE (%)"]
    )

    if not valid_wape.empty:
        best = valid_wape.sort_values(
            "WAPE (%)"
        ).iloc[0]

        st.success(
            f"Lowest observed WAPE: {best['Model']} "
            f"({best['WAPE (%)']:.2f}%)."
        )

    else:
        st.info(
            "WAPE is unavailable for all evaluated models."
        )

    first = model_metrics.iloc[0]

    columns = st.columns(4)

    columns[0].metric(
        "Models evaluated",
        format_number(
            len(model_metrics)
        ),
    )

    columns[1].metric(
        "Observations",
        format_number(
            first.get("Observations", 0)
        ),
    )

    columns[2].metric(
        "MAE",
        format_number(
            first.get("MAE", np.nan)
        ),
    )

    columns[3].metric(
        "RMSE",
        format_number(
            first.get("RMSE", np.nan)
        ),
    )


def render_forecast_intelligence_actual_predicted_chart(
    prepared,
):
    """Render actual and predicted observations."""

    if prepared is None or prepared.empty:
        st.info(
            "No observations are available for charting."
        )
        return

    chart_data = prepared.copy()

    if "Timestamp" in chart_data.columns:
        chart_data = chart_data.sort_values(
            "Timestamp"
        ).set_index(
            "Timestamp"
        )

    else:
        chart_data = chart_data.reset_index(
            drop=True
        )

        chart_data.index.name = "Observation"

    if "Model" in chart_data.columns:
        models = chart_data["Model"].dropna().unique()

        if len(models) == 1:
            chart_data = chart_data[
                ["Actual", "Predicted"]
            ]

            st.line_chart(
                chart_data
            )

        else:
            selected_model = st.selectbox(
                "Choose model to visualize",
                sorted(models.astype(str)),
                key="forecast_intelligence_chart_model",
            )

            chart_data["Model"] = (
                chart_data["Model"].astype(str)
            )

            selected = chart_data[
                chart_data["Model"] == selected_model
            ][["Actual", "Predicted"]]

            st.line_chart(
                selected
            )

    else:
        st.line_chart(
            chart_data[["Actual", "Predicted"]]
        )


def render_forecast_intelligence_residual_chart(
    prepared,
):
    """Render residuals in chronological or observation order."""

    if prepared is None or prepared.empty:
        st.info(
            "No residuals are available."
        )
        return

    chart_data = prepared.copy()

    if "Model" in chart_data.columns:
        models = sorted(
            chart_data["Model"].dropna().astype(str).unique()
        )

        if not models:
            st.info(
                "No valid model labels are available."
            )
            return

        selected_model = st.selectbox(
            "Model for residual analysis",
            models,
            key="forecast_intelligence_residual_model",
        )

        chart_data["Model"] = (
            chart_data["Model"].astype(str)
        )

        chart_data = chart_data[
            chart_data["Model"] == selected_model
        ]

    if "Timestamp" in chart_data.columns:
        chart_data = chart_data.sort_values(
            "Timestamp"
        ).set_index(
            "Timestamp"
        )

    else:
        chart_data = chart_data.reset_index(
            drop=True
        )

        chart_data.index.name = "Observation"

    st.line_chart(
        chart_data[["Residual"]]
    )


def render_forecast_intelligence_period_chart(
    period_report,
):
    """Visualize time-based forecast error metrics."""

    if period_report is None or period_report.empty:
        st.info(
            "Timestamped observations are required for period analysis."
        )
        return

    st.write(
        "Weekly MAE and RMSE"
    )

    if "Model" in period_report.columns:
        models = sorted(
            period_report["Model"].dropna().astype(str).unique()
        )

        if len(models) > 1:
            selected_model = st.selectbox(
                "Model for weekly trend",
                models,
                key="forecast_intelligence_period_model",
            )

            period_report = period_report[
                period_report["Model"].astype(str)
                == selected_model
            ]

    chart_data = period_report.copy()

    chart_data["Period"] = pd.to_datetime(
        chart_data["Period"],
        errors="coerce",
    )

    chart_data = chart_data.dropna(
        subset=["Period"]
    )

    chart_data = chart_data.sort_values(
        "Period"
    ).set_index(
        "Period"
    )

    metric_columns = [
        column
        for column in ["MAE", "RMSE"]
        if column in chart_data.columns
    ]

    if metric_columns:
        st.line_chart(
            chart_data[metric_columns]
        )


