def forecast_intelligence_dataframe_to_csv(
    dataframe,
):
    """Convert a DataFrame into UTF-8 CSV bytes."""

    if dataframe is None:
        dataframe = pd.DataFrame()

    return dataframe.to_csv(
        index=False
    ).encode(
        "utf-8"
    )


def build_forecast_intelligence_summary_table(
    report,
):
    """Create a compact report summary suitable for CSV export."""

    rows = [
        {
            "Section": "Report",
            "Metric": "Version",
            "Value": report.get("version"),
        },
        {
            "Section": "Report",
            "Metric": "Generated At",
            "Value": report.get("generated_at"),
        },
        {
            "Section": "Dataset",
            "Metric": "Observations",
            "Value": report.get("observations"),
        },
        {
            "Section": "Dataset",
            "Metric": "Models Evaluated",
            "Value": report.get("models_evaluated"),
        },
        {
            "Section": "Ranking",
            "Metric": "Selected Metric",
            "Value": report.get("ranking_metric"),
        },
    ]

    for index, insight in enumerate(
        report.get("insights", []),
        start=1,
    ):
        rows.append({
            "Section": "Insight",
            "Metric": f"Insight {index}",
            "Value": insight,
        })

    for index, recommendation in enumerate(
        report.get("recommendations", []),
        start=1,
    ):
        rows.append({
            "Section": "Recommendation",
            "Metric": f"Recommendation {index}",
            "Value": recommendation,
        })

    return pd.DataFrame(
        rows
    )


