def render_forecast_intelligence_center():
    """Render the complete advanced forecast evaluation workspace."""

    st.header(
        "Advanced Forecast Intelligence & Decision Support"
    )

    st.caption(
        f"Module version {FORECAST_INTELLIGENCE_VERSION} | "
        "Evaluation, residual diagnostics, model ranking and exports"
    )

    st.info(
        "Upload historical actual values and existing model predictions. "
        "This center evaluates supplied forecasts; it does not train "
        "models or generate future predictions."
    )

    uploaded_file = st.file_uploader(
        "Upload forecast evaluation CSV",
        type=["csv"],
        key="forecast_intelligence_upload",
    )

    if uploaded_file is None:
        st.write(
            "Expected columns: actual values, predicted values, "
            "and optionally timestamp and model name."
        )
        return

    try:
        raw_data = pd.read_csv(
            uploaded_file
        )
    except Exception as error:
        st.error(
            f"Unable to read uploaded CSV: {error}"
        )
        return

    if raw_data.empty:
        st.warning(
            "The uploaded CSV contains no data rows."
        )
        return

    st.subheader(
        "Uploaded dataset"
    )

    st.write(
        f"Rows: {len(raw_data):,} | "
        f"Columns: {len(raw_data.columns):,}"
    )

    st.dataframe(
        raw_data.head(10),
        use_container_width=True,
        hide_index=True,
    )

    suggestions = (
        identify_forecast_intelligence_columns(
            raw_data
        )
    )

    columns = list(
        raw_data.columns
    )

    timestamp_options = [
        "No timestamp"
    ] + columns

    model_options = [
        "Single model / no model column"
    ] + columns

    default_actual = (
        suggestions["Actual"]
        if suggestions["Actual"] in columns
        else columns[0]
    )

    default_predicted = (
        suggestions["Predicted"]
        if suggestions["Predicted"] in columns
        else (
            columns[1]
            if len(columns) > 1
            else columns[0]
        )
    )

    timestamp_index = (
        timestamp_options.index(
            suggestions["Timestamp"]
        )
        if suggestions["Timestamp"] in columns
        else 0
    )

    model_index = (
        model_options.index(
            suggestions["Model"]
        )
        if suggestions["Model"] in columns
        else 0
    )

    with st.expander(
        "Column mapping",
        expanded=True,
    ):
        timestamp_selection = st.selectbox(
            "Timestamp column",
            timestamp_options,
            index=timestamp_index,
            key="forecast_intelligence_timestamp_column",
        )

        actual_column = st.selectbox(
            "Actual values column",
            columns,
            index=columns.index(
                default_actual
            ),
            key="forecast_intelligence_actual_column",
        )

        predicted_candidates = [
            column
            for column in columns
            if column != actual_column
        ]

        if not predicted_candidates:
            st.error(
                "Select a dataset containing separate actual "
                "and predicted columns."
            )
            return

        predicted_default = (
            default_predicted
            if default_predicted in predicted_candidates
            else predicted_candidates[0]
        )

        predicted_column = st.selectbox(
            "Predicted values column",
            predicted_candidates,
            index=predicted_candidates.index(
                predicted_default
            ),
            key="forecast_intelligence_predicted_column",
        )

        model_selection = st.selectbox(
            "Model column",
            model_options,
            index=model_index,
            key="forecast_intelligence_model_column",
        )

    timestamp_column = (
        None
        if timestamp_selection == "No timestamp"
        else timestamp_selection
    )

    model_column = (
        None
        if model_selection == "Single model / no model column"
        else model_selection
    )

    if actual_column == predicted_column:
        st.error(
            "Actual and predicted columns must be different."
        )
        return

    if timestamp_column in [
        actual_column,
        predicted_column,
    ]:
        st.error(
            "Timestamp cannot be the actual or predicted column."
        )
        return

    if model_column in [
        actual_column,
        predicted_column,
        timestamp_column,
    ]:
        st.error(
            "Model column must be separate from timestamp, actual "
            "and predicted columns."
        )
        return

    try:
        prepared = prepare_forecast_intelligence_data(
            raw_data,
            actual_column=actual_column,
            predicted_column=predicted_column,
            timestamp_column=timestamp_column,
            model_column=model_column,
        )
    except Exception as error:
        st.error(
            f"Data preparation failed: {error}"
        )
        return

    original_rows = raw_data.shape[0]

    st.success(
        f"Prepared {len(prepared):,} valid observations. "
        f"{original_rows - len(prepared):,} original rows were excluded."
    )

    st.subheader(
        "Evaluation configuration"
    )

    config_columns = st.columns(3)

    with config_columns[0]:
        ranking_metric = st.selectbox(
            "Model ranking metric",
            FORECAST_INTELLIGENCE_RANKING_METRICS,
            index=0,
            key="forecast_intelligence_ranking_metric",
        )

    with config_columns[1]:
        low_threshold = st.number_input(
            "Low WAPE upper threshold (%)",
            min_value=0.0,
            max_value=1000.0,
            value=5.0,
            step=1.0,
            key="forecast_intelligence_low_threshold",
        )

    with config_columns[2]:
        moderate_threshold = st.number_input(
            "Moderate WAPE upper threshold (%)",
            min_value=0.0,
            max_value=1000.0,
            value=10.0,
            step=1.0,
            key="forecast_intelligence_moderate_threshold",
        )

    high_threshold = st.number_input(
        "High WAPE upper threshold (%)",
        min_value=0.0,
        max_value=1000.0,
        value=20.0,
        step=1.0,
        key="forecast_intelligence_high_threshold",
    )

    if not (
        low_threshold
        <= moderate_threshold
        <= high_threshold
    ):
        st.error(
            "Thresholds must satisfy Low â‰¤ Moderate â‰¤ High."
        )
        return

    try:
        report = build_forecast_intelligence_report(
            prepared,
            ranking_metric=ranking_metric,
            low_threshold=low_threshold,
            moderate_threshold=moderate_threshold,
            high_threshold=high_threshold,
        )
    except Exception as error:
        st.error(
            f"Unable to build the intelligence report: {error}"
        )
        return

    st.divider()

    st.subheader(
        "Evaluation overview"
    )

    render_forecast_intelligence_metric_cards(
        report["model_metrics"]
    )

    tab_metrics, tab_residuals, tab_periods, tab_decisions, tab_exports = (
        st.tabs([
            "Model Evaluation",
            "Residual Diagnostics",
            "Time-Based Analysis",
            "Insights & Decisions",
            "Exports",
        ])
    )

    with tab_metrics:
        st.subheader(
            "Model metrics"
        )

        st.dataframe(
            report["model_metrics"],
            use_container_width=True,
            hide_index=True,
        )

        st.subheader(
            "Model ranking"
        )

        st.dataframe(
            report["ranking"],
            use_container_width=True,
            hide_index=True,
        )

        render_forecast_intelligence_actual_predicted_chart(
            prepared
        )

    with tab_residuals:
        st.subheader(
            "Residual summary"
        )

        st.dataframe(
            report["residual_report"],
            use_container_width=True,
            hide_index=True,
        )

        render_forecast_intelligence_residual_chart(
            prepared
        )

        st.subheader(
            "Large forecast errors"
        )

        if report["outliers"].empty:
            st.info(
                "No absolute-error outliers were identified "
                "using the current IQR rule."
            )
        else:
            st.dataframe(
                report["outliers"],
                use_container_width=True,
                hide_index=True,
            )

    with tab_periods:
        if timestamp_column:
            render_forecast_intelligence_period_chart(
                report["period_report"]
            )

            st.subheader(
                "Weekly error table"
            )

            st.dataframe(
                report["period_report"],
                use_container_width=True,
                hide_index=True,
            )

        else:
            st.info(
                "Select a timestamp column to enable "
                "time-based error analysis."
            )

        st.subheader(
            "Rolling error monitoring"
        )

        if model_column is None:
            rolling_window = st.number_input(
                "Rolling window size",
                min_value=2,
                max_value=max(
                    2,
                    min(
                        365,
                        len(prepared),
                    ),
                ),
                value=min(
                    FORECAST_INTELLIGENCE_DEFAULT_ROLLING_WINDOW,
                    max(2, len(prepared)),
                ),
                step=1,
                key="forecast_intelligence_rolling_window",
            )

            try:
                rolling = (
                    calculate_forecast_intelligence_rolling_errors(
                        prepared,
                        window=int(rolling_window),
                    )
                )

                rolling_columns = [
                    column
                    for column in [
                        "Timestamp",
                        "Rolling_MAE",
                        "Rolling_Bias",
                    ]
                    if column in rolling.columns
                ]

                rolling_chart = rolling[
                    rolling_columns
                ].copy()

                if "Timestamp" in rolling_chart.columns:
                    rolling_chart = rolling_chart.set_index(
                        "Timestamp"
                    )

                st.line_chart(
                    rolling_chart[
                        [
                            column
                            for column in [
                                "Rolling_MAE",
                                "Rolling_Bias",
                            ]
                            if column in rolling_chart.columns
                        ]
                    ]
                )

            except Exception as error:
                st.warning(
                    f"Rolling error analysis is unavailable: {error}"
                )
        else:
            st.info(
                "Rolling analysis is available for a single model "
                "in this module. Use model-specific filtering for "
                "separate rolling diagnostics."
            )

    with tab_decisions:
        st.subheader(
            "Configurable evaluation risk"
        )

        st.caption(
            "The thresholds below are configurable heuristics, "
            "not universal quality standards."
        )

        st.dataframe(
            report["risk_report"],
            use_container_width=True,
            hide_index=True,
        )

        render_forecast_intelligence_insights(
            report["insights"]
        )

        render_forecast_intelligence_recommendations(
            report["recommendations"]
        )

    with tab_exports:
        render_forecast_intelligence_exports(
            report,
            prepared,
        )

    st.caption(
        "Forecast evaluation describes the supplied observations. "
        "Model rankings are meaningful only when models are evaluated "
        "on comparable targets and appropriate held-out data."
    )


