PIPELINE_AUDIT_VERSION = "1.0.0"

PIPELINE_AUDIT_HISTORY_PATH = (
    OUTPUT_DIR / "pipeline_audit_history.csv"
)

PIPELINE_AUDIT_CONFIGURATION_PATH = (
    OUTPUT_DIR / "pipeline_audit_configuration.json"
)

PIPELINE_AUDIT_MAX_ARTIFACTS = 5000
PIPELINE_AUDIT_MAX_COMPARISON_ROWS = 1000
PIPELINE_AUDIT_HASH_CHUNK_SIZE = 1024 * 1024

PIPELINE_AUDIT_SCRIPT_EXTENSIONS = {
    ".py",
    ".sh",
    ".bat",
    ".ps1",
}

PIPELINE_AUDIT_IGNORED_DIRECTORIES = {
    ".git",
    ".venv",
    "venv",
    "__pycache__",
    "node_modules",
    ".pytest_cache",
}

PIPELINE_AUDIT_METRIC_CANDIDATES = [
    "MAE",
    "RMSE",
    "WAPE (%)",
    "MAPE (%)",
    "Observations",
    "Records",
    "Duration Seconds",
]


