# 24.1 â€” DIRECTORY AND PATH HELPERS
# ------------------------------------------------------------

def ensure_pipeline_audit_directories():
    """Create directories required by the audit module."""

    OUTPUT_DIR.mkdir(
        parents=True,
        exist_ok=True,
    )

    PIPELINE_AUDIT_HISTORY_PATH.parent.mkdir(
        parents=True,
        exist_ok=True,
    )

    return {
        "output_directory": str(OUTPUT_DIR),
        "history_file": str(
            PIPELINE_AUDIT_HISTORY_PATH
        ),
        "configuration_file": str(
            PIPELINE_AUDIT_CONFIGURATION_PATH
        ),
    }


def normalize_pipeline_audit_path(path_value):
    """Return a normalized absolute path string."""

    if path_value is None:
        return ""

    try:
        return str(
            Path(path_value).expanduser().resolve()
        )
    except (OSError, RuntimeError, TypeError, ValueError):
        return str(path_value)


def is_pipeline_audit_path_inside(
    target_path,
    parent_path,
):
    """Check whether a target path is inside a parent directory."""

    try:
        Path(target_path).resolve().relative_to(
            Path(parent_path).resolve()
        )

        return True

    except (
        ValueError,
        OSError,
        RuntimeError,
    ):
        return False


# ------------------------------------------------------------
# 24.2 â€” FILE FINGERPRINTS
# ------------------------------------------------------------

def calculate_pipeline_audit_file_hash(
    file_path,
    algorithm="sha256",
):
    """
    Calculate a file hash incrementally.

    Large files are read in chunks to avoid loading them
    completely into memory.
    """

    import hashlib

    path = Path(file_path)

    if not path.exists():
        raise FileNotFoundError(
            f"File does not exist: {path}"
        )

    if not path.is_file():
        raise ValueError(
            f"Path is not a file: {path}"
        )

    if algorithm not in hashlib.algorithms_available:
        raise ValueError(
            f"Unsupported hash algorithm: {algorithm}"
        )

    digest = hashlib.new(
        algorithm
    )

    with path.open("rb") as file_handle:
        while True:
            chunk = file_handle.read(
                PIPELINE_AUDIT_HASH_CHUNK_SIZE
            )

            if not chunk:
                break

            digest.update(
                chunk
            )

    return digest.hexdigest()


def build_pipeline_audit_file_metadata(
    file_path,
    include_hash=False,
):
    """Build a metadata record for one file."""

    path = Path(file_path)

    record = {
        "Path": normalize_pipeline_audit_path(
            path
        ),
        "File Name": path.name,
        "Extension": path.suffix.lower(),
        "Exists": path.exists(),
        "Is File": path.is_file(),
        "Size Bytes": np.nan,
        "Modified Time": None,
        "SHA256": None,
        "Hash Status": "Not requested",
    }

    if not path.exists():
        record["Hash Status"] = "File missing"

        return record

    if not path.is_file():
        record["Hash Status"] = "Not a file"

        return record

    try:
        stat_result = path.stat()

        record["Size Bytes"] = int(
            stat_result.st_size
        )

        record["Modified Time"] = datetime.fromtimestamp(
            stat_result.st_mtime
        ).isoformat(
            timespec="seconds"
        )

    except OSError as error:
        record["Metadata Error"] = str(
            error
        )

    if include_hash:
        try:
            record["SHA256"] = (
                calculate_pipeline_audit_file_hash(
                    path,
                    algorithm="sha256",
                )
            )

            record["Hash Status"] = "Calculated"

        except Exception as error:
            record["Hash Status"] = (
                f"Failed: {error}"
            )

    return record


def fingerprint_pipeline_audit_dataset(
    file_path,
    include_hash=True,
):
    """
    Fingerprint a dataset file using metadata and optional SHA-256.

    Hash calculation may take time for very large files.
    """

    path = Path(
        file_path
    ).expanduser()

    if not path.exists():
        return {
            "status": "Missing",
            "path": normalize_pipeline_audit_path(
                path
            ),
            "message": "Dataset file was not found.",
        }

    if not path.is_file():
        return {
            "status": "Invalid",
            "path": normalize_pipeline_audit_path(
                path
            ),
            "message": "Dataset path is not a file.",
        }

    metadata = build_pipeline_audit_file_metadata(
        path,
        include_hash=include_hash,
    )

    return {
        "status": "Available",
        "path": metadata["Path"],
        "file_name": metadata["File Name"],
        "size_bytes": metadata["Size Bytes"],
        "modified_time": metadata["Modified Time"],
        "sha256": metadata["SHA256"],
        "hash_status": metadata["Hash Status"],
        "message": (
            "SHA-256 identifies the file contents; it does not "
            "prove that the data or analysis is correct."
        ),
    }


# ------------------------------------------------------------
# 24.3 â€” PROJECT SCRIPT INVENTORY
# ------------------------------------------------------------

def discover_pipeline_audit_scripts(
    project_directory=None,
    maximum_files=PIPELINE_AUDIT_MAX_ARTIFACTS,
):
    """Discover source scripts without executing them."""

    root = Path(
        project_directory or BASE_DIR
    ).expanduser()

    if not root.exists() or not root.is_dir():
        return pd.DataFrame()

    records = []

    for current_root, directory_names, filenames in os.walk(
        root
    ):
        directory_names[:] = [
            name
            for name in directory_names
            if name not in PIPELINE_AUDIT_IGNORED_DIRECTORIES
        ]

        for filename in filenames:
            path = Path(
                current_root
            ) / filename

            if path.suffix.lower() not in (
                PIPELINE_AUDIT_SCRIPT_EXTENSIONS
            ):
                continue

            try:
                relative_path = path.relative_to(
                    root
                )
            except ValueError:
                relative_path = path

            record = build_pipeline_audit_file_metadata(
                path,
                include_hash=False,
            )

            record["Relative Path"] = str(
                relative_path
            )

            records.append(
                record
            )

            if len(records) >= maximum_files:
                return pd.DataFrame(
                    records
                )

    return pd.DataFrame(
        records
    )


# ------------------------------------------------------------
# 24.4 â€” OUTPUT ARTIFACT INVENTORY
# ------------------------------------------------------------

def inventory_pipeline_audit_artifacts(
    directories=None,
    include_hash=False,
    maximum_files=PIPELINE_AUDIT_MAX_ARTIFACTS,
):
    """Inventory files inside selected output directories."""

    if directories is None:
        directories = [
            OUTPUT_DIR,
            BASE_DIR / "reports",
            BASE_DIR / "models",
            BASE_DIR / "artifacts",
        ]

    records = []
    visited_paths = set()

    for directory in directories:
        root = Path(
            directory
        ).expanduser()

        if not root.exists() or not root.is_dir():
            continue

        for current_root, directory_names, filenames in os.walk(
            root
        ):
            directory_names[:] = [
                name
                for name in directory_names
                if name not in PIPELINE_AUDIT_IGNORED_DIRECTORIES
            ]

            for filename in filenames:
                path = (
                    Path(current_root) / filename
                ).resolve()

                path_key = str(
                    path
                ).lower()

                if path_key in visited_paths:
                    continue

                visited_paths.add(
                    path_key
                )

                record = build_pipeline_audit_file_metadata(
                    path,
                    include_hash=include_hash,
                )

                record["Artifact Category"] = (
                    path.suffix.lower().lstrip(".")
                    or "no extension"
                )

                records.append(
                    record
                )

                if len(records) >= maximum_files:
                    return pd.DataFrame(
                        records
                    )

    return pd.DataFrame(
        records
    )


# ------------------------------------------------------------
# 24.5 â€” DATASET PROFILE SNAPSHOT
# ------------------------------------------------------------

def build_pipeline_audit_dataframe_profile(
    dataframe,
):
    """Create a lightweight structural profile of a DataFrame."""

    if dataframe is None:
        return {
            "status": "Unavailable",
            "reason": "No DataFrame was supplied.",
        }

    column_records = []

    for column in dataframe.columns:
        series = dataframe[column]

        column_records.append({
            "Column": str(column),
            "Dtype": str(series.dtype),
            "Rows": int(len(series)),
            "Missing Count": int(
                series.isna().sum()
            ),
            "Missing Percentage": (
                float(
                    series.isna().mean() * 100
                )
                if len(series) > 0
                else np.nan
            ),
            "Distinct Values": int(
                series.nunique(
                    dropna=True
                )
            ),
        })

    profile = {
        "status": "Available",
        "row_count": int(
            dataframe.shape[0]
        ),
        "column_count": int(
            dataframe.shape[1]
        ),
        "duplicate_rows": int(
            dataframe.duplicated().sum()
        ),
        "memory_usage_bytes": int(
            dataframe.memory_usage(
                index=True,
                deep=True,
            ).sum()
        ),
        "columns": column_records,
    }

    return profile


def pipeline_audit_profile_to_dataframe(
    profile,
):
    """Convert a profile's column metadata to a table."""

    if not profile or profile.get("status") != "Available":
        return pd.DataFrame()

    return pd.DataFrame(
        profile.get(
            "columns",
            [],
        )
    )


# ------------------------------------------------------------
# 24.6 â€” CONFIGURATION SNAPSHOTS
# ------------------------------------------------------------

def sanitize_pipeline_audit_configuration(
    configuration,
):
    """
    Convert configuration into JSON-compatible values.

    Do not put passwords, API keys, tokens or credentials in the
    configuration supplied to this function.
    """

    import json

    if not isinstance(configuration, dict):
        raise ValueError(
            "Configuration must be a dictionary."
        )

    try:
        encoded = json.dumps(
            configuration,
            default=str,
            indent=2,
        )

        decoded = json.loads(
            encoded
        )

    except (TypeError, ValueError) as error:
        raise ValueError(
            f"Configuration is not serializable: {error}"
        )

    return decoded


def save_pipeline_audit_configuration(
    configuration,
    destination=None,
):
    """Save a non-secret configuration snapshot as JSON."""

    import json

    ensure_pipeline_audit_directories()

    target = Path(
        destination or PIPELINE_AUDIT_CONFIGURATION_PATH
    )

    safe_configuration = (
        sanitize_pipeline_audit_configuration(
            configuration
        )
    )

    payload = {
        "audit_version": PIPELINE_AUDIT_VERSION,
        "saved_at": datetime.now().isoformat(
            timespec="seconds"
        ),
        "configuration": safe_configuration,
    }

    target.parent.mkdir(
        parents=True,
        exist_ok=True,
    )

    with target.open(
        "w",
        encoding="utf-8",
    ) as file_handle:
        json.dump(
            payload,
            file_handle,
            ensure_ascii=False,
            indent=2,
        )

    return {
        "path": str(target.resolve()),
        "saved_at": payload["saved_at"],
        "configuration_keys": list(
            safe_configuration.keys()
        ),
    }


def load_pipeline_audit_configuration(
    source=None,
):
    """Load a saved configuration snapshot."""

    import json

    target = Path(
        source or PIPELINE_AUDIT_CONFIGURATION_PATH
    )

    if not target.exists():
        return None

    try:
        with target.open(
            "r",
            encoding="utf-8",
        ) as file_handle:
            payload = json.load(
                file_handle
            )

    except (OSError, ValueError):
        return None

    if not isinstance(payload, dict):
        return None

    return payload


# ------------------------------------------------------------
# 24.7 â€” PIPELINE RUN RECORDS
# ------------------------------------------------------------

def build_pipeline_audit_run_record(
    run_name,
    status,
    start_time,
    end_time,
    dataset_path=None,
    input_rows=None,
    output_rows=None,
    metrics=None,
    notes="",
):
    """Build a normalized audit record for a completed run."""

    start = pd.to_datetime(
        start_time,
        errors="coerce",
    )

    end = pd.to_datetime(
        end_time,
        errors="coerce",
    )

    if pd.isna(start) or pd.isna(end):
        duration_seconds = np.nan
    else:
        duration_seconds = (
            end - start
        ).total_seconds()

        if duration_seconds < 0:
            raise ValueError(
                "End time cannot be earlier than start time."
            )

    allowed_statuses = {
        "Success",
        "Failed",
        "Partial",
        "Skipped",
        "Unknown",
    }

    if status not in allowed_statuses:
        raise ValueError(
            f"Status must be one of: "
            f"{', '.join(sorted(allowed_statuses))}"
        )

    metrics = metrics or {}

    if not isinstance(metrics, dict):
        raise ValueError(
            "Metrics must be supplied as a dictionary."
        )

    record = {
        "Run ID": str(
            uuid.uuid4()
        ),
        "Run Name": str(
            run_name
        ),
        "Status": status,
        "Start Time": str(start),
        "End Time": str(end),
        "Duration Seconds": duration_seconds,
        "Dataset Path": normalize_pipeline_audit_path(
            dataset_path
        ),
        "Input Rows": input_rows,
        "Output Rows": output_rows,
        "Notes": str(notes),
        "Recorded At": datetime.now().isoformat(
            timespec="seconds"
        ),
    }

    for metric_name, metric_value in metrics.items():
        key = str(
            metric_name
        ).strip()

        if not key:
            continue

        # Prefix custom metrics to prevent overwriting core fields.
        record[f"Metric: {key}"] = metric_value

    return record


# ------------------------------------------------------------
# 24.8 â€” RUN HISTORY PERSISTENCE
# ------------------------------------------------------------

def load_pipeline_audit_history(
    history_path=None,
):
    """Read existing audit history without deleting prior records."""

    target = Path(
        history_path or PIPELINE_AUDIT_HISTORY_PATH
    )

    if not target.exists():
        return pd.DataFrame()

    try:
        history = pd.read_csv(
            target
        )
    except Exception as error:
        raise ValueError(
            f"Unable to read pipeline audit history: {error}"
        )

    return history


def append_pipeline_audit_run(
    run_record,
    history_path=None,
):
    """Append a run record to the persistent CSV history."""

    import csv

    ensure_pipeline_audit_directories()

    target = Path(
        history_path or PIPELINE_AUDIT_HISTORY_PATH
    )

    if not isinstance(run_record, dict):
        raise ValueError(
            "Run record must be a dictionary."
        )

    target.parent.mkdir(
        parents=True,
        exist_ok=True,
    )

    history_exists = (
        target.exists()
        and target.stat().st_size > 0
    )

    existing_columns = []

    if history_exists:
        try:
            existing_columns = list(
                pd.read_csv(
                    target,
                    nrows=0,
                ).columns
            )
        except Exception as error:
            raise ValueError(
                f"Unable to inspect existing history: {error}"
            )

    new_columns = list(
        run_record.keys()
    )

    combined_columns = list(
        dict.fromkeys(
            existing_columns + new_columns
        )
    )

    existing_rows = []

    if history_exists:
        existing_rows = load_pipeline_audit_history(
            target
        ).to_dict(
            orient="records"
        )

    existing_ids = {
        str(row.get("Run ID"))
        for row in existing_rows
        if row.get("Run ID") is not None
    }

    if str(run_record.get("Run ID")) in existing_ids:
        raise ValueError(
            "This Run ID already exists in the audit history."
        )

    combined = pd.DataFrame(
        existing_rows + [run_record],
        columns=combined_columns,
    )

    temporary_path = target.with_suffix(
        target.suffix + ".tmp"
    )

    combined.to_csv(
        temporary_path,
        index=False,
        quoting=csv.QUOTE_MINIMAL,
    )

    temporary_path.replace(
        target
    )

    return {
        "path": str(target.resolve()),
        "total_runs": int(
            len(combined)
        ),
        "columns": combined_columns,
    }


# ------------------------------------------------------------
# 24.9 â€” RUN COMPARISON
# ------------------------------------------------------------

def compare_pipeline_audit_run_records(
    first_run,
    second_run,
):
    """Compare two dictionaries representing pipeline run records."""

    if not isinstance(first_run, dict) or not isinstance(
        second_run,
        dict,
    ):
        raise ValueError(
            "Both runs must be dictionaries."
        )

    all_keys = sorted(
        set(first_run.keys())
        | set(second_run.keys())
    )

    comparison_rows = []

    for key in all_keys:
        first_value = first_run.get(
            key,
            np.nan,
        )

        second_value = second_run.get(
            key,
            np.nan,
        )

        if (
            isinstance(first_value, (int, float, np.number))
            and isinstance(second_value, (int, float, np.number))
        ):
            try:
                difference = (
                    float(second_value)
                    - float(first_value)
                )
            except (TypeError, ValueError):
                difference = np.nan
        else:
            difference = np.nan

        comparison_rows.append({
            "Field": key,
            "First Run": first_value,
            "Second Run": second_value,
            "Numeric Difference": difference,
            "Changed": str(first_value) != str(second_value),
        })

    return pd.DataFrame(
        comparison_rows
    )


def compare_pipeline_audit_histories(
    history,
    first_run_id,
    second_run_id,
):
    """Compare two runs selected from the saved history."""

    if history is None or history.empty:
        raise ValueError(
            "Pipeline history is empty."
        )

    if "Run ID" not in history.columns:
        raise ValueError(
            "Run ID column is missing from history."
        )

    first_matches = history[
        history["Run ID"].astype(str)
        == str(first_run_id)
    ]

    second_matches = history[
        history["Run ID"].astype(str)
        == str(second_run_id)
    ]

    if first_matches.empty or second_matches.empty:
        raise ValueError(
            "One or both selected runs were not found."
        )

    first_run = first_matches.iloc[0].to_dict()
    second_run = second_matches.iloc[0].to_dict()

    return compare_pipeline_audit_run_records(
        first_run,
        second_run,
    )


# ------------------------------------------------------------
# 24.10 â€” ARTIFACT CHANGE DETECTION
# ------------------------------------------------------------

def compare_pipeline_audit_artifact_inventories(
    first_inventory,
    second_inventory,
):
    """
    Compare artifact inventories using normalized file paths.

    SHA-256 is required to detect content changes reliably.
    """

    required_columns = [
        "Path",
        "Size Bytes",
        "SHA256",
    ]

    for inventory in [
        first_inventory,
        second_inventory,
    ]:
        if inventory is None or inventory.empty:
            continue

        missing = [
            column
            for column in required_columns
            if column not in inventory.columns
        ]

        if missing:
            raise ValueError(
                "Artifact inventory lacks required columns: "
                + ", ".join(missing)
            )

    first = (
        first_inventory.copy()
        if first_inventory is not None
        else pd.DataFrame()
    )

    second = (
        second_inventory.copy()
        if second_inventory is not None
        else pd.DataFrame()
    )

    for dataframe in [
        first,
        second,
    ]:
        for column in required_columns:
            if column not in dataframe.columns:
                dataframe[column] = np.nan

        dataframe["_Path_Key"] = (
            dataframe["Path"]
            .astype(str)
            .map(
                lambda value: value.lower()
            )
        )

    first_map = {
        row["_Path_Key"]: row
        for _, row in first.iterrows()
    }

    second_map = {
        row["_Path_Key"]: row
        for _, row in second.iterrows()
    }

    all_paths = sorted(
        set(first_map)
        | set(second_map)
    )

    rows = []

    for path_key in all_paths:
        first_row = first_map.get(
            path_key
        )

        second_row = second_map.get(
            path_key
        )

        if first_row is None:
            status = "Added"
        elif second_row is None:
            status = "Removed"
        else:
            first_hash = first_row.get(
                "SHA256"
            )

            second_hash = second_row.get(
                "SHA256"
            )

            if pd.isna(first_hash) or pd.isna(second_hash):
                if str(first_row.get("Size Bytes")) != str(
                    second_row.get("Size Bytes")
                ):
                    status = "Size Changed"
                else:
                    status = "Unverified"
            elif str(first_hash) != str(second_hash):
                status = "Content Changed"
            else:
                status = "Unchanged"

        rows.append({
            "Path": path_key,
            "First Size Bytes": (
                first_row.get("Size Bytes")
                if first_row is not None
                else np.nan
            ),
            "Second Size Bytes": (
                second_row.get("Size Bytes")
                if second_row is not None
                else np.nan
            ),
            "First SHA256": (
                first_row.get("SHA256")
                if first_row is not None
                else None
            ),
            "Second SHA256": (
                second_row.get("SHA256")
                if second_row is not None
                else None
            ),
            "Comparison Status": status,
        })

    return pd.DataFrame(
        rows
    )


# ------------------------------------------------------------
# 24.11 â€” AUDIT CHECKLIST
# ------------------------------------------------------------

def build_pipeline_audit_checklist(
    project_directory=None,
    dataset_path=None,
    artifact_inventory=None,
):
    """Create a basic reproducibility checklist."""

    root = Path(
        project_directory or BASE_DIR
    ).expanduser()

    checks = []

    checks.append({
        "Check": "Project directory exists",
        "Status": (
            "Pass"
            if root.exists() and root.is_dir()
            else "Fail"
        ),
        "Details": str(
            root
        ),
    })

    if dataset_path:
        dataset = Path(
            dataset_path
        ).expanduser()

        checks.append({
            "Check": "Dataset file exists",
            "Status": (
                "Pass"
                if dataset.exists() and dataset.is_file()
                else "Fail"
            ),
            "Details": str(
                dataset
            ),
        })

    requirements_file = (
        root / "requirements.txt"
    )

    checks.append({
        "Check": "Dependency manifest exists",
        "Status": (
            "Pass"
            if requirements_file.exists()
            else "Review"
        ),
        "Details": str(
            requirements_file
        ),
    })

    readme_file = (
        root / "README.md"
    )

    checks.append({
        "Check": "README exists",
        "Status": (
            "Pass"
            if readme_file.exists()
            else "Review"
        ),
        "Details": str(
            readme_file
        ),
    })

    history = load_pipeline_audit_history()

    checks.append({
        "Check": "Run history available",
        "Status": (
            "Pass"
            if not history.empty
            else "Review"
        ),
        "Details": (
            f"{len(history):,} recorded run(s)"
            if not history.empty
            else "No saved audit runs"
        ),
    })

    if artifact_inventory is not None:
        checks.append({
            "Check": "Artifact inventory available",
            "Status": (
                "Pass"
                if not artifact_inventory.empty
                else "Review"
            ),
            "Details": (
                f"{len(artifact_inventory):,} artifact(s)"
            ),
        })

    return pd.DataFrame(
        checks
    )


# ------------------------------------------------------------
# 24.12 â€” AUDIT SUMMARY
# ------------------------------------------------------------

def build_pipeline_audit_summary(
    script_inventory,
    artifact_inventory,
    history,
):
    """Summarize scripts, artifacts and recorded runs."""

    script_count = (
        0
        if script_inventory is None
        else len(script_inventory)
    )

    artifact_count = (
        0
        if artifact_inventory is None
        else len(artifact_inventory)
    )

    run_count = (
        0
        if history is None
        else len(history)
    )

    if (
        history is not None
        and not history.empty
        and "Status" in history.columns
    ):
        status_counts = (
            history["Status"]
            .astype(str)
            .value_counts()
            .to_dict()
        )
    else:
        status_counts = {}

    return {
        "script_count": int(
            script_count
        ),
        "artifact_count": int(
            artifact_count
        ),
        "recorded_run_count": int(
            run_count
        ),
        "run_status_counts": status_counts,
        "audit_version": PIPELINE_AUDIT_VERSION,
    }


