    st.download_button(
        "Download artifact inventory",
        data=filtered.to_csv(
            index=False
        ).encode("utf-8"),
        file_name="pipeline_audit_artifacts.csv",
        mime="text/csv",
        key="pipeline_audit_artifacts_download",
    )


