def render_pipeline_audit_run_recorder():
    """
    Allow a user to record metadata about an already completed run.

    This form does not execute a pipeline.
    """

    st.subheader(
        "Record a completed pipeline run"
    )

    st.caption(
        "Enter details from a run that already happened. "
        "The form does not start scripts or fabricate execution results."
    )

    with st.form(
        "pipeline_audit_run_record_form"
    ):
        run_name = st.text_input(
            "Run name",
            value="Manual pipeline run",
        )

        status = st.selectbox(
            "Observed status",
            [
                "Success",
                "Failed",
                "Partial",
                "Skipped",
                "Unknown",
            ],
        )

        start_time = st.text_input(
            "Start timestamp",
            value=datetime.now().isoformat(
                timespec="seconds"
            ),
            help="Use an ISO-compatible date/time.",
        )

        end_time = st.text_input(
            "End timestamp",
            value=datetime.now().isoformat(
                timespec="seconds"
            ),
            help="Use an ISO-compatible date/time.",
        )

        dataset_path = st.text_input(
            "Dataset path (optional)",
            value=str(
                DEFAULT_DATASET_PATH
            ),
        )

        input_rows = st.number_input(
            "Input row count (optional)",
            min_value=0,
            value=0,
            step=1,
        )

        output_rows = st.number_input(
            "Output row count (optional)",
            min_value=0,
            value=0,
            step=1,
        )

        notes = st.text_area(
            "Notes",
            placeholder=(
                "Record what actually happened, including "
                "any warnings or known limitations."
            ),
        )

        submitted = st.form_submit_button(
            "Save run record"
        )

    if submitted:
        try:
            record = build_pipeline_audit_run_record(
                run_name=run_name,
                status=status,
                start_time=start_time,
                end_time=end_time,
                dataset_path=dataset_path or None,
                input_rows=int(input_rows),
                output_rows=int(output_rows),
                metrics={},
                notes=notes,
            )

            result = append_pipeline_audit_run(
                record
            )

            st.success(
                f"Run record saved. Total recorded runs: "
                f"{result['total_runs']:,}."
            )

        except Exception as error:
            st.error(
                f"Unable to save run record: {error}"
            )


