def render_pipeline_audit_history():
    """Display, filter and export run history."""

    st.subheader(
        "Pipeline run history"
    )

    try:
        history = load_pipeline_audit_history()
    except Exception as error:
        st.error(
            f"Unable to load history: {error}"
        )
        return history if "history" in locals() else pd.DataFrame()

    if history.empty:
        st.info(
            "No run records have been saved yet."
        )
        return history

    filtered = history.copy()

    if "Status" in filtered.columns:
        statuses = sorted(
            filtered["Status"]
            .fillna("Unknown")
            .astype(str)
            .unique()
        )

        selected_statuses = st.multiselect(
            "Filter run status",
            statuses,
            default=statuses,
            key="pipeline_audit_history_status",
        )

        filtered = filtered[
            filtered["Status"]
            .fillna("Unknown")
            .astype(str)
            .isin(selected_statuses)
        ]

    st.dataframe(
        filtered.head(
            PIPELINE_AUDIT_MAX_COMPARISON_ROWS
        ),
        use_container_width=True,
        hide_index=True,
    )

    st.download_button(
        "Download filtered run history",
        data=filtered.to_csv(
            index=False
        ).encode("utf-8"),
        file_name="pipeline_audit_history.csv",
        mime="text/csv",
        key="pipeline_audit_history_download",
    )

    return history


