# 24.19 â€” STREAMLIT: RUN COMPARISON
# ------------------------------------------------------------

def render_pipeline_audit_run_comparison(
    history,
):
    """Compare two previously recorded runs."""

    st.subheader(
        "Compare two recorded runs"
    )

    if history is None or history.empty:
        st.info(
            "Save at least two run records to enable comparison."
        )
        return

    if "Run ID" not in history.columns:
        st.warning(
            "Run ID is unavailable in the saved history."
        )
        return

    run_options = history[
        "Run ID"
    ].astype(str).tolist()

    if len(run_options) < 2:
        st.info(
            "At least two distinct run records are required."
        )
        return

    labels = {}

    for _, row in history.iterrows():
        run_id = str(
            row["Run ID"]
        )

        labels[run_id] = (
            f"{row.get('Run Name', 'Unnamed')} | "
            f"{row.get('Status', 'Unknown')} | {run_id[:8]}"
        )

    first_id = st.selectbox(
        "First run",
        run_options,
        format_func=lambda value: labels.get(
            value,
            value,
        ),
        key="pipeline_audit_compare_first",
    )

    second_options = [
        run_id
        for run_id in run_options
        if run_id != first_id
    ]

    second_id = st.selectbox(
        "Second run",
        second_options,
        format_func=lambda value: labels.get(
            value,
            value,
        ),
        key="pipeline_audit_compare_second",
    )

    try:
        comparison = compare_pipeline_audit_histories(
            history,
            first_id,
            second_id,
        )
    except Exception as error:
        st.error(
            f"Unable to compare runs: {error}"
        )
        return

    st.dataframe(
        comparison,
        use_container_width=True,
        hide_index=True,
    )

    st.download_button(
        "Download run comparison",
        data=comparison.to_csv(
            index=False
        ).encode("utf-8"),
        file_name="pipeline_audit_run_comparison.csv",
        mime="text/csv",
        key="pipeline_audit_run_comparison_download",
    )


