def render_pipeline_audit_checklist(
    project_directory,
    dataset_path,
    artifact_inventory,
):
    """Display basic project reproducibility checks."""

    st.subheader(
        "Reproducibility checklist"
    )

    checklist = build_pipeline_audit_checklist(
        project_directory=project_directory,
        dataset_path=dataset_path,
        artifact_inventory=artifact_inventory,
    )

    if checklist.empty:
        st.info(
            "No checklist items are available."
        )
        return

    st.dataframe(
        checklist,
        use_container_width=True,
        hide_index=True,
    )

    pass_count = int(
        (
            checklist["Status"] == "Pass"
        ).sum()
    )

    fail_count = int(
        (
            checklist["Status"] == "Fail"
        ).sum()
    )

    review_count = int(
        (
            checklist["Status"] == "Review"
        ).sum()
    )

    columns = st.columns(3)

    columns[0].metric(
        "Pass",
        pass_count,
    )

    columns[1].metric(
        "Fail",
        fail_count,
    )

    columns[2].metric(
        "Review",
        review_count,
    )

    st.download_button(
        "Download reproducibility checklist",
        data=checklist.to_csv(
            index=False
        ).encode("utf-8"),
        file_name="pipeline_reproducibility_checklist.csv",
        mime="text/csv",
        key="pipeline_audit_checklist_download",
    )


