# ============================================================
# PART 25 â€” FORECAST ENSEMBLE & MODEL BLEND SIMULATOR
# ============================================================

ENSEMBLE_BLEND_VERSION = "1.0.0"

ENSEMBLE_BLEND_REQUIRED_COLUMNS = [
    "Model",
    "Timestamp",
    "Actual",
    "Predicted",
]

ENSEMBLE_BLEND_MINIMUM_MODELS = 2
ENSEMBLE_BLEND_MINIMUM_ROWS = 2
ENSEMBLE_BLEND_MAXIMUM_DISPLAY_ROWS = 2000

ENSEMBLE_BLEND_SUPPORTED_METRICS = [
    "WAPE",
    "MAE",
    "RMSE",
]


def prepare_ensemble_blend_data(
    dataframe,
    model_column,
    actual_column,
    predicted_column,
    timestamp_column=None,
):
    """
    Standardize uploaded model predictions.

    Required:
        Model name
        Actual observed value
        Predicted value

    Timestamp is optional for reporting, but model predictions
    must align on the same observations before blending.
    """

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    required = [
        model_column,
        actual_column,
        predicted_column,
    ]

    if any(column not in dataframe.columns for column in required):
        return pd.DataFrame()

    columns = required.copy()

    if timestamp_column and timestamp_column in dataframe.columns:
        if timestamp_column not in columns:
            columns.append(timestamp_column)

    result = dataframe[columns].copy()

    rename_map = {
        model_column: "Model",
        actual_column: "Actual",
        predicted_column: "Predicted",
    }

    if timestamp_column and timestamp_column in result.columns:
        rename_map[timestamp_column] = "Timestamp"

    result = result.rename(columns=rename_map)

    result["Model"] = (
        result["Model"]
        .astype("string")
        .str.strip()
    )

    result["Actual"] = pd.to_numeric(
        result["Actual"],
        errors="coerce",
    )

    result["Predicted"] = pd.to_numeric(
        result["Predicted"],
        errors="coerce",
    )

    if "Timestamp" in result.columns:
        result["Timestamp"] = pd.to_datetime(
            result["Timestamp"],
            errors="coerce",
        )

    result = result.replace(
        [np.inf, -np.inf],
        np.nan,
    )

    result = result.dropna(
        subset=["Model", "Actual", "Predicted"]
    )

    result = result[
        result["Model"].astype(str).str.len() > 0
    ]

    if "Timestamp" in result.columns:
        result = result.dropna(subset=["Timestamp"])

    return result.reset_index(drop=True)


def identify_ensemble_blend_alignment(
    dataframe,
):
    """
    Verify that each model uses the same actual observations.

    Timestamp is used as the observation key when available.
    Without timestamps, row positions and actual values must match
    in the same order for every model.
    """

    if dataframe is None or dataframe.empty:
        return {
            "Aligned": False,
            "Reason": "No valid prediction records were provided.",
            "Models": [],
            "Observation_Count": 0,
            "Alignment_Key": None,
        }

    model_names = sorted(
        dataframe["Model"].astype(str).unique().tolist()
    )

    if len(model_names) < ENSEMBLE_BLEND_MINIMUM_MODELS:
        return {
            "Aligned": False,
            "Reason": "At least two different models are required.",
            "Models": model_names,
            "Observation_Count": 0,
            "Alignment_Key": None,
        }

    has_timestamp = "Timestamp" in dataframe.columns

    if has_timestamp:
        alignment_key = ["Timestamp"]
    else:
        alignment_key = ["Actual"]

    grouped = {}

    for model_name in model_names:
        model_data = dataframe[
            dataframe["Model"] == model_name
        ].copy()

        if model_data.empty:
            return {
                "Aligned": False,
                "Reason": f"No valid rows were found for {model_name}.",
                "Models": model_names,
                "Observation_Count": 0,
                "Alignment_Key": alignment_key,
            }

        if has_timestamp:
            model_data = model_data.sort_values(
                "Timestamp"
            )

            if model_data["Timestamp"].duplicated().any():
                return {
                    "Aligned": False,
                    "Reason": (
                        f"{model_name} contains duplicate timestamps. "
                        "Each timestamp must identify one prediction."
                    ),
                    "Models": model_names,
                    "Observation_Count": 0,
                    "Alignment_Key": alignment_key,
                }

        grouped[model_name] = model_data.reset_index(drop=True)

    reference_name = model_names[0]
    reference = grouped[reference_name]

    if len(reference) < ENSEMBLE_BLEND_MINIMUM_ROWS:
        return {
            "Aligned": False,
            "Reason": "At least two aligned observations are required.",
            "Models": model_names,
            "Observation_Count": len(reference),
            "Alignment_Key": alignment_key,
        }

    reference_keys = reference[alignment_key].reset_index(drop=True)
    reference_actual = reference["Actual"].reset_index(drop=True)

    for model_name in model_names[1:]:
        candidate = grouped[model_name]

        if len(candidate) != len(reference):
            return {
                "Aligned": False,
                "Reason": (
                    f"{model_name} has {len(candidate)} rows, "
                    f"but {reference_name} has {len(reference)}. "
                    "All models must use the same observations."
                ),
                "Models": model_names,
                "Observation_Count": 0,
                "Alignment_Key": alignment_key,
            }

        candidate_keys = candidate[
            alignment_key
        ].reset_index(drop=True)

        candidate_actual = candidate[
            "Actual"
        ].reset_index(drop=True)

        if not reference_keys.equals(candidate_keys):
            return {
                "Aligned": False,
                "Reason": (
                    f"Observation keys do not match between "
                    f"{reference_name} and {model_name}."
                ),
                "Models": model_names,
                "Observation_Count": 0,
                "Alignment_Key": alignment_key,
            }

        if not np.allclose(
            reference_actual.to_numpy(dtype=float),
            candidate_actual.to_numpy(dtype=float),
            rtol=1e-7,
            atol=1e-9,
        ):
            return {
                "Aligned": False,
                "Reason": (
                    f"Actual values differ between {reference_name} "
                    f"and {model_name}. Blending is blocked."
                ),
                "Models": model_names,
                "Observation_Count": 0,
                "Alignment_Key": alignment_key,
            }

    return {
        "Aligned": True,
        "Reason": "All models use matching observation keys and actual values.",
        "Models": model_names,
        "Observation_Count": len(reference),
        "Alignment_Key": alignment_key,
    }


def calculate_ensemble_blend_mae(
    actual,
    predicted,
):
    """Calculate mean absolute error."""

    actual_values = np.asarray(actual, dtype=float)
    predicted_values = np.asarray(predicted, dtype=float)

    if len(actual_values) == 0:
        return np.nan

    return float(
        np.mean(
            np.abs(actual_values - predicted_values)
        )
    )


def calculate_ensemble_blend_rmse(
    actual,
    predicted,
):
    """Calculate root mean squared error."""

    actual_values = np.asarray(actual, dtype=float)
    predicted_values = np.asarray(predicted, dtype=float)

    if len(actual_values) == 0:
        return np.nan

    return float(
        np.sqrt(
            np.mean(
                np.square(actual_values - predicted_values)
            )
        )
    )


def calculate_ensemble_blend_wape(
    actual,
    predicted,
):
    """
    Calculate weighted absolute percentage error.

    WAPE = sum(abs(actual - predicted)) / sum(abs(actual)) * 100

    If the denominator is zero, WAPE is undefined.
    """

    actual_values = np.asarray(actual, dtype=float)
    predicted_values = np.asarray(predicted, dtype=float)

    if len(actual_values) == 0:
        return np.nan

    denominator = np.sum(np.abs(actual_values))

    if denominator == 0:
        return np.nan

    numerator = np.sum(
        np.abs(actual_values - predicted_values)
    )

    return float(
        numerator / denominator * 100
    )


def calculate_ensemble_blend_metrics(
    actual,
    predicted,
):
    """Return the supported metrics for one prediction series."""

    return {
        "MAE": calculate_ensemble_blend_mae(
            actual,
            predicted,
        ),
        "RMSE": calculate_ensemble_blend_rmse(
            actual,
            predicted,
        ),
        "WAPE": calculate_ensemble_blend_wape(
            actual,
            predicted,
        ),
    }


def build_ensemble_blend_prediction_matrix(
    dataframe,
):
    """
    Convert long-format predictions into an aligned wide table.

    The function refuses to blend predictions if alignment checks fail.
    """

    alignment = identify_ensemble_blend_alignment(
        dataframe
    )

    if not alignment["Aligned"]:
        return {
            "Success": False,
            "Reason": alignment["Reason"],
            "Alignment": alignment,
            "Predictions": pd.DataFrame(),
        }

    model_names = alignment["Models"]
    has_timestamp = "Timestamp" in dataframe.columns

    reference_name = model_names[0]

    reference = dataframe[
        dataframe["Model"] == reference_name
    ].copy()

    if has_timestamp:
        reference = reference.sort_values(
            "Timestamp"
        ).reset_index(drop=True)

    result = pd.DataFrame()

    if has_timestamp:
        result["Timestamp"] = reference[
            "Timestamp"
        ].to_numpy()

    result["Actual"] = reference[
        "Actual"
    ].to_numpy(dtype=float)

    for model_name in model_names:
        model_data = dataframe[
            dataframe["Model"] == model_name
        ].copy()

        if has_timestamp:
            model_data = model_data.sort_values(
                "Timestamp"
            ).reset_index(drop=True)

        result[model_name] = model_data[
            "Predicted"
        ].to_numpy(dtype=float)

    return {
        "Success": True,
        "Reason": alignment["Reason"],
        "Alignment": alignment,
        "Predictions": result,
    }


def normalize_ensemble_blend_weights(
    model_names,
    requested_weights,
):
    """
    Normalize non-negative weights so their total equals one.

    A model with weight zero contributes nothing to the blend.
    """

    if not model_names:
        return {}

    weights = {}

    for model_name in model_names:
        try:
            value = float(
                requested_weights.get(model_name, 1.0)
            )
        except (TypeError, ValueError):
            value = 0.0

        if not np.isfinite(value):
            value = 0.0

        weights[model_name] = max(0.0, value)

    total_weight = sum(weights.values())

    if total_weight <= 0:
        equal_weight = 1.0 / len(model_names)

        return {
            model_name: equal_weight
            for model_name in model_names
        }

    return {
        model_name: weight / total_weight
        for model_name, weight in weights.items()
    }


def calculate_ensemble_blend_predictions(
    prediction_matrix,
    requested_weights,
):
    """
    Compute a weighted ensemble using aligned model predictions.

    This function combines supplied predictions; it does not train
    models or generate a new future forecast.
    """

    if prediction_matrix is None or prediction_matrix.empty:
        return {
            "Success": False,
            "Reason": "The aligned prediction matrix is empty.",
            "Weights": {},
            "Predictions": pd.DataFrame(),
        }

    if "Actual" not in prediction_matrix.columns:
        return {
            "Success": False,
            "Reason": "The aligned matrix does not contain Actual values.",
            "Weights": {},
            "Predictions": pd.DataFrame(),
        }

    model_names = [
        column
        for column in prediction_matrix.columns
        if column not in ["Timestamp", "Actual"]
    ]

    if len(model_names) < ENSEMBLE_BLEND_MINIMUM_MODELS:
        return {
            "Success": False,
            "Reason": "At least two model prediction columns are required.",
            "Weights": {},
            "Predictions": pd.DataFrame(),
        }

    weights = normalize_ensemble_blend_weights(
        model_names,
        requested_weights,
    )

    result = prediction_matrix.copy()

    blended_values = np.zeros(
        len(result),
        dtype=float,
    )

    for model_name in model_names:
        blended_values += (
            result[model_name].to_numpy(dtype=float)
            * weights[model_name]
        )

    result["Ensemble_Predicted"] = blended_values

    return {
        "Success": True,
        "Reason": "Weighted ensemble predictions calculated.",
        "Weights": weights,
        "Predictions": result,
    }


def build_ensemble_blend_comparison(
    prediction_matrix,
    ensemble_predictions,
):
    """Compare individual models against the weighted ensemble."""

    if prediction_matrix is None or prediction_matrix.empty:
        return pd.DataFrame()

    if ensemble_predictions is None or ensemble_predictions.empty:
        return pd.DataFrame()

    if "Ensemble_Predicted" not in ensemble_predictions.columns:
        return pd.DataFrame()

    actual = ensemble_predictions[
        "Actual"
    ].to_numpy(dtype=float)

    model_names = [
        column
        for column in prediction_matrix.columns
        if column not in ["Timestamp", "Actual"]
    ]

    rows = []

    for model_name in model_names:
        predicted = prediction_matrix[
            model_name
        ].to_numpy(dtype=float)

        metrics = calculate_ensemble_blend_metrics(
            actual,
            predicted,
        )

        rows.append({
            "Model": model_name,
            "Model Type": "Individual",
            "Observation Count": len(actual),
            **metrics,
        })

    ensemble_metrics = calculate_ensemble_blend_metrics(
        actual,
        ensemble_predictions[
            "Ensemble_Predicted"
        ].to_numpy(dtype=float),
    )

    rows.append({
        "Model": "Weighted Ensemble",
        "Model Type": "Ensemble",
        "Observation Count": len(actual),
        **ensemble_metrics,
    })

    comparison = pd.DataFrame(rows)

    for metric in ENSEMBLE_BLEND_SUPPORTED_METRICS:
        if metric in comparison.columns:
            comparison[metric] = pd.to_numeric(
                comparison[metric],
                errors="coerce",
            )

    return comparison


def rank_ensemble_blend_models(
    comparison,
    ranking_metric="WAPE",
):
    """Rank model rows using a selected lower-is-better metric."""

    if comparison is None or comparison.empty:
        return pd.DataFrame()

    if ranking_metric not in ENSEMBLE_BLEND_SUPPORTED_METRICS:
        ranking_metric = "WAPE"

    result = comparison.copy()

    result[ranking_metric] = pd.to_numeric(
        result[ranking_metric],
        errors="coerce",
    )

    result = result.sort_values(
        ranking_metric,
        ascending=True,
        na_position="last",
    ).reset_index(drop=True)

    result.insert(
        0,
        "Rank",
        np.arange(1, len(result) + 1),
    )

    return result


def build_ensemble_blend_error_table(
    ensemble_predictions,
):
    """Create row-level ensemble errors for inspection and export."""

    if ensemble_predictions is None or ensemble_predictions.empty:
        return pd.DataFrame()

    if not {
        "Actual",
        "Ensemble_Predicted",
    }.issubset(ensemble_predictions.columns):
        return pd.DataFrame()

    result = ensemble_predictions.copy()

    result["Error"] = (
        result["Actual"]
        - result["Ensemble_Predicted"]
    )

    result["Absolute_Error"] = result[
        "Error"
    ].abs()

    result["Squared_Error"] = result[
        "Error"
    ].pow(2)

    result["Error_Direction"] = np.select(
        [
            result["Error"] > 0,
            result["Error"] < 0,
        ],
        [
            "Underprediction",
            "Overprediction",
        ],
        default="Exact Match",
    )

    return result.sort_values(
        "Absolute_Error",
        ascending=False,
    ).reset_index(drop=True)


def generate_ensemble_blend_interpretation(
    comparison,
    ranking_metric="WAPE",
):
    """Generate cautious performance observations."""

    if comparison is None or comparison.empty:
        return [
            "No model comparison is available.",
        ]

    if ranking_metric not in comparison.columns:
        return [
            "The selected ranking metric is unavailable.",
        ]

    valid = comparison.dropna(
        subset=[ranking_metric]
    ).copy()

    if valid.empty:
        return [
            f"{ranking_metric} cannot be calculated for these observations.",
        ]

    best_row = valid.sort_values(
        ranking_metric
    ).iloc[0]

    messages = [
        (
            f"Best result on this evaluation sample: "
            f"{best_row['Model']} "
            f"({ranking_metric} = "
            f"{best_row[ranking_metric]:.4f})."
        )
    ]

    ensemble_rows = valid[
        valid["Model"] == "Weighted Ensemble"
    ]

    individual_rows = valid[
        valid["Model Type"] == "Individual"
    ]

    if not ensemble_rows.empty and not individual_rows.empty:
        ensemble_score = float(
            ensemble_rows.iloc[0][ranking_metric]
        )

        best_individual_score = float(
            individual_rows[ranking_metric].min()
        )

        if ensemble_score < best_individual_score:
            messages.append(
                "The ensemble outperformed every individual model "
                "on the selected metric for this sample."
            )
        elif ensemble_score > best_individual_score:
            messages.append(
                "At least one individual model outperformed the ensemble "
                "on the selected metric for this sample."
            )
        else:
            messages.append(
                "The ensemble matched the best individual model's "
                "score on the selected metric."
            )

    messages.append(
        "These results describe the supplied evaluation data only. "
        "They do not guarantee future performance."
    )

    return messages


def render_ensemble_blend_upload():
    """Upload prediction results from multiple models."""

    st.subheader("1. Upload Model Predictions")

    uploaded_file = st.file_uploader(
        "Upload a CSV containing multiple model predictions",
        type=["csv"],
        key="ensemble_blend_upload",
        help=(
            "Expected format: one row per model and observation, "
            "with model name, actual value, predicted value, and "
            "optionally timestamp."
        ),
    )

    if uploaded_file is None:
        st.info(
            "Upload a prediction-results CSV to begin the ensemble analysis."
        )
        return None

    try:
        dataframe = pd.read_csv(uploaded_file)
    except Exception as exc:
        st.error(
            f"Unable to read the uploaded CSV: {exc}"
        )
        return None

    if dataframe.empty:
        st.warning("The uploaded CSV contains no records.")
        return None

    st.caption(
        f"Uploaded rows: {len(dataframe):,} | "
        f"Columns: {len(dataframe.columns):,}"
    )

    st.dataframe(
        dataframe.head(10),
        use_container_width=True,
    )

    return dataframe


def render_ensemble_blend_column_mapping(dataframe):
    """Allow users to map source columns to standard fields."""

    if dataframe is None or dataframe.empty:
        return None

    st.subheader("2. Map Prediction Columns")

    columns = dataframe.columns.tolist()

    def choose_column(label, preferred, key):
        default_index = (
            columns.index(preferred)
            if preferred in columns
            else 0
        )

        return st.selectbox(
            label,
            options=columns,
            index=default_index,
            key=key,
        )

    model_column = choose_column(
        "Model name column",
        "Model",
        "ensemble_blend_model_column",
    )

    actual_column = choose_column(
        "Actual observed value column",
        "Actual",
        "ensemble_blend_actual_column",
    )

    predicted_column = choose_column(
        "Predicted value column",
        "Predicted",
        "ensemble_blend_predicted_column",
    )

    timestamp_options = ["No timestamp column"] + columns

    timestamp_default = (
        columns.index("Timestamp") + 1
        if "Timestamp" in columns
        else 0
    )

    timestamp_selection = st.selectbox(
        "Timestamp column (recommended)",
        options=timestamp_options,
        index=timestamp_default,
        key="ensemble_blend_timestamp_column",
    )

    timestamp_column = (
        None
        if timestamp_selection == "No timestamp column"
        else timestamp_selection
    )

    if len({
        model_column,
        actual_column,
        predicted_column,
    }) < 3:
        st.error(
            "Model, Actual, and Predicted must use three different columns."
        )
        return None

    return {
        "model_column": model_column,
        "actual_column": actual_column,
        "predicted_column": predicted_column,
        "timestamp_column": timestamp_column,
    }


def render_ensemble_blend_alignment_status(
    alignment,
):
    """Display whether predictions can be safely combined."""

    st.subheader("3. Observation Alignment Check")

    if not alignment:
        st.warning("Alignment information is unavailable.")
        return

    if alignment["Aligned"]:
        st.success(alignment["Reason"])

        col1, col2 = st.columns(2)

        col1.metric(
            "Models",
            len(alignment["Models"]),
        )

        col2.metric(
            "Aligned observations",
            f"{alignment['Observation_Count']:,}",
        )
    else:
        st.error(alignment["Reason"])


def render_ensemble_blend_weight_controls(
    model_names,
):
    """Collect model blend weights from the user."""

    st.subheader("4. Configure Ensemble Weights")

    st.caption(
        "Weights are normalized automatically. "
        "For example, weights 2 and 1 become approximately 66.7% and 33.3%. "
        "Weights are user-selected, not automatically learned."
    )

    weights = {}

    columns = st.columns(
        min(3, max(1, len(model_names)))
    )

    for index, model_name in enumerate(model_names):
        with columns[index % len(columns)]:
            weights[model_name] = st.number_input(
                f"{model_name} weight",
                min_value=0.0,
                max_value=1000.0,
                value=1.0,
                step=0.25,
                key=f"ensemble_blend_weight_{index}",
            )

    if sum(weights.values()) <= 0:
        st.warning(
            "All weights are zero. Equal weights will be used."
        )

    return weights


def render_ensemble_blend_metrics(comparison):
    """Show metric results for individual models and ensemble."""

    st.subheader("5. Model and Ensemble Performance")

    if comparison is None or comparison.empty:
        st.info("No comparison metrics are available.")
        return

    st.dataframe(
        comparison,
        use_container_width=True,
        hide_index=True,
    )

    if "Model Type" in comparison.columns:
        ensemble_rows = comparison[
            comparison["Model Type"] == "Ensemble"
        ]

        if not ensemble_rows.empty:
            ensemble = ensemble_rows.iloc[0]

            columns = st.columns(3)

            for index, metric in enumerate(
                ENSEMBLE_BLEND_SUPPORTED_METRICS
            ):
                value = ensemble.get(metric, np.nan)

                if pd.notna(value):
                    columns[index].metric(
                        f"Ensemble {metric}",
                        (
                            f"{value:.3f}%"
                            if metric == "WAPE"
                            else f"{value:.3f}"
                        ),
                    )
                else:
                    columns[index].metric(
                        f"Ensemble {metric}",
                        "N/A",
                    )


def render_ensemble_blend_ranking(comparison):
    """Allow interactive ranking by supported error metric."""

    st.subheader("6. Model Ranking")

    ranking_metric = st.selectbox(
        "Rank models by",
        options=ENSEMBLE_BLEND_SUPPORTED_METRICS,
        index=0,
        key="ensemble_blend_ranking_metric",
    )

    ranking = rank_ensemble_blend_models(
        comparison,
        ranking_metric=ranking_metric,
    )

    if ranking.empty:
        st.info("No ranking is available.")
        return ranking, ranking_metric

    st.dataframe(
        ranking,
        use_container_width=True,
        hide_index=True,
    )

    return ranking, ranking_metric


def render_ensemble_blend_error_analysis(
    ensemble_predictions,
):
    """Inspect the largest errors made by the ensemble."""

    st.subheader("7. Ensemble Error Analysis")

    error_table = build_ensemble_blend_error_table(
        ensemble_predictions
    )

    if error_table.empty:
        st.info("No ensemble error details are available.")
        return error_table

    under = int(
        (error_table["Error_Direction"] == "Underprediction").sum()
    )

    over = int(
        (error_table["Error_Direction"] == "Overprediction").sum()
    )

    exact = int(
        (error_table["Error_Direction"] == "Exact Match").sum()
    )

    col1, col2, col3 = st.columns(3)

    col1.metric("Underpredictions", f"{under:,}")
    col2.metric("Overpredictions", f"{over:,}")
    col3.metric("Exact matches", f"{exact:,}")

    st.caption(
        "Positive Error = Actual âˆ’ Predicted. "
        "A positive error means the model underpredicted the observed value."
    )

    st.dataframe(
        error_table.head(
            ENSEMBLE_BLEND_MAXIMUM_DISPLAY_ROWS
        ),
        use_container_width=True,
        hide_index=True,
    )

    return error_table


def render_ensemble_blend_interpretation(
    comparison,
    ranking_metric,
):
    """Present concise interpretation of model comparison results."""

    st.subheader("8. Interpretation")

    messages = generate_ensemble_blend_interpretation(
        comparison,
        ranking_metric=ranking_metric,
    )

    for message in messages:
        st.write(f"â€¢ {message}")


def render_ensemble_blend_exports(
    comparison,
    ranking,
    ensemble_predictions,
    error_table,
):
    """Download the ensemble outputs as CSV files."""

    st.subheader("9. Export Results")

    export_items = [
        (
            "Model and Ensemble Metrics",
            comparison,
            "ensemble_model_comparison.csv",
        ),
        (
            "Ranked Model Comparison",
            ranking,
            "ensemble_model_ranking.csv",
        ),
        (
            "Aligned Ensemble Predictions",
            ensemble_predictions,
            "ensemble_predictions.csv",
        ),
        (
            "Ensemble Error Details",
            error_table,
            "ensemble_error_analysis.csv",
        ),
    ]

    for label, dataframe, filename in export_items:
        if dataframe is None or dataframe.empty:
            continue

        st.download_button(
            label=f"Download {label}",
            data=dataframe.to_csv(
                index=False
            ).encode("utf-8"),
            file_name=filename,
            mime="text/csv",
            key=f"download_{filename}",
        )


def render_ensemble_blend_center():
    """
    Main page for comparing individual forecasting models
    with a weighted prediction ensemble.
    """

    st.header(
        "Forecast Ensemble & Model Blend Simulator"
    )

    st.write(
        "Compare predictions from multiple models and test a "
        "user-configured weighted blend on aligned observations."
    )

    st.info(
        "This module evaluates supplied predictions. It does not "
        "train models, generate future forecasts, or prove that an "
        "ensemble will improve future results."
    )

    uploaded_dataframe = render_ensemble_blend_upload()

    if uploaded_dataframe is None:
        return

    mapping = render_ensemble_blend_column_mapping(
        uploaded_dataframe
    )

    if mapping is None:
        return

    standardized = prepare_ensemble_blend_data(
        uploaded_dataframe,
        model_column=mapping["model_column"],
        actual_column=mapping["actual_column"],
        predicted_column=mapping["predicted_column"],
        timestamp_column=mapping["timestamp_column"],
    )

    if standardized.empty:
        st.error(
            "No valid prediction rows remain after data preparation. "
            "Check the selected columns and uploaded values."
        )
        return

    with st.expander("Prepared prediction data", expanded=False):
        st.dataframe(
            standardized.head(100),
            use_container_width=True,
            hide_index=True,
        )

    alignment = identify_ensemble_blend_alignment(
        standardized
    )

    render_ensemble_blend_alignment_status(
        alignment
    )

    if not alignment["Aligned"]:
        st.warning(
            "The ensemble has not been calculated because the "
            "models' observations are not aligned."
        )
        return

    matrix_result = build_ensemble_blend_prediction_matrix(
        standardized
    )

    if not matrix_result["Success"]:
        st.error(matrix_result["Reason"])
        return

    prediction_matrix = matrix_result["Predictions"]

    weights = render_ensemble_blend_weight_controls(
        alignment["Models"]
    )

    blend_result = calculate_ensemble_blend_predictions(
        prediction_matrix,
        weights,
    )

    if not blend_result["Success"]:
        st.error(blend_result["Reason"])
        return

    ensemble_predictions = blend_result["Predictions"]

    with st.expander("Normalized model weights", expanded=True):
        weight_table = pd.DataFrame([
            {
                "Model": model_name,
                "Normalized Weight": weight,
                "Weight Percentage": weight * 100,
            }
            for model_name, weight
            in blend_result["Weights"].items()
        ])

        st.dataframe(
            weight_table,
            use_container_width=True,
            hide_index=True,
        )

    comparison = build_ensemble_blend_comparison(
        prediction_matrix,
        ensemble_predictions,
    )

    render_ensemble_blend_metrics(
        comparison
    )

    ranking, ranking_metric = render_ensemble_blend_ranking(
        comparison
    )

    error_table = render_ensemble_blend_error_analysis(
        ensemble_predictions
    )

    render_ensemble_blend_interpretation(
        comparison,
        ranking_metric,
    )

    render_ensemble_blend_exports(
        comparison,
        ranking,
        ensemble_predictions,
        error_table,
    )


def get_ensemble_blend_module_information():
    """Return metadata for the ensemble blending module."""

    return {
        "name": "Forecast Ensemble & Model Blend Simulator",
        "version": ENSEMBLE_BLEND_VERSION,
        "minimum_models": ENSEMBLE_BLEND_MINIMUM_MODELS,
        "supported_metrics": ENSEMBLE_BLEND_SUPPORTED_METRICS,
        "requires_aligned_observations": True,
        "trains_models": False,
        "description": (
            "Evaluates weighted blends of supplied model predictions "
            "after checking observation alignment."
        ),
    }


