# ============================================================
# PART 26 â€” FORECAST CONFIDENCE & PREDICTION INTERVAL ANALYSIS
# ============================================================

FORECAST_INTERVAL_VERSION = "1.0.0"

FORECAST_INTERVAL_MINIMUM_ROWS = 2
FORECAST_INTERVAL_MAXIMUM_DISPLAY_ROWS = 2000

FORECAST_INTERVAL_REQUIRED_FIELDS = [
    "Actual",
    "Predicted",
    "Lower_Bound",
    "Upper_Bound",
]


def prepare_forecast_interval_data(
    dataframe,
    actual_column,
    predicted_column,
    lower_column,
    upper_column,
    timestamp_column=None,
):
    """
    Standardize forecast predictions and prediction intervals.

    Lower_Bound and Upper_Bound must be supplied by the source.
    This function does not invent or estimate interval boundaries.
    """

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    required_columns = [
        actual_column,
        predicted_column,
        lower_column,
        upper_column,
    ]

    if any(
        column not in dataframe.columns
        for column in required_columns
    ):
        return pd.DataFrame()

    selected_columns = list(dict.fromkeys(required_columns))

    if (
        timestamp_column
        and timestamp_column in dataframe.columns
        and timestamp_column not in selected_columns
    ):
        selected_columns.append(timestamp_column)

    result = dataframe[selected_columns].copy()

    rename_map = {
        actual_column: "Actual",
        predicted_column: "Predicted",
        lower_column: "Lower_Bound",
        upper_column: "Upper_Bound",
    }

    if timestamp_column and timestamp_column in result.columns:
        rename_map[timestamp_column] = "Timestamp"

    result = result.rename(columns=rename_map)

    numeric_columns = [
        "Actual",
        "Predicted",
        "Lower_Bound",
        "Upper_Bound",
    ]

    for column in numeric_columns:
        result[column] = pd.to_numeric(
            result[column],
            errors="coerce",
        )

    result = result.replace(
        [np.inf, -np.inf],
        np.nan,
    )

    result = result.dropna(
        subset=numeric_columns
    )

    if "Timestamp" in result.columns:
        result["Timestamp"] = pd.to_datetime(
            result["Timestamp"],
            errors="coerce",
        )

        result = result.dropna(
            subset=["Timestamp"]
        )

    result["Interval_Width"] = (
        result["Upper_Bound"]
        - result["Lower_Bound"]
    )

    result["Valid_Interval"] = (
        result["Lower_Bound"]
        <= result["Upper_Bound"]
    )

    return result.reset_index(drop=True)


def calculate_forecast_interval_coverage(
    dataframe,
):
    """
    Calculate empirical prediction interval coverage.

    Coverage is the percentage of valid observations whose actual
    values fall between the supplied lower and upper bounds.
    """

    if dataframe is None or dataframe.empty:
        return {
            "Total_Rows": 0,
            "Valid_Intervals": 0,
            "Invalid_Intervals": 0,
            "Covered_Observations": 0,
            "Outside_Observations": 0,
            "Coverage_Percentage": np.nan,
        }

    valid = dataframe[
        dataframe["Valid_Interval"]
    ].copy()

    invalid_count = int(
        (~dataframe["Valid_Interval"]).sum()
    )

    if valid.empty:
        return {
            "Total_Rows": len(dataframe),
            "Valid_Intervals": 0,
            "Invalid_Intervals": invalid_count,
            "Covered_Observations": 0,
            "Outside_Observations": 0,
            "Coverage_Percentage": np.nan,
        }

    covered = (
        (valid["Actual"] >= valid["Lower_Bound"])
        & (valid["Actual"] <= valid["Upper_Bound"])
    )

    covered_count = int(covered.sum())
    outside_count = int((~covered).sum())

    coverage = (
        covered_count / len(valid)
    ) * 100

    return {
        "Total_Rows": len(dataframe),
        "Valid_Intervals": len(valid),
        "Invalid_Intervals": invalid_count,
        "Covered_Observations": covered_count,
        "Outside_Observations": outside_count,
        "Coverage_Percentage": float(coverage),
    }


def calculate_forecast_interval_width_summary(
    dataframe,
):
    """Summarize the widths of valid prediction intervals."""

    if dataframe is None or dataframe.empty:
        return {
            "Mean_Width": np.nan,
            "Median_Width": np.nan,
            "Minimum_Width": np.nan,
            "Maximum_Width": np.nan,
            "Width_Standard_Deviation": np.nan,
        }

    valid = dataframe[
        dataframe["Valid_Interval"]
    ].copy()

    widths = pd.to_numeric(
        valid["Interval_Width"],
        errors="coerce",
    ).dropna()

    if widths.empty:
        return {
            "Mean_Width": np.nan,
            "Median_Width": np.nan,
            "Minimum_Width": np.nan,
            "Maximum_Width": np.nan,
            "Width_Standard_Deviation": np.nan,
        }

    return {
        "Mean_Width": float(widths.mean()),
        "Median_Width": float(widths.median()),
        "Minimum_Width": float(widths.min()),
        "Maximum_Width": float(widths.max()),
        "Width_Standard_Deviation": float(widths.std(ddof=0)),
    }


def calculate_forecast_interval_error_summary(
    dataframe,
):
    """Compare point predictions against actual observations."""

    if dataframe is None or dataframe.empty:
        return {
            "MAE": np.nan,
            "RMSE": np.nan,
            "WAPE": np.nan,
        }

    valid = dataframe[
        dataframe["Valid_Interval"]
    ].copy()

    if valid.empty:
        return {
            "MAE": np.nan,
            "RMSE": np.nan,
            "WAPE": np.nan,
        }

    actual = valid["Actual"].to_numpy(dtype=float)
    predicted = valid["Predicted"].to_numpy(dtype=float)

    absolute_errors = np.abs(actual - predicted)

    mae = float(absolute_errors.mean())

    rmse = float(
        np.sqrt(
            np.mean(
                np.square(actual - predicted)
            )
        )
    )

    denominator = float(
        np.abs(actual).sum()
    )

    wape = (
        float(absolute_errors.sum() / denominator * 100)
        if denominator > 0
        else np.nan
    )

    return {
        "MAE": mae,
        "RMSE": rmse,
        "WAPE": wape,
    }


def build_forecast_interval_observation_table(
    dataframe,
):
    """Create row-level interval coverage diagnostics."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    result = dataframe.copy()

    result["Point_Error"] = (
        result["Actual"]
        - result["Predicted"]
    )

    result["Absolute_Point_Error"] = (
        result["Point_Error"].abs()
    )

    result["Below_Lower_Bound"] = (
        result["Actual"]
        < result["Lower_Bound"]
    )

    result["Above_Upper_Bound"] = (
        result["Actual"]
        > result["Upper_Bound"]
    )

    result["Outside_Interval"] = (
        result["Valid_Interval"]
        & (
            result["Below_Lower_Bound"]
            | result["Above_Upper_Bound"]
        )
    )

    result["Interval_Status"] = np.select(
        [
            ~result["Valid_Interval"],
            result["Below_Lower_Bound"],
            result["Above_Upper_Bound"],
        ],
        [
            "Invalid interval",
            "Below lower bound",
            "Above upper bound",
        ],
        default="Inside interval",
    )

    result["Lower_Bound_Gap"] = (
        result["Lower_Bound"]
        - result["Actual"]
    ).clip(lower=0)

    result["Upper_Bound_Gap"] = (
        result["Actual"]
        - result["Upper_Bound"]
    ).clip(lower=0)

    return result


def build_forecast_interval_period_summary(
    dataframe,
    frequency="MS",
):
    """Calculate coverage and average width over time periods."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    if "Timestamp" not in dataframe.columns:
        return pd.DataFrame()

    valid = dataframe[
        dataframe["Valid_Interval"]
    ].copy()

    if valid.empty:
        return pd.DataFrame()

    valid = valid.sort_values(
        "Timestamp"
    ).set_index("Timestamp")

    valid["Covered"] = (
        (valid["Actual"] >= valid["Lower_Bound"])
        & (valid["Actual"] <= valid["Upper_Bound"])
    ).astype(int)

    summary = valid.resample(frequency).agg(
        Observation_Count=("Actual", "count"),
        Coverage=("Covered", "mean"),
        Mean_Interval_Width=("Interval_Width", "mean"),
        Mean_Absolute_Error=("Absolute_Point_Error", "mean"),
    )

    summary["Coverage_Percentage"] = (
        summary["Coverage"] * 100
    )

    summary = summary.drop(
        columns=["Coverage"]
    )

    return summary.reset_index()


def generate_forecast_interval_interpretation(
    coverage_summary,
    width_summary,
    error_summary,
):
    """Generate descriptive observations without claiming certainty."""

    messages = []

    coverage = coverage_summary.get(
        "Coverage_Percentage",
        np.nan,
    )

    if pd.notna(coverage):
        messages.append(
            f"Observed empirical interval coverage is {coverage:.2f}%."
        )
    else:
        messages.append(
            "Coverage could not be calculated because no valid intervals exist."
        )

    mean_width = width_summary.get(
        "Mean_Width",
        np.nan,
    )

    if pd.notna(mean_width):
        messages.append(
            f"The average interval width is {mean_width:.4f} "
            "in the units of the target variable."
        )

    outside_count = coverage_summary.get(
        "Outside_Observations",
        0,
    )

    if outside_count:
        messages.append(
            f"{outside_count:,} valid observations fell outside "
            "their supplied prediction intervals."
        )

    invalid_count = coverage_summary.get(
        "Invalid_Intervals",
        0,
    )

    if invalid_count:
        messages.append(
            f"{invalid_count:,} rows contain invalid intervals "
            "where the lower bound exceeds the upper bound."
        )

    mae = error_summary.get("MAE", np.nan)

    if pd.notna(mae):
        messages.append(
            f"Point-forecast MAE on valid-interval rows is {mae:.4f}."
        )

    messages.append(
        "Empirical coverage alone does not prove that an interval "
        "is statistically calibrated. Interpret it alongside the "
        "intended confidence level and an appropriate held-out evaluation."
    )

    return messages


def render_forecast_interval_upload():
    """Upload an evaluation file containing interval boundaries."""

    st.subheader("1. Upload Forecast Interval Results")

    uploaded_file = st.file_uploader(
        "Upload a CSV with actuals, predictions and interval bounds",
        type=["csv"],
        key="forecast_interval_upload",
    )

    if uploaded_file is None:
        st.info(
            "Required fields: Actual, Predicted, Lower Bound, Upper Bound. "
            "A timestamp column is optional."
        )
        return None

    try:
        dataframe = pd.read_csv(uploaded_file)
    except Exception as exc:
        st.error(
            f"Unable to read the uploaded file: {exc}"
        )
        return None

    if dataframe.empty:
        st.warning("The uploaded file contains no rows.")
        return None

    st.caption(
        f"{len(dataframe):,} rows | "
        f"{len(dataframe.columns):,} columns"
    )

    return dataframe


def render_forecast_interval_column_mapping(dataframe):
    """Map source fields to the interval analysis fields."""

    if dataframe is None or dataframe.empty:
        return None

    st.subheader("2. Map Source Columns")

    columns = dataframe.columns.tolist()

    def select_source_column(label, preferred, key):
        index = (
            columns.index(preferred)
            if preferred in columns
            else 0
        )

        return st.selectbox(
            label,
            options=columns,
            index=index,
            key=key,
        )

    actual_column = select_source_column(
        "Actual values",
        "Actual",
        "forecast_interval_actual",
    )

    predicted_column = select_source_column(
        "Point predictions",
        "Predicted",
        "forecast_interval_predicted",
    )

    lower_column = select_source_column(
        "Lower interval bound",
        "Lower_Bound",
        "forecast_interval_lower",
    )

    upper_column = select_source_column(
        "Upper interval bound",
        "Upper_Bound",
        "forecast_interval_upper",
    )

    timestamp_options = [
        "No timestamp column"
    ] + columns

    timestamp_index = (
        columns.index("Timestamp") + 1
        if "Timestamp" in columns
        else 0
    )

    timestamp_selection = st.selectbox(
        "Timestamp (optional)",
        options=timestamp_options,
        index=timestamp_index,
        key="forecast_interval_timestamp",
    )

    timestamp_column = (
        None
        if timestamp_selection == "No timestamp column"
        else timestamp_selection
    )

    if len({
        actual_column,
        predicted_column,
        lower_column,
        upper_column,
    }) < 4:
        st.error(
            "Select four different columns for Actual, Predicted, "
            "Lower Bound and Upper Bound."
        )
        return None

    return {
        "actual_column": actual_column,
        "predicted_column": predicted_column,
        "lower_column": lower_column,
        "upper_column": upper_column,
        "timestamp_column": timestamp_column,
    }


def render_forecast_interval_kpis(
    coverage_summary,
    width_summary,
    error_summary,
):
    """Display coverage, width and point-forecast metrics."""

    st.subheader("3. Interval Performance Overview")

    coverage = coverage_summary.get(
        "Coverage_Percentage",
        np.nan,
    )

    mean_width = width_summary.get(
        "Mean_Width",
        np.nan,
    )

    mae = error_summary.get(
        "MAE",
        np.nan,
    )

    rmse = error_summary.get(
        "RMSE",
        np.nan,
    )

    columns = st.columns(4)

    columns[0].metric(
        "Empirical Coverage",
        f"{coverage:.2f}%" if pd.notna(coverage) else "N/A",
    )

    columns[1].metric(
        "Mean Interval Width",
        f"{mean_width:.3f}" if pd.notna(mean_width) else "N/A",
    )

    columns[2].metric(
        "Point MAE",
        f"{mae:.3f}" if pd.notna(mae) else "N/A",
    )

    columns[3].metric(
        "Point RMSE",
        f"{rmse:.3f}" if pd.notna(rmse) else "N/A",
    )

    st.caption(
        "Coverage is measured only on valid intervals. "
        "Width is expressed in the target variable's units."
    )


