# ============================================================
# PART 27 â€” FORECAST BACKTESTING & WALK-FORWARD VALIDATION
# ============================================================

FORECAST_BACKTEST_VERSION = "1.0.0"

FORECAST_BACKTEST_MINIMUM_ROWS = 10
FORECAST_BACKTEST_DEFAULT_FOLDS = 5
FORECAST_BACKTEST_MAXIMUM_FOLDS = 20
FORECAST_BACKTEST_MINIMUM_TEST_SIZE = 2
FORECAST_BACKTEST_MAXIMUM_DISPLAY_ROWS = 2000

FORECAST_BACKTEST_SUPPORTED_METRICS = [
    "MAE",
    "RMSE",
    "WAPE",
]


def prepare_forecast_backtest_data(
    dataframe,
    actual_column,
    predicted_column,
    timestamp_column=None,
):
    """
    Standardize historical actual and predicted values.

    Predictions must already exist in the supplied data.
    This function does not train or generate forecasting models.
    """

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    required_columns = [
        actual_column,
        predicted_column,
    ]

    if any(
        column not in dataframe.columns
        for column in required_columns
    ):
        return pd.DataFrame()

    selected_columns = list(
        dict.fromkeys(required_columns)
    )

    if (
        timestamp_column
        and timestamp_column in dataframe.columns
        and timestamp_column not in selected_columns
    ):
        selected_columns.append(timestamp_column)

    result = dataframe[selected_columns].copy()

    rename_map = {
        actual_column: "Actual",
        predicted_column: "Predicted",
    }

    if timestamp_column and timestamp_column in result.columns:
        rename_map[timestamp_column] = "Timestamp"

    result = result.rename(
        columns=rename_map
    )

    result["Actual"] = pd.to_numeric(
        result["Actual"],
        errors="coerce",
    )

    result["Predicted"] = pd.to_numeric(
        result["Predicted"],
        errors="coerce",
    )

    result = result.replace(
        [np.inf, -np.inf],
        np.nan,
    )

    result = result.dropna(
        subset=["Actual", "Predicted"]
    )

    if "Timestamp" in result.columns:
        result["Timestamp"] = pd.to_datetime(
            result["Timestamp"],
            errors="coerce",
        )

        result = result.dropna(
            subset=["Timestamp"]
        )

        result = result.sort_values(
            "Timestamp"
        )

        if result["Timestamp"].duplicated().any():
            return pd.DataFrame()

    return result.reset_index(
        drop=True
    )


def calculate_forecast_backtest_metrics(
    actual,
    predicted,
):
    """Calculate MAE, RMSE and WAPE for one evaluation window."""

    actual_values = np.asarray(
        actual,
        dtype=float,
    )

    predicted_values = np.asarray(
        predicted,
        dtype=float,
    )

    if (
        len(actual_values) == 0
        or len(actual_values) != len(predicted_values)
    ):
        return {
            "MAE": np.nan,
            "RMSE": np.nan,
            "WAPE": np.nan,
        }

    if (
        not np.isfinite(actual_values).all()
        or not np.isfinite(predicted_values).all()
    ):
        return {
            "MAE": np.nan,
            "RMSE": np.nan,
            "WAPE": np.nan,
        }

    errors = actual_values - predicted_values

    mae = float(
        np.mean(
            np.abs(errors)
        )
    )

    rmse = float(
        np.sqrt(
            np.mean(
                np.square(errors)
            )
        )
    )

    denominator = float(
        np.sum(
            np.abs(actual_values)
        )
    )

    wape = (
        float(
            np.sum(np.abs(errors))
            / denominator
            * 100
        )
        if denominator > 0
        else np.nan
    )

    return {
        "MAE": mae,
        "RMSE": rmse,
        "WAPE": wape,
    }


def build_forecast_backtest_folds(
    dataframe,
    number_of_folds=5,
    minimum_test_size=2,
):
    """
    Create chronological, non-overlapping evaluation windows.

    This divides already-generated predictions into time windows.
    It does not retrain a model at each fold and therefore is not
    a substitute for a complete model-training backtest.
    """

    if dataframe is None or dataframe.empty:
        return {
            "Success": False,
            "Reason": "No evaluation data is available.",
            "Folds": [],
        }

    row_count = len(dataframe)

    if row_count < FORECAST_BACKTEST_MINIMUM_ROWS:
        return {
            "Success": False,
            "Reason": (
                f"At least {FORECAST_BACKTEST_MINIMUM_ROWS} rows "
                "are required."
            ),
            "Folds": [],
        }

    try:
        number_of_folds = int(
            number_of_folds
        )
        minimum_test_size = int(
            minimum_test_size
        )
    except (TypeError, ValueError):
        return {
            "Success": False,
            "Reason": "Fold settings must be whole numbers.",
            "Folds": [],
        }

    number_of_folds = max(
        1,
        min(
            number_of_folds,
            FORECAST_BACKTEST_MAXIMUM_FOLDS,
        ),
    )

    minimum_test_size = max(
        1,
        minimum_test_size,
    )

    maximum_possible_folds = (
        row_count // minimum_test_size
    )

    number_of_folds = min(
        number_of_folds,
        maximum_possible_folds,
    )

    if number_of_folds < 1:
        return {
            "Success": False,
            "Reason": "Not enough rows to create evaluation folds.",
            "Folds": [],
        }

    # The earliest records form the initial history window.
    # Remaining records are divided into chronological test windows.
    initial_history_size = (
        row_count - number_of_folds * minimum_test_size
    )

    if initial_history_size < 1:
        number_of_folds = max(
            1,
            min(
                number_of_folds,
                max(1, row_count // 3),
            ),
        )

        initial_history_size = (
            row_count - number_of_folds * minimum_test_size
        )

    if initial_history_size < 1:
        return {
            "Success": False,
            "Reason": (
                "Unable to reserve an initial history window "
                "and at least one test window."
            ),
            "Folds": [],
        }

    remaining_rows = (
        row_count - initial_history_size
    )

    fold_sizes = np.full(
        number_of_folds,
        remaining_rows // number_of_folds,
        dtype=int,
    )

    fold_sizes[:remaining_rows % number_of_folds] += 1

    folds = []
    start = initial_history_size

    for fold_number, fold_size in enumerate(
        fold_sizes,
        start=1,
    ):
        end = start + int(fold_size)

        if end <= start:
            continue

        history = dataframe.iloc[:start].copy()

        test = dataframe.iloc[start:end].copy()

        if test.empty:
            continue

        folds.append({
            "Fold": fold_number,
            "History_Start_Row": 0,
            "History_End_Row": start - 1,
            "History_Rows": len(history),
            "Test_Start_Row": start,
            "Test_End_Row": end - 1,
            "Test_Rows": len(test),
            "History": history,
            "Test": test,
        })

        start = end

    if not folds:
        return {
            "Success": False,
            "Reason": "No valid evaluation folds could be created.",
            "Folds": [],
        }

    return {
        "Success": True,
        "Reason": (
            "Chronological evaluation folds created from the "
            "provided actual and predicted values."
        ),
        "Folds": folds,
    }


def evaluate_forecast_backtest_folds(
    fold_result,
):
    """Evaluate the existing predictions within each test window."""

    if (
        not fold_result
        or not fold_result.get("Success")
    ):
        return pd.DataFrame()

    rows = []

    for fold in fold_result["Folds"]:
        test = fold["Test"]

        metrics = calculate_forecast_backtest_metrics(
            test["Actual"],
            test["Predicted"],
        )

        row = {
            "Fold": fold["Fold"],
            "History_Rows": fold["History_Rows"],
            "Test_Rows": fold["Test_Rows"],
            **metrics,
        }

        if "Timestamp" in test.columns:
            row["Test_Start"] = test["Timestamp"].min()
            row["Test_End"] = test["Timestamp"].max()

        rows.append(row)

    return pd.DataFrame(rows)


def summarize_forecast_backtest_results(
    fold_metrics,
):
    """Summarize metric consistency across evaluation windows."""

    if fold_metrics is None or fold_metrics.empty:
        return pd.DataFrame()

    rows = []

    for metric in FORECAST_BACKTEST_SUPPORTED_METRICS:
        if metric not in fold_metrics.columns:
            continue

        values = pd.to_numeric(
            fold_metrics[metric],
            errors="coerce",
        ).dropna()

        if values.empty:
            rows.append({
                "Metric": metric,
                "Valid_Folds": 0,
                "Mean": np.nan,
                "Median": np.nan,
                "Minimum": np.nan,
                "Maximum": np.nan,
                "Standard_Deviation": np.nan,
            })
            continue

        rows.append({
            "Metric": metric,
            "Valid_Folds": len(values),
            "Mean": float(values.mean()),
            "Median": float(values.median()),
            "Minimum": float(values.min()),
            "Maximum": float(values.max()),
            "Standard_Deviation": float(
                values.std(ddof=0)
            ),
        })

    return pd.DataFrame(rows)


def calculate_forecast_backtest_error_trend(
    fold_metrics,
    metric="WAPE",
):
    """
    Describe whether the selected error metric rises or falls
    over the chronological evaluation folds.
    """

    if fold_metrics is None or fold_metrics.empty:
        return {
            "Metric": metric,
            "Trend": "Unavailable",
            "First_Fold_Mean": np.nan,
            "Last_Fold_Mean": np.nan,
            "Percentage_Change": np.nan,
            "Interpretation": "No fold metrics are available.",
        }

    if metric not in fold_metrics.columns:
        return {
            "Metric": metric,
            "Trend": "Unavailable",
            "First_Fold_Mean": np.nan,
            "Last_Fold_Mean": np.nan,
            "Percentage_Change": np.nan,
            "Interpretation": "The selected metric is unavailable.",
        }

    ordered = fold_metrics.sort_values(
        "Fold"
    ).copy()

    ordered[metric] = pd.to_numeric(
        ordered[metric],
        errors="coerce",
    )

    ordered = ordered.dropna(
        subset=[metric]
    )

    if len(ordered) < 2:
        return {
            "Metric": metric,
            "Trend": "Insufficient folds",
            "First_Fold_Mean": np.nan,
            "Last_Fold_Mean": np.nan,
            "Percentage_Change": np.nan,
            "Interpretation": (
                "At least two valid folds are required "
                "to compare early and late errors."
            ),
        }

    first_value = float(
        ordered.iloc[0][metric]
    )

    last_value = float(
        ordered.iloc[-1][metric]
    )

    if np.isclose(first_value, 0.0):
        percentage_change = np.nan
    else:
        percentage_change = (
            (last_value - first_value)
            / abs(first_value)
            * 100
        )

    if last_value > first_value:
        trend = "Error increased"
        interpretation = (
            "The selected error metric is higher in the final "
            "evaluation window than in the first."
        )
    elif last_value < first_value:
        trend = "Error decreased"
        interpretation = (
            "The selected error metric is lower in the final "
            "evaluation window than in the first."
        )
    else:
        trend = "No net change"
        interpretation = (
            "The selected error metric is unchanged between "
            "the first and final evaluation windows."
        )

    return {
        "Metric": metric,
        "Trend": trend,
        "First_Fold_Mean": first_value,
        "Last_Fold_Mean": last_value,
        "Percentage_Change": percentage_change,
        "Interpretation": interpretation,
    }


def build_forecast_backtest_observation_report(
    fold_result,
):
    """Combine test-window records into one observation report."""

    if (
        not fold_result
        or not fold_result.get("Success")
    ):
        return pd.DataFrame()

    reports = []

    for fold in fold_result["Folds"]:
        test = fold["Test"].copy()

        test["Fold"] = fold["Fold"]

        test["Error"] = (
            test["Actual"]
            - test["Predicted"]
        )

        test["Absolute_Error"] = (
            test["Error"].abs()
        )

        test["Squared_Error"] = (
            test["Error"].pow(2)
        )

        reports.append(test)

    if not reports:
        return pd.DataFrame()

    return pd.concat(
        reports,
        ignore_index=True,
    )


def generate_forecast_backtest_interpretation(
    fold_metrics,
    metric="WAPE",
):
    """Create a cautious textual summary of the fold evaluation."""

    messages = []

    if fold_metrics is None or fold_metrics.empty:
        return [
            "No valid evaluation folds are available.",
        ]

    if metric not in fold_metrics.columns:
        return [
            f"The selected metric {metric} is unavailable.",
        ]

    valid = fold_metrics.dropna(
        subset=[metric]
    ).copy()

    if valid.empty:
        return [
            f"{metric} could not be calculated for these folds.",
        ]

    mean_error = float(
        valid[metric].mean()
    )

    std_error = float(
        valid[metric].std(ddof=0)
    )

    messages.append(
        f"Mean fold {metric}: {mean_error:.4f}."
    )

    messages.append(
        f"Fold-to-fold standard deviation of {metric}: "
        f"{std_error:.4f}."
    )

    trend = calculate_forecast_backtest_error_trend(
        valid,
        metric=metric,
    )

    messages.append(
        trend["Interpretation"]
    )

    messages.append(
        "These folds evaluate predictions already supplied in the file. "
        "They do not establish that the model was retrained at each "
        "historical cutoff. For leakage-safe walk-forward validation, "
        "retrain the forecasting model separately within each fold."
    )

    return messages


def render_forecast_backtest_upload():
    """Upload historical predictions for chronological evaluation."""

    st.subheader("1. Upload Historical Predictions")

    uploaded_file = st.file_uploader(
        "Upload a CSV with actual and predicted values",
        type=["csv"],
        key="forecast_backtest_upload",
    )

    if uploaded_file is None:
        st.info(
            "Provide historical actuals and corresponding predictions. "
            "Include timestamps whenever possible."
        )
        return None

    try:
        dataframe = pd.read_csv(
            uploaded_file
        )
    except Exception as exc:
        st.error(
            f"Could not read the uploaded CSV: {exc}"
        )
        return None

    if dataframe.empty:
        st.warning(
            "The uploaded file contains no rows."
        )
        return None

    st.caption(
        f"Rows: {len(dataframe):,} | "
        f"Columns: {len(dataframe.columns):,}"
    )

    return dataframe


def render_forecast_backtest_column_mapping(
    dataframe,
):
    """Allow selection of actual, predicted and timestamp fields."""

    if dataframe is None or dataframe.empty:
        return None

    st.subheader("2. Map Evaluation Columns")

    columns = dataframe.columns.tolist()

    def select_column(label, preferred, key):
        default_index = (
            columns.index(preferred)
            if preferred in columns
            else 0
        )

        return st.selectbox(
            label,
            options=columns,
            index=default_index,
            key=key,
        )

    actual_column = select_column(
        "Actual values",
        "Actual",
        "forecast_backtest_actual_column",
    )

    predicted_column = select_column(
        "Predicted values",
        "Predicted",
        "forecast_backtest_predicted_column",
    )

    timestamp_options = [
        "No timestamp column"
    ] + columns

    timestamp_index = (
        columns.index("Timestamp") + 1
        if "Timestamp" in columns
        else 0
    )

    timestamp_choice = st.selectbox(
        "Timestamp column",
        options=timestamp_options,
        index=timestamp_index,
        key="forecast_backtest_timestamp_column",
    )

    timestamp_column = (
        None
        if timestamp_choice == "No timestamp column"
        else timestamp_choice
    )

    if actual_column == predicted_column:
        st.error(
            "Actual and Predicted must be different columns."
        )
        return None

    return {
        "actual_column": actual_column,
        "predicted_column": predicted_column,
        "timestamp_column": timestamp_column,
    }


def render_forecast_backtest_controls(
    row_count,
):
    """Collect fold settings from the user."""

    st.subheader("3. Configure Evaluation Windows")

    maximum_folds = max(
        1,
        min(
            FORECAST_BACKTEST_MAXIMUM_FOLDS,
            row_count // FORECAST_BACKTEST_MINIMUM_TEST_SIZE,
        ),
    )

    default_folds = min(
        FORECAST_BACKTEST_DEFAULT_FOLDS,
        maximum_folds,
    )

    col1, col2 = st.columns(2)

    number_of_folds = col1.number_input(
        "Number of evaluation folds",
        min_value=1,
        max_value=maximum_folds,
        value=default_folds,
        step=1,
        key="forecast_backtest_number_of_folds",
    )

    minimum_test_size = col2.number_input(
        "Minimum test-window size",
        min_value=1,
        max_value=max(
            1,
            row_count // 2,
        ),
        value=min(
            FORECAST_BACKTEST_MINIMUM_TEST_SIZE,
            max(1, row_count // 2),
        ),
        step=1,
        key="forecast_backtest_minimum_test_size",
    )

    st.caption(
        "Each test window uses a later chronological segment. "
        "Earlier rows form its historical context, but this interface "
        "does not retrain models inside the windows."
    )

    return int(number_of_folds), int(minimum_test_size)


