# ============================================================
# PART 28 â€” FORECAST RESIDUAL DIAGNOSTICS & ERROR PATTERNS
# ============================================================

FORECAST_RESIDUAL_VERSION = "1.0.0"

FORECAST_RESIDUAL_MINIMUM_ROWS = 5
FORECAST_RESIDUAL_MAXIMUM_LAG = 30
FORECAST_RESIDUAL_MAXIMUM_DISPLAY_ROWS = 2000

FORECAST_RESIDUAL_SUPPORTED_METRICS = [
    "MAE",
    "RMSE",
    "WAPE",
]


def prepare_forecast_residual_data(
    dataframe,
    actual_column,
    predicted_column,
    timestamp_column=None,
):
    """Standardize actual and predicted values for residual analysis."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    required_columns = [
        actual_column,
        predicted_column,
    ]

    if any(
        column not in dataframe.columns
        for column in required_columns
    ):
        return pd.DataFrame()

    selected_columns = list(
        dict.fromkeys(required_columns)
    )

    if (
        timestamp_column
        and timestamp_column in dataframe.columns
        and timestamp_column not in selected_columns
    ):
        selected_columns.append(timestamp_column)

    result = dataframe[selected_columns].copy()

    rename_map = {
        actual_column: "Actual",
        predicted_column: "Predicted",
    }

    if timestamp_column and timestamp_column in result.columns:
        rename_map[timestamp_column] = "Timestamp"

    result = result.rename(
        columns=rename_map
    )

    result["Actual"] = pd.to_numeric(
        result["Actual"],
        errors="coerce",
    )

    result["Predicted"] = pd.to_numeric(
        result["Predicted"],
        errors="coerce",
    )

    result = result.replace(
        [np.inf, -np.inf],
        np.nan,
    )

    result = result.dropna(
        subset=["Actual", "Predicted"]
    )

    if "Timestamp" in result.columns:
        result["Timestamp"] = pd.to_datetime(
            result["Timestamp"],
            errors="coerce",
        )

        result = result.dropna(
            subset=["Timestamp"]
        )

        result = result.sort_values(
            "Timestamp"
        )

        if result["Timestamp"].duplicated().any():
            return pd.DataFrame()

    result = result.reset_index(
        drop=True
    )

    result["Residual"] = (
        result["Actual"] - result["Predicted"]
    )

    result["Absolute_Residual"] = (
        result["Residual"].abs()
    )

    result["Squared_Residual"] = (
        result["Residual"].pow(2)
    )

    result["Error_Direction"] = np.select(
        [
            result["Residual"] > 0,
            result["Residual"] < 0,
        ],
        [
            "Underprediction",
            "Overprediction",
        ],
        default="Exact Match",
    )

    return result


def calculate_forecast_residual_statistics(
    dataframe,
):
    """Calculate descriptive statistics for residuals."""

    if (
        dataframe is None
        or dataframe.empty
        or "Residual" not in dataframe.columns
    ):
        return {}

    residuals = pd.to_numeric(
        dataframe["Residual"],
        errors="coerce",
    ).dropna()

    if residuals.empty:
        return {}

    return {
        "Observation_Count": int(len(residuals)),
        "Mean_Residual": float(residuals.mean()),
        "Median_Residual": float(residuals.median()),
        "Residual_Standard_Deviation": float(
            residuals.std(ddof=0)
        ),
        "Residual_Variance": float(
            residuals.var(ddof=0)
        ),
        "Minimum_Residual": float(residuals.min()),
        "Maximum_Residual": float(residuals.max()),
        "Mean_Absolute_Residual": float(
            residuals.abs().mean()
        ),
        "Root_Mean_Squared_Residual": float(
            np.sqrt(np.mean(np.square(residuals)))
        ),
        "Residual_Skewness": (
            float(residuals.skew())
            if len(residuals) >= 3
            else np.nan
        ),
        "Residual_Kurtosis": (
            float(residuals.kurt())
            if len(residuals) >= 4
            else np.nan
        ),
    }


def calculate_forecast_residual_metrics(
    dataframe,
):
    """Calculate standard prediction error metrics."""

    if (
        dataframe is None
        or dataframe.empty
        or not {"Actual", "Predicted"}.issubset(
            dataframe.columns
        )
    ):
        return {}

    actual = dataframe["Actual"].to_numpy(
        dtype=float
    )

    predicted = dataframe["Predicted"].to_numpy(
        dtype=float
    )

    if len(actual) == 0:
        return {}

    errors = actual - predicted

    denominator = np.sum(
        np.abs(actual)
    )

    return {
        "MAE": float(
            np.mean(np.abs(errors))
        ),
        "RMSE": float(
            np.sqrt(np.mean(np.square(errors)))
        ),
        "WAPE": (
            float(
                np.sum(np.abs(errors))
                / denominator
                * 100
            )
            if denominator > 0
            else np.nan
        ),
    }


def calculate_forecast_residual_direction_summary(
    dataframe,
):
    """Summarize the direction of forecast errors."""

    if (
        dataframe is None
        or dataframe.empty
        or "Residual" not in dataframe.columns
    ):
        return pd.DataFrame()

    counts = (
        dataframe["Error_Direction"]
        .value_counts()
        .rename_axis("Error Direction")
        .reset_index(name="Observation Count")
    )

    counts["Percentage"] = (
        counts["Observation Count"]
        / len(dataframe)
        * 100
    )

    return counts


def calculate_forecast_residual_autocorrelation(
    dataframe,
    maximum_lag=20,
):
    """
    Calculate residual autocorrelation for available lags.

    This is a descriptive diagnostic, not a formal significance test.
    """

    if (
        dataframe is None
        or dataframe.empty
        or "Residual" not in dataframe.columns
    ):
        return pd.DataFrame()

    residuals = pd.to_numeric(
        dataframe["Residual"],
        errors="coerce",
    ).dropna().reset_index(drop=True)

    if len(residuals) < FORECAST_RESIDUAL_MINIMUM_ROWS:
        return pd.DataFrame()

    maximum_lag = max(
        1,
        min(
            int(maximum_lag),
            FORECAST_RESIDUAL_MAXIMUM_LAG,
            len(residuals) - 1,
        ),
    )

    if np.isclose(
        float(residuals.var(ddof=0)),
        0.0,
    ):
        return pd.DataFrame({
            "Lag": list(range(1, maximum_lag + 1)),
            "Autocorrelation": [
                np.nan
            ] * maximum_lag,
        })

    rows = []

    for lag in range(1, maximum_lag + 1):
        correlation = residuals.autocorr(
            lag=lag
        )

        rows.append({
            "Lag": lag,
            "Autocorrelation": (
                float(correlation)
                if pd.notna(correlation)
                else np.nan
            ),
        })

    return pd.DataFrame(rows)


def calculate_forecast_residual_period_summary(
    dataframe,
    frequency="MS",
):
    """Summarize residual behavior by calendar period."""

    if (
        dataframe is None
        or dataframe.empty
        or "Timestamp" not in dataframe.columns
    ):
        return pd.DataFrame()

    result = dataframe.copy()

    result = result.sort_values(
        "Timestamp"
    ).set_index("Timestamp")

    summary = result.resample(frequency).agg(
        Observation_Count=("Residual", "count"),
        Mean_Residual=("Residual", "mean"),
        Mean_Absolute_Residual=("Absolute_Residual", "mean"),
        Maximum_Absolute_Residual=("Absolute_Residual", "max"),
        Mean_Actual=("Actual", "mean"),
        Mean_Predicted=("Predicted", "mean"),
    )

    return summary.reset_index()


def identify_forecast_residual_outliers(
    dataframe,
    standard_deviation_threshold=3.0,
):
    """
    Flag residuals beyond a configurable standard-deviation threshold.

    The threshold is a heuristic and should not be interpreted
    as a guaranteed statistical outlier test.
    """

    if (
        dataframe is None
        or dataframe.empty
        or "Residual" not in dataframe.columns
    ):
        return pd.DataFrame()

    result = dataframe.copy()

    residuals = result["Residual"].astype(
        float
    )

    center = float(
        residuals.mean()
    )

    spread = float(
        residuals.std(ddof=0)
    )

    try:
        threshold = float(
            standard_deviation_threshold
        )
    except (TypeError, ValueError):
        threshold = 3.0

    if not np.isfinite(threshold) or threshold <= 0:
        threshold = 3.0

    if np.isclose(spread, 0.0):
        result["Residual_Z_Score"] = 0.0
        result["Potential_Error_Outlier"] = False
    else:
        result["Residual_Z_Score"] = (
            (residuals - center) / spread
        )

        result["Potential_Error_Outlier"] = (
            result["Residual_Z_Score"].abs()
            >= threshold
        )

    outliers = result[
        result["Potential_Error_Outlier"]
    ].copy()

    return outliers.sort_values(
        "Absolute_Residual",
        ascending=False,
    ).reset_index(drop=True)


def build_forecast_residual_report(
    dataframe,
    maximum_lag=20,
    standard_deviation_threshold=3.0,
):
    """Build the principal outputs for residual diagnostics."""

    if dataframe is None or dataframe.empty:
        return {
            "Success": False,
            "Reason": "No valid prediction records are available.",
        }

    if len(dataframe) < FORECAST_RESIDUAL_MINIMUM_ROWS:
        return {
            "Success": False,
            "Reason": (
                f"At least {FORECAST_RESIDUAL_MINIMUM_ROWS} "
                "valid rows are required."
            ),
        }

    statistics = calculate_forecast_residual_statistics(
        dataframe
    )

    metrics = calculate_forecast_residual_metrics(
        dataframe
    )

    direction = calculate_forecast_residual_direction_summary(
        dataframe
    )

    autocorrelation = calculate_forecast_residual_autocorrelation(
        dataframe,
        maximum_lag=maximum_lag,
    )

    period_summary = calculate_forecast_residual_period_summary(
        dataframe
    )

    outliers = identify_forecast_residual_outliers(
        dataframe,
        standard_deviation_threshold=standard_deviation_threshold,
    )

    return {
        "Success": True,
        "Reason": "Residual diagnostics were calculated.",
        "Statistics": statistics,
        "Metrics": metrics,
        "Direction": direction,
        "Autocorrelation": autocorrelation,
        "Period_Summary": period_summary,
        "Outliers": outliers,
        "Observation_Details": dataframe.copy(),
    }


def generate_forecast_residual_interpretation(
    report,
):
    """Generate descriptive residual observations."""

    if (
        not report
        or not report.get("Success")
    ):
        return [
            "Residual interpretation is unavailable.",
        ]

    messages = []

    statistics = report.get(
        "Statistics",
        {},
    )

    mean_residual = statistics.get(
        "Mean_Residual",
        np.nan,
    )

    if pd.notna(mean_residual):
        if mean_residual > 0:
            messages.append(
                "The mean residual is positive, indicating that "
                "predictions tend to be below actual values."
            )
        elif mean_residual < 0:
            messages.append(
                "The mean residual is negative, indicating that "
                "predictions tend to be above actual values."
            )
        else:
            messages.append(
                "The mean residual is approximately zero."
            )

    autocorrelation = report.get(
        "Autocorrelation",
        pd.DataFrame(),
    )

    if (
        autocorrelation is not None
        and not autocorrelation.empty
    ):
        correlations = pd.to_numeric(
            autocorrelation["Autocorrelation"],
            errors="coerce",
        ).dropna()

        if not correlations.empty:
            largest = float(
                correlations.abs().max()
            )

            if largest >= 0.5:
                messages.append(
                    "At least one tested lag has a comparatively strong "
                    "residual autocorrelation. The errors may retain "
                    "a temporal pattern."
                )
            else:
                messages.append(
                    "No tested lag reached the configured descriptive "
                    "threshold of 0.5 for absolute autocorrelation."
                )

    outliers = report.get(
        "Outliers",
        pd.DataFrame(),
    )

    if outliers is not None:
        messages.append(
            f"Potential large-error observations flagged: "
            f"{len(outliers):,}."
        )

    messages.append(
        "Residual autocorrelation and standard-deviation thresholds "
        "are descriptive diagnostics. They do not alone prove that "
        "a model is adequate or inadequate."
    )

    return messages


def render_forecast_residual_upload():
    """Upload actual and predicted values for residual analysis."""

    st.subheader("1. Upload Prediction Results")

    uploaded_file = st.file_uploader(
        "Upload a CSV with actual and predicted values",
        type=["csv"],
        key="forecast_residual_upload",
    )

    if uploaded_file is None:
        st.info(
            "Select a prediction-results CSV to begin."
        )
        return None

    try:
        dataframe = pd.read_csv(
            uploaded_file
        )
    except Exception as exc:
        st.error(
            f"Could not read the uploaded CSV: {exc}"
        )
        return None

    if dataframe.empty:
        st.warning(
            "The uploaded CSV contains no rows."
        )
        return None

    return dataframe


def render_forecast_residual_column_mapping(
    dataframe,
):
    """Map the actual, predicted and optional timestamp fields."""

    if dataframe is None or dataframe.empty:
        return None

    st.subheader("2. Select Data Columns")

    columns = dataframe.columns.tolist()

    def select_column(label, preferred, key):
        default_index = (
            columns.index(preferred)
            if preferred in columns
            else 0
        )

        return st.selectbox(
            label,
            options=columns,
            index=default_index,
            key=key,
        )

    actual_column = select_column(
        "Actual values",
        "Actual",
        "forecast_residual_actual_column",
    )

    predicted_column = select_column(
        "Predicted values",
        "Predicted",
        "forecast_residual_predicted_column",
    )

    timestamp_options = [
        "No timestamp column"
    ] + columns

    timestamp_index = (
        columns.index("Timestamp") + 1
        if "Timestamp" in columns
        else 0
    )

    timestamp_selection = st.selectbox(
        "Timestamp column",
        options=timestamp_options,
        index=timestamp_index,
        key="forecast_residual_timestamp_column",
    )

    timestamp_column = (
        None
        if timestamp_selection == "No timestamp column"
        else timestamp_selection
    )

    if actual_column == predicted_column:
        st.error(
            "Actual and Predicted must be different columns."
        )
        return None

    return {
        "actual_column": actual_column,
        "predicted_column": predicted_column,
        "timestamp_column": timestamp_column,
    }


