def render_forecast_residual_center():
    """Main interface for forecast residual diagnostics."""

    st.header(
        "Forecast Residual Diagnostics & Error Patterns"
    )

    st.write(
        "Analyze forecast residuals, systematic error direction, "
        "temporal error patterns and residual autocorrelation."
    )

    st.info(
        "Residual = Actual âˆ’ Predicted. Positive residuals indicate "
        "underprediction; negative residuals indicate overprediction."
    )

    uploaded_dataframe = render_forecast_residual_upload()

    if uploaded_dataframe is None:
        return

    mapping = render_forecast_residual_column_mapping(
        uploaded_dataframe
    )

    if mapping is None:
        return

    prepared = prepare_forecast_residual_data(
        uploaded_dataframe,
        actual_column=mapping["actual_column"],
        predicted_column=mapping["predicted_column"],
        timestamp_column=mapping["timestamp_column"],
    )

    if prepared.empty:
        st.error(
            "No valid records remain. Check the selected columns, "
            "numeric values and timestamps."
        )
        return

    if len(prepared) < FORECAST_RESIDUAL_MINIMUM_ROWS:
        st.warning(
            f"At least {FORECAST_RESIDUAL_MINIMUM_ROWS} valid rows "
            "are required."
        )
        return

    maximum_lag, outlier_threshold = (
        render_forecast_residual_controls()
    )

    report = build_forecast_residual_report(
        prepared,
        maximum_lag=maximum_lag,
        standard_deviation_threshold=outlier_threshold,
    )

    if not report.get("Success"):
        st.error(
            report.get(
                "Reason",
                "Residual diagnostics could not be calculated.",
            )
        )
        return

    render_forecast_residual_kpis(
        report
    )

    render_forecast_residual_statistics(
        report["Statistics"]
    )

    render_forecast_residual_charts(
        report["Observation_Details"]
    )

    render_forecast_residual_direction(
        report["Direction"]
    )

    render_forecast_residual_autocorrelation(
        report["Autocorrelation"]
    )

    render_forecast_residual_periods(
        report["Period_Summary"]
    )

    render_forecast_residual_outliers(
        report["Outliers"]
    )

    render_forecast_residual_interpretation(
        report
    )

    render_forecast_residual_exports(
        report
    )


