# ============================================================
# PART 29 â€” FORECAST CONFIDENCE & PREDICTION INTERVAL ANALYSIS
# ============================================================

FORECAST_INTERVAL_VERSION = "1.0.0"

FORECAST_INTERVAL_MINIMUM_ROWS = 2
FORECAST_INTERVAL_DEFAULT_COVERAGE = 90
FORECAST_INTERVAL_SUPPORTED_COVERAGE_LEVELS = [
    80,
    90,
    95,
    99,
]


def prepare_forecast_interval_data(
    dataframe,
    actual_column,
    predicted_column,
    lower_column=None,
    upper_column=None,
    timestamp_column=None,
):
    """
    Standardize forecast observations and optional prediction bounds.

    Lower and upper bounds must come from a forecasting method
    or supplied forecast artifact. They are never fabricated here.
    """

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    required_columns = [
        actual_column,
        predicted_column,
    ]

    if any(
        column not in dataframe.columns
        for column in required_columns
    ):
        return pd.DataFrame()

    selected_columns = list(
        dict.fromkeys(required_columns)
    )

    optional_columns = [
        lower_column,
        upper_column,
        timestamp_column,
    ]

    for column in optional_columns:
        if (
            column
            and column in dataframe.columns
            and column not in selected_columns
        ):
            selected_columns.append(column)

    result = dataframe[selected_columns].copy()

    rename_map = {
        actual_column: "Actual",
        predicted_column: "Predicted",
    }

    if lower_column and lower_column in result.columns:
        rename_map[lower_column] = "Lower_Bound"

    if upper_column and upper_column in result.columns:
        rename_map[upper_column] = "Upper_Bound"

    if timestamp_column and timestamp_column in result.columns:
        rename_map[timestamp_column] = "Timestamp"

    result = result.rename(
        columns=rename_map
    )

    for column in [
        "Actual",
        "Predicted",
        "Lower_Bound",
        "Upper_Bound",
    ]:
        if column in result.columns:
            result[column] = pd.to_numeric(
                result[column],
                errors="coerce",
            )

    result = result.replace(
        [np.inf, -np.inf],
        np.nan,
    )

    result = result.dropna(
        subset=[
            "Actual",
            "Predicted",
        ]
    )

    if "Timestamp" in result.columns:
        result["Timestamp"] = pd.to_datetime(
            result["Timestamp"],
            errors="coerce",
        )

        result = result.dropna(
            subset=["Timestamp"]
        )

        result = result.sort_values(
            "Timestamp"
        )

        if result["Timestamp"].duplicated().any():
            return pd.DataFrame()

    if {
        "Lower_Bound",
        "Upper_Bound",
    }.issubset(result.columns):
        valid_bounds = (
            result["Lower_Bound"].notna()
            & result["Upper_Bound"].notna()
            & (
                result["Lower_Bound"]
                <= result["Upper_Bound"]
            )
        )

        result["Valid_Interval"] = valid_bounds

        result["Interval_Width"] = np.where(
            valid_bounds,
            result["Upper_Bound"] - result["Lower_Bound"],
            np.nan,
        )

        result["Actual_Within_Interval"] = np.where(
            valid_bounds,
            (
                (result["Actual"] >= result["Lower_Bound"])
                & (result["Actual"] <= result["Upper_Bound"])
            ),
            np.nan,
        )

    return result.reset_index(
        drop=True
    )


def calculate_forecast_interval_metrics(
    dataframe,
):
    """Calculate point-forecast metrics without inventing uncertainty."""

    if (
        dataframe is None
        or dataframe.empty
        or not {
            "Actual",
            "Predicted",
        }.issubset(dataframe.columns)
    ):
        return {}

    actual = dataframe["Actual"].to_numpy(
        dtype=float
    )

    predicted = dataframe["Predicted"].to_numpy(
        dtype=float
    )

    if len(actual) == 0:
        return {}

    errors = actual - predicted

    denominator = float(
        np.sum(np.abs(actual))
    )

    return {
        "Observation_Count": int(len(actual)),
        "MAE": float(
            np.mean(np.abs(errors))
        ),
        "RMSE": float(
            np.sqrt(np.mean(np.square(errors)))
        ),
        "WAPE": (
            float(
                np.sum(np.abs(errors))
                / denominator
                * 100
            )
            if denominator > 0
            else np.nan
        ),
    }


def calculate_forecast_interval_coverage(
    dataframe,
):
    """
    Calculate empirical interval coverage for supplied valid bounds.

    Coverage is the percentage of valid actual observations falling
    between the supplied lower and upper bounds, inclusive.
    """

    required_columns = {
        "Actual",
        "Lower_Bound",
        "Upper_Bound",
    }

    if (
        dataframe is None
        or dataframe.empty
        or not required_columns.issubset(
            dataframe.columns
        )
    ):
        return {
            "Available": False,
            "Reason": (
                "Both lower and upper prediction bounds are required."
            ),
        }

    lower = dataframe["Lower_Bound"]
    upper = dataframe["Upper_Bound"]
    actual = dataframe["Actual"]

    valid = (
        actual.notna()
        & lower.notna()
        & upper.notna()
        & (lower <= upper)
    )

    valid_count = int(
        valid.sum()
    )

    if valid_count == 0:
        return {
            "Available": False,
            "Reason": (
                "No valid prediction intervals were found."
            ),
        }

    covered = (
        (actual[valid] >= lower[valid])
        & (actual[valid] <= upper[valid])
    )

    coverage_percentage = float(
        covered.mean() * 100
    )

    return {
        "Available": True,
        "Valid_Interval_Count": valid_count,
        "Covered_Count": int(covered.sum()),
        "Outside_Count": int((~covered).sum()),
        "Empirical_Coverage_Percentage": coverage_percentage,
        "Mean_Interval_Width": float(
            (upper[valid] - lower[valid]).mean()
        ),
        "Median_Interval_Width": float(
            (upper[valid] - lower[valid]).median()
        ),
        "Minimum_Interval_Width": float(
            (upper[valid] - lower[valid]).min()
        ),
        "Maximum_Interval_Width": float(
            (upper[valid] - lower[valid]).max()
        ),
    }


def build_forecast_interval_width_summary(
    dataframe,
):
    """Summarize widths for valid prediction intervals."""

    if (
        dataframe is None
        or dataframe.empty
        or "Interval_Width" not in dataframe.columns
    ):
        return pd.DataFrame()

    valid_widths = pd.to_numeric(
        dataframe["Interval_Width"],
        errors="coerce",
    ).dropna()

    if valid_widths.empty:
        return pd.DataFrame()

    return pd.DataFrame([
        {
            "Statistic": "Count",
            "Value": int(valid_widths.count()),
        },
        {
            "Statistic": "Mean Width",
            "Value": float(valid_widths.mean()),
        },
        {
            "Statistic": "Median Width",
            "Value": float(valid_widths.median()),
        },
        {
            "Statistic": "Minimum Width",
            "Value": float(valid_widths.min()),
        },
        {
            "Statistic": "Maximum Width",
            "Value": float(valid_widths.max()),
        },
        {
            "Statistic": "Width Standard Deviation",
            "Value": float(valid_widths.std(ddof=0)),
        },
    ])


def build_forecast_interval_period_summary(
    dataframe,
    frequency="MS",
):
    """Summarize coverage and interval width over time."""

    if (
        dataframe is None
        or dataframe.empty
        or "Timestamp" not in dataframe.columns
        or "Valid_Interval" not in dataframe.columns
    ):
        return pd.DataFrame()

    result = dataframe.copy()

    result = result[
        result["Valid_Interval"].fillna(False)
    ].copy()

    if result.empty:
        return pd.DataFrame()

    result = result.sort_values(
        "Timestamp"
    ).set_index("Timestamp")

    result["Covered_Flag"] = (
        result["Actual_Within_Interval"]
        .astype(float)
    )

    summary = result.resample(frequency).agg(
        Observation_Count=("Actual", "count"),
        Empirical_Coverage=("Covered_Flag", "mean"),
        Mean_Interval_Width=("Interval_Width", "mean"),
        Median_Interval_Width=("Interval_Width", "median"),
    )

    summary["Empirical_Coverage_Percentage"] = (
        summary["Empirical_Coverage"] * 100
    )

    return summary.drop(
        columns=["Empirical_Coverage"]
    ).reset_index()


def identify_forecast_interval_misses(
    dataframe,
):
    """Identify actual observations outside valid supplied intervals."""

    if (
        dataframe is None
        or dataframe.empty
        or "Actual_Within_Interval" not in dataframe.columns
    ):
        return pd.DataFrame()

    result = dataframe.copy()

    outside = result[
        result["Valid_Interval"].fillna(False)
        & (
            result["Actual_Within_Interval"]
            == False
        )
    ].copy()

    if outside.empty:
        return outside

    outside["Distance_Outside_Interval"] = np.where(
        outside["Actual"] < outside["Lower_Bound"],
        outside["Lower_Bound"] - outside["Actual"],
        outside["Actual"] - outside["Upper_Bound"],
    )

    return outside.sort_values(
        "Distance_Outside_Interval",
        ascending=False,
    ).reset_index(drop=True)


def generate_forecast_interval_interpretation(
    coverage_summary,
    nominal_coverage=None,
):
    """Interpret empirical coverage without asserting calibration."""

    messages = []

    if (
        not coverage_summary
        or not coverage_summary.get("Available")
    ):
        messages.append(
            "Prediction interval analysis is unavailable because "
            "valid lower and upper bounds were not supplied."
        )
        return messages

    observed = coverage_summary[
        "Empirical_Coverage_Percentage"
    ]

    messages.append(
        f"Observed empirical interval coverage is {observed:.2f}% "
        "among valid intervals."
    )

    if nominal_coverage is not None:
        try:
            nominal = float(
                nominal_coverage
            )
        except (TypeError, ValueError):
            nominal = None

        if (
            nominal is not None
            and 0 < nominal < 100
        ):
            difference = observed - nominal

            messages.append(
                f"Observed coverage differs from the selected "
                f"{nominal:.0f}% reference by {difference:+.2f} "
                "percentage points."
            )

            messages.append(
                "A single empirical coverage value does not prove "
                "that intervals are statistically calibrated. "
                "Use a separate calibration dataset and account "
                "for the forecasting method and evaluation period."
            )

    messages.append(
        "Narrower intervals are not automatically better: interval "
        "width should be interpreted together with empirical coverage."
    )

    return messages


def build_forecast_interval_report(
    dataframe,
    nominal_coverage=None,
):
    """Build all confidence and interval analysis outputs."""

    if dataframe is None or dataframe.empty:
        return {
            "Success": False,
            "Reason": "No valid forecast records are available.",
        }

    point_metrics = calculate_forecast_interval_metrics(
        dataframe
    )

    coverage = calculate_forecast_interval_coverage(
        dataframe
    )

    width_summary = build_forecast_interval_width_summary(
        dataframe
    )

    period_summary = build_forecast_interval_period_summary(
        dataframe
    )

    interval_misses = identify_forecast_interval_misses(
        dataframe
    )

    interpretation = generate_forecast_interval_interpretation(
        coverage,
        nominal_coverage=nominal_coverage,
    )

    return {
        "Success": True,
        "Reason": "Forecast interval report created.",
        "Point_Metrics": point_metrics,
        "Coverage": coverage,
        "Width_Summary": width_summary,
        "Period_Summary": period_summary,
        "Interval_Misses": interval_misses,
        "Interpretation": interpretation,
        "Observation_Details": dataframe.copy(),
    }


def render_forecast_interval_upload():
    """Upload actual, predicted and optional interval columns."""

    st.subheader("1. Upload Forecast Results")

    uploaded_file = st.file_uploader(
        "Upload a CSV with actual and predicted values",
        type=["csv"],
        key="forecast_interval_upload",
    )

    if uploaded_file is None:
        st.info(
            "For interval coverage analysis, the CSV should also "
            "contain lower and upper prediction-bound columns."
        )
        return None

    try:
        dataframe = pd.read_csv(
            uploaded_file
        )
    except Exception as exc:
        st.error(
            f"Could not read the CSV: {exc}"
        )
        return None

    if dataframe.empty:
        st.warning(
            "The uploaded file contains no rows."
        )
        return None

    return dataframe


def render_forecast_interval_column_mapping(
    dataframe,
):
    """Map forecast and prediction-interval fields."""

    if dataframe is None or dataframe.empty:
        return None

    st.subheader("2. Map Forecast Columns")

    columns = dataframe.columns.tolist()

    def select_column(label, preferred, key):
        options = ["Not available"] + columns

        if preferred in columns:
            default_index = columns.index(preferred) + 1
        else:
            default_index = 0

        selected = st.selectbox(
            label,
            options=options,
            index=default_index,
            key=key,
        )

        return (
            None
            if selected == "Not available"
            else selected
        )

    actual_column = select_column(
        "Actual values",
        "Actual",
        "forecast_interval_actual_column",
    )

    predicted_column = select_column(
        "Predicted values",
        "Predicted",
        "forecast_interval_predicted_column",
    )

    lower_column = select_column(
        "Lower prediction bound",
        "Lower_Bound",
        "forecast_interval_lower_column",
    )

    upper_column = select_column(
        "Upper prediction bound",
        "Upper_Bound",
        "forecast_interval_upper_column",
    )

    timestamp_column = select_column(
        "Timestamp (optional)",
        "Timestamp",
        "forecast_interval_timestamp_column",
    )

    if actual_column is None or predicted_column is None:
        st.error(
            "Select both actual and predicted columns."
        )
        return None

    if actual_column == predicted_column:
        st.error(
            "Actual and predicted columns must be different."
        )
        return None

    if (
        lower_column is not None
        and lower_column == upper_column
    ):
        st.error(
            "Lower and upper bounds must be different columns."
        )
        return None

    if (
        (lower_column is None)
        != (upper_column is None)
    ):
        st.warning(
            "Select both lower and upper bounds, or leave both "
            "unselected to skip interval coverage analysis."
        )
        return None

    return {
        "actual_column": actual_column,
        "predicted_column": predicted_column,
        "lower_column": lower_column,
        "upper_column": upper_column,
        "timestamp_column": timestamp_column,
    }


