def render_forecast_interval_center():
    """Main interface for prediction interval analysis."""

    st.header(
        "Forecast Confidence & Prediction Interval Analysis"
    )

    st.write(
        "Evaluate the empirical coverage and width of supplied "
        "forecast prediction intervals."
    )

    st.warning(
        "Prediction intervals must come from a forecasting model "
        "or another documented uncertainty method. This module "
        "does not manufacture confidence bounds."
    )

    uploaded_dataframe = render_forecast_interval_upload()

    if uploaded_dataframe is None:
        return

    mapping = render_forecast_interval_column_mapping(
        uploaded_dataframe
    )

    if mapping is None:
        return

    prepared = prepare_forecast_interval_data(
        uploaded_dataframe,
        actual_column=mapping["actual_column"],
        predicted_column=mapping["predicted_column"],
        lower_column=mapping["lower_column"],
        upper_column=mapping["upper_column"],
        timestamp_column=mapping["timestamp_column"],
    )

    if prepared.empty:
        st.error(
            "No valid observations remain. Check your selected "
            "columns and source data."
        )
        return

    if len(prepared) < FORECAST_INTERVAL_MINIMUM_ROWS:
        st.warning(
            f"At least {FORECAST_INTERVAL_MINIMUM_ROWS} valid rows "
            "are recommended for this analysis."
        )
        return

    nominal_coverage = render_forecast_interval_controls()

    report = build_forecast_interval_report(
        prepared,
        nominal_coverage=nominal_coverage,
    )

    if not report.get("Success"):
        st.error(
            report.get(
                "Reason",
                "The interval report could not be generated.",
            )
        )
        return

    render_forecast_interval_kpis(
        report
    )

    render_forecast_interval_width(
        report["Width_Summary"]
    )

    render_forecast_interval_period_analysis(
        report["Period_Summary"]
    )

    render_forecast_interval_misses(
        report["Interval_Misses"]
    )

    render_forecast_interval_interpretation(
        report,
        nominal_coverage=nominal_coverage,
    )

    render_forecast_interval_exports(
        report
    )


