# ============================================================
# PART 30 â€” FORECAST BIAS & ERROR CALIBRATION CENTER
# ============================================================

FORECAST_BIAS_CAL_VERSION = "1.0.0"

FORECAST_BIAS_CAL_MINIMUM_ROWS = 20
FORECAST_BIAS_CAL_DEFAULT_TRAIN_RATIO = 0.70
FORECAST_BIAS_CAL_MINIMUM_TRAIN_RATIO = 0.50
FORECAST_BIAS_CAL_MAXIMUM_TRAIN_RATIO = 0.90

FORECAST_BIAS_CAL_METHODS = [
    "Additive Correction",
    "Proportional Correction",
]


def prepare_forecast_bias_cal_data(
    dataframe,
    actual_column,
    predicted_column,
    timestamp_column=None,
):
    """
    Prepare actual and predicted observations for bias analysis.

    Positive residual means actual demand exceeded the prediction.
    Negative residual means the prediction exceeded actual demand.
    """

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    required = [
        actual_column,
        predicted_column,
    ]

    if any(
        column not in dataframe.columns
        for column in required
    ):
        return pd.DataFrame()

    selected = list(required)

    if (
        timestamp_column
        and timestamp_column in dataframe.columns
        and timestamp_column not in selected
    ):
        selected.append(timestamp_column)

    result = dataframe[selected].copy()

    rename_map = {
        actual_column: "Actual",
        predicted_column: "Predicted",
    }

    if (
        timestamp_column
        and timestamp_column in result.columns
    ):
        rename_map[timestamp_column] = "Timestamp"

    result = result.rename(
        columns=rename_map
    )

    result["Actual"] = pd.to_numeric(
        result["Actual"],
        errors="coerce",
    )

    result["Predicted"] = pd.to_numeric(
        result["Predicted"],
        errors="coerce",
    )

    result = result.replace(
        [np.inf, -np.inf],
        np.nan,
    )

    result = result.dropna(
        subset=[
            "Actual",
            "Predicted",
        ]
    )

    if result.empty:
        return result

    if "Timestamp" in result.columns:
        result["Timestamp"] = pd.to_datetime(
            result["Timestamp"],
            errors="coerce",
        )

        result = result.dropna(
            subset=["Timestamp"]
        )

        result = result.sort_values(
            "Timestamp"
        )

        if result["Timestamp"].duplicated().any():
            return pd.DataFrame()

    result["Residual"] = (
        result["Actual"] - result["Predicted"]
    )

    result["Absolute_Error"] = (
        result["Residual"].abs()
    )

    result["Squared_Error"] = (
        result["Residual"] ** 2
    )

    return result.reset_index(
        drop=True
    )


def calculate_forecast_bias_cal_metrics(
    dataframe,
):
    """Calculate error metrics for a forecast dataset."""

    if (
        dataframe is None
        or dataframe.empty
        or not {
            "Actual",
            "Predicted",
        }.issubset(dataframe.columns)
    ):
        return {}

    actual = dataframe["Actual"].to_numpy(
        dtype=float
    )

    predicted = dataframe["Predicted"].to_numpy(
        dtype=float
    )

    residual = actual - predicted

    absolute_error_sum = float(
        np.sum(np.abs(residual))
    )

    actual_absolute_sum = float(
        np.sum(np.abs(actual))
    )

    mean_actual = float(
        np.mean(actual)
    )

    mean_predicted = float(
        np.mean(predicted)
    )

    return {
        "Observation_Count": int(
            len(dataframe)
        ),
        "MAE": float(
            np.mean(np.abs(residual))
        ),
        "RMSE": float(
            np.sqrt(np.mean(residual ** 2))
        ),
        "WAPE_Percentage": (
            absolute_error_sum
            / actual_absolute_sum
            * 100
            if actual_absolute_sum > 0
            else np.nan
        ),
        "Mean_Residual": float(
            np.mean(residual)
        ),
        "Mean_Actual": mean_actual,
        "Mean_Predicted": mean_predicted,
        "Mean_Prediction_Bias": float(
            mean_predicted - mean_actual
        ),
    }


def calculate_forecast_bias_calibration_parameters(
    training_data,
    method="Additive Correction",
):
    """
    Estimate correction parameters from training data only.

    Additive:
        corrected_prediction = prediction + mean_residual

    Proportional:
        corrected_prediction = prediction * scale_factor
    """

    if (
        training_data is None
        or training_data.empty
        or not {
            "Actual",
            "Predicted",
        }.issubset(training_data.columns)
    ):
        return {
            "Available": False,
            "Reason": "Training data is unavailable.",
        }

    actual = training_data["Actual"].to_numpy(
        dtype=float
    )

    predicted = training_data["Predicted"].to_numpy(
        dtype=float
    )

    if len(actual) < 2:
        return {
            "Available": False,
            "Reason": "At least two training observations are required.",
        }

    if method == "Additive Correction":
        correction = float(
            np.mean(actual - predicted)
        )

        return {
            "Available": True,
            "Method": method,
            "Additive_Correction": correction,
            "Reason": (
                "Correction estimated from the mean training residual."
            ),
        }

    if method == "Proportional Correction":
        prediction_sum = float(
            np.sum(predicted)
        )

        actual_sum = float(
            np.sum(actual)
        )

        if prediction_sum == 0:
            return {
                "Available": False,
                "Reason": (
                    "Training predictions sum to zero; "
                    "a proportional factor cannot be estimated."
                ),
            }

        scale_factor = (
            actual_sum / prediction_sum
        )

        if not np.isfinite(scale_factor):
            return {
                "Available": False,
                "Reason": "The calculated scale factor is invalid.",
            }

        return {
            "Available": True,
            "Method": method,
            "Scale_Factor": float(
                scale_factor
            ),
            "Reason": (
                "Scale factor estimated from training-set totals."
            ),
        }

    return {
        "Available": False,
        "Reason": "Unsupported calibration method.",
    }


def apply_forecast_bias_calibration(
    dataframe,
    calibration_parameters,
):
    """Apply fixed training-derived parameters to forecast values."""

    if (
        dataframe is None
        or dataframe.empty
        or not calibration_parameters
        or not calibration_parameters.get("Available")
    ):
        return pd.DataFrame()

    result = dataframe.copy()

    if (
        calibration_parameters["Method"]
        == "Additive Correction"
    ):
        correction = calibration_parameters[
            "Additive_Correction"
        ]

        result["Corrected_Predicted"] = (
            result["Predicted"] + correction
        )

    elif (
        calibration_parameters["Method"]
        == "Proportional Correction"
    ):
        scale_factor = calibration_parameters[
            "Scale_Factor"
        ]

        result["Corrected_Predicted"] = (
            result["Predicted"] * scale_factor
        )

    else:
        return pd.DataFrame()

    result["Original_Residual"] = (
        result["Actual"] - result["Predicted"]
    )

    result["Corrected_Residual"] = (
        result["Actual"]
        - result["Corrected_Predicted"]
    )

    result["Original_Absolute_Error"] = (
        result["Original_Residual"].abs()
    )

    result["Corrected_Absolute_Error"] = (
        result["Corrected_Residual"].abs()
    )

    return result


def build_forecast_bias_calibration_comparison(
    holdout_data,
):
    """Compare original and corrected forecasts on holdout data."""

    if (
        holdout_data is None
        or holdout_data.empty
        or "Corrected_Predicted" not in holdout_data.columns
    ):
        return pd.DataFrame()

    original = calculate_forecast_bias_cal_metrics(
        holdout_data[
            ["Actual", "Predicted"]
        ]
    )

    corrected_dataframe = holdout_data[
        ["Actual", "Corrected_Predicted"]
    ].rename(
        columns={
            "Corrected_Predicted": "Predicted"
        }
    )

    corrected = calculate_forecast_bias_cal_metrics(
        corrected_dataframe
    )

    if not original or not corrected:
        return pd.DataFrame()

    rows = []

    for metric in [
        "MAE",
        "RMSE",
        "WAPE_Percentage",
        "Mean_Residual",
        "Mean_Prediction_Bias",
    ]:
        original_value = original.get(
            metric,
            np.nan,
        )

        corrected_value = corrected.get(
            metric,
            np.nan,
        )

        if (
            pd.notna(original_value)
            and pd.notna(corrected_value)
        ):
            difference = (
                corrected_value - original_value
            )
        else:
            difference = np.nan

        rows.append({
            "Metric": metric,
            "Original_Forecast": original_value,
            "Corrected_Forecast": corrected_value,
            "Change_After_Correction": difference,
        })

    return pd.DataFrame(rows)


def evaluate_forecast_bias_calibration(
    dataframe,
    train_ratio=FORECAST_BIAS_CAL_DEFAULT_TRAIN_RATIO,
    method="Additive Correction",
):
    """
    Evaluate a correction using chronological train/holdout separation.

    A timestamp column is required for a chronological holdout.
    The correction is estimated only from the earlier training period.
    """

    if dataframe is None or dataframe.empty:
        return {
            "Success": False,
            "Reason": "No valid forecast observations are available.",
        }

    if "Timestamp" not in dataframe.columns:
        return {
            "Success": False,
            "Reason": (
                "A timestamp column is required to establish "
                "a chronological holdout and reduce leakage risk."
            ),
        }

    try:
        train_ratio = float(
            train_ratio
        )
    except (TypeError, ValueError):
        return {
            "Success": False,
            "Reason": "The training ratio must be numeric.",
        }

    if not (
        FORECAST_BIAS_CAL_MINIMUM_TRAIN_RATIO
        <= train_ratio
        <= FORECAST_BIAS_CAL_MAXIMUM_TRAIN_RATIO
    ):
        return {
            "Success": False,
            "Reason": (
                "Choose a training ratio between 50% and 90%."
            ),
        }

    ordered = dataframe.sort_values(
        "Timestamp"
    ).reset_index(
        drop=True
    )

    total_rows = len(ordered)

    split_index = int(
        total_rows * train_ratio
    )

    if (
        split_index < 2
        or total_rows - split_index < 2
    ):
        return {
            "Success": False,
            "Reason": (
                "The dataset is too small for separate training "
                "and holdout periods."
            ),
        }

    training_data = ordered.iloc[
        :split_index
    ].copy()

    holdout_data = ordered.iloc[
        split_index:
    ].copy()

    parameters = (
        calculate_forecast_bias_calibration_parameters(
            training_data,
            method=method,
        )
    )

    if not parameters.get("Available"):
        return {
            "Success": False,
            "Reason": parameters.get(
                "Reason",
                "Calibration parameters could not be estimated.",
            ),
        }

    calibrated_holdout = (
        apply_forecast_bias_calibration(
            holdout_data,
            parameters,
        )
    )

    if calibrated_holdout.empty:
        return {
            "Success": False,
            "Reason": (
                "Corrected holdout forecasts could not be calculated."
            ),
        }

    comparison = (
        build_forecast_bias_calibration_comparison(
            calibrated_holdout
        )
    )

    training_metrics = (
        calculate_forecast_bias_cal_metrics(
            training_data
        )
    )

    holdout_original_metrics = (
        calculate_forecast_bias_cal_metrics(
            holdout_data
        )
    )

    return {
        "Success": True,
        "Reason": (
            "Calibration evaluated on a separate chronological holdout."
        ),
        "Method": method,
        "Training_Ratio": train_ratio,
        "Training_Row_Count": len(training_data),
        "Holdout_Row_Count": len(holdout_data),
        "Training_Start": training_data["Timestamp"].min(),
        "Training_End": training_data["Timestamp"].max(),
        "Holdout_Start": holdout_data["Timestamp"].min(),
        "Holdout_End": holdout_data["Timestamp"].max(),
        "Calibration_Parameters": parameters,
        "Training_Metrics": training_metrics,
        "Original_Holdout_Metrics": holdout_original_metrics,
        "Holdout_Comparison": comparison,
        "Holdout_Details": calibrated_holdout,
    }


def generate_forecast_bias_calibration_interpretation(
    evaluation,
):
    """Explain holdout calibration results."""

    messages = []

    if (
        not evaluation
        or not evaluation.get("Success")
    ):
        messages.append(
            "Calibration evaluation was not completed."
        )
        return messages

    comparison = evaluation.get(
        "Holdout_Comparison",
        pd.DataFrame(),
    )

    if comparison.empty:
        messages.append(
            "No valid holdout comparison metrics are available."
        )
        return messages

    messages.append(
        "Correction parameters were estimated using the earlier "
        "training period, then evaluated on later holdout observations."
    )

    for metric in [
        "MAE",
        "RMSE",
        "WAPE_Percentage",
    ]:
        matching = comparison[
            comparison["Metric"] == metric
        ]

        if matching.empty:
            continue

        row = matching.iloc[0]

        original = row["Original_Forecast"]
        corrected = row["Corrected_Forecast"]

        if pd.isna(original) or pd.isna(corrected):
            continue

        if corrected < original:
            messages.append(
                f"{metric}: the corrected holdout result improved "
                f"from {original:.4f} to {corrected:.4f}."
            )

        elif corrected > original:
            messages.append(
                f"{metric}: the corrected holdout result worsened "
                f"from {original:.4f} to {corrected:.4f}."
            )

        else:
            messages.append(
                f"{metric}: the corrected and original results "
                "were equal on the holdout."
            )

    messages.append(
        "A single chronological holdout is not sufficient to establish "
        "reliable future performance. Repeat the evaluation across "
        "multiple periods before adopting a correction."
    )

    return messages


def render_forecast_bias_calibration_upload():
    """Upload a dataset containing historical actual and predicted values."""

    st.subheader(
        "1. Upload Historical Forecast Results"
    )

    uploaded_file = st.file_uploader(
        "Upload CSV with actual, predicted and timestamp columns",
        type=["csv"],
        key="forecast_bias_cal_upload",
    )

    if uploaded_file is None:
        st.info(
            "Use historical predictions that can be matched with "
            "their actual observed values."
        )
        return None

    try:
        dataframe = pd.read_csv(
            uploaded_file
        )
    except Exception as exc:
        st.error(
            f"Unable to read the CSV: {exc}"
        )
        return None

    if dataframe.empty:
        st.warning(
            "The uploaded CSV contains no records."
        )
        return None

    return dataframe


def render_forecast_bias_calibration_mapping(
    dataframe,
):
    """Choose timestamp, actual and predicted columns."""

    if dataframe is None or dataframe.empty:
        return None

    st.subheader(
        "2. Map Forecast Columns"
    )

    columns = dataframe.columns.tolist()

    def choose_column(
        label,
        preferred,
        key,
    ):
        options = ["Select a column"] + columns

        index = (
            columns.index(preferred) + 1
            if preferred in columns
            else 0
        )

        selected = st.selectbox(
            label,
            options=options,
            index=index,
            key=key,
        )

        return (
            None
            if selected == "Select a column"
            else selected
        )

    timestamp_column = choose_column(
        "Timestamp",
        "Timestamp",
        "forecast_bias_cal_timestamp",
    )

    actual_column = choose_column(
        "Actual values",
        "Actual",
        "forecast_bias_cal_actual",
    )

    predicted_column = choose_column(
        "Predicted values",
        "Predicted",
        "forecast_bias_cal_predicted",
    )

    if any(
        value is None
        for value in [
            timestamp_column,
            actual_column,
            predicted_column,
        ]
    ):
        st.info(
            "Select all three columns to continue."
        )
        return None

    if len({
        timestamp_column,
        actual_column,
        predicted_column,
    }) != 3:
        st.error(
            "Timestamp, actual and predicted columns must be different."
        )
        return None

    return {
        "timestamp_column": timestamp_column,
        "actual_column": actual_column,
        "predicted_column": predicted_column,
    }


