def render_forecast_bias_calibration_center():
    """Main interface for forecast bias correction analysis."""

    st.header(
        "Forecast Bias & Error Calibration Center"
    )

    st.write(
        "Investigate systematic forecast bias and evaluate simple "
        "corrections on a separate later holdout period."
    )

    st.warning(
        "This tool evaluates historical predictions. It does not "
        "generate a new forecasting model or guarantee better future "
        "performance."
    )

    uploaded = render_forecast_bias_calibration_upload()

    if uploaded is None:
        return

    mapping = render_forecast_bias_calibration_mapping(
        uploaded
    )

    if mapping is None:
        return

    prepared = prepare_forecast_bias_cal_data(
        uploaded,
        actual_column=mapping["actual_column"],
        predicted_column=mapping["predicted_column"],
        timestamp_column=mapping["timestamp_column"],
    )

    if prepared.empty:
        st.error(
            "No valid observations remain. Check the selected columns, "
            "timestamps and duplicate timestamps."
        )
        return

    st.write(
        f"**Valid observations:** {len(prepared):,}"
    )

    if len(prepared) < FORECAST_BIAS_CAL_MINIMUM_ROWS:
        st.warning(
            f"At least {FORECAST_BIAS_CAL_MINIMUM_ROWS} observations "
            "are recommended for this experiment."
        )
        return

    controls = render_forecast_bias_calibration_controls()

    if not st.button(
        "Run Bias Calibration Evaluation",
        key="forecast_bias_cal_run",
        type="primary",
    ):
        st.info(
            "Choose the split and correction method, then run the evaluation."
        )
        return

    evaluation = evaluate_forecast_bias_calibration(
        prepared,
        train_ratio=controls["train_ratio"],
        method=controls["method"],
    )

    if not evaluation.get("Success"):
        st.error(
            evaluation.get(
                "Reason",
                "The calibration evaluation could not be completed.",
            )
        )
        return

    render_forecast_bias_calibration_metrics(
        evaluation
    )

    render_forecast_bias_calibration_comparison(
        evaluation["Holdout_Comparison"]
    )

    render_forecast_bias_calibration_parameters(
        evaluation["Calibration_Parameters"]
    )

    render_forecast_bias_calibration_interpretation(
        evaluation
    )

    render_forecast_bias_calibration_export(
        evaluation
    )


def get_forecast_bias_calibration_module_information():
    """Return metadata for the forecast bias calibration module."""

    return {
        "name": "Forecast Bias & Error Calibration Center",
        "version": FORECAST_BIAS_CAL_VERSION,
        "minimum_rows": FORECAST_BIAS_CAL_MINIMUM_ROWS,
        "supported_methods": FORECAST_BIAS_CAL_METHODS,
        "requires_timestamp": True,
        "uses_chronological_holdout": True,
        "description": (
            "Estimates simple bias corrections from historical "
            "training predictions and compares them on later holdout data."
        ),
    }


