# ============================================================
# PART 31 â€” DEMAND FORECAST RISK & DECISION SUPPORT CENTER
# ============================================================

DEMAND_RISK_CENTER_VERSION = "1.0.0"

DEMAND_RISK_CENTER_MINIMUM_PERIODS = 5
DEMAND_RISK_CENTER_DEFAULT_WINDOW = 7
DEMAND_RISK_CENTER_MAXIMUM_DISPLAY_ROWS = 2000

DEMAND_RISK_CENTER_LEVELS = [
    "Low",
    "Moderate",
    "High",
    "Very High",
]


def prepare_demand_risk_center_data(
    dataframe,
    timestamp_column="Timestamp",
    demand_column="Sales Count",
    actual_column=None,
    predicted_column=None,
):
    """Prepare time-series demand and optional forecast errors."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    required = [
        timestamp_column,
        demand_column,
    ]

    if any(
        column not in dataframe.columns
        for column in required
    ):
        return pd.DataFrame()

    selected = list(required)

    for column in [
        actual_column,
        predicted_column,
    ]:
        if (
            column
            and column in dataframe.columns
            and column not in selected
        ):
            selected.append(column)

    result = dataframe[selected].copy()

    rename_map = {
        timestamp_column: "Timestamp",
        demand_column: "Demand",
    }

    if actual_column in result.columns if actual_column else False:
        rename_map[actual_column] = "Actual"

    if predicted_column in result.columns if predicted_column else False:
        rename_map[predicted_column] = "Predicted"

    result = result.rename(
        columns=rename_map
    )

    result["Timestamp"] = pd.to_datetime(
        result["Timestamp"],
        errors="coerce",
    )

    result["Demand"] = pd.to_numeric(
        result["Demand"],
        errors="coerce",
    )

    result = result.replace(
        [np.inf, -np.inf],
        np.nan,
    )

    result = result.dropna(
        subset=[
            "Timestamp",
            "Demand",
        ]
    )

    if result.empty:
        return pd.DataFrame()

    if (result["Demand"] < 0).any():
        result["Negative_Demand_Flag"] = (
            result["Demand"] < 0
        )
    else:
        result["Negative_Demand_Flag"] = False

    if {"Actual", "Predicted"}.issubset(result.columns):
        result["Actual"] = pd.to_numeric(
            result["Actual"],
            errors="coerce",
        )

        result["Predicted"] = pd.to_numeric(
            result["Predicted"],
            errors="coerce",
        )

        result["Forecast_Error"] = (
            result["Actual"] - result["Predicted"]
        )

        result["Absolute_Forecast_Error"] = (
            result["Forecast_Error"].abs()
        )

    return result.sort_values(
        "Timestamp"
    ).reset_index(
        drop=True
    )


def aggregate_demand_risk_periods(
    dataframe,
    frequency="D",
):
    """Aggregate demand by day, week or month."""

    if (
        dataframe is None
        or dataframe.empty
        or not {
            "Timestamp",
            "Demand",
        }.issubset(dataframe.columns)
    ):
        return pd.DataFrame()

    frequency_map = {
        "Daily": "D",
        "Weekly": "W",
        "Monthly": "MS",
        "D": "D",
        "W": "W",
        "MS": "MS",
    }

    selected_frequency = frequency_map.get(
        frequency
    )

    if selected_frequency is None:
        raise ValueError(
            "Unsupported aggregation frequency."
        )

    result = dataframe[
        ["Timestamp", "Demand"]
    ].copy()

    result = result.sort_values(
        "Timestamp"
    ).set_index(
        "Timestamp"
    )

    aggregated = result["Demand"].resample(
        selected_frequency
    ).agg([
        "sum",
        "mean",
        "std",
        "count",
    ])

    aggregated = aggregated.rename(
        columns={
            "sum": "Total_Demand",
            "mean": "Mean_Demand",
            "std": "Demand_Standard_Deviation",
            "count": "Observation_Count",
        }
    )

    aggregated["Demand_Standard_Deviation"] = (
        aggregated["Demand_Standard_Deviation"].fillna(0)
    )

    return aggregated.reset_index()


def calculate_demand_risk_center_metrics(
    aggregated_data,
):
    """Calculate descriptive variability and change indicators."""

    if (
        aggregated_data is None
        or aggregated_data.empty
        or "Total_Demand" not in aggregated_data.columns
    ):
        return {}

    demand = pd.to_numeric(
        aggregated_data["Total_Demand"],
        errors="coerce",
    ).dropna()

    if demand.empty:
        return {}

    mean_demand = float(
        demand.mean()
    )

    std_demand = float(
        demand.std(ddof=0)
    )

    cv = (
        std_demand / abs(mean_demand)
        if mean_demand != 0
        else np.nan
    )

    changes = demand.pct_change().replace(
        [np.inf, -np.inf],
        np.nan,
    )

    return {
        "Period_Count": int(len(demand)),
        "Total_Demand": float(demand.sum()),
        "Mean_Period_Demand": mean_demand,
        "Median_Period_Demand": float(demand.median()),
        "Standard_Deviation": std_demand,
        "Coefficient_of_Variation": float(cv),
        "Maximum_Period_Demand": float(demand.max()),
        "Minimum_Period_Demand": float(demand.min()),
        "Mean_Absolute_Period_Change_Percentage": (
            float(changes.abs().mean() * 100)
            if changes.notna().any()
            else np.nan
        ),
    }


def classify_demand_risk_center(
    coefficient_of_variation,
):
    """Classify variability using explicit heuristic thresholds."""

    if pd.isna(coefficient_of_variation):
        return "Unavailable"

    if coefficient_of_variation < 0:
        return "Unavailable"

    if coefficient_of_variation < 0.20:
        return "Low"

    if coefficient_of_variation < 0.40:
        return "Moderate"

    if coefficient_of_variation < 0.70:
        return "High"

    return "Very High"


def identify_demand_risk_center_periods(
    aggregated_data,
    percentile=90,
):
    """Identify periods with unusually high aggregated demand."""

    if (
        aggregated_data is None
        or aggregated_data.empty
        or "Total_Demand" not in aggregated_data.columns
    ):
        return pd.DataFrame()

    result = aggregated_data.copy()

    demand = pd.to_numeric(
        result["Total_Demand"],
        errors="coerce",
    )

    valid = demand.dropna()

    if valid.empty:
        return pd.DataFrame()

    threshold = float(
        valid.quantile(percentile / 100)
    )

    result["High_Demand_Threshold"] = threshold

    result["High_Demand_Flag"] = (
        demand >= threshold
    )

    result["Demand_Rank"] = demand.rank(
        method="min",
        ascending=False,
    )

    return result.sort_values(
        "Demand_Rank"
    ).reset_index(
        drop=True
    )


def calculate_demand_risk_center_changes(
    aggregated_data,
):
    """Identify large period-to-period changes."""

    if (
        aggregated_data is None
        or aggregated_data.empty
        or not {
            "Timestamp",
            "Total_Demand",
        }.issubset(aggregated_data.columns)
    ):
        return pd.DataFrame()

    result = aggregated_data.copy()

    result["Previous_Period_Demand"] = (
        result["Total_Demand"].shift(1)
    )

    result["Absolute_Change"] = (
        result["Total_Demand"]
        - result["Previous_Period_Demand"]
    )

    result["Percentage_Change"] = (
        result["Total_Demand"]
        .pct_change()
        .replace(
            [np.inf, -np.inf],
            np.nan,
        )
        * 100
    )

    result["Absolute_Percentage_Change"] = (
        result["Percentage_Change"].abs()
    )

    return result.sort_values(
        "Absolute_Change",
        key=lambda series: series.abs(),
        ascending=False,
    ).reset_index(
        drop=True
    )


def build_demand_risk_center_recommendations(
    metrics,
    high_demand_periods,
    large_changes,
):
    """Generate cautious planning suggestions from observed patterns."""

    recommendations = []

    if not metrics:
        return [
            "Insufficient valid demand data for recommendations."
        ]

    cv = metrics.get(
        "Coefficient_of_Variation",
        np.nan,
    )

    risk_level = classify_demand_risk_center(
        cv
    )

    if risk_level in ["High", "Very High"]:
        recommendations.append(
            "Demand varies substantially across the selected periods. "
            "Review staffing and operating plans against historical "
            "high- and low-demand periods."
        )

    elif risk_level == "Moderate":
        recommendations.append(
            "Demand variability is moderate. Review recurring peaks "
            "and avoid relying only on the average period demand."
        )

    elif risk_level == "Low":
        recommendations.append(
            "Demand variability is relatively low under this heuristic. "
            "Continue monitoring for seasonal or structural changes."
        )

    if (
        high_demand_periods is not None
        and not high_demand_periods.empty
        and "High_Demand_Flag" in high_demand_periods.columns
        and high_demand_periods["High_Demand_Flag"].any()
    ):
        recommendations.append(
            "Review periods above the selected historical demand "
            "percentile when preparing future operational schedules."
        )

    if (
        large_changes is not None
        and not large_changes.empty
        and "Absolute_Percentage_Change" in large_changes.columns
    ):
        changes = large_changes[
            "Absolute_Percentage_Change"
        ].dropna()

        if not changes.empty and changes.max() >= 30:
            recommendations.append(
                "Large period-to-period changes were observed. "
                "Investigate possible calendar effects, missing records "
                "and unusual demand patterns before changing plans."
            )

    recommendations.append(
        "These recommendations are descriptive. They do not establish "
        "actual ferry capacity, passenger occupancy or safety risk."
    )

    return recommendations


def build_demand_risk_center_report(
    prepared_data,
    frequency="Daily",
    high_demand_percentile=90,
):
    """Build the demand risk and decision-support report."""

    if prepared_data is None or prepared_data.empty:
        return {
            "Success": False,
            "Reason": "No valid demand observations are available.",
        }

    aggregated = aggregate_demand_risk_periods(
        prepared_data,
        frequency=frequency,
    )

    if aggregated.empty:
        return {
            "Success": False,
            "Reason": "Demand aggregation produced no valid periods.",
        }

    metrics = calculate_demand_risk_center_metrics(
        aggregated
    )

    if not metrics:
        return {
            "Success": False,
            "Reason": "Demand metrics could not be calculated.",
        }

    high_periods = identify_demand_risk_center_periods(
        aggregated,
        percentile=high_demand_percentile,
    )

    changes = calculate_demand_risk_center_changes(
        aggregated
    )

    recommendations = (
        build_demand_risk_center_recommendations(
            metrics,
            high_periods,
            changes,
        )
    )

    return {
        "Success": True,
        "Metrics": metrics,
        "Risk_Level": classify_demand_risk_center(
            metrics.get(
                "Coefficient_of_Variation",
                np.nan,
            )
        ),
        "Aggregated_Demand": aggregated,
        "High_Demand_Periods": high_periods,
        "Period_Changes": changes,
        "Recommendations": recommendations,
    }


