# ============================================================
# PART 32 â€” DEMAND DATA QUALITY & RELIABILITY CENTER
# ============================================================

DEMAND_QUALITY_CENTER_VERSION = "1.0.0"

DEMAND_QUALITY_REQUIRED_COLUMNS = [
    "Timestamp",
    "Sales Count",
    "Redemption Count",
]

DEMAND_QUALITY_NUMERIC_COLUMNS = [
    "Sales Count",
    "Redemption Count",
]

DEMAND_QUALITY_MAX_DISPLAY_ROWS = 2000


def prepare_demand_quality_data(
    dataframe,
    timestamp_column="Timestamp",
    numeric_columns=None,
):
    """Prepare a copy of the dataset for quality assessment."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    if timestamp_column not in dataframe.columns:
        return pd.DataFrame()

    if numeric_columns is None:
        numeric_columns = (
            DEMAND_QUALITY_NUMERIC_COLUMNS
        )

    selected_numeric = [
        column
        for column in numeric_columns
        if column in dataframe.columns
    ]

    result = dataframe.copy()

    result["Source_Row_Number"] = np.arange(
        1,
        len(result) + 1,
    )

    result["Original_Timestamp"] = (
        result[timestamp_column].copy()
    )

    result["Parsed_Timestamp"] = pd.to_datetime(
        result[timestamp_column],
        errors="coerce",
    )

    result["Invalid_Timestamp_Flag"] = (
        result["Parsed_Timestamp"].isna()
    )

    for column in selected_numeric:
        original_values = result[column].copy()

        numeric_values = pd.to_numeric(
            original_values,
            errors="coerce",
        )

        result[f"{column}__Numeric"] = numeric_values

        result[f"{column}__Invalid_Flag"] = (
            original_values.notna()
            & numeric_values.isna()
        )

        result[f"{column}__Missing_Flag"] = (
            original_values.isna()
        )

        result[f"{column}__Negative_Flag"] = (
            numeric_values < 0
        )

        result[f"{column}__NonInteger_Flag"] = (
            numeric_values.notna()
            & (numeric_values % 1 != 0)
        )

    result["Duplicate_Timestamp_Flag"] = False

    valid_timestamp_mask = (
        result["Parsed_Timestamp"].notna()
    )

    result.loc[
        valid_timestamp_mask,
        "Duplicate_Timestamp_Flag",
    ] = (
        result.loc[
            valid_timestamp_mask,
            "Parsed_Timestamp",
        ].duplicated(
            keep=False
        )
    )

    result["Duplicate_Row_Flag"] = (
        dataframe.duplicated(
            keep=False
        )
    )

    return result


def calculate_demand_quality_column_summary(
    dataframe,
):
    """Summarize missing, invalid and negative numeric values."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    rows = []

    for column in DEMAND_QUALITY_NUMERIC_COLUMNS:
        if column not in dataframe.columns:
            rows.append({
                "Column": column,
                "Column_Available": False,
                "Missing_Count": np.nan,
                "Invalid_Numeric_Count": np.nan,
                "Negative_Count": np.nan,
                "Non_Integer_Count": np.nan,
            })
            continue

        numeric_values = pd.to_numeric(
            dataframe[column],
            errors="coerce",
        )

        invalid_numeric = (
            dataframe[column].notna()
            & numeric_values.isna()
        )

        rows.append({
            "Column": column,
            "Column_Available": True,
            "Missing_Count": int(
                dataframe[column].isna().sum()
            ),
            "Invalid_Numeric_Count": int(
                invalid_numeric.sum()
            ),
            "Negative_Count": int(
                (numeric_values < 0).sum()
            ),
            "Non_Integer_Count": int(
                (
                    numeric_values.notna()
                    & (numeric_values % 1 != 0)
                ).sum()
            ),
        })

    return pd.DataFrame(rows)


def calculate_demand_quality_timestamp_summary(
    dataframe,
):
    """Summarize timestamp validity and duplicate timestamp groups."""

    if dataframe is None or dataframe.empty:
        return {}

    parsed = pd.to_datetime(
        dataframe["Timestamp"],
        errors="coerce",
    )

    valid = parsed.dropna()

    duplicate_rows = int(
        valid.duplicated(
            keep=False
        ).sum()
    )

    unique_timestamp_count = int(
        valid.nunique()
    )

    return {
        "Total_Rows": int(len(dataframe)),
        "Valid_Timestamp_Rows": int(valid.notna().sum()),
        "Invalid_Timestamp_Rows": int(parsed.isna().sum()),
        "Unique_Valid_Timestamps": unique_timestamp_count,
        "Duplicate_Timestamp_Rows": duplicate_rows,
        "Earliest_Timestamp": (
            valid.min()
            if not valid.empty
            else pd.NaT
        ),
        "Latest_Timestamp": (
            valid.max()
            if not valid.empty
            else pd.NaT
        ),
    }


def calculate_demand_quality_duplicate_summary(
    dataframe,
):
    """Report exact duplicate rows and duplicate timestamps separately."""

    if dataframe is None or dataframe.empty:
        return {}

    timestamp = pd.to_datetime(
        dataframe["Timestamp"],
        errors="coerce",
    )

    valid = timestamp.notna()

    return {
        "Exact_Duplicate_Rows": int(
            dataframe.duplicated(
                keep=False
            ).sum()
        ),
        "Exact_Duplicate_Extra_Rows": int(
            dataframe.duplicated(
                keep="first"
            ).sum()
        ),
        "Duplicate_Timestamp_Rows": int(
            timestamp[valid].duplicated(
                keep=False
            ).sum()
        ),
        "Duplicate_Timestamp_Extra_Rows": int(
            timestamp[valid].duplicated(
                keep="first"
            ).sum()
        ),
    }


def calculate_demand_quality_date_coverage(
    dataframe,
):
    """Calculate date-level observation coverage."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    timestamp = pd.to_datetime(
        dataframe["Timestamp"],
        errors="coerce",
    )

    valid = timestamp.dropna()

    if valid.empty:
        return pd.DataFrame()

    dates = pd.DataFrame({
        "Date": valid.dt.normalize()
    })

    daily_counts = dates.groupby(
        "Date"
    ).size().rename(
        "Observation_Count"
    ).reset_index()

    full_calendar = pd.date_range(
        start=daily_counts["Date"].min(),
        end=daily_counts["Date"].max(),
        freq="D",
    )

    calendar = pd.DataFrame({
        "Date": full_calendar
    })

    result = calendar.merge(
        daily_counts,
        on="Date",
        how="left",
    )

    result["Observation_Count"] = (
        result["Observation_Count"].fillna(0).astype(int)
    )

    result["Has_Observation"] = (
        result["Observation_Count"] > 0
    )

    result["Date_Gap_Flag"] = (
        ~result["Has_Observation"]
    )

    return result


def calculate_demand_quality_integrity_checks(
    dataframe,
):
    """Evaluate key integrity conditions without modifying source data."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    checks = []

    required_columns = (
        DEMAND_QUALITY_REQUIRED_COLUMNS
    )

    for column in required_columns:
        available = column in dataframe.columns

        checks.append({
            "Check": f"Required column: {column}",
            "Status": (
                "PASS"
                if available
                else "FAIL"
            ),
            "Affected_Rows": (
                0
                if available
                else len(dataframe)
            ),
            "Explanation": (
                "Column is available."
                if available
                else "Required column is missing."
            ),
        })

    timestamp = pd.to_datetime(
        dataframe["Timestamp"],
        errors="coerce",
    )

    invalid_timestamp_count = int(
        timestamp.isna().sum()
    )

    checks.append({
        "Check": "Valid timestamps",
        "Status": (
            "PASS"
            if invalid_timestamp_count == 0
            else "WARNING"
        ),
        "Affected_Rows": invalid_timestamp_count,
        "Explanation": (
            "All timestamps could be parsed."
            if invalid_timestamp_count == 0
            else "Some timestamps could not be parsed."
        ),
    })

    duplicate_timestamp_count = int(
        timestamp.dropna().duplicated(
            keep=False
        ).sum()
    )

    checks.append({
        "Check": "Duplicate timestamps",
        "Status": (
            "PASS"
            if duplicate_timestamp_count == 0
            else "WARNING"
        ),
        "Affected_Rows": duplicate_timestamp_count,
        "Explanation": (
            "No duplicate valid timestamps were detected."
            if duplicate_timestamp_count == 0
            else (
                "Some records share a timestamp. This may be valid "
                "if timestamps represent multiple transactions."
            )
        ),
    })

    for column in DEMAND_QUALITY_NUMERIC_COLUMNS:
        if column not in dataframe.columns:
            continue

        numeric = pd.to_numeric(
            dataframe[column],
            errors="coerce",
        )

        invalid = int(
            (
                dataframe[column].notna()
                & numeric.isna()
            ).sum()
        )

        negative = int(
            (numeric < 0).sum()
        )

        checks.append({
            "Check": f"Numeric validity: {column}",
            "Status": (
                "PASS"
                if invalid == 0 and negative == 0
                else "WARNING"
            ),
            "Affected_Rows": invalid + negative,
            "Explanation": (
                "No invalid numeric strings or negative values found."
                if invalid == 0 and negative == 0
                else (
                    f"Invalid numeric values: {invalid}; "
                    f"negative values: {negative}."
                )
            ),
        })

    return pd.DataFrame(checks)


def calculate_demand_quality_scorecard(
    dataframe,
):
    """Build a transparent, heuristic data-quality scorecard."""

    if dataframe is None or dataframe.empty:
        return {
            "Available": False,
            "Reason": "No source data is available.",
        }

    total_rows = len(dataframe)

    timestamp = pd.to_datetime(
        dataframe["Timestamp"],
        errors="coerce",
    )

    invalid_timestamps = int(
        timestamp.isna().sum()
    )

    duplicate_rows = int(
        dataframe.duplicated(
            keep="first"
        ).sum()
    )

    component_scores = {
        "Timestamp Validity": (
            100 * (1 - invalid_timestamps / total_rows)
        ),
        "Exact Row Uniqueness": (
            100 * (1 - duplicate_rows / total_rows)
        ),
    }

    for column in DEMAND_QUALITY_NUMERIC_COLUMNS:
        if column not in dataframe.columns:
            component_scores[
                f"{column} Validity"
            ] = 0.0
            continue

        numeric = pd.to_numeric(
            dataframe[column],
            errors="coerce",
        )

        invalid_numeric = (
            dataframe[column].notna()
            & numeric.isna()
        )

        negative = (
            numeric < 0
        ).fillna(False)

        invalid_count = int(
            (
                invalid_numeric
                | negative
            ).sum()
        )

        component_scores[
            f"{column} Validity"
        ] = (
            100 * (1 - invalid_count / total_rows)
        )

    overall_score = float(
        np.mean(
            list(component_scores.values())
        )
    )

    if overall_score >= 95:
        grade = "Excellent"
    elif overall_score >= 85:
        grade = "Good"
    elif overall_score >= 70:
        grade = "Needs Review"
    else:
        grade = "Poor"

    return {
        "Available": True,
        "Overall_Score": overall_score,
        "Grade": grade,
        "Component_Scores": component_scores,
        "Total_Rows": total_rows,
    }


def generate_demand_quality_recommendations(
    column_summary,
    timestamp_summary,
    duplicate_summary,
    date_coverage,
):
    """Generate remediation suggestions from observed data issues."""

    recommendations = []

    if timestamp_summary:
        invalid_count = timestamp_summary.get(
            "Invalid_Timestamp_Rows",
            0,
        )

        if invalid_count > 0:
            recommendations.append(
                f"Investigate {invalid_count:,} rows with invalid "
                "timestamps before using them in time-series analysis."
            )

    if duplicate_summary:
        duplicate_count = duplicate_summary.get(
            "Exact_Duplicate_Extra_Rows",
            0,
        )

        if duplicate_count > 0:
            recommendations.append(
                f"Review {duplicate_count:,} exact duplicate extra rows. "
                "Confirm they are unintended before removing them."
            )

        timestamp_duplicates = duplicate_summary.get(
            "Duplicate_Timestamp_Extra_Rows",
            0,
        )

        if timestamp_duplicates > 0:
            recommendations.append(
                f"Review {timestamp_duplicates:,} extra rows sharing "
                "timestamps. Duplicate timestamps do not necessarily "
                "mean duplicate transactions."
            )

    if column_summary is not None and not column_summary.empty:
        for _, row in column_summary.iterrows():
            column = row["Column"]

            if not row.get("Column_Available", False):
                recommendations.append(
                    f"Required demand column '{column}' is missing."
                )
                continue

            if row["Missing_Count"] > 0:
                recommendations.append(
                    f"Investigate missing values in '{column}'."
                )

            if row["Invalid_Numeric_Count"] > 0:
                recommendations.append(
                    f"Correct non-numeric entries in '{column}'."
                )

            if row["Negative_Count"] > 0:
                recommendations.append(
                    f"Review negative values in '{column}' against "
                    "the source-system business rules."
                )

            if row["Non_Integer_Count"] > 0:
                recommendations.append(
                    f"Review non-integer values in '{column}' if the "
                    "field is intended to count tickets."
                )

    if date_coverage is not None and not date_coverage.empty:
        gap_count = int(
            date_coverage["Date_Gap_Flag"].sum()
        )

        if gap_count > 0:
            recommendations.append(
                f"{gap_count:,} calendar dates have no recorded rows. "
                "Check the expected reporting schedule before treating "
                "these as missing data."
            )

    if not recommendations:
        recommendations.append(
            "No major issues were identified by the configured checks. "
            "Continue reviewing source definitions and reporting rules."
        )

    return recommendations


def build_demand_quality_center_report(
    dataframe,
):
    """Build a comprehensive demand data-quality report."""

    if dataframe is None or dataframe.empty:
        return {
            "Success": False,
            "Reason": "The source dataset is empty.",
        }

    missing_required = [
        column
        for column in DEMAND_QUALITY_REQUIRED_COLUMNS
        if column not in dataframe.columns
    ]

    if missing_required:
        return {
            "Success": False,
            "Reason": (
                "Missing required columns: "
                + ", ".join(missing_required)
            ),
        }

    prepared = prepare_demand_quality_data(
        dataframe
    )

    column_summary = (
        calculate_demand_quality_column_summary(
            dataframe
        )
    )

    timestamp_summary = (
        calculate_demand_quality_timestamp_summary(
            dataframe
        )
    )

    duplicate_summary = (
        calculate_demand_quality_duplicate_summary(
            dataframe
        )
    )

    date_coverage = (
        calculate_demand_quality_date_coverage(
            dataframe
        )
    )

    integrity_checks = (
        calculate_demand_quality_integrity_checks(
            dataframe
        )
    )

    scorecard = (
        calculate_demand_quality_scorecard(
            dataframe
        )
    )

    recommendations = (
        generate_demand_quality_recommendations(
            column_summary,
            timestamp_summary,
            duplicate_summary,
            date_coverage,
        )
    )

    return {
        "Success": True,
        "Prepared_Data": prepared,
        "Column_Summary": column_summary,
        "Timestamp_Summary": timestamp_summary,
        "Duplicate_Summary": duplicate_summary,
        "Date_Coverage": date_coverage,
        "Integrity_Checks": integrity_checks,
        "Scorecard": scorecard,
        "Recommendations": recommendations,
    }


