def render_demand_quality_exports(
    report,
):
    """Export the data-quality report tables."""

    st.subheader("7. Download Quality Reports")

    exports = [
        (
            "Demand Column Summary",
            report["Column_Summary"],
            "demand_quality_column_summary.csv",
        ),
        (
            "Integrity Checks",
            report["Integrity_Checks"],
            "demand_quality_integrity_checks.csv",
        ),
        (
            "Date Coverage",
            report["Date_Coverage"],
            "demand_quality_date_coverage.csv",
        ),
        (
            "Prepared Data",
            report["Prepared_Data"],
            "demand_quality_prepared_data.csv",
        ),
    ]

    for label, dataframe, filename in exports:
        if dataframe is None or dataframe.empty:
            continue

        st.download_button(
            label=f"Download {label}",
            data=dataframe.to_csv(
                index=False
            ).encode("utf-8"),
            file_name=filename,
            mime="text/csv",
            key=f"demand_quality_download_{filename}",
        )

    summary_rows = []

    for section in [
        "Timestamp_Summary",
        "Duplicate_Summary",
        "Scorecard",
    ]:
        values = report.get(
            section,
            {},
        )

        if not isinstance(values, dict):
            continue

        for key, value in values.items():
            if isinstance(value, dict):
                for sub_key, sub_value in value.items():
                    summary_rows.append({
                        "Section": section,
                        "Metric": f"{key}.{sub_key}",
                        "Value": sub_value,
                    })
            elif isinstance(value, (str, int, float, bool)):
                summary_rows.append({
                    "Section": section,
                    "Metric": key,
                    "Value": value,
                })

    if summary_rows:
        summary = pd.DataFrame(
            summary_rows
        )

        st.download_button(
            label="Download Overall Quality Summary",
            data=summary.to_csv(
                index=False
            ).encode("utf-8"),
            file_name="demand_quality_summary.csv",
            mime="text/csv",
            key="demand_quality_summary_download",
        )


def render_demand_quality_center():
    """Main dashboard for demand data quality."""

    st.header(
        "Demand Data Quality & Reliability Intelligence Center"
    )

    st.write(
        "Validate timestamps, demand values, duplicate records "
        "and date coverage before using data for forecasting."
    )

    dataset_path = st.session_state.get(
        "dataset_path",
        str(DEFAULT_DATASET_PATH),
    )

    try:
        dataframe = pd.read_csv(
            dataset_path
        )
    except Exception as exc:
        st.error(
            f"Unable to read the selected dataset: {exc}"
        )
        return

    if dataframe.empty:
        st.error(
            "The selected dataset contains no records."
        )
        return

    report = build_demand_quality_center_report(
        dataframe
    )

    if not report.get("Success"):
        st.error(
            report.get(
                "Reason",
                "The data-quality report could not be generated.",
            )
        )
        return

    render_demand_quality_center_overview(
        report
    )

    render_demand_quality_column_analysis(
        report["Column_Summary"]
    )

    render_demand_quality_integrity_checks(
        report["Integrity_Checks"]
    )

    render_demand_quality_date_coverage(
        report["Date_Coverage"]
    )

    render_demand_quality_scorecard(
        report["Scorecard"]
    )

    render_demand_quality_recommendations(
        report["Recommendations"]
    )

    render_demand_quality_exports(
        report
    )


