# ============================================================
# PART 33 â€” FORECAST MONITORING & PERFORMANCE TRACKING CENTER
# ============================================================

FORECAST_PERFORMANCE_CENTER_VERSION = "1.0.0"

FORECAST_PERFORMANCE_MINIMUM_ROWS = 2
FORECAST_PERFORMANCE_MAXIMUM_DISPLAY_ROWS = 2000

FORECAST_PERFORMANCE_METRICS = [
    "MAE",
    "RMSE",
    "WAPE_Percentage",
]


def prepare_forecast_performance_data(
    dataframe,
    timestamp_column,
    actual_column,
    predicted_column,
):
    """
    Standardize historical actual and predicted observations.

    This function does not train a model or generate predictions.
    """

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    required = [
        timestamp_column,
        actual_column,
        predicted_column,
    ]

    if any(
        column not in dataframe.columns
        for column in required
    ):
        return pd.DataFrame()

    if len(set(required)) != 3:
        return pd.DataFrame()

    result = dataframe[required].copy()

    result = result.rename(
        columns={
            timestamp_column: "Timestamp",
            actual_column: "Actual",
            predicted_column: "Predicted",
        }
    )

    result["Timestamp"] = pd.to_datetime(
        result["Timestamp"],
        errors="coerce",
    )

    result["Actual"] = pd.to_numeric(
        result["Actual"],
        errors="coerce",
    )

    result["Predicted"] = pd.to_numeric(
        result["Predicted"],
        errors="coerce",
    )

    result = result.replace(
        [np.inf, -np.inf],
        np.nan,
    )

    result = result.dropna(
        subset=[
            "Timestamp",
            "Actual",
            "Predicted",
        ]
    )

    result = result.sort_values(
        "Timestamp"
    ).reset_index(
        drop=True
    )

    result["Forecast_Error"] = (
        result["Actual"]
        - result["Predicted"]
    )

    result["Absolute_Error"] = (
        result["Forecast_Error"].abs()
    )

    result["Squared_Error"] = (
        result["Forecast_Error"] ** 2
    )

    result["Absolute_Actual"] = (
        result["Actual"].abs()
    )

    result["Error_Direction"] = np.select(
        [
            result["Forecast_Error"] > 0,
            result["Forecast_Error"] < 0,
        ],
        [
            "Underprediction",
            "Overprediction",
        ],
        default="Exact Prediction",
    )

    return result


def calculate_forecast_performance_metrics(
    dataframe,
):
    """Calculate MAE, RMSE and WAPE for forecast observations."""

    if (
        dataframe is None
        or dataframe.empty
        or not {
            "Actual",
            "Predicted",
        }.issubset(dataframe.columns)
    ):
        return {}

    actual = dataframe["Actual"].to_numpy(
        dtype=float
    )

    predicted = dataframe["Predicted"].to_numpy(
        dtype=float
    )

    errors = actual - predicted

    absolute_error_sum = float(
        np.sum(np.abs(errors))
    )

    absolute_actual_sum = float(
        np.sum(np.abs(actual))
    )

    return {
        "Observation_Count": int(
            len(actual)
        ),
        "MAE": float(
            np.mean(np.abs(errors))
        ),
        "RMSE": float(
            np.sqrt(np.mean(errors ** 2))
        ),
        "WAPE_Percentage": (
            absolute_error_sum
            / absolute_actual_sum
            * 100
            if absolute_actual_sum > 0
            else np.nan
        ),
        "Mean_Residual": float(
            np.mean(errors)
        ),
        "Underprediction_Count": int(
            np.sum(errors > 0)
        ),
        "Overprediction_Count": int(
            np.sum(errors < 0)
        ),
        "Exact_Prediction_Count": int(
            np.sum(errors == 0)
        ),
    }


def aggregate_forecast_performance_by_period(
    dataframe,
    frequency="W",
):
    """Aggregate forecast performance into chronological periods."""

    if (
        dataframe is None
        or dataframe.empty
        or not {
            "Timestamp",
            "Actual",
            "Predicted",
        }.issubset(dataframe.columns)
    ):
        return pd.DataFrame()

    frequency_map = {
        "Daily": "D",
        "Weekly": "W",
        "Monthly": "MS",
        "D": "D",
        "W": "W",
        "MS": "MS",
    }

    selected_frequency = frequency_map.get(
        frequency
    )

    if selected_frequency is None:
        raise ValueError(
            "Unsupported forecast monitoring frequency."
        )

    result = dataframe.copy()

    result = result.sort_values(
        "Timestamp"
    ).set_index(
        "Timestamp"
    )

    grouped = result.resample(
        selected_frequency
    )

    summary = grouped.agg(
        Observation_Count=("Actual", "count"),
        Actual_Total=("Actual", "sum"),
        Predicted_Total=("Predicted", "sum"),
        Mean_Actual=("Actual", "mean"),
        Mean_Predicted=("Predicted", "mean"),
        MAE=("Absolute_Error", "mean"),
        Mean_Residual=("Forecast_Error", "mean"),
    )

    squared_error_mean = grouped[
        "Squared_Error"
    ].mean()

    summary["RMSE"] = np.sqrt(
        squared_error_mean
    )

    absolute_error_sum = grouped[
        "Absolute_Error"
    ].sum()

    absolute_actual_sum = grouped[
        "Absolute_Actual"
    ].sum()

    summary["WAPE_Percentage"] = np.where(
        absolute_actual_sum > 0,
        absolute_error_sum
        / absolute_actual_sum
        * 100,
        np.nan,
    )

    return summary.reset_index()


def classify_forecast_performance_trend(
    period_summary,
    metric="MAE",
):
    """Describe whether the selected error metric is rising or falling."""

    if (
        period_summary is None
        or period_summary.empty
        or metric not in period_summary.columns
    ):
        return {
            "Available": False,
            "Reason": "The selected metric is unavailable.",
        }

    values = pd.to_numeric(
        period_summary[metric],
        errors="coerce",
    ).dropna()

    if len(values) < 4:
        return {
            "Available": False,
            "Reason": (
                "At least four valid periods are required "
                "to describe an error trend."
            ),
        }

    split_index = len(values) // 2

    first_half = values.iloc[
        :split_index
    ]

    second_half = values.iloc[
        split_index:
    ]

    first_mean = float(
        first_half.mean()
    )

    second_mean = float(
        second_half.mean()
    )

    if first_mean == 0:
        percentage_change = (
            0.0
            if second_mean == 0
            else np.nan
        )
    else:
        percentage_change = (
            (second_mean - first_mean)
            / abs(first_mean)
            * 100
        )

    if pd.isna(percentage_change):
        classification = "Inconclusive"
    elif percentage_change <= -10:
        classification = "Improving"
    elif percentage_change >= 10:
        classification = "Worsening"
    else:
        classification = "Relatively Stable"

    return {
        "Available": True,
        "Metric": metric,
        "First_Period_Mean": first_mean,
        "Second_Period_Mean": second_mean,
        "Percentage_Change": percentage_change,
        "Classification": classification,
    }


def identify_forecast_performance_high_error_periods(
    period_summary,
    metric="MAE",
    percentile=90,
):
    """Identify periods above a selected error percentile."""

    if (
        period_summary is None
        or period_summary.empty
        or metric not in period_summary.columns
    ):
        return pd.DataFrame()

    result = period_summary.copy()

    values = pd.to_numeric(
        result[metric],
        errors="coerce",
    )

    valid = values.dropna()

    if valid.empty:
        return pd.DataFrame()

    threshold = float(
        valid.quantile(
            percentile / 100
        )
    )

    result["Error_Threshold"] = threshold

    result["High_Error_Flag"] = (
        values >= threshold
    )

    result["Error_Rank"] = values.rank(
        ascending=False,
        method="min",
    )

    return result.sort_values(
        "Error_Rank"
    ).reset_index(
        drop=True
    )


def build_forecast_performance_monitoring_report(
    prepared_data,
    frequency="Weekly",
):
    """Build a complete historical forecast monitoring report."""

    if prepared_data is None or prepared_data.empty:
        return {
            "Success": False,
            "Reason": "No valid forecast observations are available.",
        }

    metrics = calculate_forecast_performance_metrics(
        prepared_data
    )

    period_summary = (
        aggregate_forecast_performance_by_period(
            prepared_data,
            frequency=frequency,
        )
    )

    if period_summary.empty:
        return {
            "Success": False,
            "Reason": "No forecast monitoring periods were created.",
        }

    mae_trend = classify_forecast_performance_trend(
        period_summary,
        metric="MAE",
    )

    rmse_trend = classify_forecast_performance_trend(
        period_summary,
        metric="RMSE",
    )

    high_error_periods = (
        identify_forecast_performance_high_error_periods(
            period_summary,
            metric="MAE",
            percentile=90,
        )
    )

    return {
        "Success": True,
        "Overall_Metrics": metrics,
        "Period_Summary": period_summary,
        "MAE_Trend": mae_trend,
        "RMSE_Trend": rmse_trend,
        "High_Error_Periods": high_error_periods,
        "Observation_Details": prepared_data.copy(),
    }


def generate_forecast_performance_recommendations(
    report,
):
    """Generate recommendations from measured forecast errors."""

    recommendations = []

    if (
        not report
        or not report.get("Success")
    ):
        return [
            "Valid forecast observations are required before generating recommendations."
        ]

    mae_trend = report.get(
        "MAE_Trend",
        {},
    )

    if mae_trend.get("Available"):
        classification = mae_trend.get(
            "Classification"
        )

        if classification == "Worsening":
            recommendations.append(
                "MAE is higher in the later portion of the evaluated "
                "periods. Investigate data changes, seasonal effects "
                "and model drift before deploying the forecast."
            )

        elif classification == "Improving":
            recommendations.append(
                "MAE is lower in the later portion of the evaluated "
                "periods. Continue monitoring to check whether the "
                "improvement persists."
            )

        elif classification == "Relatively Stable":
            recommendations.append(
                "MAE is relatively stable under the configured "
                "half-period comparison."
            )

        else:
            recommendations.append(
                "The MAE trend is inconclusive. Review more periods "
                "or use a formal trend analysis."
            )

    high_periods = report.get(
        "High_Error_Periods",
        pd.DataFrame(),
    )

    if not high_periods.empty:
        recommendations.append(
            "Review periods flagged for high MAE to identify "
            "specific dates and potential sources of forecast error."
        )

    recommendations.append(
        "Trend classifications use simple descriptive thresholds. "
        "They are not statistical significance tests."
    )

    recommendations.append(
        "This report monitors historical forecast performance only. "
        "It does not continuously run or retrain a forecasting model."
    )

    return recommendations


