def render_forecast_performance_column_mapping(
    dataframe,
):
    """Map timestamp, actual and predicted fields."""

    if dataframe is None or dataframe.empty:
        return None

    st.subheader("2. Map Forecast Columns")

    columns = dataframe.columns.tolist()

    def choose(
        label,
        preferred,
        key,
    ):
        options = ["Select a column"] + columns

        index = (
            columns.index(preferred) + 1
            if preferred in columns
            else 0
        )

        value = st.selectbox(
            label,
            options=options,
            index=index,
            key=key,
        )

        return (
            None
            if value == "Select a column"
            else value
        )

    timestamp_column = choose(
        "Timestamp",
        "Timestamp",
        "forecast_performance_timestamp",
    )

    actual_column = choose(
        "Actual values",
        "Actual",
        "forecast_performance_actual",
    )

    predicted_column = choose(
        "Predicted values",
        "Predicted",
        "forecast_performance_predicted",
    )

    if any(
        column is None
        for column in [
            timestamp_column,
            actual_column,
            predicted_column,
        ]
    ):
        st.info(
            "Select all three columns to continue."
        )
        return None

    if len({
        timestamp_column,
        actual_column,
        predicted_column,
    }) != 3:
        st.error(
            "Timestamp, actual and predicted must use different columns."
        )
        return None

    return {
        "timestamp_column": timestamp_column,
        "actual_column": actual_column,
        "predicted_column": predicted_column,
    }


