def render_forecast_performance_center():
    """Main interface for historical forecast monitoring."""

    st.header(
        "Forecast Monitoring & Performance Tracking Center"
    )

    st.write(
        "Track historical forecast accuracy, error direction "
        "and performance changes across time."
    )

    st.warning(
        "This center evaluates existing forecast results. It does "
        "not create predictions or automatically monitor a running model."
    )

    uploaded = render_forecast_performance_upload()

    if uploaded is None:
        return

    mapping = render_forecast_performance_column_mapping(
        uploaded
    )

    if mapping is None:
        return

    prepared = prepare_forecast_performance_data(
        uploaded,
        timestamp_column=mapping["timestamp_column"],
        actual_column=mapping["actual_column"],
        predicted_column=mapping["predicted_column"],
    )

    if prepared.empty:
        st.error(
            "No valid observations remain after parsing the selected columns."
        )
        return

    if len(prepared) < FORECAST_PERFORMANCE_MINIMUM_ROWS:
        st.warning(
            f"At least {FORECAST_PERFORMANCE_MINIMUM_ROWS} valid "
            "observations are recommended."
        )
        return

    frequency = render_forecast_performance_controls()

    report = build_forecast_performance_monitoring_report(
        prepared,
        frequency=frequency,
    )

    if not report.get("Success"):
        st.error(
            report.get(
                "Reason",
                "The monitoring report could not be generated.",
            )
        )
        return

    render_forecast_performance_overview(
        report
    )

    render_forecast_performance_error_chart(
        report["Period_Summary"]
    )

    render_forecast_performance_trend_summary(
        report["MAE_Trend"],
        "MAE Trend",
    )

    render_forecast_performance_trend_summary(
        report["RMSE_Trend"],
        "RMSE Trend",
    )

    render_forecast_performance_high_error_periods(
        report["High_Error_Periods"]
    )

    render_forecast_performance_direction(
        report["Observation_Details"]
    )

    recommendations = (
        generate_forecast_performance_recommendations(
            report
        )
    )

    render_forecast_performance_recommendations(
        recommendations
    )

    render_forecast_performance_exports(
        report
    )


