# ============================================================
# PART 34 â€” DEMAND FORECAST COMPARISON & HORIZON PLANNING
# ============================================================

DEMAND_HORIZON_VERSION = "1.0.0"

DEMAND_HORIZON_OPTIONS = {
    "7 Days": 7,
    "14 Days": 14,
    "30 Days": 30,
    "60 Days": 60,
    "90 Days": 90,
}

DEMAND_HORIZON_SUPPORTED_METRICS = [
    "Sales Count",
    "Redemption Count",
]

DEMAND_HORIZON_MINIMUM_PERIODS = 7
DEMAND_HORIZON_MAXIMUM_DISPLAY_ROWS = 2000


def prepare_demand_horizon_data(dataframe):
    """Prepare historical ticket records for horizon analysis."""

    required_columns = [
        "Timestamp",
        "Sales Count",
        "Redemption Count",
    ]

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    if not set(required_columns).issubset(
        dataframe.columns
    ):
        return pd.DataFrame()

    result = dataframe[
        required_columns
    ].copy()

    result["Timestamp"] = pd.to_datetime(
        result["Timestamp"],
        errors="coerce",
    )

    for column in DEMAND_HORIZON_SUPPORTED_METRICS:
        result[column] = pd.to_numeric(
            result[column],
            errors="coerce",
        )

    result = result.replace(
        [np.inf, -np.inf],
        np.nan,
    )

    result = result.dropna(
        subset=["Timestamp"]
    )

    result = result.sort_values(
        "Timestamp"
    ).reset_index(
        drop=True
    )

    return result


def aggregate_demand_horizon_history(
    dataframe,
    metric,
    frequency="D",
):
    """Aggregate historical ticket counts by calendar period."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    if metric not in DEMAND_HORIZON_SUPPORTED_METRICS:
        raise ValueError(
            "Unsupported demand metric."
        )

    if frequency not in ["D", "W", "MS"]:
        raise ValueError(
            "Frequency must be D, W or MS."
        )

    valid = dataframe[
        ["Timestamp", metric]
    ].dropna().copy()

    if valid.empty:
        return pd.DataFrame()

    valid = valid.set_index(
        "Timestamp"
    ).sort_index()

    aggregated = valid[metric].resample(
        frequency
    ).agg(
        ["sum", "count", "mean"]
    )

    aggregated = aggregated.rename(
        columns={
            "sum": "Observed_Total",
            "count": "Record_Count",
            "mean": "Mean_Record_Value",
        }
    )

    aggregated.index.name = "Timestamp"

    return aggregated.reset_index()


def calculate_demand_horizon_statistics(
    aggregated_data,
):
    """Calculate descriptive statistics for historical periods."""

    if (
        aggregated_data is None
        or aggregated_data.empty
        or "Observed_Total" not in aggregated_data.columns
    ):
        return {}

    values = pd.to_numeric(
        aggregated_data["Observed_Total"],
        errors="coerce",
    ).dropna()

    if values.empty:
        return {}

    mean_value = float(
        values.mean()
    )

    median_value = float(
        values.median()
    )

    standard_deviation = float(
        values.std(ddof=1)
    ) if len(values) > 1 else 0.0

    coefficient_of_variation = (
        standard_deviation / abs(mean_value)
        if mean_value != 0
        else np.nan
    )

    return {
        "Period_Count": int(len(values)),
        "Historical_Total": float(values.sum()),
        "Mean_Period_Demand": mean_value,
        "Median_Period_Demand": median_value,
        "Minimum_Period_Demand": float(values.min()),
        "Maximum_Period_Demand": float(values.max()),
        "Standard_Deviation": standard_deviation,
        "Coefficient_of_Variation": coefficient_of_variation,
    }


def calculate_demand_horizon_baseline(
    aggregated_data,
    horizon_days,
    baseline_method="Mean",
    recent_periods=28,
):
    """
    Build a simple reference scenario using historical period totals.

    This is not a trained forecasting model.
    """

    if (
        aggregated_data is None
        or aggregated_data.empty
        or "Observed_Total" not in aggregated_data.columns
    ):
        return {}

    if horizon_days <= 0:
        raise ValueError(
            "Horizon must be greater than zero."
        )

    values = pd.to_numeric(
        aggregated_data["Observed_Total"],
        errors="coerce",
    ).dropna()

    if values.empty:
        return {}

    recent_values = values.tail(
        max(1, int(recent_periods))
    )

    if baseline_method == "Median":
        daily_reference = float(
            recent_values.median()
        )

    elif baseline_method == "Mean":
        daily_reference = float(
            recent_values.mean()
        )

    elif baseline_method == "Trimmed Mean":
        lower = recent_values.quantile(0.10)
        upper = recent_values.quantile(0.90)

        trimmed = recent_values[
            recent_values.between(
                lower,
                upper,
            )
        ]

        if trimmed.empty:
            daily_reference = float(
                recent_values.mean()
            )
        else:
            daily_reference = float(
                trimmed.mean()
            )

    else:
        raise ValueError(
            "Unsupported baseline method."
        )

    reference_total = (
        daily_reference * horizon_days
    )

    return {
        "Horizon_Days": int(horizon_days),
        "Baseline_Method": baseline_method,
        "Reference_Daily_Demand": daily_reference,
        "Reference_Horizon_Total": reference_total,
        "Historical_Reference_Periods": int(
            len(recent_values)
        ),
        "Interpretation": (
            "A simple historical reference scenario, not a verified forecast."
        ),
    }


def build_demand_horizon_comparison(
    aggregated_data,
    baseline_method="Mean",
    recent_periods=28,
):
    """Compare historical reference scenarios across multiple horizons."""

    if aggregated_data is None or aggregated_data.empty:
        return pd.DataFrame()

    rows = []

    for label, horizon_days in DEMAND_HORIZON_OPTIONS.items():
        baseline = calculate_demand_horizon_baseline(
            aggregated_data=aggregated_data,
            horizon_days=horizon_days,
            baseline_method=baseline_method,
            recent_periods=recent_periods,
        )

        if not baseline:
            continue

        rows.append({
            "Horizon": label,
            "Horizon_Days": horizon_days,
            "Baseline_Method": baseline_method,
            "Reference_Daily_Demand": baseline[
                "Reference_Daily_Demand"
            ],
            "Reference_Horizon_Total": baseline[
                "Reference_Horizon_Total"
            ],
            "Historical_Reference_Periods": baseline[
                "Historical_Reference_Periods"
            ],
        })

    return pd.DataFrame(rows)


def calculate_demand_horizon_sensitivity(
    comparison,
    growth_rates=None,
):
    """Create alternative demand scenarios using explicit growth assumptions."""

    if (
        comparison is None
        or comparison.empty
        or "Reference_Horizon_Total" not in comparison.columns
    ):
        return pd.DataFrame()

    if growth_rates is None:
        growth_rates = [
            -20,
            -10,
            0,
            10,
            20,
        ]

    rows = []

    for _, row in comparison.iterrows():
        baseline_total = float(
            row["Reference_Horizon_Total"]
        )

        for growth_rate in growth_rates:
            if growth_rate <= -100:
                continue

            scenario_total = (
                baseline_total
                * (1 + growth_rate / 100)
            )

            rows.append({
                "Horizon": row["Horizon"],
                "Horizon_Days": int(
                    row["Horizon_Days"]
                ),
                "Growth_Assumption_Percentage": growth_rate,
                "Reference_Total": baseline_total,
                "Scenario_Total": scenario_total,
                "Difference_From_Reference": (
                    scenario_total - baseline_total
                ),
            })

    return pd.DataFrame(rows)


def identify_demand_horizon_extremes(
    aggregated_data,
    top_n=10,
):
    """Identify highest and lowest observed historical periods."""

    if (
        aggregated_data is None
        or aggregated_data.empty
        or "Observed_Total" not in aggregated_data.columns
    ):
        return {
            "Highest": pd.DataFrame(),
            "Lowest": pd.DataFrame(),
        }

    valid = aggregated_data.dropna(
        subset=["Observed_Total"]
    ).copy()

    if valid.empty:
        return {
            "Highest": pd.DataFrame(),
            "Lowest": pd.DataFrame(),
        }

    top_n = max(
        1,
        min(int(top_n), len(valid)),
    )

    highest = valid.nlargest(
        top_n,
        "Observed_Total",
    )

    lowest = valid.nsmallest(
        top_n,
        "Observed_Total",
    )

    return {
        "Highest": highest.reset_index(drop=True),
        "Lowest": lowest.reset_index(drop=True),
    }


def generate_demand_horizon_insights(
    statistics,
    comparison,
    sensitivity,
):
    """Generate descriptive insights for horizon planning."""

    insights = []

    if statistics:
        insights.append(
            f"Analysis contains {statistics['Period_Count']:,} "
            "historical periods."
        )

        insights.append(
            "The historical mean period total is "
            f"{statistics['Mean_Period_Demand']:,.2f}."
        )

        insights.append(
            "The historical maximum period total is "
            f"{statistics['Maximum_Period_Demand']:,.2f}."
        )

    if (
        comparison is not None
        and not comparison.empty
    ):
        first = comparison.iloc[0]
        last = comparison.iloc[-1]

        insights.append(
            f"The {first['Horizon']} reference scenario is "
            f"{first['Reference_Horizon_Total']:,.2f}; "
            f"the {last['Horizon']} scenario is "
            f"{last['Reference_Horizon_Total']:,.2f}."
        )

        insights.append(
            "Longer horizons produce larger reference totals when "
            "the same average daily baseline is multiplied across days."
        )

    if (
        sensitivity is not None
        and not sensitivity.empty
    ):
        insights.append(
            "Growth scenarios are assumption-based sensitivity "
            "calculations, not predictions of actual future demand."
        )

    insights.append(
        "Sales Count and Redemption Count are ticket activity measures. "
        "They do not independently establish passenger boarding, "
        "vessel occupancy or available ferry capacity."
    )

    return insights


