def render_demand_horizon_planning_center():
    """Main UI for demand horizon planning."""

    st.header(
        "Demand Forecast Comparison & Horizon Planning Center"
    )

    st.write(
        "Compare historical reference scenarios over different "
        "planning horizons and explore alternative growth assumptions."
    )

    st.warning(
        "This module creates descriptive scenarios from historical data. "
        "It does not train or validate a forecasting model."
    )

    dataset_path = st.session_state.get(
        "dataset_path",
        str(DEFAULT_DATASET_PATH),
    )

    try:
        dataframe = load_ticket_dataframe(
            dataset_path
        )
    except Exception as exc:
        st.error(
            f"Unable to load the dataset: {exc}"
        )
        return

    if dataframe is None or dataframe.empty:
        st.error(
            "No historical ticket records are available."
        )
        return

    prepared = prepare_demand_horizon_data(
        dataframe
    )

    if prepared.empty:
        st.error(
            "Required ticket activity columns are missing or invalid."
        )
        return

    controls = render_demand_horizon_controls()

    aggregated = aggregate_demand_horizon_history(
        prepared,
        metric=controls["metric"],
        frequency=controls["frequency"],
    )

    if aggregated.empty:
        st.warning(
            "No valid historical periods were found."
        )
        return

    statistics = calculate_demand_horizon_statistics(
        aggregated
    )

    comparison = build_demand_horizon_comparison(
        aggregated_data=aggregated,
        baseline_method=controls["baseline_method"],
        recent_periods=controls["recent_periods"],
    )

    sensitivity = calculate_demand_horizon_sensitivity(
        comparison
    )

    extremes = identify_demand_horizon_extremes(
        aggregated
    )

    insights = generate_demand_horizon_insights(
        statistics,
        comparison,
        sensitivity,
    )

    render_demand_horizon_overview(
        statistics
    )

    render_demand_horizon_comparison(
        comparison
    )

    render_demand_horizon_sensitivity(
        sensitivity
    )

    render_demand_horizon_extremes(
        extremes
    )

    render_demand_horizon_insights(
        insights
    )

    render_demand_horizon_exports(
        comparison,
        sensitivity,
        aggregated,
    )


