# PART 35 â€” DEMAND PATTERN SEGMENTATION & REGIME ANALYSIS
# ============================================================

DEMAND_REGIME_VERSION = "1.0.0"

DEMAND_REGIME_METRICS = [
    "Sales Count",
    "Redemption Count",
]

DEMAND_REGIME_LEVELS = [
    "Low Demand",
    "Normal Demand",
    "High Demand",
]

DEMAND_REGIME_MINIMUM_PERIODS = 7
DEMAND_REGIME_DEFAULT_ROLLING_WINDOW = 7
DEMAND_REGIME_MAXIMUM_DISPLAY_ROWS = 2000


def prepare_demand_regime_data(dataframe):
    """Prepare timestamped ticket records for regime analysis."""

    required_columns = [
        "Timestamp",
        "Sales Count",
        "Redemption Count",
    ]

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    if not set(required_columns).issubset(
        dataframe.columns
    ):
        return pd.DataFrame()

    result = dataframe[
        required_columns
    ].copy()

    result["Timestamp"] = pd.to_datetime(
        result["Timestamp"],
        errors="coerce",
    )

    for column in DEMAND_REGIME_METRICS:
        result[column] = pd.to_numeric(
            result[column],
            errors="coerce",
        )

    result = result.replace(
        [np.inf, -np.inf],
        np.nan,
    )

    result = result.dropna(
        subset=["Timestamp"]
    )

    return result.sort_values(
        "Timestamp"
    ).reset_index(
        drop=True
    )


def aggregate_demand_regime_periods(
    dataframe,
    metric="Sales Count",
    frequency="D",
):
    """Aggregate observed ticket activity into calendar periods."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    if metric not in DEMAND_REGIME_METRICS:
        raise ValueError(
            "Unsupported demand metric."
        )

    if frequency not in ["D", "W", "MS"]:
        raise ValueError(
            "Frequency must be D, W or MS."
        )

    selected = dataframe[
        ["Timestamp", metric]
    ].dropna().copy()

    if selected.empty:
        return pd.DataFrame()

    selected = selected.set_index(
        "Timestamp"
    ).sort_index()

    grouped = selected[metric].resample(
        frequency
    )

    result = grouped.agg(
        Observed_Total="sum",
        Record_Count="count",
        Mean_Record_Value="mean",
        Median_Record_Value="median",
        Standard_Deviation="std",
    ).reset_index()

    result["Standard_Deviation"] = (
        result["Standard_Deviation"].fillna(0)
    )

    result["Observed_Total"] = pd.to_numeric(
        result["Observed_Total"],
        errors="coerce",
    )

    return result


def calculate_demand_regime_thresholds(
    period_data,
    lower_percentile=25,
    upper_percentile=75,
):
    """Calculate historical percentile thresholds."""

    if (
        period_data is None
        or period_data.empty
        or "Observed_Total" not in period_data.columns
    ):
        return {}

    values = pd.to_numeric(
        period_data["Observed_Total"],
        errors="coerce",
    ).dropna()

    if values.empty:
        return {}

    if not (
        0 <= lower_percentile
        < upper_percentile
        <= 100
    ):
        raise ValueError(
            "Percentiles must satisfy 0 <= lower < upper <= 100."
        )

    return {
        "Lower_Threshold": float(
            values.quantile(
                lower_percentile / 100
            )
        ),
        "Upper_Threshold": float(
            values.quantile(
                upper_percentile / 100
            )
        ),
        "Lower_Percentile": lower_percentile,
        "Upper_Percentile": upper_percentile,
        "Reference_Period_Count": int(
            len(values)
        ),
    }


def classify_demand_regime_periods(
    period_data,
    thresholds,
):
    """Classify each period using historical percentile cutoffs."""

    if period_data is None or period_data.empty:
        return pd.DataFrame()

    if not thresholds:
        return pd.DataFrame()

    result = period_data.copy()

    lower_threshold = thresholds[
        "Lower_Threshold"
    ]

    upper_threshold = thresholds[
        "Upper_Threshold"
    ]

    values = pd.to_numeric(
        result["Observed_Total"],
        errors="coerce",
    )

    conditions = [
        values <= lower_threshold,
        values >= upper_threshold,
    ]

    labels = [
        "Low Demand",
        "High Demand",
    ]

    result["Demand_Regime"] = np.select(
        conditions,
        labels,
        default="Normal Demand",
    )

    result["Demand_Regime"] = (
        result["Demand_Regime"].where(
            values.notna(),
            "Unclassified",
        )
    )

    result["Lower_Threshold"] = lower_threshold
    result["Upper_Threshold"] = upper_threshold

    return result


def calculate_demand_regime_summary(
    classified_data,
):
    """Summarize count, totals and averages by demand regime."""

    if (
        classified_data is None
        or classified_data.empty
        or "Demand_Regime" not in classified_data.columns
    ):
        return pd.DataFrame()

    result = classified_data.groupby(
        "Demand_Regime",
        observed=True,
    ).agg(
        Period_Count=("Observed_Total", "count"),
        Total_Activity=("Observed_Total", "sum"),
        Mean_Period_Activity=("Observed_Total", "mean"),
        Median_Period_Activity=("Observed_Total", "median"),
        Minimum_Period_Activity=("Observed_Total", "min"),
        Maximum_Period_Activity=("Observed_Total", "max"),
    ).reset_index()

    total_periods = result[
        "Period_Count"
    ].sum()

    result["Period_Share_Percentage"] = (
        result["Period_Count"]
        / total_periods
        * 100
        if total_periods > 0
        else np.nan
    )

    return result.sort_values(
        "Mean_Period_Activity",
        ascending=False,
    ).reset_index(
        drop=True
    )


def calculate_demand_regime_transition_table(
    classified_data,
):
    """Count observed transitions between consecutive demand regimes."""

    if (
        classified_data is None
        or classified_data.empty
        or "Demand_Regime" not in classified_data.columns
    ):
        return pd.DataFrame()

    ordered = classified_data.sort_values(
        "Timestamp"
    ).copy()

    ordered["Previous_Regime"] = (
        ordered["Demand_Regime"].shift(1)
    )

    ordered = ordered.dropna(
        subset=[
            "Previous_Regime",
            "Demand_Regime",
        ]
    )

    if ordered.empty:
        return pd.DataFrame()

    transitions = ordered.groupby(
        [
            "Previous_Regime",
            "Demand_Regime",
        ],
        observed=True,
    ).size().reset_index(
        name="Transition_Count"
    )

    return transitions.sort_values(
        "Transition_Count",
        ascending=False,
    ).reset_index(
        drop=True
    )


def calculate_demand_regime_rolling_profile(
    classified_data,
    window=7,
):
    """Calculate a rolling average of historical period activity."""

    if (
        classified_data is None
        or classified_data.empty
        or "Observed_Total" not in classified_data.columns
    ):
        return pd.DataFrame()

    if window < 1:
        raise ValueError(
            "Rolling window must be at least one period."
        )

    result = classified_data.sort_values(
        "Timestamp"
    ).copy()

    result["Rolling_Mean"] = (
        result["Observed_Total"]
        .rolling(
            window=window,
            min_periods=1,
        )
        .mean()
    )

    result["Rolling_Standard_Deviation"] = (
        result["Observed_Total"]
        .rolling(
            window=window,
            min_periods=2,
        )
        .std()
    )

    result["Rolling_Standard_Deviation"] = (
        result["Rolling_Standard_Deviation"].fillna(0)
    )

    result["Rolling_Upper_Band"] = (
        result["Rolling_Mean"]
        + 2 * result["Rolling_Standard_Deviation"]
    )

    result["Rolling_Lower_Band"] = (
        result["Rolling_Mean"]
        - 2 * result["Rolling_Standard_Deviation"]
    )

    return result


def calculate_demand_regime_weekday_profile(
    classified_data,
):
    """Compare historical activity across weekdays."""

    if (
        classified_data is None
        or classified_data.empty
        or "Timestamp" not in classified_data.columns
    ):
        return pd.DataFrame()

    result = classified_data.copy()

    result["Weekday_Number"] = (
        result["Timestamp"].dt.dayofweek
    )

    result["Weekday"] = (
        result["Timestamp"].dt.day_name()
    )

    summary = result.groupby(
        [
            "Weekday_Number",
            "Weekday",
        ],
        observed=True,
    ).agg(
        Mean_Activity=("Observed_Total", "mean"),
        Median_Activity=("Observed_Total", "median"),
        Period_Count=("Observed_Total", "count"),
        Standard_Deviation=("Observed_Total", "std"),
    ).reset_index()

    summary["Standard_Deviation"] = (
        summary["Standard_Deviation"].fillna(0)
    )

    return summary.sort_values(
        "Weekday_Number"
    ).reset_index(
        drop=True
    )


def calculate_demand_regime_month_profile(
    classified_data,
):
    """Compare historical activity by calendar month."""

    if (
        classified_data is None
        or classified_data.empty
        or "Timestamp" not in classified_data.columns
    ):
        return pd.DataFrame()

    result = classified_data.copy()

    result["Month_Number"] = (
        result["Timestamp"].dt.month
    )

    result["Month"] = (
        result["Timestamp"].dt.month_name()
    )

    summary = result.groupby(
        [
            "Month_Number",
            "Month",
        ],
        observed=True,
    ).agg(
        Mean_Activity=("Observed_Total", "mean"),
        Median_Activity=("Observed_Total", "median"),
        Period_Count=("Observed_Total", "count"),
    ).reset_index()

    return summary.sort_values(
        "Month_Number"
    ).reset_index(
        drop=True
    )


def calculate_demand_regime_volatility(
    classified_data,
):
    """Measure variation across observed demand periods."""

    if (
        classified_data is None
        or classified_data.empty
        or "Observed_Total" not in classified_data.columns
    ):
        return {}

    values = pd.to_numeric(
        classified_data["Observed_Total"],
        errors="coerce",
    ).dropna()

    if values.empty:
        return {}

    mean_value = float(
        values.mean()
    )

    std_value = (
        float(values.std(ddof=1))
        if len(values) > 1
        else 0.0
    )

    coefficient = (
        std_value / abs(mean_value)
        if mean_value != 0
        else np.nan
    )

    if pd.isna(coefficient):
        label = "Undefined"
    elif coefficient < 0.25:
        label = "Lower Relative Variation"
    elif coefficient < 0.75:
        label = "Moderate Relative Variation"
    else:
        label = "Higher Relative Variation"

    return {
        "Mean_Activity": mean_value,
        "Standard_Deviation": std_value,
        "Coefficient_of_Variation": coefficient,
        "Volatility_Classification": label,
        "Period_Count": int(len(values)),
    }


def generate_demand_regime_insights(
    thresholds,
    regime_summary,
    volatility,
):
    """Generate concise descriptive demand insights."""

    insights = []

    if thresholds:
        insights.append(
            "The low-demand threshold is "
            f"{thresholds['Lower_Threshold']:,.2f}, based on the "
            f"{thresholds['Lower_Percentile']}th percentile."
        )

        insights.append(
            "The high-demand threshold is "
            f"{thresholds['Upper_Threshold']:,.2f}, based on the "
            f"{thresholds['Upper_Percentile']}th percentile."
        )

    if (
        regime_summary is not None
        and not regime_summary.empty
    ):
        highest = regime_summary.iloc[0]

        insights.append(
            f"The segment with the highest average period activity "
            f"is {highest['Demand_Regime']}."
        )

    if volatility:
        insights.append(
            "Overall historical variation is classified as "
            f"{volatility['Volatility_Classification']}."
        )

    insights.append(
        "Regime labels are relative to the selected historical sample. "
        "They are not operational capacity or safety classifications."
    )

    insights.append(
        "The transition table describes consecutive observed calendar "
        "periods; it does not identify the cause of demand changes."
    )

    return insights


