def render_demand_regime_analysis_center():
    """Main interface for historical demand segmentation."""

    st.header(
        "Demand Pattern Segmentation & Regime Analysis Center"
    )

    st.write(
        "Classify historical ticket activity into relative demand "
        "regimes and explore changes over time."
    )

    st.warning(
        "Regime thresholds are calculated from the selected historical "
        "sample. They do not represent verified ferry capacity or "
        "passenger occupancy."
    )

    dataset_path = st.session_state.get(
        "dataset_path",
        str(DEFAULT_DATASET_PATH),
    )

    try:
        dataframe = load_ticket_dataframe(
            dataset_path
        )
    except Exception as exc:
        st.error(
            f"Unable to load the dataset: {exc}"
        )
        return

    if dataframe is None or dataframe.empty:
        st.error(
            "No historical ticket records are available."
        )
        return

    prepared = prepare_demand_regime_data(
        dataframe
    )

    if prepared.empty:
        st.error(
            "The required ticket activity fields are unavailable."
        )
        return

    controls = render_demand_regime_controls()

    if (
        controls["lower_percentile"]
        >= controls["upper_percentile"]
    ):
        st.error(
            "The low-demand percentile must be lower than the high-demand percentile."
        )
        return

    periods = aggregate_demand_regime_periods(
        prepared,
        metric=controls["metric"],
        frequency=controls["frequency"],
    )

    if len(periods) < DEMAND_REGIME_MINIMUM_PERIODS:
        st.warning(
            "More historical periods are recommended for stable "
            "demand segmentation."
        )
        return

    thresholds = calculate_demand_regime_thresholds(
        periods,
        lower_percentile=controls["lower_percentile"],
        upper_percentile=controls["upper_percentile"],
    )

    classified = classify_demand_regime_periods(
        periods,
        thresholds,
    )

    regime_summary = calculate_demand_regime_summary(
        classified
    )

    transition_data = calculate_demand_regime_transition_table(
        classified
    )

    rolling_data = calculate_demand_regime_rolling_profile(
        classified,
        window=controls["rolling_window"],
    )

    weekday_profile = calculate_demand_regime_weekday_profile(
        classified
    )

    month_profile = calculate_demand_regime_month_profile(
        classified
    )

    volatility = calculate_demand_regime_volatility(
        classified
    )

    insights = generate_demand_regime_insights(
        thresholds,
        regime_summary,
        volatility,
    )

    render_demand_regime_overview(
        classified,
        thresholds,
        volatility,
    )

    render_demand_regime_timeline(
        rolling_data
    )

    render_demand_regime_distribution(
        regime_summary
    )

    render_demand_regime_transitions(
        transition_data
    )

    render_demand_regime_calendar_profiles(
        weekday_profile,
        month_profile,
    )

    render_demand_regime_insight_panel(
        insights
    )

    render_demand_regime_exports(
        classified,
        regime_summary,
        transition_data,
        rolling_data,
    )


