# ============================================================
# PART 36 â€” DEMAND ANOMALY DETECTION & INVESTIGATION CENTER
# ============================================================

DEMAND_ANOMALY_CENTER_VERSION = "1.0.0"

DEMAND_ANOMALY_CENTER_METRICS = [
    "Sales Count",
    "Redemption Count",
]

DEMAND_ANOMALY_CENTER_METHODS = [
    "IQR",
    "Rolling Deviation",
    "Combined",
]

DEMAND_ANOMALY_CENTER_MAX_DISPLAY_ROWS = 2000
DEMAND_ANOMALY_CENTER_DEFAULT_WINDOW = 7
DEMAND_ANOMALY_CENTER_MINIMUM_PERIODS = 10


def prepare_demand_anomaly_center_data(dataframe):
    """Prepare ticket activity records for anomaly detection."""

    required_columns = [
        "Timestamp",
        "Sales Count",
        "Redemption Count",
    ]

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    if not set(required_columns).issubset(
        dataframe.columns
    ):
        return pd.DataFrame()

    result = dataframe[
        required_columns
    ].copy()

    result["Timestamp"] = pd.to_datetime(
        result["Timestamp"],
        errors="coerce",
    )

    for column in DEMAND_ANOMALY_CENTER_METRICS:
        result[column] = pd.to_numeric(
            result[column],
            errors="coerce",
        )

    result = result.replace(
        [np.inf, -np.inf],
        np.nan,
    )

    result = result.dropna(
        subset=["Timestamp"]
    )

    return result.sort_values(
        "Timestamp"
    ).reset_index(
        drop=True
    )


def aggregate_demand_anomaly_center_data(
    dataframe,
    metric="Sales Count",
    frequency="D",
):
    """Aggregate ticket activity before investigating anomalies."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    if metric not in DEMAND_ANOMALY_CENTER_METRICS:
        raise ValueError(
            "Unsupported demand metric."
        )

    if frequency not in ["D", "W", "MS"]:
        raise ValueError(
            "Frequency must be D, W or MS."
        )

    selected = dataframe[
        ["Timestamp", metric]
    ].dropna().copy()

    if selected.empty:
        return pd.DataFrame()

    selected = selected.set_index(
        "Timestamp"
    ).sort_index()

    grouped = selected[metric].resample(
        frequency
    )

    result = grouped.agg(
        Observed_Total="sum",
        Record_Count="count",
        Mean_Record_Value="mean",
    ).reset_index()

    result["Observed_Total"] = pd.to_numeric(
        result["Observed_Total"],
        errors="coerce",
    )

    return result


def calculate_demand_anomaly_iqr_bounds(
    values,
    multiplier=1.5,
):
    """Calculate lower and upper IQR anomaly thresholds."""

    numeric = pd.to_numeric(
        pd.Series(values),
        errors="coerce",
    ).replace(
        [np.inf, -np.inf],
        np.nan,
    ).dropna()

    if numeric.empty:
        return {}

    q1 = float(
        numeric.quantile(0.25)
    )

    q3 = float(
        numeric.quantile(0.75)
    )

    iqr = q3 - q1

    lower_bound = q1 - multiplier * iqr
    upper_bound = q3 + multiplier * iqr

    return {
        "Q1": q1,
        "Q3": q3,
        "IQR": float(iqr),
        "Lower_Bound": float(lower_bound),
        "Upper_Bound": float(upper_bound),
        "Multiplier": float(multiplier),
    }


def detect_demand_anomaly_iqr(
    period_data,
    multiplier=1.5,
):
    """Flag observations outside the IQR bounds."""

    if (
        period_data is None
        or period_data.empty
        or "Observed_Total" not in period_data.columns
    ):
        return pd.DataFrame()

    result = period_data.copy()

    bounds = calculate_demand_anomaly_iqr_bounds(
        result["Observed_Total"],
        multiplier=multiplier,
    )

    if not bounds:
        return pd.DataFrame()

    values = pd.to_numeric(
        result["Observed_Total"],
        errors="coerce",
    )

    result["IQR_Lower_Bound"] = bounds[
        "Lower_Bound"
    ]

    result["IQR_Upper_Bound"] = bounds[
        "Upper_Bound"
    ]

    result["IQR_Anomaly"] = (
        (values < bounds["Lower_Bound"])
        | (values > bounds["Upper_Bound"])
    )

    result["IQR_Anomaly_Type"] = np.select(
        [
            values < bounds["Lower_Bound"],
            values > bounds["Upper_Bound"],
        ],
        [
            "Unusually Low",
            "Unusually High",
        ],
        default="Within IQR Bounds",
    )

    return result


def detect_demand_anomaly_rolling(
    period_data,
    window=7,
    deviation_threshold=3.0,
):
    """Detect large deviations from a trailing historical window."""

    if (
        period_data is None
        or period_data.empty
        or "Observed_Total" not in period_data.columns
    ):
        return pd.DataFrame()

    if window < 2:
        raise ValueError(
            "Rolling window must be at least two periods."
        )

    if deviation_threshold <= 0:
        raise ValueError(
            "Deviation threshold must be positive."
        )

    result = period_data.sort_values(
        "Timestamp"
    ).copy()

    values = pd.to_numeric(
        result["Observed_Total"],
        errors="coerce",
    )

    # Shift first so the current period is not included
    # in the reference window used to judge that period.
    history = values.shift(1)

    result["Rolling_Reference_Mean"] = (
        history.rolling(
            window=window,
            min_periods=max(2, window // 2),
        ).mean()
    )

    result["Rolling_Reference_Std"] = (
        history.rolling(
            window=window,
            min_periods=max(2, window // 2),
        ).std()
    )

    result["Rolling_Reference_Std"] = (
        result["Rolling_Reference_Std"].replace(
            0,
            np.nan,
        )
    )

    result["Rolling_Z_Score"] = (
        (
            values
            - result["Rolling_Reference_Mean"]
        )
        / result["Rolling_Reference_Std"]
    )

    result["Rolling_Anomaly"] = (
        result["Rolling_Z_Score"].abs()
        >= deviation_threshold
    ).fillna(False)

    result["Rolling_Anomaly_Type"] = np.select(
        [
            result["Rolling_Z_Score"]
            >= deviation_threshold,

            result["Rolling_Z_Score"]
            <= -deviation_threshold,
        ],
        [
            "Sudden Increase",
            "Sudden Decrease",
        ],
        default="No Rolling Alert",
    )

    return result


def combine_demand_anomaly_signals(
    iqr_data,
    rolling_data,
    method="Combined",
):
    """Combine IQR and rolling-deviation anomaly signals."""

    if iqr_data is None or iqr_data.empty:
        return pd.DataFrame()

    if method not in DEMAND_ANOMALY_CENTER_METHODS:
        raise ValueError(
            "Unsupported anomaly detection method."
        )

    result = iqr_data.copy()

    if (
        rolling_data is not None
        and not rolling_data.empty
    ):
        rolling_columns = [
            "Timestamp",
            "Rolling_Reference_Mean",
            "Rolling_Reference_Std",
            "Rolling_Z_Score",
            "Rolling_Anomaly",
            "Rolling_Anomaly_Type",
        ]

        available = [
            column
            for column in rolling_columns
            if column in rolling_data.columns
        ]

        result = result.merge(
            rolling_data[available],
            on="Timestamp",
            how="left",
        )

    if "Rolling_Anomaly" not in result.columns:
        result["Rolling_Anomaly"] = False

    result["Rolling_Anomaly"] = (
        result["Rolling_Anomaly"]
        .fillna(False)
        .astype(bool)
    )

    if method == "IQR":
        result["Anomaly_Flag"] = (
            result["IQR_Anomaly"].fillna(False)
        )

    elif method == "Rolling Deviation":
        result["Anomaly_Flag"] = (
            result["Rolling_Anomaly"]
        )

    else:
        result["Anomaly_Flag"] = (
            result["IQR_Anomaly"].fillna(False)
            | result["Rolling_Anomaly"]
        )

    result["Anomaly_Signal_Count"] = (
        result["IQR_Anomaly"].fillna(False).astype(int)
        + result["Rolling_Anomaly"].astype(int)
    )

    result["Anomaly_Severity"] = np.select(
        [
            result["Anomaly_Signal_Count"] >= 2,
            result["Anomaly_Flag"],
        ],
        [
            "High",
            "Review",
        ],
        default="Normal",
    )

    return result


def calculate_demand_anomaly_magnitude(
    anomaly_data,
):
    """Calculate deviation magnitude from the historical reference."""

    if (
        anomaly_data is None
        or anomaly_data.empty
        or "Observed_Total" not in anomaly_data.columns
    ):
        return pd.DataFrame()

    result = anomaly_data.copy()

    reference = result.get(
        "Rolling_Reference_Mean",
        pd.Series(
            np.nan,
            index=result.index,
        ),
    )

    result["Reference_Deviation"] = (
        result["Observed_Total"] - reference
    )

    result["Reference_Deviation_Percentage"] = np.where(
        reference.abs() > 0,
        result["Reference_Deviation"]
        / reference.abs()
        * 100,
        np.nan,
    )

    return result


def build_demand_anomaly_investigation_queue(
    anomaly_data,
):
    """Create a prioritized queue of flagged historical periods."""

    if (
        anomaly_data is None
        or anomaly_data.empty
        or "Anomaly_Flag" not in anomaly_data.columns
    ):
        return pd.DataFrame()

    flagged = anomaly_data[
        anomaly_data["Anomaly_Flag"]
    ].copy()

    if flagged.empty:
        return flagged

    if "Reference_Deviation" in flagged.columns:
        flagged["Investigation_Magnitude"] = (
            flagged["Reference_Deviation"].abs()
        )

    else:
        flagged["Investigation_Magnitude"] = (
            flagged["Observed_Total"].abs()
        )

    flagged["Investigation_Priority"] = np.select(
        [
            flagged["Anomaly_Severity"] == "High",
            flagged["Anomaly_Severity"] == "Review",
        ],
        [
            "P1 - Investigate",
            "P2 - Review",
        ],
        default="P3 - Monitor",
    )

    flagged = flagged.sort_values(
        [
            "Investigation_Priority",
            "Investigation_Magnitude",
        ],
        ascending=[
            True,
            False,
        ],
    )

    return flagged.reset_index(
        drop=True
    )


def generate_demand_anomaly_center_insights(
    anomaly_data,
    investigation_queue,
):
    """Generate cautious descriptions of flagged observations."""

    insights = []

    if anomaly_data is None or anomaly_data.empty:
        return [
            "No period-level observations are available for analysis."
        ]

    total_periods = len(
        anomaly_data
    )

    flagged_count = int(
        anomaly_data["Anomaly_Flag"].sum()
    )

    anomaly_rate = (
        flagged_count / total_periods * 100
        if total_periods
        else 0.0
    )

    insights.append(
        f"{flagged_count:,} of {total_periods:,} periods "
        f"were flagged ({anomaly_rate:.2f}%)."
    )

    if not investigation_queue.empty:
        highest = investigation_queue.iloc[0]

        insights.append(
            "The highest-ranked flagged period is "
            f"{highest['Timestamp']:%Y-%m-%d}, with observed "
            f"activity of {highest['Observed_Total']:,.2f}."
        )

        high_count = int(
            (
                investigation_queue["Anomaly_Severity"]
                == "High"
            ).sum()
        )

        insights.append(
            f"{high_count:,} flagged periods triggered both "
            "IQR and rolling-deviation signals."
        )

    else:
        insights.append(
            "No periods met the selected anomaly rule."
        )

    insights.append(
        "A flagged period may reflect a genuine demand change, "
        "seasonality, a special event, missing context or a data issue."
    )

    insights.append(
        "Investigate the original records and external context before "
        "making operational decisions."
    )

    return insights


