def render_demand_anomaly_detection_center():
    """Main UI for demand anomaly detection."""

    st.header(
        "Demand Anomaly Detection & Investigation Center"
    )

    st.write(
        "Identify unusual historical ticket activity and prioritize "
        "periods for further investigation."
    )

    st.warning(
        "Anomaly detection identifies unusual observations. It does "
        "not establish the cause of a spike or drop."
    )

    dataset_path = st.session_state.get(
        "dataset_path",
        str(DEFAULT_DATASET_PATH),
    )

    try:
        dataframe = load_ticket_dataframe(
            dataset_path
        )
    except Exception as exc:
        st.error(
            f"Unable to load the dataset: {exc}"
        )
        return

    if dataframe is None or dataframe.empty:
        st.error(
            "No historical ticket records are available."
        )
        return

    prepared = prepare_demand_anomaly_center_data(
        dataframe
    )

    if prepared.empty:
        st.error(
            "Required ticket activity columns are missing."
        )
        return

    controls = render_demand_anomaly_center_controls()

    periods = aggregate_demand_anomaly_center_data(
        prepared,
        metric=controls["metric"],
        frequency=controls["frequency"],
    )

    if len(periods) < DEMAND_ANOMALY_CENTER_MINIMUM_PERIODS:
        st.warning(
            "More historical periods are recommended for reliable "
            "descriptive anomaly analysis."
        )
        return

    iqr_data = detect_demand_anomaly_iqr(
        periods,
        multiplier=controls["iqr_multiplier"],
    )

    rolling_data = detect_demand_anomaly_rolling(
        periods,
        window=controls["rolling_window"],
        deviation_threshold=controls[
            "deviation_threshold"
        ],
    )

    anomaly_data = combine_demand_anomaly_signals(
        iqr_data,
        rolling_data,
        method=controls["method"],
    )

    anomaly_data = calculate_demand_anomaly_magnitude(
        anomaly_data
    )

    investigation_queue = (
        build_demand_anomaly_investigation_queue(
            anomaly_data
        )
    )

    insights = generate_demand_anomaly_center_insights(
        anomaly_data,
        investigation_queue,
    )

    render_demand_anomaly_center_overview(
        anomaly_data
    )

    render_demand_anomaly_center_timeline(
        anomaly_data
    )

    render_demand_anomaly_center_investigation_queue(
        investigation_queue
    )

    render_demand_anomaly_center_insights(
        insights
    )

    render_demand_anomaly_center_exports(
        anomaly_data,
        investigation_queue,
    )


