def render_demand_resource_planning_center():
    """Main interface for demand planning and prioritization."""

    st.header(
        "Demand Forecast Planning & Resource Allocation Center"
    )

    st.write(
        "Use historical ticket activity to compare planning "
        "scenarios and identify periods for closer review."
    )

    st.warning(
        "This center provides relative planning indicators. "
        "It does not calculate actual ferry capacity, vessel "
        "requirements, staffing levels or guaranteed future demand."
    )

    dataset_path = st.session_state.get(
        "dataset_path",
        str(DEFAULT_DATASET_PATH),
    )

    try:
        dataframe = load_ticket_dataframe(
            dataset_path
        )
    except Exception as exc:
        st.error(
            f"Unable to load the dataset: {exc}"
        )
        return

    if dataframe is None or dataframe.empty:
        st.error(
            "No historical ticket records are available."
        )
        return

    prepared = prepare_demand_resource_planning_data(
        dataframe
    )

    if prepared.empty:
        st.error(
            "Required ticket activity fields are unavailable."
        )
        return

    controls = render_demand_resource_planning_controls()

    periods = aggregate_demand_resource_planning_data(
        prepared,
        metric=controls["metric"],
        frequency=controls["frequency"],
    )

    if len(periods) < DEMAND_RESOURCE_PLANNING_MINIMUM_PERIODS:
        st.warning(
            "More historical periods are recommended for this analysis."
        )
        return

    report = build_demand_resource_planning_report(
        periods,
        recent_periods=controls["recent_periods"],
    )

    if not report.get("Success"):
        st.error(
            report.get(
                "Reason",
                "Planning report generation failed.",
            )
        )
        return

    render_demand_resource_planning_overview(
        report["Reference"]
    )

    render_demand_resource_scenario_table(
        report["Scenarios"]
    )

    render_demand_resource_priority_analysis(
        report["Priority_Data"],
        report["Priority_Summary"],
    )

    render_demand_resource_planning_actions(
        report["Planning_Actions"]
    )

    render_demand_resource_planning_exports(
        report
    )


