# ============================================================
# PART 38 â€” TICKET SALES VS REDEMPTION RELATIONSHIP ANALYSIS
# ============================================================

TICKET_RELATION_ANALYSIS_VERSION = "1.0.0"

TICKET_RELATION_METRICS = [
    "Sales Count",
    "Redemption Count",
]

TICKET_RELATION_MAX_DISPLAY_ROWS = 2000


def prepare_ticket_relation_data(dataframe):
    """Validate and prepare sales and redemption records."""

    required = [
        "Timestamp",
        "Sales Count",
        "Redemption Count",
    ]

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    if not set(required).issubset(dataframe.columns):
        return pd.DataFrame()

    result = dataframe[required].copy()

    result["Timestamp"] = pd.to_datetime(
        result["Timestamp"],
        errors="coerce",
    )

    for column in TICKET_RELATION_METRICS:
        result[column] = pd.to_numeric(
            result[column],
            errors="coerce",
        )

    result = result.replace(
        [np.inf, -np.inf],
        np.nan,
    )

    result = result.dropna(
        subset=["Timestamp"]
    )

    return result.sort_values(
        "Timestamp"
    ).reset_index(drop=True)


def aggregate_ticket_relation_data(
    dataframe,
    frequency="D",
):
    """Aggregate both activity measures into the same time periods."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    if frequency not in ["D", "W", "MS"]:
        raise ValueError(
            "Frequency must be D, W or MS."
        )

    indexed = dataframe.set_index(
        "Timestamp"
    ).sort_index()

    result = indexed[
        TICKET_RELATION_METRICS
    ].resample(
        frequency
    ).sum(min_count=1).reset_index()

    return result


def calculate_ticket_relation_gap(
    period_data,
):
    """Calculate the numeric difference between observed measures."""

    if period_data is None or period_data.empty:
        return pd.DataFrame()

    required = set(
        TICKET_RELATION_METRICS
    )

    if not required.issubset(period_data.columns):
        return pd.DataFrame()

    result = period_data.copy()

    result["Sales_Minus_Redemption"] = (
        result["Sales Count"]
        - result["Redemption Count"]
    )

    result["Absolute_Measure_Gap"] = (
        result["Sales_Minus_Redemption"].abs()
    )

    result["Combined_Observed_Activity"] = (
        result["Sales Count"]
        + result["Redemption Count"]
    )

    denominator = result[
        "Sales Count"
    ].abs()

    result["Gap_As_Percentage_Of_Sales"] = (
        result["Sales_Minus_Redemption"]
        / denominator.replace(0, np.nan)
        * 100
    )

    result["Gap_Direction"] = np.select(
        [
            result["Sales_Minus_Redemption"] > 0,
            result["Sales_Minus_Redemption"] < 0,
        ],
        [
            "Sales Higher",
            "Redemption Higher",
        ],
        default="Equal Measures",
    )

    return result


def calculate_ticket_relation_summary(
    relation_data,
):
    """Summarize totals and relationship statistics."""

    if relation_data is None or relation_data.empty:
        return {}

    result = relation_data.copy()

    sales = pd.to_numeric(
        result["Sales Count"],
        errors="coerce",
    )

    redemptions = pd.to_numeric(
        result["Redemption Count"],
        errors="coerce",
    )

    valid_pairs = pd.DataFrame({
        "Sales": sales,
        "Redemptions": redemptions,
    }).dropna()

    if valid_pairs.empty:
        correlation = np.nan
    elif len(valid_pairs) < 2:
        correlation = np.nan
    elif (
        valid_pairs["Sales"].nunique() < 2
        or valid_pairs["Redemptions"].nunique() < 2
    ):
        correlation = np.nan
    else:
        correlation = valid_pairs[
            "Sales"
        ].corr(
            valid_pairs["Redemptions"]
        )

    gap = sales - redemptions

    return {
        "Period_Count": int(len(result)),
        "Sales_Total": float(sales.sum()),
        "Redemption_Total": float(redemptions.sum()),
        "Sales_Mean_Per_Period": float(
            sales.mean()
        ) if sales.notna().any() else np.nan,
        "Redemption_Mean_Per_Period": float(
            redemptions.mean()
        ) if redemptions.notna().any() else np.nan,
        "Mean_Sales_Minus_Redemption": float(
            gap.mean()
        ) if gap.notna().any() else np.nan,
        "Mean_Absolute_Gap": float(
            gap.abs().mean()
        ) if gap.notna().any() else np.nan,
        "Pearson_Correlation": float(
            correlation
        ) if pd.notna(correlation) else np.nan,
        "Valid_Paired_Periods": int(
            len(valid_pairs)
        ),
    }


def calculate_ticket_relation_rolling_correlation(
    relation_data,
    window=7,
):
    """Calculate rolling correlation between both activity measures."""

    if relation_data is None or relation_data.empty:
        return pd.DataFrame()

    if window < 2:
        raise ValueError(
            "Rolling window must be at least 2."
        )

    result = relation_data[
        [
            "Timestamp",
            "Sales Count",
            "Redemption Count",
        ]
    ].copy()

    result["Rolling_Correlation"] = (
        result["Sales Count"]
        .rolling(
            window=window,
            min_periods=window,
        )
        .corr(
            result["Redemption Count"]
        )
    )

    result["Rolling_Window_Periods"] = window

    return result


def calculate_ticket_relation_lag_analysis(
    relation_data,
    maximum_lag=7,
):
    """Compare sales at earlier periods with later redemptions."""

    if relation_data is None or relation_data.empty:
        return pd.DataFrame()

    if maximum_lag < 0:
        raise ValueError(
            "Maximum lag cannot be negative."
        )

    sales = pd.to_numeric(
        relation_data["Sales Count"],
        errors="coerce",
    )

    redemptions = pd.to_numeric(
        relation_data["Redemption Count"],
        errors="coerce",
    )

    rows = []

    for lag in range(
        0,
        maximum_lag + 1,
    ):
        aligned = pd.DataFrame({
            "Earlier_Sales": sales,
            "Later_Redemptions": redemptions.shift(-lag),
        }).dropna()

        if (
            len(aligned) >= 2
            and aligned["Earlier_Sales"].nunique() > 1
            and aligned["Later_Redemptions"].nunique() > 1
        ):
            correlation = aligned[
                "Earlier_Sales"
            ].corr(
                aligned["Later_Redemptions"]
            )
        else:
            correlation = np.nan

        rows.append({
            "Lag_Periods": lag,
            "Paired_Observations": int(
                len(aligned)
            ),
            "Sales_Redemption_Correlation": (
                float(correlation)
                if pd.notna(correlation)
                else np.nan
            ),
        })

    return pd.DataFrame(rows)


def identify_ticket_relation_divergence(
    relation_data,
    percentile=90,
):
    """Identify periods with unusually large absolute gaps."""

    if relation_data is None or relation_data.empty:
        return pd.DataFrame()

    result = calculate_ticket_relation_gap(
        relation_data
    )

    if result.empty:
        return result

    if not 0 <= percentile <= 100:
        raise ValueError(
            "Percentile must be between 0 and 100."
        )

    valid_gaps = result[
        "Absolute_Measure_Gap"
    ].dropna()

    if valid_gaps.empty:
        result["Divergence_Threshold"] = np.nan
        result["Large_Gap_Flag"] = False
        return result

    threshold = float(
        valid_gaps.quantile(
            percentile / 100
        )
    )

    result["Divergence_Threshold"] = threshold

    result["Large_Gap_Flag"] = (
        result["Absolute_Measure_Gap"] >= threshold
    ) & result["Absolute_Measure_Gap"].notna()

    result["Gap_Review_Category"] = np.where(
        result["Large_Gap_Flag"],
        "Review Large Difference",
        "Within Historical Comparison Range",
    )

    return result


def generate_ticket_relation_insights(
    summary,
    lag_data,
    divergence_data,
):
    """Generate cautious, data-driven relationship observations."""

    insights = []

    if not summary:
        return [
            "Insufficient data to generate relationship insights."
        ]

    correlation = summary.get(
        "Pearson_Correlation",
        np.nan,
    )

    if pd.notna(correlation):
        if correlation >= 0.7:
            insights.append(
                "Sales and redemption activity show a strong "
                "positive linear relationship in the selected periods."
            )
        elif correlation >= 0.3:
            insights.append(
                "Sales and redemption activity show a moderate "
                "positive linear relationship."
            )
        elif correlation > -0.3:
            insights.append(
                "The selected periods show a weak linear relationship "
                "between sales and redemption activity."
            )
        else:
            insights.append(
                "The selected periods show a negative linear relationship. "
                "Review data coverage and temporal context before interpreting it."
            )
    else:
        insights.append(
            "Correlation could not be estimated reliably for the selected data."
        )

    mean_gap = summary.get(
        "Mean_Sales_Minus_Redemption",
        np.nan,
    )

    if pd.notna(mean_gap):
        if mean_gap > 0:
            insights.append(
                "The average period-level sales measure exceeds "
                "the redemption measure."
            )
        elif mean_gap < 0:
            insights.append(
                "The average period-level redemption measure exceeds "
                "the sales measure."
            )
        else:
            insights.append(
                "The average signed difference between the two measures is zero."
            )

    if (
        lag_data is not None
        and not lag_data.empty
    ):
        valid_lags = lag_data.dropna(
            subset=["Sales_Redemption_Correlation"]
        )

        if not valid_lags.empty:
            best_row = valid_lags.loc[
                valid_lags[
                    "Sales_Redemption_Correlation"
                ].abs().idxmax()
            ]

            insights.append(
                "The largest absolute lagged correlation occurs at "
                f"lag {int(best_row['Lag_Periods'])}. "
                "This is exploratory and does not establish causation."
            )

    if (
        divergence_data is not None
        and not divergence_data.empty
    ):
        count = int(
            divergence_data[
                "Large_Gap_Flag"
            ].sum()
        )

        insights.append(
            f"{count:,} periods meet the selected historical "
            "large-gap threshold."
        )

    insights.append(
        "A difference between sales and redemptions is a comparison "
        "of two measures; it is not automatically a count of unredeemed tickets."
    )

    return insights


