def render_ticket_sales_redemption_relationship_center():
    """Main UI for sales-redemption relationship analysis."""

    st.header(
        "Ticket Sales vs Redemption Relationship Analysis Center"
    )

    st.write(
        "Compare ticket sales and redemption activity across "
        "historical periods, investigate differences, and explore "
        "their time-based relationships."
    )

    dataset_path = st.session_state.get(
        "dataset_path",
        str(DEFAULT_DATASET_PATH),
    )

    try:
        dataframe = load_ticket_dataframe(
            dataset_path
        )
    except Exception as exc:
        st.error(
            f"Unable to load the ticket dataset: {exc}"
        )
        return

    if dataframe is None or dataframe.empty:
        st.error(
            "The ticket dataset contains no usable records."
        )
        return

    prepared = prepare_ticket_relation_data(
        dataframe
    )

    if prepared.empty:
        st.error(
            "Timestamp, Sales Count and Redemption Count are required."
        )
        return

    controls = render_ticket_relation_controls()

    relation_data = aggregate_ticket_relation_data(
        prepared,
        frequency=controls["frequency"],
    )

    if relation_data.empty:
        st.warning(
            "No aggregated periods are available."
        )
        return

    summary = calculate_ticket_relation_summary(
        relation_data
    )

    gap_data = calculate_ticket_relation_gap(
        relation_data
    )

    rolling_data = (
        calculate_ticket_relation_rolling_correlation(
            relation_data,
            window=controls["rolling_window"],
        )
    )

    lag_data = calculate_ticket_relation_lag_analysis(
        relation_data,
        maximum_lag=controls["maximum_lag"],
    )

    divergence_data = identify_ticket_relation_divergence(
        relation_data,
        percentile=controls["divergence_percentile"],
    )

    insights = generate_ticket_relation_insights(
        summary,
        lag_data,
        divergence_data,
    )

    render_ticket_relation_overview(
        summary
    )

    render_ticket_relation_trends(
        relation_data,
        rolling_data,
    )

    render_ticket_relation_gap_analysis(
        gap_data,
        divergence_data,
    )

    render_ticket_relation_lag_analysis(
        lag_data
    )

    render_ticket_relation_insight_panel(
        insights
    )

    render_ticket_relation_exports(
        relation_data,
        gap_data,
        rolling_data,
        lag_data,
        divergence_data,
    )


