DEMAND_GAP_INVESTIGATION_VERSION = "1.0.0"

DEMAND_GAP_INVESTIGATION_METRICS = [
    "Sales Count",
    "Redemption Count",
]

DEMAND_GAP_INVESTIGATION_MAX_DISPLAY_ROWS = 2000


def prepare_demand_gap_investigation_data(dataframe):
    """Prepare source records for data completeness investigation."""

    required = [
        "Timestamp",
        "Sales Count",
        "Redemption Count",
    ]

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    if not set(required).issubset(dataframe.columns):
        return pd.DataFrame()

    result = dataframe[required].copy()

    result["Timestamp"] = pd.to_datetime(
        result["Timestamp"],
        errors="coerce",
    )

    for column in DEMAND_GAP_INVESTIGATION_METRICS:
        result[column] = pd.to_numeric(
            result[column],
            errors="coerce",
        )

    result = result.replace(
        [np.inf, -np.inf],
        np.nan,
    )

    return result


def calculate_demand_gap_source_quality(dataframe):
    """Calculate source-level missingness and duplicate indicators."""

    if dataframe is None or dataframe.empty:
        return {}

    total_rows = len(dataframe)

    valid_timestamps = dataframe[
        "Timestamp"
    ].notna()

    invalid_timestamp_count = int(
        (~valid_timestamps).sum()
    )

    valid_time_data = dataframe.loc[
        valid_timestamps
    ].copy()

    duplicate_timestamp_rows = int(
        valid_time_data.duplicated(
            subset=["Timestamp"],
            keep=False,
        ).sum()
    )

    duplicate_timestamp_excess = int(
        valid_time_data.duplicated(
            subset=["Timestamp"],
            keep="first",
        ).sum()
    )

    missing_sales = int(
        dataframe["Sales Count"].isna().sum()
    )

    missing_redemptions = int(
        dataframe["Redemption Count"].isna().sum()
    )

    negative_sales = int(
        (
            dataframe["Sales Count"] < 0
        ).sum()
    )

    negative_redemptions = int(
        (
            dataframe["Redemption Count"] < 0
        ).sum()
    )

    valid_timestamp_count = int(
        valid_timestamps.sum()
    )

    date_min = (
        valid_time_data["Timestamp"].min()
        if not valid_time_data.empty
        else pd.NaT
    )

    date_max = (
        valid_time_data["Timestamp"].max()
        if not valid_time_data.empty
        else pd.NaT
    )

    return {
        "Total_Source_Rows": total_rows,
        "Valid_Timestamp_Rows": valid_timestamp_count,
        "Invalid_Timestamp_Rows": invalid_timestamp_count,
        "Missing_Sales_Values": missing_sales,
        "Missing_Redemption_Values": missing_redemptions,
        "Duplicate_Timestamp_Rows": duplicate_timestamp_rows,
        "Duplicate_Timestamp_Excess_Rows": duplicate_timestamp_excess,
        "Negative_Sales_Values": negative_sales,
        "Negative_Redemption_Values": negative_redemptions,
        "First_Valid_Timestamp": date_min,
        "Last_Valid_Timestamp": date_max,
        "Sales_Completeness_Percentage": (
            100 * dataframe["Sales Count"].notna().mean()
        ),
        "Redemption_Completeness_Percentage": (
            100 * dataframe["Redemption Count"].notna().mean()
        ),
    }


def aggregate_demand_gap_investigation_data(
    dataframe,
    frequency="D",
):
    """Aggregate observations and retain observed-record counts."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    if frequency not in ["D", "W", "MS"]:
        raise ValueError(
            "Frequency must be D, W or MS."
        )

    valid = dataframe.dropna(
        subset=["Timestamp"]
    ).copy()

    if valid.empty:
        return pd.DataFrame()

    indexed = valid.set_index(
        "Timestamp"
    ).sort_index()

    result = indexed.resample(
        frequency
    ).agg(
        Sales_Total=(
            "Sales Count",
            lambda values: values.sum(min_count=1),
        ),
        Redemption_Total=(
            "Redemption Count",
            lambda values: values.sum(min_count=1),
        ),
        Source_Record_Count=(
            "Timestamp",
            "size",
        ),
        Valid_Sales_Record_Count=(
            "Sales Count",
            "count",
        ),
        Valid_Redemption_Record_Count=(
            "Redemption Count",
            "count",
        ),
    ).reset_index()

    return result


def identify_demand_gap_periods(
    period_data,
    frequency="D",
):
    """Flag calendar periods with no valid source observations."""

    if period_data is None or period_data.empty:
        return pd.DataFrame()

    if frequency not in ["D", "W", "MS"]:
        raise ValueError(
            "Frequency must be D, W or MS."
        )

    result = period_data.copy()

    result["No_Source_Records"] = (
        result["Source_Record_Count"] == 0
    )

    result["Missing_Sales_For_Period"] = (
        result["Valid_Sales_Record_Count"] == 0
    )

    result["Missing_Redemption_For_Period"] = (
        result["Valid_Redemption_Record_Count"] == 0
    )

    result["Potential_Gap_Category"] = np.select(
        [
            result["No_Source_Records"],
            (
                result["Missing_Sales_For_Period"]
                & result["Missing_Redemption_For_Period"]
            ),
            result["Missing_Sales_For_Period"],
            result["Missing_Redemption_For_Period"],
        ],
        [
            "No Source Records",
            "Both Measures Missing",
            "Sales Measure Missing",
            "Redemption Measure Missing",
        ],
        default="Observed Data Available",
    )

    result["Investigation_Required"] = (
        result["Potential_Gap_Category"]
        != "Observed Data Available"
    )

    return result


def calculate_demand_gap_completeness_summary(
    period_data,
):
    """Summarize observed period coverage."""

    if period_data is None or period_data.empty:
        return {}

    total_periods = len(period_data)

    periods_with_records = int(
        (
            period_data["Source_Record_Count"] > 0
        ).sum()
    )

    periods_without_records = int(
        (
            period_data["Source_Record_Count"] == 0
        ).sum()
    )

    periods_with_sales = int(
        (
            period_data["Valid_Sales_Record_Count"] > 0
        ).sum()
    )

    periods_with_redemptions = int(
        (
            period_data["Valid_Redemption_Record_Count"] > 0
        ).sum()
    )

    periods_with_both = int(
        (
            (
                period_data["Valid_Sales_Record_Count"] > 0
            )
            & (
                period_data["Valid_Redemption_Record_Count"] > 0
            )
        ).sum()
    )

    return {
        "Expected_Calendar_Periods": total_periods,
        "Periods_With_Source_Records": periods_with_records,
        "Periods_Without_Source_Records": periods_without_records,
        "Periods_With_Sales_Observations": periods_with_sales,
        "Periods_With_Redemption_Observations": periods_with_redemptions,
        "Periods_With_Both_Measures": periods_with_both,
        "Calendar_Record_Coverage_Percentage": (
            100 * periods_with_records / total_periods
        ),
        "Sales_Period_Coverage_Percentage": (
            100 * periods_with_sales / total_periods
        ),
        "Redemption_Period_Coverage_Percentage": (
            100 * periods_with_redemptions / total_periods
        ),
        "Both_Measures_Period_Coverage_Percentage": (
            100 * periods_with_both / total_periods
        ),
    }


def build_demand_gap_investigation_queue(
    period_data,
):
    """Create a review queue for potentially incomplete periods."""

    if period_data is None or period_data.empty:
        return pd.DataFrame()

    result = period_data.loc[
        period_data["Investigation_Required"]
    ].copy()

    if result.empty:
        return result

    priority_map = {
        "No Source Records": 1,
        "Both Measures Missing": 2,
        "Sales Measure Missing": 3,
        "Redemption Measure Missing": 4,
    }

    result["Review_Priority"] = (
        result["Potential_Gap_Category"].map(
            priority_map
        ).fillna(99).astype(int)
    )

    result = result.sort_values(
        ["Review_Priority", "Timestamp"]
    )

    return result.reset_index(
        drop=True
    )


def generate_demand_gap_investigation_recommendations(
    source_quality,
    completeness_summary,
):
    """Generate recommendations based on observed quality indicators."""

    recommendations = []

    if not source_quality or not completeness_summary:
        return [
            "Insufficient data to generate quality recommendations."
        ]

    invalid_timestamps = source_quality[
        "Invalid_Timestamp_Rows"
    ]

    if invalid_timestamps > 0:
        recommendations.append(
            f"Review {invalid_timestamps:,} records with invalid timestamps."
        )
    else:
        recommendations.append(
            "No invalid timestamps were found in the prepared source records."
        )

    duplicate_rows = source_quality[
        "Duplicate_Timestamp_Excess_Rows"
    ]

    if duplicate_rows > 0:
        recommendations.append(
            f"Review {duplicate_rows:,} excess duplicate-timestamp rows. "
            "Repeated timestamps may be legitimate observations, so do not "
            "delete them automatically."
        )

    missing_sales = source_quality[
        "Missing_Sales_Values"
    ]

    missing_redemptions = source_quality[
        "Missing_Redemption_Values"
    ]

    if missing_sales > 0:
        recommendations.append(
            f"Investigate {missing_sales:,} missing Sales Count values."
        )

    if missing_redemptions > 0:
        recommendations.append(
            f"Investigate {missing_redemptions:,} missing Redemption Count values."
        )

    gap_count = completeness_summary[
        "Periods_Without_Source_Records"
    ]

    if gap_count > 0:
        recommendations.append(
            f"Investigate {gap_count:,} calendar periods without source records. "
            "Confirm whether these represent closed periods, zero activity, "
            "or incomplete data."
        )
    else:
        recommendations.append(
            "Every generated calendar period contains at least one source record."
        )

    recommendations.append(
        "Before forecasting, document the expected reporting frequency and "
        "whether absent periods should be treated as zero, missing, or not applicable."
    )

    return recommendations


def build_demand_gap_investigation_report(
    dataframe,
    frequency="D",
):
    """Build the complete data completeness report."""

    prepared = prepare_demand_gap_investigation_data(
        dataframe
    )

    if prepared.empty:
        return {
            "Success": False,
            "Reason": "No valid source records are available.",
        }

    source_quality = calculate_demand_gap_source_quality(
        prepared
    )

    aggregated = aggregate_demand_gap_investigation_data(
        prepared,
        frequency=frequency,
    )

    if aggregated.empty:
        return {
            "Success": False,
            "Reason": "Unable to aggregate source observations.",
        }

    periods = identify_demand_gap_periods(
        aggregated,
        frequency=frequency,
    )

    summary = calculate_demand_gap_completeness_summary(
        periods
    )

    queue = build_demand_gap_investigation_queue(
        periods
    )

    recommendations = (
        generate_demand_gap_investigation_recommendations(
            source_quality,
            summary,
        )
    )

    return {
        "Success": True,
        "Source_Quality": source_quality,
        "Aggregated_Periods": periods,
        "Completeness_Summary": summary,
        "Investigation_Queue": queue,
        "Recommendations": recommendations,
    }


