# PART 40 â€” DEMAND FORECAST FEATURE & RELATIONSHIP INTELLIGENCE
# ============================================================

DEMAND_FEATURE_INTELLIGENCE_VERSION = "1.0.0"

DEMAND_FEATURE_INTELLIGENCE_METRICS = [
    "Sales Count",
    "Redemption Count",
]

DEMAND_FEATURE_INTELLIGENCE_MAX_LAG = 14
DEMAND_FEATURE_INTELLIGENCE_MAX_DISPLAY_ROWS = 2000


def prepare_demand_feature_intelligence_data(dataframe):
    """Validate source data before time-based feature engineering."""

    required = [
        "Timestamp",
        "Sales Count",
        "Redemption Count",
    ]

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    if not set(required).issubset(dataframe.columns):
        return pd.DataFrame()

    result = dataframe[required].copy()

    result["Timestamp"] = pd.to_datetime(
        result["Timestamp"],
        errors="coerce",
    )

    for column in DEMAND_FEATURE_INTELLIGENCE_METRICS:
        result[column] = pd.to_numeric(
            result[column],
            errors="coerce",
        )

    result = result.replace(
        [np.inf, -np.inf],
        np.nan,
    )

    result = result.dropna(
        subset=["Timestamp"]
    )

    return result.sort_values(
        "Timestamp"
    ).reset_index(drop=True)


def aggregate_demand_feature_intelligence_data(
    dataframe,
    frequency="D",
):
    """Create a regular daily, weekly or monthly demand series."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    if frequency not in ["D", "W", "MS"]:
        raise ValueError(
            "Frequency must be D, W or MS."
        )

    indexed = dataframe.set_index(
        "Timestamp"
    ).sort_index()

    result = indexed[
        DEMAND_FEATURE_INTELLIGENCE_METRICS
    ].resample(
        frequency
    ).sum(min_count=1).reset_index()

    return result


def create_demand_time_features(
    period_data,
    frequency="D",
):
    """Create calendar and historical lag features."""

    if period_data is None or period_data.empty:
        return pd.DataFrame()

    result = period_data.copy()

    result["Timestamp"] = pd.to_datetime(
        result["Timestamp"],
        errors="coerce",
    )

    result = result.dropna(
        subset=["Timestamp"]
    ).sort_values(
        "Timestamp"
    ).reset_index(drop=True)

    timestamp = result["Timestamp"]

    result["Calendar_Year"] = timestamp.dt.year
    result["Calendar_Month"] = timestamp.dt.month
    result["Calendar_Quarter"] = timestamp.dt.quarter
    result["Day_Of_Week"] = timestamp.dt.dayofweek
    result["Day_Of_Month"] = timestamp.dt.day
    result["Week_Of_Year"] = (
        timestamp.dt.isocalendar().week.astype("int64")
    )

    result["Is_Weekend"] = (
        timestamp.dt.dayofweek >= 5
    ).astype(int)

    result["Day_Of_Week_Sin"] = np.sin(
        2 * np.pi * timestamp.dt.dayofweek / 7
    )

    result["Day_Of_Week_Cos"] = np.cos(
        2 * np.pi * timestamp.dt.dayofweek / 7
    )

    result["Month_Sin"] = np.sin(
        2 * np.pi * (timestamp.dt.month - 1) / 12
    )

    result["Month_Cos"] = np.cos(
        2 * np.pi * (timestamp.dt.month - 1) / 12
    )

    for metric in DEMAND_FEATURE_INTELLIGENCE_METRICS:
        safe_name = metric.replace(
            " ",
            "_",
        )

        # Shift first so each feature uses only prior periods.
        result[f"{safe_name}_Previous_Period"] = (
            result[metric].shift(1)
        )

        for lag in [2, 3, 7, 14]:
            if lag <= DEMAND_FEATURE_INTELLIGENCE_MAX_LAG:
                result[f"{safe_name}_Lag_{lag}"] = (
                    result[metric].shift(lag)
                )

        # Rolling calculations exclude the current period.
        previous_values = result[metric].shift(1)

        result[f"{safe_name}_Rolling_Mean_3"] = (
            previous_values.rolling(
                window=3,
                min_periods=3,
            ).mean()
        )

        result[f"{safe_name}_Rolling_Mean_7"] = (
            previous_values.rolling(
                window=7,
                min_periods=7,
            ).mean()
        )

        result[f"{safe_name}_Rolling_Std_7"] = (
            previous_values.rolling(
                window=7,
                min_periods=7,
            ).std()
        )

    result["Aggregation_Frequency"] = frequency

    return result


def calculate_demand_feature_correlations(
    feature_data,
):
    """Measure feature correlations with the two demand measures."""

    if feature_data is None or feature_data.empty:
        return pd.DataFrame()

    feature_columns = [
        column
        for column in feature_data.columns
        if column not in [
            "Timestamp",
            "Sales Count",
            "Redemption Count",
            "Aggregation_Frequency",
        ]
    ]

    rows = []

    for feature in feature_columns:
        feature_values = pd.to_numeric(
            feature_data[feature],
            errors="coerce",
        )

        for target in DEMAND_FEATURE_INTELLIGENCE_METRICS:
            target_values = pd.to_numeric(
                feature_data[target],
                errors="coerce",
            )

            paired = pd.DataFrame({
                "Feature": feature_values,
                "Target": target_values,
            }).dropna()

            if (
                len(paired) >= 3
                and paired["Feature"].nunique() > 1
                and paired["Target"].nunique() > 1
            ):
                correlation = paired[
                    "Feature"
                ].corr(
                    paired["Target"]
                )
            else:
                correlation = np.nan

            rows.append({
                "Feature": feature,
                "Target_Metric": target,
                "Valid_Paired_Observations": int(
                    len(paired)
                ),
                "Pearson_Correlation": (
                    float(correlation)
                    if pd.notna(correlation)
                    else np.nan
                ),
            })

    return pd.DataFrame(
        rows
    )


def calculate_demand_feature_quality(
    feature_data,
):
    """Summarize feature completeness and availability."""

    if feature_data is None or feature_data.empty:
        return {}

    feature_columns = [
        column
        for column in feature_data.columns
        if column not in [
            "Timestamp",
            "Aggregation_Frequency",
        ]
    ]

    rows = []

    for column in feature_columns:
        series = feature_data[column]

        rows.append({
            "Feature": column,
            "Available_Values": int(
                series.notna().sum()
            ),
            "Missing_Values": int(
                series.isna().sum()
            ),
            "Completeness_Percentage": float(
                series.notna().mean() * 100
            ),
            "Unique_Values": int(
                series.nunique(dropna=True)
            ),
        })

    return pd.DataFrame(
        rows
    )


def calculate_demand_weekday_profiles(
    period_data,
):
    """Compare observed demand across weekdays."""

    if period_data is None or period_data.empty:
        return pd.DataFrame()

    result = period_data.copy()

    result["Day_Of_Week"] = (
        result["Timestamp"].dt.dayofweek
    )

    result["Weekday_Name"] = (
        result["Timestamp"].dt.day_name()
    )

    profile = result.groupby(
        [
            "Day_Of_Week",
            "Weekday_Name",
        ],
        observed=True,
    ).agg(
        Sales_Mean=("Sales Count", "mean"),
        Sales_Median=("Sales Count", "median"),
        Redemption_Mean=("Redemption Count", "mean"),
        Redemption_Median=("Redemption Count", "median"),
        Observed_Periods=("Timestamp", "count"),
    ).reset_index()

    return profile.sort_values(
        "Day_Of_Week"
    )


def calculate_demand_feature_insights(
    feature_data,
    correlation_data,
    quality_data,
):
    """Generate descriptive observations from feature analysis."""

    insights = []

    if feature_data is None or feature_data.empty:
        return [
            "No feature data is available for analysis."
        ]

    insights.append(
        f"Feature engineering produced {len(feature_data.columns):,} columns, "
        "including target measures, calendar features and lag-based features."
    )

    if (
        correlation_data is not None
        and not correlation_data.empty
    ):
        valid_correlations = correlation_data.dropna(
            subset=["Pearson_Correlation"]
        )

        if not valid_correlations.empty:
            strongest = valid_correlations.loc[
                valid_correlations[
                    "Pearson_Correlation"
                ].abs().idxmax()
            ]

            insights.append(
                f"The strongest absolute feature correlation in the inspected "
                f"table is {strongest['Feature']} against "
                f"{strongest['Target_Metric']} "
                f"(r = {strongest['Pearson_Correlation']:.3f})."
            )

    if (
        quality_data is not None
        and not quality_data.empty
    ):
        lag_features = quality_data[
            quality_data["Feature"].str.contains(
                "Lag|Previous_Period|Rolling",
                case=False,
                regex=True,
            )
        ]

        if not lag_features.empty:
            incomplete = int(
                (
                    lag_features["Missing_Values"] > 0
                ).sum()
            )

            insights.append(
                f"{incomplete:,} lag or rolling features contain missing values, "
                "which is expected at the beginning of a time series."
            )

    insights.append(
        "Correlations describe association; they do not establish causal effects."
    )

    insights.append(
        "Before training, split the data chronologically and ensure all "
        "features are available at the forecast origin."
    )

    return insights


def build_demand_feature_intelligence_report(
    period_data,
    frequency="D",
):
    """Build feature data and supporting analysis tables."""

    features = create_demand_time_features(
        period_data,
        frequency=frequency,
    )

    if features.empty:
        return {
            "Success": False,
            "Reason": "Unable to construct time-based features.",
        }

    correlations = calculate_demand_feature_correlations(
        features
    )

    quality = calculate_demand_feature_quality(
        features
    )

    weekday_profile = calculate_demand_weekday_profiles(
        period_data
    )

    insights = calculate_demand_feature_insights(
        features,
        correlations,
        quality,
    )

    return {
        "Success": True,
        "Feature_Data": features,
        "Correlation_Data": correlations,
        "Feature_Quality": quality,
        "Weekday_Profile": weekday_profile,
        "Insights": insights,
    }


