# ------------------------------------------------------------
# 41.14 â€” MAIN BENCHMARK CENTER
# ------------------------------------------------------------

def render_demand_baseline_benchmark_center(
    dataframe=None,
):
    """
    Main renderer for Part 41.

    Connected through the dedicated Demand Baseline Benchmark page.
    """

    st.header(
        "Demand Forecast Baseline Benchmark Center"
    )

    st.markdown(
        """
        Compare simple historical reference methods using
        chronological holdout evaluation.

        This module does not train a machine-learning model,
        predict exact ferry arrivals, or estimate vessel capacity.
        """
    )

    if dataframe is None:
        try:
            dataset_path = DEFAULT_DATASET_PATH

            if not dataset_path.exists():
                st.error(
                    "The configured ticket dataset was not found."
                )
                return

            dataframe = load_ticket_dataframe(
                str(dataset_path)
            )

        except Exception as error:
            st.error(
                "Unable to load the ticket dataset."
            )

            st.caption(
                f"Details: {error}"
            )
            return

    prepared = prepare_demand_baseline_benchmark_data(
        dataframe
    )

    if prepared.empty:
        st.warning(
            "No usable ticket demand data is available."
        )
        return

    controls_col1, controls_col2 = st.columns(2)

    with controls_col1:
        selected_metric = st.selectbox(
            "Demand metric",
            DEMAND_BASELINE_BENCHMARK_METRICS,
            key="demand_baseline_metric",
        )

    with controls_col2:
        frequency_options = {
            "Daily": "D",
            "Weekly": "W",
            "Monthly": "MS",
        }

        selected_frequency_label = st.selectbox(
            "Aggregation frequency",
            list(frequency_options.keys()),
            key="demand_baseline_frequency",
        )

    selected_frequency = frequency_options[
        selected_frequency_label
    ]

    test_fraction = st.slider(
        "Test period share",
        min_value=0.10,
        max_value=0.40,
        value=0.20,
        step=0.05,
        key="demand_baseline_test_fraction",
        help=(
            "The latest portion of the series is held out "
            "for evaluation."
        ),
    )

    if selected_frequency == "D":
        default_seasonal_period = 7
        seasonal_help = (
            "For daily data, 7 represents a seven-day cycle."
        )

    elif selected_frequency == "W":
        default_seasonal_period = 52
        seasonal_help = (
            "For weekly data, 52 represents approximately "
            "one year of weekly periods."
        )

    else:
        default_seasonal_period = 12
        seasonal_help = (
            "For monthly data, 12 represents a twelve-month cycle."
        )

    seasonal_period = st.number_input(
        "Seasonal period",
        min_value=1,
        max_value=366,
        value=default_seasonal_period,
        step=1,
        help=seasonal_help,
        key="demand_baseline_seasonal_period",
    )

    aggregated = aggregate_demand_baseline_benchmark_data(
        prepared,
        metric=selected_metric,
        frequency=selected_frequency,
    )

    if aggregated.empty:
        st.warning(
            "Demand aggregation produced no usable observations."
        )
        return

    train_data, test_data = (
        split_demand_baseline_chronologically(
            aggregated,
            test_fraction=test_fraction,
        )
    )

    if train_data.empty or test_data.empty:
        st.warning(
            "There are not enough valid observations for "
            "chronological train/test evaluation."
        )
        return

    predictions = create_demand_baseline_predictions(
        train_data,
        test_data,
        seasonal_period=int(seasonal_period),
    )

    if predictions.empty:
        st.warning(
            "Baseline predictions could not be generated."
        )
        return

    comparison = compare_demand_baseline_models(
        predictions
    )

    evaluation_data = build_demand_baseline_evaluation_data(
        predictions
    )

    artifact_path = None
    try:
        artifact_path = save_demand_baseline_evaluation_artifact(
            evaluation_data
        )
    except Exception as error:
        logging.exception(
            "Could not save the baseline evaluation artifact."
        )
        st.warning(
            "Predictions were generated, but the reusable evaluation "
            "CSV could not be saved. You can still download it below."
        )
        st.caption(f"Save details: {error}")

    if artifact_path is not None:
        st.success(
            "Reusable evaluation CSV saved successfully."
        )
        st.caption(
            f"Saved file: {artifact_path}"
        )

    report = build_demand_baseline_benchmark_report(
        metric=selected_metric,
        frequency=selected_frequency,
        train_data=train_data,
        test_data=test_data,
        comparison=comparison,
    )

    render_demand_baseline_benchmark_overview(
        train_data=train_data,
        test_data=test_data,
        comparison=comparison,
        metric=selected_metric,
        frequency=selected_frequency,
    )

    st.divider()

    render_demand_baseline_prediction_chart(
        predictions
    )

    st.divider()

    render_demand_baseline_error_analysis(
        predictions
    )

    st.divider()

    render_demand_baseline_prediction_table(
        predictions
    )

    st.divider()

    with st.expander(
        "Benchmark Methodology and Limitations"
    ):
        st.markdown(
            """
            **Naive baseline:** repeats the final observed
            training value for each test period.

            **Historical mean:** uses the mean of the
            training observations.

            **Historical median:** uses the median of the
            training observations.

            **Seasonal naive:** uses a historical observation
            separated by the chosen seasonal period, with a
            training-mean fallback where necessary.

            **Chronological split:** earlier observations form
            the training history; later observations are held
            out for evaluation.

            **MAE:** average absolute prediction error.

            **RMSE:** gives larger errors more influence.

            **WAPE:** total absolute error divided by the sum
            of absolute actual values, expressed as a percentage.

            These are reference benchmarks. They do not establish
            future performance, passenger counts, vessel capacity
            or guaranteed operational outcomes.
            """
        )

    st.divider()

    render_demand_baseline_benchmark_exports(
        prediction_data=predictions,
        comparison=comparison,
        report=report,
        evaluation_data=evaluation_data,
    )

    st.caption(
        "Demand Baseline Benchmark Center "
        f"v{DEMAND_BASELINE_BENCHMARK_VERSION}"
    )


