# >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
# PART 42 START
# DEMAND FORECAST STABILITY & VOLATILITY INTELLIGENCE CENTER
# >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

DEMAND_STABILITY_VERSION = "1.0.0"

DEMAND_STABILITY_METRICS = [
    "Sales Count",
    "Redemption Count",
]


# ------------------------------------------------------------
# 42.1 â€” PREPARE SOURCE DATA
# ------------------------------------------------------------

def prepare_demand_stability_data(dataframe):
    """Validate and prepare historical ticket demand data."""

    required_columns = [
        "Timestamp",
        "Sales Count",
        "Redemption Count",
    ]

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    if any(
        column not in dataframe.columns
        for column in required_columns
    ):
        return pd.DataFrame()

    result = dataframe[
        required_columns
    ].copy()

    result["Timestamp"] = pd.to_datetime(
        result["Timestamp"],
        errors="coerce",
    )

    for column in DEMAND_STABILITY_METRICS:
        result[column] = pd.to_numeric(
            result[column],
            errors="coerce",
        )

    result = result.replace(
        [np.inf, -np.inf],
        np.nan,
    )

    result = result.dropna(
        subset=["Timestamp"]
    )

    result = result.sort_values(
        "Timestamp"
    ).reset_index(drop=True)

    return result


# ------------------------------------------------------------
# 42.2 â€” AGGREGATE DEMAND
# ------------------------------------------------------------

def aggregate_demand_stability_data(
    dataframe,
    metric="Sales Count",
    frequency="D",
):
    """Aggregate ticket demand into daily, weekly or monthly periods."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    if metric not in DEMAND_STABILITY_METRICS:
        raise ValueError(
            f"Unsupported demand metric: {metric}"
        )

    if frequency not in ["D", "W", "MS"]:
        raise ValueError(
            "Frequency must be D, W or MS."
        )

    indexed = dataframe.set_index(
        "Timestamp"
    ).sort_index()

    aggregated = indexed[metric].resample(
        frequency
    ).sum(min_count=1)

    result = aggregated.rename(
        "Demand"
    ).reset_index()

    result["Demand"] = pd.to_numeric(
        result["Demand"],
        errors="coerce",
    )

    return result


# ------------------------------------------------------------
# 42.3 â€” CALCULATE ROLLING STABILITY
# ------------------------------------------------------------

def calculate_demand_stability_rolling(
    aggregated_data,
    window=7,
):
    """Calculate rolling demand mean and standard deviation."""

    if aggregated_data is None or aggregated_data.empty:
        return pd.DataFrame()

    if window < 2:
        raise ValueError(
            "Rolling window must be at least 2."
        )

    result = aggregated_data.copy()

    result["Demand"] = pd.to_numeric(
        result["Demand"],
        errors="coerce",
    )

    result["Rolling Mean"] = (
        result["Demand"]
        .rolling(
            window=window,
            min_periods=window,
        )
        .mean()
    )

    result["Rolling Std"] = (
        result["Demand"]
        .rolling(
            window=window,
            min_periods=window,
        )
        .std()
    )

    result["Rolling Min"] = (
        result["Demand"]
        .rolling(
            window=window,
            min_periods=window,
        )
        .min()
    )

    result["Rolling Max"] = (
        result["Demand"]
        .rolling(
            window=window,
            min_periods=window,
        )
        .max()
    )

    result["Rolling Range"] = (
        result["Rolling Max"]
        - result["Rolling Min"]
    )

    result["Rolling CV Percentage"] = np.where(
        result["Rolling Mean"].abs() > 0,
        (
            result["Rolling Std"]
            / result["Rolling Mean"].abs()
        ) * 100,
        np.nan,
    )

    return result


# ------------------------------------------------------------
# 42.4 â€” SUMMARIZE DEMAND VOLATILITY
# ------------------------------------------------------------

def summarize_demand_stability(
    aggregated_data,
):
    """Summarize demand variability and stability."""

    if aggregated_data is None or aggregated_data.empty:
        return {}

    values = pd.to_numeric(
        aggregated_data["Demand"],
        errors="coerce",
    )

    values = values.replace(
        [np.inf, -np.inf],
        np.nan,
    ).dropna()

    if values.empty:
        return {}

    mean_demand = float(
        values.mean()
    )

    median_demand = float(
        values.median()
    )

    std_demand = float(
        values.std()
    ) if len(values) > 1 else 0.0

    minimum_demand = float(
        values.min()
    )

    maximum_demand = float(
        values.max()
    )

    cv_percentage = (
        std_demand / abs(mean_demand) * 100
        if mean_demand != 0
        else np.nan
    )

    return {
        "Period Count": int(len(values)),
        "Mean Demand": mean_demand,
        "Median Demand": median_demand,
        "Standard Deviation": std_demand,
        "Minimum Demand": minimum_demand,
        "Maximum Demand": maximum_demand,
        "Demand Range": maximum_demand - minimum_demand,
        "Coefficient of Variation Percentage": cv_percentage,
    }


# ------------------------------------------------------------
# 42.5 â€” CLASSIFY VOLATILITY
# ------------------------------------------------------------

def classify_demand_stability_volatility(
    aggregated_data,
    window=7,
):
    """
    Classify relative volatility using rolling CV.

    These thresholds are heuristic indicators, not
    statistically validated operational risk limits.
    """

    result = calculate_demand_stability_rolling(
        aggregated_data,
        window=window,
    )

    if result.empty:
        return result

    def classify_cv(value):
        if pd.isna(value):
            return "Insufficient History"

        if value < 10:
            return "Low Relative Volatility"

        if value < 25:
            return "Moderate Relative Volatility"

        return "High Relative Volatility"

    result["Volatility Category"] = (
        result["Rolling CV Percentage"].apply(
            classify_cv
        )
    )

    return result


# ------------------------------------------------------------
# 42.6 â€” IDENTIFY LARGE PERIOD-TO-PERIOD CHANGES
# ------------------------------------------------------------

def identify_demand_stability_changes(
    aggregated_data,
    change_threshold=25.0,
):
    """Identify large percentage changes between consecutive periods."""

    if aggregated_data is None or aggregated_data.empty:
        return pd.DataFrame()

    result = aggregated_data.copy()

    result["Demand"] = pd.to_numeric(
        result["Demand"],
        errors="coerce",
    )

    result["Previous Demand"] = (
        result["Demand"].shift(1)
    )

    result["Absolute Change"] = (
        result["Demand"]
        - result["Previous Demand"]
    )

    result["Percentage Change"] = np.where(
        result["Previous Demand"].abs() > 0,
        (
            result["Absolute Change"]
            / result["Previous Demand"].abs()
        ) * 100,
        np.nan,
    )

    result["Change Category"] = "Within Threshold"

    result.loc[
        result["Percentage Change"] >= change_threshold,
        "Change Category",
    ] = "Large Increase"

    result.loc[
        result["Percentage Change"] <= -change_threshold,
        "Change Category",
    ] = "Large Decrease"

    result.loc[
        result["Previous Demand"].isna(),
        "Change Category",
    ] = "No Previous Period"

    result.loc[
        (
            result["Previous Demand"].abs() == 0
        ) & (
            result["Demand"] > 0
        ),
        "Change Category",
    ] = "Increase From Zero"

    return result


# ------------------------------------------------------------
# 42.7 â€” CREATE STABILITY INSIGHTS
# ------------------------------------------------------------

def generate_demand_stability_insights(
    summary,
    stability_data,
    change_data,
):
    """Generate concise insights from calculated results."""

    insights = []

    if not summary:
        return [
            "Insufficient valid demand data for stability analysis."
        ]

    cv = summary.get(
        "Coefficient of Variation Percentage",
        np.nan,
    )

    if pd.notna(cv):
        if cv < 10:
            insights.append(
                "Historical demand variability is low relative "
                "to its average in the selected period."
            )
        elif cv < 25:
            insights.append(
                "Historical demand shows moderate relative "
                "variability."
            )
        else:
            insights.append(
                "Historical demand shows high relative "
                "variability and may require closer monitoring."
            )
    else:
        insights.append(
            "Relative variability cannot be calculated because "
            "the mean demand is zero or unavailable."
        )

    if (
        stability_data is not None
        and not stability_data.empty
        and "Volatility Category" in stability_data.columns
    ):
        valid_categories = stability_data[
            "Volatility Category"
        ]

        high_count = int(
            (
                valid_categories
                == "High Relative Volatility"
            ).sum()
        )

        if high_count:
            insights.append(
                f"{high_count:,} periods were classified as "
                "high relative volatility using the selected "
                "rolling window."
            )

    if (
        change_data is not None
        and not change_data.empty
        and "Change Category" in change_data.columns
    ):
        large_increases = int(
            (
                change_data["Change Category"]
                == "Large Increase"
            ).sum()
        )

        large_decreases = int(
            (
                change_data["Change Category"]
                == "Large Decrease"
            ).sum()
        )

        insights.append(
            f"Large period-to-period changes identified: "
            f"{large_increases} increases and "
            f"{large_decreases} decreases."
        )

    insights.append(
        "Historical variability alone does not identify its "
        "cause and does not confirm future demand."
    )

    return insights


