# 42.14 â€” MAIN STABILITY CENTER
# ------------------------------------------------------------

def render_demand_stability_intelligence_center(
    dataframe=None,
):
    """Main renderer for Part 42."""

    st.header(
        "Demand Stability & Volatility Intelligence Center"
    )

    st.markdown(
        """
        Analyze how historical ticket demand changes over time,
        how much it varies around its rolling average, and which
        periods show unusually large changes.
        """
    )

    if dataframe is None:
        try:
            dataset_path = DEFAULT_DATASET_PATH

            if not dataset_path.exists():
                st.error(
                    "The configured ticket dataset was not found."
                )
                return

            dataframe = load_ticket_dataframe(
                str(dataset_path)
            )

        except Exception as error:
            st.error(
                "Unable to load the ticket dataset."
            )

            st.caption(
                f"Details: {error}"
            )
            return

    prepared = prepare_demand_stability_data(
        dataframe
    )

    if prepared.empty:
        st.warning(
            "No usable demand data is available."
        )
        return

    control_col1, control_col2 = st.columns(2)

    with control_col1:
        selected_metric = st.selectbox(
            "Demand metric",
            DEMAND_STABILITY_METRICS,
            key="demand_stability_metric",
        )

    with control_col2:
        frequency_options = {
            "Daily": "D",
            "Weekly": "W",
            "Monthly": "MS",
        }

        frequency_label = st.selectbox(
            "Aggregation frequency",
            list(frequency_options.keys()),
            key="demand_stability_frequency",
        )

    selected_frequency = frequency_options[
        frequency_label
    ]

    if selected_frequency == "D":
        default_window = 7
        maximum_window = 90
    elif selected_frequency == "W":
        default_window = 4
        maximum_window = 52
    else:
        default_window = 3
        maximum_window = 24

    window = st.slider(
        "Rolling window size",
        min_value=2,
        max_value=maximum_window,
        value=default_window,
        key="demand_stability_window",
        help=(
            "Number of consecutive aggregated periods "
            "used for rolling calculations."
        ),
    )

    change_threshold = st.slider(
        "Large-change threshold (%)",
        min_value=5,
        max_value=100,
        value=25,
        step=5,
        key="demand_stability_change_threshold",
        help=(
            "Flags period-to-period percentage changes "
            "at or above this absolute threshold."
        ),
    )

    aggregated = aggregate_demand_stability_data(
        prepared,
        metric=selected_metric,
        frequency=selected_frequency,
    )

    if aggregated.empty:
        st.warning(
            "Demand aggregation returned no usable observations."
        )
        return

    summary = summarize_demand_stability(
        aggregated
    )

    stability_data = classify_demand_stability_volatility(
        aggregated,
        window=window,
    )

    change_data = identify_demand_stability_changes(
        aggregated,
        change_threshold=float(change_threshold),
    )

    insights = generate_demand_stability_insights(
        summary,
        stability_data,
        change_data,
    )

    render_demand_stability_overview(
        summary
    )

    st.divider()

    render_demand_stability_chart(
        stability_data
    )

    st.divider()

    render_demand_stability_volatility_chart(
        stability_data
    )

    st.divider()

    render_demand_stability_change_analysis(
        change_data
    )

    st.divider()

    render_demand_stability_insight_panel(
        insights
    )

    st.divider()

    with st.expander(
        "Methodology and Limitations"
    ):
        st.markdown(
            """
            **Rolling mean:** average demand across the selected
            number of consecutive periods.

            **Rolling standard deviation:** measures variation
            within each rolling window.

            **Coefficient of variation:** standard deviation
            divided by the absolute mean, expressed as a percentage.

            **Period change:** compares each period with the
            immediately preceding aggregated period.

            The low, moderate and high volatility thresholds are
            heuristic categories. They have not been validated
            against ferry capacity or operational outcomes.

            Large changes identify periods worth investigating;
            they do not establish the reason for the change.
            Missing periods are not automatically confirmed
            zero-demand periods.
            """
        )

    st.divider()

    render_demand_stability_exports(
        stability_data=stability_data,
        change_data=change_data,
        summary=summary,
    )

    st.caption(
        "Demand Stability Intelligence Center "
        f"v{DEMAND_STABILITY_VERSION}"
    )


