# >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
# PART 43 START
# DEMAND TREND & GROWTH ANALYSIS INTELLIGENCE CENTER
# >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

DEMAND_GROWTH_ANALYSIS_VERSION = "1.0.0"

DEMAND_GROWTH_ANALYSIS_METRICS = [
    "Sales Count",
    "Redemption Count",
]


# ------------------------------------------------------------
# 43.1 â€” PREPARE SOURCE DATA
# ------------------------------------------------------------

def prepare_demand_growth_analysis_data(dataframe):
    """Validate and prepare historical ticket demand."""

    required_columns = [
        "Timestamp",
        "Sales Count",
        "Redemption Count",
    ]

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    if any(
        column not in dataframe.columns
        for column in required_columns
    ):
        return pd.DataFrame()

    result = dataframe[
        required_columns
    ].copy()

    result["Timestamp"] = pd.to_datetime(
        result["Timestamp"],
        errors="coerce",
    )

    for column in DEMAND_GROWTH_ANALYSIS_METRICS:
        result[column] = pd.to_numeric(
            result[column],
            errors="coerce",
        )

    result = result.replace(
        [np.inf, -np.inf],
        np.nan,
    )

    result = result.dropna(
        subset=["Timestamp"]
    )

    result = result.sort_values(
        "Timestamp"
    ).reset_index(drop=True)

    return result


# ------------------------------------------------------------
# 43.2 â€” AGGREGATE DEMAND BY PERIOD
# ------------------------------------------------------------

def aggregate_demand_growth_analysis_data(
    dataframe,
    metric="Sales Count",
    frequency="D",
):
    """Aggregate demand into daily, weekly or monthly periods."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    if metric not in DEMAND_GROWTH_ANALYSIS_METRICS:
        raise ValueError(
            f"Unsupported demand metric: {metric}"
        )

    if frequency not in ["D", "W", "MS"]:
        raise ValueError(
            "Frequency must be D, W or MS."
        )

    indexed = dataframe.set_index(
        "Timestamp"
    ).sort_index()

    aggregated = indexed[metric].resample(
        frequency
    ).sum(min_count=1)

    result = aggregated.rename(
        "Demand"
    ).reset_index()

    result["Demand"] = pd.to_numeric(
        result["Demand"],
        errors="coerce",
    )

    return result


# ------------------------------------------------------------
# 43.3 â€” CALCULATE PERIOD-TO-PERIOD GROWTH
# ------------------------------------------------------------

def calculate_demand_growth_rates(
    aggregated_data,
):
    """Calculate absolute and percentage demand changes."""

    if aggregated_data is None or aggregated_data.empty:
        return pd.DataFrame()

    result = aggregated_data.copy()

    result["Demand"] = pd.to_numeric(
        result["Demand"],
        errors="coerce",
    )

    result["Previous Demand"] = (
        result["Demand"].shift(1)
    )

    result["Absolute Change"] = (
        result["Demand"]
        - result["Previous Demand"]
    )

    previous = result["Previous Demand"]

    result["Growth Percentage"] = np.where(
        previous.abs() > 0,
        (
            result["Absolute Change"]
            / previous.abs()
        ) * 100,
        np.nan,
    )

    result["Growth Direction"] = "Unchanged"

    result.loc[
        result["Absolute Change"] > 0,
        "Growth Direction",
    ] = "Increase"

    result.loc[
        result["Absolute Change"] < 0,
        "Growth Direction",
    ] = "Decrease"

    result.loc[
        result["Previous Demand"].isna(),
        "Growth Direction",
    ] = "No Previous Period"

    result.loc[
        (
            result["Previous Demand"] == 0
        ) & (
            result["Demand"] > 0
        ),
        "Growth Direction",
    ] = "Increase From Zero"

    result.loc[
        (
            result["Previous Demand"] == 0
        ) & (
            result["Demand"] == 0
        ),
        "Growth Direction",
    ] = "Zero Demand"

    return result


# ------------------------------------------------------------
# 43.4 â€” CALCULATE ROLLING TREND
# ------------------------------------------------------------

def calculate_demand_growth_rolling_trend(
    aggregated_data,
    window=7,
):
    """Calculate rolling demand average and change."""

    if aggregated_data is None or aggregated_data.empty:
        return pd.DataFrame()

    if window < 2:
        raise ValueError(
            "Rolling window must be at least 2."
        )

    result = aggregated_data.copy()

    result["Demand"] = pd.to_numeric(
        result["Demand"],
        errors="coerce",
    )

    result["Rolling Average"] = (
        result["Demand"]
        .rolling(
            window=window,
            min_periods=window,
        )
        .mean()
    )

    result["Previous Rolling Average"] = (
        result["Rolling Average"].shift(1)
    )

    result["Rolling Trend Change"] = (
        result["Rolling Average"]
        - result["Previous Rolling Average"]
    )

    result["Rolling Trend Change Percentage"] = np.where(
        result["Previous Rolling Average"].abs() > 0,
        (
            result["Rolling Trend Change"]
            / result["Previous Rolling Average"].abs()
        ) * 100,
        np.nan,
    )

    result["Trend Direction"] = "Stable"

    result.loc[
        result["Rolling Trend Change"] > 0,
        "Trend Direction",
    ] = "Increasing"

    result.loc[
        result["Rolling Trend Change"] < 0,
        "Trend Direction",
    ] = "Decreasing"

    result.loc[
        result["Rolling Average"].isna(),
        "Trend Direction",
    ] = "Insufficient History"

    return result


# ------------------------------------------------------------
# 43.5 â€” CALCULATE PERIODIC GROWTH SUMMARY
# ------------------------------------------------------------

def summarize_demand_growth(
    growth_data,
):
    """Summarize historical growth and demand changes."""

    if growth_data is None or growth_data.empty:
        return {}

    values = pd.to_numeric(
        growth_data["Demand"],
        errors="coerce",
    )

    values = values.replace(
        [np.inf, -np.inf],
        np.nan,
    ).dropna()

    if values.empty:
        return {}

    first_demand = float(
        values.iloc[0]
    )

    last_demand = float(
        values.iloc[-1]
    )

    total_change = (
        last_demand - first_demand
    )

    if first_demand != 0:
        overall_change_percentage = (
            total_change
            / abs(first_demand)
        ) * 100
    else:
        overall_change_percentage = np.nan

    valid_growth = pd.to_numeric(
        growth_data["Growth Percentage"],
        errors="coerce",
    ).replace(
        [np.inf, -np.inf],
        np.nan,
    ).dropna()

    increase_count = int(
        (
            growth_data["Growth Direction"]
            == "Increase"
        ).sum()
    )

    decrease_count = int(
        (
            growth_data["Growth Direction"]
            == "Decrease"
        ).sum()
    )

    return {
        "Observed Periods": int(len(values)),
        "First Observed Demand": first_demand,
        "Latest Observed Demand": last_demand,
        "Overall Absolute Change": float(total_change),
        "Overall Change Percentage": float(
            overall_change_percentage
        ) if pd.notna(overall_change_percentage) else np.nan,
        "Average Period Demand": float(values.mean()),
        "Median Period Demand": float(values.median()),
        "Largest Period Demand": float(values.max()),
        "Smallest Period Demand": float(values.min()),
        "Average Valid Period Growth Percentage": float(
            valid_growth.mean()
        ) if not valid_growth.empty else np.nan,
        "Periods With Increase": increase_count,
        "Periods With Decrease": decrease_count,
    }


# ------------------------------------------------------------
# 43.6 â€” IDENTIFY STRONG GROWTH OR DECLINE PERIODS
# ------------------------------------------------------------

def identify_demand_growth_extremes(
    growth_data,
    threshold_percentage=25.0,
):
    """Identify periods with large percentage changes."""

    if growth_data is None or growth_data.empty:
        return pd.DataFrame()

    result = growth_data.copy()

    result["Growth Event"] = "Ordinary Change"

    result.loc[
        result["Growth Percentage"] >= threshold_percentage,
        "Growth Event",
    ] = "Strong Increase"

    result.loc[
        result["Growth Percentage"] <= -threshold_percentage,
        "Growth Event",
    ] = "Strong Decrease"

    result.loc[
        result["Growth Direction"] == "No Previous Period",
        "Growth Event",
    ] = "First Period"

    result.loc[
        result["Growth Direction"] == "Increase From Zero",
        "Growth Event",
    ] = "Increase From Zero"

    result.loc[
        result["Growth Direction"] == "Zero Demand",
        "Growth Event",
    ] = "Zero Demand"

    return result


# ------------------------------------------------------------
# 43.7 â€” GENERATE GROWTH INSIGHTS
# ------------------------------------------------------------

def generate_demand_growth_insights(
    summary,
    growth_data,
    rolling_data,
    extreme_data,
):
    """Generate data-driven summaries without inventing causes."""

    insights = []

    if not summary:
        return [
            "Insufficient data for growth analysis."
        ]

    overall_change = summary.get(
        "Overall Change Percentage",
        np.nan,
    )

    if pd.notna(overall_change):
        if overall_change > 0:
            insights.append(
                f"Demand at the final observed period is "
                f"{overall_change:,.2f}% higher than at the "
                "first observed period."
            )
        elif overall_change < 0:
            insights.append(
                f"Demand at the final observed period is "
                f"{abs(overall_change):,.2f}% lower than at the "
                "first observed period."
            )
        else:
            insights.append(
                "The first and final observed periods have "
                "the same demand value."
            )
    else:
        insights.append(
            "Overall percentage change cannot be calculated "
            "because the first observed demand is zero."
        )

    if (
        rolling_data is not None
        and not rolling_data.empty
    ):
        valid_trend = rolling_data[
            rolling_data["Trend Direction"].isin([
                "Increasing",
                "Decreasing",
                "Stable",
            ])
        ]

        if not valid_trend.empty:
            latest_trend = valid_trend.iloc[-1][
                "Trend Direction"
            ]

            insights.append(
                f"The latest calculated rolling trend is "
                f"{latest_trend.lower()}."
            )

    if (
        extreme_data is not None
        and not extreme_data.empty
    ):
        strong_increases = int(
            (
                extreme_data["Growth Event"]
                == "Strong Increase"
            ).sum()
        )

        strong_decreases = int(
            (
                extreme_data["Growth Event"]
                == "Strong Decrease"
            ).sum()
        )

        insights.append(
            f"Periods crossing the configured growth threshold: "
            f"{strong_increases} strong increases and "
            f"{strong_decreases} strong decreases."
        )

    insights.append(
        "Historical growth does not prove that the same "
        "trend will continue in future periods."
    )

    return insights


