def render_demand_growth_trend_chart(
    aggregated_data,
    rolling_data,
):
    """Visualize observed demand and its rolling average."""

    if aggregated_data is None or aggregated_data.empty:
        return

    chart_data = aggregated_data[
        ["Timestamp", "Demand"]
    ].copy()

    if (
        rolling_data is not None
        and not rolling_data.empty
    ):
        rolling_subset = rolling_data[
            ["Timestamp", "Rolling Average"]
        ].copy()

        chart_data = chart_data.merge(
            rolling_subset,
            on="Timestamp",
            how="left",
        )

    chart_data = chart_data.set_index(
        "Timestamp"
    )

    st.subheader(
        "Historical Demand Trend"
    )

    st.line_chart(
        chart_data,
        use_container_width=True,
    )

    st.caption(
        "The rolling average summarizes past observations; "
        "it is not a future forecast."
    )


