# ------------------------------------------------------------
# 43.14 â€” MAIN GROWTH ANALYSIS CENTER
# ------------------------------------------------------------

def render_demand_growth_analysis_center(
    dataframe=None,
):
    """Main renderer for Part 43."""

    st.header(
        "Demand Trend & Growth Analysis Center"
    )

    st.markdown(
        """
        Explore historical demand growth, period-to-period
        changes, rolling trends and significant increases
        or decreases.
        """
    )

    if dataframe is None:
        try:
            dataset_path = DEFAULT_DATASET_PATH

            if not dataset_path.exists():
                st.error(
                    "The configured ticket dataset was not found."
                )
                return

            dataframe = load_ticket_dataframe(
                str(dataset_path)
            )

        except Exception as error:
            st.error(
                "Unable to load the ticket dataset."
            )

            st.caption(
                f"Details: {error}"
            )
            return

    prepared = prepare_demand_growth_analysis_data(
        dataframe
    )

    if prepared.empty:
        st.warning(
            "No usable ticket demand data is available."
        )
        return

    control_col1, control_col2 = st.columns(2)

    with control_col1:
        selected_metric = st.selectbox(
            "Demand metric",
            DEMAND_GROWTH_ANALYSIS_METRICS,
            key="demand_growth_metric",
        )

    with control_col2:
        frequency_options = {
            "Daily": "D",
            "Weekly": "W",
            "Monthly": "MS",
        }

        frequency_label = st.selectbox(
            "Aggregation frequency",
            list(frequency_options.keys()),
            key="demand_growth_frequency",
        )

    selected_frequency = frequency_options[
        frequency_label
    ]

    if selected_frequency == "D":
        default_window = 7
        maximum_window = 90
    elif selected_frequency == "W":
        default_window = 4
        maximum_window = 52
    else:
        default_window = 3
        maximum_window = 24

    window = st.slider(
        "Rolling trend window",
        min_value=2,
        max_value=maximum_window,
        value=default_window,
        key="demand_growth_window",
    )

    threshold_percentage = st.slider(
        "Significant growth threshold (%)",
        min_value=5,
        max_value=100,
        value=25,
        step=5,
        key="demand_growth_threshold",
    )

    aggregated = aggregate_demand_growth_analysis_data(
        prepared,
        metric=selected_metric,
        frequency=selected_frequency,
    )

    if aggregated.empty:
        st.warning(
            "No aggregated demand data is available."
        )
        return

    growth_data = calculate_demand_growth_rates(
        aggregated
    )

    rolling_data = calculate_demand_growth_rolling_trend(
        aggregated,
        window=window,
    )

    extreme_data = identify_demand_growth_extremes(
        growth_data,
        threshold_percentage=float(
            threshold_percentage
        ),
    )

    summary = summarize_demand_growth(
        growth_data
    )

    insights = generate_demand_growth_insights(
        summary,
        growth_data,
        rolling_data,
        extreme_data,
    )

    render_demand_growth_overview(
        summary
    )

    st.divider()

    render_demand_growth_trend_chart(
        aggregated,
        rolling_data,
    )

    st.divider()

    render_demand_growth_change_chart(
        growth_data
    )

    st.divider()

    render_demand_growth_extremes(
        extreme_data
    )

    st.divider()

    render_demand_growth_insight_panel(
        insights
    )

    st.divider()

    with st.expander(
        "Methodology and Limitations"
    ):
        st.markdown(
            """
            **Absolute change:** current period demand minus
            previous period demand.

            **Growth percentage:** absolute change divided
            by the absolute previous-period demand.

            **Rolling average:** average demand over the
            selected number of consecutive periods.

            **Significant changes:** periods whose percentage
            change crosses the user-selected threshold.

            When the previous period is zero, percentage
            growth is undefined and is not calculated.

            The first and final observed values may belong to
            partial calendar periods. Overall change compares
            those observed period totals; it is not an annual
            growth rate or a causal explanation.

            Historical patterns do not guarantee future demand.
            """
        )

    st.divider()

    render_demand_growth_exports(
        growth_data=growth_data,
        rolling_data=rolling_data,
        extreme_data=extreme_data,
        summary=summary,
    )

    st.caption(
        "Demand Growth Analysis Center "
        f"v{DEMAND_GROWTH_ANALYSIS_VERSION}"
    )


