DEMAND_PEAK_PLANNING_VERSION = "1.0.0"

DEMAND_PEAK_PLANNING_METRICS = [
    "Sales Count",
    "Redemption Count",
]


# ------------------------------------------------------------
# 44.1 â€” PREPARE SOURCE DATA
# ------------------------------------------------------------

def prepare_demand_peak_planning_data(dataframe):
    """Validate and prepare historical ticket demand."""

    required_columns = [
        "Timestamp",
        "Sales Count",
        "Redemption Count",
    ]

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    if any(
        column not in dataframe.columns
        for column in required_columns
    ):
        return pd.DataFrame()

    result = dataframe[required_columns].copy()

    result["Timestamp"] = pd.to_datetime(
        result["Timestamp"],
        errors="coerce",
    )

    for column in DEMAND_PEAK_PLANNING_METRICS:
        result[column] = pd.to_numeric(
            result[column],
            errors="coerce",
        )

    result = result.replace(
        [np.inf, -np.inf],
        np.nan,
    )

    result = result.dropna(
        subset=["Timestamp"]
    )

    return result.sort_values(
        "Timestamp"
    ).reset_index(drop=True)


# ------------------------------------------------------------
# 44.2 â€” AGGREGATE DEMAND
# ------------------------------------------------------------

def aggregate_demand_peak_planning_data(
    dataframe,
    metric="Sales Count",
    frequency="D",
):
    """Aggregate demand into daily, weekly or monthly periods."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    if metric not in DEMAND_PEAK_PLANNING_METRICS:
        raise ValueError(
            f"Unsupported demand metric: {metric}"
        )

    if frequency not in ["D", "W", "MS"]:
        raise ValueError(
            "Frequency must be D, W or MS."
        )

    indexed = dataframe.set_index(
        "Timestamp"
    ).sort_index()

    aggregated = indexed[metric].resample(
        frequency
    ).sum(min_count=1)

    return aggregated.rename(
        "Demand"
    ).reset_index()


# ------------------------------------------------------------
# 44.3 â€” IDENTIFY PEAK AND LOW PERIODS
# ------------------------------------------------------------

def identify_demand_peak_periods(
    aggregated_data,
    peak_percentile=90,
    low_percentile=10,
):
    """Classify observed periods using demand percentiles."""

    if aggregated_data is None or aggregated_data.empty:
        return pd.DataFrame()

    if not 0 <= low_percentile < peak_percentile <= 100:
        raise ValueError(
            "Percentiles must satisfy "
            "0 <= low < peak <= 100."
        )

    result = aggregated_data.copy()

    result["Demand"] = pd.to_numeric(
        result["Demand"],
        errors="coerce",
    )

    valid_values = result["Demand"].dropna()

    if valid_values.empty:
        return pd.DataFrame()

    peak_threshold = float(
        valid_values.quantile(
            peak_percentile / 100
        )
    )

    low_threshold = float(
        valid_values.quantile(
            low_percentile / 100
        )
    )

    result["Peak Threshold"] = peak_threshold
    result["Low Threshold"] = low_threshold

    result["Demand Classification"] = "Typical"

    result.loc[
        result["Demand"] >= peak_threshold,
        "Demand Classification",
    ] = "Peak"

    result.loc[
        result["Demand"] <= low_threshold,
        "Demand Classification",
    ] = "Low"

    result.loc[
        result["Demand"].isna(),
        "Demand Classification",
    ] = "Unavailable"

    return result


# ------------------------------------------------------------
# 44.4 â€” ANALYZE WEEKDAY PATTERNS
# ------------------------------------------------------------

def calculate_demand_peak_weekday_profile(
    dataframe,
    metric="Sales Count",
):
    """Summarize historical demand by weekday."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    if metric not in DEMAND_PEAK_PLANNING_METRICS:
        return pd.DataFrame()

    result = dataframe[
        ["Timestamp", metric]
    ].copy()

    result[metric] = pd.to_numeric(
        result[metric],
        errors="coerce",
    )

    result = result.dropna(
        subset=["Timestamp", metric]
    )

    if result.empty:
        return pd.DataFrame()

    result["Weekday Number"] = (
        result["Timestamp"].dt.dayofweek
    )

    result["Weekday"] = (
        result["Timestamp"].dt.day_name()
    )

    profile = result.groupby(
        ["Weekday Number", "Weekday"],
        as_index=False,
    ).agg(
        Mean_Demand=(metric, "mean"),
        Median_Demand=(metric, "median"),
        Total_Demand=(metric, "sum"),
        Observation_Count=(metric, "count"),
    )

    return profile.sort_values(
        "Weekday Number"
    ).reset_index(drop=True)


# ------------------------------------------------------------
# 44.5 â€” ANALYZE MONTH PATTERNS
# ------------------------------------------------------------

def calculate_demand_peak_month_profile(
    dataframe,
    metric="Sales Count",
):
    """Summarize historical demand by calendar month."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    if metric not in DEMAND_PEAK_PLANNING_METRICS:
        return pd.DataFrame()

    result = dataframe[
        ["Timestamp", metric]
    ].copy()

    result[metric] = pd.to_numeric(
        result[metric],
        errors="coerce",
    )

    result = result.dropna(
        subset=["Timestamp", metric]
    )

    if result.empty:
        return pd.DataFrame()

    result["Month Number"] = (
        result["Timestamp"].dt.month
    )

    result["Month"] = (
        result["Timestamp"].dt.month_name()
    )

    profile = result.groupby(
        ["Month Number", "Month"],
        as_index=False,
    ).agg(
        Mean_Demand=(metric, "mean"),
        Median_Demand=(metric, "median"),
        Total_Demand=(metric, "sum"),
        Observation_Count=(metric, "count"),
    )

    return profile.sort_values(
        "Month Number"
    ).reset_index(drop=True)


# ------------------------------------------------------------
# 44.6 â€” ANALYZE YEAR-OVER-YEAR DATA
# ------------------------------------------------------------

def calculate_demand_peak_year_profile(
    dataframe,
    metric="Sales Count",
):
    """Summarize available data by calendar year."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    if metric not in DEMAND_PEAK_PLANNING_METRICS:
        return pd.DataFrame()

    result = dataframe[
        ["Timestamp", metric]
    ].copy()

    result[metric] = pd.to_numeric(
        result[metric],
        errors="coerce",
    )

    result = result.dropna(
        subset=["Timestamp", metric]
    )

    if result.empty:
        return pd.DataFrame()

    result["Year"] = (
        result["Timestamp"].dt.year
    )

    profile = result.groupby(
        "Year",
        as_index=False,
    ).agg(
        Total_Demand=(metric, "sum"),
        Mean_Observed_Value=(metric, "mean"),
        Median_Observed_Value=(metric, "median"),
        Observation_Count=(metric, "count"),
        First_Observed_Date=("Timestamp", "min"),
        Last_Observed_Date=("Timestamp", "max"),
    )

    return profile.sort_values(
        "Year"
    ).reset_index(drop=True)


# ------------------------------------------------------------
# 44.7 â€” BUILD PLANNING RECOMMENDATIONS
# ------------------------------------------------------------

def build_demand_peak_planning_recommendations(
    peak_data,
    weekday_profile,
    month_profile,
):
    """Generate recommendations based on observed demand patterns."""

    recommendations = []

    if peak_data is not None and not peak_data.empty:
        peak_count = int(
            (
                peak_data["Demand Classification"]
                == "Peak"
            ).sum()
        )

        low_count = int(
            (
                peak_data["Demand Classification"]
                == "Low"
            ).sum()
        )

        recommendations.append(
            f"{peak_count} observed periods fall within the "
            "selected upper demand percentile."
        )

        recommendations.append(
            f"{low_count} observed periods fall within the "
            "selected lower demand percentile."
        )

    if (
        weekday_profile is not None
        and not weekday_profile.empty
    ):
        valid_weekdays = weekday_profile.dropna(
            subset=["Mean_Demand"]
        )

        if not valid_weekdays.empty:
            busiest = valid_weekdays.loc[
                valid_weekdays["Mean_Demand"].idxmax()
            ]

            quietest = valid_weekdays.loc[
                valid_weekdays["Mean_Demand"].idxmin()
            ]

            recommendations.append(
                f"{busiest['Weekday']} has the highest mean "
                "observed demand among weekdays in this dataset."
            )

            recommendations.append(
                f"{quietest['Weekday']} has the lowest mean "
                "observed demand among weekdays in this dataset."
            )

    if (
        month_profile is not None
        and not month_profile.empty
    ):
        valid_months = month_profile.dropna(
            subset=["Mean_Demand"]
        )

        if not valid_months.empty:
            busiest_month = valid_months.loc[
                valid_months["Mean_Demand"].idxmax()
            ]

            recommendations.append(
                f"{busiest_month['Month']} has the highest mean "
                "observed value among represented calendar months."
            )

    recommendations.append(
        "Use these patterns as inputs to planning discussions; "
        "validate them against service schedules, holidays, "
        "weather, capacity and operational records before acting."
    )

    return recommendations


