# ------------------------------------------------------------
# 44.14 â€” MAIN PEAK PLANNING CENTER
# ------------------------------------------------------------

def render_demand_peak_planning_center(
    dataframe=None,
):
    """Main renderer for Part 44."""

    st.header(
        "Demand Peak Period & Seasonal Planning Center"
    )

    st.markdown(
        """
        Examine historically high and low demand periods,
        weekday patterns, calendar-month profiles and
        year-level demand summaries.
        """
    )

    if dataframe is None:
        try:
            dataset_path = DEFAULT_DATASET_PATH

            if not dataset_path.exists():
                st.error(
                    "The configured ticket dataset was not found."
                )
                return

            dataframe = load_ticket_dataframe(
                str(dataset_path)
            )

        except Exception as error:
            st.error(
                "Unable to load the ticket dataset."
            )

            st.caption(
                f"Details: {error}"
            )
            return

    prepared = prepare_demand_peak_planning_data(
        dataframe
    )

    if prepared.empty:
        st.warning(
            "No usable ticket demand data is available."
        )
        return

    col1, col2 = st.columns(2)

    with col1:
        selected_metric = st.selectbox(
            "Demand metric",
            DEMAND_PEAK_PLANNING_METRICS,
            key="demand_peak_planning_metric",
        )

    with col2:
        frequency_options = {
            "Daily": "D",
            "Weekly": "W",
            "Monthly": "MS",
        }

        frequency_label = st.selectbox(
            "Peak-period aggregation",
            list(frequency_options.keys()),
            key="demand_peak_planning_frequency",
        )

    selected_frequency = frequency_options[
        frequency_label
    ]

    peak_percentile = st.slider(
        "Peak percentile",
        min_value=70,
        max_value=99,
        value=90,
        step=1,
        key="demand_peak_percentile",
    )

    low_percentile = st.slider(
        "Low-demand percentile",
        min_value=1,
        max_value=30,
        value=10,
        step=1,
        key="demand_low_percentile",
    )

    if low_percentile >= peak_percentile:
        st.warning(
            "The low-demand percentile must be lower "
            "than the peak percentile."
        )
        return

    aggregated = aggregate_demand_peak_planning_data(
        prepared,
        metric=selected_metric,
        frequency=selected_frequency,
    )

    if aggregated.empty:
        st.warning(
            "No aggregated demand observations are available."
        )
        return

    peak_data = identify_demand_peak_periods(
        aggregated,
        peak_percentile=peak_percentile,
        low_percentile=low_percentile,
    )

    weekday_profile = calculate_demand_peak_weekday_profile(
        prepared,
        metric=selected_metric,
    )

    month_profile = calculate_demand_peak_month_profile(
        prepared,
        metric=selected_metric,
    )

    year_profile = calculate_demand_peak_year_profile(
        prepared,
        metric=selected_metric,
    )

    recommendations = build_demand_peak_planning_recommendations(
        peak_data,
        weekday_profile,
        month_profile,
    )

    render_demand_peak_period_overview(
        peak_data
    )

    st.divider()

    render_demand_peak_weekday_analysis(
        weekday_profile
    )

    st.divider()

    render_demand_peak_month_analysis(
        month_profile
    )

    st.divider()

    render_demand_peak_year_analysis(
        year_profile
    )

    st.divider()

    render_demand_peak_planning_recommendations(
        recommendations
    )

    st.divider()

    with st.expander(
        "Methodology and Limitations"
    ):
        st.markdown(
            """
            **Peak periods:** periods at or above the selected
            upper demand percentile.

            **Low periods:** periods at or below the selected
            lower demand percentile.

            **Weekday profile:** summarizes the observed values
            associated with each weekday.

            **Calendar-month profile:** summarizes observations
            grouped by month name across the available years.

            **Year profile:** summarizes available observations
            within each calendar year.

            Month and weekday averages can be affected by partial
            coverage, missing records, holidays and operational
            schedules. Peak classification is relative to the
            selected historical dataset, not to verified vessel
            capacity or passenger limits.

            These results support investigation and planning;
            they do not automatically establish the cause of peaks
            or prove that future demand will follow the same pattern.
            """
        )

    st.divider()

    render_demand_peak_planning_exports(
        peak_data=peak_data,
        weekday_profile=weekday_profile,
        month_profile=month_profile,
        year_profile=year_profile,
    )

    st.caption(
        "Demand Peak Planning Intelligence Center "
        f"v{DEMAND_PEAK_PLANNING_VERSION}"
    )


