DEMAND_DISTRIBUTION_INTELLIGENCE_VERSION = "1.0.0"

DEMAND_DISTRIBUTION_INTELLIGENCE_METRICS = [
    "Sales Count",
    "Redemption Count",
]


# ------------------------------------------------------------
# 45.1 â€” PREPARE DATA
# ------------------------------------------------------------

def prepare_demand_distribution_intelligence_data(dataframe):
    """Validate and prepare ticket demand for statistical analysis."""

    required_columns = [
        "Timestamp",
        "Sales Count",
        "Redemption Count",
    ]

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    if not all(
        column in dataframe.columns
        for column in required_columns
    ):
        return pd.DataFrame()

    result = dataframe[required_columns].copy()

    result["Timestamp"] = pd.to_datetime(
        result["Timestamp"],
        errors="coerce",
    )

    for column in DEMAND_DISTRIBUTION_INTELLIGENCE_METRICS:
        result[column] = pd.to_numeric(
            result[column],
            errors="coerce",
        )

    result = result.replace(
        [np.inf, -np.inf],
        np.nan,
    )

    result = result.dropna(
        subset=["Timestamp"]
    )

    return result.sort_values(
        "Timestamp"
    ).reset_index(drop=True)


# ------------------------------------------------------------
# 45.2 â€” CALCULATE STATISTICAL SUMMARY
# ------------------------------------------------------------

def calculate_demand_distribution_statistics(
    dataframe,
    metric="Sales Count",
):
    """Calculate descriptive statistics for the selected metric."""

    if dataframe is None or dataframe.empty:
        return {}

    if metric not in DEMAND_DISTRIBUTION_INTELLIGENCE_METRICS:
        return {}

    values = pd.to_numeric(
        dataframe[metric],
        errors="coerce",
    ).replace(
        [np.inf, -np.inf],
        np.nan,
    ).dropna()

    if values.empty:
        return {}

    statistics = {
        "Observation Count": int(values.count()),
        "Total": float(values.sum()),
        "Mean": float(values.mean()),
        "Median": float(values.median()),
        "Minimum": float(values.min()),
        "Maximum": float(values.max()),
        "Standard Deviation": float(values.std()),
        "Variance": float(values.var()),
        "25th Percentile": float(values.quantile(0.25)),
        "50th Percentile": float(values.quantile(0.50)),
        "75th Percentile": float(values.quantile(0.75)),
        "90th Percentile": float(values.quantile(0.90)),
        "95th Percentile": float(values.quantile(0.95)),
        "99th Percentile": float(values.quantile(0.99)),
        "Skewness": float(values.skew()),
    }

    return statistics


# ------------------------------------------------------------
# 45.3 â€” CREATE DEMAND DISTRIBUTION BINS
# ------------------------------------------------------------

def calculate_demand_distribution_bins(
    dataframe,
    metric="Sales Count",
    bin_count=20,
):
    """Group numeric demand observations into histogram bins."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    if metric not in DEMAND_DISTRIBUTION_INTELLIGENCE_METRICS:
        return pd.DataFrame()

    values = pd.to_numeric(
        dataframe[metric],
        errors="coerce",
    ).replace(
        [np.inf, -np.inf],
        np.nan,
    ).dropna()

    if values.empty:
        return pd.DataFrame()

    if bin_count < 2 or bin_count > 100:
        raise ValueError(
            "Bin count must be between 2 and 100."
        )

    if values.nunique() == 1:
        return pd.DataFrame({
            "Bin Start": [float(values.iloc[0])],
            "Bin End": [float(values.iloc[0])],
            "Observation Count": [int(len(values))],
        })

    counts, edges = np.histogram(
        values.to_numpy(),
        bins=bin_count,
    )

    return pd.DataFrame({
        "Bin Start": edges[:-1],
        "Bin End": edges[1:],
        "Observation Count": counts,
    })


# ------------------------------------------------------------
# 45.4 â€” DETECT IQR-BASED EXTREME OBSERVATIONS
# ------------------------------------------------------------

def identify_demand_distribution_outliers(
    dataframe,
    metric="Sales Count",
    iqr_multiplier=1.5,
):
    """Flag observations outside the IQR-based statistical bounds."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    if metric not in DEMAND_DISTRIBUTION_INTELLIGENCE_METRICS:
        return pd.DataFrame()

    result = dataframe[
        ["Timestamp", metric]
    ].copy()

    result[metric] = pd.to_numeric(
        result[metric],
        errors="coerce",
    )

    result = result.replace(
        [np.inf, -np.inf],
        np.nan,
    ).dropna(
        subset=["Timestamp", metric]
    )

    if result.empty:
        return pd.DataFrame()

    q1 = float(
        result[metric].quantile(0.25)
    )

    q3 = float(
        result[metric].quantile(0.75)
    )

    iqr = q3 - q1

    lower_bound = q1 - (
        iqr_multiplier * iqr
    )

    upper_bound = q3 + (
        iqr_multiplier * iqr
    )

    result["Lower Bound"] = lower_bound
    result["Upper Bound"] = upper_bound

    result["Extreme Observation"] = (
        (result[metric] < lower_bound)
        | (result[metric] > upper_bound)
    )

    result["Deviation From Median"] = (
        result[metric] - result[metric].median()
    )

    result["Absolute Deviation"] = (
        result["Deviation From Median"].abs()
    )

    return result.sort_values(
        "Absolute Deviation",
        ascending=False,
    ).reset_index(drop=True)


# ------------------------------------------------------------
# 45.5 â€” COMPARE SALES AND REDEMPTION DISTRIBUTIONS
# ------------------------------------------------------------

def compare_demand_distribution_metrics(dataframe):
    """Compare descriptive statistics for both demand columns."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    rows = []

    for metric in DEMAND_DISTRIBUTION_INTELLIGENCE_METRICS:
        statistics = calculate_demand_distribution_statistics(
            dataframe,
            metric=metric,
        )

        if statistics:
            rows.append({
                "Metric": metric,
                **statistics,
            })

    return pd.DataFrame(rows)


# ------------------------------------------------------------
# 45.6 â€” CALCULATE DAILY DISTRIBUTION
# ------------------------------------------------------------

def calculate_daily_demand_distribution(
    dataframe,
    metric="Sales Count",
):
    """Aggregate observations to daily totals before distribution analysis."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    if metric not in DEMAND_DISTRIBUTION_INTELLIGENCE_METRICS:
        return pd.DataFrame()

    result = dataframe[
        ["Timestamp", metric]
    ].copy()

    result[metric] = pd.to_numeric(
        result[metric],
        errors="coerce",
    )

    result = result.dropna(
        subset=["Timestamp"]
    )

    if result.empty:
        return pd.DataFrame()

    result = result.set_index(
        "Timestamp"
    ).sort_index()

    daily = result[metric].resample(
        "D"
    ).sum(min_count=1)

    return daily.rename(
        "Daily Demand"
    ).reset_index()


