# ------------------------------------------------------------
# 45.14 â€” MAIN DISTRIBUTION INTELLIGENCE CENTER
# ------------------------------------------------------------

def render_demand_distribution_intelligence_center(
    dataframe=None,
):
    """Main Streamlit renderer for Part 45."""

    st.header(
        "Demand Distribution & Statistical Intelligence Center"
    )

    st.markdown(
        """
        Understand the spread, percentiles and statistical
        characteristics of historical ferry ticket sales
        and redemptions.
        """
    )

    if dataframe is None:
        try:
            if not DEFAULT_DATASET_PATH.exists():
                st.error(
                    "The configured dataset file was not found."
                )
                return

            dataframe = load_ticket_dataframe(
                str(DEFAULT_DATASET_PATH)
            )

        except Exception as error:
            st.error(
                "Unable to load the ticket dataset."
            )
            st.caption(
                f"Details: {error}"
            )
            return

    prepared = prepare_demand_distribution_intelligence_data(
        dataframe
    )

    if prepared.empty:
        st.warning(
            "No valid demand data is available for this analysis."
        )
        return

    selected_metric = st.selectbox(
        "Select demand metric",
        DEMAND_DISTRIBUTION_INTELLIGENCE_METRICS,
        key="demand_distribution_intelligence_metric",
    )

    bin_count = st.slider(
        "Histogram bin count",
        min_value=5,
        max_value=50,
        value=20,
        step=5,
        key="demand_distribution_intelligence_bins",
    )

    iqr_multiplier = st.slider(
        "IQR extreme-value multiplier",
        min_value=1.0,
        max_value=3.0,
        value=1.5,
        step=0.25,
        key="demand_distribution_intelligence_iqr",
    )

    selected_values = prepared[
        selected_metric
    ].replace(
        [np.inf, -np.inf],
        np.nan,
    ).dropna()

    if selected_values.empty:
        st.warning(
            "The selected metric contains no valid numeric values."
        )
        return

    statistics = calculate_demand_distribution_statistics(
        prepared,
        metric=selected_metric,
    )

    histogram_data = calculate_demand_distribution_bins(
        prepared,
        metric=selected_metric,
        bin_count=bin_count,
    )

    outliers = identify_demand_distribution_outliers(
        prepared,
        metric=selected_metric,
        iqr_multiplier=iqr_multiplier,
    )

    comparison = compare_demand_distribution_metrics(
        prepared
    )

    daily_data = calculate_daily_demand_distribution(
        prepared,
        metric=selected_metric,
    )

    render_demand_distribution_statistics(
        statistics
    )

    st.divider()

    render_demand_distribution_histogram(
        prepared,
        metric=selected_metric,
    )

    st.divider()

    render_demand_distribution_percentiles(
        statistics
    )

    st.divider()

    render_demand_distribution_outliers(
        outliers
    )

    st.divider()

    render_demand_distribution_comparison(
        comparison
    )

    st.divider()

    render_daily_demand_distribution(
        daily_data
    )

    st.divider()

    render_demand_distribution_exports(
        dataframe=prepared,
        histogram_data=histogram_data,
        outliers=outliers,
        comparison=comparison,
        daily_data=daily_data,
    )

    with st.expander(
        "Methodology and Limitations"
    ):
        st.markdown(
            """
            - **Mean and median:** summarize the center of the data.
            - **Standard deviation:** measures dispersion around the mean.
            - **Percentiles:** describe the relative position of observations.
            - **Histogram:** groups values into numeric ranges.
            - **IQR bounds:** flag values below Q1 âˆ’ 1.5 Ã— IQR or
              above Q3 + 1.5 Ã— IQR by default.

            Extreme observations are not automatically data errors.
            They may reflect genuine changes, special events, missing
            context or recording issues.

            These statistics describe the supplied ticket records.
            They do not independently establish passenger counts,
            vessel occupancy, revenue, future demand or service capacity.
            """
        )

    st.caption(
        "Demand Distribution Intelligence Center "
        f"v{DEMAND_DISTRIBUTION_INTELLIGENCE_VERSION}"
    )


