DEMAND_RECORD_INTEGRITY_VERSION = "1.0.0"

DEMAND_RECORD_INTEGRITY_METRICS = [
    "Sales Count",
    "Redemption Count",
]


# ------------------------------------------------------------
# 46.1 â€” PREPARE AND VALIDATE RECORDS
# ------------------------------------------------------------

def prepare_demand_record_integrity_data(dataframe):
    """Prepare records and retain validation flags."""

    required_columns = [
        "Timestamp",
        "Sales Count",
        "Redemption Count",
    ]

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    if not all(
        column in dataframe.columns
        for column in required_columns
    ):
        return pd.DataFrame()

    result = dataframe[required_columns].copy()

    result["Original Timestamp"] = result["Timestamp"]

    result["Timestamp"] = pd.to_datetime(
        result["Timestamp"],
        errors="coerce",
    )

    result["Timestamp Invalid"] = (
        result["Timestamp"].isna()
    )

    for column in DEMAND_RECORD_INTEGRITY_METRICS:
        original = result[column]

        result[column] = pd.to_numeric(
            original,
            errors="coerce",
        )

        result[f"{column} Missing"] = (
            original.isna()
            | result[column].isna()
        )

        result[f"{column} Negative"] = (
            result[column] < 0
        ).fillna(False)

        result[f"{column} Non-Integer"] = (
            result[column].notna()
            & (
                result[column]
                != np.floor(result[column])
            )
        ).fillna(False)

        result[f"{column} Non-Finite"] = (
            result[column].isin(
                [np.inf, -np.inf]
            )
        )

    result["Duplicate Timestamp"] = (
        result["Timestamp"].notna()
        & result["Timestamp"].duplicated(
            keep=False
        )
    )

    result["Both Metrics Missing"] = (
        result["Sales Count Missing"]
        & result["Redemption Count Missing"]
    )

    return result.reset_index(drop=True)


# ------------------------------------------------------------
# 46.2 â€” BUILD RECORD-LEVEL VALIDATION FLAGS
# ------------------------------------------------------------

def calculate_demand_record_integrity_flags(
    dataframe,
):
    """Build a readable list of potential record issues."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    result = dataframe.copy()

    issue_columns = [
        "Timestamp Invalid",
        "Duplicate Timestamp",
        "Both Metrics Missing",
        "Sales Count Negative",
        "Redemption Count Negative",
        "Sales Count Non-Integer",
        "Redemption Count Non-Integer",
        "Sales Count Non-Finite",
        "Redemption Count Non-Finite",
    ]

    available_issue_columns = [
        column
        for column in issue_columns
        if column in result.columns
    ]

    result["Issue Count"] = result[
        available_issue_columns
    ].astype(int).sum(axis=1)

    result["Record Status"] = np.select(
        [
            result["Issue Count"] == 0,
            result["Issue Count"] == 1,
            result["Issue Count"] > 1,
        ],
        [
            "No Flagged Issues",
            "Review Recommended",
            "Multiple Issues",
        ],
        default="Review Recommended",
    )

    return result


# ------------------------------------------------------------
# 46.3 â€” SUMMARIZE DATA QUALITY
# ------------------------------------------------------------

def calculate_demand_record_integrity_summary(
    dataframe,
):
    """Summarize validation results without silently changing data."""

    if dataframe is None or dataframe.empty:
        return {}

    total = len(dataframe)

    def count_true(column):
        if column not in dataframe.columns:
            return 0

        return int(
            dataframe[column]
            .fillna(False)
            .astype(bool)
            .sum()
        )

    timestamp_invalid = count_true(
        "Timestamp Invalid"
    )

    duplicate_timestamp = count_true(
        "Duplicate Timestamp"
    )

    both_missing = count_true(
        "Both Metrics Missing"
    )

    sales_missing = count_true(
        "Sales Count Missing"
    )

    redemption_missing = count_true(
        "Redemption Count Missing"
    )

    sales_negative = count_true(
        "Sales Count Negative"
    )

    redemption_negative = count_true(
        "Redemption Count Negative"
    )

    sales_non_integer = count_true(
        "Sales Count Non-Integer"
    )

    redemption_non_integer = count_true(
        "Redemption Count Non-Integer"
    )

    flagged_rows = count_true(
        "Issue Count"
    ) if "Issue Count" in dataframe.columns else 0

    return {
        "Total Records": total,
        "Invalid Timestamps": timestamp_invalid,
        "Rows With Duplicate Timestamps": duplicate_timestamp,
        "Rows With Both Metrics Missing": both_missing,
        "Missing Sales Values": sales_missing,
        "Missing Redemption Values": redemption_missing,
        "Negative Sales Values": sales_negative,
        "Negative Redemption Values": redemption_negative,
        "Non-Integer Sales Values": sales_non_integer,
        "Non-Integer Redemption Values": redemption_non_integer,
        "Rows With At Least One Flag": flagged_rows,
        "Rows Without Flagged Issues": max(
            total - flagged_rows,
            0,
        ),
    }


# ------------------------------------------------------------
# 46.4 â€” CHECK TIMESTAMP COVERAGE
# ------------------------------------------------------------

def calculate_demand_record_timestamp_coverage(
    dataframe,
):
    """Summarize timestamp coverage and gaps."""

    if dataframe is None or dataframe.empty:
        return {}

    timestamps = pd.to_datetime(
        dataframe["Timestamp"],
        errors="coerce",
    ).dropna()

    if timestamps.empty:
        return {
            "Valid Timestamp Count": 0,
            "Invalid Timestamp Count": len(dataframe),
            "First Timestamp": None,
            "Last Timestamp": None,
            "Observed Calendar Days": 0,
            "Missing Calendar Days": None,
        }

    first_timestamp = timestamps.min()
    last_timestamp = timestamps.max()

    observed_days = timestamps.dt.normalize().nunique()

    expected_days = (
        last_timestamp.normalize()
        - first_timestamp.normalize()
    ).days + 1

    return {
        "Valid Timestamp Count": int(
            timestamps.count()
        ),
        "Invalid Timestamp Count": int(
            dataframe["Timestamp"].isna().sum()
        ),
        "First Timestamp": first_timestamp,
        "Last Timestamp": last_timestamp,
        "Observed Calendar Days": int(observed_days),
        "Calendar Days In Date Range": int(expected_days),
        "Unobserved Calendar Days": max(
            int(expected_days - observed_days),
            0,
        ),
    }


# ------------------------------------------------------------
# 46.5 â€” CHECK DUPLICATE RECORDS
# ------------------------------------------------------------

def identify_demand_record_duplicates(
    dataframe,
):
    """Identify exact duplicate records and repeated timestamps."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame(), pd.DataFrame()

    source_columns = [
        column
        for column in [
            "Original Timestamp",
            "Sales Count",
            "Redemption Count",
        ]
        if column in dataframe.columns
    ]

    exact_duplicate_mask = dataframe[
        source_columns
    ].duplicated(
        keep=False
    )

    exact_duplicates = dataframe.loc[
        exact_duplicate_mask
    ].copy()

    repeated_timestamp_mask = (
        dataframe["Timestamp"].notna()
        & dataframe["Timestamp"].duplicated(
            keep=False
        )
    )

    repeated_timestamps = dataframe.loc[
        repeated_timestamp_mask
    ].copy()

    return exact_duplicates, repeated_timestamps


# ------------------------------------------------------------
# 46.6 â€” CREATE VALIDATION REPORT
# ------------------------------------------------------------

def build_demand_record_integrity_report(
    summary,
    timestamp_coverage,
):
    """Convert validation metrics into a report table."""

    rows = []

    for label, value in summary.items():
        rows.append({
            "Category": "Record Validation",
            "Check": label,
            "Result": value,
        })

    for label, value in timestamp_coverage.items():
        rows.append({
            "Category": "Timestamp Coverage",
            "Check": label,
            "Result": value,
        })

    return pd.DataFrame(rows)


# ------------------------------------------------------------
# 46.7 â€” GENERATE DATA QUALITY RECOMMENDATIONS
# ------------------------------------------------------------

def generate_demand_record_integrity_recommendations(
    summary,
    timestamp_coverage,
):
    """Generate review suggestions based on observed flags."""

    recommendations = []

    if not summary:
        return [
            "No summary is available. Check the input dataset."
        ]

    if summary.get("Invalid Timestamps", 0) > 0:
        recommendations.append(
            "Review invalid timestamps before performing "
            "time-series aggregation or forecasting."
        )

    if summary.get("Rows With Duplicate Timestamps", 0) > 0:
        recommendations.append(
            "Investigate repeated timestamps. They may represent "
            "multiple legitimate records or duplicated data."
        )

    if summary.get("Negative Sales Values", 0) > 0:
        recommendations.append(
            "Review negative Sales Count values against the "
            "source system's correction and refund rules."
        )

    if summary.get("Negative Redemption Values", 0) > 0:
        recommendations.append(
            "Review negative Redemption Count values against the "
            "source system's correction rules."
        )

    if summary.get("Missing Sales Values", 0) > 0:
        recommendations.append(
            "Investigate missing sales values. Do not automatically "
            "replace missing values with zero."
        )

    if summary.get("Missing Redemption Values", 0) > 0:
        recommendations.append(
            "Investigate missing redemption values. A missing value "
            "does not necessarily mean zero redemptions."
        )

    if timestamp_coverage.get(
        "Unobserved Calendar Days", 0
    ) > 0:
        recommendations.append(
            "Investigate unobserved calendar days before interpreting "
            "them as zero-demand days."
        )

    if not recommendations:
        recommendations.append(
            "No issues were flagged by these checks. This does not "
            "guarantee that every source record is correct."
        )

    return recommendations


