# ------------------------------------------------------------
# 46.14 â€” MAIN RECORD INTEGRITY CENTER
# ------------------------------------------------------------

def render_demand_record_integrity_center(
    dataframe=None,
):
    """Main renderer for Part 46."""

    st.header(
        "Demand Data Consistency & Record Integrity Center"
    )

    st.markdown(
        """
        Inspect missing values, invalid timestamps, negative
        counts, non-integer values, repeated timestamps and
        potential duplicate records.
        """
    )

    if dataframe is None:
        try:
            if not DEFAULT_DATASET_PATH.exists():
                st.error(
                    "The configured dataset was not found."
                )
                return

            dataframe = load_ticket_dataframe(
                str(DEFAULT_DATASET_PATH)
            )

        except Exception as error:
            st.error(
                "Unable to load the source dataset."
            )
            st.caption(
                f"Details: {error}"
            )
            return

    prepared = prepare_demand_record_integrity_data(
        dataframe
    )

    if prepared.empty:
        st.warning(
            "No usable records are available for validation."
        )
        return

    flagged_data = calculate_demand_record_integrity_flags(
        prepared
    )

    summary = calculate_demand_record_integrity_summary(
        flagged_data
    )

    coverage = calculate_demand_record_timestamp_coverage(
        flagged_data
    )

    exact_duplicates, repeated_timestamps = (
        identify_demand_record_duplicates(
            flagged_data
        )
    )

    report = build_demand_record_integrity_report(
        summary,
        coverage,
    )

    recommendations = (
        generate_demand_record_integrity_recommendations(
            summary,
            coverage,
        )
    )

    render_demand_record_integrity_overview(
        summary
    )

    st.divider()

    render_demand_record_timestamp_coverage(
        coverage
    )

    st.divider()

    render_demand_record_duplicate_analysis(
        exact_duplicates,
        repeated_timestamps,
    )

    st.divider()

    render_demand_record_integrity_flags(
        flagged_data
    )

    st.divider()

    render_demand_record_integrity_recommendations(
        recommendations
    )

    st.divider()

    render_demand_record_integrity_exports(
        flagged_data,
        report,
        exact_duplicates,
        repeated_timestamps,
    )

    with st.expander(
        "Validation Methodology and Limitations"
    ):
        st.markdown(
            """
            **Missing values:** values that are absent or could not
            be converted to numeric form.

            **Negative values:** flagged for source-system review;
            corrections, reversals or refunds may explain some cases.

            **Non-integer values:** flagged because ticket counts
            would ordinarily be whole numbers, but the source schema
            and business rules should be confirmed first.

            **Repeated timestamps:** multiple records may legitimately
            share a timestamp. They are not automatically duplicates.

            **Exact duplicates:** identical timestamp and demand
            values are potential duplicates, not proof of an error.

            This module does not silently delete or repair source
            records. Validate every proposed correction against the
            authoritative source system before modifying data.
            """
        )

    st.caption(
        "Demand Record Integrity Center "
        f"v{DEMAND_RECORD_INTEGRITY_VERSION}"
    )


