# ------------------------------------------------------------
# 47.1 â€” PREPARE THE SOURCE DATA
# ------------------------------------------------------------

def prepare_demand_forecast_readiness_data(dataframe):
    """Create a standardized dataset for readiness assessment."""

    required_columns = [
        "Timestamp",
        "Sales Count",
        "Redemption Count",
    ]

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    if not all(
        column in dataframe.columns
        for column in required_columns
    ):
        return pd.DataFrame()

    result = dataframe[required_columns].copy()

    result["Source Row Number"] = np.arange(
        1,
        len(result) + 1,
    )

    result["Timestamp"] = pd.to_datetime(
        result["Timestamp"],
        errors="coerce",
    )

    for column in DEMAND_FORECAST_READINESS_METRICS:
        result[column] = pd.to_numeric(
            result[column],
            errors="coerce",
        )

    result = result.replace(
        [np.inf, -np.inf],
        np.nan,
    )

    result["Timestamp Missing"] = (
        result["Timestamp"].isna()
    )

    result["Original Order"] = np.arange(
        len(result)
    )

    return result


# ------------------------------------------------------------
# 47.2 â€” ASSESS COLUMN READINESS
# ------------------------------------------------------------

def calculate_demand_forecast_column_readiness(dataframe):
    """Summarize missing and usable values in required columns."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    columns = [
        "Timestamp",
        "Sales Count",
        "Redemption Count",
    ]

    rows = []

    for column in columns:
        if column not in dataframe.columns:
            rows.append({
                "Column": column,
                "Total Rows": len(dataframe),
                "Valid Values": 0,
                "Missing Values": len(dataframe),
                "Completeness Percent": 0.0,
                "Readiness": "Unavailable",
            })
            continue

        if column == "Timestamp":
            values = pd.to_datetime(
                dataframe[column],
                errors="coerce",
            )
        else:
            values = pd.to_numeric(
                dataframe[column],
                errors="coerce",
            )

        valid_count = int(
            values.notna().sum()
        )

        missing_count = int(
            values.isna().sum()
        )

        completeness = (
            valid_count / len(dataframe) * 100
            if len(dataframe) > 0
            else 0.0
        )

        if completeness >= 99:
            readiness = "High"
        elif completeness >= 90:
            readiness = "Moderate"
        else:
            readiness = "Low"

        rows.append({
            "Column": column,
            "Total Rows": len(dataframe),
            "Valid Values": valid_count,
            "Missing Values": missing_count,
            "Completeness Percent": round(
                completeness,
                2,
            ),
            "Readiness": readiness,
        })

    return pd.DataFrame(rows)


# ------------------------------------------------------------
# 47.3 â€” ASSESS CHRONOLOGICAL ORDER
# ------------------------------------------------------------

def calculate_demand_forecast_chronology(dataframe):
    """Inspect timestamp order before time-series modelling."""

    if dataframe is None or dataframe.empty:
        return {}

    timestamps = pd.to_datetime(
        dataframe["Timestamp"],
        errors="coerce",
    )

    valid_timestamps = timestamps.dropna()

    if valid_timestamps.empty:
        return {
            "Total Rows": len(dataframe),
            "Valid Timestamps": 0,
            "Invalid Timestamps": len(dataframe),
            "Chronological": False,
            "Out-of-Order Adjacent Pairs": None,
            "Duplicate Valid Timestamps": 0,
            "First Valid Timestamp": None,
            "Last Valid Timestamp": None,
        }

    adjacent_valid = (
        timestamps.notna()
        & timestamps.shift(1).notna()
    )

    out_of_order = (
        timestamps < timestamps.shift(1)
    ) & adjacent_valid

    return {
        "Total Rows": len(dataframe),
        "Valid Timestamps": int(
            timestamps.notna().sum()
        ),
        "Invalid Timestamps": int(
            timestamps.isna().sum()
        ),
        "Chronological": bool(
            not out_of_order.any()
        ),
        "Out-of-Order Adjacent Pairs": int(
            out_of_order.sum()
        ),
        "Duplicate Valid Timestamps": int(
            valid_timestamps.duplicated(
                keep=False
            ).sum()
        ),
        "First Valid Timestamp": valid_timestamps.min(),
        "Last Valid Timestamp": valid_timestamps.max(),
    }


# ------------------------------------------------------------
# 47.4 â€” MEASURE OBSERVATION FREQUENCY
# ------------------------------------------------------------

def calculate_demand_forecast_frequency_profile(dataframe):
    """Describe time intervals between valid observations."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    timestamps = pd.to_datetime(
        dataframe["Timestamp"],
        errors="coerce",
    ).dropna().sort_values()

    if len(timestamps) < 2:
        return pd.DataFrame([{
            "Measurement": "Valid timestamps",
            "Value": len(timestamps),
        }])

    intervals = timestamps.diff().dropna()

    interval_seconds = (
        intervals.dt.total_seconds()
    )

    profile = [
        {
            "Measurement": "Valid timestamps",
            "Value": int(len(timestamps)),
        },
        {
            "Measurement": "Minimum interval (seconds)",
            "Value": float(interval_seconds.min()),
        },
        {
            "Measurement": "Median interval (seconds)",
            "Value": float(interval_seconds.median()),
        },
        {
            "Measurement": "Mean interval (seconds)",
            "Value": float(interval_seconds.mean()),
        },
        {
            "Measurement": "Maximum interval (seconds)",
            "Value": float(interval_seconds.max()),
        },
        {
            "Measurement": "Intervals longer than 24 hours",
            "Value": int(
                (interval_seconds > 86400).sum()
            ),
        },
    ]

    return pd.DataFrame(profile)


# ------------------------------------------------------------
# 47.5 â€” CHECK DAILY TIME-SERIES COVERAGE
# ------------------------------------------------------------

def calculate_demand_forecast_daily_coverage(dataframe):
    """Measure observed calendar-day coverage."""

    if dataframe is None or dataframe.empty:
        return {}

    timestamps = pd.to_datetime(
        dataframe["Timestamp"],
        errors="coerce",
    ).dropna()

    if timestamps.empty:
        return {
            "First Date": None,
            "Last Date": None,
            "Expected Calendar Days": 0,
            "Observed Calendar Days": 0,
            "Unobserved Calendar Days": None,
            "Coverage Percent": 0.0,
        }

    first_date = timestamps.min().normalize()
    last_date = timestamps.max().normalize()

    expected_days = (
        last_date - first_date
    ).days + 1

    observed_days = int(
        timestamps.dt.normalize().nunique()
    )

    missing_days = max(
        expected_days - observed_days,
        0,
    )

    coverage_percent = (
        observed_days / expected_days * 100
        if expected_days > 0
        else 0.0
    )

    return {
        "First Date": first_date,
        "Last Date": last_date,
        "Expected Calendar Days": int(expected_days),
        "Observed Calendar Days": observed_days,
        "Unobserved Calendar Days": int(missing_days),
        "Coverage Percent": round(
            coverage_percent,
            2,
        ),
    }


# ------------------------------------------------------------
# 47.6 â€” ASSESS NUMERIC DATA USABILITY
# ------------------------------------------------------------

def calculate_demand_forecast_numeric_readiness(dataframe):
    """Check whether demand metrics are suitable for numeric analysis."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    rows = []

    for column in DEMAND_FORECAST_READINESS_METRICS:
        if column not in dataframe.columns:
            continue

        values = pd.to_numeric(
            dataframe[column],
            errors="coerce",
        ).replace(
            [np.inf, -np.inf],
            np.nan,
        )

        valid = values.dropna()

        negative_count = int(
            (valid < 0).sum()
        )

        non_integer_count = int(
            (
                valid
                != np.floor(valid)
            ).sum()
        )

        rows.append({
            "Metric": column,
            "Valid Numeric Values": int(
                valid.count()
            ),
            "Missing or Invalid Values": int(
                values.isna().sum()
            ),
            "Negative Values": negative_count,
            "Non-Integer Values": non_integer_count,
            "Unique Values": int(
                valid.nunique()
            ),
            "Mean": (
                float(valid.mean())
                if not valid.empty
                else np.nan
            ),
            "Standard Deviation": (
                float(valid.std())
                if len(valid) > 1
                else np.nan
            ),
            "Constant Series": bool(
                len(valid) > 0
                and valid.nunique() == 1
            ),
        })

    return pd.DataFrame(rows)


# ------------------------------------------------------------
# 47.7 â€” CALCULATE A READINESS SCORECARD
# ------------------------------------------------------------

def calculate_demand_forecast_readiness_scorecard(
    dataframe,
    column_profile,
    chronology,
    coverage,
    numeric_profile,
):
    """Create a transparent heuristic readiness scorecard."""

    checks = []

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    timestamp_validity = (
        chronology.get("Valid Timestamps", 0)
        / max(len(dataframe), 1)
        * 100
    )

    checks.append({
        "Check": "Timestamp Validity",
        "Score": round(timestamp_validity, 2),
        "Weight": 25,
        "Reason": "Share of rows with valid timestamps.",
    })

    if (
        column_profile is not None
        and not column_profile.empty
    ):
        numeric_rows = column_profile[
            column_profile["Column"].isin(
                DEMAND_FORECAST_READINESS_METRICS
            )
        ]

        numeric_completeness = (
            float(
                numeric_rows[
                    "Completeness Percent"
                ].mean()
            )
            if not numeric_rows.empty
            else 0.0
        )
    else:
        numeric_completeness = 0.0

    checks.append({
        "Check": "Demand Value Completeness",
        "Score": round(numeric_completeness, 2),
        "Weight": 25,
        "Reason": "Average completeness of demand metrics.",
    })

    if (
        numeric_profile is not None
        and not numeric_profile.empty
    ):
        negative_values = int(
            numeric_profile["Negative Values"].sum()
        )

        total_numeric = int(
            numeric_profile[
                "Valid Numeric Values"
            ].sum()
        )

        negative_penalty = (
            negative_values / max(total_numeric, 1)
        )

        numeric_integrity_score = max(
            0.0,
            100.0 - negative_penalty * 100.0,
        )
    else:
        numeric_integrity_score = 0.0

    checks.append({
        "Check": "Numeric Integrity",
        "Score": round(numeric_integrity_score, 2),
        "Weight": 20,
        "Reason": (
            "Heuristic score penalizing negative values; "
            "other business-rule checks are separate."
        ),
    })

    chronology_score = (
        100.0
        if chronology.get("Chronological", False)
        else 50.0
    )

    if chronology.get("Invalid Timestamps", 0) > 0:
        chronology_score = min(
            chronology_score,
            timestamp_validity,
        )

    checks.append({
        "Check": "Chronological Order",
        "Score": round(chronology_score, 2),
        "Weight": 15,
        "Reason": "Checks source-row timestamp ordering.",
    })

    coverage_score = coverage.get(
        "Coverage Percent",
        0.0,
    )

    checks.append({
        "Check": "Calendar Coverage",
        "Score": round(float(coverage_score), 2),
        "Weight": 15,
        "Reason": (
            "Share of calendar days containing at least one "
            "valid timestamp; not proof of scheduled operation."
        ),
    })

    result = pd.DataFrame(checks)

    total_weight = result["Weight"].sum()

    result["Weighted Contribution"] = (
        result["Score"]
        * result["Weight"]
        / max(total_weight, 1)
    )

    overall_score = float(
        result["Weighted Contribution"].sum()
    )

    result.attrs["overall_score"] = round(
        overall_score,
        2,
    )

    if overall_score >= 90:
        label = "High"
    elif overall_score >= 75:
        label = "Moderate"
    elif overall_score >= 55:
        label = "Needs Review"
    else:
        label = "Low"

    result.attrs["readiness_label"] = label

    return result


# ------------------------------------------------------------
# 47.8 â€” GENERATE DATA PREPARATION ACTIONS
# ------------------------------------------------------------

def generate_demand_forecast_preparation_actions(
    chronology,
    coverage,
    numeric_profile,
    column_profile,
):
    """Generate suggested preparation actions."""

    actions = []

    if chronology.get("Invalid Timestamps", 0) > 0:
        actions.append(
            "Resolve invalid timestamps before chronological "
            "splitting or time-series forecasting."
        )

    if not chronology.get("Chronological", False):
        actions.append(
            "Sort valid timestamps before building a time-series "
            "model. Preserve a copy of original row order for auditing."
        )

    if chronology.get(
        "Duplicate Valid Timestamps", 0
    ) > 0:
        actions.append(
            "Inspect repeated timestamps and decide whether they "
            "should be aggregated or retained as separate records."
        )

    if coverage.get(
        "Unobserved Calendar Days", 0
    ) not in (None, 0):
        actions.append(
            "Investigate unobserved calendar days. Do not fill them "
            "with zero unless the data collection process confirms "
            "that missing records represent zero demand."
        )

    if (
        numeric_profile is not None
        and not numeric_profile.empty
    ):
        for _, row in numeric_profile.iterrows():
            if row["Negative Values"] > 0:
                actions.append(
                    f"Review negative values in {row['Metric']} "
                    "against source-system rules."
                )

            if row["Missing or Invalid Values"] > 0:
                actions.append(
                    f"Investigate missing or invalid values in "
                    f"{row['Metric']}."
                )

            if row["Constant Series"]:
                actions.append(
                    f"{row['Metric']} is constant across its valid "
                    "observations; verify whether this is expected."
                )

    if (
        column_profile is not None
        and not column_profile.empty
        and (
            column_profile["Completeness Percent"] < 100
        ).any()
    ):
        actions.append(
            "Document a missing-value strategy for each column "
            "before model training."
        )

    if not actions:
        actions.append(
            "The configured checks found no immediate preparation "
            "warning. Review model assumptions and data provenance "
            "before training."
        )

    return actions


