# ------------------------------------------------------------
# 47.15 â€” MAIN FORECAST READINESS CENTER
# ------------------------------------------------------------

def render_demand_forecast_readiness_center(
    dataframe=None,
):
    """Main Streamlit renderer for Part 47."""

    st.header(
        "Demand Forecast Readiness & Data Preparation Center"
    )

    st.markdown(
        """
        Assess whether ticket sales and redemption records are
        ready for chronological forecasting workflows.
        """
    )

    if dataframe is None:
        try:
            if not DEFAULT_DATASET_PATH.exists():
                st.error(
                    "The configured dataset was not found."
                )
                return

            dataframe = load_ticket_dataframe(
                str(DEFAULT_DATASET_PATH)
            )

        except Exception as error:
            st.error(
                "Unable to load the configured dataset."
            )
            st.caption(
                f"Details: {error}"
            )
            return

    prepared = prepare_demand_forecast_readiness_data(
        dataframe
    )

    if prepared.empty:
        st.warning(
            "No records are available for readiness analysis."
        )
        return

    column_profile = calculate_demand_forecast_column_readiness(
        prepared
    )

    chronology = calculate_demand_forecast_chronology(
        prepared
    )

    frequency_profile = (
        calculate_demand_forecast_frequency_profile(
            prepared
        )
    )

    coverage = calculate_demand_forecast_daily_coverage(
        prepared
    )

    numeric_profile = (
        calculate_demand_forecast_numeric_readiness(
            prepared
        )
    )

    scorecard = calculate_demand_forecast_readiness_scorecard(
        prepared,
        column_profile,
        chronology,
        coverage,
        numeric_profile,
    )

    actions = generate_demand_forecast_preparation_actions(
        chronology,
        coverage,
        numeric_profile,
        column_profile,
    )

    render_demand_forecast_readiness_scorecard(
        scorecard
    )

    st.divider()

    render_demand_forecast_column_readiness(
        column_profile
    )

    st.divider()

    render_demand_forecast_chronology(
        chronology,
        frequency_profile,
    )

    st.divider()

    render_demand_forecast_numeric_readiness(
        numeric_profile
    )

    st.divider()

    render_demand_forecast_preparation_actions(
        actions
    )

    st.divider()

    render_demand_forecast_readiness_exports(
        column_profile,
        frequency_profile,
        numeric_profile,
        scorecard,
    )

    with st.expander(
        "Methodology and Limitations"
    ):
        st.markdown(
            """
            - Timestamp checks evaluate parsing and source-row order.
            - Frequency checks summarize intervals between valid records.
            - Calendar coverage counts days with at least one valid timestamp.
            - Numeric checks identify missing, negative and non-integer values.
            - The readiness score combines selected checks using fixed weights.

            A day without a record is not necessarily a zero-demand day.
            Multiple records at one timestamp may be legitimate. The score
            does not guarantee model quality and should not replace
            chronological train/test evaluation.

            No source records are automatically deleted or repaired.
            """
        )

    st.caption(
        "Demand Forecast Readiness Center "
        f"v{DEMAND_FORECAST_READINESS_VERSION}"
    )


