# >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

DEMAND_DRIFT_INTELLIGENCE_VERSION = "1.0.0"

DEMAND_DRIFT_INTELLIGENCE_METRICS = [
    "Sales Count",
    "Redemption Count",
]


# ------------------------------------------------------------
# 48.1 â€” PREPARE SOURCE DATA
# ------------------------------------------------------------

def prepare_demand_drift_intelligence_data(dataframe):
    """Validate and prepare demand records for drift analysis."""

    required_columns = [
        "Timestamp",
        "Sales Count",
        "Redemption Count",
    ]

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    if not all(
        column in dataframe.columns
        for column in required_columns
    ):
        return pd.DataFrame()

    result = dataframe[required_columns].copy()

    result["Timestamp"] = pd.to_datetime(
        result["Timestamp"],
        errors="coerce",
    )

    for column in DEMAND_DRIFT_INTELLIGENCE_METRICS:
        result[column] = pd.to_numeric(
            result[column],
            errors="coerce",
        )

    result = result.replace(
        [np.inf, -np.inf],
        np.nan,
    )

    result = result.dropna(
        subset=["Timestamp"]
    )

    return result.sort_values(
        "Timestamp"
    ).reset_index(drop=True)


# ------------------------------------------------------------
# 48.2 â€” AGGREGATE DEMAND BY PERIOD
# ------------------------------------------------------------

def aggregate_demand_drift_periods(
    dataframe,
    metric="Sales Count",
    frequency="D",
):
    """Aggregate demand to daily, weekly or monthly totals."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    if metric not in DEMAND_DRIFT_INTELLIGENCE_METRICS:
        raise ValueError(
            f"Unsupported metric: {metric}"
        )

    if frequency not in ["D", "W", "MS"]:
        raise ValueError(
            "Frequency must be D, W or MS."
        )

    indexed = dataframe.set_index(
        "Timestamp"
    ).sort_index()

    aggregated = indexed[metric].resample(
        frequency
    ).sum(min_count=1)

    return aggregated.rename(
        "Demand"
    ).reset_index()


# ------------------------------------------------------------
# 48.3 â€” SPLIT HISTORICAL DATA INTO REFERENCE AND CURRENT
# ------------------------------------------------------------

def split_demand_drift_periods(
    aggregated_data,
    reference_fraction=0.70,
):
    """Create chronological reference and comparison periods."""

    if aggregated_data is None or aggregated_data.empty:
        return pd.DataFrame(), pd.DataFrame()

    if not 0.50 <= reference_fraction <= 0.90:
        raise ValueError(
            "Reference fraction must be between 0.50 and 0.90."
        )

    result = aggregated_data.copy()

    result["Timestamp"] = pd.to_datetime(
        result["Timestamp"],
        errors="coerce",
    )

    result["Demand"] = pd.to_numeric(
        result["Demand"],
        errors="coerce",
    )

    result = result.replace(
        [np.inf, -np.inf],
        np.nan,
    ).dropna(
        subset=["Timestamp", "Demand"]
    ).sort_values(
        "Timestamp"
    ).reset_index(drop=True)

    if len(result) < 4:
        return pd.DataFrame(), pd.DataFrame()

    split_index = int(
        len(result) * reference_fraction
    )

    split_index = min(
        max(split_index, 2),
        len(result) - 2,
    )

    reference_data = result.iloc[
        :split_index
    ].copy()

    comparison_data = result.iloc[
        split_index:
    ].copy()

    return reference_data, comparison_data


# ------------------------------------------------------------
# 48.4 â€” CALCULATE DISTRIBUTION STATISTICS
# ------------------------------------------------------------

def calculate_demand_drift_statistics(
    dataframe,
    label,
):
    """Calculate descriptive statistics for one comparison period."""

    if dataframe is None or dataframe.empty:
        return {}

    values = pd.to_numeric(
        dataframe["Demand"],
        errors="coerce",
    ).replace(
        [np.inf, -np.inf],
        np.nan,
    ).dropna()

    if values.empty:
        return {}

    return {
        "Period": label,
        "Observations": int(values.count()),
        "Mean": float(values.mean()),
        "Median": float(values.median()),
        "Standard Deviation": float(values.std()),
        "Minimum": float(values.min()),
        "Maximum": float(values.max()),
        "P25": float(values.quantile(0.25)),
        "P75": float(values.quantile(0.75)),
        "P90": float(values.quantile(0.90)),
    }


# ------------------------------------------------------------
# 48.5 â€” CALCULATE POPULATION STABILITY INDEX
# ------------------------------------------------------------

def calculate_demand_drift_psi(
    reference_values,
    comparison_values,
    bin_count=10,
):
    """
    Calculate an approximate PSI using shared reference-derived bins.

    PSI measures differences in binned distributions. It does not
    establish the cause or business importance of a change.
    """

    reference = pd.Series(
        reference_values,
        dtype="float64",
    ).replace(
        [np.inf, -np.inf],
        np.nan,
    ).dropna()

    comparison = pd.Series(
        comparison_values,
        dtype="float64",
    ).replace(
        [np.inf, -np.inf],
        np.nan,
    ).dropna()

    if (
        len(reference) < 2
        or len(comparison) < 2
        or bin_count < 2
    ):
        return {
            "PSI": np.nan,
            "Status": "Insufficient Data",
            "Bin Details": pd.DataFrame(),
        }

    quantiles = np.linspace(
        0,
        1,
        bin_count + 1,
    )

    edges = np.unique(
        reference.quantile(
            quantiles
        ).to_numpy()
    )

    if len(edges) < 3:
        minimum = float(reference.min())
        maximum = float(reference.max())

        if minimum == maximum:
            return {
                "PSI": np.nan,
                "Status": "Reference Has No Variation",
                "Bin Details": pd.DataFrame(),
            }

        edges = np.linspace(
            minimum,
            maximum,
            bin_count + 1,
        )

    edges = np.asarray(
        edges,
        dtype=float,
    )

    edges[0] = -np.inf
    edges[-1] = np.inf

    reference_bins = pd.cut(
        reference,
        bins=edges,
        include_lowest=True,
    )

    comparison_bins = pd.cut(
        comparison,
        bins=edges,
        include_lowest=True,
    )

    bin_categories = reference_bins.cat.categories

    reference_counts = (
        reference_bins.value_counts(
            sort=False
        ).reindex(
            bin_categories,
            fill_value=0,
        )
    )

    comparison_counts = (
        comparison_bins.value_counts(
            sort=False
        ).reindex(
            bin_categories,
            fill_value=0,
        )
    )

    reference_share = (
        reference_counts / len(reference)
    )

    comparison_share = (
        comparison_counts / len(comparison)
    )

    epsilon = 1e-6

    reference_adjusted = reference_share.clip(
        lower=epsilon
    )

    comparison_adjusted = comparison_share.clip(
        lower=epsilon
    )

    contributions = (
        comparison_adjusted - reference_adjusted
    ) * np.log(
        comparison_adjusted / reference_adjusted
    )

    psi_value = float(
        contributions.sum()
    )

    details = pd.DataFrame({
        "Reference Bin": [
            str(category)
            for category in bin_categories
        ],
        "Reference Count": reference_counts.to_numpy(),
        "Comparison Count": comparison_counts.to_numpy(),
        "Reference Share": reference_share.to_numpy(),
        "Comparison Share": comparison_share.to_numpy(),
        "PSI Contribution": contributions.to_numpy(),
    })

    if psi_value < 0.10:
        status = "Small Distribution Shift"
    elif psi_value < 0.25:
        status = "Moderate Distribution Shift"
    else:
        status = "Large Distribution Shift"

    return {
        "PSI": psi_value,
        "Status": status,
        "Bin Details": details,
    }


# ------------------------------------------------------------
# 48.6 â€” COMPARE MEAN AND MEDIAN
# ------------------------------------------------------------

def compare_demand_drift_central_tendency(
    reference_data,
    comparison_data,
):
    """Compare mean and median changes between two periods."""

    reference_stats = calculate_demand_drift_statistics(
        reference_data,
        "Reference",
    )

    comparison_stats = calculate_demand_drift_statistics(
        comparison_data,
        "Comparison",
    )

    if not reference_stats or not comparison_stats:
        return pd.DataFrame()

    rows = []

    for measure in ["Mean", "Median"]:
        reference_value = reference_stats[measure]
        comparison_value = comparison_stats[measure]

        absolute_change = (
            comparison_value - reference_value
        )

        percentage_change = (
            absolute_change / abs(reference_value) * 100
            if reference_value != 0
            else np.nan
        )

        rows.append({
            "Measure": measure,
            "Reference Value": reference_value,
            "Comparison Value": comparison_value,
            "Absolute Change": absolute_change,
            "Percentage Change": percentage_change,
        })

    return pd.DataFrame(rows)


# ------------------------------------------------------------
# 48.7 â€” BUILD DRIFT REPORT
# ------------------------------------------------------------

def build_demand_drift_report(
    reference_data,
    comparison_data,
    metric,
):
    """Combine statistical comparisons and PSI into a report."""

    reference_stats = calculate_demand_drift_statistics(
        reference_data,
        "Reference",
    )

    comparison_stats = calculate_demand_drift_statistics(
        comparison_data,
        "Comparison",
    )

    if not reference_stats or not comparison_stats:
        return pd.DataFrame()

    psi_result = calculate_demand_drift_psi(
        reference_data["Demand"],
        comparison_data["Demand"],
    )

    central_comparison = compare_demand_drift_central_tendency(
        reference_data,
        comparison_data,
    )

    rows = [
        {
            "Metric": metric,
            "Measure": "PSI",
            "Reference Value": np.nan,
            "Comparison Value": psi_result["PSI"],
            "Change": np.nan,
            "Status": psi_result["Status"],
        },
    ]

    for _, row in central_comparison.iterrows():
        rows.append({
            "Metric": metric,
            "Measure": row["Measure"],
            "Reference Value": row["Reference Value"],
            "Comparison Value": row["Comparison Value"],
            "Change": row["Absolute Change"],
            "Status": (
                "Increased"
                if row["Absolute Change"] > 0
                else (
                    "Decreased"
                    if row["Absolute Change"] < 0
                    else "Unchanged"
                )
            ),
        })

    rows.extend([
        {
            "Metric": metric,
            "Measure": "Reference Observations",
            "Reference Value": reference_stats["Observations"],
            "Comparison Value": comparison_stats["Observations"],
            "Change": (
                comparison_stats["Observations"]
                - reference_stats["Observations"]
            ),
            "Status": "Observation Count",
        },
        {
            "Metric": metric,
            "Measure": "Reference Standard Deviation",
            "Reference Value": reference_stats["Standard Deviation"],
            "Comparison Value": comparison_stats["Standard Deviation"],
            "Change": (
                comparison_stats["Standard Deviation"]
                - reference_stats["Standard Deviation"]
            ),
            "Status": "Dispersion Comparison",
        },
    ])

    return pd.DataFrame(rows)


# ------------------------------------------------------------
# 48.8 â€” GENERATE DRIFT INSIGHTS
# ------------------------------------------------------------

def generate_demand_drift_insights(
    reference_data,
    comparison_data,
    metric,
):
    """Create plain-language observations about distribution changes."""

    insights = []

    reference_stats = calculate_demand_drift_statistics(
        reference_data,
        "Reference",
    )

    comparison_stats = calculate_demand_drift_statistics(
        comparison_data,
        "Comparison",
    )

    if not reference_stats or not comparison_stats:
        return [
            "Insufficient observations for reliable comparison."
        ]

    psi_result = calculate_demand_drift_psi(
        reference_data["Demand"],
        comparison_data["Demand"],
    )

    psi_value = psi_result["PSI"]

    if pd.notna(psi_value):
        insights.append(
            f"{metric}: PSI is {psi_value:.4f}; "
            f"classification: {psi_result['Status']}."
        )
    else:
        insights.append(
            "PSI could not be calculated reliably for this split."
        )

    reference_mean = reference_stats["Mean"]
    comparison_mean = comparison_stats["Mean"]

    if reference_mean != 0:
        mean_change_pct = (
            (comparison_mean - reference_mean)
            / abs(reference_mean)
            * 100
        )

        insights.append(
            f"Mean demand changed by {mean_change_pct:.2f}% "
            "between the reference and comparison periods."
        )
    else:
        insights.append(
            "Reference mean is zero; percentage change is undefined."
        )

    reference_std = reference_stats["Standard Deviation"]
    comparison_std = comparison_stats["Standard Deviation"]

    if pd.notna(reference_std) and pd.notna(comparison_std):
        if comparison_std > reference_std:
            insights.append(
                "Demand dispersion increased in the comparison period."
            )
        elif comparison_std < reference_std:
            insights.append(
                "Demand dispersion decreased in the comparison period."
            )
        else:
            insights.append(
                "Demand dispersion remained unchanged."
            )

    insights.append(
        "A distribution shift is a signal to investigate changes "
        "in schedules, holidays, recording practices or demand patterns; "
        "it does not identify the cause on its own."
    )

    return insights


