def render_demand_drift_distribution_comparison(
    reference_data,
    comparison_data,
):
    """Compare the two chronological demand distributions."""

    st.subheader(
        "Reference vs Comparison Distribution"
    )

    if (
        reference_data is None
        or comparison_data is None
        or reference_data.empty
        or comparison_data.empty
    ):
        st.info(
            "Not enough data to compare the distributions."
        )
        return

    col1, col2 = st.columns(2)

    with col1:
        st.markdown(
            "**Reference Period**"
        )

        st.write(
            f"{reference_data['Timestamp'].min()} to "
            f"{reference_data['Timestamp'].max()}"
        )

        st.metric(
            "Observations",
            f"{len(reference_data):,}",
        )

    with col2:
        st.markdown(
            "**Comparison Period**"
        )

        st.write(
            f"{comparison_data['Timestamp'].min()} to "
            f"{comparison_data['Timestamp'].max()}"
        )

        st.metric(
            "Observations",
            f"{len(comparison_data):,}",
        )

    reference_chart = reference_data[
        ["Timestamp", "Demand"]
    ].rename(
        columns={"Demand": "Reference Demand"}
    ).set_index(
        "Timestamp"
    )

    comparison_chart = comparison_data[
        ["Timestamp", "Demand"]
    ].rename(
        columns={"Demand": "Comparison Demand"}
    ).set_index(
        "Timestamp"
    )

    st.line_chart(
        reference_chart,
        use_container_width=True,
    )

    st.line_chart(
        comparison_chart,
        use_container_width=True,
    )


