    st.subheader(
        "Population Stability Index"
    )

    if not psi_result:
        st.info(
            "PSI results are unavailable."
        )
        return

    psi_value = psi_result.get(
        "PSI",
        np.nan,
    )

    if pd.notna(psi_value):
        st.metric(
            "PSI",
            f"{psi_value:.4f}",
        )

        st.write(
            f"**Classification:** {psi_result['Status']}"
        )
    else:
        st.warning(
            f"PSI unavailable: {psi_result.get('Status', 'Unknown reason')}"
        )

    details = psi_result.get(
        "Bin Details",
        pd.DataFrame(),
    )

    if details is not None and not details.empty:
        st.dataframe(
            details,
            use_container_width=True,
            hide_index=True,
        )

    st.caption(
        "Common heuristic interpretation: below 0.10 is small, "
        "0.10â€“0.25 is moderate, and 0.25 or above is large. "
        "These are not universal statistical significance thresholds."
    )


