# 48.15 â€” MAIN DATA DRIFT CENTER
# ------------------------------------------------------------

def render_demand_drift_intelligence_center(
    dataframe=None,
):
    """Main Streamlit renderer for Part 48."""

    st.header(
        "Demand Forecast Data Drift & Distribution Shift Center"
    )

    st.markdown(
        """
        Compare earlier and later demand distributions to identify
        possible changes in ticket sales and redemption patterns.
        """
    )

    if dataframe is None:
        try:
            if not DEFAULT_DATASET_PATH.exists():
                st.error(
                    "The configured ticket dataset was not found."
                )
                return

            dataframe = load_ticket_dataframe(
                str(DEFAULT_DATASET_PATH)
            )

        except Exception as error:
            st.error(
                "Unable to load the ticket dataset."
            )

            st.caption(
                f"Details: {error}"
            )
            return

    prepared = prepare_demand_drift_intelligence_data(
        dataframe
    )

    if prepared.empty:
        st.warning(
            "No usable timestamped demand data is available."
        )
        return

    metric, frequency, reference_fraction = (
        render_demand_drift_controls()
    )

    aggregated_data = aggregate_demand_drift_periods(
        prepared,
        metric=metric,
        frequency=frequency,
    )

    reference_data, comparison_data = (
        split_demand_drift_periods(
            aggregated_data,
            reference_fraction=reference_fraction,
        )
    )

    if reference_data.empty or comparison_data.empty:
        st.warning(
            "Insufficient aggregated observations. Choose a finer "
            "frequency or provide a longer historical dataset."
        )
        return

    psi_result = calculate_demand_drift_psi(
        reference_data["Demand"],
        comparison_data["Demand"],
    )

    report = build_demand_drift_report(
        reference_data,
        comparison_data,
        metric,
    )

    insights = generate_demand_drift_insights(
        reference_data,
        comparison_data,
        metric,
    )

    render_demand_drift_distribution_comparison(
        reference_data,
        comparison_data,
    )

    st.divider()

    render_demand_drift_psi_analysis(
        psi_result
    )

    st.divider()

    render_demand_drift_report(
        report
    )

    st.divider()

    render_demand_drift_insights(
        insights
    )

    st.divider()

    render_demand_drift_exports(
        aggregated_data,
        reference_data,
        comparison_data,
        report,
        psi_result,
    )

    with st.expander(
        "Methodology and Limitations"
    ):
        st.markdown(
            """
            **Reference period:** the earlier portion of the
            chronologically ordered aggregated dataset.

            **Comparison period:** the later portion of the dataset.

            **PSI:** compares proportions of observations across
            bins derived from the reference distribution.

            This implementation uses heuristic PSI thresholds.
            PSI does not prove that a model has become inaccurate,
            establish statistical significance or explain why
            a distribution changed.

            Changes may reflect seasonality, holidays, service
            schedules, recording differences or genuine demand
            shifts. Investigate these possibilities before making
            operational decisions.

            This module analyzes historical observations; it does
            not itself retrain a forecasting model or generate
            verified future predictions.
            """
        )

    st.caption(
        "Demand Drift Intelligence Center "
        f"v{DEMAND_DRIFT_INTELLIGENCE_VERSION}"
    )


