DEMAND_TRANSFORM_WORKBENCH_VERSION = "1.0.0"

DEMAND_TRANSFORM_METRICS = [
    "Sales Count",
    "Redemption Count",
]


# ------------------------------------------------------------
# 49.1 â€” PREPARE SOURCE DATA
# ------------------------------------------------------------

def prepare_demand_transform_data(dataframe):
    """Validate timestamps and demand metrics for transformation."""

    required_columns = [
        "Timestamp",
        "Sales Count",
        "Redemption Count",
    ]

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    missing_columns = [
        column
        for column in required_columns
        if column not in dataframe.columns
    ]

    if missing_columns:
        raise ValueError(
            "Missing required columns: "
            + ", ".join(missing_columns)
        )

    result = dataframe[required_columns].copy()

    result["Timestamp"] = pd.to_datetime(
        result["Timestamp"],
        errors="coerce",
    )

    for column in DEMAND_TRANSFORM_METRICS:
        result[column] = pd.to_numeric(
            result[column],
            errors="coerce",
        )

    result = result.replace(
        [np.inf, -np.inf],
        np.nan,
    )

    invalid_timestamp_count = int(
        result["Timestamp"].isna().sum()
    )

    invalid_numeric_count = int(
        result[DEMAND_TRANSFORM_METRICS].isna().any(axis=1).sum()
    )

    result = result.dropna(
        subset=["Timestamp"]
    ).sort_values(
        "Timestamp"
    ).reset_index(drop=True)

    result.attrs["invalid_timestamp_count"] = (
        invalid_timestamp_count
    )

    result.attrs["rows_with_invalid_demand"] = (
        invalid_numeric_count
    )

    return result


# ------------------------------------------------------------
# 49.2 â€” AGGREGATE SOURCE DATA
# ------------------------------------------------------------

def aggregate_demand_transform_data(
    dataframe,
    frequency="D",
    aggregation_method="sum",
):
    """Aggregate source demand into daily, weekly or monthly periods."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    frequency_options = {
        "D": "Daily",
        "W": "Weekly",
        "MS": "Monthly",
    }

    if frequency not in frequency_options:
        raise ValueError(
            "Frequency must be D, W or MS."
        )

    if aggregation_method not in ["sum", "mean", "median"]:
        raise ValueError(
            "Aggregation must be sum, mean or median."
        )

    indexed = dataframe.set_index(
        "Timestamp"
    ).sort_index()

    demand_columns = [
        column
        for column in DEMAND_TRANSFORM_METRICS
        if column in indexed.columns
    ]

    if aggregation_method == "sum":
        aggregated = indexed[
            demand_columns
        ].resample(
            frequency
        ).sum(min_count=1)

    elif aggregation_method == "mean":
        aggregated = indexed[
            demand_columns
        ].resample(
            frequency
        ).mean()

    else:
        aggregated = indexed[
            demand_columns
        ].resample(
            frequency
        ).median()

    return aggregated.reset_index()


# ------------------------------------------------------------
# 49.3 â€” ADD TIME FEATURES
# ------------------------------------------------------------

def create_demand_transform_time_features(dataframe):
    """Create calendar features from aggregated timestamps."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    result = dataframe.copy()

    result["Timestamp"] = pd.to_datetime(
        result["Timestamp"],
        errors="coerce",
    )

    timestamp = result["Timestamp"]

    result["Year"] = timestamp.dt.year
    result["Quarter"] = timestamp.dt.quarter
    result["Month"] = timestamp.dt.month
    result["Month_Name"] = timestamp.dt.month_name()
    result["Day_Of_Week"] = timestamp.dt.dayofweek
    result["Day_Name"] = timestamp.dt.day_name()
    result["Day_Of_Month"] = timestamp.dt.day
    result["Week_Of_Year"] = (
        timestamp.dt.isocalendar().week.astype("Int64")
    )
    result["Is_Weekend"] = (
        timestamp.dt.dayofweek >= 5
    )

    return result


# ------------------------------------------------------------
# 49.4 â€” CALCULATE ROLLING AVERAGES
# ------------------------------------------------------------

def calculate_demand_transform_rolling(
    dataframe,
    metric="Sales Count",
    windows=(3, 7, 14),
):
    """Add trailing rolling means to an aggregated demand series."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    if metric not in dataframe.columns:
        raise ValueError(
            f"Metric not found: {metric}"
        )

    result = dataframe.copy()

    result[metric] = pd.to_numeric(
        result[metric],
        errors="coerce",
    )

    result = result.sort_values(
        "Timestamp"
    ).reset_index(drop=True)

    for window in windows:
        if not isinstance(window, int) or window < 1:
            continue

        column_name = (
            f"{metric.replace(' ', '_')}_Rolling_Mean_{window}"
        )

        result[column_name] = (
            result[metric]
            .rolling(
                window=window,
                min_periods=window,
            )
            .mean()
        )

    return result


# ------------------------------------------------------------
# 49.5 â€” CALCULATE PERIOD-OVER-PERIOD CHANGES
# ------------------------------------------------------------

def calculate_demand_transform_changes(
    dataframe,
    metric="Sales Count",
):
    """Calculate absolute and percentage changes from the prior row."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    if metric not in dataframe.columns:
        raise ValueError(
            f"Metric not found: {metric}"
        )

    result = dataframe.copy()

    result[metric] = pd.to_numeric(
        result[metric],
        errors="coerce",
    )

    result = result.sort_values(
        "Timestamp"
    ).reset_index(drop=True)

    result["Previous_Period_Demand"] = (
        result[metric].shift(1)
    )

    result["Demand_Change"] = (
        result[metric]
        - result["Previous_Period_Demand"]
    )

    previous = result["Previous_Period_Demand"]

    result["Demand_Change_Percent"] = np.where(
        previous.notna() & previous.ne(0),
        result["Demand_Change"] / previous.abs() * 100,
        np.nan,
    )

    return result


# ------------------------------------------------------------
# 49.6 â€” BUILD TRANSFORMATION SUMMARY
# ------------------------------------------------------------

def build_demand_transform_summary(
    source_data,
    transformed_data,
):
    """Summarize the source and transformed datasets."""

    if source_data is None or transformed_data is None:
        return pd.DataFrame()

    if source_data.empty or transformed_data.empty:
        return pd.DataFrame()

    rows = [
        {
            "Measure": "Source Records",
            "Value": int(len(source_data)),
        },
        {
            "Measure": "Aggregated Periods",
            "Value": int(len(transformed_data)),
        },
        {
            "Measure": "Source Start Date",
            "Value": str(
                source_data["Timestamp"].min()
            ),
        },
        {
            "Measure": "Source End Date",
            "Value": str(
                source_data["Timestamp"].max()
            ),
        },
        {
            "Measure": "Invalid Timestamp Rows Removed",
            "Value": int(
                source_data.attrs.get(
                    "invalid_timestamp_count",
                    0,
                )
            ),
        },
        {
            "Measure": "Rows With Invalid Demand Values",
            "Value": int(
                source_data.attrs.get(
                    "rows_with_invalid_demand",
                    0,
                )
            ),
        },
    ]

    for metric in DEMAND_TRANSFORM_METRICS:
        if metric not in transformed_data.columns:
            continue

        values = pd.to_numeric(
            transformed_data[metric],
            errors="coerce",
        )

        rows.extend([
            {
                "Measure": f"{metric} Total",
                "Value": (
                    float(values.sum())
                    if values.notna().any()
                    else np.nan
                ),
            },
            {
                "Measure": f"{metric} Average Per Period",
                "Value": (
                    float(values.mean())
                    if values.notna().any()
                    else np.nan
                ),
            },
            {
                "Measure": f"{metric} Missing Aggregated Periods",
                "Value": int(values.isna().sum()),
            },
        ])

    return pd.DataFrame(rows)


