# ------------------------------------------------------------
# 49.14 â€” MAIN TRANSFORMATION WORKBENCH
# ------------------------------------------------------------

def render_demand_transformation_workbench(
    dataframe=None,
):
    """Main Streamlit renderer for Part 49."""

    st.header(
        "Demand Forecast Data Transformation & Aggregation Workbench"
    )

    st.markdown(
        """
        Transform raw ticket records into daily, weekly or monthly
        demand series. Explore rolling averages and period changes,
        then export the transformed data for downstream analysis.
        """
    )

    if dataframe is None:
        try:
            if not DEFAULT_DATASET_PATH.exists():
                st.error(
                    "The configured ticket dataset was not found."
                )
                return

            dataframe = load_ticket_dataframe(
                str(DEFAULT_DATASET_PATH)
            )

        except Exception as error:
            st.error(
                "Unable to load the ticket dataset."
            )

            st.caption(
                f"Details: {error}"
            )
            return

    try:
        source_data = prepare_demand_transform_data(
            dataframe
        )

    except Exception as error:
        st.error(
            "The source dataset could not be prepared."
        )

        st.caption(
            f"Details: {error}"
        )
        return

    if source_data.empty:
        st.warning(
            "No usable timestamped records are available."
        )
        return

    frequency, aggregation_method, metric = (
        render_demand_transform_controls()
    )

    transformed_data = aggregate_demand_transform_data(
        source_data,
        frequency=frequency,
        aggregation_method=aggregation_method,
    )

    if transformed_data.empty:
        st.warning(
            "Aggregation did not produce usable periods."
        )
        return

    transformed_data = create_demand_transform_time_features(
        transformed_data
    )

    rolling_windows = (3, 7, 14)

    transformed_data = calculate_demand_transform_rolling(
        transformed_data,
        metric=metric,
        windows=rolling_windows,
    )

    change_data = calculate_demand_transform_changes(
        transformed_data,
        metric=metric,
    )

    summary = build_demand_transform_summary(
        source_data,
        transformed_data,
    )

    render_demand_transform_overview(
        source_data,
        transformed_data,
    )

    st.divider()

    render_demand_transform_chart(
        transformed_data,
        metric,
    )

    st.divider()

    render_demand_transform_change_analysis(
        change_data,
        metric,
    )

    st.divider()

    render_demand_transform_summary(
        summary
    )

    with st.expander(
        "View Transformed Dataset"
    ):
        render_demand_transform_preview(
            transformed_data
        )

    st.divider()

    render_demand_transform_exports(
        transformed_data,
        change_data,
        summary,
    )

    with st.expander(
        "Transformation Methodology & Limitations"
    ):
        st.markdown(
            """
            - **Daily aggregation:** groups observations by calendar day.
            - **Weekly aggregation:** groups observations into weekly periods.
            - **Monthly aggregation:** groups observations by calendar month.
            - **Total:** sums the selected metric within each period.
            - **Average and median:** describe the observed records in
              each period; they do not represent total demand.
            - **Rolling average:** smooths recent aggregated observations.
            - **Period change:** compares each period with the preceding
              aggregated row.

            Empty periods may appear with missing values when the chosen
            aggregation method is average or median. A missing period
            must not automatically be interpreted as zero demand.

            The available dataset records ticket sales and redemptions.
            These measures do not, by themselves, confirm passenger
            boarding, vessel occupancy, waiting time or available capacity.

            This workbench performs historical data transformation.
            It does not train a forecasting model or create verified
            future predictions.
            """
        )

    st.caption(
        "Demand Transformation Workbench "
        f"v{DEMAND_TRANSFORM_WORKBENCH_VERSION}"
    )


