DEMAND_MODEL_INPUT_VERSION = "1.0.0"

DEMAND_MODEL_INPUT_METRICS = [
    "Sales Count",
    "Redemption Count",
]


# ------------------------------------------------------------
# 50.1 â€” PREPARE HISTORICAL DEMAND
# ------------------------------------------------------------

def prepare_demand_model_input_data(
    dataframe,
    metric="Sales Count",
    frequency="D",
):
    """Prepare a chronological demand series for feature engineering."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    required = ["Timestamp", metric]

    missing = [
        column
        for column in required
        if column not in dataframe.columns
    ]

    if missing:
        raise ValueError(
            "Missing required columns: "
            + ", ".join(missing)
        )

    result = dataframe[required].copy()

    result["Timestamp"] = pd.to_datetime(
        result["Timestamp"],
        errors="coerce",
    )

    result[metric] = pd.to_numeric(
        result[metric],
        errors="coerce",
    )

    result = result.replace(
        [np.inf, -np.inf],
        np.nan,
    ).dropna(
        subset=["Timestamp"]
    )

    result = result.sort_values(
        "Timestamp"
    )

    result = result.set_index(
        "Timestamp"
    )

    if frequency not in ["D", "W", "MS"]:
        raise ValueError(
            "Frequency must be D, W or MS."
        )

    result = result.resample(
        frequency
    )[metric].sum(
        min_count=1
    ).rename(
        "Demand"
    ).reset_index()

    result["Demand"] = pd.to_numeric(
        result["Demand"],
        errors="coerce",
    )

    return result


# ------------------------------------------------------------
# 50.2 â€” CREATE CALENDAR FEATURES
# ------------------------------------------------------------

def create_demand_model_calendar_features(
    dataframe,
    frequency="D",
):
    """Create calendar features appropriate to the selected frequency."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    result = dataframe.copy()

    result["Timestamp"] = pd.to_datetime(
        result["Timestamp"],
        errors="coerce",
    )

    timestamp = result["Timestamp"]

    result["Year"] = timestamp.dt.year
    result["Quarter"] = timestamp.dt.quarter

    if frequency == "D":
        result["Month"] = timestamp.dt.month
        result["Day_Of_Week"] = timestamp.dt.dayofweek
        result["Day_Of_Month"] = timestamp.dt.day
        result["Is_Weekend"] = (
            timestamp.dt.dayofweek >= 5
        ).astype("int8")

    elif frequency == "W":
        result["Month"] = timestamp.dt.month
        result["Week_Of_Year"] = (
            timestamp.dt.isocalendar().week.astype("Int64")
        )

    elif frequency == "MS":
        result["Month"] = timestamp.dt.month

    else:
        raise ValueError(
            "Frequency must be D, W or MS."
        )

    result["Month_Sin"] = np.sin(
        2 * np.pi * timestamp.dt.month / 12
    )

    result["Month_Cos"] = np.cos(
        2 * np.pi * timestamp.dt.month / 12
    )

    if frequency == "D":
        result["Weekday_Sin"] = np.sin(
            2 * np.pi * timestamp.dt.dayofweek / 7
        )

        result["Weekday_Cos"] = np.cos(
            2 * np.pi * timestamp.dt.dayofweek / 7
        )

    return result


# ------------------------------------------------------------
# 50.3 â€” CREATE LAG FEATURES
# ------------------------------------------------------------

def create_demand_model_lag_features(
    dataframe,
    lag_periods=(1, 2, 3, 7, 14, 28),
):
    """Create previous-period demand features without using future values."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    if "Demand" not in dataframe.columns:
        raise ValueError(
            "Demand column is required."
        )

    result = dataframe.copy()

    result = result.sort_values(
        "Timestamp"
    ).reset_index(drop=True)

    for lag in lag_periods:
        if not isinstance(lag, int) or lag < 1:
            continue

        result[f"Lag_{lag}"] = (
            result["Demand"].shift(lag)
        )

    return result


# ------------------------------------------------------------
# 50.4 â€” CREATE ROLLING STATISTICAL FEATURES
# ------------------------------------------------------------

def create_demand_model_rolling_features(
    dataframe,
    windows=(3, 7, 14, 28),
):
    """Calculate historical rolling statistics using prior periods only."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    if "Demand" not in dataframe.columns:
        raise ValueError(
            "Demand column is required."
        )

    result = dataframe.copy()

    demand = pd.to_numeric(
        result["Demand"],
        errors="coerce",
    )

    for window in windows:
        if not isinstance(window, int) or window < 2:
            continue

        previous_demand = demand.shift(1)

        result[f"Rolling_Mean_{window}"] = (
            previous_demand.rolling(
                window=window,
                min_periods=window,
            ).mean()
        )

        result[f"Rolling_Std_{window}"] = (
            previous_demand.rolling(
                window=window,
                min_periods=window,
            ).std()
        )

        result[f"Rolling_Min_{window}"] = (
            previous_demand.rolling(
                window=window,
                min_periods=window,
            ).min()
        )

        result[f"Rolling_Max_{window}"] = (
            previous_demand.rolling(
                window=window,
                min_periods=window,
            ).max()
        )

    return result


# ------------------------------------------------------------
# 50.5 â€” CREATE DEMAND CHANGE FEATURES
# ------------------------------------------------------------

def create_demand_model_change_features(
    dataframe,
):
    """Calculate lagged differences and percentage changes."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    if "Demand" not in dataframe.columns:
        raise ValueError(
            "Demand column is required."
        )

    result = dataframe.copy()

    demand = pd.to_numeric(
        result["Demand"],
        errors="coerce",
    )

    previous = demand.shift(1)

    result["Previous_Period_Demand"] = previous

    result["Previous_Period_Change"] = (
        demand - previous
    )

    result["Previous_Period_Change_Percent"] = np.where(
        previous.notna() & previous.ne(0),
        (demand - previous) / previous.abs() * 100,
        np.nan,
    )

    return result


# ------------------------------------------------------------
# 50.6 â€” BUILD MODEL-READY FEATURE DATASET
# ------------------------------------------------------------

def build_demand_model_feature_dataset(
    dataframe,
    frequency="D",
    lag_periods=(1, 2, 3, 7, 14, 28),
    rolling_windows=(3, 7, 14, 28),
):
    """Build features and preserve the target column."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    result = create_demand_model_calendar_features(
        dataframe,
        frequency=frequency,
    )

    result = create_demand_model_lag_features(
        result,
        lag_periods=lag_periods,
    )

    result = create_demand_model_rolling_features(
        result,
        windows=rolling_windows,
    )

    result = create_demand_model_change_features(
        result
    )

    result = result.replace(
        [np.inf, -np.inf],
        np.nan,
    )

    return result


# ------------------------------------------------------------
# 50.7 â€” ASSESS FEATURE COMPLETENESS
# ------------------------------------------------------------

def calculate_demand_model_feature_quality(
    feature_data,
):
    """Summarize missing values and data types for each feature."""

    if feature_data is None or feature_data.empty:
        return pd.DataFrame()

    rows = []

    for column in feature_data.columns:
        series = feature_data[column]

        rows.append({
            "Feature": column,
            "Data Type": str(series.dtype),
            "Total Rows": int(len(series)),
            "Missing Values": int(series.isna().sum()),
            "Missing Percentage": (
                float(series.isna().mean() * 100)
            ),
            "Unique Values": int(series.nunique(dropna=True)),
        })

    return pd.DataFrame(rows)


# ------------------------------------------------------------
# 50.8 â€” SUMMARIZE FEATURE DATASET
# ------------------------------------------------------------

def summarize_demand_model_feature_dataset(
    feature_data,
):
    """Create a compact model input summary."""

    if feature_data is None or feature_data.empty:
        return pd.DataFrame()

    feature_columns = [
        column
        for column in feature_data.columns
        if column not in ["Timestamp", "Demand"]
    ]

    rows = [
        {
            "Measure": "Total Periods",
            "Value": len(feature_data),
        },
        {
            "Measure": "Total Columns",
            "Value": len(feature_data.columns),
        },
        {
            "Measure": "Engineered Features",
            "Value": len(feature_columns),
        },
        {
            "Measure": "Missing Feature Cells",
            "Value": int(
                feature_data[feature_columns].isna().sum().sum()
            ) if feature_columns else 0,
        },
        {
            "Measure": "Missing Target Values",
            "Value": int(
                feature_data["Demand"].isna().sum()
            ),
        },
        {
            "Measure": "First Period",
            "Value": str(
                feature_data["Timestamp"].min()
            ),
        },
        {
            "Measure": "Last Period",
            "Value": str(
                feature_data["Timestamp"].max()
            ),
        },
    ]

    return pd.DataFrame(rows)


