# ------------------------------------------------------------
# 50.12 â€” RENDER FEATURE CORRELATION
# ------------------------------------------------------------

def render_demand_model_input_correlation(
    feature_data,
):
    """Display numeric feature correlations with the demand target."""

    st.subheader(
        "Feature Relationship With Demand"
    )

    if (
        feature_data is None
        or feature_data.empty
        or "Demand" not in feature_data.columns
    ):
        st.info(
            "Demand target data is unavailable."
        )
        return

    numeric_data = feature_data.select_dtypes(
        include=[np.number]
    )

    if "Demand" not in numeric_data.columns:
        st.info(
            "No numeric demand target is available."
        )
        return

    correlation = numeric_data.corr(
        method="pearson"
    )["Demand"].drop(
        labels=["Demand"],
        errors="ignore",
    ).dropna()

    if correlation.empty:
        st.info(
            "Not enough numeric variation to calculate correlations."
        )
        return

    correlation_table = correlation.rename(
        "Correlation With Demand"
    ).reset_index()

    correlation_table = correlation_table.rename(
        columns={"index": "Feature"}
    )

    correlation_table["Absolute Correlation"] = (
        correlation_table["Correlation With Demand"].abs()
    )

    correlation_table = correlation_table.sort_values(
        "Absolute Correlation",
        ascending=False,
    )

    st.dataframe(
        correlation_table,
        use_container_width=True,
        hide_index=True,
    )

    st.caption(
        "Correlation describes association, not causation. "
        "Lag and rolling features are derived from historical demand, "
        "so strong correlations are not proof of forecasting accuracy."
    )


