# ------------------------------------------------------------
# 50.15 â€” MAIN MODEL INPUT CENTER
# ------------------------------------------------------------

def render_demand_model_input_center(
    dataframe=None,
):
    """Main Streamlit renderer for Part 50."""

    st.header(
        "Demand Forecast Model Input & Feature Preparation Center"
    )

    st.markdown(
        """
        Prepare historical ticket demand for downstream forecasting
        by engineering calendar, lag, rolling and change features.
        """
    )

    if dataframe is None:
        try:
            if not DEFAULT_DATASET_PATH.exists():
                st.error(
                    "The configured ticket dataset was not found."
                )
                return

            dataframe = load_ticket_dataframe(
                str(DEFAULT_DATASET_PATH)
            )

        except Exception as error:
            st.error(
                "Unable to load the ticket dataset."
            )

            st.caption(
                f"Details: {error}"
            )
            return

    metric, frequency = (
        render_demand_model_input_controls()
    )

    try:
        demand_data = prepare_demand_model_input_data(
            dataframe,
            metric=metric,
            frequency=frequency,
        )

        if demand_data.empty:
            st.warning(
                "No usable demand periods are available."
            )
            return

        feature_data = build_demand_model_feature_dataset(
            demand_data,
            frequency=frequency,
        )

        quality_data = calculate_demand_model_feature_quality(
            feature_data
        )

        summary = summarize_demand_model_feature_dataset(
            feature_data
        )

    except Exception as error:
        st.error(
            "Feature preparation could not be completed."
        )

        st.caption(
            f"Details: {error}"
        )
        return

    render_demand_model_input_overview(
        feature_data,
        summary,
    )

    st.divider()

    render_demand_model_input_quality(
        quality_data
    )

    st.divider()

    render_demand_model_input_correlation(
        feature_data
    )

    with st.expander(
        "View Model-Ready Feature Dataset"
    ):
        render_demand_model_input_preview(
            feature_data
        )

    st.divider()

    render_demand_model_input_exports(
        feature_data,
        quality_data,
        summary,
    )

    with st.expander(
        "Feature Engineering Methodology & Limitations"
    ):
        st.markdown(
            """
            **Calendar features:** encode time-related patterns.

            **Lag features:** use demand from earlier aggregated periods.

            **Rolling features:** calculate historical statistics after
            shifting demand by one period, avoiding use of the current
            target inside its own rolling window.

            **Change features:** compare the current target with the
            previous period. These are descriptive features; when training
            a model to predict future demand, target-derived features must
            be aligned carefully to avoid leakage.

            Initial lag and rolling values are missing by design.
            Do not automatically replace all missing values with zero.

            This module does not split data, train a model, tune
            hyperparameters or verify out-of-sample forecasting accuracy.
            A downstream pipeline should use chronological validation
            and construct prediction-time features using only information
            available at the forecast origin.
            """
        )

    st.caption(
        "Demand Model Input Center "
        f"v{DEMAND_MODEL_INPUT_VERSION}"
    )


