DEMAND_CHRONO_SPLIT_VERSION = "1.0.0"


# ------------------------------------------------------------
# 51.1 â€” PREPARE CHRONOLOGICAL DEMAND DATA
# ------------------------------------------------------------

def prepare_demand_chrono_split_data(
    dataframe,
    metric="Sales Count",
    frequency="D",
):
    """Create a chronological demand series for validation."""

    required_columns = ["Timestamp", metric]

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    missing_columns = [
        column
        for column in required_columns
        if column not in dataframe.columns
    ]

    if missing_columns:
        raise ValueError(
            "Missing required columns: "
            + ", ".join(missing_columns)
        )

    result = dataframe[required_columns].copy()

    result["Timestamp"] = pd.to_datetime(
        result["Timestamp"],
        errors="coerce",
    )

    result[metric] = pd.to_numeric(
        result[metric],
        errors="coerce",
    )

    result = result.replace(
        [np.inf, -np.inf],
        np.nan,
    ).dropna(
        subset=["Timestamp"]
    )

    result = result.sort_values(
        "Timestamp"
    ).set_index(
        "Timestamp"
    )

    if frequency not in ["D", "W", "MS"]:
        raise ValueError(
            "Frequency must be D, W or MS."
        )

    result = result.resample(
        frequency
    )[metric].sum(
        min_count=1
    ).rename(
        "Actual_Demand"
    ).reset_index()

    return result


# ------------------------------------------------------------
# 51.2 â€” SPLIT DATA CHRONOLOGICALLY
# ------------------------------------------------------------

def split_demand_chrono_train_test(
    dataframe,
    test_fraction=0.20,
):
    """Split historical observations without shuffling."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame(), pd.DataFrame()

    if not 0.10 <= test_fraction <= 0.40:
        raise ValueError(
            "Test fraction must be between 0.10 and 0.40."
        )

    result = dataframe.copy()

    result["Timestamp"] = pd.to_datetime(
        result["Timestamp"],
        errors="coerce",
    )

    result = result.dropna(
        subset=["Timestamp", "Actual_Demand"]
    ).sort_values(
        "Timestamp"
    ).reset_index(drop=True)

    if len(result) < 5:
        return pd.DataFrame(), pd.DataFrame()

    test_size = max(
        1,
        int(np.ceil(len(result) * test_fraction)),
    )

    if test_size >= len(result):
        return pd.DataFrame(), pd.DataFrame()

    split_index = len(result) - test_size

    train_data = result.iloc[
        :split_index
    ].copy()

    test_data = result.iloc[
        split_index:
    ].copy()

    train_data["Dataset_Split"] = "Train"
    test_data["Dataset_Split"] = "Test"

    return train_data, test_data


# ------------------------------------------------------------
# 51.3 â€” BUILD SPLIT SUMMARY
# ------------------------------------------------------------

def build_demand_chrono_split_summary(
    train_data,
    test_data,
):
    """Summarize the chronological split."""

    if (
        train_data is None
        or test_data is None
        or train_data.empty
        or test_data.empty
    ):
        return pd.DataFrame()

    total_rows = len(train_data) + len(test_data)

    rows = []

    for label, dataset in [
        ("Train", train_data),
        ("Test", test_data),
    ]:
        rows.append({
            "Dataset": label,
            "Observations": int(len(dataset)),
            "Share_Percent": (
                len(dataset) / total_rows * 100
                if total_rows
                else np.nan
            ),
            "Start_Date": dataset["Timestamp"].min(),
            "End_Date": dataset["Timestamp"].max(),
            "Mean_Demand": dataset["Actual_Demand"].mean(),
            "Median_Demand": dataset["Actual_Demand"].median(),
            "Standard_Deviation": dataset["Actual_Demand"].std(),
            "Missing_Demand": int(
                dataset["Actual_Demand"].isna().sum()
            ),
        })

    return pd.DataFrame(rows)


# ------------------------------------------------------------
# 51.4 â€” CHECK CHRONOLOGICAL SPLIT INTEGRITY
# ------------------------------------------------------------

def check_demand_chrono_split_integrity(
    train_data,
    test_data,
):
    """Check ordering and separation of train and test periods."""

    checks = []

    train_valid = (
        train_data is not None
        and not train_data.empty
    )

    test_valid = (
        test_data is not None
        and not test_data.empty
    )

    checks.append({
        "Check": "Training data available",
        "Result": bool(train_valid),
        "Details": (
            f"{len(train_data):,} observations"
            if train_valid
            else "No training observations"
        ),
    })

    checks.append({
        "Check": "Testing data available",
        "Result": bool(test_valid),
        "Details": (
            f"{len(test_data):,} observations"
            if test_valid
            else "No testing observations"
        ),
    })

    if train_valid and test_valid:
        train_ordered = train_data[
            "Timestamp"
        ].is_monotonic_increasing

        test_ordered = test_data[
            "Timestamp"
        ].is_monotonic_increasing

        no_overlap = (
            train_data["Timestamp"].max()
            < test_data["Timestamp"].min()
        )

        checks.extend([
            {
                "Check": "Training timestamps ordered",
                "Result": bool(train_ordered),
                "Details": (
                    "Chronological order preserved"
                    if train_ordered
                    else "Training timestamps are not ordered"
                ),
            },
            {
                "Check": "Testing timestamps ordered",
                "Result": bool(test_ordered),
                "Details": (
                    "Chronological order preserved"
                    if test_ordered
                    else "Testing timestamps are not ordered"
                ),
            },
            {
                "Check": "Train precedes test",
                "Result": bool(no_overlap),
                "Details": (
                    "Training period ends before test period begins"
                    if no_overlap
                    else "Train and test timestamps overlap"
                ),
            },
        ])

    return pd.DataFrame(checks)


# ------------------------------------------------------------
# 51.5 â€” CREATE HISTORICAL BASELINE PREDICTIONS
# ------------------------------------------------------------

def create_demand_chrono_baseline_predictions(
    train_data,
    test_data,
):
    """
    Create simple fixed baselines using training data only.

    These are reference forecasts, not trained machine-learning models.
    """

    if (
        train_data is None
        or test_data is None
        or train_data.empty
        or test_data.empty
    ):
        return pd.DataFrame()

    train_values = pd.to_numeric(
        train_data["Actual_Demand"],
        errors="coerce",
    ).dropna()

    test = test_data[
        ["Timestamp", "Actual_Demand"]
    ].copy()

    if train_values.empty:
        return pd.DataFrame()

    last_value = float(
        train_values.iloc[-1]
    )

    mean_value = float(
        train_values.mean()
    )

    median_value = float(
        train_values.median()
    )

    test["Naive_Prediction"] = last_value
    test["Historical_Mean_Prediction"] = mean_value
    test["Historical_Median_Prediction"] = median_value

    return test


# ------------------------------------------------------------
# 51.6 â€” CALCULATE BASELINE METRICS
# ------------------------------------------------------------

def calculate_demand_chrono_baseline_metrics(
    prediction_data,
):
    """Calculate MAE, RMSE and WAPE for baseline predictions."""

    if prediction_data is None or prediction_data.empty:
        return pd.DataFrame()

    if "Actual_Demand" not in prediction_data.columns:
        return pd.DataFrame()

    actual = pd.to_numeric(
        prediction_data["Actual_Demand"],
        errors="coerce",
    )

    prediction_columns = [
        column
        for column in prediction_data.columns
        if column.endswith("_Prediction")
    ]

    rows = []

    for column in prediction_columns:
        predicted = pd.to_numeric(
            prediction_data[column],
            errors="coerce",
        )

        valid = (
            actual.notna()
            & predicted.notna()
        )

        y_true = actual.loc[valid].to_numpy(
            dtype=float
        )

        y_pred = predicted.loc[valid].to_numpy(
            dtype=float
        )

        if len(y_true) == 0:
            continue

        errors = y_true - y_pred

        denominator = float(
            np.abs(y_true).sum()
        )

        wape = (
            float(np.abs(errors).sum() / denominator * 100)
            if denominator > 0
            else np.nan
        )

        rows.append({
            "Model": column.replace(
                "_Prediction",
                "",
            ),
            "Observations": len(y_true),
            "MAE": float(
                np.mean(np.abs(errors))
            ),
            "RMSE": float(
                np.sqrt(np.mean(errors ** 2))
            ),
            "WAPE_Percent": wape,
        })

    return pd.DataFrame(rows)


