# ------------------------------------------------------------
# 52.1 â€” PREPARE UPLOADED MODEL RESULTS
# ------------------------------------------------------------

def prepare_demand_model_leaderboard_data(dataframe):
    """Validate uploaded actual and predicted demand observations."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    result = dataframe.copy()

    result.columns = [
        str(column).strip()
        for column in result.columns
    ]

    normalized_columns = {
        str(column).strip().lower().replace(" ", "_"): column
        for column in result.columns
    }

    actual_candidates = [
        "actual",
        "actual_demand",
        "actual_value",
        "y_true",
        "true",
    ]

    predicted_candidates = [
        "predicted",
        "predicted_demand",
        "prediction",
        "predicted_value",
        "y_pred",
        "forecast",
    ]

    actual_column = next(
        (
            normalized_columns[name]
            for name in actual_candidates
            if name in normalized_columns
        ),
        None,
    )

    predicted_column = next(
        (
            normalized_columns[name]
            for name in predicted_candidates
            if name in normalized_columns
        ),
        None,
    )

    if actual_column is None or predicted_column is None:
        raise ValueError(
            "The uploaded file must contain actual and predicted "
            "columns, for example Actual and Predicted."
        )

    date_candidates = [
        "timestamp",
        "date",
        "datetime",
        "period",
    ]

    date_column = next(
        (
            normalized_columns[name]
            for name in date_candidates
            if name in normalized_columns
        ),
        None,
    )

    output = pd.DataFrame({
        "Actual": pd.to_numeric(
            result[actual_column],
            errors="coerce",
        ),
        "Predicted": pd.to_numeric(
            result[predicted_column],
            errors="coerce",
        ),
    })

    if date_column is not None:
        output["Timestamp"] = pd.to_datetime(
            result[date_column],
            errors="coerce",
        )

    output = output.replace(
        [np.inf, -np.inf],
        np.nan,
    )

    if "Timestamp" in output.columns:
        output = output.sort_values(
            "Timestamp",
            na_position="last",
        )

    output = output.dropna(
        subset=["Actual", "Predicted"]
    ).reset_index(drop=True)

    if output.empty:
        raise ValueError(
            "No valid numeric actual-predicted pairs were found."
        )

    output["Error"] = (
        output["Actual"] - output["Predicted"]
    )

    output["Absolute_Error"] = output["Error"].abs()

    output["Squared_Error"] = (
        output["Error"] ** 2
    )

    output["Absolute_Percentage_Error"] = np.where(
        output["Actual"].abs() > 0,
        output["Absolute_Error"]
        / output["Actual"].abs() * 100,
        np.nan,
    )

    return output


# ------------------------------------------------------------
# 52.2 â€” CALCULATE MODEL METRICS
# ------------------------------------------------------------

def calculate_demand_model_leaderboard_metrics(
    prediction_data,
):
    """Calculate standard regression forecast metrics."""

    if prediction_data is None or prediction_data.empty:
        return {}

    actual = pd.to_numeric(
        prediction_data["Actual"],
        errors="coerce",
    )

    predicted = pd.to_numeric(
        prediction_data["Predicted"],
        errors="coerce",
    )

    valid = (
        actual.notna()
        & predicted.notna()
        & np.isfinite(actual)
        & np.isfinite(predicted)
    )

    actual = actual.loc[valid].to_numpy(
        dtype=float
    )

    predicted = predicted.loc[valid].to_numpy(
        dtype=float
    )

    if len(actual) == 0:
        return {}

    errors = actual - predicted

    absolute_error = np.abs(errors)

    denominator = float(
        np.abs(actual).sum()
    )

    wape = (
        float(absolute_error.sum() / denominator * 100)
        if denominator > 0
        else np.nan
    )

    nonzero_actual = np.abs(actual) > 0

    mape = (
        float(
            np.mean(
                absolute_error[nonzero_actual]
                / np.abs(actual[nonzero_actual])
            ) * 100
        )
        if nonzero_actual.any()
        else np.nan
    )

    return {
        "Observations": int(len(actual)),
        "MAE": float(
            np.mean(absolute_error)
        ),
        "RMSE": float(
            np.sqrt(np.mean(errors ** 2))
        ),
        "WAPE_Percent": wape,
        "MAPE_Percent": mape,
        "Mean_Error": float(
            np.mean(errors)
        ),
        "Underprediction_Percent": float(
            np.mean(errors > 0) * 100
        ),
        "Overprediction_Percent": float(
            np.mean(errors < 0) * 100
        ),
        "Exact_Match_Percent": float(
            np.mean(np.isclose(errors, 0)) * 100
        ),
    }


# ------------------------------------------------------------
# 52.3 â€” BUILD MODEL LEADERBOARD
# ------------------------------------------------------------

def build_demand_model_leaderboard(
    model_results,
):
    """Build a ranked leaderboard from separate model evaluations."""

    if not model_results:
        return pd.DataFrame()

    rows = []

    for model_name, prediction_data in model_results.items():
        metrics = calculate_demand_model_leaderboard_metrics(
            prediction_data
        )

        if not metrics:
            continue

        rows.append({
            "Model": str(model_name),
            **metrics,
        })

    if not rows:
        return pd.DataFrame()

    leaderboard = pd.DataFrame(rows)

    leaderboard = leaderboard.sort_values(
        ["MAE", "RMSE"],
        ascending=[True, True],
        na_position="last",
    ).reset_index(drop=True)

    leaderboard.insert(
        0,
        "Rank",
        np.arange(1, len(leaderboard) + 1),
    )

    return leaderboard


# ------------------------------------------------------------
# 52.4 â€” BUILD ERROR DIAGNOSTICS
# ------------------------------------------------------------

def build_demand_model_leaderboard_diagnostics(
    prediction_data,
):
    """Summarize forecast errors and their direction."""

    if prediction_data is None or prediction_data.empty:
        return pd.DataFrame()

    error = prediction_data["Error"]

    rows = [
        {
            "Diagnostic": "Mean Error",
            "Value": float(error.mean()),
            "Interpretation": (
                "Positive means underprediction on average."
            ),
        },
        {
            "Diagnostic": "Mean Absolute Error",
            "Value": float(error.abs().mean()),
            "Interpretation": (
                "Average absolute difference between actual and predicted."
            ),
        },
        {
            "Diagnostic": "Largest Underprediction",
            "Value": float(
                error.max()
            ),
            "Interpretation": (
                "Largest positive Actual minus Predicted error."
            ),
        },
        {
            "Diagnostic": "Largest Overprediction",
            "Value": float(
                error.min()
            ),
            "Interpretation": (
                "Most negative Actual minus Predicted error."
            ),
        },
        {
            "Diagnostic": "Error Standard Deviation",
            "Value": float(
                error.std()
            ) if len(error) > 1 else 0.0,
            "Interpretation": (
                "Describes variation in signed forecast errors."
            ),
        },
    ]

    return pd.DataFrame(rows)


