def render_demand_model_leaderboard_upload():
    """Upload predictions for a single model."""

    st.subheader(
        "Evaluate a Forecast Model"
    )

    uploaded_file = st.file_uploader(
        "Upload actual and predicted values as CSV",
        type=["csv"],
        key="demand_model_leaderboard_upload",
        help=(
            "Required columns: Actual and Predicted. "
            "An optional Date or Timestamp column can be included."
        ),
    )

    model_name = st.text_input(
        "Model name",
        value="Model 1",
        key="demand_model_leaderboard_name",
    )

    if uploaded_file is None:
        return None, model_name.strip() or "Model 1"

    try:
        uploaded_data = pd.read_csv(
            uploaded_file
        )

        prepared_data = prepare_demand_model_leaderboard_data(
            uploaded_data
        )

        st.success(
            f"Loaded {len(prepared_data):,} valid prediction pairs."
        )

        return (
            prepared_data,
            model_name.strip() or "Model 1",
        )

    except Exception as error:
        st.error(
            "Unable to prepare the uploaded predictions."
        )

        st.caption(
            f"Details: {error}"
        )

        return None, model_name.strip() or "Model 1"


