def prepare_demand_feature_audit_data(dataframe):
    """Prepare a copy of a dataset for feature leakage inspection."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    result = dataframe.copy()

    result.columns = [
        str(column).strip()
        for column in result.columns
    ]

    if result.columns.duplicated().any():
        raise ValueError(
            "The dataset contains duplicate column names. "
            "Rename duplicate columns before auditing."
        )

    return result


# ------------------------------------------------------------
# 53.2 â€” IDENTIFY TARGET AND TIME COLUMNS
# ------------------------------------------------------------

def identify_demand_feature_audit_columns(dataframe):
    """Suggest likely target and timestamp columns."""

    if dataframe is None or dataframe.empty:
        return {
            "target_candidates": [],
            "time_candidates": [],
        }

    columns = list(dataframe.columns)

    target_candidates = [
        column
        for column in columns
        if str(column).strip().lower()
        in {
            value.lower()
            for value in DEMAND_FEATURE_AUDIT_TARGET_CANDIDATES
        }
    ]

    time_candidates = [
        column
        for column in columns
        if str(column).strip().lower()
        in {
            value.lower()
            for value in DEMAND_FEATURE_AUDIT_TIME_CANDIDATES
        }
    ]

    return {
        "target_candidates": target_candidates,
        "time_candidates": time_candidates,
    }


# ------------------------------------------------------------
# 53.3 â€” AUDIT INDIVIDUAL FEATURE COLUMNS
# ------------------------------------------------------------

def calculate_demand_feature_audit_column_report(
    dataframe,
    target_column,
    timestamp_column=None,
):
    """Profile features and flag possible leakage indicators.

    These are screening rules, not proof that leakage exists.
    """

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    if target_column not in dataframe.columns:
        raise ValueError(
            f"Target column '{target_column}' was not found."
        )

    rows = []

    row_count = len(dataframe)

    for column in dataframe.columns:
        series = dataframe[column]

        non_null_count = int(series.notna().sum())

        unique_count = int(series.nunique(dropna=True))

        missing_percent = (
            float(series.isna().mean() * 100)
            if row_count
            else 0.0
        )

        is_target = column == target_column

        is_timestamp = (
            timestamp_column is not None
            and column == timestamp_column
        )

        name_lower = str(column).strip().lower()

        suspicious_name_terms = [
            "future",
            "lead_",
            "next_",
            "target",
            "actual",
            "outcome",
            "after_",
            "post_",
        ]

        name_flag = (
            any(
                term in name_lower
                for term in suspicious_name_terms
            )
            and not is_target
        )

        numeric_series = pd.to_numeric(
            series,
            errors="coerce",
        )

        numeric_count = int(
            numeric_series.notna().sum()
        )

        numeric_percent = (
            numeric_count / row_count * 100
            if row_count
            else 0.0
        )

        constant_flag = (
            unique_count <= 1
            and non_null_count > 0
            and not is_target
        )

        target_correlation = np.nan

        if (
            not is_target
            and numeric_percent >= 80
            and pd.api.types.is_numeric_dtype(
                dataframe[target_column]
            )
        ):
            pair = pd.DataFrame({
                "feature": numeric_series,
                "target": pd.to_numeric(
                    dataframe[target_column],
                    errors="coerce",
                ),
            }).replace(
                [np.inf, -np.inf],
                np.nan,
            ).dropna()

            if (
                len(pair) >= 3
                and pair["feature"].nunique() > 1
                and pair["target"].nunique() > 1
            ):
                target_correlation = float(
                    pair["feature"].corr(pair["target"])
                )

        warning_reasons = []

        if name_flag:
            warning_reasons.append(
                "Column name may indicate future or outcome information"
            )

        if constant_flag:
            warning_reasons.append(
                "Constant feature; likely has little predictive value"
            )

        if (
            pd.notna(target_correlation)
            and abs(target_correlation) >= 0.98
        ):
            warning_reasons.append(
                "Very high target correlation; investigate possible leakage"
            )

        if is_target:
            classification = "Target"
        elif is_timestamp:
            classification = "Time Index"
        elif warning_reasons:
            classification = "Review"
        else:
            classification = "No Simple Flag"

        rows.append({
            "Column": column,
            "Role": classification,
            "Data_Type": str(series.dtype),
            "Non_Null_Count": non_null_count,
            "Missing_Percent": round(
                missing_percent,
                2,
            ),
            "Unique_Values": unique_count,
            "Numeric_Value_Percent": round(
                numeric_percent,
                2,
            ),
            "Target_Correlation": (
                round(target_correlation, 4)
                if pd.notna(target_correlation)
                else np.nan
            ),
            "Warning_Reasons": "; ".join(
                warning_reasons
            ) if warning_reasons else "No simple rule triggered",
        })

    return pd.DataFrame(rows)


# ------------------------------------------------------------
# 53.4 â€” CHECK CHRONOLOGICAL ORDER
# ------------------------------------------------------------

def calculate_demand_feature_audit_chronology(
    dataframe,
    timestamp_column,
):
    """Inspect timestamp parsing, order and duplicate timestamps."""

    if dataframe is None or dataframe.empty:
        return {
            "status": "No data",
            "rows": 0,
            "valid_timestamps": 0,
            "invalid_timestamps": 0,
            "duplicate_timestamp_rows": 0,
            "out_of_order_rows": 0,
            "earliest_timestamp": None,
            "latest_timestamp": None,
        }

    if timestamp_column not in dataframe.columns:
        raise ValueError(
            f"Timestamp column '{timestamp_column}' was not found."
        )

    timestamps = pd.to_datetime(
        dataframe[timestamp_column],
        errors="coerce",
    )

    valid_timestamps = timestamps.dropna()

    duplicate_rows = int(
        valid_timestamps.duplicated(
            keep=False
        ).sum()
    )

    valid_positions = np.flatnonzero(
        timestamps.notna().to_numpy()
    )

    valid_values = timestamps.iloc[
        valid_positions
    ].reset_index(drop=True)

    out_of_order_count = int(
        (valid_values.diff().dropna() < pd.Timedelta(0)).sum()
    )

    earliest = (
        valid_timestamps.min()
        if not valid_timestamps.empty
        else None
    )

    latest = (
        valid_timestamps.max()
        if not valid_timestamps.empty
        else None
    )

    invalid_count = int(
        timestamps.isna().sum()
    )

    status = (
        "Review required"
        if invalid_count or out_of_order_count
        else "Basic checks passed"
    )

    return {
        "status": status,
        "rows": int(len(dataframe)),
        "valid_timestamps": int(
            timestamps.notna().sum()
        ),
        "invalid_timestamps": invalid_count,
        "duplicate_timestamp_rows": duplicate_rows,
        "out_of_order_rows": out_of_order_count,
        "earliest_timestamp": earliest,
        "latest_timestamp": latest,
    }


# ------------------------------------------------------------
# 53.5 â€” CHECK FEATURE-TARGET ALIGNMENT
# ------------------------------------------------------------

def calculate_demand_feature_audit_alignment(
    dataframe,
    target_column,
    timestamp_column,
    lag_columns=None,
):
    """Inspect whether rows are chronologically sorted and
    whether the target and named lag features contain missing values.

    This function does not prove that every feature is leakage-free.
    """

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    if target_column not in dataframe.columns:
        raise ValueError(
            f"Target column '{target_column}' was not found."
        )

    if timestamp_column not in dataframe.columns:
        raise ValueError(
            f"Timestamp column '{timestamp_column}' was not found."
        )

    lag_columns = lag_columns or []

    timestamps = pd.to_datetime(
        dataframe[timestamp_column],
        errors="coerce",
    )

    target = pd.to_numeric(
        dataframe[target_column],
        errors="coerce",
    )

    rows = [
        {
            "Check": "Target missing values",
            "Result": int(target.isna().sum()),
            "Interpretation": (
                "Rows without a numeric target cannot be used "
                "as ordinary supervised target observations."
            ),
        },
        {
            "Check": "Invalid timestamps",
            "Result": int(timestamps.isna().sum()),
            "Interpretation": (
                "Rows with invalid timestamps cannot be reliably "
                "ordered for chronological forecasting."
            ),
        },
        {
            "Check": "Timestamp order violations",
            "Result": int(
                (
                    timestamps.dropna()
                    .reset_index(drop=True)
                    .diff()
                    .dropna()
                    < pd.Timedelta(0)
                ).sum()
            ),
            "Interpretation": (
                "A positive count means valid timestamps are not "
                "in chronological order."
            ),
        },
    ]

    for column in lag_columns:
        if column not in dataframe.columns:
            rows.append({
                "Check": f"Lag feature: {column}",
                "Result": "Column not found",
                "Interpretation": (
                    "Confirm the intended lag feature name."
                ),
            })
            continue

        values = pd.to_numeric(
            dataframe[column],
            errors="coerce",
        )

        rows.append({
            "Check": f"Lag feature missing: {column}",
            "Result": int(values.isna().sum()),
            "Interpretation": (
                "Missing lag values can be expected at the start "
                "of a time series; inspect the feature-generation logic."
            ),
        })

    return pd.DataFrame(rows)


# ------------------------------------------------------------
# 53.6 â€” GENERATE AUDIT RECOMMENDATIONS
# ------------------------------------------------------------

def generate_demand_feature_audit_recommendations(
    column_report,
    chronology_report,
):
    """Create recommendations from simple audit findings."""

    recommendations = []

    if column_report is None or column_report.empty:
        recommendations.append(
            "Load a dataset and select a target column before auditing."
        )
    else:
        review_rows = column_report[
            column_report["Role"] == "Review"
        ]

        if not review_rows.empty:
            recommendations.append(
                "Review flagged columns manually. A warning is a signal "
                "to investigate, not proof of data leakage."
            )

        target_rows = column_report[
            column_report["Role"] == "Target"
        ]

        if target_rows.empty:
            recommendations.append(
                "Confirm that the selected target represents the value "
                "you actually intend to predict."
            )

        if (
            column_report["Missing_Percent"] > 0
        ).any():
            recommendations.append(
                "Investigate missing values and decide how to handle them "
                "without using information from the future."
            )

    if chronology_report:
        if chronology_report.get(
            "invalid_timestamps",
            0,
        ) > 0:
            recommendations.append(
                "Resolve or explicitly exclude rows with invalid timestamps."
            )

        if chronology_report.get(
            "out_of_order_rows",
            0,
        ) > 0:
            recommendations.append(
                "Sort observations chronologically before creating "
                "lags, rolling features and chronological train-test splits."
            )

        if chronology_report.get(
            "duplicate_timestamp_rows",
            0,
        ) > 0:
            recommendations.append(
                "Investigate repeated timestamps. They may represent "
                "legitimate multiple records or require aggregation."
            )

    recommendations.extend([
        "Create lag features using past observations only.",
        "For rolling features, shift the series before calculating "
        "statistics when predicting the current period.",
        "Fit imputers, scalers and feature-selection steps on training "
        "data only, then apply them to validation and test data.",
        "Use a chronological split for time-series evaluation.",
        "Confirm suspicious columns by tracing how and when each "
        "value becomes available in a real forecasting workflow.",
    ])

    return list(dict.fromkeys(recommendations))


