# 53.12 â€” MAIN FEATURE AUDIT CENTER
# ------------------------------------------------------------

def render_demand_feature_audit_center():
    """Main Streamlit renderer for Part 53."""

    st.header(
        "Forecast Data Leakage & Feature Audit Center"
    )

    st.markdown(
        """
        Inspect forecasting datasets for suspicious feature names,
        missing data, constant columns, unusually high target correlation
        and chronology problems.
        """
    )

    dataframe = render_demand_feature_audit_upload()

    if dataframe is None or dataframe.empty:
        st.info(
            "Upload a CSV file to start the audit."
        )
        return

    suggestions = identify_demand_feature_audit_columns(
        dataframe
    )

    columns = list(dataframe.columns)

    default_target = (
        suggestions["target_candidates"][0]
        if suggestions["target_candidates"]
        else columns[0]
    )

    target_column = st.selectbox(
        "Select the target column",
        options=columns,
        index=columns.index(default_target),
        key="demand_feature_audit_target",
    )

    time_options = ["None"] + columns

    default_time = (
        suggestions["time_candidates"][0]
        if suggestions["time_candidates"]
        else "None"
    )

    timestamp_column = st.selectbox(
        "Select the timestamp column, if available",
        options=time_options,
        index=time_options.index(default_time),
        key="demand_feature_audit_timestamp",
    )

    if timestamp_column == "None":
        timestamp_column = None

    st.warning(
        "This center performs heuristic checks. It cannot automatically "
        "prove that a feature leaks information; review the data-generation "
        "process and prediction-time availability of each flagged column."
    )

    column_report = calculate_demand_feature_audit_column_report(
        dataframe,
        target_column,
        timestamp_column,
    )

    chronology_report = None

    if timestamp_column is not None:
        chronology_report = (
            calculate_demand_feature_audit_chronology(
                dataframe,
                timestamp_column,
            )
        )

    recommendations = (
        generate_demand_feature_audit_recommendations(
            column_report,
            chronology_report,
        )
    )

    st.divider()

    render_demand_feature_audit_report(
        column_report
    )

    if timestamp_column is not None:
        st.divider()

        render_demand_feature_audit_chronology(
            chronology_report
        )

    st.divider()

    render_demand_feature_audit_recommendations(
        recommendations
    )

    st.divider()

    render_demand_feature_audit_exports(
        column_report,
        chronology_report,
        recommendations,
    )

    with st.expander(
        "Important: What counts as data leakage?"
    ):
        st.markdown(
            """
            Data leakage occurs when training or evaluation uses
            information that would not legitimately be available at the
            time a forecast is made.

            Examples include:
            - Using a future demand value as a feature for an earlier
              prediction.
            - Calculating rolling statistics using the current target
              or future observations when they would not be available.
            - Fitting preprocessing steps on the complete dataset before
              creating a train-test split.
            - Randomly splitting time-series records when the task
              requires future-period forecasting.

            A highly correlated feature is not automatically leakage.
            It must be investigated in context.
            """
        )

    st.caption(
        "Feature Audit Center "
        f"v{DEMAND_FEATURE_AUDIT_VERSION}"
    )


