# ------------------------------------------------------------
# 54.1 â€” PREPARE FEATURE IMPORTANCE DATA
# ------------------------------------------------------------

def prepare_demand_feature_explainability_data(dataframe):
    """Identify feature-name and importance-score columns."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    result = dataframe.copy()

    result.columns = [
        str(column).strip()
        for column in result.columns
    ]

    normalized = {
        str(column).strip().lower().replace(" ", "_"): column
        for column in result.columns
    }

    feature_candidates = [
        "feature",
        "feature_name",
        "variable",
        "column",
        "predictor",
    ]

    importance_candidates = [
        "importance",
        "feature_importance",
        "importance_score",
        "weight",
        "coefficient",
        "contribution",
    ]

    feature_column = next(
        (
            normalized[name]
            for name in feature_candidates
            if name in normalized
        ),
        None,
    )

    importance_column = next(
        (
            normalized[name]
            for name in importance_candidates
            if name in normalized
        ),
        None,
    )

    if feature_column is None or importance_column is None:
        raise ValueError(
            "The CSV must contain a feature-name column and an "
            "importance-score column. Examples: Feature, Importance."
        )

    output = pd.DataFrame({
        "Feature": result[feature_column].astype("string"),
        "Importance": pd.to_numeric(
            result[importance_column],
            errors="coerce",
        ),
    })

    output = output.replace(
        [np.inf, -np.inf],
        np.nan,
    )

    output = output.dropna(
        subset=["Feature", "Importance"]
    )

    output["Feature"] = (
        output["Feature"].str.strip()
    )

    output = output[
        output["Feature"].ne("")
    ].copy()

    if output.empty:
        raise ValueError(
            "No valid feature-importance records were found."
        )

    output = (
        output.groupby(
            "Feature",
            as_index=False,
        )["Importance"]
        .mean()
    )

    output["Absolute_Importance"] = (
        output["Importance"].abs()
    )

    output = output.sort_values(
        "Absolute_Importance",
        ascending=False,
    ).reset_index(drop=True)

    output.insert(
        0,
        "Rank",
        np.arange(1, len(output) + 1),
    )

    return output


# ------------------------------------------------------------
# 54.2 â€” SUMMARIZE IMPORTANCE DISTRIBUTION
# ------------------------------------------------------------

def calculate_demand_feature_explainability_summary(
    importance_data,
):
    """Calculate descriptive statistics for uploaded scores."""

    if importance_data is None or importance_data.empty:
        return {}

    scores = pd.to_numeric(
        importance_data["Importance"],
        errors="coerce",
    ).replace(
        [np.inf, -np.inf],
        np.nan,
    ).dropna()

    if scores.empty:
        return {}

    absolute_scores = scores.abs()

    absolute_total = float(
        absolute_scores.sum()
    )

    normalized = (
        absolute_scores / absolute_total
        if absolute_total > 0
        else pd.Series(
            np.zeros(len(absolute_scores)),
            index=absolute_scores.index,
        )
    )

    return {
        "Feature_Count": int(len(scores)),
        "Positive_Count": int((scores > 0).sum()),
        "Negative_Count": int((scores < 0).sum()),
        "Zero_Count": int((scores == 0).sum()),
        "Largest_Absolute_Importance": float(
            absolute_scores.max()
        ),
        "Mean_Absolute_Importance": float(
            absolute_scores.mean()
        ),
        "Absolute_Importance_Total": absolute_total,
        "Top_Feature_Share_Percent": float(
            normalized.max() * 100
        ) if len(normalized) else 0.0,
    }


# ------------------------------------------------------------
# 54.3 â€” BUILD TOP-FEATURE REPORT
# ------------------------------------------------------------

def build_demand_feature_explainability_top_features(
    importance_data,
    top_n=15,
):
    """Return the most important features by absolute score."""

    if importance_data is None or importance_data.empty:
        return pd.DataFrame()

    top_n = max(
        1,
        min(int(top_n), 500),
    )

    result = importance_data.copy()

    return result.nlargest(
        top_n,
        "Absolute_Importance",
    ).reset_index(drop=True)


# ------------------------------------------------------------
# 54.4 â€” GROUP FEATURES BY NAME
# ------------------------------------------------------------

def classify_demand_feature_explainability_groups(
    importance_data,
):
    """Group feature names using transparent name-based heuristics."""

    if importance_data is None or importance_data.empty:
        return pd.DataFrame()

    result = importance_data.copy()

    def classify_feature(feature_name):
        name = str(feature_name).lower()

        if any(
            term in name
            for term in [
                "lag",
                "rolling",
                "shift",
                "previous",
                "prior",
            ]
        ):
            return "Historical / Lag"

        if any(
            term in name
            for term in [
                "weekday",
                "day",
                "month",
                "quarter",
                "year",
                "week",
                "holiday",
                "season",
            ]
        ):
            return "Calendar / Seasonal"

        if any(
            term in name
            for term in [
                "sales",
                "redemption",
                "demand",
                "ticket",
            ]
        ):
            return "Demand / Ticket"

        if any(
            term in name
            for term in [
                "average",
                "mean",
                "median",
                "std",
                "volatility",
                "change",
                "growth",
            ]
        ):
            return "Statistical / Trend"

        return "Other"

    result["Feature_Group"] = (
        result["Feature"].map(
            classify_feature
        )
    )

    return result


# ------------------------------------------------------------
# 54.5 â€” SUMMARIZE FEATURE GROUPS
# ------------------------------------------------------------

def calculate_demand_feature_explainability_group_summary(
    grouped_data,
):
    """Aggregate absolute importance by heuristic feature group."""

    if grouped_data is None or grouped_data.empty:
        return pd.DataFrame()

    summary = (
        grouped_data.groupby(
            "Feature_Group",
            as_index=False,
        )
        .agg(
            Feature_Count=("Feature", "count"),
            Total_Absolute_Importance=(
                "Absolute_Importance",
                "sum",
            ),
            Mean_Absolute_Importance=(
                "Absolute_Importance",
                "mean",
            ),
        )
    )

    total = float(
        summary["Total_Absolute_Importance"].sum()
    )

    summary["Share_Percent"] = (
        summary["Total_Absolute_Importance"]
        / total * 100
        if total > 0
        else 0.0
    )

    return summary.sort_values(
        "Total_Absolute_Importance",
        ascending=False,
    ).reset_index(drop=True)


# ------------------------------------------------------------
# 54.6 â€” GENERATE INTERPRETATION NOTES
# ------------------------------------------------------------

def generate_demand_feature_explainability_insights(
    importance_data,
    summary,
):
    """Generate cautious descriptions of uploaded importance scores."""

    insights = []

    if importance_data is None or importance_data.empty:
        return [
            "Upload a valid feature-importance CSV to generate insights."
        ]

    top_feature = importance_data.iloc[0]

    insights.append(
        f"Highest absolute importance score: "
        f"{top_feature['Feature']} "
        f"({top_feature['Importance']:.4f})."
    )

    if summary:
        insights.append(
            f"The file contains {summary['Feature_Count']:,} "
            "distinct feature names after duplicate names were combined."
        )

        if summary["Negative_Count"] > 0:
            insights.append(
                "Negative scores exist. Their meaning depends on the "
                "model and importance method; they should not automatically "
                "be interpreted as negative predictive influence."
            )

        if summary["Top_Feature_Share_Percent"] >= 50:
            insights.append(
                "One feature accounts for at least half of the total "
                "absolute score. Verify the scoring method and investigate "
                "possible redundancy or leakage."
            )

    insights.extend([
        "Feature importance indicates model-specific relevance, "
        "not proof of a causal relationship.",
        "Scores from different models or importance methods may not be "
        "directly comparable.",
        "Check that all reported features were available at the time "
        "each forecast would have been generated.",
    ])

    return insights


