DEMAND_GENERALIZATION_VERSION = "1.0.0"


# ------------------------------------------------------------
# 55.1 â€” PREPARE EVALUATION DATA
# ------------------------------------------------------------

def prepare_demand_generalization_data(dataframe):
    """Prepare uploaded actual and predicted values for analysis."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    result = dataframe.copy()

    result.columns = [
        str(column).strip()
        for column in result.columns
    ]

    normalized = {
        str(column).strip().lower().replace(" ", "_"): column
        for column in result.columns
    }

    actual_candidates = [
        "actual",
        "actual_demand",
        "actual_value",
        "y_true",
    ]

    predicted_candidates = [
        "predicted",
        "predicted_demand",
        "prediction",
        "predicted_value",
        "y_pred",
        "forecast",
    ]

    actual_column = next(
        (
            normalized[name]
            for name in actual_candidates
            if name in normalized
        ),
        None,
    )

    predicted_column = next(
        (
            normalized[name]
            for name in predicted_candidates
            if name in normalized
        ),
        None,
    )

    if actual_column is None or predicted_column is None:
        raise ValueError(
            "Required columns were not found. Include Actual and "
            "Predicted columns in the uploaded CSV."
        )

    date_candidates = [
        "timestamp",
        "date",
        "datetime",
        "period",
    ]

    date_column = next(
        (
            normalized[name]
            for name in date_candidates
            if name in normalized
        ),
        None,
    )

    result_data = pd.DataFrame({
        "Actual": pd.to_numeric(
            result[actual_column],
            errors="coerce",
        ),
        "Predicted": pd.to_numeric(
            result[predicted_column],
            errors="coerce",
        ),
    })

    if date_column is not None:
        result_data["Timestamp"] = pd.to_datetime(
            result[date_column],
            errors="coerce",
        )

    result_data = result_data.replace(
        [np.inf, -np.inf],
        np.nan,
    )

    if "Timestamp" in result_data.columns:
        result_data = result_data.sort_values(
            "Timestamp",
            na_position="last",
        )

    result_data = result_data.dropna(
        subset=["Actual", "Predicted"]
    ).reset_index(drop=True)

    if result_data.empty:
        raise ValueError(
            "No valid actual-predicted pairs remain after cleaning."
        )

    result_data["Error"] = (
        result_data["Actual"]
        - result_data["Predicted"]
    )

    result_data["Absolute_Error"] = (
        result_data["Error"].abs()
    )

    result_data["Squared_Error"] = (
        result_data["Error"] ** 2
    )

    return result_data


# ------------------------------------------------------------
# 55.2 â€” CALCULATE RELIABILITY METRICS
# ------------------------------------------------------------

def calculate_demand_generalization_metrics(dataframe):
    """Calculate standard forecast metrics for a data segment."""

    if dataframe is None or dataframe.empty:
        return {}

    actual = pd.to_numeric(
        dataframe["Actual"],
        errors="coerce",
    ).to_numpy(dtype=float)

    predicted = pd.to_numeric(
        dataframe["Predicted"],
        errors="coerce",
    ).to_numpy(dtype=float)

    valid = (
        np.isfinite(actual)
        & np.isfinite(predicted)
    )

    actual = actual[valid]
    predicted = predicted[valid]

    if len(actual) == 0:
        return {}

    error = actual - predicted

    absolute_error = np.abs(error)

    actual_total = float(
        np.abs(actual).sum()
    )

    wape = (
        float(absolute_error.sum() / actual_total * 100)
        if actual_total > 0
        else np.nan
    )

    nonzero_actual = np.abs(actual) > 0

    mape = (
        float(
            np.mean(
                absolute_error[nonzero_actual]
                / np.abs(actual[nonzero_actual])
            ) * 100
        )
        if nonzero_actual.any()
        else np.nan
    )

    actual_std = float(
        np.std(actual)
    )

    return {
        "Observations": int(len(actual)),
        "MAE": float(
            np.mean(absolute_error)
        ),
        "RMSE": float(
            np.sqrt(np.mean(error ** 2))
        ),
        "WAPE_Percent": wape,
        "MAPE_Percent": mape,
        "Mean_Error": float(
            np.mean(error)
        ),
        "Error_Std": float(
            np.std(error)
        ),
        "Actual_Mean": float(
            np.mean(actual)
        ),
        "Actual_Std": actual_std,
    }


# ------------------------------------------------------------
# 55.3 â€” SPLIT INTO CHRONOLOGICAL SEGMENTS
# ------------------------------------------------------------

def split_demand_generalization_segments(
    dataframe,
    segment_count=4,
):
    """Split observations into consecutive segments by row order.

    If a Timestamp column exists, preparation sorts valid timestamps
    before invalid timestamps. This function does not retrain a model.
    """

    if dataframe is None or dataframe.empty:
        return {}

    segment_count = max(
        2,
        min(int(segment_count), len(dataframe)),
    )

    index_groups = np.array_split(
        np.arange(len(dataframe)),
        segment_count,
    )

    segments = {}

    for index, row_indexes in enumerate(
        index_groups,
        start=1,
    ):
        if len(row_indexes) == 0:
            continue

        segment_name = f"Segment {index}"

        segment_data = dataframe.iloc[
            row_indexes
        ].copy().reset_index(drop=True)

        segments[segment_name] = segment_data

    return segments


# ------------------------------------------------------------
# 55.4 â€” BUILD SEGMENT PERFORMANCE REPORT
# ------------------------------------------------------------

def build_demand_generalization_report(
    segments,
):
    """Compare metrics across consecutive evaluation segments."""

    if not segments:
        return pd.DataFrame()

    rows = []

    for segment_name, segment_data in segments.items():
        metrics = calculate_demand_generalization_metrics(
            segment_data
        )

        if not metrics:
            continue

        rows.append({
            "Segment": segment_name,
            **metrics,
        })

    if not rows:
        return pd.DataFrame()

    report = pd.DataFrame(rows)

    report["MAE_Change_From_First_Percent"] = np.nan
    report["RMSE_Change_From_First_Percent"] = np.nan

    first_mae = report.iloc[0]["MAE"]
    first_rmse = report.iloc[0]["RMSE"]

    if first_mae != 0:
        report["MAE_Change_From_First_Percent"] = (
            (report["MAE"] - first_mae)
            / abs(first_mae)
            * 100
        )

    if first_rmse != 0:
        report["RMSE_Change_From_First_Percent"] = (
            (report["RMSE"] - first_rmse)
            / abs(first_rmse)
            * 100
        )

    return report


# ------------------------------------------------------------
# 55.5 â€” CLASSIFY PERFORMANCE CONSISTENCY
# ------------------------------------------------------------

def classify_demand_generalization_consistency(
    report,
):
    """Apply a transparent heuristic to segment-level MAE."""

    if report is None or report.empty:
        return {
            "status": "Insufficient data",
            "mae_variation_percent": np.nan,
            "interpretation": (
                "No segment metrics are available."
            ),
        }

    mae_values = pd.to_numeric(
        report["MAE"],
        errors="coerce",
    ).dropna()

    if len(mae_values) < 2:
        return {
            "status": "Insufficient segments",
            "mae_variation_percent": np.nan,
            "interpretation": (
                "At least two valid segments are needed for comparison."
            ),
        }

    average_mae = float(
        mae_values.mean()
    )

    if average_mae == 0:
        variation = (
            0.0
            if float(mae_values.std(ddof=0)) == 0
            else np.nan
        )
    else:
        variation = float(
            mae_values.std(ddof=0)
            / abs(average_mae)
            * 100
        )

    if pd.isna(variation):
        status = "Review"
        interpretation = (
            "MAE variation cannot be summarized reliably because "
            "the average MAE is zero while segment errors differ."
        )
    elif variation <= 10:
        status = "Relatively stable"
        interpretation = (
            "Segment MAE values vary relatively little under this "
            "heuristic. This does not prove generalization to future data."
        )
    elif variation <= 25:
        status = "Moderate variation"
        interpretation = (
            "Segment MAE values vary moderately. Inspect the periods "
            "with the largest errors."
        )
    else:
        status = "High variation"
        interpretation = (
            "Segment MAE values differ substantially. Investigate "
            "demand changes, data quality and model limitations."
        )

    return {
        "status": status,
        "mae_variation_percent": variation,
        "interpretation": interpretation,
    }


# ------------------------------------------------------------
# 55.6 â€” IDENTIFY HIGH-ERROR SEGMENTS
# ------------------------------------------------------------

def identify_demand_generalization_high_error_segments(
    report,
):
    """Return segments with MAE above the overall segment median."""

    if report is None or report.empty:
        return pd.DataFrame()

    result = report.copy()

    valid_mae = pd.to_numeric(
        result["MAE"],
        errors="coerce",
    ).dropna()

    if valid_mae.empty:
        return pd.DataFrame()

    threshold = float(
        valid_mae.median()
    )

    result["Above_Median_MAE"] = (
        result["MAE"] > threshold
    )

    result["Segment_Median_MAE_Threshold"] = threshold

    return result[
        result["Above_Median_MAE"]
    ].reset_index(drop=True)


# ------------------------------------------------------------
# 55.7 â€” GENERATE INTERPRETATION
# ------------------------------------------------------------

def generate_demand_generalization_insights(
    report,
    consistency,
):
    """Generate cautious, descriptive observations."""

    insights = []

    if report is None or report.empty:
        return [
            "Upload valid predictions to inspect segment performance."
        ]

    best_index = report["MAE"].idxmin()
    worst_index = report["MAE"].idxmax()

    best_row = report.loc[best_index]
    worst_row = report.loc[worst_index]

    insights.append(
        f"Lowest MAE was observed in {best_row['Segment']} "
        f"({best_row['MAE']:.3f})."
    )

    insights.append(
        f"Highest MAE was observed in {worst_row['Segment']} "
        f"({worst_row['MAE']:.3f})."
    )

    if consistency:
        insights.append(
            f"Segment consistency assessment: "
            f"{consistency['status']}."
        )

        insights.append(
            consistency["interpretation"]
        )

    insights.extend([
        "Segment-level performance can change because demand patterns, "
        "data quality or observation counts differ across periods.",
        "This analysis evaluates predictions already supplied by the user. "
        "It does not retrain the model in each segment.",
        "A reliable future-performance estimate requires a suitable "
        "chronological validation design and consistent test conditions.",
    ])

    return insights


# ------------------------------------------------------------
# 55.8 â€” RENDER UPLOAD
