def render_demand_generalization_upload():
    """Upload actual and predicted observations."""

    uploaded_file = st.file_uploader(
        "Upload forecast evaluation CSV",
        type=["csv"],
        key="demand_generalization_upload",
        help=(
            "Required: Actual and Predicted columns. "
            "Optional: Timestamp or Date."
        ),
    )

    if uploaded_file is None:
        return None

    try:
        raw_data = pd.read_csv(
            uploaded_file
        )

        prepared_data = (
            prepare_demand_generalization_data(
                raw_data
            )
        )

        st.success(
            f"Prepared {len(prepared_data):,} valid observations."
        )

        return prepared_data

    except Exception as error:
        st.error(
            f"Could not prepare the evaluation file: {error}"
        )
        return None


