def render_demand_generalization_center():
    """Main renderer for the model reliability center."""

    st.header(
        "Forecast Model Reliability & Generalization Analysis Center"
    )

    st.markdown(
        """
        Compare forecast errors across consecutive data segments
        to investigate whether model performance remains consistent.
        """
    )

    prediction_data = (
        render_demand_generalization_upload()
    )

    if prediction_data is None or prediction_data.empty:
        st.info(
            "Upload actual and predicted values to start the analysis."
        )
        return

    minimum_segments = 2
    maximum_segments = min(
        12,
        len(prediction_data),
    )

    segment_count = st.slider(
        "Number of consecutive segments",
        min_value=minimum_segments,
        max_value=maximum_segments,
        value=min(4, maximum_segments),
        key="demand_generalization_segment_count",
    )

    segments = split_demand_generalization_segments(
        prediction_data,
        segment_count,
    )

    report = build_demand_generalization_report(
        segments
    )

    consistency = (
        classify_demand_generalization_consistency(
            report
        )
    )

    high_error_segments = (
        identify_demand_generalization_high_error_segments(
            report
        )
    )

    insights = generate_demand_generalization_insights(
        report,
        consistency,
    )

    st.divider()

    render_demand_generalization_overview(
        report,
        consistency,
    )

    st.divider()

    render_demand_generalization_charts(
        report
    )

    st.subheader(
        "Detailed Segment Metrics"
    )

    st.dataframe(
        report,
        use_container_width=True,
        hide_index=True,
    )

    st.divider()

    render_demand_generalization_high_errors(
        high_error_segments
    )

    st.divider()

    render_demand_generalization_insights(
        insights
    )

    st.divider()

    render_demand_generalization_exports(
        report,
        high_error_segments,
    )

    with st.expander(
        "Methodology & Limitations"
    ):
        st.markdown(
            """
            - Rows are split into consecutive segments after preparation.
            - When timestamps are available, valid timestamps are sorted
              before invalid timestamps.
            - Segment metrics describe the uploaded predictions only.
            - No model is retrained for individual segments.
            - MAE variation thresholds are heuristic indicators, not
              statistical guarantees.
            - Performance consistency on these observations does not
              guarantee accuracy on future ferry demand.
            """
        )

    st.caption(
        "Reliability & Generalization Center "
        f"v{DEMAND_GENERALIZATION_VERSION}"
    )


