# PART 56 START
# FERRY DEMAND ALERT & THRESHOLD MONITORING CENTER
# >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

DEMAND_ALERT_CENTER_VERSION = "1.0.0"

DEMAND_ALERT_METRICS = [
    "Sales Count",
    "Redemption Count",
]

DEMAND_ALERT_FREQUENCIES = [
    "Daily",
    "Weekly",
    "Monthly",
]


# ------------------------------------------------------------
# 56.1 â€” PREPARE TICKET DATA
# ------------------------------------------------------------

def prepare_demand_alert_data(dataframe):
    """Validate and prepare ticket records for threshold monitoring."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    required_columns = [
        "Timestamp",
        *DEMAND_ALERT_METRICS,
    ]

    missing_columns = [
        column
        for column in required_columns
        if column not in dataframe.columns
    ]

    if missing_columns:
        raise ValueError(
            "Missing required columns: "
            + ", ".join(missing_columns)
        )

    result = dataframe[required_columns].copy()

    result["Timestamp"] = pd.to_datetime(
        result["Timestamp"],
        errors="coerce",
    )

    for column in DEMAND_ALERT_METRICS:
        result[column] = pd.to_numeric(
            result[column],
            errors="coerce",
        )

    result = result.replace(
        [np.inf, -np.inf],
        np.nan,
    )

    result = result.dropna(
        subset=["Timestamp"]
    )

    result = result.sort_values(
        "Timestamp"
    ).reset_index(drop=True)

    return result


# ------------------------------------------------------------
# 56.2 â€” AGGREGATE DEMAND BY FREQUENCY
# ------------------------------------------------------------

def aggregate_demand_alert_periods(
    dataframe,
    metric,
    frequency="Daily",
):
    """Aggregate ticket counts into daily, weekly or monthly totals."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    if metric not in DEMAND_ALERT_METRICS:
        raise ValueError(
            f"Unsupported metric: {metric}"
        )

    frequency_map = {
        "Daily": "D",
        "Weekly": "W-MON",
        "Monthly": "MS",
    }

    if frequency not in frequency_map:
        raise ValueError(
            f"Unsupported frequency: {frequency}"
        )

    result = dataframe[
        ["Timestamp", metric]
    ].dropna(
        subset=["Timestamp"]
    ).copy()

    if result.empty:
        return pd.DataFrame()

    result = result.set_index(
        "Timestamp"
    )

    aggregated = (
        result[metric]
        .resample(
            frequency_map[frequency]
        )
        .sum(min_count=1)
        .rename("Demand")
        .reset_index()
    )

    return aggregated


# ------------------------------------------------------------
# 56.3 â€” CALCULATE THRESHOLD STATUS
# ------------------------------------------------------------

def calculate_demand_alert_status(
    demand,
    lower_threshold,
    upper_threshold,
):
    """Classify a period against configured demand thresholds."""

    if pd.isna(demand):
        return "Unavailable"

    if demand > upper_threshold:
        return "Above Upper Threshold"

    if demand < lower_threshold:
        return "Below Lower Threshold"

    return "Within Threshold"


# ------------------------------------------------------------
# 56.4 â€” BUILD ALERT TABLE
# ------------------------------------------------------------

def build_demand_alert_table(
    aggregated_data,
    lower_threshold,
    upper_threshold,
):
    """Generate a period-level threshold monitoring table."""

    if aggregated_data is None or aggregated_data.empty:
        return pd.DataFrame()

    if lower_threshold < 0:
        raise ValueError(
            "The lower threshold cannot be negative."
        )

    if upper_threshold < lower_threshold:
        raise ValueError(
            "The upper threshold must be greater than or equal "
            "to the lower threshold."
        )

    result = aggregated_data.copy()

    result["Lower_Threshold"] = float(
        lower_threshold
    )

    result["Upper_Threshold"] = float(
        upper_threshold
    )

    result["Alert_Status"] = result["Demand"].map(
        lambda value: calculate_demand_alert_status(
            value,
            lower_threshold,
            upper_threshold,
        )
    )

    result["Deviation_From_Upper"] = (
        result["Demand"] - upper_threshold
    )

    result["Deviation_From_Lower"] = (
        result["Demand"] - lower_threshold
    )

    return result


# ------------------------------------------------------------
# 56.5 â€” SUMMARIZE ALERTS
# ------------------------------------------------------------

def calculate_demand_alert_summary(alert_data):
    """Summarize threshold crossings and observed demand."""

    if alert_data is None or alert_data.empty:
        return {}

    demand = pd.to_numeric(
        alert_data["Demand"],
        errors="coerce",
    ).dropna()

    if demand.empty:
        return {}

    statuses = alert_data["Alert_Status"]

    above_count = int(
        (statuses == "Above Upper Threshold").sum()
    )

    below_count = int(
        (statuses == "Below Lower Threshold").sum()
    )

    within_count = int(
        (statuses == "Within Threshold").sum()
    )

    total_periods = int(
        len(alert_data)
    )

    return {
        "Total_Periods": total_periods,
        "Above_Upper_Count": above_count,
        "Below_Lower_Count": below_count,
        "Within_Threshold_Count": within_count,
        "Unavailable_Count": int(
            (statuses == "Unavailable").sum()
        ),
        "Observed_Demand_Total": float(
            demand.sum()
        ),
        "Observed_Demand_Mean": float(
            demand.mean()
        ),
        "Observed_Demand_Max": float(
            demand.max()
        ),
        "Observed_Demand_Min": float(
            demand.min()
        ),
        "Above_Threshold_Percent": (
            above_count / total_periods * 100
            if total_periods
            else 0.0
        ),
    }


# ------------------------------------------------------------
# 56.6 â€” BUILD ALERT INVESTIGATION QUEUE
# ------------------------------------------------------------

def build_demand_alert_investigation_queue(alert_data):
    """Prioritize threshold crossings for manual investigation."""

    if alert_data is None or alert_data.empty:
        return pd.DataFrame()

    result = alert_data[
        alert_data["Alert_Status"].isin([
            "Above Upper Threshold",
            "Below Lower Threshold",
        ])
    ].copy()

    if result.empty:
        return result

    result["Priority"] = np.where(
        result["Alert_Status"] == "Above Upper Threshold",
        "Review High Demand",
        "Review Low Demand",
    )

    result["Absolute_Deviation"] = np.where(
        result["Alert_Status"] == "Above Upper Threshold",
        result["Deviation_From_Upper"].abs(),
        result["Deviation_From_Lower"].abs(),
    )

    result = result.sort_values(
        "Absolute_Deviation",
        ascending=False,
    ).reset_index(drop=True)

    result.insert(
        0,
        "Investigation_Rank",
        np.arange(1, len(result) + 1),
    )

    return result


# ------------------------------------------------------------
# 56.7 â€” GENERATE MONITORING RECOMMENDATIONS
# ------------------------------------------------------------

def generate_demand_alert_recommendations(
    summary,
):
    """Create descriptive recommendations from threshold results."""

    recommendations = []

    if not summary:
        return [
            "Select a valid metric and period to generate alert results."
        ]

    if summary["Above_Upper_Count"] > 0:
        recommendations.append(
            "Investigate periods above the upper threshold. Compare "
            "them with historical patterns, calendar effects and "
            "available operational records."
        )

    if summary["Below_Lower_Count"] > 0:
        recommendations.append(
            "Investigate periods below the lower threshold. Check "
            "whether the pattern reflects seasonality, data gaps or "
            "a genuine reduction in ticket activity."
        )

    if (
        summary["Above_Upper_Count"] == 0
        and summary["Below_Lower_Count"] == 0
    ):
        recommendations.append(
            "No threshold crossings were detected under the selected "
            "settings. This does not guarantee that demand is normal."
        )

    recommendations.extend([
        "Set thresholds using historical evidence and operational "
        "requirements rather than choosing arbitrary limits.",
        "Review data completeness before treating an unusually low "
        "count as a real demand decline.",
        "These alerts are based on historical observations and configured "
        "thresholds; they are not predictions of future demand.",
    ])

    return recommendations


# ------------------------------------------------------------
# 56.8 â€” RENDER MONITORING CONTROLS
# ------------------------------------------------------------

def render_demand_alert_controls(aggregated_data):
    """Render threshold configuration controls."""

    if aggregated_data is None or aggregated_data.empty:
        return None, None

    demand = pd.to_numeric(
        aggregated_data["Demand"],
        errors="coerce",
    ).dropna()

    if demand.empty:
        return None, None

    observed_min = float(
        demand.min()
    )

    observed_max = float(
        demand.max()
    )

    observed_mean = float(
        demand.mean()
    )

    observed_std = float(
        demand.std(ddof=0)
    )

    st.subheader(
        "Configure Demand Thresholds"
    )

    st.caption(
        "Defaults are derived from the selected historical data. "
        "Adjust them according to your monitoring objective."
    )

    col1, col2 = st.columns(2)

    with col1:
        lower_threshold = st.number_input(
            "Lower threshold",
            min_value=0.0,
            value=max(
                0.0,
                float(observed_min),
            ),
            key="demand_alert_lower_threshold",
        )

    with col2:
        upper_default = max(
            observed_mean + observed_std,
            observed_max,
            lower_threshold,
        )

        upper_threshold = st.number_input(
            "Upper threshold",
            min_value=0.0,
            value=float(upper_default),
            key="demand_alert_upper_threshold",
        )

    if upper_threshold < lower_threshold:
        st.error(
            "Upper threshold must be greater than or equal "
            "to the lower threshold."
        )
        return None, None

    return lower_threshold, upper_threshold


