DEMAND_RECONCILIATION_VERSION = "1.0.0"

DEMAND_RECONCILIATION_METRICS = [
    "Sales Count",
    "Redemption Count",
]

DEMAND_RECONCILIATION_FREQUENCIES = [
    "Daily",
    "Weekly",
    "Monthly",
]


# ------------------------------------------------------------
# 57.1 â€” PREPARE SOURCE DATA
# ------------------------------------------------------------

def prepare_demand_reconciliation_data(dataframe):
    """Prepare source records without silently removing invalid values."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    required_columns = [
        "Timestamp",
        *DEMAND_RECONCILIATION_METRICS,
    ]

    missing_columns = [
        column
        for column in required_columns
        if column not in dataframe.columns
    ]

    if missing_columns:
        raise ValueError(
            "Missing required columns: "
            + ", ".join(missing_columns)
        )

    result = dataframe[required_columns].copy()

    result["Timestamp"] = pd.to_datetime(
        result["Timestamp"],
        errors="coerce",
    )

    for column in DEMAND_RECONCILIATION_METRICS:
        result[column] = pd.to_numeric(
            result[column],
            errors="coerce",
        )

    result["Invalid_Timestamp"] = (
        result["Timestamp"].isna()
    )

    result["Missing_Sales_Count"] = (
        result["Sales Count"].isna()
    )

    result["Missing_Redemption_Count"] = (
        result["Redemption Count"].isna()
    )

    result["Negative_Sales_Count"] = (
        result["Sales Count"] < 0
    )

    result["Negative_Redemption_Count"] = (
        result["Redemption Count"] < 0
    )

    result["Duplicate_Timestamp"] = (
        result["Timestamp"].notna()
        & result["Timestamp"].duplicated(
            keep=False
        )
    )

    return result


# ------------------------------------------------------------
# 57.2 â€” BUILD DATA QUALITY FLAGS
# ------------------------------------------------------------

def calculate_demand_reconciliation_flags(dataframe):
    """Create record-level integrity flags."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    result = dataframe.copy()

    flag_columns = [
        "Invalid_Timestamp",
        "Missing_Sales_Count",
        "Missing_Redemption_Count",
        "Negative_Sales_Count",
        "Negative_Redemption_Count",
        "Duplicate_Timestamp",
    ]

    for column in flag_columns:
        if column not in result.columns:
            result[column] = False

    result["Issue_Count"] = result[
        flag_columns
    ].astype(int).sum(axis=1)

    result["Record_Status"] = np.select(
        [
            result["Issue_Count"] == 0,
            result["Issue_Count"] > 0,
        ],
        [
            "No Detected Issue",
            "Review Required",
        ],
        default="Unknown",
    )

    return result


# ------------------------------------------------------------
# 57.3 â€” AGGREGATE SALES AND REDEMPTIONS
# ------------------------------------------------------------

def aggregate_demand_reconciliation_periods(
    dataframe,
    frequency="Daily",
):
    """Aggregate valid timestamped records by calendar period."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    frequency_map = {
        "Daily": "D",
        "Weekly": "W-MON",
        "Monthly": "MS",
    }

    if frequency not in frequency_map:
        raise ValueError(
            f"Unsupported frequency: {frequency}"
        )

    valid = dataframe.loc[
        dataframe["Timestamp"].notna()
    ].copy()

    if valid.empty:
        return pd.DataFrame()

    valid = valid.set_index(
        "Timestamp"
    )

    aggregated = valid.resample(
        frequency_map[frequency]
    ).agg({
        "Sales Count": lambda values: values.sum(
            min_count=1
        ),
        "Redemption Count": lambda values: values.sum(
            min_count=1
        ),
    })

    aggregated = aggregated.reset_index()

    aggregated["Sales_Minus_Redemptions"] = (
        aggregated["Sales Count"]
        - aggregated["Redemption Count"]
    )

    aggregated["Combined_Count"] = (
        aggregated["Sales Count"]
        + aggregated["Redemption Count"]
    )

    aggregated["Sales_Redemption_Ratio"] = np.where(
        aggregated["Redemption Count"] > 0,
        aggregated["Sales Count"]
        / aggregated["Redemption Count"],
        np.nan,
    )

    aggregated["Period_Status"] = np.select(
        [
            aggregated["Sales Count"].isna(),
            aggregated["Redemption Count"].isna(),
            aggregated["Sales_Minus_Redemptions"] > 0,
            aggregated["Sales_Minus_Redemptions"] < 0,
        ],
        [
            "Sales Data Unavailable",
            "Redemption Data Unavailable",
            "Sales Count Higher",
            "Redemption Count Higher",
        ],
        default="Counts Equal",
    )

    return aggregated


# ------------------------------------------------------------
# 57.4 â€” RECORD-LEVEL QUALITY SUMMARY
# ------------------------------------------------------------

def calculate_demand_reconciliation_quality(flags):
    """Summarize source-record quality indicators."""

    if flags is None or flags.empty:
        return {}

    total_records = len(flags)

    issue_records = int(
        (flags["Issue_Count"] > 0).sum()
    )

    return {
        "Total_Records": int(total_records),
        "Records_With_Issues": issue_records,
        "Records_Without_Detected_Issues": int(
            total_records - issue_records
        ),
        "Invalid_Timestamps": int(
            flags["Invalid_Timestamp"].sum()
        ),
        "Missing_Sales_Values": int(
            flags["Missing_Sales_Count"].sum()
        ),
        "Missing_Redemption_Values": int(
            flags["Missing_Redemption_Count"].sum()
        ),
        "Negative_Sales_Values": int(
            flags["Negative_Sales_Count"].sum()
        ),
        "Negative_Redemption_Values": int(
            flags["Negative_Redemption_Count"].sum()
        ),
        "Duplicate_Timestamp_Records": int(
            flags["Duplicate_Timestamp"].sum()
        ),
        "Records_With_Issues_Percent": (
            issue_records / total_records * 100
            if total_records
            else 0.0
        ),
    }


# ------------------------------------------------------------
# 57.5 â€” PERIOD RECONCILIATION SUMMARY
# ------------------------------------------------------------

def calculate_demand_reconciliation_summary(
    aggregated_data,
):
    """Summarize period-level sales and redemption comparisons."""

    if aggregated_data is None or aggregated_data.empty:
        return {}

    sales = pd.to_numeric(
        aggregated_data["Sales Count"],
        errors="coerce",
    )

    redemptions = pd.to_numeric(
        aggregated_data["Redemption Count"],
        errors="coerce",
    )

    valid_sales = sales.dropna()
    valid_redemptions = redemptions.dropna()

    difference = (
        sales - redemptions
    ).dropna()

    return {
        "Total_Periods": int(
            len(aggregated_data)
        ),
        "Periods_With_Sales": int(
            sales.notna().sum()
        ),
        "Periods_With_Redemptions": int(
            redemptions.notna().sum()
        ),
        "Periods_Sales_Higher": int(
            (
                aggregated_data["Period_Status"]
                == "Sales Count Higher"
            ).sum()
        ),
        "Periods_Redemptions_Higher": int(
            (
                aggregated_data["Period_Status"]
                == "Redemption Count Higher"
            ).sum()
        ),
        "Periods_Counts_Equal": int(
            (
                aggregated_data["Period_Status"]
                == "Counts Equal"
            ).sum()
        ),
        "Total_Sales_Observed": float(
            valid_sales.sum()
        ),
        "Total_Redemptions_Observed": float(
            valid_redemptions.sum()
        ),
        "Mean_Period_Difference": (
            float(difference.mean())
            if not difference.empty
            else np.nan
        ),
        "Largest_Positive_Difference": (
            float(difference.max())
            if not difference.empty
            else np.nan
        ),
        "Largest_Negative_Difference": (
            float(difference.min())
            if not difference.empty
            else np.nan
        ),
    }


# ------------------------------------------------------------
# 57.6 â€” BUILD INVESTIGATION QUEUE
# ------------------------------------------------------------

def build_demand_reconciliation_queue(flags):
    """Prioritize source records that need manual review."""

    if flags is None or flags.empty:
        return pd.DataFrame()

    queue = flags.loc[
        flags["Issue_Count"] > 0
    ].copy()

    if queue.empty:
        return queue

    queue = queue.sort_values(
        by=[
            "Issue_Count",
            "Timestamp",
        ],
        ascending=[
            False,
            True,
        ],
        na_position="last",
    )

    queue.insert(
        0,
        "Review_Rank",
        np.arange(1, len(queue) + 1),
    )

    return queue


# ------------------------------------------------------------
# 57.7 â€” BUILD RECOMMENDATIONS
# ------------------------------------------------------------

def generate_demand_reconciliation_recommendations(
    quality_summary,
    reconciliation_summary,
):
    """Generate follow-up actions from observed data quality."""

    recommendations = []

    if not quality_summary:
        return [
            "Load valid source records before running reconciliation."
        ]

    if quality_summary["Invalid_Timestamps"] > 0:
        recommendations.append(
            "Review rows with invalid timestamps because they cannot "
            "be assigned reliably to a calendar period."
        )

    if (
        quality_summary["Missing_Sales_Values"] > 0
        or quality_summary["Missing_Redemption_Values"] > 0
    ):
        recommendations.append(
            "Investigate missing sales or redemption values before "
            "drawing conclusions from period totals."
        )

    if (
        quality_summary["Negative_Sales_Values"] > 0
        or quality_summary["Negative_Redemption_Values"] > 0
    ):
        recommendations.append(
            "Review negative counts. Confirm whether they represent "
            "corrections, refunds, data-entry errors or another "
            "documented process."
        )

    if quality_summary["Duplicate_Timestamp_Records"] > 0:
        recommendations.append(
            "Inspect repeated timestamps. Multiple records at the "
            "same timestamp may be legitimate, so do not delete them "
            "without checking the source meaning."
        )

    if reconciliation_summary:
        if (
            reconciliation_summary["Periods_Sales_Higher"] > 0
        ):
            recommendations.append(
                "Review periods where sales counts exceed redemption "
                "counts, using ticket definitions and reporting rules "
                "to understand the difference."
            )

        if (
            reconciliation_summary[
                "Periods_Redemptions_Higher"
            ] > 0
        ):
            recommendations.append(
                "Review periods where redemption counts exceed sales "
                "counts. Timing differences, historical ticket sales "
                "or reporting scope may contribute."
            )

    if not recommendations:
        recommendations.append(
            "No issues were detected by the selected checks. This "
            "does not prove that every source record is correct."
        )

    recommendations.append(
        "Sales-minus-redemptions is a numerical comparison only; "
        "it is not automatically a count of unredeemed tickets."
    )

    return recommendations


