# ------------------------------------------------------------
# 57.14 â€” MAIN RECONCILIATION CENTER
# ------------------------------------------------------------

def render_demand_reconciliation_center():
    """Main renderer for Part 57."""

    st.header(
        "Ferry Demand Data Reconciliation & Consistency Center"
    )

    st.markdown(
        """
        Review source-record quality and compare ticket sales with
        redemptions over daily, weekly or monthly periods.
        """
    )

    frequency = st.selectbox(
        "Reconciliation frequency",
        options=DEMAND_RECONCILIATION_FREQUENCIES,
        key="demand_reconciliation_frequency",
    )

    try:
        raw_data = load_ticket_dataframe(
            str(DEFAULT_DATASET_PATH)
        )

        prepared_data = prepare_demand_reconciliation_data(
            raw_data
        )

        flags = calculate_demand_reconciliation_flags(
            prepared_data
        )

        aggregated_data = (
            aggregate_demand_reconciliation_periods(
                prepared_data,
                frequency,
            )
        )

    except Exception as error:
        st.error(
            f"Unable to prepare reconciliation data: {error}"
        )
        return

    if prepared_data.empty:
        st.warning(
            "No source records are available."
        )
        return

    quality_summary = calculate_demand_reconciliation_quality(
        flags
    )

    reconciliation_summary = (
        calculate_demand_reconciliation_summary(
            aggregated_data
        )
    )

    investigation_queue = (
        build_demand_reconciliation_queue(
            flags
        )
    )

    recommendations = (
        generate_demand_reconciliation_recommendations(
            quality_summary,
            reconciliation_summary,
        )
    )

    st.divider()

    st.subheader(
        "Source Data Quality"
    )

    render_demand_reconciliation_quality_overview(
        quality_summary
    )

    st.divider()

    st.subheader(
        "Period-Level Reconciliation"
    )

    render_demand_reconciliation_period_metrics(
        reconciliation_summary
    )

    st.divider()

    render_demand_reconciliation_charts(
        aggregated_data
    )

    st.subheader(
        "Period Reconciliation Table"
    )

    st.dataframe(
        aggregated_data,
        use_container_width=True,
        hide_index=True,
    )

    st.divider()

    render_demand_reconciliation_investigation_queue(
        investigation_queue
    )

    st.divider()

    render_demand_reconciliation_recommendations(
        recommendations
    )

    st.divider()

    render_demand_reconciliation_exports(
        aggregated_data,
        flags,
        investigation_queue,
    )

    with st.expander(
        "Methodology & Limitations"
    ):
        st.markdown(
            """
            - Quality flags identify records that deserve review; they
              do not automatically prove that a record is incorrect.
            - Multiple records can legitimately share a timestamp.
            - Negative counts may represent corrections or other
              documented source-system behavior.
            - Calendar periods without records are not automatically
              confirmed data failures.
            - Sales and redemption totals can differ because of timing,
              historical sales or differences in reporting scope.
            - The difference between sales and redemptions is not
              automatically the number of unused tickets.
            """
        )

    st.caption(
        "Demand Data Reconciliation & Consistency Center "
        f"v{DEMAND_RECONCILIATION_VERSION}"
    )


