DEMAND_PERIOD_COMPARISON_VERSION = "1.0.0"

DEMAND_PERIOD_COMPARISON_METRICS = [
    "Sales Count",
    "Redemption Count",
]

DEMAND_PERIOD_COMPARISON_FREQUENCIES = [
    "Daily",
    "Weekly",
    "Monthly",
]


# ------------------------------------------------------------
# 58.1 â€” PREPARE SOURCE DATA
# ------------------------------------------------------------

def prepare_demand_period_comparison_data(dataframe):
    """Prepare timestamped ticket counts for period comparisons."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    required_columns = [
        "Timestamp",
        *DEMAND_PERIOD_COMPARISON_METRICS,
    ]

    missing_columns = [
        column
        for column in required_columns
        if column not in dataframe.columns
    ]

    if missing_columns:
        raise ValueError(
            "Missing required columns: "
            + ", ".join(missing_columns)
        )

    result = dataframe[required_columns].copy()

    result["Timestamp"] = pd.to_datetime(
        result["Timestamp"],
        errors="coerce",
    )

    for column in DEMAND_PERIOD_COMPARISON_METRICS:
        result[column] = pd.to_numeric(
            result[column],
            errors="coerce",
        )

    result = result.replace(
        [np.inf, -np.inf],
        np.nan,
    )

    result = result.dropna(
        subset=["Timestamp"]
    )

    result = result.sort_values(
        "Timestamp"
    ).reset_index(drop=True)

    return result


# ------------------------------------------------------------
# 58.2 â€” AGGREGATE PERIOD DATA
# ------------------------------------------------------------

def aggregate_demand_period_comparison_data(
    dataframe,
    metric,
    frequency="Daily",
):
    """Aggregate ticket counts into comparable calendar periods."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    if metric not in DEMAND_PERIOD_COMPARISON_METRICS:
        raise ValueError(
            f"Unsupported metric: {metric}"
        )

    frequency_map = {
        "Daily": "D",
        "Weekly": "W-MON",
        "Monthly": "MS",
    }

    if frequency not in frequency_map:
        raise ValueError(
            f"Unsupported frequency: {frequency}"
        )

    result = dataframe[
        ["Timestamp", metric]
    ].dropna(
        subset=["Timestamp"]
    ).copy()

    if result.empty:
        return pd.DataFrame()

    result = result.set_index(
        "Timestamp"
    )

    aggregated = (
        result[metric]
        .resample(
            frequency_map[frequency]
        )
        .sum(min_count=1)
        .rename("Demand")
        .reset_index()
    )

    return aggregated


# ------------------------------------------------------------
# 58.3 â€” CALCULATE COMPARISON METRICS
# ------------------------------------------------------------

def calculate_demand_period_comparison_metrics(
    first_period_data,
    second_period_data,
):
    """Compare two sets of observed demand values."""

    def summarize_period(period_data):
        if (
            period_data is None
            or period_data.empty
            or "Demand" not in period_data.columns
        ):
            return {
                "Period_Count": 0,
                "Demand_Total": np.nan,
                "Demand_Mean": np.nan,
                "Demand_Median": np.nan,
                "Demand_Max": np.nan,
                "Demand_Min": np.nan,
            }

        demand = pd.to_numeric(
            period_data["Demand"],
            errors="coerce",
        ).dropna()

        if demand.empty:
            return {
                "Period_Count": 0,
                "Demand_Total": np.nan,
                "Demand_Mean": np.nan,
                "Demand_Median": np.nan,
                "Demand_Max": np.nan,
                "Demand_Min": np.nan,
            }

        return {
            "Period_Count": int(len(demand)),
            "Demand_Total": float(demand.sum()),
            "Demand_Mean": float(demand.mean()),
            "Demand_Median": float(demand.median()),
            "Demand_Max": float(demand.max()),
            "Demand_Min": float(demand.min()),
        }

    first_summary = summarize_period(
        first_period_data
    )

    second_summary = summarize_period(
        second_period_data
    )

    first_total = first_summary["Demand_Total"]
    second_total = second_summary["Demand_Total"]

    first_mean = first_summary["Demand_Mean"]
    second_mean = second_summary["Demand_Mean"]

    if (
        pd.isna(first_total)
        or pd.isna(second_total)
    ):
        total_change = np.nan
        total_change_percent = np.nan
    else:
        total_change = second_total - first_total

        total_change_percent = (
            total_change / abs(first_total) * 100
            if first_total != 0
            else np.nan
        )

    mean_change = (
        second_mean - first_mean
        if not pd.isna(first_mean)
        and not pd.isna(second_mean)
        else np.nan
    )

    mean_change_percent = (
        mean_change / abs(first_mean) * 100
        if not pd.isna(mean_change)
        and first_mean != 0
        else np.nan
    )

    return {
        "First_Period": first_summary,
        "Second_Period": second_summary,
        "Total_Change": total_change,
        "Total_Change_Percent": total_change_percent,
        "Mean_Change": mean_change,
        "Mean_Change_Percent": mean_change_percent,
    }


# ------------------------------------------------------------
# 58.4 â€” BUILD COMPARISON REPORT
# ------------------------------------------------------------

def build_demand_period_comparison_report(
    first_data,
    second_data,
    first_label,
    second_label,
    metric,
    frequency,
):
    """Create a compact comparison report."""

    metrics = calculate_demand_period_comparison_metrics(
        first_data,
        second_data,
    )

    first_summary = metrics["First_Period"]
    second_summary = metrics["Second_Period"]

    report_rows = [
        {
            "Metric": "Demand Total",
            first_label: first_summary["Demand_Total"],
            second_label: second_summary["Demand_Total"],
            "Absolute Change": metrics["Total_Change"],
            "Percentage Change": metrics[
                "Total_Change_Percent"
            ],
        },
        {
            "Metric": "Average Demand Per Observed Period",
            first_label: first_summary["Demand_Mean"],
            second_label: second_summary["Demand_Mean"],
            "Absolute Change": metrics["Mean_Change"],
            "Percentage Change": metrics[
                "Mean_Change_Percent"
            ],
        },
        {
            "Metric": "Median Demand",
            first_label: first_summary["Demand_Median"],
            second_label: second_summary["Demand_Median"],
            "Absolute Change": (
                second_summary["Demand_Median"]
                - first_summary["Demand_Median"]
                if not pd.isna(
                    first_summary["Demand_Median"]
                )
                and not pd.isna(
                    second_summary["Demand_Median"]
                )
                else np.nan
            ),
            "Percentage Change": np.nan,
        },
        {
            "Metric": "Maximum Period Demand",
            first_label: first_summary["Demand_Max"],
            second_label: second_summary["Demand_Max"],
            "Absolute Change": (
                second_summary["Demand_Max"]
                - first_summary["Demand_Max"]
                if not pd.isna(
                    first_summary["Demand_Max"]
                )
                and not pd.isna(
                    second_summary["Demand_Max"]
                )
                else np.nan
            ),
            "Percentage Change": np.nan,
        },
    ]

    report = pd.DataFrame(
        report_rows
    )

    report.insert(
        0,
        "Demand Metric",
        metric,
    )

    report.insert(
        1,
        "Frequency",
        frequency,
    )

    report.insert(
        2,
        "First Period Label",
        first_label,
    )

    report.insert(
        3,
        "Second Period Label",
        second_label,
    )

    return report, metrics


# ------------------------------------------------------------
# 58.5 â€” GENERATE COMPARISON INSIGHTS
# ------------------------------------------------------------

def generate_demand_period_comparison_insights(
    metrics,
    first_label,
    second_label,
):
    """Generate descriptive insights from period comparisons."""

    insights = []

    change_percent = metrics.get(
        "Total_Change_Percent",
        np.nan,
    )

    total_change = metrics.get(
        "Total_Change",
        np.nan,
    )

    first_summary = metrics.get(
        "First_Period",
        {},
    )

    second_summary = metrics.get(
        "Second_Period",
        {},
    )

    first_total = first_summary.get(
        "Demand_Total",
        np.nan,
    )

    second_total = second_summary.get(
        "Demand_Total",
        np.nan,
    )

    if (
        pd.isna(first_total)
        or pd.isna(second_total)
    ):
        insights.append(
            "A valid comparison could not be calculated for both periods."
        )

    elif first_total == 0:
        insights.append(
            f"{first_label} has zero observed total demand. "
            "Percentage change from a zero baseline is undefined."
        )

        if second_total > 0:
            insights.append(
                f"{second_label} has positive observed demand, "
                "while the first period has zero recorded demand."
            )

    elif total_change > 0:
        insights.append(
            f"Observed demand increased by {total_change:,.2f} "
            f"between {first_label} and {second_label}."
        )

    elif total_change < 0:
        insights.append(
            f"Observed demand decreased by {abs(total_change):,.2f} "
            f"between {first_label} and {second_label}."
        )

    else:
        insights.append(
            "Both periods have the same observed total demand."
        )

    if not pd.isna(change_percent):
        insights.append(
            f"The total-demand change is {change_percent:+.2f}% "
            "relative to the first period."
        )

    insights.append(
        "Check whether both periods cover comparable numbers of "
        "days and have similar data completeness before interpreting "
        "their total-demand difference."
    )

    return insights


# ------------------------------------------------------------
# 58.6 â€” RENDER PERIOD COMPARISON CONTROLS
# ------------------------------------------------------------

def render_demand_period_comparison_controls(
    aggregated_data,
):
    """Allow the user to select two date ranges."""

    if (
        aggregated_data is None
        or aggregated_data.empty
    ):
        return None

    available_dates = pd.to_datetime(
        aggregated_data["Timestamp"],
        errors="coerce",
    ).dropna()

    if available_dates.empty:
        return None

    minimum_date = available_dates.min().date()
    maximum_date = available_dates.max().date()

    st.subheader(
        "Select Two Historical Periods"
    )

    st.caption(
        "Choose two date ranges. The report compares observed counts "
        "within each selected range."
    )

    col1, col2 = st.columns(2)

    with col1:
        st.markdown(
            "**First period**"
        )

        first_start = st.date_input(
            "Start date",
            value=minimum_date,
            min_value=minimum_date,
            max_value=maximum_date,
            key="demand_period_compare_first_start",
        )

        first_end = st.date_input(
            "End date",
            value=minimum_date,
            min_value=minimum_date,
            max_value=maximum_date,
            key="demand_period_compare_first_end",
        )

    with col2:
        st.markdown(
            "**Second period**"
        )

        second_start = st.date_input(
            "Start date ",
            value=maximum_date,
            min_value=minimum_date,
            max_value=maximum_date,
            key="demand_period_compare_second_start",
        )

        second_end = st.date_input(
            "End date ",
            value=maximum_date,
            min_value=minimum_date,
            max_value=maximum_date,
            key="demand_period_compare_second_end",
        )

    if first_start > first_end:
        st.error(
            "The first period's start date must not be after "
            "its end date."
        )
        return None

    if second_start > second_end:
        st.error(
            "The second period's start date must not be after "
            "its end date."
        )
        return None

    if not (
        first_end < second_start
        or second_end < first_start
    ):
        st.warning(
            "The selected periods overlap. Interpret the comparison "
            "carefully because some observations may be included "
            "in both periods."
        )

    return {
        "first_start": first_start,
        "first_end": first_end,
        "second_start": second_start,
        "second_end": second_end,
    }


# ------------------------------------------------------------
# 58.7 â€” FILTER SELECTED PERIODS
# ------------------------------------------------------------

def filter_demand_period_comparison_range(
    aggregated_data,
    start_date,
    end_date,
):
    """Filter aggregated observations to an inclusive date range."""

    if (
        aggregated_data is None
        or aggregated_data.empty
    ):
        return pd.DataFrame()

    timestamps = pd.to_datetime(
        aggregated_data["Timestamp"],
        errors="coerce",
    )

    start_timestamp = pd.Timestamp(
        start_date
    )

    end_timestamp = (
        pd.Timestamp(end_date)
        + pd.Timedelta(days=1)
    )

    mask = (
        (timestamps >= start_timestamp)
        & (timestamps < end_timestamp)
    )

    return aggregated_data.loc[
        mask
    ].copy().reset_index(drop=True)


