def render_demand_period_comparison_chart(
    first_data,
    second_data,
    first_label,
    second_label,
):
    """Compare demand observations within the selected periods."""

    st.subheader(
        "Demand Distribution Across Selected Periods"
    )

    first_chart = first_data[
        ["Timestamp", "Demand"]
    ].copy()

    first_chart["Period"] = first_label

    second_chart = second_data[
        ["Timestamp", "Demand"]
    ].copy()

    second_chart["Period"] = second_label

    first_chart["Timestamp"] = pd.to_datetime(
        first_chart["Timestamp"]
    )

    second_chart["Timestamp"] = pd.to_datetime(
        second_chart["Timestamp"]
    )

    combined = pd.concat(
        [
            first_chart,
            second_chart,
        ],
        ignore_index=True,
    )

    if combined.empty:
        st.info(
            "No observations are available for the selected periods."
        )
        return

    st.bar_chart(
        combined.groupby(
            "Period"
        )["Demand"].mean(),
        use_container_width=True,
    )

    st.caption(
        "The chart shows average demand per observed aggregated period, "
        "not a forecast of future demand."
    )


