def render_demand_period_comparison_center():
    """Main Streamlit renderer for Part 58."""

    st.header(
        "Ferry Demand Reporting & Period Comparison Center"
    )

    st.markdown(
        """
        Compare historical ticket sales or redemptions across two
        selected periods and generate an exportable report.
        """
    )

    metric = st.selectbox(
        "Select demand metric",
        options=DEMAND_PERIOD_COMPARISON_METRICS,
        key="demand_period_comparison_metric",
    )

    frequency = st.selectbox(
        "Select aggregation frequency",
        options=DEMAND_PERIOD_COMPARISON_FREQUENCIES,
        key="demand_period_comparison_frequency",
    )

    try:
        raw_data = load_ticket_dataframe(
            str(DEFAULT_DATASET_PATH)
        )

        prepared_data = (
            prepare_demand_period_comparison_data(
                raw_data
            )
        )

        aggregated_data = (
            aggregate_demand_period_comparison_data(
                prepared_data,
                metric,
                frequency,
            )
        )

    except Exception as error:
        st.error(
            f"Unable to prepare period comparison: {error}"
        )
        return

    if aggregated_data.empty:
        st.warning(
            "No valid aggregated observations are available."
        )
        return

    selected_ranges = (
        render_demand_period_comparison_controls(
            aggregated_data
        )
    )

    if selected_ranges is None:
        return

    first_data = filter_demand_period_comparison_range(
        aggregated_data,
        selected_ranges["first_start"],
        selected_ranges["first_end"],
    )

    second_data = filter_demand_period_comparison_range(
        aggregated_data,
        selected_ranges["second_start"],
        selected_ranges["second_end"],
    )

    if first_data.empty or second_data.empty:
        st.warning(
            "At least one selected period has no aggregated "
            "observations. Please adjust the date ranges."
        )
        return

    first_label = (
        f"{selected_ranges['first_start']} to "
        f"{selected_ranges['first_end']}"
    )

    second_label = (
        f"{selected_ranges['second_start']} to "
        f"{selected_ranges['second_end']}"
    )

    report, metrics = build_demand_period_comparison_report(
        first_data,
        second_data,
        first_label,
        second_label,
        metric,
        frequency,
    )

    insights = generate_demand_period_comparison_insights(
        metrics,
        first_label,
        second_label,
    )

    st.divider()

    render_demand_period_comparison_overview(
        metrics,
        first_label,
        second_label,
    )

    st.divider()

    render_demand_period_comparison_chart(
        first_data,
        second_data,
        first_label,
        second_label,
    )

    st.subheader(
        "Detailed Comparison Report"
    )

    st.dataframe(
        report,
        use_container_width=True,
        hide_index=True,
    )

    st.divider()

    render_demand_period_comparison_insights(
        insights
    )

    st.download_button(
        label="Download Period Comparison CSV",
        data=report.to_csv(
            index=False
        ).encode("utf-8"),
        file_name="ferry_demand_period_comparison.csv",
        mime="text/csv",
        key="demand_period_comparison_export",
    )

    with st.expander(
        "Methodology & Limitations"
    ):
        st.markdown(
            """
            - The report compares historical observations only.
            - Percentage change is undefined when the first period's
              total demand is zero.
            - Different period lengths can make total-count comparisons
              misleading; compare average demand as well.
            - Partial calendar periods and missing records can affect
              the results.
            - Sales and redemptions are ticket-record measures and do
              not establish actual passenger boarding counts.
            - This module does not predict future demand.
            """
        )

    st.caption(
        "Demand Reporting & Period Comparison Center "
        f"v{DEMAND_PERIOD_COMPARISON_VERSION}"
    )


