DEMAND_PROFILE_CENTER_VERSION = "1.0.0"

DEMAND_PROFILE_METRICS = [
    "Sales Count",
    "Redemption Count",
]


# ------------------------------------------------------------
# 59.1 â€” PREPARE DATA FOR PROFILING
# ------------------------------------------------------------

def prepare_demand_profile_data(dataframe):
    """Prepare ticket data and retain source-quality indicators."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    required_columns = [
        "Timestamp",
        *DEMAND_PROFILE_METRICS,
    ]

    missing_columns = [
        column
        for column in required_columns
        if column not in dataframe.columns
    ]

    if missing_columns:
        raise ValueError(
            "Missing required columns: "
            + ", ".join(missing_columns)
        )

    result = dataframe[required_columns].copy()

    result["Timestamp"] = pd.to_datetime(
        result["Timestamp"],
        errors="coerce",
    )

    result["Invalid_Timestamp"] = (
        result["Timestamp"].isna()
    )

    for column in DEMAND_PROFILE_METRICS:
        result[column] = pd.to_numeric(
            result[column],
            errors="coerce",
        )

    result["Missing_Sales_Count"] = (
        result["Sales Count"].isna()
    )

    result["Missing_Redemption_Count"] = (
        result["Redemption Count"].isna()
    )

    return result


# ------------------------------------------------------------
# 59.2 â€” CALCULATE NUMERIC PROFILE
# ------------------------------------------------------------

def calculate_demand_profile_statistics(
    dataframe,
    metric,
):
    """Calculate descriptive statistics for a selected metric."""

    if dataframe is None or dataframe.empty:
        return {}

    if metric not in DEMAND_PROFILE_METRICS:
        raise ValueError(
            f"Unsupported metric: {metric}"
        )

    values = pd.to_numeric(
        dataframe[metric],
        errors="coerce",
    )

    finite_values = values[
        np.isfinite(values)
    ].dropna()

    total_records = len(values)
    valid_count = len(finite_values)
    missing_count = int(
        values.isna().sum()
    )

    if finite_values.empty:
        return {
            "Metric": metric,
            "Total_Records": total_records,
            "Valid_Count": 0,
            "Missing_Count": missing_count,
            "Mean": np.nan,
            "Median": np.nan,
            "Standard_Deviation": np.nan,
            "Minimum": np.nan,
            "Maximum": np.nan,
            "Q1": np.nan,
            "Q3": np.nan,
            "IQR": np.nan,
            "Skewness": np.nan,
            "Zero_Count": 0,
            "Negative_Count": 0,
            "Unique_Count": 0,
        }

    q1 = float(
        finite_values.quantile(0.25)
    )

    q3 = float(
        finite_values.quantile(0.75)
    )

    return {
        "Metric": metric,
        "Total_Records": int(total_records),
        "Valid_Count": int(valid_count),
        "Missing_Count": missing_count,
        "Mean": float(finite_values.mean()),
        "Median": float(finite_values.median()),
        "Standard_Deviation": float(
            finite_values.std(ddof=1)
        ) if valid_count > 1 else np.nan,
        "Minimum": float(finite_values.min()),
        "Maximum": float(finite_values.max()),
        "Q1": q1,
        "Q3": q3,
        "IQR": float(q3 - q1),
        "Skewness": float(
            finite_values.skew()
        ) if valid_count > 2 else np.nan,
        "Zero_Count": int(
            (finite_values == 0).sum()
        ),
        "Negative_Count": int(
            (finite_values < 0).sum()
        ),
        "Unique_Count": int(
            finite_values.nunique()
        ),
    }


# ------------------------------------------------------------
# 59.3 â€” IDENTIFY IQR-BASED OUTLIERS
# ------------------------------------------------------------

def identify_demand_profile_outliers(
    dataframe,
    metric,
    multiplier=1.5,
):
    """Identify observations outside the IQR fences."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    if metric not in DEMAND_PROFILE_METRICS:
        raise ValueError(
            f"Unsupported metric: {metric}"
        )

    if multiplier <= 0:
        raise ValueError(
            "The IQR multiplier must be greater than zero."
        )

    result = dataframe[
        ["Timestamp", metric]
    ].copy()

    result[metric] = pd.to_numeric(
        result[metric],
        errors="coerce",
    )

    valid = result[metric].replace(
        [np.inf, -np.inf],
        np.nan,
    ).dropna()

    if valid.empty:
        return pd.DataFrame()

    q1 = valid.quantile(0.25)
    q3 = valid.quantile(0.75)
    iqr = q3 - q1

    lower_bound = q1 - multiplier * iqr
    upper_bound = q3 + multiplier * iqr

    result["Lower_IQR_Bound"] = float(
        lower_bound
    )

    result["Upper_IQR_Bound"] = float(
        upper_bound
    )

    result["Outlier_Status"] = np.select(
        [
            result[metric] < lower_bound,
            result[metric] > upper_bound,
        ],
        [
            "Below Lower Bound",
            "Above Upper Bound",
        ],
        default="Within Bounds",
    )

    result["Outlier_Deviation"] = np.select(
        [
            result[metric] < lower_bound,
            result[metric] > upper_bound,
        ],
        [
            lower_bound - result[metric],
            result[metric] - upper_bound,
        ],
        default=0.0,
    )

    return result


# ------------------------------------------------------------
# 59.4 â€” CREATE FREQUENCY DISTRIBUTION
# ------------------------------------------------------------

def calculate_demand_profile_distribution(
    dataframe,
    metric,
    bin_count=20,
):
    """Create a numeric frequency distribution."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    if metric not in DEMAND_PROFILE_METRICS:
        raise ValueError(
            f"Unsupported metric: {metric}"
        )

    if not 2 <= int(bin_count) <= 100:
        raise ValueError(
            "Bin count must be between 2 and 100."
        )

    values = pd.to_numeric(
        dataframe[metric],
        errors="coerce",
    ).replace(
        [np.inf, -np.inf],
        np.nan,
    ).dropna()

    if values.empty:
        return pd.DataFrame()

    if values.nunique() == 1:
        return pd.DataFrame({
            "Range": [
                f"Value = {values.iloc[0]:g}"
            ],
            "Frequency": [
                int(len(values))
            ],
            "Percentage": [
                100.0
            ],
        })

    categories = pd.cut(
        values,
        bins=int(bin_count),
        duplicates="drop",
    )

    counts = categories.value_counts(
        sort=False,
        dropna=False,
    )

    distribution = pd.DataFrame({
        "Range": counts.index.astype(str),
        "Frequency": counts.values,
    })

    total = distribution["Frequency"].sum()

    distribution["Percentage"] = (
        distribution["Frequency"] / total * 100
        if total
        else 0.0
    )

    return distribution.reset_index(
        drop=True
    )


# ------------------------------------------------------------
# 59.5 â€” PROFILE TIMESTAMP COVERAGE
# ------------------------------------------------------------

def calculate_demand_profile_timestamp_summary(
    dataframe,
):
    """Summarize timestamp coverage and record repetition."""

    if dataframe is None or dataframe.empty:
        return {}

    timestamps = pd.to_datetime(
        dataframe["Timestamp"],
        errors="coerce",
    )

    valid_timestamps = timestamps.dropna()

    return {
        "Total_Records": int(len(dataframe)),
        "Valid_Timestamps": int(
            timestamps.notna().sum()
        ),
        "Invalid_Timestamps": int(
            timestamps.isna().sum()
        ),
        "Distinct_Timestamps": int(
            valid_timestamps.nunique()
        ),
        "Repeated_Timestamp_Rows": int(
            valid_timestamps.duplicated(
                keep=False
            ).sum()
        ),
        "First_Timestamp": (
            valid_timestamps.min()
            if not valid_timestamps.empty
            else pd.NaT
        ),
        "Last_Timestamp": (
            valid_timestamps.max()
            if not valid_timestamps.empty
            else pd.NaT
        ),
    }


# ------------------------------------------------------------
# 59.6 â€” BUILD STATISTICAL PROFILE REPORT
# ------------------------------------------------------------

def build_demand_profile_report(dataframe):
    """Combine descriptive statistics into a report."""

    rows = []

    for metric in DEMAND_PROFILE_METRICS:
        summary = calculate_demand_profile_statistics(
            dataframe,
            metric,
        )

        if summary:
            rows.append(summary)

    if not rows:
        return pd.DataFrame()

    return pd.DataFrame(
        rows
    )


# ------------------------------------------------------------
# 59.7 â€” RENDER STATISTICAL OVERVIEW
# ------------------------------------------------------------

def render_demand_profile_overview(
    dataframe,
    metric,
):
    """Display descriptive statistics."""

    summary = calculate_demand_profile_statistics(
        dataframe,
        metric,
    )

    if not summary or summary["Valid_Count"] == 0:
        st.warning(
            "No valid numeric values are available for this metric."
        )
        return

    col1, col2, col3 = st.columns(3)

    col1.metric(
        "Mean",
        f"{summary['Mean']:,.2f}",
    )

    col2.metric(
        "Median",
        f"{summary['Median']:,.2f}",
    )

    col3.metric(
        "Standard Deviation",
        (
            f"{summary['Standard_Deviation']:,.2f}"
            if not pd.isna(
                summary["Standard_Deviation"]
            )
            else "Unavailable"
        ),
    )

    col4, col5, col6 = st.columns(3)

    col4.metric(
        "Minimum",
        f"{summary['Minimum']:,.2f}",
    )

    col5.metric(
        "Maximum",
        f"{summary['Maximum']:,.2f}",
    )

    col6.metric(
        "Unique Values",
        f"{summary['Unique_Count']:,}",
    )

    st.caption(
        f"Valid values: {summary['Valid_Count']:,} | "
        f"Missing values: {summary['Missing_Count']:,} | "
        f"Zero values: {summary['Zero_Count']:,} | "
        f"Negative values: {summary['Negative_Count']:,}"
    )


# ------------------------------------------------------------
# 59.8 â€” RENDER DISTRIBUTION
# ------------------------------------------------------------

def render_demand_profile_distribution(
    dataframe,
    metric,
    bin_count,
):
    """Render histogram and distribution table."""

    st.subheader(
        "Demand Frequency Distribution"
    )

    values = pd.to_numeric(
        dataframe[metric],
        errors="coerce",
    ).replace(
        [np.inf, -np.inf],
        np.nan,
    ).dropna()

    if values.empty:
        st.info(
            "No valid numeric values are available."
        )
        return

    if values.nunique() == 1:
        st.info(
            "All valid observations have the same value."
        )
    else:
        histogram = pd.cut(
            values,
            bins=int(bin_count),
            duplicates="drop",
        ).value_counts(
            sort=False
        )

        chart_data = pd.DataFrame({
            "Demand Range": histogram.index.astype(str),
            "Frequency": histogram.values,
        })

        st.bar_chart(
            chart_data.set_index(
                "Demand Range"
            ),
            use_container_width=True,
        )

    distribution = calculate_demand_profile_distribution(
        dataframe,
        metric,
        bin_count,
    )

    if not distribution.empty:
        with st.expander(
            "View Distribution Table"
        ):
            st.dataframe(
                distribution,
                use_container_width=True,
                hide_index=True,
            )


# ------------------------------------------------------------
# 59.9 â€” RENDER OUTLIER ANALYSIS
# ------------------------------------------------------------

def render_demand_profile_outlier_analysis(
    dataframe,
    metric,
    multiplier,
):
    """Display IQR-based outlier analysis."""

    st.subheader(
        "IQR-Based Outlier Analysis"
    )

    outlier_data = identify_demand_profile_outliers(
        dataframe,
        metric,
        multiplier,
    )

    if outlier_data.empty:
        st.info(
            "No valid values are available for outlier analysis."
        )
        return outlier_data

    above_count = int(
        (
            outlier_data["Outlier_Status"]
            == "Above Upper Bound"
        ).sum()
    )

    below_count = int(
        (
            outlier_data["Outlier_Status"]
            == "Below Lower Bound"
        ).sum()
    )

    col1, col2 = st.columns(2)

    col1.metric(
        "Above Upper Bound",
        f"{above_count:,}",
    )

    col2.metric(
        "Below Lower Bound",
        f"{below_count:,}",
    )

    st.caption(
        "IQR flags identify statistically unusual observations; "
        "they do not automatically indicate data errors."
    )

    flagged = outlier_data.loc[
        outlier_data["Outlier_Status"] != "Within Bounds"
    ].copy()

    if flagged.empty:
        st.success(
            "No observations were flagged by the selected IQR rule."
        )
    else:
        st.dataframe(
            flagged.sort_values(
                "Outlier_Deviation",
                ascending=False,
            ).head(500),
            use_container_width=True,
            hide_index=True,
        )

        if len(flagged) > 500:
            st.caption(
                "The table displays the 500 largest flagged records. "
                "The export contains the complete outlier analysis."
            )

    return outlier_data


