DEMAND_QUALITY_GATE_VERSION = "1.0.0"

DEMAND_QUALITY_GATE_METRICS = [
    "Sales Count",
    "Redemption Count",
]


# ------------------------------------------------------------
# 60.1 â€” PREPARE DATA AND PRESERVE QUALITY FLAGS
# ------------------------------------------------------------

def prepare_demand_quality_gate_data(dataframe):
    """Prepare ticket records and identify basic data-quality issues."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    required_columns = [
        "Timestamp",
        *DEMAND_QUALITY_GATE_METRICS,
    ]

    missing_columns = [
        column
        for column in required_columns
        if column not in dataframe.columns
    ]

    if missing_columns:
        raise ValueError(
            "Missing required columns: "
            + ", ".join(missing_columns)
        )

    result = dataframe[required_columns].copy()

    original_timestamps = result["Timestamp"].copy()

    result["Timestamp"] = pd.to_datetime(
        original_timestamps,
        errors="coerce",
    )

    result["Invalid_Timestamp"] = (
        result["Timestamp"].isna()
    )

    for column in DEMAND_QUALITY_GATE_METRICS:
        result[column] = pd.to_numeric(
            result[column],
            errors="coerce",
        )

        result[f"{column}_Missing"] = (
            result[column].isna()
        )

        result[f"{column}_Non_Finite"] = (
            result[column].isin(
                [np.inf, -np.inf]
            )
        )

        result[f"{column}_Negative"] = (
            result[column] < 0
        )

    valid_timestamp_mask = (
        result["Timestamp"].notna()
    )

    result["Duplicate_Timestamp"] = False

    result.loc[
        valid_timestamp_mask,
        "Duplicate_Timestamp",
    ] = result.loc[
        valid_timestamp_mask,
        "Timestamp",
    ].duplicated(
        keep=False
    )

    return result


# ------------------------------------------------------------
# 60.2 â€” CALCULATE COLUMN READINESS
# ------------------------------------------------------------

def calculate_demand_quality_gate_column_report(dataframe):
    """Calculate completeness and numeric-validity statistics."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    total_rows = len(dataframe)
    report_rows = []

    for column in DEMAND_QUALITY_GATE_METRICS:
        values = dataframe[column]

        finite_mask = (
            values.notna()
            & np.isfinite(values)
        )

        finite_values = values.loc[
            finite_mask
        ]

        missing_count = int(
            values.isna().sum()
        )

        non_finite_count = int(
            values.isin(
                [np.inf, -np.inf]
            ).sum()
        )

        negative_count = int(
            (values < 0).sum()
        )

        report_rows.append({
            "Column": column,
            "Total_Rows": total_rows,
            "Valid_Finite_Values": int(
                finite_mask.sum()
            ),
            "Missing_Values": missing_count,
            "Non_Finite_Values": non_finite_count,
            "Negative_Values": negative_count,
            "Unique_Values": int(
                finite_values.nunique()
            ),
            "Completeness_Percent": (
                finite_mask.sum() / total_rows * 100
                if total_rows
                else 0.0
            ),
        })

    timestamp_valid_count = int(
        dataframe["Timestamp"].notna().sum()
    )

    report_rows.append({
        "Column": "Timestamp",
        "Total_Rows": total_rows,
        "Valid_Finite_Values": timestamp_valid_count,
        "Missing_Values": int(
            dataframe["Invalid_Timestamp"].sum()
        ),
        "Non_Finite_Values": 0,
        "Negative_Values": 0,
        "Unique_Values": int(
            dataframe["Timestamp"].nunique()
        ),
        "Completeness_Percent": (
            timestamp_valid_count / total_rows * 100
            if total_rows
            else 0.0
        ),
    })

    return pd.DataFrame(
        report_rows
    )


# ------------------------------------------------------------
# 60.3 â€” CALCULATE CHRONOLOGICAL READINESS
# ------------------------------------------------------------

def calculate_demand_quality_gate_chronology(dataframe):
    """Assess timestamp coverage and ordering."""

    if dataframe is None or dataframe.empty:
        return {}

    timestamps = dataframe["Timestamp"]

    valid_timestamps = timestamps.dropna()

    if valid_timestamps.empty:
        return {
            "Total_Rows": int(len(dataframe)),
            "Valid_Timestamps": 0,
            "Invalid_Timestamps": int(len(dataframe)),
            "Distinct_Timestamps": 0,
            "Duplicate_Timestamp_Rows": 0,
            "Chronological_Order": False,
            "Coverage_Days": 0,
            "Median_Interval_Hours": np.nan,
            "Longest_Interval_Hours": np.nan,
        }

    ordered = valid_timestamps.sort_values()

    intervals_hours = (
        ordered.diff()
        .dt.total_seconds()
        .div(3600)
        .dropna()
    )

    positive_intervals = intervals_hours[
        intervals_hours > 0
    ]

    coverage_days = (
        ordered.max() - ordered.min()
    ).total_seconds() / 86400

    return {
        "Total_Rows": int(len(dataframe)),
        "Valid_Timestamps": int(
            timestamps.notna().sum()
        ),
        "Invalid_Timestamps": int(
            timestamps.isna().sum()
        ),
        "Distinct_Timestamps": int(
            valid_timestamps.nunique()
        ),
        "Duplicate_Timestamp_Rows": int(
            valid_timestamps.duplicated(
                keep=False
            ).sum()
        ),
        "Chronological_Order": bool(
            valid_timestamps.is_monotonic_increasing
        ),
        "Coverage_Days": float(
            coverage_days
        ),
        "Median_Interval_Hours": (
            float(positive_intervals.median())
            if not positive_intervals.empty
            else np.nan
        ),
        "Longest_Interval_Hours": (
            float(positive_intervals.max())
            if not positive_intervals.empty
            else np.nan
        ),
    }


# ------------------------------------------------------------
# 60.4 â€” CALCULATE OBSERVATION READINESS
# ------------------------------------------------------------

def calculate_demand_quality_gate_observation_report(
    dataframe,
):
    """Summarize available observations for each demand metric."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    rows = []

    for metric in DEMAND_QUALITY_GATE_METRICS:
        values = dataframe[metric]

        finite_values = values.loc[
            values.notna()
            & np.isfinite(values)
        ]

        rows.append({
            "Metric": metric,
            "Valid_Observations": int(
                len(finite_values)
            ),
            "Unique_Values": int(
                finite_values.nunique()
            ),
            "Zero_Observations": int(
                (finite_values == 0).sum()
            ),
            "Negative_Observations": int(
                (finite_values < 0).sum()
            ),
            "Mean": (
                float(finite_values.mean())
                if not finite_values.empty
                else np.nan
            ),
            "Standard_Deviation": (
                float(finite_values.std(ddof=1))
                if len(finite_values) > 1
                else np.nan
            ),
        })

    return pd.DataFrame(
        rows
    )


# ------------------------------------------------------------
# 60.5 â€” CALCULATE HEURISTIC READINESS SCORE
# ------------------------------------------------------------

def calculate_demand_quality_gate_scorecard(
    dataframe,
    column_report,
    chronology,
    minimum_observations=100,
):
    """
    Produce a heuristic readiness score.

    This is a data-quality screening score, not a statistical
    guarantee that a forecasting model will perform well.
    """

    if dataframe is None or dataframe.empty:
        return {
            "Readiness_Score": 0.0,
            "Readiness_Label": "No Data",
            "Gate_Status": "Blocked",
            "Checks": [],
        }

    checks = []

    total_rows = len(dataframe)

    timestamp_valid_percent = (
        dataframe["Timestamp"].notna().mean() * 100
    )

    checks.append({
        "Check": "Timestamp completeness",
        "Passed": timestamp_valid_percent >= 95,
        "Detail": (
            f"{timestamp_valid_percent:.2f}% of rows have "
            "valid timestamps."
        ),
        "Weight": 25,
    })

    numeric_valid_percentages = []

    for metric in DEMAND_QUALITY_GATE_METRICS:
        values = dataframe[metric]

        valid_mask = (
            values.notna()
            & np.isfinite(values)
        )

        numeric_valid_percentages.append(
            valid_mask.mean() * 100
        )

    numeric_completeness = (
        float(np.mean(numeric_valid_percentages))
        if numeric_valid_percentages
        else 0.0
    )

    checks.append({
        "Check": "Numeric completeness",
        "Passed": numeric_completeness >= 95,
        "Detail": (
            f"Average valid numeric completeness: "
            f"{numeric_completeness:.2f}%."
        ),
        "Weight": 25,
    })

    valid_timestamps = dataframe[
        "Timestamp"
    ].dropna()

    distinct_timestamp_count = int(
        valid_timestamps.nunique()
    )

    checks.append({
        "Check": "Distinct timestamps",
        "Passed": distinct_timestamp_count >= 2,
        "Detail": (
            f"{distinct_timestamp_count:,} distinct timestamps."
        ),
        "Weight": 15,
    })

    checks.append({
        "Check": "Minimum observations",
        "Passed": total_rows >= minimum_observations,
        "Detail": (
            f"{total_rows:,} source rows; screening threshold "
            f"is {minimum_observations:,}."
        ),
        "Weight": 15,
    })

    negative_values = sum(
        int((dataframe[metric] < 0).sum())
        for metric in DEMAND_QUALITY_GATE_METRICS
    )

    checks.append({
        "Check": "Negative demand values",
        "Passed": negative_values == 0,
        "Detail": (
            f"{negative_values:,} negative numeric values detected."
        ),
        "Weight": 10,
    })

    duplicate_rows = chronology.get(
        "Duplicate_Timestamp_Rows",
        0,
    )

    checks.append({
        "Check": "Repeated timestamps reviewed",
        "Passed": duplicate_rows == 0,
        "Detail": (
            f"{duplicate_rows:,} rows share timestamps. "
            "Repeated timestamps may be legitimate."
        ),
        "Weight": 10,
    })

    weighted_score = sum(
        check["Weight"]
        for check in checks
        if check["Passed"]
    )

    if weighted_score >= 85:
        readiness_label = "High"
    elif weighted_score >= 65:
        readiness_label = "Moderate"
    else:
        readiness_label = "Low"

    hard_block = (
        distinct_timestamp_count < 2
        or timestamp_valid_percent == 0
        or numeric_completeness == 0
    )

    gate_status = (
        "Blocked"
        if hard_block
        else "Review Required"
        if weighted_score < 85
        else "Passes Basic Screening"
    )

    return {
        "Readiness_Score": float(
            weighted_score
        ),
        "Readiness_Label": readiness_label,
        "Gate_Status": gate_status,
        "Checks": checks,
    }


# ------------------------------------------------------------
# 60.6 â€” GENERATE PREPARATION ACTIONS
# ------------------------------------------------------------

def generate_demand_quality_gate_actions(
    scorecard,
    chronology,
    column_report,
):
    """Generate practical data-preparation actions."""

    actions = []

    if not scorecard:
        return [
            "Load a valid dataset before assessing readiness."
        ]

    for check in scorecard.get("Checks", []):
        if not check["Passed"]:
            actions.append(
                f"{check['Check']}: {check['Detail']}"
            )

    if chronology.get("Invalid_Timestamps", 0) > 0:
        actions.append(
            "Investigate invalid timestamps and document whether "
            "affected records should be corrected or excluded."
        )

    if chronology.get("Coverage_Days", 0) < 30:
        actions.append(
            "The observed timestamp coverage is short. Consider "
            "whether sufficient seasonal and calendar variation "
            "is available for the intended forecasting task."
        )

    if chronology.get("Longest_Interval_Hours", 0) > 24:
        actions.append(
            "Inspect long intervals between distinct observations. "
            "A long interval can indicate a reporting gap, but it "
            "does not prove records are missing."
        )

    if not actions:
        actions.append(
            "The dataset passes the configured basic screening checks. "
            "Still validate chronological splits, target alignment, "
            "baseline performance and leakage before model training."
        )

    actions.append(
        "The readiness score is a heuristic checklist; it is not "
        "a prediction of model accuracy."
    )

    return actions


