    """Main Streamlit renderer for Part 60."""

    st.header(
        "Ferry Demand Forecast Readiness & Data Quality Gate"
    )

    st.markdown(
        """
        Assess historical ticket data before forecasting. The scorecard
        highlights completeness, numeric validity, timestamp coverage
        and potential preparation issues.
        """
    )

    minimum_observations = st.number_input(
        "Minimum source-row screening threshold",
        min_value=2,
        max_value=1_000_000,
        value=100,
        step=10,
        key="demand_quality_gate_minimum_observations",
    )

    try:
        raw_data = load_ticket_dataframe(
            str(DEFAULT_DATASET_PATH)
        )

        prepared_data = prepare_demand_quality_gate_data(
            raw_data
        )

    except Exception as error:
        st.error(
            f"Unable to prepare readiness data: {error}"
        )
        return

    if prepared_data.empty:
        st.warning(
            "No records are available for readiness analysis."
        )
        return

    column_report = (
        calculate_demand_quality_gate_column_report(
            prepared_data
        )
    )

    chronology = calculate_demand_quality_gate_chronology(
        prepared_data
    )

    observation_report = (
        calculate_demand_quality_gate_observation_report(
            prepared_data
        )
    )

    scorecard = calculate_demand_quality_gate_scorecard(
        prepared_data,
        column_report,
        chronology,
        int(minimum_observations),
    )

    actions = generate_demand_quality_gate_actions(
        scorecard,
        chronology,
        column_report,
    )

    st.divider()

    render_demand_quality_gate_scorecard(
        scorecard
    )

    st.divider()

    render_demand_quality_gate_chronology(
        chronology
    )

    st.divider()

    render_demand_quality_gate_column_report(
        column_report
    )

    st.divider()

    render_demand_quality_gate_observation_report(
        observation_report
    )

    st.divider()

    render_demand_quality_gate_actions(
        actions
    )

    st.download_button(
        label="Download Column Readiness Report",
        data=column_report.to_csv(
            index=False
        ).encode("utf-8"),
        file_name="ferry_demand_quality_gate_columns.csv",
        mime="text/csv",
        key="demand_quality_gate_export_columns",
    )

    st.download_button(
        label="Download Observation Report",
        data=observation_report.to_csv(
            index=False
        ).encode("utf-8"),
        file_name="ferry_demand_quality_gate_observations.csv",
        mime="text/csv",
        key="demand_quality_gate_export_observations",
    )

    st.download_button(
        label="Download Readiness Checks",
        data=pd.DataFrame(
            scorecard["Checks"]
        ).to_csv(
            index=False
        ).encode("utf-8"),
        file_name="ferry_demand_quality_gate_checks.csv",
        mime="text/csv",
        key="demand_quality_gate_export_checks",
    )

    with st.expander(
        "Readiness Score Methodology & Limitations"
    ):
        st.markdown(
            """
            - The score is a configurable heuristic, not a standard
              industry certification.
            - Passing the checks does not guarantee forecast accuracy.
            - A repeated timestamp is not necessarily a duplicate record.
            - Negative counts may reflect documented source corrections.
            - Source-row count is not the same as the number of independent
              daily, weekly or monthly forecasting observations.
            - Model validation, chronological splitting and leakage checks
              remain necessary before training or deployment.
            """
        )

    st.caption(
        "Demand Forecast Readiness & Data Quality Gate "
        f"v{DEMAND_QUALITY_GATE_VERSION}"
    )


