# ------------------------------------------------------------
# 61.1 â€” PREPARE ACTUAL AND PREDICTED DATA
# ------------------------------------------------------------

def prepare_demand_tolerance_data(
    dataframe,
    actual_column,
    predicted_column,
    timestamp_column=None,
):
    """Validate and prepare actual-versus-predicted observations."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    required_columns = [
        actual_column,
        predicted_column,
    ]

    if timestamp_column:
        required_columns.append(
            timestamp_column
        )

    missing_columns = [
        column
        for column in required_columns
        if column not in dataframe.columns
    ]

    if missing_columns:
        raise ValueError(
            "Required columns not found: "
            + ", ".join(missing_columns)
        )

    result = pd.DataFrame(index=dataframe.index)

    if timestamp_column:
        result["Timestamp"] = pd.to_datetime(
            dataframe[timestamp_column],
            errors="coerce",
        )

    result["Actual"] = pd.to_numeric(
        dataframe[actual_column],
        errors="coerce",
    )

    result["Predicted"] = pd.to_numeric(
        dataframe[predicted_column],
        errors="coerce",
    )

    result["Actual_Non_Finite"] = (
        result["Actual"].isin(
            [np.inf, -np.inf]
        )
    )

    result["Predicted_Non_Finite"] = (
        result["Predicted"].isin(
            [np.inf, -np.inf]
        )
    )

    result["Actual"] = result[
        "Actual"
    ].replace(
        [np.inf, -np.inf],
        np.nan,
    )

    result["Predicted"] = result[
        "Predicted"
    ].replace(
        [np.inf, -np.inf],
        np.nan,
    )

    result["Valid_Pair"] = (
        result["Actual"].notna()
        & result["Predicted"].notna()
    )

    result["Signed_Error"] = (
        result["Predicted"]
        - result["Actual"]
    )

    result["Absolute_Error"] = (
        result["Signed_Error"].abs()
    )

    result["Squared_Error"] = (
        result["Signed_Error"] ** 2
    )

    result["Absolute_Percent_Error"] = np.where(
        result["Actual"].abs() > 0,
        (
            result["Absolute_Error"]
            / result["Actual"].abs()
        ) * 100,
        np.nan,
    )

    result["Error_Direction"] = np.select(
        [
            result["Signed_Error"] > 0,
            result["Signed_Error"] < 0,
        ],
        [
            "Overprediction",
            "Underprediction",
        ],
        default="Exact Match",
    )

    return result


# ------------------------------------------------------------
# 61.2 â€” CALCULATE TOLERANCE CLASSIFICATION
# ------------------------------------------------------------

def classify_demand_tolerance(
    dataframe,
    absolute_tolerance,
    percentage_tolerance,
    tolerance_mode="Absolute Error",
):
    """
    Classify valid predictions against user-defined tolerances.

    Absolute Error:
        abs(predicted - actual) <= absolute tolerance

    Percentage Error:
        absolute percentage error <= percentage tolerance

    Either Rule:
        pass if either enabled tolerance rule passes

    Both Rules:
        pass only if both enabled rules pass
    """

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    if absolute_tolerance < 0:
        raise ValueError(
            "Absolute tolerance cannot be negative."
        )

    if percentage_tolerance < 0:
        raise ValueError(
            "Percentage tolerance cannot be negative."
        )

    result = dataframe.copy()

    absolute_pass = (
        result["Absolute_Error"]
        <= absolute_tolerance
    )

    percentage_pass = (
        result["Absolute_Percent_Error"]
        <= percentage_tolerance
    )

    percentage_available = (
        result["Absolute_Percent_Error"].notna()
    )

    valid_pairs = result[
        "Valid_Pair"
    ]

    if tolerance_mode == "Absolute Error":
        passed = absolute_pass

    elif tolerance_mode == "Percentage Error":
        passed = (
            percentage_available
            & percentage_pass
        )

    elif tolerance_mode == "Either Rule":
        passed = (
            absolute_pass
            | (
                percentage_available
                & percentage_pass
            )
        )

    elif tolerance_mode == "Both Rules":
        passed = (
            absolute_pass
            & percentage_available
            & percentage_pass
        )

    else:
        raise ValueError(
            "Unsupported tolerance mode."
        )

    result["Absolute_Tolerance_Pass"] = (
        absolute_pass.where(
            valid_pairs,
            False,
        )
    )

    result["Percentage_Tolerance_Pass"] = (
        (
            percentage_available
            & percentage_pass
        ).where(
            valid_pairs,
            False,
        )
    )

    result["Tolerance_Status"] = np.select(
        [
            ~valid_pairs,
            valid_pairs & passed,
        ],
        [
            "Invalid Pair",
            "Within Tolerance",
        ],
        default="Outside Tolerance",
    )

    return result


# ------------------------------------------------------------
# 61.3 â€” CALCULATE OVERALL ERROR METRICS
# ------------------------------------------------------------

def calculate_demand_tolerance_summary(
    dataframe,
):
    """Calculate forecast error metrics and tolerance compliance."""

    if dataframe is None or dataframe.empty:
        return {}

    valid = dataframe.loc[
        dataframe["Valid_Pair"]
    ].copy()

    total_rows = len(dataframe)
    valid_count = len(valid)

    within_count = int(
        (
            dataframe["Tolerance_Status"]
            == "Within Tolerance"
        ).sum()
    )

    outside_count = int(
        (
            dataframe["Tolerance_Status"]
            == "Outside Tolerance"
        ).sum()
    )

    invalid_count = int(
        (
            dataframe["Tolerance_Status"]
            == "Invalid Pair"
        ).sum()
    )

    if valid_count == 0:
        return {
            "Total_Rows": total_rows,
            "Valid_Pairs": 0,
            "Invalid_Pairs": invalid_count,
            "Within_Tolerance": 0,
            "Outside_Tolerance": 0,
            "Tolerance_Compliance_Percent": np.nan,
            "MAE": np.nan,
            "RMSE": np.nan,
            "Bias": np.nan,
            "WAPE_Percent": np.nan,
            "MAPE_Percent": np.nan,
            "Overpredictions": 0,
            "Underpredictions": 0,
            "Exact_Matches": 0,
        }

    actual_sum = valid[
        "Actual"
    ].abs().sum()

    absolute_error_sum = valid[
        "Absolute_Error"
    ].sum()

    actual_nonzero = valid.loc[
        valid["Actual"].abs() > 0
    ]

    return {
        "Total_Rows": int(total_rows),
        "Valid_Pairs": int(valid_count),
        "Invalid_Pairs": int(invalid_count),
        "Within_Tolerance": int(within_count),
        "Outside_Tolerance": int(outside_count),
        "Tolerance_Compliance_Percent": (
            within_count / valid_count * 100
        ),
        "MAE": float(
            valid["Absolute_Error"].mean()
        ),
        "RMSE": float(
            np.sqrt(
                valid["Squared_Error"].mean()
            )
        ),
        "Bias": float(
            valid["Signed_Error"].mean()
        ),
        "WAPE_Percent": (
            float(
                absolute_error_sum
                / actual_sum
                * 100
            )
            if actual_sum > 0
            else np.nan
        ),
        "MAPE_Percent": (
            float(
                (
                    actual_nonzero[
                        "Absolute_Error"
                    ]
                    / actual_nonzero[
                        "Actual"
                    ].abs()
                ).mean()
                * 100
            )
            if not actual_nonzero.empty
            else np.nan
        ),
        "Overpredictions": int(
            (
                valid["Error_Direction"]
                == "Overprediction"
            ).sum()
        ),
        "Underpredictions": int(
            (
                valid["Error_Direction"]
                == "Underprediction"
            ).sum()
        ),
        "Exact_Matches": int(
            (
                valid["Error_Direction"]
                == "Exact Match"
            ).sum()
        ),
    }


# ------------------------------------------------------------
# 61.4 â€” BUILD ERROR INVESTIGATION QUEUE
# ------------------------------------------------------------

def build_demand_tolerance_investigation_queue(
    dataframe,
):
    """Rank valid out-of-tolerance predictions for investigation."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    queue = dataframe.loc[
        dataframe["Tolerance_Status"]
        == "Outside Tolerance"
    ].copy()

    if queue.empty:
        return queue

    queue["Investigation_Reason"] = np.select(
        [
            queue["Error_Direction"]
            == "Overprediction",
            queue["Error_Direction"]
            == "Underprediction",
        ],
        [
            "Predicted demand exceeds actual demand.",
            "Predicted demand is below actual demand.",
        ],
        default="Prediction error exceeds configured tolerance.",
    )

    queue = queue.sort_values(
        by="Absolute_Error",
        ascending=False,
    )

    queue.insert(
        0,
        "Investigation_Rank",
        range(1, len(queue) + 1),
    )

    preferred_columns = [
        column
        for column in [
            "Investigation_Rank",
            "Timestamp",
            "Actual",
            "Predicted",
            "Signed_Error",
            "Absolute_Error",
            "Absolute_Percent_Error",
            "Error_Direction",
            "Investigation_Reason",
        ]
        if column in queue.columns
    ]

    return queue[
        preferred_columns
    ]


