def _ferry_suggest_column(columns, role, exclude=None, fallback=None):
    """Suggest a CSV column for a semantic role without relying on column order."""
    exclude = set(exclude or [])
    candidates = [column for column in columns if column not in exclude]
    if not candidates:
        return None

    aliases = {
        "actual": {
            "actual", "actualdemand", "actualvalue", "observed",
            "observedvalue", "observeddemand", "ytrue", "groundtruth",
            "targetactual",
        },
        "predicted": {
            "predicted", "prediction", "predictedvalue", "predicteddemand",
            "forecast", "forecastvalue", "forecasted", "ypred", "yhat",
        },
        "timestamp": {
            "timestamp", "datetime", "date", "ds", "time", "period",
            "observationdate", "forecastdate",
        },
        "model": {
            "model", "modelname", "algorithm", "estimator", "modelid",
            "forecastmodel",
        },
        "value": {
            "actual", "value", "demand", "salescount", "redemptioncount",
            "passengers", "count", "quantity",
        },
    }

    def normalize(value):
        return "".join(character.lower() for character in str(value)
                       if character.isalnum())

    role_aliases = aliases.get(role, set())
    ranked = []
    for position, column in enumerate(candidates):
        name = normalize(column)
        score = 0
        if name in role_aliases:
            score = 100
        elif any(name.startswith(alias) for alias in role_aliases):
            score = 80
        elif any(alias in name for alias in role_aliases):
            score = 60

        # Avoid accidentally treating a predicted column as actual.
        if role == "actual" and any(token in name for token in
                                    ("predicted", "prediction", "forecast")):
            score = 0
        if role == "predicted" and any(token in name for token in
                                       ("actual", "observed", "groundtruth")):
            score = 0

        ranked.append((score, -position, column))

    best = max(ranked, default=(0, 0, None))
    if best[0] > 0:
        return best[2]
    if fallback in candidates:
        return fallback
    return candidates[0]


def _ferry_column_index(options, role, exclude=None, fallback=None):
    """Return the semantic default index for a Streamlit selectbox."""
    suggested = _ferry_suggest_column(
        options,
        role,
        exclude=exclude,
        fallback=fallback,
    )
    return options.index(suggested) if suggested in options else 0


