# 61.9 â€” MAIN TOLERANCE CENTER
# ------------------------------------------------------------

def render_demand_tolerance_center():
    """Render the complete forecast tolerance analysis center."""

    st.header(
        "Ferry Demand Forecast Error & Accuracy Tolerance Center"
    )

    st.markdown(
        """
        Upload a CSV containing actual and predicted values.
        Configure the error tolerance and identify prediction
        records that require further investigation.
        """
    )

    uploaded_file = st.file_uploader(
        "Upload actual-versus-predicted CSV",
        type=["csv"],
        key="demand_tolerance_prediction_upload",
    )

    if uploaded_file is None:
        st.info(
            "Upload a CSV with actual and predicted demand columns "
            "to start the tolerance analysis."
        )
        st.caption(
            "This module does not train a model or generate forecasts."
        )
        return

    try:
        source_data = pd.read_csv(
            uploaded_file
        )
    except Exception as error:
        st.error(
            f"Unable to read uploaded CSV: {error}"
        )
        return

    if source_data.empty:
        st.warning(
            "The uploaded CSV contains no data rows."
        )
        return

    st.caption(
        f"Uploaded file contains {len(source_data):,} rows "
        f"and {len(source_data.columns):,} columns."
    )

    columns = source_data.columns.tolist()

    col1, col2 = st.columns(2)

    actual_column = col1.selectbox(
        "Actual demand column",
        options=columns,
        index=_ferry_column_index(columns, "actual"),
        key="demand_tolerance_actual_column_v2",
    )

    predicted_options = [
        column
        for column in columns
        if column != actual_column
    ]

    if not predicted_options:
        st.error(
            "The file must contain separate actual and predicted columns."
        )
        return

    predicted_column = col2.selectbox(
        "Predicted demand column",
        options=predicted_options,
        index=_ferry_column_index(
            predicted_options, "predicted", exclude=[actual_column]
        ),
        key="demand_tolerance_predicted_column_v2",
    )

    timestamp_options = [
        "No timestamp column"
    ] + [
        column
        for column in columns
        if column not in [
            actual_column,
            predicted_column,
        ]
    ]

    timestamp_column = st.selectbox(
        "Optional timestamp column",
        options=timestamp_options,
        index=_ferry_column_index(
            timestamp_options, "timestamp", fallback="No timestamp column"
        ),
        key="demand_tolerance_timestamp_column_v2",
    )

    if timestamp_column == "No timestamp column":
        timestamp_column = None

    st.subheader(
        "Configure Error Tolerance"
    )

    col3, col4 = st.columns(2)

    absolute_tolerance = col3.number_input(
        "Maximum absolute error",
        min_value=0.0,
        value=10.0,
        step=1.0,
        key="demand_tolerance_absolute_threshold",
        help=(
            "Allowed absolute difference in the same unit as "
            "the uploaded demand values."
        ),
    )

    percentage_tolerance = col4.number_input(
        "Maximum absolute percentage error (%)",
        min_value=0.0,
        value=10.0,
        step=1.0,
        key="demand_tolerance_percentage_threshold",
    )

    tolerance_mode = st.selectbox(
        "Tolerance decision rule",
        options=[
            "Absolute Error",
            "Percentage Error",
            "Either Rule",
            "Both Rules",
        ],
        key="demand_tolerance_mode",
        help=(
            "Percentage error cannot be calculated when actual demand "
            "is zero. Such rows do not pass percentage-only or both-rule "
            "checks."
        ),
    )

    try:
        prepared_data = prepare_demand_tolerance_data(
            source_data,
            actual_column,
            predicted_column,
            timestamp_column,
        )

        classified_data = classify_demand_tolerance(
            prepared_data,
            absolute_tolerance,
            percentage_tolerance,
            tolerance_mode,
        )

    except Exception as error:
        st.error(
            f"Unable to classify forecast errors: {error}"
        )
        return

    if classified_data.empty:
        st.warning(
            "No forecast observations are available."
        )
        return

    summary = calculate_demand_tolerance_summary(
        classified_data
    )

    queue = build_demand_tolerance_investigation_queue(
        classified_data
    )

    st.divider()

    render_demand_tolerance_summary(
        summary
    )

    st.divider()

    render_demand_tolerance_distribution(
        classified_data
    )

    st.divider()

    render_demand_tolerance_investigation_queue(
        queue
    )

    st.divider()

    render_demand_tolerance_exports(
        classified_data,
        queue,
    )

    with st.expander(
        "Metric Definitions & Limitations"
    ):
        st.markdown(
            """
            - **Signed Error:** Predicted minus actual. Positive means
              overprediction; negative means underprediction.
            - **MAE:** Mean absolute error, in the original demand unit.
            - **RMSE:** Root mean squared error, in the original demand unit.
            - **Bias:** Mean signed error; positive values indicate average
              overprediction.
            - **WAPE:** Total absolute error divided by total absolute actual
              demand. It is unavailable when the denominator is zero.
            - **MAPE:** Mean absolute percentage error for non-zero actuals.
            - **Tolerance Compliance:** Percentage of valid actual-predicted
              pairs classified as within the selected tolerance.
            - Tolerances are user-defined analytical thresholds, not
              verified operational requirements.
            - A high tolerance-compliance rate does not guarantee good
              future performance.
            """
        )

    st.caption(
        "Forecast Error & Accuracy Tolerance Center "
        f"v{DEMAND_TOLERANCE_CENTER_VERSION}"
    )


