DEMAND_ERROR_STABILITY_VERSION = "1.0.0"

DEMAND_ERROR_STABILITY_FREQUENCIES = {
    "Daily": "D",
    "Weekly": "W-SUN",
    "Monthly": "MS",
}


# ------------------------------------------------------------
# 62.1 â€” PREPARE ERROR MONITORING DATA
# ------------------------------------------------------------

def prepare_demand_error_stability_data(
    dataframe,
    actual_column,
    predicted_column,
    timestamp_column,
):
    """Prepare timestamped actual and predicted observations."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    required_columns = [
        actual_column,
        predicted_column,
        timestamp_column,
    ]

    missing_columns = [
        column
        for column in required_columns
        if column not in dataframe.columns
    ]

    if missing_columns:
        raise ValueError(
            "Missing columns: "
            + ", ".join(missing_columns)
        )

    result = pd.DataFrame()

    result["Timestamp"] = pd.to_datetime(
        dataframe[timestamp_column],
        errors="coerce",
    )

    result["Actual"] = pd.to_numeric(
        dataframe[actual_column],
        errors="coerce",
    )

    result["Predicted"] = pd.to_numeric(
        dataframe[predicted_column],
        errors="coerce",
    )

    result["Actual"] = result["Actual"].replace(
        [np.inf, -np.inf],
        np.nan,
    )

    result["Predicted"] = result["Predicted"].replace(
        [np.inf, -np.inf],
        np.nan,
    )

    result = result.dropna(
        subset=[
            "Timestamp",
            "Actual",
            "Predicted",
        ]
    )

    result = result.sort_values(
        "Timestamp"
    ).reset_index(
        drop=True
    )

    result["Signed_Error"] = (
        result["Predicted"]
        - result["Actual"]
    )

    result["Absolute_Error"] = (
        result["Signed_Error"].abs()
    )

    result["Squared_Error"] = (
        result["Signed_Error"] ** 2
    )

    result["Absolute_Percent_Error"] = np.where(
        result["Actual"].abs() > 0,
        (
            result["Absolute_Error"]
            / result["Actual"].abs()
        ) * 100,
        np.nan,
    )

    return result


# ------------------------------------------------------------
# 62.2 â€” AGGREGATE ERROR BY TIME PERIOD
# ------------------------------------------------------------

def aggregate_demand_error_stability_periods(
    dataframe,
    frequency="Daily",
):
    """Aggregate forecast error metrics by calendar period."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    if frequency not in DEMAND_ERROR_STABILITY_FREQUENCIES:
        raise ValueError(
            "Unsupported aggregation frequency."
        )

    frequency_rule = (
        DEMAND_ERROR_STABILITY_FREQUENCIES[
            frequency
        ]
    )

    working = dataframe.copy()

    working = working.set_index(
        "Timestamp"
    )

    aggregation = working.resample(
        frequency_rule
    ).agg(
        Actual=("Actual", "sum"),
        Predicted=("Predicted", "sum"),
        Observation_Count=("Actual", "count"),
        Mean_Absolute_Error=("Absolute_Error", "mean"),
        Mean_Signed_Error=("Signed_Error", "mean"),
        Absolute_Error_Total=("Absolute_Error", "sum"),
        Squared_Error_Total=("Squared_Error", "sum"),
    )

    aggregation["RMSE"] = np.sqrt(
        aggregation["Squared_Error_Total"]
        / aggregation["Observation_Count"].replace(
            0,
            np.nan,
        )
    )

    aggregation["WAPE_Percent"] = np.where(
        aggregation["Actual"].abs() > 0,
        (
            aggregation["Absolute_Error_Total"]
            / aggregation["Actual"].abs()
        ) * 100,
        np.nan,
    )

    aggregation["Bias_Percent"] = np.where(
        aggregation["Actual"].abs() > 0,
        (
            (
                aggregation["Predicted"]
                - aggregation["Actual"]
            )
            / aggregation["Actual"].abs()
        ) * 100,
        np.nan,
    )

    aggregation = aggregation.reset_index()

    aggregation["Period_Status"] = np.select(
        [
            aggregation["Observation_Count"] == 0,
            aggregation["WAPE_Percent"] > 20,
            aggregation["WAPE_Percent"] > 10,
        ],
        [
            "No Observations",
            "High Error",
            "Elevated Error",
        ],
        default="Lower Error",
    )

    return aggregation


# ------------------------------------------------------------
# 62.3 â€” CALCULATE STABILITY SUMMARY
# ------------------------------------------------------------

def calculate_demand_error_stability_summary(
    period_data,
):
    """Summarize period-level forecast error variability."""

    if period_data is None or period_data.empty:
        return {}

    observed = period_data.loc[
        period_data["Observation_Count"] > 0
    ].copy()

    if observed.empty:
        return {
            "Periods": 0,
            "Total_Observations": 0,
            "Mean_Period_MAE": np.nan,
            "Median_Period_MAE": np.nan,
            "MAE_Standard_Deviation": np.nan,
            "MAE_Coefficient_of_Variation": np.nan,
            "Mean_Period_WAPE": np.nan,
            "High_Error_Periods": 0,
            "Elevated_Error_Periods": 0,
            "No_Observation_Periods": int(
                (
                    period_data["Observation_Count"] == 0
                ).sum()
            ),
        }

    mae_mean = observed[
        "Mean_Absolute_Error"
    ].mean()

    mae_std = observed[
        "Mean_Absolute_Error"
    ].std(ddof=1)

    mae_cv = (
        mae_std / abs(mae_mean)
        if pd.notna(mae_mean) and mae_mean != 0
        else np.nan
    )

    return {
        "Periods": int(len(observed)),
        "Total_Observations": int(
            observed["Observation_Count"].sum()
        ),
        "Mean_Period_MAE": float(
            mae_mean
        ),
        "Median_Period_MAE": float(
            observed["Mean_Absolute_Error"].median()
        ),
        "MAE_Standard_Deviation": (
            float(mae_std)
            if pd.notna(mae_std)
            else np.nan
        ),
        "MAE_Coefficient_of_Variation": (
            float(mae_cv)
            if pd.notna(mae_cv)
            else np.nan
        ),
        "Mean_Period_WAPE": (
            float(
                observed["WAPE_Percent"].mean()
            )
            if observed["WAPE_Percent"].notna().any()
            else np.nan
        ),
        "High_Error_Periods": int(
            (
                observed["Period_Status"]
                == "High Error"
            ).sum()
        ),
        "Elevated_Error_Periods": int(
            (
                observed["Period_Status"]
                == "Elevated Error"
            ).sum()
        ),
        "No_Observation_Periods": int(
            (
                period_data["Observation_Count"] == 0
            ).sum()
        ),
    }


# ------------------------------------------------------------
# 62.4 â€” IDENTIFY ERROR CHANGES
# ------------------------------------------------------------

def identify_demand_error_stability_changes(
    period_data,
    minimum_observations=3,
):
    """Identify large changes in consecutive period MAE."""

    if period_data is None or period_data.empty:
        return pd.DataFrame()

    result = period_data.copy()

    result["Previous_Period_MAE"] = (
        result["Mean_Absolute_Error"].shift(1)
    )

    result["MAE_Change"] = (
        result["Mean_Absolute_Error"]
        - result["Previous_Period_MAE"]
    )

    result["MAE_Change_Percent"] = np.where(
        result["Previous_Period_MAE"].abs() > 0,
        (
            result["MAE_Change"]
            / result["Previous_Period_MAE"].abs()
        ) * 100,
        np.nan,
    )

    result["Error_Change_Flag"] = np.select(
        [
            result["Observation_Count"] == 0,
            result["Observation_Count"] < minimum_observations,
            result["MAE_Change_Percent"] >= 50,
            result["MAE_Change_Percent"] <= -50,
        ],
        [
            "No Observations",
            "Limited Observations",
            "MAE Increased by at Least 50%",
            "MAE Decreased by at Least 50%",
        ],
        default="No Large MAE Change",
    )

    return result


# ------------------------------------------------------------
# 62.5 â€” GENERATE STABILITY INSIGHTS
# ------------------------------------------------------------

def generate_demand_error_stability_insights(
    summary,
    period_data,
):
    """Generate descriptive error-monitoring observations."""

    insights = []

    if not summary:
        return [
            "No error stability summary is available."
        ]

    insights.append(
        f"Analyzed {summary['Periods']:,} periods "
        f"containing {summary['Total_Observations']:,} "
        "valid actual-predicted observations."
    )

    mean_wape = summary.get(
        "Mean_Period_WAPE",
        np.nan,
    )

    if pd.notna(mean_wape):
        insights.append(
            f"Mean period-level WAPE is {mean_wape:.2f}%. "
            "This is the unweighted mean of available period WAPE values."
        )
    else:
        insights.append(
            "Period-level WAPE could not be calculated for the available data."
        )

    cv = summary.get(
        "MAE_Coefficient_of_Variation",
        np.nan,
    )

    if pd.notna(cv):
        insights.append(
            f"The coefficient of variation of period MAE is {cv:.3f}. "
            "It describes relative variability in period-level MAE."
        )

    if summary["High_Error_Periods"] > 0:
        insights.append(
            f"{summary['High_Error_Periods']:,} periods have WAPE "
            "above the illustrative 20% threshold."
        )

    if summary["Elevated_Error_Periods"] > 0:
        insights.append(
            f"{summary['Elevated_Error_Periods']:,} periods have WAPE "
            "above 10% and up to 20%."
        )

    if period_data is not None and not period_data.empty:
        observed = period_data.loc[
            period_data["Observation_Count"] > 0
        ]

        if not observed.empty:
            worst_index = (
                observed["Mean_Absolute_Error"].idxmax()
            )

            worst_period = observed.loc[
                worst_index
            ]

            insights.append(
                "The period with the largest mean absolute error is "
                f"{worst_period['Timestamp']}, with MAE "
                f"{worst_period['Mean_Absolute_Error']:.3f}."
            )

    insights.append(
        "These are retrospective diagnostics on uploaded predictions; "
        "they do not prove model drift or guarantee future accuracy."
    )

    return insights


