def render_demand_error_stability_center():
    """Render retrospective forecast error stability monitoring."""

    st.header(
        "Ferry Demand Forecast Error Trend & Stability Monitor"
    )

    st.markdown(
        """
        Review historical forecast errors over time, identify periods
        with elevated error and investigate large changes in MAE.
        Upload predictions generated by a forecasting model.
        """
    )

    uploaded_file = st.file_uploader(
        "Upload timestamped actual and predicted demand CSV",
        type=["csv"],
        key="demand_error_stability_upload",
    )

    if uploaded_file is None:
        st.info(
            "Upload a CSV containing a timestamp column, actual demand "
            "and predicted demand."
        )
        return

    try:
        source_data = pd.read_csv(
            uploaded_file
        )
    except Exception as error:
        st.error(
            f"Unable to read CSV: {error}"
        )
        return

    if source_data.empty:
        st.warning(
            "The uploaded file contains no data rows."
        )
        return

    columns = source_data.columns.tolist()

    col1, col2, col3 = st.columns(3)

    timestamp_column = col1.selectbox(
        "Timestamp column",
        options=columns,
        index=_ferry_column_index(columns, "timestamp"),
        key="demand_error_stability_timestamp_column_v2",
    )

    actual_options = [
        column
        for column in columns
        if column != timestamp_column
    ]

    if not actual_options:
        st.error(
            "A separate actual demand column is required."
        )
        return

    actual_column = col2.selectbox(
        "Actual demand column",
        options=actual_options,
        index=_ferry_column_index(actual_options, "actual"),
        key="demand_error_stability_actual_column_v2",
    )

    predicted_options = [
        column
        for column in columns
        if column not in [
            timestamp_column,
            actual_column,
        ]
    ]

    if not predicted_options:
        st.error(
            "A separate predicted demand column is required."
        )
        return

    predicted_column = col3.selectbox(
        "Predicted demand column",
        options=predicted_options,
        index=_ferry_column_index(predicted_options, "predicted"),
        key="demand_error_stability_predicted_column_v2",
    )

    frequency = st.selectbox(
        "Aggregation frequency",
        options=list(
            DEMAND_ERROR_STABILITY_FREQUENCIES.keys()
        ),
        index=0,
        key="demand_error_stability_frequency",
    )

    minimum_observations = st.number_input(
        "Minimum observations for change flags",
        min_value=1,
        max_value=1000,
        value=3,
        step=1,
        key="demand_error_stability_minimum_observations",
    )

    try:
        prepared = prepare_demand_error_stability_data(
            source_data,
            actual_column,
            predicted_column,
            timestamp_column,
        )

        if prepared.empty:
            st.warning(
                "No rows have valid timestamps and numeric "
                "actual-predicted pairs."
            )
            return

        period_data = aggregate_demand_error_stability_periods(
            prepared,
            frequency,
        )

        summary = calculate_demand_error_stability_summary(
            period_data
        )

        changes = identify_demand_error_stability_changes(
            period_data,
            int(minimum_observations),
        )

        insights = generate_demand_error_stability_insights(
            summary,
            period_data,
        )

    except Exception as error:
        st.error(
            f"Unable to calculate error stability: {error}"
        )
        return

    st.divider()

    render_demand_error_stability_summary(
        summary
    )

    st.divider()

    render_demand_error_stability_trend(
        period_data
    )

    st.divider()

    render_demand_error_stability_period_table(
        period_data
    )

    st.divider()

    render_demand_error_stability_changes(
        changes
    )

    st.divider()

    st.subheader(
        "Analytical Insights"
    )

    for insight in insights:
        st.markdown(
            f"- {insight}"
        )

    st.download_button(
        label="Download Period Error Diagnostics",
        data=period_data.to_csv(
            index=False
        ).encode("utf-8"),
        file_name="ferry_demand_error_stability_periods.csv",
        mime="text/csv",
        key="demand_error_stability_export_periods",
    )

    st.download_button(
        label="Download Error Change Diagnostics",
        data=changes.to_csv(
            index=False
        ).encode("utf-8"),
        file_name="ferry_demand_error_stability_changes.csv",
        mime="text/csv",
        key="demand_error_stability_export_changes",
    )

    with st.expander(
        "Methodology & Limitations"
    ):
        st.markdown(
            """
            - Error trends are calculated from uploaded predictions;
              this module does not retrain the forecasting model.
            - Empty calendar periods are shown as having no observations.
              They do not automatically prove missing source data.
            - WAPE thresholds of 10% and 20% are illustrative monitoring
              thresholds, not validated operational standards.
            - Period MAE variability is descriptive and does not establish
              statistically significant model drift.
            - Aggregated-period error metrics can differ from metrics
              calculated across all individual observations.
            - Reliable monitoring requires correct timestamp alignment
              and predictions generated without future-data leakage.
            """
        )

    st.caption(
        "Forecast Error Trend & Stability Monitor "
        f"v{DEMAND_ERROR_STABILITY_VERSION}"
    )


