# ------------------------------------------------------------
# 63.1 â€” PREPARE ROOT-CAUSE INVESTIGATION DATA
# ------------------------------------------------------------

def prepare_demand_error_root_cause_data(
    dataframe,
    actual_column,
    predicted_column,
    timestamp_column=None,
    segment_column=None,
):
    """Prepare actual-predicted records for error investigation."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    required_columns = [
        actual_column,
        predicted_column,
    ]

    if timestamp_column:
        required_columns.append(timestamp_column)

    if segment_column:
        required_columns.append(segment_column)

    missing_columns = [
        column
        for column in required_columns
        if column not in dataframe.columns
    ]

    if missing_columns:
        raise ValueError(
            "Required columns not found: "
            + ", ".join(missing_columns)
        )

    result = pd.DataFrame(index=dataframe.index)

    if timestamp_column:
        result["Timestamp"] = pd.to_datetime(
            dataframe[timestamp_column],
            errors="coerce",
        )

    if segment_column:
        result["Segment"] = (
            dataframe[segment_column]
            .fillna("Unknown")
            .astype(str)
        )

    result["Actual"] = pd.to_numeric(
        dataframe[actual_column],
        errors="coerce",
    )

    result["Predicted"] = pd.to_numeric(
        dataframe[predicted_column],
        errors="coerce",
    )

    result["Actual"] = result["Actual"].replace(
        [np.inf, -np.inf],
        np.nan,
    )

    result["Predicted"] = result["Predicted"].replace(
        [np.inf, -np.inf],
        np.nan,
    )

    result = result.dropna(
        subset=[
            "Actual",
            "Predicted",
        ]
    ).copy()

    if result.empty:
        return result

    result["Signed_Error"] = (
        result["Predicted"]
        - result["Actual"]
    )

    result["Absolute_Error"] = (
        result["Signed_Error"].abs()
    )

    result["Squared_Error"] = (
        result["Signed_Error"] ** 2
    )

    result["Absolute_Percent_Error"] = np.where(
        result["Actual"].abs() > 0,
        (
            result["Absolute_Error"]
            / result["Actual"].abs()
        ) * 100,
        np.nan,
    )

    result["Error_Direction"] = np.select(
        [
            result["Signed_Error"] > 0,
            result["Signed_Error"] < 0,
        ],
        [
            "Overprediction",
            "Underprediction",
        ],
        default="Exact Match",
    )

    result["Actual_Demand_Band"] = pd.cut(
        result["Actual"],
        bins=[
            -np.inf,
            0,
            10,
            50,
            100,
            np.inf,
        ],
        labels=[
            "Negative",
            "0â€“10",
            "10â€“50",
            "50â€“100",
            "100+",
        ],
        include_lowest=True,
    ).astype(str)

    return result.reset_index(
        drop=True
    )


# ------------------------------------------------------------
# 63.2 â€” IDENTIFY LARGE ERRORS
# ------------------------------------------------------------

def identify_demand_error_root_cause_records(
    dataframe,
    error_threshold,
    percentage_threshold,
    error_rule="Absolute Error",
):
    """Flag records exceeding user-defined error thresholds."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    if error_threshold < 0:
        raise ValueError(
            "Absolute error threshold cannot be negative."
        )

    if percentage_threshold < 0:
        raise ValueError(
            "Percentage error threshold cannot be negative."
        )

    result = dataframe.copy()

    absolute_flag = (
        result["Absolute_Error"]
        > error_threshold
    )

    percentage_available = (
        result["Absolute_Percent_Error"].notna()
    )

    percentage_flag = (
        percentage_available
        & (
            result["Absolute_Percent_Error"]
            > percentage_threshold
        )
    )

    if error_rule == "Absolute Error":
        flagged = absolute_flag

    elif error_rule == "Percentage Error":
        flagged = percentage_flag

    elif error_rule == "Either Rule":
        flagged = (
            absolute_flag
            | percentage_flag
        )

    elif error_rule == "Both Rules":
        flagged = (
            absolute_flag
            & percentage_flag
        )

    else:
        raise ValueError(
            "Unsupported error investigation rule."
        )

    result["Root_Cause_Review_Flag"] = flagged

    result["Investigation_Category"] = np.select(
        [
            ~flagged,
            flagged
            & (
                result["Error_Direction"]
                == "Overprediction"
            ),
            flagged
            & (
                result["Error_Direction"]
                == "Underprediction"
            ),
        ],
        [
            "Within Investigation Threshold",
            "Large Overprediction",
            "Large Underprediction",
        ],
        default="Review Required",
    )

    return result


# ------------------------------------------------------------
# 63.3 â€” SUMMARIZE ERRORS BY DEMAND LEVEL
# ------------------------------------------------------------

def summarize_demand_error_by_demand_band(
    dataframe,
):
    """Compare errors across actual demand bands."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    rows = []

    for band, group in dataframe.groupby(
        "Actual_Demand_Band",
        observed=False,
        dropna=False,
    ):
        if group.empty:
            continue

        rows.append({
            "Actual_Demand_Band": str(band),
            "Observations": int(len(group)),
            "Mean_Actual": float(
                group["Actual"].mean()
            ),
            "Mean_Predicted": float(
                group["Predicted"].mean()
            ),
            "MAE": float(
                group["Absolute_Error"].mean()
            ),
            "RMSE": float(
                np.sqrt(
                    group["Squared_Error"].mean()
                )
            ),
            "Mean_Bias": float(
                group["Signed_Error"].mean()
            ),
            "Mean_Absolute_Percent_Error": (
                float(
                    group["Absolute_Percent_Error"].mean()
                )
                if group[
                    "Absolute_Percent_Error"
                ].notna().any()
                else np.nan
            ),
            "Flagged_Records": int(
                group[
                    "Root_Cause_Review_Flag"
                ].sum()
            ),
        })

    return pd.DataFrame(
        rows
    )


# ------------------------------------------------------------
# 63.4 â€” SUMMARIZE ERRORS BY SEGMENT
# ------------------------------------------------------------

def summarize_demand_error_by_segment(
    dataframe,
):
    """Compare forecast errors across an optional segment column."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    if "Segment" not in dataframe.columns:
        return pd.DataFrame()

    summary = dataframe.groupby(
        "Segment",
        dropna=False,
    ).agg(
        Observations=("Actual", "count"),
        Mean_Actual=("Actual", "mean"),
        Mean_Predicted=("Predicted", "mean"),
        MAE=("Absolute_Error", "mean"),
        Mean_Bias=("Signed_Error", "mean"),
        Flagged_Records=(
            "Root_Cause_Review_Flag",
            "sum",
        ),
    ).reset_index()

    summary["RMSE"] = (
        dataframe.groupby(
            "Segment",
            dropna=False,
        )["Squared_Error"]
        .mean()
        .pow(0.5)
        .to_numpy()
    )

    summary["Flagged_Percent"] = np.where(
        summary["Observations"] > 0,
        (
            summary["Flagged_Records"]
            / summary["Observations"]
        ) * 100,
        np.nan,
    )

    return summary.sort_values(
        "MAE",
        ascending=False,
    )


# ------------------------------------------------------------
# 63.5 â€” SUMMARIZE ERRORS BY TIME PERIOD
# ------------------------------------------------------------

def summarize_demand_error_by_time_period(
    dataframe,
    frequency="Monthly",
):
    """Find time periods with the largest observed errors."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    if "Timestamp" not in dataframe.columns:
        return pd.DataFrame()

    frequency_map = {
        "Daily": "D",
        "Weekly": "W-SUN",
        "Monthly": "MS",
    }

    if frequency not in frequency_map:
        raise ValueError(
            "Unsupported time aggregation frequency."
        )

    working = dataframe.dropna(
        subset=["Timestamp"]
    ).copy()

    if working.empty:
        return pd.DataFrame()

    working = working.set_index(
        "Timestamp"
    )

    summary = working.resample(
        frequency_map[frequency]
    ).agg(
        Observations=("Actual", "count"),
        Actual=("Actual", "sum"),
        Predicted=("Predicted", "sum"),
        MAE=("Absolute_Error", "mean"),
        Mean_Bias=("Signed_Error", "mean"),
        Absolute_Error_Total=("Absolute_Error", "sum"),
        Squared_Error_Total=("Squared_Error", "sum"),
        Flagged_Records=(
            "Root_Cause_Review_Flag",
            "sum",
        ),
    )

    summary["RMSE"] = np.sqrt(
        summary["Squared_Error_Total"]
        / summary["Observations"].replace(
            0,
            np.nan,
        )
    )

    summary["WAPE_Percent"] = np.where(
        summary["Actual"].abs() > 0,
        (
            summary["Absolute_Error_Total"]
            / summary["Actual"].abs()
        ) * 100,
        np.nan,
    )

    summary["Flagged_Percent"] = np.where(
        summary["Observations"] > 0,
        (
            summary["Flagged_Records"]
            / summary["Observations"]
        ) * 100,
        np.nan,
    )

    return summary.reset_index()


# ------------------------------------------------------------
# 63.6 â€” BUILD INVESTIGATION QUEUE
# ------------------------------------------------------------

def build_demand_error_root_cause_queue(
    dataframe,
    maximum_records=100,
):
    """Rank flagged predictions by absolute error."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    queue = dataframe.loc[
        dataframe["Root_Cause_Review_Flag"]
    ].copy()

    if queue.empty:
        return queue

    queue = queue.sort_values(
        "Absolute_Error",
        ascending=False,
    ).head(
        maximum_records
    )

    queue.insert(
        0,
        "Investigation_Rank",
        range(1, len(queue) + 1),
    )

    columns = [
        "Investigation_Rank",
        "Timestamp",
        "Segment",
        "Actual",
        "Predicted",
        "Signed_Error",
        "Absolute_Error",
        "Absolute_Percent_Error",
        "Error_Direction",
        "Actual_Demand_Band",
        "Investigation_Category",
    ]

    return queue[
        [
            column
            for column in columns
            if column in queue.columns
        ]
    ]


# ------------------------------------------------------------
# 63.7 â€” GENERATE INVESTIGATION HYPOTHESES
# ------------------------------------------------------------

def generate_demand_error_root_cause_hypotheses(
    dataframe,
    demand_band_summary,
    segment_summary,
    time_summary,
):
    """Suggest areas to investigate without claiming proven causes."""

    hypotheses = []

    if dataframe is None or dataframe.empty:
        return [
            "Upload valid actual and predicted observations first."
        ]

    over_count = int(
        (
            dataframe["Error_Direction"]
            == "Overprediction"
        ).sum()
    )

    under_count = int(
        (
            dataframe["Error_Direction"]
            == "Underprediction"
        ).sum()
    )

    if over_count > under_count:
        hypotheses.append(
            "Overpredictions occur more frequently than underpredictions. "
            "Review whether the model systematically overestimates demand "
            "in particular periods or demand bands."
        )

    elif under_count > over_count:
        hypotheses.append(
            "Underpredictions occur more frequently than overpredictions. "
            "Review whether demand peaks or upward changes are being missed."
        )

    else:
        hypotheses.append(
            "Overprediction and underprediction counts are equal. "
            "Inspect error magnitude and segment-level patterns before "
            "concluding that forecast errors are balanced."
        )

    if (
        demand_band_summary is not None
        and not demand_band_summary.empty
    ):
        observed_bands = demand_band_summary.loc[
            demand_band_summary["Observations"] > 0
        ]

        if not observed_bands.empty:
            worst_band = observed_bands.loc[
                observed_bands["MAE"].idxmax()
            ]

            hypotheses.append(
                f"The {worst_band['Actual_Demand_Band']} actual-demand "
                f"band has the largest MAE ({worst_band['MAE']:.3f}). "
                "Review the prediction distribution and sample size for "
                "that band."
            )

    if (
        segment_summary is not None
        and not segment_summary.empty
    ):
        largest_segment = segment_summary.iloc[0]

        hypotheses.append(
            f"Segment '{largest_segment['Segment']}' has the largest "
            f"segment-level MAE ({largest_segment['MAE']:.3f}). "
            "Check whether the segment has unusual data coverage or "
            "different demand patterns."
        )

    if (
        time_summary is not None
        and not time_summary.empty
    ):
        observed_periods = time_summary.loc[
            time_summary["Observations"] > 0
        ]

        if not observed_periods.empty:
            worst_period = observed_periods.loc[
                observed_periods["MAE"].idxmax()
            ]

            hypotheses.append(
                f"The period beginning {worst_period['Timestamp']} has "
                f"the highest period MAE ({worst_period['MAE']:.3f}). "
                "Review holidays, seasonality, source-data changes and "
                "prediction alignment for that period."
            )

    hypotheses.append(
        "These are investigation hypotheses derived from observed error "
        "patterns, not confirmed root causes. Confirm causes using source "
        "data, model features and the training/evaluation workflow."
    )

    return hypotheses


