# ------------------------------------------------------------
# 63.13 â€” MAIN ROOT-CAUSE CENTER
# ------------------------------------------------------------

def render_demand_error_root_cause_center():
    """Render the complete error root-cause investigation center."""

    st.header(
        "Ferry Demand Forecast Error Root-Cause Investigation Center"
    )

    st.markdown(
        """
        Investigate where forecast errors are concentrated by demand
        level, optional segment and time period. This center highlights
        patterns for review; it does not automatically establish causality.
        """
    )

    uploaded_file = st.file_uploader(
        "Upload actual and predicted demand CSV",
        type=["csv"],
        key="demand_error_root_cause_upload",
    )

    if uploaded_file is None:
        st.info(
            "Upload a CSV containing actual and predicted demand."
        )
        return

    try:
        source_data = pd.read_csv(
            uploaded_file
        )
    except Exception as error:
        st.error(
            f"Unable to read uploaded CSV: {error}"
        )
        return

    if source_data.empty:
        st.warning(
            "The uploaded CSV contains no data rows."
        )
        return

    columns = source_data.columns.tolist()

    col1, col2 = st.columns(2)

    actual_column = col1.selectbox(
        "Actual demand column",
        options=columns,
        index=_ferry_column_index(columns, "actual"),
        key="demand_error_root_cause_actual_v2",
    )

    predicted_options = [
        column
        for column in columns
        if column != actual_column
    ]

    if not predicted_options:
        st.error(
            "A separate predicted demand column is required."
        )
        return

    predicted_column = col2.selectbox(
        "Predicted demand column",
        options=predicted_options,
        index=_ferry_column_index(predicted_options, "predicted"),
        key="demand_error_root_cause_predicted_v2",
    )

    remaining_columns = [
        column
        for column in columns
        if column not in [
            actual_column,
            predicted_column,
        ]
    ]

    timestamp_options = [
        "No timestamp"
    ] + remaining_columns

    timestamp_column = st.selectbox(
        "Optional timestamp column",
        options=timestamp_options,
        index=_ferry_column_index(
            timestamp_options, "timestamp", fallback="No timestamp"
        ),
        key="demand_error_root_cause_timestamp_v2",
    )

    if timestamp_column == "No timestamp":
        timestamp_column = None

    segment_options = [
        "No segment"
    ] + [
        column
        for column in remaining_columns
        if column != timestamp_column
    ]

    segment_column = st.selectbox(
        "Optional segment column",
        options=segment_options,
        key="demand_error_root_cause_segment",
    )

    if segment_column == "No segment":
        segment_column = None

    col3, col4 = st.columns(2)

    error_threshold = col3.number_input(
        "Absolute error review threshold",
        min_value=0.0,
        value=10.0,
        step=1.0,
        key="demand_error_root_cause_absolute_threshold",
    )

    percentage_threshold = col4.number_input(
        "Absolute percentage error threshold (%)",
        min_value=0.0,
        value=20.0,
        step=1.0,
        key="demand_error_root_cause_percentage_threshold",
    )

    error_rule = st.selectbox(
        "Investigation rule",
        options=[
            "Absolute Error",
            "Percentage Error",
            "Either Rule",
            "Both Rules",
        ],
        key="demand_error_root_cause_rule",
    )

    time_frequency = st.selectbox(
        "Time analysis frequency",
        options=[
            "Daily",
            "Weekly",
            "Monthly",
        ],
        index=2,
        key="demand_error_root_cause_frequency",
    )

    maximum_records = st.number_input(
        "Maximum investigation queue records",
        min_value=10,
        max_value=1000,
        value=100,
        step=10,
        key="demand_error_root_cause_max_records",
    )

    try:
        prepared = prepare_demand_error_root_cause_data(
            source_data,
            actual_column,
            predicted_column,
            timestamp_column,
            segment_column,
        )

        if prepared.empty:
            st.warning(
                "No valid actual-predicted pairs were found."
            )
            return

        classified = identify_demand_error_root_cause_records(
            prepared,
            error_threshold,
            percentage_threshold,
            error_rule,
        )

        demand_band_summary = (
            summarize_demand_error_by_demand_band(
                classified
            )
        )

        segment_summary = (
            summarize_demand_error_by_segment(
                classified
            )
        )

        time_summary = (
            summarize_demand_error_by_time_period(
                classified,
                time_frequency,
            )
        )

        queue = build_demand_error_root_cause_queue(
            classified,
            int(maximum_records),
        )

        hypotheses = (
            generate_demand_error_root_cause_hypotheses(
                classified,
                demand_band_summary,
                segment_summary,
                time_summary,
            )
        )

    except Exception as error:
        st.error(
            f"Root-cause investigation failed: {error}"
        )
        return

    st.divider()

    render_demand_error_root_cause_overview(
        classified
    )

    st.divider()

    render_demand_error_root_cause_demand_bands(
        demand_band_summary
    )

    st.divider()

    render_demand_error_root_cause_segments(
        segment_summary
    )

    st.divider()

    render_demand_error_root_cause_time(
        time_summary
    )

    st.divider()

    render_demand_error_root_cause_queue(
        queue
    )

    st.divider()

    st.subheader(
        "Suggested Investigation Hypotheses"
    )

    for hypothesis in hypotheses:
        st.markdown(
            f"- {hypothesis}"
        )

    st.download_button(
        label="Download Classified Error Records",
        data=classified.to_csv(
            index=False
        ).encode("utf-8"),
        file_name="ferry_demand_root_cause_classified.csv",
        mime="text/csv",
        key="demand_error_root_cause_export_records",
    )

    st.download_button(
        label="Download Demand-Band Summary",
        data=demand_band_summary.to_csv(
            index=False
        ).encode("utf-8"),
        file_name="ferry_demand_root_cause_demand_bands.csv",
        mime="text/csv",
        key="demand_error_root_cause_export_bands",
    )

    if not segment_summary.empty:
        st.download_button(
            label="Download Segment Summary",
            data=segment_summary.to_csv(
                index=False
            ).encode("utf-8"),
            file_name="ferry_demand_root_cause_segments.csv",
            mime="text/csv",
            key="demand_error_root_cause_export_segments",
        )

    if not time_summary.empty:
        st.download_button(
            label="Download Time Summary",
            data=time_summary.to_csv(
                index=False
            ).encode("utf-8"),
            file_name="ferry_demand_root_cause_time.csv",
            mime="text/csv",
            key="demand_error_root_cause_export_time",
        )

    if not queue.empty:
        st.download_button(
            label="Download Investigation Queue",
            data=queue.to_csv(
                index=False
            ).encode("utf-8"),
            file_name="ferry_demand_root_cause_queue.csv",
            mime="text/csv",
            key="demand_error_root_cause_export_queue",
        )

    with st.expander(
        "Methodology & Limitations"
    ):
        st.markdown(
            """
            - Actual demand bands use fixed illustrative boundaries and may
              need adjustment for the dataset's measurement units.
            - A segment with high MAE may have larger demand values or a
              different scale; compare metrics and sample sizes carefully.
            - Time-based comparisons require timestamps that align with the
              periods represented by actual and predicted values.
            - Percentage error is undefined when actual demand is zero.
            - The module identifies associations and unusual error patterns,
              not confirmed causal explanations.
            - The investigation queue is ranked by absolute error and
              limited to the configured number of records.
            """
        )

    st.caption(
        "Forecast Error Root-Cause Investigation Center "
        f"v{DEMAND_ERROR_ROOT_CAUSE_VERSION}"
    )


