# ------------------------------------------------------------
# 64.1 â€” PREPARE MODEL EVALUATION DATA
# ------------------------------------------------------------

def prepare_demand_model_selection_data(
    dataframe,
    timestamp_column,
    actual_column,
    predicted_column,
    model_name,
):
    """Prepare one model's actual-versus-predicted observations."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    required_columns = [
        actual_column,
        predicted_column,
    ]

    if timestamp_column:
        required_columns.append(timestamp_column)

    missing_columns = [
        column
        for column in required_columns
        if column not in dataframe.columns
    ]

    if missing_columns:
        raise ValueError(
            "Missing required columns: "
            + ", ".join(missing_columns)
        )

    result = pd.DataFrame()

    if timestamp_column:
        result["Timestamp"] = pd.to_datetime(
            dataframe[timestamp_column],
            errors="coerce",
        )

    result["Actual"] = pd.to_numeric(
        dataframe[actual_column],
        errors="coerce",
    )

    result["Predicted"] = pd.to_numeric(
        dataframe[predicted_column],
        errors="coerce",
    )

    result["Actual"] = result["Actual"].replace(
        [np.inf, -np.inf],
        np.nan,
    )

    result["Predicted"] = result["Predicted"].replace(
        [np.inf, -np.inf],
        np.nan,
    )

    result = result.dropna(
        subset=[
            "Actual",
            "Predicted",
        ]
    ).copy()

    if result.empty:
        return result

    result["Model"] = str(
        model_name
    )

    result["Signed_Error"] = (
        result["Predicted"]
        - result["Actual"]
    )

    result["Absolute_Error"] = (
        result["Signed_Error"].abs()
    )

    result["Squared_Error"] = (
        result["Signed_Error"] ** 2
    )

    result["Absolute_Percent_Error"] = np.where(
        result["Actual"].abs() > 0,
        (
            result["Absolute_Error"]
            / result["Actual"].abs()
        ) * 100,
        np.nan,
    )

    return result.reset_index(
        drop=True
    )


# ------------------------------------------------------------
# 64.2 â€” CALCULATE METRICS FOR ONE MODEL
# ------------------------------------------------------------

def calculate_demand_model_selection_metrics(
    dataframe,
):
    """Calculate comparable metrics for one model."""

    if dataframe is None or dataframe.empty:
        return {}

    valid = dataframe.loc[
        dataframe["Actual"].notna()
        & dataframe["Predicted"].notna()
        & np.isfinite(dataframe["Actual"])
        & np.isfinite(dataframe["Predicted"])
    ].copy()

    if valid.empty:
        return {
            "Observations": 0,
            "MAE": np.nan,
            "RMSE": np.nan,
            "WAPE_Percent": np.nan,
            "MAPE_Percent": np.nan,
            "Bias": np.nan,
            "Bias_Percent": np.nan,
        }

    absolute_error_total = float(
        valid["Absolute_Error"].sum()
    )

    actual_absolute_total = float(
        valid["Actual"].abs().sum()
    )

    actual_nonzero = valid.loc[
        valid["Actual"].abs() > 0
    ]

    actual_signed_total = float(
        valid["Actual"].sum()
    )

    return {
        "Observations": int(
            len(valid)
        ),
        "MAE": float(
            valid["Absolute_Error"].mean()
        ),
        "RMSE": float(
            np.sqrt(
                valid["Squared_Error"].mean()
            )
        ),
        "WAPE_Percent": (
            absolute_error_total
            / actual_absolute_total
            * 100
            if actual_absolute_total > 0
            else np.nan
        ),
        "MAPE_Percent": (
            float(
                (
                    actual_nonzero["Absolute_Error"]
                    / actual_nonzero["Actual"].abs()
                ).mean()
                * 100
            )
            if not actual_nonzero.empty
            else np.nan
        ),
        "Bias": float(
            valid["Signed_Error"].mean()
        ),
        "Bias_Percent": (
            float(
                (
                    valid["Signed_Error"].sum()
                    / actual_absolute_total
                ) * 100
            )
            if actual_absolute_total > 0
            else np.nan
        ),
        "Actual_Total": actual_signed_total,
        "Predicted_Total": float(
            valid["Predicted"].sum()
        ),
    }


# ------------------------------------------------------------
# 64.3 â€” BUILD MODEL LEADERBOARD
# ------------------------------------------------------------

def build_demand_model_selection_leaderboard(
    dataframe,
):
    """Create a metric leaderboard from uploaded model predictions."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    if "Model" not in dataframe.columns:
        return pd.DataFrame()

    leaderboard_rows = []

    for model_name, model_data in dataframe.groupby(
        "Model",
        dropna=False,
    ):
        metrics = calculate_demand_model_selection_metrics(
            model_data
        )

        metrics["Model"] = str(
            model_name
        )

        leaderboard_rows.append(
            metrics
        )

    leaderboard = pd.DataFrame(
        leaderboard_rows
    )

    if leaderboard.empty:
        return leaderboard

    leaderboard = leaderboard.sort_values(
        by="MAE",
        ascending=True,
        na_position="last",
    ).reset_index(
        drop=True
    )

    leaderboard.insert(
        0,
        "MAE_Rank",
        range(1, len(leaderboard) + 1),
    )

    return leaderboard


# ------------------------------------------------------------
# 64.4 â€” CHECK TIMESTAMP ALIGNMENT
# ------------------------------------------------------------

def calculate_demand_model_alignment_report(
    dataframe,
):
    """
    Describe timestamp coverage for each model.

    This checks timestamp presence and uniqueness. It does not establish
    that actual values from different uploads refer to identical targets.
    """

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    if "Timestamp" not in dataframe.columns:
        return pd.DataFrame()

    rows = []

    for model_name, model_data in dataframe.groupby(
        "Model",
        dropna=False,
    ):
        timestamps = model_data[
            "Timestamp"
        ].dropna()

        rows.append({
            "Model": str(model_name),
            "Valid_Timestamps": int(
                timestamps.count()
            ),
            "Distinct_Timestamps": int(
                timestamps.nunique()
            ),
            "Repeated_Timestamp_Rows": int(
                timestamps.duplicated(
                    keep=False
                ).sum()
            ),
            "First_Timestamp": (
                timestamps.min()
                if not timestamps.empty
                else pd.NaT
            ),
            "Last_Timestamp": (
                timestamps.max()
                if not timestamps.empty
                else pd.NaT
            ),
        })

    return pd.DataFrame(
        rows
    )


# ------------------------------------------------------------
# 64.5 â€” COMPARE MODELS ON COMMON TIMESTAMPS
# ------------------------------------------------------------

def compare_demand_models_on_common_timestamps(
    dataframe,
):
    """
    Compare models using only timestamps present for every model.

    If multiple rows exist for the same model and timestamp, their
    predictions are averaged. Actual values are also averaged per
    model/timestamp, so inspect the alignment report before relying
    on this comparison.
    """

    if dataframe is None or dataframe.empty:
        return pd.DataFrame(), pd.DataFrame()

    if "Timestamp" not in dataframe.columns:
        return pd.DataFrame(), pd.DataFrame()

    working = dataframe.dropna(
        subset=["Timestamp"]
    ).copy()

    if working.empty:
        return pd.DataFrame(), pd.DataFrame()

    model_names = working[
        "Model"
    ].dropna().unique().tolist()

    if len(model_names) < 2:
        return pd.DataFrame(), pd.DataFrame()

    timestamp_counts = (
        working.groupby("Model")["Timestamp"]
        .nunique()
    )

    if timestamp_counts.empty:
        return pd.DataFrame(), pd.DataFrame()

    # A timestamp is common only if each model has at least one
    # valid prediction at that timestamp.
    model_timestamp_sets = [
        set(
            working.loc[
                working["Model"] == model_name,
                "Timestamp",
            ].tolist()
        )
        for model_name in model_names
    ]

    common_timestamps = set.intersection(
        *model_timestamp_sets
    )

    if not common_timestamps:
        return pd.DataFrame(), pd.DataFrame()

    common = working.loc[
        working["Timestamp"].isin(
            common_timestamps
        )
    ].copy()

    aligned = common.groupby(
        ["Timestamp", "Model"],
        as_index=False,
    ).agg(
        Actual=("Actual", "mean"),
        Predicted=("Predicted", "mean"),
    )

    actual_counts = aligned.groupby(
        "Timestamp"
    )["Actual"].nunique()

    inconsistent_timestamps = actual_counts[
        actual_counts > 1
    ].index

    if len(inconsistent_timestamps) > 0:
        aligned = aligned.loc[
            ~aligned["Timestamp"].isin(
                inconsistent_timestamps
            )
        ].copy()

    if aligned.empty:
        return pd.DataFrame(), pd.DataFrame()

    aligned["Signed_Error"] = (
        aligned["Predicted"]
        - aligned["Actual"]
    )

    aligned["Absolute_Error"] = (
        aligned["Signed_Error"].abs()
    )

    aligned["Squared_Error"] = (
        aligned["Signed_Error"] ** 2
    )

    common_rows = []

    for model_name, model_data in aligned.groupby(
        "Model",
        dropna=False,
    ):
        metrics = calculate_demand_model_selection_metrics(
            model_data
        )

        metrics["Model"] = str(
            model_name
        )

        common_rows.append(
            metrics
        )

    common_leaderboard = pd.DataFrame(
        common_rows
    )

    if not common_leaderboard.empty:
        common_leaderboard = (
            common_leaderboard.sort_values(
                "MAE",
                ascending=True,
                na_position="last",
            ).reset_index(
                drop=True
            )
        )

        common_leaderboard.insert(
            0,
            "Common_Timestamp_MAE_Rank",
            range(
                1,
                len(common_leaderboard) + 1,
            ),
        )

    return aligned, common_leaderboard


# ------------------------------------------------------------
# 64.6 â€” GENERATE MODEL SELECTION NOTES
# ------------------------------------------------------------

def generate_demand_model_selection_notes(
    leaderboard,
    common_leaderboard=None,
):
    """Generate descriptive notes about model comparison."""

    notes = []

    if leaderboard is None or leaderboard.empty:
        return [
            "No valid model leaderboard is available."
        ]

    usable = leaderboard.loc[
        leaderboard["MAE"].notna()
    ]

    if usable.empty:
        return [
            "No model has sufficient valid observations to calculate MAE."
        ]

    best = usable.iloc[0]

    notes.append(
        f"Based on the uploaded observations, '{best['Model']}' "
        f"has the lowest MAE ({best['MAE']:.3f}) in the overall "
        "leaderboard."
    )

    if len(usable) >= 2:
        second = usable.iloc[1]

        notes.append(
            f"The second-ranked model by MAE is '{second['Model']}' "
            f"with MAE {second['MAE']:.3f}."
        )

    if common_leaderboard is not None:
        common_usable = common_leaderboard.loc[
            common_leaderboard["MAE"].notna()
        ]

        if not common_usable.empty:
            common_best = common_usable.iloc[0]

            notes.append(
                f"On the common-timestamp comparison, "
                f"'{common_best['Model']}' has the lowest MAE "
                f"({common_best['MAE']:.3f})."
            )
        else:
            notes.append(
                "A common-timestamp comparison could not be produced. "
                "Check timestamp coverage and actual-value consistency."
            )

    notes.append(
        "The leaderboard is trustworthy only when the models are "
        "evaluated against equivalent targets and comparable time periods."
    )

    notes.append(
        "Select a model using chronological holdout or rolling-origin "
        "evaluation, appropriate baselines and operational error costs; "
        "lowest uploaded-sample MAE alone is not enough."
    )

    return notes


