# ------------------------------------------------------------
# 64.11 â€” MAIN MODEL SELECTION CENTER
# ------------------------------------------------------------

def render_demand_model_selection_center():
    """Render model comparison using uploaded prediction CSV files."""

    st.header(
        "Ferry Demand Forecast Model Comparison & Selection Center"
    )

    st.markdown(
        """
        Compare prediction outputs from multiple models using common
        error metrics. Upload one CSV per model, with actual demand,
        predicted demand and preferably a timestamp column.
        """
    )

    st.caption(
        "This center evaluates supplied predictions. It does not train "
        "models or generate forecasts."
    )

    number_of_models = st.number_input(
        "Number of model prediction files",
        min_value=2,
        max_value=10,
        value=2,
        step=1,
        key="demand_model_selection_file_count",
    )

    uploaded_models = []

    for index in range(
        int(number_of_models)
    ):
        st.subheader(
            f"Model {index + 1}"
        )

        model_name = st.text_input(
            f"Model name {index + 1}",
            value=f"Model_{index + 1}",
            key=f"demand_model_selection_name_{index}",
        )

        uploaded_file = st.file_uploader(
            f"Upload prediction CSV {index + 1}",
            type=["csv"],
            key=f"demand_model_selection_file_{index}",
        )

        if uploaded_file is None:
            continue

        try:
            source_data = pd.read_csv(
                uploaded_file
            )
        except Exception as error:
            st.error(
                f"Unable to read file {index + 1}: {error}"
            )
            continue

        if source_data.empty:
            st.warning(
                f"File {index + 1} contains no data rows."
            )
            continue

        uploaded_models.append({
            "model_name": model_name.strip()
            or f"Model_{index + 1}",
            "source_data": source_data,
        })

    if len(uploaded_models) < 2:
        st.info(
            "Upload at least two valid prediction files to compare models."
        )
        return

    prepared_models = []
    preparation_errors = []

    for model_item in uploaded_models:
        source_data = model_item["source_data"]

        st.markdown(
            f"**Configure: {model_item['model_name']}**"
        )

        columns = source_data.columns.tolist()

        col1, col2 = st.columns(2)

        actual_column = col1.selectbox(
            f"Actual column â€” {model_item['model_name']}",
            options=columns,
            index=_ferry_column_index(columns, "actual"),
            key=(
                "demand_model_selection_actual_v2_"
                + model_item["model_name"]
            ),
        )

        predicted_options = [
            column
            for column in columns
            if column != actual_column
        ]

        if not predicted_options:
            preparation_errors.append(
                f"{model_item['model_name']}: no separate predicted column."
            )
            continue

        predicted_column = col2.selectbox(
            f"Predicted column â€” {model_item['model_name']}",
            options=predicted_options,
            index=_ferry_column_index(predicted_options, "predicted"),
            key=(
                "demand_model_selection_predicted_v2_"
                + model_item["model_name"]
            ),
        )

        remaining_columns = [
            column
            for column in columns
            if column not in [
                actual_column,
                predicted_column,
            ]
        ]

        timestamp_options = [
            "No timestamp"
        ] + remaining_columns

        timestamp_column = st.selectbox(
            f"Timestamp column â€” {model_item['model_name']}",
            options=timestamp_options,
            index=_ferry_column_index(
                timestamp_options, "timestamp", fallback="No timestamp"
            ),
            key=(
                "demand_model_selection_timestamp_v2_"
                + model_item["model_name"]
            ),
        )

        if timestamp_column == "No timestamp":
            timestamp_column = None

        try:
            prepared = prepare_demand_model_selection_data(
                source_data,
                timestamp_column,
                actual_column,
                predicted_column,
                model_item["model_name"],
            )

            if not prepared.empty:
                prepared_models.append(
                    prepared
                )
            else:
                preparation_errors.append(
                    f"{model_item['model_name']}: no valid prediction pairs."
                )

        except Exception as error:
            preparation_errors.append(
                f"{model_item['model_name']}: {error}"
            )

    if preparation_errors:
        with st.expander(
            "Input preparation messages"
        ):
            for message in preparation_errors:
                st.warning(
                    message
                )

    if len(prepared_models) < 2:
        st.warning(
            "At least two model files must contain valid prediction pairs."
        )
        return

    combined = pd.concat(
        prepared_models,
        ignore_index=True,
    )

    leaderboard = build_demand_model_selection_leaderboard(
        combined
    )

    alignment_report = calculate_demand_model_alignment_report(
        combined
    )

    aligned_data, common_leaderboard = (
        compare_demand_models_on_common_timestamps(
            combined
        )
    )

    notes = generate_demand_model_selection_notes(
        leaderboard,
        common_leaderboard,
    )

    st.divider()

    render_demand_model_selection_leaderboard(
        leaderboard
    )

    st.divider()

    render_demand_model_alignment_report(
        alignment_report
    )

    st.divider()

    render_demand_model_common_comparison(
        common_leaderboard
    )

    st.divider()

    render_demand_model_selection_notes(
        notes
    )

    st.download_button(
        label="Download Overall Model Leaderboard",
        data=leaderboard.to_csv(
            index=False
        ).encode("utf-8"),
        file_name="ferry_demand_model_selection_leaderboard.csv",
        mime="text/csv",
        key="demand_model_selection_export_leaderboard",
    )

    if not alignment_report.empty:
        st.download_button(
            label="Download Timestamp Alignment Report",
            data=alignment_report.to_csv(
                index=False
            ).encode("utf-8"),
            file_name="ferry_demand_model_timestamp_alignment.csv",
            mime="text/csv",
            key="demand_model_selection_export_alignment",
        )

    if not common_leaderboard.empty:
        st.download_button(
            label="Download Common-Timestamp Leaderboard",
            data=common_leaderboard.to_csv(
                index=False
            ).encode("utf-8"),
            file_name="ferry_demand_model_common_timestamp_leaderboard.csv",
            mime="text/csv",
            key="demand_model_selection_export_common",
        )

    if not aligned_data.empty:
        st.download_button(
            label="Download Aligned Prediction Records",
            data=aligned_data.to_csv(
                index=False
            ).encode("utf-8"),
            file_name="ferry_demand_model_aligned_predictions.csv",
            mime="text/csv",
            key="demand_model_selection_export_aligned",
        )

    with st.expander(
        "Metric Definitions & Comparison Limitations"
    ):
        st.markdown(
            """
            - **MAE:** Average absolute prediction error.
            - **RMSE:** Penalizes larger errors more heavily than MAE.
            - **WAPE:** Total absolute error divided by total absolute actual
              demand; unavailable when the denominator is zero.
            - **MAPE:** Average percentage error over non-zero actual values.
            - **Bias:** Mean predicted-minus-actual error.
            - Models must use comparable target definitions, forecasting
              horizons, timestamps and evaluation periods.
            - If files contain different actual values for the same
              timestamp, those timestamps are excluded from the
              common-timestamp comparison.
            - Lowest historical error does not guarantee best future
              performance. Prefer chronological holdout or rolling-origin
              validation before deployment.
            """
        )

    st.caption(
        "Forecast Model Comparison & Selection Center "
        f"v{DEMAND_MODEL_SELECTION_VERSION}"
    )


