# ------------------------------------------------------------
# 65.1 â€” PREPARE RELIABILITY OBSERVATIONS
# ------------------------------------------------------------

def prepare_demand_model_reliability_data(
    dataframe,
    timestamp_column,
    actual_column,
    predicted_column,
    model_name,
):
    """Prepare and validate actual/predicted values for reliability analysis."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame(), {
            "Source_Rows": 0,
            "Valid_Pairs": 0,
            "Invalid_Timestamps": 0,
            "Invalid_Actual_Values": 0,
            "Invalid_Predicted_Values": 0,
        }

    required_columns = [
        actual_column,
        predicted_column,
    ]

    if timestamp_column:
        required_columns.append(timestamp_column)

    missing_columns = [
        column
        for column in required_columns
        if column not in dataframe.columns
    ]

    if missing_columns:
        raise ValueError(
            "Required columns are missing: "
            + ", ".join(missing_columns)
        )

    source_rows = len(dataframe)

    actual_numeric = pd.to_numeric(
        dataframe[actual_column],
        errors="coerce",
    )

    predicted_numeric = pd.to_numeric(
        dataframe[predicted_column],
        errors="coerce",
    )

    actual_finite = np.isfinite(
        actual_numeric.to_numpy(
            dtype=float,
            na_value=np.nan,
        )
    )

    predicted_finite = np.isfinite(
        predicted_numeric.to_numpy(
            dtype=float,
            na_value=np.nan,
        )
    )

    actual_invalid_count = int(
        (~actual_finite).sum()
    )

    predicted_invalid_count = int(
        (~predicted_finite).sum()
    )

    result = pd.DataFrame(
        {
            "Actual": actual_numeric,
            "Predicted": predicted_numeric,
        },
        index=dataframe.index,
    )

    if timestamp_column:
        result["Timestamp"] = pd.to_datetime(
            dataframe[timestamp_column],
            errors="coerce",
        )

        invalid_timestamp_count = int(
            result["Timestamp"].isna().sum()
        )
    else:
        result["Timestamp"] = pd.NaT
        invalid_timestamp_count = 0

    valid_pair_mask = (
        np.isfinite(
            result["Actual"].to_numpy(
                dtype=float,
                na_value=np.nan,
            )
        )
        & np.isfinite(
            result["Predicted"].to_numpy(
                dtype=float,
                na_value=np.nan,
            )
        )
    )

    result = result.loc[
        valid_pair_mask
    ].copy()

    result["Model"] = str(
        model_name
    )

    result["Error"] = (
        result["Predicted"]
        - result["Actual"]
    )

    result["Absolute_Error"] = (
        result["Error"].abs()
    )

    result["Squared_Error"] = (
        result["Error"] ** 2
    )

    result["Absolute_Actual"] = (
        result["Actual"].abs()
    )

    result["Absolute_Percent_Error"] = np.where(
        result["Absolute_Actual"] > 0,
        (
            result["Absolute_Error"]
            / result["Absolute_Actual"]
        ) * 100,
        np.nan,
    )

    validation = {
        "Source_Rows": int(source_rows),
        "Valid_Pairs": int(len(result)),
        "Invalid_Timestamps": invalid_timestamp_count,
        "Invalid_Actual_Values": actual_invalid_count,
        "Invalid_Predicted_Values": predicted_invalid_count,
    }

    return result.reset_index(
        drop=True
    ), validation


# ------------------------------------------------------------
# 65.2 â€” CALCULATE ERROR STABILITY
# ------------------------------------------------------------

def calculate_demand_model_error_stability(
    dataframe,
):
    """Calculate variation in absolute prediction errors."""

    if dataframe is None or dataframe.empty:
        return {
            "Error_Mean": np.nan,
            "Error_Std": np.nan,
            "Absolute_Error_Mean": np.nan,
            "Absolute_Error_Std": np.nan,
            "Absolute_Error_CV_Percent": np.nan,
            "P90_Absolute_Error": np.nan,
            "P95_Absolute_Error": np.nan,
            "Maximum_Absolute_Error": np.nan,
        }

    errors = pd.to_numeric(
        dataframe["Error"],
        errors="coerce",
    ).replace(
        [np.inf, -np.inf],
        np.nan,
    ).dropna()

    absolute_errors = errors.abs()

    if errors.empty:
        return {
            "Error_Mean": np.nan,
            "Error_Std": np.nan,
            "Absolute_Error_Mean": np.nan,
            "Absolute_Error_Std": np.nan,
            "Absolute_Error_CV_Percent": np.nan,
            "P90_Absolute_Error": np.nan,
            "P95_Absolute_Error": np.nan,
            "Maximum_Absolute_Error": np.nan,
        }

    mean_absolute_error = float(
        absolute_errors.mean()
    )

    std_absolute_error = float(
        absolute_errors.std(ddof=0)
    )

    return {
        "Error_Mean": float(
            errors.mean()
        ),
        "Error_Std": float(
            errors.std(ddof=0)
        ),
        "Absolute_Error_Mean": mean_absolute_error,
        "Absolute_Error_Std": std_absolute_error,
        "Absolute_Error_CV_Percent": (
            std_absolute_error
            / mean_absolute_error
            * 100
            if mean_absolute_error > 0
            else np.nan
        ),
        "P90_Absolute_Error": float(
            absolute_errors.quantile(0.90)
        ),
        "P95_Absolute_Error": float(
            absolute_errors.quantile(0.95)
        ),
        "Maximum_Absolute_Error": float(
            absolute_errors.max()
        ),
    }


# ------------------------------------------------------------
# 65.3 â€” CALCULATE RELIABILITY METRICS
# ------------------------------------------------------------

def calculate_demand_model_reliability_metrics(
    dataframe,
):
    """Calculate accuracy, bias and error-tail metrics."""

    if dataframe is None or dataframe.empty:
        return {}

    actual = dataframe["Actual"].to_numpy(
        dtype=float
    )

    predicted = dataframe["Predicted"].to_numpy(
        dtype=float
    )

    errors = predicted - actual

    absolute_errors = np.abs(
        errors
    )

    absolute_actual_total = float(
        np.abs(actual).sum()
    )

    actual_total = float(
        actual.sum()
    )

    predicted_total = float(
        predicted.sum()
    )

    nonzero_actual_mask = (
        np.abs(actual) > 0
    )

    if len(actual) == 0:
        return {}

    mae = float(
        absolute_errors.mean()
    )

    rmse = float(
        np.sqrt(
            np.mean(errors ** 2)
        )
    )

    bias = float(
        errors.mean()
    )

    wape = (
        float(
            absolute_errors.sum()
            / absolute_actual_total
            * 100
        )
        if absolute_actual_total > 0
        else np.nan
    )

    if nonzero_actual_mask.any():
        mape = float(
            np.mean(
                absolute_errors[nonzero_actual_mask]
                / np.abs(actual[nonzero_actual_mask])
            ) * 100
        )
    else:
        mape = np.nan

    if absolute_actual_total > 0:
        aggregate_bias_percent = float(
            (
                errors.sum()
                / absolute_actual_total
            ) * 100
        )
    else:
        aggregate_bias_percent = np.nan

    stability = calculate_demand_model_error_stability(
        dataframe
    )

    return {
        "Observations": int(
            len(actual)
        ),
        "MAE": mae,
        "RMSE": rmse,
        "WAPE_Percent": wape,
        "MAPE_Percent": mape,
        "Bias": bias,
        "Aggregate_Bias_Percent": aggregate_bias_percent,
        "Actual_Total": actual_total,
        "Predicted_Total": predicted_total,
        "Absolute_Total_Gap": float(
            abs(predicted_total - actual_total)
        ),
        **stability,
    }


# ------------------------------------------------------------
# 65.4 â€” BUILD RELIABILITY SCORECARD
# ------------------------------------------------------------

def build_demand_model_reliability_scorecard(
    combined_data,
    validation_records=None,
):
    """
    Build a transparent heuristic scorecard.

    The score is a diagnostic indicator, not a probability that a
    model will perform correctly in the future.
    """

    if combined_data is None or combined_data.empty:
        return pd.DataFrame()

    if "Model" not in combined_data.columns:
        return pd.DataFrame()

    validation_lookup = {}

    if validation_records:
        for record in validation_records:
            validation_lookup[
                str(record["Model"])
            ] = record

    scorecard_rows = []

    for model_name, model_data in combined_data.groupby(
        "Model",
        dropna=False,
    ):
        metrics = calculate_demand_model_reliability_metrics(
            model_data
        )

        if not metrics:
            continue

        valid_count = metrics.get(
            "Observations",
            0,
        )

        wape = metrics.get(
            "WAPE_Percent",
            np.nan,
        )

        bias_percent = metrics.get(
            "Aggregate_Bias_Percent",
            np.nan,
        )

        error_cv = metrics.get(
            "Absolute_Error_CV_Percent",
            np.nan,
        )

        # Component 1: WAPE performance, 0â€“40 points.
        if pd.notna(wape):
            if wape <= 5:
                accuracy_score = 40
            elif wape <= 10:
                accuracy_score = 35
            elif wape <= 20:
                accuracy_score = 25
            elif wape <= 30:
                accuracy_score = 15
            else:
                accuracy_score = 5
        else:
            accuracy_score = 0

        # Component 2: aggregate bias, 0â€“25 points.
        if pd.notna(bias_percent):
            absolute_bias = abs(
                bias_percent
            )

            if absolute_bias <= 2:
                bias_score = 25
            elif absolute_bias <= 5:
                bias_score = 20
            elif absolute_bias <= 10:
                bias_score = 15
            elif absolute_bias <= 20:
                bias_score = 8
            else:
                bias_score = 2
        else:
            bias_score = 0

        # Component 3: observation coverage, 0â€“20 points.
        if valid_count >= 1000:
            coverage_score = 20
        elif valid_count >= 500:
            coverage_score = 16
        elif valid_count >= 100:
            coverage_score = 12
        elif valid_count >= 30:
            coverage_score = 8
        elif valid_count >= 10:
            coverage_score = 4
        else:
            coverage_score = 0

        # Component 4: absolute-error variability, 0â€“15 points.
        if pd.notna(error_cv):
            if error_cv <= 50:
                stability_score = 15
            elif error_cv <= 100:
                stability_score = 12
            elif error_cv <= 150:
                stability_score = 8
            else:
                stability_score = 4
        else:
            stability_score = 0

        total_score = (
            accuracy_score
            + bias_score
            + coverage_score
            + stability_score
        )

        if valid_count < 10:
            reliability_band = "Insufficient Evidence"
        elif total_score >= 85:
            reliability_band = "Strong Historical Indicators"
        elif total_score >= 70:
            reliability_band = "Moderate Historical Indicators"
        elif total_score >= 50:
            reliability_band = "Weak Historical Indicators"
        else:
            reliability_band = "Poor Historical Indicators"

        validation = validation_lookup.get(
            str(model_name),
            {},
        )

        source_rows = validation.get(
            "Source_Rows",
            valid_count,
        )

        invalid_rows = max(
            int(source_rows) - int(valid_count),
            0,
        )

        valid_pair_percent = (
            valid_count / source_rows * 100
            if source_rows > 0
            else np.nan
        )

        scorecard_rows.append({
            "Model": str(model_name),
            "Reliability_Score": int(
                total_score
            ),
            "Reliability_Band": reliability_band,
            "Accuracy_Score_40": accuracy_score,
            "Bias_Score_25": bias_score,
            "Coverage_Score_20": coverage_score,
            "Stability_Score_15": stability_score,
            "Valid_Observations": int(
                valid_count
            ),
            "Source_Rows": int(
                source_rows
            ),
            "Invalid_Pair_Rows": int(
                invalid_rows
            ),
            "Valid_Pair_Percent": valid_pair_percent,
            "MAE": metrics["MAE"],
            "RMSE": metrics["RMSE"],
            "WAPE_Percent": metrics["WAPE_Percent"],
            "MAPE_Percent": metrics["MAPE_Percent"],
            "Bias": metrics["Bias"],
            "Aggregate_Bias_Percent": (
                metrics["Aggregate_Bias_Percent"]
            ),
            "P95_Absolute_Error": (
                metrics["P95_Absolute_Error"]
            ),
            "Maximum_Absolute_Error": (
                metrics["Maximum_Absolute_Error"]
            ),
        })

    if not scorecard_rows:
        return pd.DataFrame()

    return pd.DataFrame(
        scorecard_rows
    ).sort_values(
        by=[
            "Reliability_Score",
            "MAE",
        ],
        ascending=[
            False,
            True,
        ],
        na_position="last",
    ).reset_index(
        drop=True
    )


# ------------------------------------------------------------
# 65.5 â€” GENERATE RELIABILITY WARNINGS
# ------------------------------------------------------------

def generate_demand_model_reliability_warnings(
    scorecard,
):
    """Generate transparent warnings based on scorecard metrics."""

    warnings = []

    if scorecard is None or scorecard.empty:
        return [
            "A reliability scorecard could not be generated."
        ]

    for _, row in scorecard.iterrows():
        model_name = row["Model"]

        if row["Valid_Observations"] < 30:
            warnings.append(
                f"{model_name}: fewer than 30 valid prediction pairs; "
                "reliability conclusions are limited."
            )

        if (
            pd.notna(row["WAPE_Percent"])
            and row["WAPE_Percent"] > 20
        ):
            warnings.append(
                f"{model_name}: WAPE exceeds 20%; review the size and "
                "distribution of forecasting errors."
            )

        if (
            pd.notna(row["Aggregate_Bias_Percent"])
            and abs(row["Aggregate_Bias_Percent"]) > 10
        ):
            direction = (
                "overpredicts"
                if row["Aggregate_Bias_Percent"] > 0
                else "underpredicts"
            )

            warnings.append(
                f"{model_name}: aggregate bias indicates that it "
                f"{direction} demand on the supplied evaluation data."
            )

        if (
            pd.notna(row["Valid_Pair_Percent"])
            and row["Valid_Pair_Percent"] < 95
        ):
            warnings.append(
                f"{model_name}: fewer than 95% of source rows produced "
                "valid actual/predicted pairs."
            )

    if not warnings:
        warnings.append(
            "No warning thresholds were triggered. This does not "
            "guarantee future forecasting performance."
        )

    return warnings


