# ------------------------------------------------------------
# 65.9 â€” RENDER SCORE EXPLANATION
# ------------------------------------------------------------

def render_demand_model_reliability_methodology():
    """Explain how the heuristic score is constructed."""

    with st.expander(
        "Reliability Score Methodology"
    ):
        st.markdown(
            """
            The score is a **heuristic diagnostic indicator out of 100**.

            | Component | Maximum points | What it examines |
            |---|---:|---|
            | Accuracy | 40 | WAPE thresholds |
            | Bias | 25 | Aggregate predicted-minus-actual bias |
            | Coverage | 20 | Number of valid prediction pairs |
            | Stability | 15 | Variation in absolute errors |

            **Important limitations**

            - The thresholds and weights are configurable in code, not
              statistically calibrated.
            - A high score does not mean the model has a particular
              probability of being correct.
            - A model can score well on one period and perform poorly
              on another.
            - Models should be compared on the same target, forecast
              horizon and chronological evaluation period.
            - The score does not account for vessel capacity, staffing
              constraints, ticket availability or financial costs.
            - Use chronological holdout or rolling-origin backtesting
              before selecting a production forecasting model.
            """
        )


# ------------------------------------------------------------
# 65.10 â€” MAIN RELIABILITY CENTER
# ------------------------------------------------------------

def render_demand_model_reliability_center():
    """Render model reliability analysis from uploaded prediction CSVs."""

    st.header(
        "Ferry Demand Forecast Error & Model Reliability Scorecard"
    )

    st.markdown(
        """
        Evaluate the historical error, bias, error-tail behavior and
        valid-pair coverage of uploaded forecasting results.
        """
    )

    st.caption(
        "This module evaluates supplied predictions; it does not train "
        "models or create new forecasts."
    )

    uploaded_file = st.file_uploader(
        "Upload combined model predictions CSV",
        type=["csv"],
        key="demand_model_reliability_upload",
        help=(
            "Include actual demand, predicted demand and a model-name "
            "column. A timestamp column is optional."
        ),
    )

    if uploaded_file is None:
        st.info(
            "Upload a CSV to calculate the reliability scorecard."
        )

        render_demand_model_reliability_methodology()
        return

    try:
        source_data = pd.read_csv(
            uploaded_file
        )
    except Exception as error:
        st.error(
            f"Unable to read the uploaded file: {error}"
        )
        return

    if source_data.empty:
        st.warning(
            "The uploaded file contains no data rows."
        )
        return

    columns = source_data.columns.tolist()

    if len(columns) < 2:
        st.error(
            "The file needs at least two columns: actual demand and "
            "predicted demand."
        )
        return

    col1, col2 = st.columns(2)

    actual_column = col1.selectbox(
        "Actual demand column",
        options=columns,
        index=_ferry_column_index(columns, "actual"),
        key="demand_model_reliability_actual_column_v2",
    )

    predicted_options = [
        column
        for column in columns
        if column != actual_column
    ]

    predicted_column = col2.selectbox(
        "Predicted demand column",
        options=predicted_options,
        index=_ferry_column_index(predicted_options, "predicted"),
        key="demand_model_reliability_predicted_column_v2",
    )

    remaining_columns = [
        column
        for column in columns
        if column not in [
            actual_column,
            predicted_column,
        ]
    ]

    model_options = ["Single model (no model column)"] + remaining_columns
    model_column = st.selectbox(
        "Model name column",
        options=model_options,
        index=_ferry_column_index(
            model_options, "model",
            fallback="Single model (no model column)"
        ),
        key="demand_model_reliability_model_column_v2",
    )

    timestamp_candidates = [
        column
        for column in remaining_columns
        if column != model_column
    ]
    remaining_timestamp_options = ["No timestamp"] + timestamp_candidates

    timestamp_column = st.selectbox(
        "Timestamp column",
        options=remaining_timestamp_options,
        index=_ferry_column_index(
            remaining_timestamp_options, "timestamp", fallback="No timestamp"
        ),
        key="demand_model_reliability_timestamp_column_v2",
    )

    if timestamp_column == "No timestamp":
        timestamp_column = None

    validation_records = []
    prepared_frames = []

    if model_column == "Single model (no model column)":
        model_groups = [("Uploaded_Model", source_data)]
    else:
        model_groups = source_data.groupby(
            model_column,
            dropna=False,
        )

    for model_name, model_source in model_groups:
        display_name = (
            str(model_name)
            if pd.notna(model_name)
            else "Unknown_Model"
        )

        try:
            prepared, validation = (
                prepare_demand_model_reliability_data(
                    model_source,
                    timestamp_column,
                    actual_column,
                    predicted_column,
                    display_name,
                )
            )

            validation["Model"] = display_name
            validation_records.append(
                validation
            )

            if not prepared.empty:
                prepared_frames.append(
                    prepared
                )

        except Exception as error:
            st.warning(
                f"{display_name}: unable to prepare records â€” {error}"
            )

    if not prepared_frames:
        st.error(
            "No valid actual/predicted pairs were found."
        )
        return

    combined = pd.concat(
        prepared_frames,
        ignore_index=True,
    )

    scorecard = build_demand_model_reliability_scorecard(
        combined,
        validation_records,
    )

    warnings = generate_demand_model_reliability_warnings(
        scorecard
    )

    validation_report = pd.DataFrame(
        validation_records
    )

    st.divider()

    render_demand_model_reliability_overview(
        scorecard
    )

    st.divider()

    render_demand_model_reliability_scorecard(
        scorecard
    )

    st.divider()

    render_demand_model_reliability_warnings(
        warnings
    )

    st.divider()

    st.subheader(
        "Input Validation Report"
    )

    st.dataframe(
        validation_report,
        use_container_width=True,
        hide_index=True,
    )

    st.download_button(
        label="Download Reliability Scorecard",
        data=scorecard.to_csv(
            index=False
        ).encode("utf-8"),
        file_name="ferry_demand_model_reliability_scorecard.csv",
        mime="text/csv",
        key="demand_model_reliability_export_scorecard",
    )

    st.download_button(
        label="Download Input Validation Report",
        data=validation_report.to_csv(
            index=False
        ).encode("utf-8"),
        file_name="ferry_demand_model_reliability_validation.csv",
        mime="text/csv",
        key="demand_model_reliability_export_validation",
    )

    render_demand_model_reliability_methodology()

    st.caption(
        "Model Reliability Scorecard "
        f"v{DEMAND_MODEL_RELIABILITY_VERSION}"
    )


