DEMAND_ACCEPTANCE_GATE_VERSION = "1.0.0"


# ------------------------------------------------------------
# 66.1 â€” PREPARE ACCEPTANCE-GATE DATA
# ------------------------------------------------------------

def prepare_demand_acceptance_gate_data(
    dataframe,
    actual_column,
    predicted_column,
    timestamp_column=None,
):
    """Prepare finite actual/predicted values for acceptance testing."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame(), {
            "Source_Rows": 0,
            "Valid_Pairs": 0,
            "Invalid_Actual": 0,
            "Invalid_Predicted": 0,
            "Invalid_Timestamps": 0,
        }

    required_columns = [
        actual_column,
        predicted_column,
    ]

    if timestamp_column:
        required_columns.append(
            timestamp_column
        )

    missing_columns = [
        column
        for column in required_columns
        if column not in dataframe.columns
    ]

    if missing_columns:
        raise ValueError(
            "Missing columns: "
            + ", ".join(missing_columns)
        )

    source_rows = len(dataframe)

    actual = pd.to_numeric(
        dataframe[actual_column],
        errors="coerce",
    )

    predicted = pd.to_numeric(
        dataframe[predicted_column],
        errors="coerce",
    )

    actual = actual.replace(
        [np.inf, -np.inf],
        np.nan,
    )

    predicted = predicted.replace(
        [np.inf, -np.inf],
        np.nan,
    )

    result = pd.DataFrame(
        {
            "Actual": actual,
            "Predicted": predicted,
        },
        index=dataframe.index,
    )

    if timestamp_column:
        result["Timestamp"] = pd.to_datetime(
            dataframe[timestamp_column],
            errors="coerce",
        )

        invalid_timestamps = int(
            result["Timestamp"].isna().sum()
        )
    else:
        result["Timestamp"] = pd.NaT
        invalid_timestamps = 0

    invalid_actual = int(
        result["Actual"].isna().sum()
    )

    invalid_predicted = int(
        result["Predicted"].isna().sum()
    )

    valid_mask = (
        result["Actual"].notna()
        & result["Predicted"].notna()
    )

    result = result.loc[
        valid_mask
    ].copy()

    result["Error"] = (
        result["Predicted"]
        - result["Actual"]
    )

    result["Absolute_Error"] = (
        result["Error"].abs()
    )

    result["Squared_Error"] = (
        result["Error"] ** 2
    )

    result["Absolute_Actual"] = (
        result["Actual"].abs()
    )

    result["Absolute_Percent_Error"] = np.where(
        result["Absolute_Actual"] > 0,
        (
            result["Absolute_Error"]
            / result["Absolute_Actual"]
        ) * 100,
        np.nan,
    )

    validation = {
        "Source_Rows": int(source_rows),
        "Valid_Pairs": int(len(result)),
        "Invalid_Actual": invalid_actual,
        "Invalid_Predicted": invalid_predicted,
        "Invalid_Timestamps": invalid_timestamps,
    }

    return result.reset_index(
        drop=True
    ), validation


# ------------------------------------------------------------
# 66.2 â€” CALCULATE BENCHMARK METRICS
# ------------------------------------------------------------

def calculate_demand_acceptance_gate_metrics(
    dataframe,
):
    """Calculate accuracy and bias metrics for valid prediction pairs."""

    if dataframe is None or dataframe.empty:
        return {}

    actual = dataframe["Actual"].to_numpy(
        dtype=float
    )

    predicted = dataframe["Predicted"].to_numpy(
        dtype=float
    )

    valid = (
        np.isfinite(actual)
        & np.isfinite(predicted)
    )

    actual = actual[valid]
    predicted = predicted[valid]

    if len(actual) == 0:
        return {}

    error = predicted - actual
    absolute_error = np.abs(error)

    absolute_actual_total = float(
        np.abs(actual).sum()
    )

    nonzero_actual = (
        np.abs(actual) > 0
    )

    mae = float(
        absolute_error.mean()
    )

    rmse = float(
        np.sqrt(
            np.mean(error ** 2)
        )
    )

    wape = (
        float(
            absolute_error.sum()
            / absolute_actual_total
            * 100
        )
        if absolute_actual_total > 0
        else np.nan
    )

    mape = (
        float(
            np.mean(
                absolute_error[nonzero_actual]
                / np.abs(actual[nonzero_actual])
            ) * 100
        )
        if nonzero_actual.any()
        else np.nan
    )

    bias = float(
        error.mean()
    )

    bias_percent = (
        float(
            error.sum()
            / absolute_actual_total
            * 100
        )
        if absolute_actual_total > 0
        else np.nan
    )

    return {
        "Valid_Observations": int(
            len(actual)
        ),
        "MAE": mae,
        "RMSE": rmse,
        "WAPE_Percent": wape,
        "MAPE_Percent": mape,
        "Bias": bias,
        "Aggregate_Bias_Percent": bias_percent,
        "Actual_Total": float(
            actual.sum()
        ),
        "Predicted_Total": float(
            predicted.sum()
        ),
    }


# ------------------------------------------------------------
# 66.3 â€” EVALUATE ACCEPTANCE CRITERIA
# ------------------------------------------------------------

def evaluate_demand_acceptance_gate(
    metrics,
    maximum_wape,
    maximum_absolute_bias_percent,
    minimum_observations,
):
    """Evaluate user-defined criteria without hiding missing metrics."""

    if not metrics:
        return {
            "Acceptance_Status": "INSUFFICIENT DATA",
            "Criteria": [],
            "Passed_Criteria": 0,
            "Failed_Criteria": 0,
            "Unverifiable_Criteria": 3,
        }

    observations = metrics.get(
        "Valid_Observations",
        0,
    )

    wape = metrics.get(
        "WAPE_Percent",
        np.nan,
    )

    bias_percent = metrics.get(
        "Aggregate_Bias_Percent",
        np.nan,
    )

    criteria = [
        {
            "Criterion": "Minimum observations",
            "Observed_Value": observations,
            "Limit": minimum_observations,
            "Status": (
                "PASS"
                if observations >= minimum_observations
                else "FAIL"
            ),
        }
    ]

    if pd.notna(wape):
        criteria.append({
            "Criterion": "Maximum WAPE",
            "Observed_Value": wape,
            "Limit": maximum_wape,
            "Status": (
                "PASS"
                if wape <= maximum_wape
                else "FAIL"
            ),
        })
    else:
        criteria.append({
            "Criterion": "Maximum WAPE",
            "Observed_Value": np.nan,
            "Limit": maximum_wape,
            "Status": "UNVERIFIABLE",
        })

    if pd.notna(bias_percent):
        absolute_bias = abs(
            bias_percent
        )

        criteria.append({
            "Criterion": "Maximum absolute aggregate bias",
            "Observed_Value": absolute_bias,
            "Limit": maximum_absolute_bias_percent,
            "Status": (
                "PASS"
                if absolute_bias <= maximum_absolute_bias_percent
                else "FAIL"
            ),
        })
    else:
        criteria.append({
            "Criterion": "Maximum absolute aggregate bias",
            "Observed_Value": np.nan,
            "Limit": maximum_absolute_bias_percent,
            "Status": "UNVERIFIABLE",
        })

    criteria_df = pd.DataFrame(
        criteria
    )

    failed_count = int(
        (
            criteria_df["Status"] == "FAIL"
        ).sum()
    )

    passed_count = int(
        (
            criteria_df["Status"] == "PASS"
        ).sum()
    )

    unverifiable_count = int(
        (
            criteria_df["Status"] == "UNVERIFIABLE"
        ).sum()
    )

    if failed_count > 0:
        acceptance_status = "NOT ACCEPTED"
    elif unverifiable_count > 0:
        acceptance_status = "INCOMPLETE EVALUATION"
    else:
        acceptance_status = "ACCEPTANCE CRITERIA MET"

    return {
        "Acceptance_Status": acceptance_status,
        "Criteria": criteria_df,
        "Passed_Criteria": passed_count,
        "Failed_Criteria": failed_count,
        "Unverifiable_Criteria": unverifiable_count,
    }


