# 66.4 â€” BUILD BENCHMARK REPORT
# ------------------------------------------------------------

def build_demand_acceptance_gate_report(
    model_name,
    metrics,
    gate_result,
):
    """Combine metrics and acceptance results into one report row."""

    if not metrics:
        metrics = {}

    return pd.DataFrame([
        {
            "Model": str(model_name),
            "Acceptance_Status": gate_result.get(
                "Acceptance_Status",
                "INSUFFICIENT DATA",
            ),
            "Valid_Observations": metrics.get(
                "Valid_Observations",
                0,
            ),
            "MAE": metrics.get(
                "MAE",
                np.nan,
            ),
            "RMSE": metrics.get(
                "RMSE",
                np.nan,
            ),
            "WAPE_Percent": metrics.get(
                "WAPE_Percent",
                np.nan,
            ),
            "MAPE_Percent": metrics.get(
                "MAPE_Percent",
                np.nan,
            ),
            "Bias": metrics.get(
                "Bias",
                np.nan,
            ),
            "Aggregate_Bias_Percent": metrics.get(
                "Aggregate_Bias_Percent",
                np.nan,
            ),
            "Passed_Criteria": gate_result.get(
                "Passed_Criteria",
                0,
            ),
            "Failed_Criteria": gate_result.get(
                "Failed_Criteria",
                0,
            ),
            "Unverifiable_Criteria": gate_result.get(
                "Unverifiable_Criteria",
                0,
            ),
        }
    ])


# ------------------------------------------------------------
# 66.5 â€” GENERATE ACCEPTANCE RECOMMENDATIONS
# ------------------------------------------------------------

def generate_demand_acceptance_gate_recommendations(
    report,
    criteria_report,
):
    """Generate review actions based on acceptance results."""

    recommendations = []

    if report is None or report.empty:
        return [
            "No report is available. Review the uploaded prediction data."
        ]

    status = report.iloc[0][
        "Acceptance_Status"
    ]

    if status == "ACCEPTANCE CRITERIA MET":
        recommendations.append(
            "The uploaded results meet the selected numerical criteria. "
            "Perform chronological holdout or rolling-origin validation "
            "before production use."
        )

    elif status == "NOT ACCEPTED":
        recommendations.append(
            "At least one acceptance criterion failed. Review the "
            "corresponding metric and investigate the largest errors."
        )

    else:
        recommendations.append(
            "The evaluation is incomplete. Verify valid observations "
            "and whether WAPE and aggregate bias can be calculated."
        )

    if (
        criteria_report is not None
        and not criteria_report.empty
    ):
        failed = criteria_report.loc[
            criteria_report["Status"] == "FAIL"
        ]

        for _, row in failed.iterrows():
            recommendations.append(
                f"Review '{row['Criterion']}': observed value "
                f"{row['Observed_Value']} exceeds or does not meet "
                f"the configured acceptance limit {row['Limit']}."
            )

        unverifiable = criteria_report.loc[
            criteria_report["Status"] == "UNVERIFIABLE"
        ]

        for _, row in unverifiable.iterrows():
            recommendations.append(
                f"'{row['Criterion']}' could not be verified from "
                "the available observations."
            )

    recommendations.append(
        "Acceptance thresholds are user-defined operational criteria, "
        "not universal standards for ferry forecasting."
    )

    return recommendations


