# ------------------------------------------------------------
# 66.9 â€” MAIN ACCEPTANCE-GATE CENTER
# ------------------------------------------------------------

def render_demand_acceptance_gate_center():
    """Run the configurable acceptance-gate analysis."""

    st.header(
        "Ferry Demand Forecast Performance Benchmark & Acceptance Gate"
    )

    st.markdown(
        """
        Upload a model's actual-versus-predicted results and evaluate
        them against configurable accuracy, bias and sample-size limits.
        """
    )

    st.caption(
        "This module evaluates uploaded predictions. It does not train "
        "a forecasting model or certify future performance."
    )

    uploaded_file = st.file_uploader(
        "Upload actual-versus-predicted CSV",
        type=["csv"],
        key="demand_acceptance_gate_upload",
    )

    if uploaded_file is None:
        st.info(
            "Upload prediction results to start the acceptance evaluation."
        )
        return

    try:
        source_data = pd.read_csv(
            uploaded_file
        )
    except Exception as error:
        st.error(
            f"Unable to read the uploaded CSV: {error}"
        )
        return

    if source_data.empty:
        st.warning(
            "The uploaded file contains no records."
        )
        return

    columns = source_data.columns.tolist()

    if len(columns) < 2:
        st.error(
            "At least two columns are required: actual and predicted."
        )
        return

    col1, col2 = st.columns(2)

    actual_column = col1.selectbox(
        "Actual demand column",
        options=columns,
        index=_ferry_column_index(columns, "actual"),
        key="demand_acceptance_gate_actual_column_v2",
    )

    predicted_options = [
        column
        for column in columns
        if column != actual_column
    ]

    predicted_column = col2.selectbox(
        "Predicted demand column",
        options=predicted_options,
        index=_ferry_column_index(predicted_options, "predicted"),
        key="demand_acceptance_gate_predicted_column_v2",
    )

    timestamp_options = [
        "No timestamp"
    ] + [
        column
        for column in columns
        if column not in [
            actual_column,
            predicted_column,
        ]
    ]

    timestamp_column = st.selectbox(
        "Optional timestamp column",
        options=timestamp_options,
        index=_ferry_column_index(
            timestamp_options, "timestamp", fallback="No timestamp"
        ),
        key="demand_acceptance_gate_timestamp_column_v2",
    )

    if timestamp_column == "No timestamp":
        timestamp_column = None

    st.subheader(
        "Configure Acceptance Limits"
    )

    col1, col2, col3 = st.columns(3)

    maximum_wape = col1.number_input(
        "Maximum WAPE (%)",
        min_value=0.0,
        max_value=1000.0,
        value=20.0,
        step=1.0,
        key="demand_acceptance_gate_max_wape",
    )

    maximum_absolute_bias_percent = col2.number_input(
        "Maximum absolute aggregate bias (%)",
        min_value=0.0,
        max_value=1000.0,
        value=10.0,
        step=1.0,
        key="demand_acceptance_gate_max_bias",
    )

    minimum_observations = col3.number_input(
        "Minimum valid observations",
        min_value=1,
        max_value=10000000,
        value=30,
        step=1,
        key="demand_acceptance_gate_min_observations",
    )

    model_name = st.text_input(
        "Model name",
        value="Uploaded_Forecast_Model",
        key="demand_acceptance_gate_model_name",
    ).strip()

    try:
        prepared, validation = (
            prepare_demand_acceptance_gate_data(
                source_data,
                actual_column,
                predicted_column,
                timestamp_column,
            )
        )
    except Exception as error:
        st.error(
            f"Unable to prepare prediction data: {error}"
        )
        return

    st.subheader(
        "Input Validation"
    )

    st.dataframe(
        pd.DataFrame([
            {
                "Source_Rows": validation["Source_Rows"],
                "Valid_Pairs": validation["Valid_Pairs"],
                "Invalid_Actual": validation["Invalid_Actual"],
                "Invalid_Predicted": validation["Invalid_Predicted"],
                "Invalid_Timestamps": validation["Invalid_Timestamps"],
            }
        ]),
        use_container_width=True,
        hide_index=True,
    )

    if prepared.empty:
        st.error(
            "No valid actual/predicted pairs are available."
        )
        return

    metrics = calculate_demand_acceptance_gate_metrics(
        prepared
    )

    gate_result = evaluate_demand_acceptance_gate(
        metrics,
        maximum_wape,
        maximum_absolute_bias_percent,
        int(minimum_observations),
    )

    criteria_report = gate_result.get(
        "Criteria",
        pd.DataFrame(),
    )

    report = build_demand_acceptance_gate_report(
        model_name or "Uploaded_Forecast_Model",
        metrics,
        gate_result,
    )

    recommendations = (
        generate_demand_acceptance_gate_recommendations(
            report,
            criteria_report,
        )
    )

    st.divider()

    render_demand_acceptance_gate_overview(
        report
    )

    st.divider()

    render_demand_acceptance_gate_criteria(
        criteria_report
    )

    st.divider()

    render_demand_acceptance_gate_recommendations(
        recommendations
    )

    st.download_button(
        label="Download Acceptance Report",
        data=report.to_csv(
            index=False
        ).encode("utf-8"),
        file_name="ferry_demand_acceptance_report.csv",
        mime="text/csv",
        key="demand_acceptance_gate_export_report",
    )

    if not criteria_report.empty:
        st.download_button(
            label="Download Acceptance Criteria Results",
            data=criteria_report.to_csv(
                index=False
            ).encode("utf-8"),
            file_name="ferry_demand_acceptance_criteria.csv",
            mime="text/csv",
            key="demand_acceptance_gate_export_criteria",
        )

    st.caption(
        "Forecast Performance Acceptance Gate "
        f"v{DEMAND_ACCEPTANCE_GATE_VERSION}"
    )


