DEMAND_EXTREME_ERROR_VERSION = "1.0.0"


# ------------------------------------------------------------
# 67.1 â€” PREPARE ERROR INVESTIGATION DATA
# ------------------------------------------------------------

def prepare_demand_extreme_error_data(
    dataframe,
    actual_column,
    predicted_column,
    timestamp_column=None,
):
    """Prepare actual-versus-predicted data for error investigation."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame(), {
            "Source_Rows": 0,
            "Valid_Pairs": 0,
            "Invalid_Actual": 0,
            "Invalid_Predicted": 0,
            "Invalid_Timestamps": 0,
        }

    required_columns = [
        actual_column,
        predicted_column,
    ]

    if timestamp_column:
        required_columns.append(
            timestamp_column
        )

    missing_columns = [
        column
        for column in required_columns
        if column not in dataframe.columns
    ]

    if missing_columns:
        raise ValueError(
            "Missing required columns: "
            + ", ".join(missing_columns)
        )

    source_rows = len(dataframe)

    actual = pd.to_numeric(
        dataframe[actual_column],
        errors="coerce",
    ).replace(
        [np.inf, -np.inf],
        np.nan,
    )

    predicted = pd.to_numeric(
        dataframe[predicted_column],
        errors="coerce",
    ).replace(
        [np.inf, -np.inf],
        np.nan,
    )

    result = pd.DataFrame(
        {
            "Actual": actual,
            "Predicted": predicted,
        },
        index=dataframe.index,
    )

    if timestamp_column:
        result["Timestamp"] = pd.to_datetime(
            dataframe[timestamp_column],
            errors="coerce",
        )

        invalid_timestamps = int(
            result["Timestamp"].isna().sum()
        )
    else:
        result["Timestamp"] = pd.NaT
        invalid_timestamps = 0

    invalid_actual = int(
        result["Actual"].isna().sum()
    )

    invalid_predicted = int(
        result["Predicted"].isna().sum()
    )

    result = result.dropna(
        subset=[
            "Actual",
            "Predicted",
        ]
    ).copy()

    if result.empty:
        return result, {
            "Source_Rows": int(source_rows),
            "Valid_Pairs": 0,
            "Invalid_Actual": invalid_actual,
            "Invalid_Predicted": invalid_predicted,
            "Invalid_Timestamps": invalid_timestamps,
        }

    result["Error"] = (
        result["Predicted"]
        - result["Actual"]
    )

    result["Absolute_Error"] = (
        result["Error"].abs()
    )

    result["Squared_Error"] = (
        result["Error"] ** 2
    )

    result["Error_Direction"] = np.select(
        [
            result["Error"] > 0,
            result["Error"] < 0,
        ],
        [
            "Overprediction",
            "Underprediction",
        ],
        default="Exact Prediction",
    )

    result["Absolute_Percent_Error"] = np.where(
        result["Actual"].abs() > 0,
        (
            result["Absolute_Error"]
            / result["Actual"].abs()
        ) * 100,
        np.nan,
    )

    validation = {
        "Source_Rows": int(source_rows),
        "Valid_Pairs": int(len(result)),
        "Invalid_Actual": invalid_actual,
        "Invalid_Predicted": invalid_predicted,
        "Invalid_Timestamps": invalid_timestamps,
    }

    return result.reset_index(
        drop=True
    ), validation


# ------------------------------------------------------------
# 67.2 â€” CALCULATE ERROR DISTRIBUTION
# ------------------------------------------------------------

def calculate_demand_error_distribution(
    dataframe,
    bin_count=20,
):
    """Calculate descriptive statistics and histogram frequencies."""

    if dataframe is None or dataframe.empty:
        return {}, pd.DataFrame()

    errors = pd.to_numeric(
        dataframe["Error"],
        errors="coerce",
    ).replace(
        [np.inf, -np.inf],
        np.nan,
    ).dropna()

    if errors.empty:
        return {}, pd.DataFrame()

    absolute_errors = errors.abs()

    q1 = float(
        errors.quantile(0.25)
    )

    q3 = float(
        errors.quantile(0.75)
    )

    iqr = q3 - q1

    lower_fence = q1 - 1.5 * iqr
    upper_fence = q3 + 1.5 * iqr

    statistics = {
        "Observation_Count": int(
            errors.count()
        ),
        "Mean_Error": float(
            errors.mean()
        ),
        "Median_Error": float(
            errors.median()
        ),
        "Error_Std": float(
            errors.std(ddof=0)
        ),
        "Minimum_Error": float(
            errors.min()
        ),
        "Maximum_Error": float(
            errors.max()
        ),
        "Q1_Error": q1,
        "Q3_Error": q3,
        "IQR_Error": float(iqr),
        "Lower_IQR_Fence": float(
            lower_fence
        ),
        "Upper_IQR_Fence": float(
            upper_fence
        ),
        "P90_Absolute_Error": float(
            absolute_errors.quantile(0.90)
        ),
        "P95_Absolute_Error": float(
            absolute_errors.quantile(0.95)
        ),
        "P99_Absolute_Error": float(
            absolute_errors.quantile(0.99)
        ),
        "Maximum_Absolute_Error": float(
            absolute_errors.max()
        ),
        "IQR_Outlier_Count": int(
            (
                (errors < lower_fence)
                | (errors > upper_fence)
            ).sum()
        ),
    }

    safe_bin_count = max(
        5,
        min(
            int(bin_count),
            100,
        ),
    )

    if errors.nunique() <= 1:
        histogram = pd.DataFrame({
            "Bin_Start": [
                float(errors.min())
            ],
            "Bin_End": [
                float(errors.max())
            ],
            "Frequency": [
                int(errors.count())
            ],
        })
    else:
        frequencies, edges = np.histogram(
            errors.to_numpy(),
            bins=safe_bin_count,
        )

        histogram = pd.DataFrame({
            "Bin_Start": edges[:-1],
            "Bin_End": edges[1:],
            "Frequency": frequencies,
        })

    return statistics, histogram


# ------------------------------------------------------------
# 67.3 â€” IDENTIFY EXTREME ERRORS
# ------------------------------------------------------------

def identify_demand_extreme_error_records(
    dataframe,
    percentile_threshold=95.0,
):
    """Identify records in the upper tail of absolute errors."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame(), np.nan

    safe_percentile = max(
        50.0,
        min(
            float(percentile_threshold),
            100.0,
        ),
    )

    valid_errors = dataframe[
        "Absolute_Error"
    ].replace(
        [np.inf, -np.inf],
        np.nan,
    ).dropna()

    if valid_errors.empty:
        return pd.DataFrame(), np.nan

    threshold = float(
        valid_errors.quantile(
            safe_percentile / 100.0
        )
    )

    result = dataframe.loc[
        dataframe["Absolute_Error"] >= threshold
    ].copy()

    result["Extreme_Error_Threshold"] = threshold

    result["Investigation_Priority"] = np.select(
        [
            result["Absolute_Error"] >= (
                valid_errors.quantile(0.99)
            ),
            result["Absolute_Error"] >= (
                valid_errors.quantile(0.95)
            ),
        ],
        [
            "P1 - Extreme",
            "P2 - High",
        ],
        default="P3 - Review",
    )

    result = result.sort_values(
        "Absolute_Error",
        ascending=False,
    ).reset_index(
        drop=True
    )

    return result, threshold


# ------------------------------------------------------------
# 67.4 â€” BUILD ERROR DIRECTION SUMMARY
# ------------------------------------------------------------

def calculate_demand_error_direction_summary(
    dataframe,
):
    """Summarize overprediction and underprediction frequency."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame()

    result = dataframe.groupby(
        "Error_Direction",
        dropna=False,
    ).agg(
        Observation_Count=("Error", "size"),
        Mean_Error=("Error", "mean"),
        Mean_Absolute_Error=("Absolute_Error", "mean"),
        Maximum_Absolute_Error=("Absolute_Error", "max"),
    ).reset_index()

    total = result[
        "Observation_Count"
    ].sum()

    result["Share_Percent"] = (
        result["Observation_Count"]
        / total
        * 100
        if total > 0
        else np.nan
    )

    return result.sort_values(
        "Observation_Count",
        ascending=False,
    ).reset_index(
        drop=True
    )


# ------------------------------------------------------------
# 67.5 â€” BUILD EXTREME ERROR INVESTIGATION QUEUE
# ------------------------------------------------------------

def build_demand_extreme_error_queue(
    extreme_records,
):
    """Create a compact investigation queue."""

    if extreme_records is None or extreme_records.empty:
        return pd.DataFrame()

    desired_columns = [
        "Timestamp",
        "Actual",
        "Predicted",
        "Error",
        "Absolute_Error",
        "Absolute_Percent_Error",
        "Error_Direction",
        "Investigation_Priority",
    ]

    available_columns = [
        column
        for column in desired_columns
        if column in extreme_records.columns
    ]

    queue = extreme_records[
        available_columns
    ].copy()

    queue["Suggested_Investigation"] = np.select(
        [
            queue["Error_Direction"].eq(
                "Overprediction"
            ),
            queue["Error_Direction"].eq(
                "Underprediction"
            ),
        ],
        [
            "Review overforecast drivers, event effects and target alignment.",
            "Review unexpected demand increases, missing predictors and target alignment.",
        ],
        default="Review the observation and source data.",
    )

    return queue.sort_values(
        "Absolute_Error",
        ascending=False,
    ).reset_index(
        drop=True
    )


# ------------------------------------------------------------
# 67.6 â€” GENERATE DISTRIBUTION INSIGHTS
# ------------------------------------------------------------

def generate_demand_error_distribution_insights(
    statistics,
    direction_summary,
    extreme_records,
):
    """Create descriptive insights without asserting causation."""

    insights = []

    if not statistics:
        return [
            "No valid errors are available for distribution analysis."
        ]

    insights.append(
        f"Error distribution contains "
        f"{statistics['Observation_Count']:,} valid observations."
    )

    insights.append(
        f"Mean signed error is "
        f"{statistics['Mean_Error']:.3f}; positive values indicate "
        "average overprediction and negative values indicate "
        "average underprediction."
    )

    insights.append(
        f"The 95th-percentile absolute error is "
        f"{statistics['P95_Absolute_Error']:.3f}."
    )

    insights.append(
        f"The IQR rule flags "
        f"{statistics['IQR_Outlier_Count']:,} error observations. "
        "These are statistical outliers, not automatically model failures."
    )

    if (
        extreme_records is not None
        and not extreme_records.empty
    ):
        insights.append(
            f"The selected percentile threshold identifies "
            f"{len(extreme_records):,} observations for review."
        )

    if (
        direction_summary is not None
        and not direction_summary.empty
    ):
        direction_row = direction_summary.iloc[0]

        insights.append(
            f"The most frequent error category is "
            f"'{direction_row['Error_Direction']}' "
            f"({direction_row['Share_Percent']:.1f}% of valid observations)."
        )

    insights.append(
        "Extreme errors may reflect unusual demand, data issues, "
        "forecast timing differences or model limitations. The "
        "distribution alone cannot determine the cause."
    )

    return insights


