# ------------------------------------------------------------
# 67.12 â€” MAIN EXTREME ERROR CENTER
# ------------------------------------------------------------

def render_demand_extreme_error_center():
    """Render the forecast error distribution and investigation center."""

    st.header(
        "Ferry Demand Forecast Error Distribution & Extreme Error Center"
    )

    st.markdown(
        """
        Explore forecast error ranges, signed-error direction,
        upper-tail error percentiles and observations that merit review.
        """
    )

    st.caption(
        "This center analyzes uploaded actual-versus-predicted records. "
        "It does not identify the cause of an error automatically."
    )

    uploaded_file = st.file_uploader(
        "Upload actual-versus-predicted CSV",
        type=["csv"],
        key="demand_extreme_error_upload",
    )

    if uploaded_file is None:
        st.info(
            "Upload a prediction-results CSV to begin."
        )
        return

    try:
        source_data = pd.read_csv(
            uploaded_file
        )
    except Exception as error:
        st.error(
            f"Unable to read the CSV: {error}"
        )
        return

    if source_data.empty:
        st.warning(
            "The uploaded CSV contains no rows."
        )
        return

    columns = source_data.columns.tolist()

    if len(columns) < 2:
        st.error(
            "The file must contain separate actual and predicted columns."
        )
        return

    col1, col2 = st.columns(2)

    actual_column = col1.selectbox(
        "Actual demand column",
        options=columns,
        index=_ferry_column_index(columns, "actual"),
        key="demand_extreme_error_actual_v2",
    )

    predicted_options = [
        column
        for column in columns
        if column != actual_column
    ]

    predicted_column = col2.selectbox(
        "Predicted demand column",
        options=predicted_options,
        index=_ferry_column_index(predicted_options, "predicted"),
        key="demand_extreme_error_predicted_v2",
    )

    timestamp_options = [
        "No timestamp"
    ] + [
        column
        for column in columns
        if column not in [
            actual_column,
            predicted_column,
        ]
    ]

    timestamp_column = st.selectbox(
        "Optional timestamp column",
        options=timestamp_options,
        index=_ferry_column_index(
            timestamp_options, "timestamp", fallback="No timestamp"
        ),
        key="demand_extreme_error_timestamp_v2",
    )

    if timestamp_column == "No timestamp":
        timestamp_column = None

    col1, col2 = st.columns(2)

    percentile_threshold = col1.slider(
        "Extreme-error percentile threshold",
        min_value=80,
        max_value=99,
        value=95,
        step=1,
        key="demand_extreme_error_percentile",
    )

    bin_count = col2.slider(
        "Histogram bin count",
        min_value=5,
        max_value=60,
        value=20,
        step=5,
        key="demand_extreme_error_bins",
    )

    try:
        prepared, validation = (
            prepare_demand_extreme_error_data(
                source_data,
                actual_column,
                predicted_column,
                timestamp_column,
            )
        )
    except Exception as error:
        st.error(
            f"Unable to prepare prediction records: {error}"
        )
        return

    st.subheader(
        "Input Validation"
    )

    st.dataframe(
        pd.DataFrame([
            validation
        ]),
        use_container_width=True,
        hide_index=True,
    )

    if prepared.empty:
        st.error(
            "No valid actual-versus-predicted pairs were found."
        )
        return

    statistics, histogram = (
        calculate_demand_error_distribution(
            prepared,
            bin_count,
        )
    )

    extreme_records, threshold = (
        identify_demand_extreme_error_records(
            prepared,
            percentile_threshold,
        )
    )

    direction_summary = (
        calculate_demand_error_direction_summary(
            prepared
        )
    )

    queue = build_demand_extreme_error_queue(
        extreme_records
    )

    insights = (
        generate_demand_error_distribution_insights(
            statistics,
            direction_summary,
            extreme_records,
        )
    )

    st.divider()

    render_demand_error_distribution_statistics(
        statistics
    )

    st.divider()

    render_demand_error_distribution_histogram(
        histogram
    )

    st.divider()

    render_demand_error_direction_summary(
        direction_summary
    )

    st.divider()

    st.subheader(
        "Extreme Error Threshold"
    )

    st.metric(
        f"{percentile_threshold}th Percentile Absolute Error",
        (
            f"{threshold:.3f}"
            if pd.notna(threshold)
            else "N/A"
        ),
    )

    render_demand_extreme_error_investigation_queue(
        queue
    )

    st.divider()

    render_demand_error_distribution_insights(
        insights
    )

    st.download_button(
        label="Download Error Distribution Histogram",
        data=histogram.to_csv(
            index=False
        ).encode("utf-8"),
        file_name="ferry_demand_error_histogram.csv",
        mime="text/csv",
        key="demand_extreme_error_export_histogram",
    )

    st.download_button(
        label="Download Prepared Error Records",
        data=prepared.to_csv(
            index=False
        ).encode("utf-8"),
        file_name="ferry_demand_prepared_error_records.csv",
        mime="text/csv",
        key="demand_extreme_error_export_prepared",
    )

    st.caption(
        "Forecast Error Distribution & Extreme Error Center "
        f"v{DEMAND_EXTREME_ERROR_VERSION}"
    )


