DEMAND_ALIGNMENT_AUDIT_VERSION = "1.0.0"


# ------------------------------------------------------------
# 68.1 â€” PREPARE A TIMESTAMPED DEMAND SERIES
# ------------------------------------------------------------

def prepare_demand_alignment_series(
    dataframe,
    timestamp_column,
    value_column,
    series_name,
):
    """Validate and prepare one timestamped demand series."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame(), {
            "Source_Rows": 0,
            "Invalid_Timestamps": 0,
            "Invalid_Values": 0,
            "Duplicate_Timestamp_Rows": 0,
        }

    required = [
        timestamp_column,
        value_column,
    ]

    missing = [
        column
        for column in required
        if column not in dataframe.columns
    ]

    if missing:
        raise ValueError(
            "Missing columns: " + ", ".join(missing)
        )

    result = pd.DataFrame()

    result["Timestamp"] = pd.to_datetime(
        dataframe[timestamp_column],
        errors="coerce",
    )

    result["Value"] = pd.to_numeric(
        dataframe[value_column],
        errors="coerce",
    )

    result["Value"] = result["Value"].replace(
        [np.inf, -np.inf],
        np.nan,
    )

    validation = {
        "Source_Rows": int(len(result)),
        "Invalid_Timestamps": int(
            result["Timestamp"].isna().sum()
        ),
        "Invalid_Values": int(
            result["Value"].isna().sum()
        ),
    }

    result = result.dropna(
        subset=["Timestamp", "Value"]
    ).copy()

    validation["Duplicate_Timestamp_Rows"] = int(
        result["Timestamp"].duplicated(
            keep=False
        ).sum()
    )

    result = result.rename(
        columns={
            "Value": str(series_name)
        }
    )

    return result.sort_values(
        "Timestamp"
    ).reset_index(
        drop=True
    ), validation


# ------------------------------------------------------------
# 68.2 â€” AGGREGATE TO A COMMON FREQUENCY
# ------------------------------------------------------------

def aggregate_demand_alignment_series(
    dataframe,
    value_column,
    frequency,
):
    """Aggregate observations into comparable calendar periods."""

    if dataframe is None or dataframe.empty:
        return pd.DataFrame(
            columns=["Timestamp", value_column]
        )

    result = dataframe[
        ["Timestamp", value_column]
    ].copy()

    result = result.dropna(
        subset=["Timestamp", value_column]
    )

    if result.empty:
        return pd.DataFrame(
            columns=["Timestamp", value_column]
        )

    result = result.set_index(
        "Timestamp"
    ).sort_index()

    if frequency == "Daily":
        aggregated = result.resample(
            "D"
        ).sum(min_count=1)

    elif frequency == "Weekly":
        aggregated = result.resample(
            "W-SUN"
        ).sum(min_count=1)

    elif frequency == "Monthly":
        aggregated = result.resample(
            "MS"
        ).sum(min_count=1)

    else:
        raise ValueError(
            "Frequency must be Daily, Weekly or Monthly."
        )

    return aggregated.reset_index()


# ------------------------------------------------------------
# 68.3 â€” ALIGN ACTUAL AND PREDICTED PERIODS
# ------------------------------------------------------------

def build_demand_alignment_audit(
    actual_series,
    predicted_series,
    actual_column,
    predicted_column,
):
    """Outer-join both series to expose unmatched periods."""

    if actual_series is None:
        actual_series = pd.DataFrame(
            columns=["Timestamp", actual_column]
        )

    if predicted_series is None:
        predicted_series = pd.DataFrame(
            columns=["Timestamp", predicted_column]
        )

    actual = actual_series.rename(
        columns={
            actual_column: "Actual"
        }
    )

    predicted = predicted_series.rename(
        columns={
            predicted_column: "Predicted"
        }
    )

    result = actual.merge(
        predicted,
        on="Timestamp",
        how="outer",
        indicator=True,
        validate="one_to_one",
    )

    result = result.sort_values(
        "Timestamp"
    ).reset_index(
        drop=True
    )

    result["Alignment_Status"] = np.select(
        [
            result["_merge"].eq("both"),
            result["_merge"].eq("left_only"),
            result["_merge"].eq("right_only"),
        ],
        [
            "Matched",
            "Actual Only",
            "Predicted Only",
        ],
        default="Unknown",
    )

    result["Absolute_Error"] = np.nan
    result["Signed_Error"] = np.nan

    matched = result[
        "Alignment_Status"
    ].eq("Matched")

    result.loc[
        matched,
        "Signed_Error",
    ] = (
        result.loc[matched, "Predicted"]
        - result.loc[matched, "Actual"]
    )

    result.loc[
        matched,
        "Absolute_Error",
    ] = result.loc[
        matched,
        "Signed_Error",
    ].abs()

    return result.drop(
        columns=["_merge"]
    )


# ------------------------------------------------------------
# 68.4 â€” SUMMARIZE ALIGNMENT QUALITY
# ------------------------------------------------------------

def calculate_demand_alignment_audit_summary(
    audit,
):
    """Summarize matched and unmatched periods."""

    if audit is None or audit.empty:
        return {
            "Actual_Periods": 0,
            "Predicted_Periods": 0,
            "Matched_Periods": 0,
            "Actual_Only_Periods": 0,
            "Predicted_Only_Periods": 0,
            "Alignment_Percent": np.nan,
            "MAE_On_Matched_Periods": np.nan,
            "RMSE_On_Matched_Periods": np.nan,
            "WAPE_On_Matched_Periods": np.nan,
        }

    matched = audit.loc[
        audit["Alignment_Status"].eq("Matched")
    ].copy()

    actual_periods = int(
        audit["Actual"].notna().sum()
    )

    predicted_periods = int(
        audit["Predicted"].notna().sum()
    )

    matched_periods = int(
        len(matched)
    )

    union_periods = int(
        len(audit)
    )

    absolute_actual_total = (
        float(matched["Actual"].abs().sum())
        if matched_periods > 0
        else 0.0
    )

    if matched_periods > 0:
        mae = float(
            matched["Absolute_Error"].mean()
        )

        rmse = float(
            np.sqrt(
                np.mean(
                    matched["Signed_Error"] ** 2
                )
            )
        )

        wape = (
            float(
                matched["Absolute_Error"].sum()
                / absolute_actual_total
                * 100
            )
            if absolute_actual_total > 0
            else np.nan
        )
    else:
        mae = np.nan
        rmse = np.nan
        wape = np.nan

    return {
        "Actual_Periods": actual_periods,
        "Predicted_Periods": predicted_periods,
        "Matched_Periods": matched_periods,
        "Actual_Only_Periods": int(
            audit["Alignment_Status"].eq(
                "Actual Only"
            ).sum()
        ),
        "Predicted_Only_Periods": int(
            audit["Alignment_Status"].eq(
                "Predicted Only"
            ).sum()
        ),
        "Alignment_Percent": (
            matched_periods / union_periods * 100
            if union_periods > 0
            else np.nan
        ),
        "MAE_On_Matched_Periods": mae,
        "RMSE_On_Matched_Periods": rmse,
        "WAPE_On_Matched_Periods": wape,
    }


