def render_demand_alignment_audit_mismatches(
    audit,
):
    """Display periods that appear in only one series."""

    st.subheader(
        "Unmatched Period Investigation"
    )

    if audit is None or audit.empty:
        st.info(
            "No alignment records are available."
        )
        return

    mismatches = audit.loc[
        audit["Alignment_Status"].ne("Matched")
    ].copy()

    if mismatches.empty:
        st.success(
            "All observed periods are matched."
        )
        return

    st.warning(
        f"{len(mismatches):,} periods occur in only one of the two series."
    )

    st.dataframe(
        mismatches,
        use_container_width=True,
        hide_index=True,
    )

    st.download_button(
        label="Download Unmatched Periods",
        data=mismatches.to_csv(
            index=False
        ).encode("utf-8"),
        file_name="ferry_demand_unmatched_periods.csv",
        mime="text/csv",
        key="demand_alignment_audit_export_mismatches",
    )


