def render_demand_alignment_audit_center():
    """Render two-file demand alignment and error audit."""

    st.header(
        "Ferry Demand Forecast Data Alignment Audit Center"
    )

    st.markdown(
        """
        Compare separate actual-demand and predicted-demand CSV files.
        The audit aligns daily, weekly or monthly totals and exposes
        periods missing from either series.
        """
    )

    st.caption(
        "The module does not interpolate, fabricate or automatically "
        "fill missing periods."
    )

    frequency = st.selectbox(
        "Common comparison frequency",
        options=[
            "Daily",
            "Weekly",
            "Monthly",
        ],
        key="demand_alignment_audit_frequency",
    )

    actual_file = st.file_uploader(
        "Upload actual demand CSV",
        type=["csv"],
        key="demand_alignment_audit_actual_file",
    )

    predicted_file = st.file_uploader(
        "Upload predicted demand CSV",
        type=["csv"],
        key="demand_alignment_audit_predicted_file",
    )

    if actual_file is None or predicted_file is None:
        st.info(
            "Upload both CSV files to perform alignment auditing."
        )
        return

    try:
        actual_source = pd.read_csv(
            actual_file
        )

        predicted_source = pd.read_csv(
            predicted_file
        )
    except Exception as error:
        st.error(
            f"Unable to read one of the CSV files: {error}"
        )
        return

    if actual_source.empty or predicted_source.empty:
        st.warning(
            "Both uploaded files must contain data rows."
        )
        return

    actual_columns = actual_source.columns.tolist()
    predicted_columns = predicted_source.columns.tolist()

    col1, col2 = st.columns(2)

    actual_timestamp_column = col1.selectbox(
        "Actual timestamp column",
        options=actual_columns,
        index=_ferry_column_index(actual_columns, "timestamp"),
        key="demand_alignment_actual_timestamp_v2",
    )

    actual_value_column = col1.selectbox(
        "Actual demand value column",
        options=[
            column
            for column in actual_columns
            if column != actual_timestamp_column
        ],
        index=_ferry_column_index(
            [column for column in actual_columns if column != actual_timestamp_column],
            "value",
            fallback=_ferry_suggest_column(
                [column for column in actual_columns if column != actual_timestamp_column],
                "actual",
            ),
        ),
        key="demand_alignment_actual_value_v2",
    )

    predicted_timestamp_column = col2.selectbox(
        "Predicted timestamp column",
        options=predicted_columns,
        index=_ferry_column_index(predicted_columns, "timestamp"),
        key="demand_alignment_predicted_timestamp_v2",
    )

    predicted_value_column = col2.selectbox(
        "Predicted demand value column",
        options=[
            column
            for column in predicted_columns
            if column != predicted_timestamp_column
        ],
        index=_ferry_column_index(
            [column for column in predicted_columns if column != predicted_timestamp_column],
            "predicted",
            fallback=_ferry_suggest_column(
                [column for column in predicted_columns if column != predicted_timestamp_column],
                "value",
            ),
        ),
        key="demand_alignment_predicted_value_v2",
    )

    try:
        actual_series, actual_validation = (
            prepare_demand_alignment_series(
                actual_source,
                actual_timestamp_column,
                actual_value_column,
                "Actual",
            )
        )

        predicted_series, predicted_validation = (
            prepare_demand_alignment_series(
                predicted_source,
                predicted_timestamp_column,
                predicted_value_column,
                "Predicted",
            )
        )

        actual_aggregated = (
            aggregate_demand_alignment_series(
                actual_series,
                "Actual",
                frequency,
            )
        )

        predicted_aggregated = (
            aggregate_demand_alignment_series(
                predicted_series,
                "Predicted",
                frequency,
            )
        )

        audit = build_demand_alignment_audit(
            actual_aggregated,
            predicted_aggregated,
            "Actual",
            "Predicted",
        )

    except Exception as error:
        st.error(
            f"Unable to align the uploaded series: {error}"
        )
        return

    if audit.empty:
        st.warning(
            "No valid timestamped periods are available for comparison."
        )
        return

    summary = calculate_demand_alignment_audit_summary(
        audit
    )

    st.divider()

    st.subheader(
        "Source Validation"
    )

    st.dataframe(
        pd.DataFrame([
            {
                "Series": "Actual",
                **actual_validation,
            },
            {
                "Series": "Predicted",
                **predicted_validation,
            },
        ]),
        use_container_width=True,
        hide_index=True,
    )

    st.warning(
        "Duplicate source timestamps are aggregated by summation. "
        "Confirm that duplicate rows represent additive observations "
        "rather than repeated copies before interpreting totals."
    )

    st.divider()

    render_demand_alignment_audit_summary(
        summary
    )

    st.divider()

    render_demand_alignment_audit_mismatches(
        audit
    )

    st.divider()

    render_demand_alignment_audit_errors(
        audit
    )

    st.download_button(
        label="Download Full Alignment Audit",
        data=audit.to_csv(
            index=False
        ).encode("utf-8"),
        file_name="ferry_demand_alignment_audit.csv",
        mime="text/csv",
        key="demand_alignment_audit_export_full",
    )

    st.caption(
        "Demand Data Alignment Audit "
        f"v{DEMAND_ALIGNMENT_AUDIT_VERSION}"
    )


