def render_ferry_integration_placeholder(
    page_name,
    error_message=None,
):
    """Show an honest message when a renderer is unavailable."""

    st.subheader(page_name)

    st.info(
        "This page is listed in the navigation registry, "
        "but its renderer has not yet been connected or verified."
    )

    if error_message:
        with st.expander(
            "Technical details"
        ):
            st.code(
                str(error_message)
            )


def dispatch_ferry_page(
    page_name,
    page_renderers,
):
    """
    Call a registered renderer if available.

    The registry must contain only functions that have been
    reviewed and explicitly connected during final integration.
    """

    renderer = page_renderers.get(
        page_name
    )

    if renderer is None:
        render_ferry_integration_placeholder(
            page_name
        )
        return

    if not callable(renderer):
        render_ferry_integration_placeholder(
            page_name,
            "Registered renderer is not callable.",
        )
        return

    try:
        renderer()

    except Exception as error:
        logging.exception(
            "Page renderer failed: %s",
            page_name,
        )

        st.error(
            f"The '{page_name}' page encountered an error."
        )

        st.caption(
            "The error has been logged. Review the traceback "
            "during final debugging."
        )

        with st.expander(
            "Technical error details"
        ):
            st.code(
                traceback.format_exc()
            )


