# ------------------------------------------------------------
# 69.5 â€” INTEGRATION HEALTH SUMMARY
# ------------------------------------------------------------

def calculate_ferry_integration_summary(
    page_renderers,
):
    """Summarize navigation coverage without executing pages."""

    registered_pages = set(
        page_renderers.keys()
    )

    all_pages = [
        page
        for pages in FERRY_NAVIGATION_GROUPS.values()
        for page in pages
    ]

    available_pages = [
        page
        for page in all_pages
        if page in registered_pages
        and callable(page_renderers.get(page))
    ]

    unavailable_pages = [
        page
        for page in all_pages
        if page not in available_pages
    ]

    return {
        "Navigation_Pages": len(all_pages),
        "Connected_Pages": len(available_pages),
        "Unconnected_Pages": len(unavailable_pages),
        "Connection_Percent": (
            len(available_pages) / len(all_pages) * 100
            if all_pages
            else 0.0
        ),
        "Available_Pages": available_pages,
        "Unavailable_Pages": unavailable_pages,
    }


