# ------------------------------------------------------------
# 70.2 â€” RESOLVE ACTUAL RENDERER FUNCTIONS
# ------------------------------------------------------------

def resolve_ferry_page_renderers():
    """
    Find renderer functions that actually exist in this module.

    This function does not execute arbitrary functions.
    It only selects explicitly listed renderer candidates.
    """

    resolved = {}

    for page_name, candidates in (
        FERRY_RENDERER_CANDIDATES.items()
    ):
        for function_name in candidates:
            candidate = globals().get(
                function_name
            )

            if callable(candidate):
                resolved[page_name] = candidate
                break

    return resolved


# ------------------------------------------------------------
# 70.3 â€” SAFE RENDERER ARGUMENT HANDLING
# ------------------------------------------------------------

def execute_ferry_page_renderer(
    page_name,
    renderer,
    dataset=None,
    dataset_source=None,
):
    """
    Execute page renderers with supported dataset and path arguments.
    """

    if not callable(renderer):
        st.error(f"The renderer for '{page_name}' is not callable.")
        return

    try:
        signature = inspect.signature(renderer)
        parameters = signature.parameters

        dataset_names = {
            "df", "data", "dataframe", "dataset",
            "ticket_data", "historical_data", "demand_data",
        }

        path_names = {
            "dataset_path", "data_path", "file_path",
            "csv_path", "source_path",
        }

        kwargs = {}
        unsupported = []

        for parameter in parameters.values():
            if parameter.kind in (
                inspect.Parameter.VAR_POSITIONAL,
                inspect.Parameter.VAR_KEYWORD,
                inspect.Parameter.POSITIONAL_ONLY,
            ):
                continue

            name = parameter.name.lower()

            if name in dataset_names:
                if dataset is not None:
                    kwargs[parameter.name] = dataset
                elif parameter.default is inspect.Parameter.empty:
                    unsupported.append(parameter.name)

            elif name in path_names:
                source_path = Path(str(dataset_source)) if dataset_source else None

                if source_path is not None and source_path.is_file():
                    kwargs[parameter.name] = str(source_path)
                elif parameter.default is inspect.Parameter.empty:
                    unsupported.append(parameter.name)

            elif parameter.default is inspect.Parameter.empty:
                unsupported.append(parameter.name)

        if unsupported:
            st.warning(
                f"'{page_name}' could not run. Missing required arguments: "
                + ", ".join(unsupported)
            )
            st.caption("Renderer signature: " + str(signature))
            return

        renderer(**kwargs)

    except Exception as error:
        logging.exception("Ferry renderer failed: %s", page_name)
        st.error(f"Error while loading {page_name}: {error}")
        with st.expander("Technical error details"):
            st.exception(error)


def load_ferry_application_dataset():
    """
    Load the configured dataset through the existing loader.

    If the default file cannot be loaded, offer a CSV upload.
    """

    dataset = None
    dataset_source = None

    default_path = globals().get(
        "DEFAULT_DATASET_PATH"
    )

    loader = globals().get(
        "load_ticket_dataset"
    )

    if default_path is not None and callable(loader):
        try:
            if Path(default_path).exists():
                dataset, load_error = loader(
                    str(default_path)
                )

                dataset_source = str(
                    default_path
                )

        except Exception:
            logging.exception(
                "Could not load the configured ferry dataset."
            )

    if dataset is not None:
        return dataset, dataset_source

    st.sidebar.warning(
        "The default dataset could not be loaded."
    )

    uploaded_file = st.sidebar.file_uploader(
        "Upload ferry ticket CSV",
        type=["csv"],
        key="ferry_application_dataset_upload",
    )

    if uploaded_file is None:
        return None, None

    try:
        dataset = pd.read_csv(
            uploaded_file
        )

        required_columns = {
            "Timestamp",
            "Sales Count",
            "Redemption Count",
        }

        missing_columns = (
            required_columns
            - set(dataset.columns)
        )

        if missing_columns:
            st.error(
                "Uploaded dataset is missing required columns: "
                + ", ".join(
                    sorted(missing_columns)
                )
            )

            return None, None

        dataset["Timestamp"] = pd.to_datetime(
            dataset["Timestamp"],
            errors="coerce",
        )

        for column in (
            "Sales Count",
            "Redemption Count",
        ):
            dataset[column] = pd.to_numeric(
                dataset[column],
                errors="coerce",
            )

        dataset = (
            dataset
            .dropna(
                subset=["Timestamp"]
            )
            .sort_values("Timestamp")
            .reset_index(drop=True)
        )

        if dataset.empty:
            st.error(
                "No valid timestamp records were found."
            )
            return None, None

        return dataset, uploaded_file.name

    except Exception:
        logging.exception(
            "Uploaded ferry dataset could not be processed."
        )

        st.error(
            "The uploaded dataset could not be processed."
        )

        with st.expander(
            "Technical details"
        ):
            st.code(
                traceback.format_exc()
            )

        return None, None


# ------------------------------------------------------------
# 70.5 â€” RENDER THE DATASET OVERVIEW
# ------------------------------------------------------------

def render_ferry_integrated_dataset_overview(
    dataset,
    dataset_source=None,
):
    """Render a reliable base overview using available columns."""

    st.subheader(
        "Ferry Ticket Dataset Overview"
    )

    if dataset is None:
        st.warning(
            "No valid base dataset is currently available."
        )
        return

    col1, col2, col3, col4 = st.columns(4)

    col1.metric(
        "Records",
        f"{len(dataset):,}",
    )

    col2.metric(
        "Columns",
        f"{len(dataset.columns):,}",
    )

    col3.metric(
        "Missing Values",
        f"{int(dataset.isna().sum().sum()):,}",
    )

    col4.metric(
        "Duplicate Rows",
        f"{int(dataset.duplicated().sum()):,}",
    )

    if dataset_source:
        st.caption(
            f"Dataset source: {dataset_source}"
        )

    if "Timestamp" in dataset.columns:
        timestamps = pd.to_datetime(
            dataset["Timestamp"],
            errors="coerce",
        ).dropna()

        if not timestamps.empty:
            date_col1, date_col2 = st.columns(2)

            date_col1.metric(
                "Coverage Start",
                timestamps.min().strftime(
                    "%d %b %Y"
                ),
            )

            date_col2.metric(
                "Coverage End",
                timestamps.max().strftime(
                    "%d %b %Y"
                ),
            )

    if all(
        column in dataset.columns
        for column in (
            "Sales Count",
            "Redemption Count",
        )
    ):
        st.markdown(
            "#### Recorded Ticket Counts"
        )

        sales = pd.to_numeric(
            dataset["Sales Count"],
            errors="coerce",
        )

        redemptions = pd.to_numeric(
            dataset["Redemption Count"],
            errors="coerce",
        )

        metric_col1, metric_col2 = st.columns(2)

        metric_col1.metric(
            "Recorded Sales Count",
            f"{sales.sum(min_count=1):,.0f}"
            if sales.notna().any()
            else "Unavailable",
        )

        metric_col2.metric(
            "Recorded Redemption Count",
            f"{redemptions.sum(min_count=1):,.0f}"
            if redemptions.notna().any()
            else "Unavailable",
        )

        st.caption(
            "Sales and redemption counts describe the recorded "
            "ticket dataset. They should not automatically be "
            "interpreted as actual passenger boardings, vessel "
            "occupancy or unused tickets."
        )

    with st.expander(
        "Dataset preview"
    ):
        st.dataframe(
            dataset.head(100),
            use_container_width=True,
            hide_index=True,
        )

    with st.expander(
        "Column information"
    ):
        column_summary = pd.DataFrame({
            "Column": dataset.columns,
            "Data Type": [
                str(dtype)
                for dtype in dataset.dtypes
            ],
            "Missing Values": [
                int(value)
                for value in dataset.isna().sum()
            ],
            "Unique Values": [
                int(dataset[column].nunique(
                    dropna=True
                ))
                for column in dataset.columns
            ],
        })

        st.dataframe(
            column_summary,
            use_container_width=True,
            hide_index=True,
        )


