def main():
    """
    Final entry point for the Ferry Demand Intelligence app.

    IMPORTANT:
    This replaces the original main() from Part 1.
    """

    st.title(
        "Ferry Demand Intelligence"
    )

    st.caption(
        "Historical ticket analysis, forecasting evaluation, "
        "demand intelligence and decision support."
    )

    st.divider()

    dataset, dataset_source = (
        load_ferry_application_dataset()
    )

    page_renderers = (
        resolve_ferry_page_renderers()
    )

    st.sidebar.title(
        "Ferry Demand Intelligence"
    )

    st.sidebar.caption(
        f"Version {FERRY_APP_INTEGRATION_VERSION}"
    )

    # ------------------------------------------------------------
    # GROUPED SIDEBAR NAVIGATION
    # Each workspace is shown as its own expandable section.
    # ------------------------------------------------------------
    navigation_groups = dict(FERRY_NAVIGATION_GROUPS)
    navigation_groups["Overview"] = [
        "Dataset Overview",
        "Integration Status",
        "Historical Demand Analysis",
    ]

    all_navigation_pages = [
        page
        for pages in navigation_groups.values()
        for page in pages
    ]

    # Keep the user's last selected module when Streamlit reruns.
    active_page = st.session_state.get(
        "ferry_active_page",
        st.session_state.get(
            "ferry_main_page_selection",
            "Dataset Overview",
        ),
    )
    if active_page not in all_navigation_pages:
        active_page = "Dataset Overview"
    st.session_state["ferry_active_page"] = active_page

    group_icons = {
        "Overview": "📊",
        "Forecasting": "📈",
        "Demand Intelligence": "🌊",
        "Planning and Monitoring": "🧭",
        "Model Evaluation": "🧪",
        "Advanced Analytics": "🔬",
        "Reports": "📁",
    }

    st.sidebar.markdown(
        """
        <style>
        [data-testid="stSidebar"] .ferry-active-module {
            border-left: 4px solid #16a34a;
            background: rgba(22, 163, 74, 0.12);
            border-radius: 8px;
            padding: 10px 12px;
            margin: 5px 0 13px 0;
        }
        [data-testid="stSidebar"] .ferry-active-label {
            color: #16a34a;
            font-size: 0.68rem;
            font-weight: 800;
            letter-spacing: 0.09em;
            margin-bottom: 4px;
        }
        [data-testid="stSidebar"] .ferry-active-name {
            color: var(--text-color);
            font-size: 0.95rem;
            font-weight: 750;
            line-height: 1.35;
            overflow-wrap: anywhere;
        }
        [data-testid="stSidebar"] [data-testid="stExpander"] {
            border: 1px solid rgba(128, 128, 128, 0.20);
            border-radius: 9px;
            margin-bottom: 7px;
        }
        [data-testid="stSidebar"] [data-testid="stButton"] button {
            text-align: left;
            border-radius: 7px;
            min-height: 2.45rem;
            font-size: 0.88rem;
        }
        </style>
        """,
        unsafe_allow_html=True,
    )

    st.sidebar.markdown(
        "**WORKSPACES**  \n        <div style='font-size:0.78rem;opacity:0.72;margin-top:2px;'>Choose a category, then open its module.</div>",
        unsafe_allow_html=True,
    )

    st.sidebar.markdown(
        f"""
        <div class="ferry-active-module">
            <div class="ferry-active-label">CURRENTLY VIEWING</div>
            <div class="ferry-active-name">{active_page}</div>
        </div>
        """,
        unsafe_allow_html=True,
    )

    selected_page = active_page
    for group_index, (group_name, group_pages) in enumerate(
        navigation_groups.items()
    ):
        icon = group_icons.get(group_name, "📂")
        with st.sidebar.expander(
            f"{icon}  {group_name}  ·  {len(group_pages)}",
            expanded=(active_page in group_pages),
        ):
            for page_index, page_name in enumerate(group_pages):
                button_label = (
                    f"●  {page_name}"
                    if page_name == active_page
                    else page_name
                )
                if st.button(
                    button_label,
                    key=f"ferry_nav_{group_index}_{page_index}",
                    type=("primary" if page_name == active_page else "secondary"),
                    use_container_width=True,
                ):
                    st.session_state["ferry_active_page"] = page_name
                    st.rerun()

    st.sidebar.divider()
    st.sidebar.caption(
        f"{len(page_renderers)} modules connected · "
        f"{len(navigation_groups)} workspaces"
    )

    if selected_page == "Dataset Overview":
        render_ferry_integrated_dataset_overview(
            dataset,
            dataset_source,
        )

    elif selected_page == "Integration Status":
        render_ferry_integration_status(
            page_renderers
        )

    else:
        st.header(
            selected_page
        )

        st.caption(
            FERRY_PAGE_DESCRIPTIONS.get(
                selected_page,
                "Explore this module.",
            )
        )

        renderer = page_renderers.get(
            selected_page
        )

        if renderer is None:
            render_ferry_integration_placeholder(
                selected_page,
                "No matching renderer function was found.",
            )
        else:
            execute_ferry_page_renderer(
                selected_page,
                renderer,
                dataset,
                dataset_source,
            )


